const APP_BUILD = '2026-10-28-milli-sohbet-836';

// 🆕 Surumu Ayarlar > Uygulama altinda goster (hangi dosyanin yuklu
//    oldugunu telefondan dogrulayabilmek icin).
(function _surumYaz(){
  function yaz(){
    try {
      var e = document.getElementById('setBuild');
      if (e) e.textContent = APP_BUILD;

      // 🆕 Ortam tanisi — Play Billing'in neden calismadigini
      //    telefondan gorebilmek icin.
      var o = document.getElementById('setOrtam');
      if (o) {
        var plat = '?';
        try { plat = (window.Capacitor && window.Capacitor.getPlatform)
                     ? window.Capacitor.getPlatform() : 'web'; } catch(x) {}
        var fiyatSayisi = 0;
        try { fiyatSayisi = Object.keys(window._playFiyat || {}).length; } catch (x) {}
        var parcalar = [
          plat,
          'Cap:'  + (window.Capacitor ? '✓' : '✗'),
          'Cdv:'  + (window.cordova ? '✓' : '✗'),
          'PB:' + (_pb() ? '✓' : '✗'),
          // 🔔 541 — bildirim eklentisi yüklü mü + izin durumu
          'LN:' + ((window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.LocalNotifications) ? '✓' : '✗')
            + (window._bldIzinSon ? '(' + window._bldIzinSon + ')' : ''),
          'Fiyat:' + fiyatSayisi + '/9'
        ];
        if (typeof window._playUrunler === 'number') parcalar.push('Urun:' + window._playUrunler);
        if (window._playSonHata) parcalar.push('Hata:' + String(window._playSonHata).slice(0, 60));
        o.textContent = parcalar.join(' · ');
      }
    } catch(err) {}
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', yaz);
  else yaz();
  setTimeout(yaz, 1200);
  // Ayarlar acikken Play durumu degisirse gorelim
  setInterval(function () {
    var el = document.getElementById('setOrtam');
    if (el && el.offsetParent !== null) yaz();
  }, 2000);
})();

