// 🆕 ═══════════════════════════════════════════════════════════════════════
// CONSOLE POLYFILL — bazı WebView/embedded browser ortamlarında console.info,
// console.warn, console.error gibi yöntemler eksik olabilir. Olmayan method'lar
// için no-op fonksiyon ata, böylece "console.info is not a function" hatası
// alınmaz. Mevcut method'lara dokunulmaz.
// ═══════════════════════════════════════════════════════════════════════
(function _cftConsolePolyfill(){
  if (typeof console === 'undefined') { window.console = {}; }
  const _noop = function(){};
  const _fallback = (typeof console.log === 'function') ? console.log.bind(console) : _noop;
  ['log','info','warn','error','debug','trace','table','group','groupEnd','time','timeEnd','assert','dir'].forEach(function(m){
    if (typeof console[m] !== 'function') {
      console[m] = _fallback;
    }
  });
})();

// 🆕 Storage log toggle — tüm `[Storage]` info mesajlarını sustur (kullanıcı için gereksiz).
// Debug yapmak istersen console'da: window._cftStorageLog = true → açılır.
window._cftStorageLog = false;
(function _cftSilenceStorageLogs(){
  if (typeof console === 'undefined' || typeof console.info !== 'function') return;
  const orig = console.info.bind(console);
  console.info = function(...args){
    try {
      // [Storage] prefixli mesajları flag kapalıyken yutma
      if (!window._cftStorageLog && args.length && typeof args[0] === 'string' && args[0].indexOf('[Storage]') === 0) {
        return;
      }
    } catch(_) {}
    return orig.apply(console, args);
  };
})();

// 🆕 ═══════════════════════════════════════════════════════════════════════
// LOCALSTORAGE QUOTA YÖNETİMİ
// Tarayıcı localStorage limiti ~5-10MB. Oyun ilerledikçe maç sonuçları,
// market değer geçmişi, mesajlar vb. birikir. Quota dolunca yazma başarısız
// olur ve oyun bozulabilir. Bu sistem otomatik temizlik yapar.
// ═══════════════════════════════════════════════════════════════════════

function _cftStorageSizeKB() {
  try {
    let total = 0;
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (!key) continue;
      const val = localStorage.getItem(key) || '';
      total += key.length + val.length;
    }
    return Math.round(total / 1024);
  } catch(e) { return 0; }
}

function _cftStorageCleanup(aggressive) {
  let freed = 0;
  // 1. Sadece geçici check flag'leri sil (migration flag'leri DOKUNMA — silersek tekrar çalışır)
  const safeToDelete = [
    'cft_injury_check',
    'cft_suspension_check',
    'cft_bet_shared'        // 592 — kupon paylaşım işareti artık bet_slips.shared_at
  ];
  safeToDelete.forEach(k => {
    try {
      const v = localStorage.getItem(k);
      if (v !== null) { freed += (k.length + v.length); localStorage.removeItem(k); }
    } catch(e){}
  });

  // 2. cft_match_results — Supabase'e taşındı, localStorage YOK

  // 3. cft_match_xp_log → Supabase'e taşındı, localStorage temizle
  try { localStorage.removeItem('cft_match_xp_log'); } catch(e){}

  // 4. cft_mv_history → Supabase'e taşındı, localStorage temizle
  try { localStorage.removeItem('cft_mv_history'); } catch(e){}

  // 5. cft_inbox — Supabase'e taşındı, localStorage temizle
  try { localStorage.removeItem('cft_inbox'); } catch(e){}

  // 6. AGGRESSIVE: cft_tr_<id> training cache (active/energy hariç)
  if (aggressive) {
    try {
      const toRemove = [];
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (!key) continue;
        if (key.startsWith('cft_tr_') && key !== 'cft_tr_active' && key !== 'cft_tr_energy') {
          toRemove.push(key);
        }
      }
      toRemove.forEach(k => {
        const v = localStorage.getItem(k) || '';
        freed += (k.length + v.length);
        localStorage.removeItem(k);
      });
    } catch(e){}
  }

  return freed;
}

// Güvenli setItem — quota dolarsa cleanup yap ve tekrar dene
function _cftSafeSetLS(key, value) {
  try {
    localStorage.setItem(key, value);
    return true;
  } catch(e) {
    if (e && (e.name === 'QuotaExceededError' || e.code === 22 || e.code === 1014)) {
      _cftStorageCleanup(false);
      try { localStorage.setItem(key, value); return true; }
      catch(e2) {
        _cftStorageCleanup(true);
        try { localStorage.setItem(key, value); return true; }
        catch(e3) { return false; }
      }
    }
    return false;
  }
}

// Sayfa açılışında otomatik temizlik (kademeli)
(function _cftAutoCleanup(){
  try {
    const size = _cftStorageSizeKB();
    // 3MB üzeri → soft cleanup
    if (size > 3072) {
      _cftStorageCleanup(false);
    }
    // 4MB üzeri → aggressive cleanup
    const sizeAfter = _cftStorageSizeKB();
    if (sizeAfter > 4096) {
      _cftStorageCleanup(true);
    }
  } catch(e){}
})();

// 🆕 GLOBAL OVERRIDE — tüm localStorage.setItem çağrıları otomatik quota-aware
// Bu sayede mevcut kodun her yerindeki setItem quota dolduğunda otomatik
// cleanup yapıp tekrar dener. Manuel _cftSafeSetLS değişikliği gerekmez.
(function _cftPatchLocalStorage(){
  try {
    const proto = Object.getPrototypeOf(localStorage) || Storage.prototype;
    if (!proto || proto.__cftQuotaPatched) return;
    const origSetItem = proto.setItem;
    proto.setItem = function(key, value) {
      try {
        return origSetItem.call(this, key, value);
      } catch(e) {
        if (e && (e.name === 'QuotaExceededError' || e.code === 22 || e.code === 1014)) {
          // 1. soft cleanup
          try { _cftStorageCleanup(false); } catch(_){}
          try { return origSetItem.call(this, key, value); }
          catch(e2) {
            // 2. aggressive cleanup
            try { _cftStorageCleanup(true); } catch(_){}
            try { return origSetItem.call(this, key, value); }
            catch(e3) {
              // 3. yine başarısız → sessizce geç (kritik veri kaybı önlenmiş olmaz ama oyun çalışsın)
              if (window._cftStorageLog) console.warn('[Storage] Yazma başarısız:', key);
              return undefined;
            }
          }
        }
        throw e;
      }
    };
    proto.__cftQuotaPatched = true;
  } catch(e){}
})();

