// Toggle başlangıç durumu
document.addEventListener('DOMContentLoaded', function(){
  const _tm = document.getElementById('set-toggle-matchsound');
  if (_tm) _tm.classList.toggle('on', !window._resGoalSoundOff);
  const _tv = document.getElementById('set-toggle-vibrate');
  if (_tv) _tv.classList.toggle('on', cftTitresimAcik());
  const tog = document.getElementById('set-toggle-buttonsound');
  if(tog){
    if(_cftButtonSoundEnabled) tog.classList.add('on');
    else tog.classList.remove('on');
  }
  // 🆕 Eski localStorage anahtarlarını sil — Supabase migration tamamlandı
  // Bir defalık çalışır (flag kontrolüyle), sonraki sayfa yüklemelerinde atlanır
  try {
    const CLEANUP_FLAG = 'cft_v2_supabase_migration_cleanup';
    if (!localStorage.getItem(CLEANUP_FLAG)) {
      const oldKeys = [
        // Cüzdan + enerji (Supabase)
        'cft_wallet', 'cft_wallet_log', 'cft_tr_energy',
        // Hazırlık maçları
        'cft_friendly_matches',
        // CFC Media
        'cft_cfcmd_posts', 'cft_cfcmd_my_likes', 'cft_cfcmd_my_reposts', 'cft_cfcmd_following',
        // Takım stratejisi + roster
        'cft_team_strategy', 'cft_roster_state', 'cft_roster_persist',
        // Free agents
        'cft_free_agents',
        // Tesis seviyeleri
        'cft_facilities', 'cft_facilities_meta',
        // Takım kasası
        'cft_treasury', 'cft_treasury_log',
        // Aşama 2 sonrası ek anahtarlar
        'cft_userTeam', 'cft_userProgress',
        'cft_market', 'cft_marketval', 'cft_mv_history',
        'cft_match_xp_log', 'cft_user_match_log',
        'cft_equipment', 'cft_career_history',
        'cft_paid_installments', 'cft_joinRequests',
        'cft_train_log', 'cft_tr_active',
        'cft_toto', 'cft_toto_pools', 'cft_toto_meta',
        'cft_shop_stocks', 'cft_transfers',
        'cft_ach_state', 'cft_ach_overrides',
        'cft_coach_profile',
        'cft_inbox',
      ];
      // Sabit anahtarları sil
      oldKeys.forEach(k => { try { localStorage.removeItem(k); } catch(e) {} });
      // Prefix anahtarları sil (cft_r3_*, cft_eurocup_s*, cft_team_manifesto__*, cft_tr_GK/DEF/MID/FWD, cft_skills_*, cft_nt_jersey_*)
      const prefixes = ['cft_r3_', 'cft_eurocup_s', 'cft_team_manifesto__', 'cft_skills_', 'cft_nt_jersey_'];
      const trPosKeys = ['cft_tr_GK', 'cft_tr_DEF', 'cft_tr_MID', 'cft_tr_FWD'];
      try {
        for (let i = localStorage.length - 1; i >= 0; i--) {
          const k = localStorage.key(i);
          if (!k) continue;
          if (trPosKeys.includes(k)) { localStorage.removeItem(k); continue; }
          for (const p of prefixes) {
            if (k.startsWith(p)) { localStorage.removeItem(k); break; }
          }
        }
      } catch(e) {}
      localStorage.setItem(CLEANUP_FLAG, '1');
      console.info('[cleanup] V2 Supabase migration: eski localStorage anahtarları silindi');
    }
  } catch(e) {}
});

