// ═══════════════════════════════════════════════════════════════════
//  🔎 EKSİK ÇEVİRİ TOPLAYICI — Ayarlar → "Eksik çeviriler" satırı
//
//  Motor, çeviremediği her ekran metnini window._i18nEksik kümesine
//  yazıyor. Bu fonksiyon o listeyi panoya kopyalar; böylece oyunda
//  gezip hangi metinlerin GERÇEKTEN Türkçe kaldığını tek seferde
//  çıkarabiliriz — dosyadan tahmin etmeye gerek kalmaz.
//
//  Kullanım: İngilizceye geç → oyunda gez → Ayarlar → dokun → yapıştır.
// ═══════════════════════════════════════════════════════════════════
window.i18nEksikKopyala = function () {
  var el = document.getElementById('setEksik');
  function yaz(m) { if (el) el.textContent = m; }
  try {
    var hepsi = Array.from(window._i18nEksik || []).sort();
    if (!hepsi.length) {
      yaz(i18nLang() === 'tr' ? 'önce İngilizceye geç' : 'liste boş ✓');
      return;
    }

    // ── ÖZEL İSİM AYIKLAMA ──────────────────────────────────────────
    //  Oyuncu, takım ve şehir adları çeviri gerektirmez ama motor
    //  onları da "çeviremedim" diye kaydediyor. Liste kirlenmesin diye
    //  ayrı başlığa alıyoruz.
    //  Kural: yalnızca harf/boşluk/nokta içeren, 1-3 kelimelik, her
    //  kelimesi büyük harfle başlayan ve içinde Türkçe bağlaç/ek
    //  bulunmayan metinler özel isim sayılır.
    // NOT: \b kullanılamaz — JS'de ş/ğ/ı gibi harfler \w sayılmadığı için
    // "Eskişehir" içindeki "Eski" yanlışlıkla kelime sınırı gibi görünür.
    // Sınırı elle tanımlıyoruz.
    var H = '[A-Za-zÇĞİÖŞÜçğıöşü]';
    var TR_KELIME = new RegExp(
      '(^|(?!' + H + ').)(ve|ile|için|bir|bu|şu|var|yok|daha|çok|az|sonra|önce|kadar|göre|tüm|her|maç|takım|oyuncu|puan|hafta|sezon|lig|kupa|gün|yeni|eski|toplam|sıra|kart|gol)((?!' + H + ').|$)', 'i');
    function ozelIsimMi(t) {
      if (!/^[A-Za-zÇĞİÖŞÜçğıöşü.\s'-]+$/.test(t)) return false;  // rakam/emoji varsa değil
      if (TR_KELIME.test(t)) return false;
      var p = t.trim().split(/\s+/);
      if (p.length < 1 || p.length > 3) return false;
      for (var i = 0; i < p.length; i++) {
        var ilk = p[i].charAt(0);
        if (ilk !== ilk.toLocaleUpperCase('tr')) return false;      // küçük harfle başlıyorsa değil
      }
      return true;
    }

    var liste = [], isim = [];
    for (var i = 0; i < hepsi.length; i++) {
      (ozelIsimMi(hepsi[i]) ? isim : liste).push(hepsi[i]);
    }

    var metin = '=== ÇEVRİLECEK (' + liste.length + ') ===\n'
              + liste.join('\n')
              + '\n\n=== ÖZEL İSİM ŞÜPHELİSİ (' + isim.length + ') — çevrilmeyecek ===\n'
              + isim.join('\n');
    var bitti = function () { yaz(liste.length + ' çevrilecek · ' + isim.length + ' isim ✓'); };
    var yedek = function () {
      try {
        var ta = document.createElement('textarea');
        ta.value = metin;
        ta.style.cssText = 'position:fixed;top:-9999px;opacity:0';
        document.body.appendChild(ta);
        ta.select(); ta.setSelectionRange(0, metin.length);
        document.execCommand('copy');
        document.body.removeChild(ta);
        bitti();
      } catch (e) { yaz('kopyalanamadı (' + liste.length + ')'); }
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(metin).then(bitti).catch(yedek);
    } else yedek();
  } catch (e) { yaz('hata'); }
};

// ═══════════════════════════════════════════════════════════════════
//  📊 PUAN TABLOSU SÜTUN BAŞLIKLARI
