// ═══════════════════════════════════════════════════
//   🌍 YABANCI OYUNCU KURALI (FOREIGN PLAYER RULE)
// ═══════════════════════════════════════════════════
// Tanım: Takımın ülkesi (countryCode) ≠ oyuncunun uyruğu (nationality) → yabancı
// Limit: Takım başına max 10 yabancı oyuncu (667)
// Uygulama: Hard limit — 10 yabancı varken 11.'si kadroya eklenemez
// Kapsam: Hem kullanıcı takımı hem AI takımları için geçerli
//
// Kullanım:
//   cftIsForeign(player, teamCC) → bool
//   cftCountForeigners(roster, teamCC) → sayı
//   cftCanAddPlayer(playerNationality, roster, teamCC) → {ok, count, limit, reason}
// ═══════════════════════════════════════════════════
const CFT_FOREIGN_LIMIT = 10;

function cftIsForeign(player, teamCC) {
  if (!player || !teamCC) return false;
  const playerCC = (player.nationality || '').toUpperCase();
  const tcc = (teamCC || '').toUpperCase();
  if (!playerCC || !tcc) return false;
  return playerCC !== tcc;
}

function cftCountForeigners(roster, teamCC) {
  if (!Array.isArray(roster) || !teamCC) return 0;
  let count = 0;
  for (const p of roster) {
    if (cftIsForeign(p, teamCC)) count++;
  }
  return count;
}

function cftCanAddPlayer(playerNationality, roster, teamCC) {
  const tcc = (teamCC || '').toUpperCase();
  const pcc = (playerNationality || '').toUpperCase();
  // Yerli oyuncu — her zaman eklenebilir
  if (pcc === tcc) {
    return { ok: true, count: cftCountForeigners(roster, teamCC), limit: CFT_FOREIGN_LIMIT, reason: 'native' };
  }
  // Yabancı oyuncu — limit kontrolü
  const count = cftCountForeigners(roster, teamCC);
  if (count >= CFT_FOREIGN_LIMIT) {
    return {
      ok: false,
      count,
      limit: CFT_FOREIGN_LIMIT,
      reason: 'foreign_limit_full',
      message: `Bu takımda yabancı oyuncu kontenjanı dolu (${count}/${CFT_FOREIGN_LIMIT}).`
    };
  }
  return { ok: true, count, limit: CFT_FOREIGN_LIMIT, reason: 'foreign_slot_available' };
}

// Takım sayfasındaki "Yabancı Kontenjanı" rozetini günceller.
// Kullanıcı takımı yoksa veya ROSTER_DATA boşsa rozet gizlenir.
function renderForeignBar() {
  const bar = document.getElementById('thbForeignBar');
  if (!bar) return;
  const teamCC = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.countryCode) || null;
  const roster = (typeof ROSTER_DATA !== 'undefined' && Array.isArray(ROSTER_DATA)) ? ROSTER_DATA : [];
  // Takım yoksa veya kadro boşsa gizle
  if (!teamCC || roster.length === 0) {
    bar.style.display = 'none';
    return;
  }
  bar.style.display = '';
  const count = cftCountForeigners(roster, teamCC);
  const limit = CFT_FOREIGN_LIMIT;
  // Sayaç ve sub yazısı
  const countEl = document.getElementById('thbForeignCount');
  const subEl = document.getElementById('thbForeignSub');
  if (countEl) countEl.textContent = String(count);
  if (subEl) {
    if (count >= limit) {
      subEl.textContent = 'Kontenjan dolu — yeni yabancı eklenemez';
    } else if (count >= limit - 1) {
      subEl.textContent = `Sadece ${limit - count} yabancı slotu kaldı`;
    } else {
      subEl.textContent = `${limit - count} yabancı slotu boş`;
    }
  }
  // Renk durumları
  bar.classList.remove('is-warn', 'is-full');
  if (count >= limit) bar.classList.add('is-full');
  else if (count >= limit - 1) bar.classList.add('is-warn');
}

// ═══════════════════════════════════════════════════
//   ☰ TAKIM HERO BAR — HAMBURGER MENÜ
// ═══════════════════════════════════════════════════
// Hero bar'daki üç çizgili butona tıklayınca açılan dropdown menüyü yönetir.
// Menü item'larına tıklandığında veya menü dışına tıklandığında otomatik kapanır.
function toggleTeamHeroMenu(e) {
  if (e) { e.stopPropagation(); e.preventDefault(); }
  const wrap = document.getElementById('thbMenuWrap');
  if (!wrap) return;
  wrap.classList.toggle('open');
}
// Global click listener — menü dışına/item'a tıklandığında kapat
document.addEventListener('click', function(e) {
  const wrap = document.getElementById('thbMenuWrap');
  if (!wrap || !wrap.classList.contains('open')) return;
  // Hamburger butonuna tıklamak toggleTeamHeroMenu tarafından yönetiliyor
  if (e.target.closest('.thb-menu-btn')) return;
  // Menü içine (item'a) tıklandı → action çalışsın, menü kapansın
  // Menü dışına tıklandı → menü kapansın
  wrap.classList.remove('open');
});
// Sayfa değişiminde menüyü kapat (hero bar başka sayfada görünmez ama yine de güvenlik)
document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') {
    const wrap = document.getElementById('thbMenuWrap');
    if (wrap) wrap.classList.remove('open');
  }
});

// ═══════════════════════════════════════════════════
//   MATCH SQUAD GENERATOR
// ═══════════════════════════════════════════════════
// Bir maç için iki takımın 11'erli kadrolarını üretir.
// Kullanıcının takımı varsa ROSTER_DATA'dan, yoksa teams DB takım rating'inden
// türetilen sentetik 11'erli kadroyu üretir.
//
// Pozisyon koordinatları HOME_TEAM/AWAY_TEAM şablonundan kopyalanır.
// İsimler takımın ülkesinin NAMES_BY_COUNTRY havuzundan rastgele çekilir.
// Numaralar 1-11.
//
// Parametreler:
//   teamData: { name, short, countryCode, rating, isUser? } — teams DB veya kullanıcı takımı
//   isHome: bool — ev sahibiyse HOME pozisyonları, deplasmansa AWAY
//   seed: deterministik üretim için
//
// Döner: { id, name, short, rating, players:[{num,name,pos,rating,x,y,isUser?}, ...] }

// ══════════════════════════════════════════════════════════════════
//  TAKIM KADRO SİSTEMİ v2 — gerçekçi rating dağılımı
//  localStorage cache → İzmir her maçta aynı kadroyla çıkar
//  oz bazlı Süper Lig farklılaştırması (hepsi rating=95 ama oz farklı)
//  Cache versiyonu: v2 (önceki cache'leri geçersiz kılar)
// ══════════════════════════════════════════════════════════════════

const _ROSTER_VER = 'v8';  // v8: jenerik isimler (gerçek futbolcu adı YOK), tüm yetenekler 10, sabit kadro

// 🆕 Eski lokal bot cache'lerini temizle (artık tüm botlar Supabase'te)
(function _cleanLegacyBotCache() {
  try {
    for (let i = localStorage.length - 1; i >= 0; i--) {
      const k = localStorage.key(i);
      if (k && k.startsWith('cft_r3_')) localStorage.removeItem(k);
    }
  } catch(e) {}
})();

// Türkçe oyuncu isimleri
const TR_FIRST = ['Murat','Emre','Burak','Serkan','Tolga','Kerem','Fatih','Gökhan','Okan','Arda','Halil','Volkan','Zafer','Berk','Taner','Kaan','Onur','Selim','Cem','Tayfun','Adem','Barış','Cenk','Erhan','Fırat','İlker','Kadir','Levent','Necati','Ozan','Recep','Soner','Uğur','Yasin','Zeki','Cengiz','Devrim','Ekrem','Hüsrev','Kemal'];
const TR_LAST  = ['Yılmaz','Kaya','Demir','Şahin','Çelik','Yıldız','Öztürk','Aydın','Arslan','Doğan','Koç','Kurt','Aslan','Çetin','Polat','Güneş','Korkmaz','Aksoy','Tekin','Bulut','Özkan','Tunç','Ateş','Karahan','Güler','Bozkurt','Duman','Demirci','Kaplan','Sarı','Topal','Acar','Erdem','Sezer','Başaran','Albayrak','Yıldırım','Çalışkan','Keskin','Altun'];

function _namePoolForCC(cc) {
  // 🆕 JENERİK İSİMLER — gerçek futbolcu adı YOK
  // Her oyuncuya ülkesine göre sıradan isim/soyad ver (NAMES_BY_COUNTRY + SURNAMES_BY_COUNTRY)
  // Eski ENC_NAME_POOLS (gerçek milli takım oyuncuları) artık kullanılmıyor.
  let FIRST = (typeof NAMES_BY_COUNTRY !== 'undefined' && NAMES_BY_COUNTRY[cc]) || null;
  let LAST  = (typeof SURNAMES_BY_COUNTRY !== 'undefined' && SURNAMES_BY_COUNTRY[cc]) || null;

  // Bu ülkenin havuzu yoksa → Türkçe jenerik (her zaman dolu)
  if (!FIRST || !FIRST.length) {
    FIRST = (typeof NAMES_BY_COUNTRY !== 'undefined' && NAMES_BY_COUNTRY.TR) || ['Mehmet','Ali','Ahmet'];
  }
  if (!LAST || !LAST.length) {
    LAST = (typeof SURNAMES_BY_COUNTRY !== 'undefined' && SURNAMES_BY_COUNTRY.TR) || ['Yılmaz','Demir','Kaya'];
  }
  return { FIRST, LAST };
}

function _hashRng(seed, salt) {
  let h = 2166136261;
  const s = String(seed) + '�' + String(salt);
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619) | 0;
  }
  return ((h ^ (h >>> 16)) >>> 0) / 0xffffffff;
}

const SQUAD_SLOTS = [
  { pos:'KL',  x:50, y:93, num:1  },
  { pos:'SB',  x:15, y:76, num:2  },
  { pos:'STB', x:37, y:76, num:5  },
  { pos:'STB', x:63, y:76, num:4  },
  { pos:'SB',  x:85, y:76, num:3  },
  { pos:'DOS', x:30, y:57, num:6  },
  { pos:'OS',  x:50, y:53, num:8  },
  { pos:'OS',  x:70, y:57, num:10 },
  { pos:'SAK', x:18, y:30, num:7  },
  { pos:'FWD', x:50, y:23, num:9  },
  { pos:'SAK', x:82, y:30, num:11 },
];

// 🆕 15-kişilik kadro: 11 ilk on + 4 yedek (yedeklerin x,y'si yok)
const SQUAD_SLOTS_15 = [
  ...SQUAD_SLOTS.map(s => ({ ...s, starter:true })),
  { pos:'KL',  num:12, starter:false },
  { pos:'STB', num:13, starter:false },
  { pos:'OS',  num:14, starter:false },
  { pos:'FWD', num:15, starter:false }
];

// 🆕 KL/STB/SB/DOS/OS/SAK/FWD → GK/DEF/MID/FWD (geriye uyumluluk için)
const POS_GROUP = { KL:'GK', STB:'DEF', SB:'DEF', DOS:'MID', OS:'MID', SAK:'MID', SOK:'MID', FWD:'FWD',
  GK:'GK', RB:'DEF', CB:'DEF', LB:'DEF', DM:'MID', CM:'MID', RM:'MID', LM:'MID', AM:'MID', RF:'FWD', LF:'FWD', ST:'FWD' };

// 🆕 ALT MEVKİ SİSTEMİ (12 mevki) — ana grubun (GK/DEF/MID/FWD) ALTINDA.
//   Ana grup hat/yetenek/antrenmanı sürdürür; alt mevki SADECE kayıt seçimi + kart gösterimi.
const SUB_POS = {
  GK:  [{c:'GK', t:'Kaleci'}],
  DEF: [{c:'RB', t:'Sağ Bek'}, {c:'CB', t:'Stoper'}, {c:'LB', t:'Sol Bek'}],
  MID: [{c:'DM', t:'Defansif Orta Saha'}, {c:'CM', t:'Merkez Orta Saha'}, {c:'RM', t:'Sağ Kanat'}, {c:'LM', t:'Sol Kanat'}, {c:'AM', t:'Forvet Arkası'}],
  FWD: [{c:'RF', t:'Sağ Forvet'}, {c:'LF', t:'Sol Forvet'}, {c:'ST', t:'Forvet'}]
};
const SUBPOS_GROUP = { GK:'GK', RB:'DEF',CB:'DEF',LB:'DEF', DM:'MID',CM:'MID',RM:'MID',LM:'MID',AM:'MID', RF:'FWD',LF:'FWD',ST:'FWD' };
const SUBPOS_LABEL = { GK:'Kaleci', RB:'Sağ Bek', CB:'Stoper', LB:'Sol Bek', DM:'Defansif Orta Saha', CM:'Merkez Orta Saha', RM:'Sağ Kanat', LM:'Sol Kanat', AM:'Forvet Arkası', RF:'Sağ Forvet', LF:'Sol Forvet', ST:'Forvet' };
const _OLD2SUB = { KL:'GK', STB:'CB', SB:'RB', DOS:'DM', OS:'CM', SAK:'RM', SOK:'LM', FWD:'ST' };
function subPosOf(p) {
  if (!p) return 'CM';
  const s = p.subPos || p.sub_pos;
  if (s && SUBPOS_GROUP[s]) return s;
  if (_OLD2SUB[p.pos]) return _OLD2SUB[p.pos];
  const g = p.posGroup || p.pos_group || (POS_GROUP[p.pos]) || p.pos;
  return ({ GK:'GK', DEF:'CB', MID:'CM', FWD:'ST' })[g] || 'CM';
}
function subPosGroupOf(sub) { return SUBPOS_GROUP[sub] || 'MID'; }
function subPosClass(p) { return 'pos-' + subPosGroupOf(subPosOf(p)).toLowerCase(); }
// 🆕 MEVKİ-DIŞI OVR CEZASI (diziliş kartı)
function _zoneIdx(z){ return z==='GK'?0 : z==='DEF'?1 : z==='MID'?2 : 3; }
// Ceza çarpanı: kendi alt mevkisi (ownSub) ↔ slot alt mevkisi (slotSub)
function posPenaltyFactor(ownSub, slotSub) {
  if (!ownSub || !slotSub) return 1;
  if (ownSub === slotSub) return 1;                 // tam kendi mevkisi
  const oz = subPosGroupOf(ownSub), sz = subPosGroupOf(slotSub);
  if (oz === sz) return 0.85;                        // aynı bölge, farklı alt mevki → -%15
  const d = Math.abs(_zoneIdx(oz) - _zoneIdx(sz));
  return d === 1 ? 0.80 : d === 2 ? 0.70 : 0.60;     // -%20 / -%30 / -%40
}
// Bir slotta gösterilecek efektif OVR (baz = slot bölgesi yeteneği × ceza çarpanı)
function pitchSlotOvr(p, slotSub) {
  if (!slotSub || !SUBPOS_GROUP[slotSub]) slotSub = (typeof subPosOf === 'function') ? subPosOf(p) : 'CM';
  const base = (p && (p.overall != null ? p.overall : (p.rating || 10))) || 10;  // 🆕 VAR OLAN stored OVR (yeniden hesap YOK); mevki-dışı cezası aşağıda uygulanır
  const ownSub = (typeof subPosOf === 'function') ? subPosOf(p) : ((p && p.pos) || 'CM');
  return Math.max(1, Math.round(base * posPenaltyFactor(ownSub, slotSub)));
}

// 🆕 Tüm yetenekler 10'dan başlar (büyüme sistemi sonradan eklenecek)
// ═══════════════════════════════════════════════════════════════════
//  YETENEK SİSTEMİ — 4 MEVKİ GRUBU
// ═══════════════════════════════════════════════════════════════════
// Her oyuncu 4 mevki grubu için ayrı yetenek setine sahiptir:
//   GK  (Kaleci)      — diving, reflexes, handling, kicking, positioning
//   DEF (Defans)      — tackling, marking, heading, strength, positioning
//   MID (Orta Saha)   — passing, vision, dribbling, stamina, technique
//   FWD (Forvet)      — shooting, finishing, pace, dribbling, positioning
//
// • Her oyuncunun her grup için bir ortalaması vardır (saklı).
// • UI'da SADECE oyuncunun seçtiği (ana) mevkisinin ortalaması gösterilir.
// • Maçta hangi mevkide oynatılırsa O mevkinin yetenekleri kullanılır.
//   (Forveti kaleye koyarsan kaleci yetenekleri ile değerlendirilir.)
//
// Tüm yetenekler 10'dan başlar (meritokrasi). Oyuncu geliştikçe yükselir.
// ═══════════════════════════════════════════════════════════════════
function _buildAbilities() {
  return {
    GK:  { refleks:10, top_tutma:10, hava_hak:10, kal_poz:10, bire_bir:10, penalti_kur:10, uzak_kur:10, yakin_kur:10, degaj:10, ayak_kur:10, konsant:10, soguk:10, ziplay:10, kal_guc:10, denge:10 },
    DEF: { markaj:10, mudahale:10, blok:10, sav_poz:10, sav_kafa:10, fiz_muc:10, ayakta_kal:10, geri_kosu:10, geriden_pas:10, alan_kapat:10 },
    MID: { kisa_pas:10, uzun_pas:10, top_kontrol:10, teknik:10, oyun_gorusu:10, tempo:10, dayanikli:10, yon_deg:10, karar:10, top_calma:10 },
    FWD: { bitiricilik:10, sut_guc:10, uzak_vurus:10, gol_poz:10, huc_kafa:10, ilk_dok:10, pat_hiz:10, calim:10, baski_alt:10, topsuz_kosu:10 }
  };
}

// Bir oyuncunun belirli bir mevki grubundaki yetenek ortalaması.
// posGroup verilmezse oyuncunun ana mevki grubunu kullanır.
// Geriye dönük: eski flat abilities yapısına da uyumlu.
function getPlayerPositionAvg(player, posGroup) {
  if (!player) return 10;
  const ab = player.abilities;

  // Yeni format: abilities = { GK:{...}, DEF:{...}, MID:{...}, FWD:{...} }
  if (ab && typeof ab === 'object' && ab.GK && ab.DEF) {
    const group = posGroup || player.posGroup
                || (typeof POS_GROUP !== 'undefined' && POS_GROUP[player.pos])
                || 'MID';
    const sub = ab[group];
    if (!sub || typeof sub !== 'object') return 10;
    const vals = Object.values(sub).filter(v => typeof v === 'number');
    if (!vals.length) return 10;
    return Math.round((vals.reduce((a,b)=>a+b,0) / vals.length) * 10) / 10;
  }

  // Eski format (geriye dönük): flat abilities objesi
  if (ab && typeof ab === 'object') {
    const vals = Object.values(ab).filter(v => typeof v === 'number');
    if (vals.length) return Math.round((vals.reduce((a,b)=>a+b,0) / vals.length) * 10) / 10;
  }

  // Hiç yetenek yoksa overall/rating fallback
  return player.overall || player.rating || 10;
}

// Oyuncunun OVERALL değeri — TEK KURAL:
//   OVR = (KL_avg + DF_avg + OS_avg + FW_avg) / 4
// 4 mevki ortalamasının ortalaması. Başka HİÇBİR yerden overall eklenmez
// (seviye bonusu yok, maç ödülü overall yok). Yetenekler arttıkça OVR otomatik artar.
// 🆕 EKİPMANLI OVR — oyuncu sayfasındaki 4 hat barının ortalamasıyla
//   AYNI hesap. Modal eskiden sunucudaki ham `players.overall` değerini
//   basıyordu; oyuncu sayfası ise ekipman bonuslu ortalamayı. Aynı kişi
//   iki ekranda 24 ve 25 görünüyordu.
//   Bonus kaynağı: kendinsen kendi setin, başkasıysa `_visitorEqCache`
//   (yalnızca önbellek O kişiye aitse — `_visitorEqUid` ile doğrulanır).
function _ovrEkipmanli(player) {
  const ab = player && player.abilities;
  if (!ab || typeof ab !== 'object' || !ab.GK || !ab.DEF || !ab.MID || !ab.FWD) return null;
  const uid = player.userId || player.user_id || null;
  let bon = null;
  try {
    const benim = (typeof window !== 'undefined' && window.authUser) ? window.authUser.id : null;
    if (uid && benim && String(uid) === String(benim)) {
      if (typeof getEquippedBonuses === 'function') bon = getEquippedBonuses();
    } else if (uid && typeof _visitorEqUid !== 'undefined' && _visitorEqUid === uid) {
      if (typeof getEquippedBonuses === 'function' && typeof _getVisitorEqData === 'function') {
        bon = getEquippedBonuses(_getVisitorEqData());
      }
    }
  } catch(e) {}
  // 593 — oyuncunun kendi ekranı ve veritabanıyla aynı hesap: yetenek başına yuvarlanmış bonus,
  //   hat = katalogdaki tüm yeteneklerin ortalaması (eksik 10)
  if (typeof SKILL_DEFS === 'undefined' || !SKILL_DEFS.ALL) return null;
  const lv = {};
  SKILL_DEFS.ALL.forEach(cat => cat.skills.forEach(sk => { lv[sk.id] = 10; }));
  ['GK', 'DEF', 'MID', 'FWD'].forEach(g => Object.keys(ab[g] || {}).forEach(id => { lv[id] = Number(ab[g][id]) || 10; }));
  if (bon) Object.keys(bon).forEach(id => { if (lv[id] !== undefined) lv[id] = Math.min(100, Math.round(lv[id] * (1 + bon[id] / 100))); });
  const c = SKILL_DEFS.ALL.map(cat => cat.skills.reduce((a, sk) => a + (lv[sk.id] || 10), 0) / cat.skills.length);
  return Math.max(1, Math.min(99, Math.round((c[0] + c[1] + c[2] + c[3]) / 4)));
}

function getPlayerMainOverall(player) {
  if (!player) return 10;

  // Yetenek ortalama helper'ı (alt obje → ortalama)
  const _avg = (sub) => {
    if (!sub || typeof sub !== 'object') return null;
    const vals = Object.values(sub).filter(v => typeof v === 'number');
    if (!vals.length) return null;
    return vals.reduce((a,b) => a+b, 0) / vals.length;
  };

  // Bir abilities/skills bag'i (yapılı {GK,DEF,MID,FWD}) için OVR
  const _ovrFromBag = (bag) => {
    if (!bag || typeof bag !== 'object' || !bag.GK || !bag.DEF || !bag.MID || !bag.FWD) return null;
    const gk = _avg(bag.GK); const df = _avg(bag.DEF); const md = _avg(bag.MID); const fw = _avg(bag.FWD);
    if (gk == null || df == null || md == null || fw == null) return null;
    return (gk + df + md + fw) / 4;
  };

  // 🟢 1) BOT veya BAŞKA KULLANICI — kendisi DEĞİL
  if (player.role !== 'user') {
    const otherUid = player.userId || player.user_id;
    const isOtherUser = !player.isBot && !!otherUid;

    // ── BAŞKA GERÇEK KULLANICI ──────────────────────────────────────
    //   ESKİDEN: `_visitorSkillsCache`ten 45 yeteneği okumaya çalışıyordu,
    //   cache boşsa `_loadVisitorSkills(uid)` ile async çekiyordu.
    //   AMA `user_player` üzerindeki RLS politikası (up_select_own)
    //   SELECT'i kişinin KENDİ satırıyla sınırlıyor — yani o çağrı
    //   BAŞKASI için hiçbir zaman veri döndürmüyordu. Sessizce boş
    //   dönüyor, kod `abilities`e düşüyor (gerçek kullanıcılarda boş),
    //   oradan da bayat `overall`a düşüyordu. Kadroda herkesin 10
    //   görünmesinin sebebi buydu. Üstelik her render'da kadro
    //   büyüklüğü kadar boşuna istek atıyordu.
    //
    //   ARTIK: `players.overall` sunucuda yazılıyor (recompute_team /
    //   recompute_all_ovr / refresh_ovr). Doğru kaynak o.
    if (isOtherUser) {
      // Cache doluysa (kendi satırın ya da başka bir yoldan geldiyse) onu yeğle
      // ⚠️ Önbellekte BOŞ nesne de olabilir: `_loadVisitorSkills` başkasının
      //    satırını okuyamadığında (RLS) tekrar tekrar denemesin diye {} yazıyor.
      //    Boşu "veri var" sayarsak 45 yeteneği 10 kabul edip 10 döneriz —
      //    doğru veri `players.abilities`'te dururken. Bu yüzden dolu mu diye bak.
      if (typeof SKILL_DEFS !== 'undefined' && SKILL_DEFS.ALL &&
          typeof _visitorSkillsCache !== 'undefined' && _visitorSkillsCache[otherUid] &&
          Object.keys(_visitorSkillsCache[otherUid]).length > 0) {
        const skills = _visitorSkillsCache[otherUid];
        const _catAvgO = (catSkills) => {
          if (!catSkills || !catSkills.length) return null;
          const sum = catSkills.reduce((a, s) => a + (skills[s.id] || 10), 0);
          return sum / catSkills.length;
        };
        const gk = _catAvgO(SKILL_DEFS.ALL[0] && SKILL_DEFS.ALL[0].skills);
        const df = _catAvgO(SKILL_DEFS.ALL[1] && SKILL_DEFS.ALL[1].skills);
        const md = _catAvgO(SKILL_DEFS.ALL[2] && SKILL_DEFS.ALL[2].skills);
        const fw = _catAvgO(SKILL_DEFS.ALL[3] && SKILL_DEFS.ALL[3].skills);
        if (gk != null && df != null && md != null && fw != null) {
          return Math.max(1, Math.min(99, Math.round((gk + df + md + fw) / 4)));
        }
      }
      // ⚠️ SIRA ÖNEMLİ — önce SUNUCU değeri.
      //   Dört hattın ortalaması ile sunucunun `players.overall` değeri
      //   aynı şey DEĞİL: sunucu ana mevkiye göre hesaplıyor, ortalama
      //   ise dört hattı eşit sayıyor. Kaleci için GK 15 ama diğer üç
      //   hat 10-11 olduğundan ortalama 12'ye düşüyordu — kadroda
      //   herkesin OVR'ı azalıp sıralama değişti.
      //   Bu yüzden başkaları için sunucu değeri esas; ortalama yalnızca
      //   sunucu değeri yoksa (0/boş) devreye giriyor.
      const _ovU = Number(player.overall || player.rating || 0);
      if (_ovU > 0) return Math.max(1, Math.min(99, Math.round(_ovU)));
      const _eqOvr = _ovrEkipmanli(player);
      if (_eqOvr != null) return _eqOvr;
      return 10;
    }

    // ── BOT ─────────────────────────────────────────────────────────
    const fromAb = _ovrFromBag(player.abilities);
    if (fromAb != null) {
      return Math.max(1, Math.min(99, Math.round(fromAb)));
    }
    // abilities ROSTER_DATA'ya tam yüklenmemiş olabilir → sunucu değeri
    const ov = Number(player.overall || player.rating || 10);
    return Math.max(1, Math.min(99, Math.round(ov)));
  }

  // 🟢 USER — UI'daki barlar ile aynı kaynaktan hesapla (getSkillLevels, item bonusları dahil).
  //   Bu sayede kartın sağ üstündeki OVR ile 4 hat barlarının ortalaması TUTARLI olur.
  //   Eski path'ler (_skillsCache yapı uyumsuzluğu + stale player.overall fallback)
  //   migration'ı self-fulfillingly bozuyordu — KALDIRILDI.
  if (typeof getSkillLevels === 'function' && typeof SKILL_DEFS !== 'undefined' && SKILL_DEFS.ALL) {
    const lvls = getSkillLevels(player.pos || 'MID');
    const _catAvg = (catSkills) => {
      if (!catSkills || !catSkills.length) return null;
      const sum = catSkills.reduce((a, s) => a + (lvls[s.id] || 10), 0);
      return sum / catSkills.length;
    };
    const gk = _catAvg(SKILL_DEFS.ALL[0] && SKILL_DEFS.ALL[0].skills);
    const df = _catAvg(SKILL_DEFS.ALL[1] && SKILL_DEFS.ALL[1].skills);
    const md = _catAvg(SKILL_DEFS.ALL[2] && SKILL_DEFS.ALL[2].skills);
    const fw = _catAvg(SKILL_DEFS.ALL[3] && SKILL_DEFS.ALL[3].skills);
    if (gk != null && df != null && md != null && fw != null) {
      return Math.max(1, Math.min(99, Math.round((gk + df + md + fw) / 4)));
    }
  }

  // User skiller henüz yüklenmemiş — başlangıç değeri 10 (stale overall'a düşme)
  return 10;
}

// 593 — Başka gerçek oyuncunun seviyeleri (eşya bonuslu) — kendi ekranındakiyle aynı hesap.
//   Kaynak: players kopyası (yetenekler + kuşandığı eşyalar); veritabanı user_player'dan eşitler.
function _digerOyuncuSeviyeleri(player) {
  const ab = player && player.abilities;
  if (!ab || typeof ab !== 'object' || !ab.GK || !ab.DEF || !ab.MID || !ab.FWD) return null;
  const lv = {};
  if (typeof SKILL_DEFS !== 'undefined' && SKILL_DEFS.ALL) SKILL_DEFS.ALL.forEach(c => c.skills.forEach(sk => { lv[sk.id] = 10; }));
  ['GK', 'DEF', 'MID', 'FWD'].forEach(g => {
    const sub = ab[g] || {};
    Object.keys(sub).forEach(id => { const v = Number(sub[id]); lv[id] = v || 10; });
  });
  const eq = player.equipment;
  if (eq && typeof eq === 'object' && typeof getEquippedBonuses === 'function') {
    const bon = getEquippedBonuses(eq);
    Object.keys(bon).forEach(id => {
      if (lv[id] === undefined) return;
      lv[id] = Math.min(100, Math.round(lv[id] * (1 + bon[id] / 100)));
    });
  }
  return lv;
}

// Maçta kullanılan effective rating: oyuncu hangi mevkide OYNATILIYORSA
// onun yetenek ortalaması. Ana mevki dışındaysa "out of position" doğal düşük olur.
// 🆕 Kullanıcı için: gerçek SKILL_DEFS verisinden, yerleştirildiği mevkinin ortalaması.
function getPlayerEffectiveRating(player, playedPosGroup) {
  if (!player) return 10;
  const group = playedPosGroup || (typeof POS_GROUP !== 'undefined' && POS_GROUP[player.pos]) || 'MID';

  // 🆕 Giriş yapan kullanıcının kendi oyuncusu: skill'ler abilities'te değil antrenman
  //   verisinde (getSkillLevels). OYNADIĞI mevkinin (group) yetenek ortalamasını oradan al.
  if ((player.role === 'user' || player.isUser) && typeof getSkillLevels === 'function' && typeof calcOverallForGroup === 'function') {
    const lvls = getSkillLevels(player.pos || 'MID');
    return Math.max(1, Math.min(99, Math.round(calcOverallForGroup(group, lvls))));
  }

  // 593 — Başka gerçek oyuncu: yetenek + eşya (kendi ekranındaki değerle aynı)
  if (!player.isBot && (player.userId || player.user_id) && typeof calcOverallForGroup === 'function') {
    const _lv = _digerOyuncuSeviyeleri(player);
    if (_lv) return Math.max(1, Math.min(99, Math.round(calcOverallForGroup(group, _lv))));
  }

  // 🆕 HERKES (bot/diğer): oynadığı mevkinin yetenek ortalaması (forvet ≠ orta saha).
  //   45 yetenekli abilities varsa o grubun ortalamasını al; yoksa overall fallback.
  const ab = player.abilities;
  const hasGroupedAbilities = ab && typeof ab === 'object' && ab.GK && ab.DEF && ab.MID && ab.FWD;
  if (hasGroupedAbilities) {
    const base = getPlayerPositionAvg(player, group);
    return Math.max(1, Math.min(99, Math.round(base)));
  }

  // Abilities yoksa (eski/eksik veri) → DB overall fallback
  const ov = Number(player.overall || player.rating || 10);
  return Math.max(1, Math.min(99, Math.round(ov)));
}

// 🆕 OVR'ye göre hiyerarşik kart kademesi (renk class'ı)
//   0-34 bronz · 35-54 silver · 55-74 gold · 75-94 elmas · 95+ premium siyah
function getOvrTier(ovr) {
  const v = Number(ovr) || 0;
  if (v >= 95) return 'tier-premium';
  if (v >= 75) return 'tier-diamond';
  if (v >= 55) return 'tier-gold';
  if (v >= 35) return 'tier-silver';
  return 'tier-bronze';
}

// Pozisyon sırası — 11 oyuncunun yıldızdan rota'ya doğal düşüş
// idx 0-10: KL, SB, STB, STB, SB, DOS, OS, OS, SAK, FWD, SAK
// Oyuncu kalitesi sıralaması: forvet yıldız, kanatlar iyi, savunma orta, kaleci stabil
const ROLE_QUALITY = [
  0.02,  // KL — ortaya yakın ama kendi özelinde
  -0.10, // SB sol — ikinci kalite savunma
  -0.05, // STB merkez — daha iyi savunma
  -0.05, // STB merkez
  -0.12, // SB sağ — en zayıf savunma
  -0.02, // DOS — ortalama orta saha
  +0.08, // OS — kaliteli orta saha
  +0.06, // OS — kaliteli orta saha
  +0.12, // SAK — yıldız kanat
  +0.18, // FWD — takımın yıldız forveti
  +0.10, // SAK — ikinci kanat
];

// ═══════════════════════════════════════════════════════════════════
//  TAKIM GÜCÜ HESABI — Mevcut oyuncuların ortalaması
// ═══════════════════════════════════════════════════════════════════
// Tüm takımlar (botlar dahil) aynı seviyeden başlar — herkes 10.
// Takım gücü statik bir değer DEĞİLDİR; takımın mevcut oyuncularının
// ortalaması olarak DİNAMİK hesaplanır. Oyuncular geliştikçe takım
// güçlenir (gerçek meritokrasi).
//
// Kullanım:
//   calcTeamPowerAverage(playersArray)   → ortalama (1 ondalık)
//   calcTeamPowerAverage({players: [..]}) → aynı (team objesi de kabul)
//
// Maç önizleme ekranı bu değeri okur (fillPreMatchPreview).
// ═══════════════════════════════════════════════════════════════════
function calcTeamPowerAverage(team) {
  let players = null;
  if (Array.isArray(team)) players = team;
  else if (team && Array.isArray(team.players)) players = team.players;
  if (!players || !players.length) return 10;

  let sum = 0, count = 0;
  for (const p of players) {
    if (!p) continue;
    // 🆕 TEK KAYNAK: getPlayerMainOverall (bot→10, user→skill levels)
    const r = (typeof getPlayerMainOverall === 'function')
      ? getPlayerMainOverall(p)
      : (p.overall || p.rating || 10);
    sum += r;
    count++;
  }
  if (count === 0) return 10;
  return Math.round((sum / count) * 10) / 10; // 1 ondalık (örn. 12.4)
}

// 🆕 v4: Yabancı oyuncular için kullanılacak ülke havuzu
// Avrupa ağırlıklı, çeşitli kıtalardan birkaç ülke karışık
const _FOREIGN_POOL_CCS = [
  'BR','AR','CO','UY',           // Güney Amerika
  'NG','SN','GH','CI','MA',      // Afrika
  'JP','KR','AU',                // Asya/Pasifik
  'FR','ES','PT','IT','DE','NL','BE','TR','SE','HR','RS','PL','UA','BG','GR','AT','CH','DK','NO'
];

// 🆕 v4: Tier'a göre yabancı oyuncu sayısı (0-3 arası, deterministik)
//   Tier 0-1 (Süper Lig + 1.Lig)  : 2-3 yabancı  (üst kalite, daha çekici lig)
//   Tier 2-3                       : 1-2 yabancı
//   Tier 4-5+                      : 0-1 yabancı  (alt lig, çoğunlukla yerli)
function _foreignCountForTier(tier, seed) {
  const t = Math.max(0, tier || 0);
  const r = _hashRng(seed, 'foreignCount'); // 0-1
  if (t <= 1) return 2 + Math.floor(r * 2);   // 2 veya 3
  if (t <= 3) return 1 + Math.floor(r * 2);   // 1 veya 2
  return Math.floor(r * 2);                    // 0 veya 1
}

// 🆕 RAM cache: takım bazlı bot listesi (Supabase'ten yüklenir)
// Format: { "TR:Galatasaray": [{num, name, pos, ...}, ...] }
const _teamRosterCache = {};
const _teamRosterLoading = {};

// Tek takım için Supabase'ten botlar+kullanıcılar (hydrated)
// 🆕 565 — Birden çok takımın kadrosunu TEK sorguda yükler (eskiden takım başına ayrı
//   istek: lig istatistik sekmesi ~18, federasyon seçimi aday sayısı kadar). Satırlar
//   tek-takım yükleyiciyle AYNI dönüşümden geçer → önbellekteki kadro birebir aynı.
const _KADRO_KOLON = 'id, num, name, pos, pos_group, sub_pos, nationality, nation, level, xp, overall, rating, abilities, role, avatar, avatar_id, is_bot, user_id, last_seen, goals_total, assists_total, matches_played, match_ratings, stats_by_comp, season_yellow, suspend_matches, suspend_reason, injury_until, kondisyon, kondisyon_at, kondisyon_hiz';
async function _kadrolariTopluYukle(cc, teamNames) {
  if (!window.sb || !cc || !Array.isArray(teamNames)) return;
  const eksik = Array.from(new Set(teamNames.filter(n => n && !_teamRosterCache[cc + ':' + n] && !_teamRosterLoading[cc + ':' + n])));
  if (!eksik.length) return;
  const gruplar = {};
  for (let i = 0; i < eksik.length; i += 20) {
    const parca = eksik.slice(i, i + 20);
    for (let from = 0; from < 5000; from += 1000) {
      const { data, error } = await window.sb.from('players').select(_KADRO_KOLON + ', team_name')
        .eq('country_code', cc).in('team_name', parca)
        .order('team_name').order('num').range(from, from + 999);
      if (error) { console.warn('[teamRoster toplu] hata:', error); return; }
      if (!Array.isArray(data) || !data.length) break;
      for (const r of data) (gruplar[r.team_name] || (gruplar[r.team_name] = [])).push(r);
      if (data.length < 1000) break;
    }
  }
  for (const tn of eksik) {
    const rows = gruplar[tn];
    if (rows && rows.length && !_teamRosterCache[cc + ':' + tn]) _teamRosterCache[cc + ':' + tn] = _kadroSatirlariniCevir(rows, cc);
  }
}

async function _loadTeamRosterFromServer(cc, teamName) {
  if (!window.sb) return null;
  const key = cc + ':' + teamName;
  if (_teamRosterCache[key]) return _teamRosterCache[key];
  if (_teamRosterLoading[key]) return _teamRosterLoading[key];
  _teamRosterLoading[key] = (async () => {
    try {
      const { data, error } = await window.sb.from('players')
        .select(_KADRO_KOLON)
        .eq('country_code', cc)
        .eq('team_name', teamName)
        .order('num');
      if (error) { console.warn('[teamRoster] hata:', error); return null; }
      if (!data || data.length === 0) return null;
      const players = _kadroSatirlariniCevir(data, cc);
      _teamRosterCache[key] = players;
      return players;
    } catch(e) { console.warn('[teamRoster] exception:', e); return null; }
    finally { delete _teamRosterLoading[key]; }
  })();
  return _teamRosterLoading[key];
}

function _kadroSatirlariniCevir(data, cc) {
      // SQUAD_SLOTS_15 ile starter/x/y bilgisini birleştir
      const players = data.map((r, i) => {
        const sl = (typeof SQUAD_SLOTS_15 !== 'undefined' && SQUAD_SLOTS_15[i]) || {};
        // Ortalama maç rating'i (match_ratings array'inden)
        let avgMatchRating = 0, mrCount = 0;
        if (Array.isArray(r.match_ratings)) {
          for (const mr of r.match_ratings) {
            if (mr && typeof mr.rating === 'number') { avgMatchRating += mr.rating; mrCount++; }
          }
          if (mrCount > 0) avgMatchRating /= mrCount;
        }
        return {
          id: r.id,
          num: r.num,
          name: r.name,
          pos: r.pos,
          posGroup: r.pos_group, subPos: r.sub_pos,
          rating: r.rating || 10,
          overall: r.overall || 10,
          level: r.level || 0,
          xp: r.xp || 0,
          age: 18 + (r.num % 17),
          starter: !!sl.starter,
          abilities: r.abilities,
          nation: r.nation || '🏳️',
          nationality: r.nationality || cc,
          avatar: r.avatar || (r.is_bot ? '🤖' : '👤'),
          avatar_id: r.avatar_id || null,
          role: r.role || 'member',
          isBot: !!r.is_bot,
          isUser: _buSatirBenMiyim(r.user_id),
          userId: r.user_id || null,
          lastSeen: r.last_seen || null,
          goalsTotal: r.goals_total || 0,
          assistsTotal: r.assists_total || 0,
          matchesPlayed: r.matches_played || 0,
          statsByComp: (r.stats_by_comp && typeof r.stats_by_comp === 'object') ? r.stats_by_comp : {},
          matchRatings: Array.isArray(r.match_ratings) ? r.match_ratings : [],
          avgMatchRating, matchRatingsCount: mrCount,
          seasonYellow:   r.season_yellow   || 0,
          suspendMatches: r.suspend_matches || 0,
          suspendReason:  r.suspend_reason  || null,
          injuryUntil:    _tsMsC(r.injury_until),
          x: sl.x, y: sl.y,
        };
      });
      return players;
}

// Önyükleme: bir kerelik tüm takımları cache'le (ağır, isteğe bağlı)
let _rkFreeUsersCache = []; // takımsız (serbest) gerçek kullanıcılar — sıralama için RAM cache
let _rkFreeUsersLoaded = false;
async function _loadFreeAgentUsers() {
  if (!window.sb) return;
  try {
    const { data, error } = await window.sb.from('players')
      .select('id, user_id, country_code, name, pos, overall, level, avatar, avatar_id, nation, nationality')
      .is('team_name', null)
      .eq('is_bot', false);
    if (error) { console.warn('[freeUsers] hata:', error); return; }
    _rkFreeUsersCache = Array.isArray(data) ? data : [];
    _rkFreeUsersLoaded = true;
    if (typeof invalidateRkPlayerCache === 'function') invalidateRkPlayerCache();
    console.info('[freeUsers] yüklendi:', _rkFreeUsersCache.length, 'takımsız kullanıcı');
  } catch(e) { console.warn('[freeUsers] exception:', e); }
}
async function preloadAllTeamRosters() {
  if (!window.sb) return;
  try {
    const PAGE = 1000;
    let all = [];
    let offset = 0;
    let safety = 0;
    while (safety++ < 50) {
      const { data, error } = await window.sb.from('players')
        .select('id, user_id, country_code, team_name, num, name, pos, pos_group, sub_pos, nationality, nation, level, xp, overall, rating, abilities, role, avatar, avatar_id, gender, is_bot, last_seen, user_team_data, goals_total, assists_total, matches_played, match_ratings, stats_by_comp, season_yellow, suspend_matches, suspend_reason, injury_until')
        // is_bot filtresi yok — gerçek kullanıcılar da yüklenir
        .not('team_name', 'is', null)
        .order('country_code')
        .order('team_name')
        .order('num')
        .range(offset, offset + PAGE - 1);
      if (error) { console.warn('[preloadAllRosters] hata:', error); break; }
      if (!Array.isArray(data) || data.length === 0) break;
      all = all.concat(data);
      offset += data.length;
      if (data.length < PAGE) break;
    }
    // Cache temizle (yeniden yüklüyoruz, çift olmasın)
    for (const k of Object.keys(_teamRosterCache)) delete _teamRosterCache[k];
    // Gruplayıp cache'e yaz — 🆕 parçalı işle: her 800 kayıtta ana iş parçacığına yield (açılış donmasını önler)
    let _proc = 0;
    for (const r of all) {
      const key = r.country_code + ':' + r.team_name;
      if (!_teamRosterCache[key]) _teamRosterCache[key] = [];
      const sl = (typeof SQUAD_SLOTS_15 !== 'undefined' && SQUAD_SLOTS_15[_teamRosterCache[key].length]) || {};
      // Ortalama maç rating'i (match_ratings array'inden hesapla)
      let avgMatchRating = 0;
      let mrCount = 0;
      if (Array.isArray(r.match_ratings)) {
        for (const mr of r.match_ratings) {
          if (mr && typeof mr.rating === 'number') {
            avgMatchRating += mr.rating;
            mrCount++;
          }
        }
        if (mrCount > 0) avgMatchRating = avgMatchRating / mrCount;
      }
      _teamRosterCache[key].push({
        id: r.id,
        userId: r.user_id,
        num: r.num, name: r.name, pos: r.pos, posGroup: r.pos_group, subPos: r.sub_pos,
        rating: r.rating || 10, overall: r.overall || 10,
        level: r.level || 0, xp: r.xp || 0,
        age: 18 + (r.num % 17),
        starter: !!sl.starter,
        abilities: r.abilities,
        nation: r.nation || '🏳️',
        nationality: r.nationality || r.country_code,
        avatar: r.avatar || (r.is_bot ? '🤖' : '👤'),
        avatar_id: r.avatar_id || null,
        role: r.role || 'member',
        isBot: !!r.is_bot,
        isUser: _buSatirBenMiyim(r.user_id),
        lastSeen: r.last_seen || null,
        // Sezon istatistikleri (Edge function maç sonu doldurur)
        goalsTotal: r.goals_total || 0,
        assistsTotal: r.assists_total || 0,
        matchesPlayed: r.matches_played || 0,
        statsByComp: (r.stats_by_comp && typeof r.stats_by_comp === 'object') ? r.stats_by_comp : {},
        matchRatings: Array.isArray(r.match_ratings) ? r.match_ratings : [],
        avgMatchRating: avgMatchRating,
        matchRatingsCount: mrCount,
        seasonYellow: 0, suspendMatches: 0, suspendReason: null, injuryUntil: 0,
        x: sl.x, y: sl.y,
      });
      if ((++_proc % 800) === 0) { await new Promise(res => setTimeout(res, 0)); }
    }
    for (const k of Object.keys(_teamRosterCache)) {
      _teamRosterCache[k].sort((a, b) => a.num - b.num);
    }
    console.info('[preloadAllRosters] yüklendi:', all.length, 'oyuncu /', Object.keys(_teamRosterCache).length, 'takım');
    if (typeof invalidateRkPlayerCache === 'function') invalidateRkPlayerCache(); // taze kadrolar geldi → sıralama tazelensin
  } catch(e) { console.warn('[preloadAllRosters] exception:', e); }
}

function getOrCreateTeamRoster(teamData) {
  // 🆕 Sadece Supabase RAM cache döner. Eski localStorage seed üretimi tamamen silindi.
  // Botlar artık DB'de — fetch arka planda, cache yüklenene kadar boş array.
  const teamName = teamData.name || 'unk';
  const cc = (teamData.countryCode || teamData.cc || 'TR').toUpperCase().slice(0, 2);
  const key = cc + ':' + teamName;
  if (_teamRosterCache[key]) return _teamRosterCache[key];
  // 🆕 ÖNBELLEK BOŞSA: yükle VE bitince ilgili ekranı yeniden çiz.
  //   Eskiden boş dizi dönülüyor, yükleme bitince kimse haber almıyordu →
  //   ziyaret edilen takım ilk açılışta boş görünüyor, ancak ikinci girişte doluyordu.
  if (typeof _loadTeamRosterFromServer === 'function') {
    if (!window._grLoading) window._grLoading = {};
    if (!window._grLoading[key]) {
      window._grLoading[key] = true;
      _loadTeamRosterFromServer(cc, teamName)
        .catch(()=>{})
        .then(() => {
          window._grLoading[key] = false;
          try {
            const v = (typeof _viewingTeam !== 'undefined') ? _viewingTeam : null;
            if (v && v.countryCode === cc && v.teamRef && v.teamRef.name === teamName) {
              if (typeof guestRenderHeader === 'function') guestRenderHeader();
              if (typeof guestRenderRoster === 'function') guestRenderRoster();
              if (typeof guestRenderFacilities === 'function') {
                const fp = document.getElementById('team-facility');
                if (fp && fp.style.display !== 'none') guestRenderFacilities();
              }
            }
          } catch(e) {}
        });
    }
  }
  return [];
}


// 🆕 KRİTİK YARDIMCI: Oyuncu havuzunu template slotlarına POS UYUMLU yerleştir.
// Sıralı index ('botPlayers[i]') yanlış sonuç verir — en yüksek overall'lı stoper
// kaleci slotuna gidebilir. Bu fonksiyon: tam pos eşleşmesi → aynı pos grubu →
// en yüksek overall (kaleci hariç). Aynı oyuncu iki kez kullanılmaz.
function _placeRosterToTemplate(templatePlayers, rosterPool) {
  if (!Array.isArray(templatePlayers) || !Array.isArray(rosterPool)) return [];
  const POS_GRP = (typeof POS_GROUP !== 'undefined') ? POS_GROUP : {};
  const used = new Set();
  const result = new Array(templatePlayers.length).fill(null);

  // Aşama 1: tam pos eşleşmesi
  templatePlayers.forEach((tp, i) => {
    if (result[i]) return;
    const exactIdx = rosterPool.findIndex((p, idx) => !used.has(idx) && p && p.pos === tp.pos);
    if (exactIdx !== -1) {
      result[i] = rosterPool[exactIdx];
      used.add(exactIdx);
    }
  });

  // Aşama 2: aynı pos grubu (KL slotu HARİÇ — kaleciye sadece kaleci konur)
  templatePlayers.forEach((tp, i) => {
    if (result[i]) return;
    const tpGrp = POS_GRP[tp.pos];
    if (!tpGrp || tpGrp === 'GK') return; // kale slotu sıkı tutulur
    const grpIdx = rosterPool.findIndex((p, idx) =>
      !used.has(idx) && p && POS_GRP[p.pos] === tpGrp
    );
    if (grpIdx !== -1) {
      result[i] = rosterPool[grpIdx];
      used.add(grpIdx);
    }
  });

  // Aşama 3: kalan slotlara en uygun oyuncu (KL slotu kaldıysa havuzdaki en zayıf)
  templatePlayers.forEach((tp, i) => {
    if (result[i]) return;
    const isGKSlot = (POS_GRP[tp.pos] === 'GK');
    if (isGKSlot) {
      // Acil: KL boş — havuzda kaleci yok demektir, en zayıf oyuncuyu koy
      let weakestIdx = -1, weakestOvr = 999;
      rosterPool.forEach((p, idx) => {
        if (used.has(idx) || !p) return;
        const o = p.overall || p.rating || 70;
        if (o < weakestOvr) { weakestOvr = o; weakestIdx = idx; }
      });
      if (weakestIdx !== -1) {
        result[i] = rosterPool[weakestIdx];
        used.add(weakestIdx);
      }
    } else {
      // En yüksek overall'lı kalan oyuncu
      let bestIdx = -1, bestOvr = -1;
      rosterPool.forEach((p, idx) => {
        if (used.has(idx) || !p) return;
        const o = p.overall || p.rating || 0;
        if (o > bestOvr) { bestOvr = o; bestIdx = idx; }
      });
      if (bestIdx !== -1) {
        result[i] = rosterPool[bestIdx];
        used.add(bestIdx);
      }
    }
  });

  return result;
}

// 🆕 KULLANICI MAÇI: activePitchPlayers'tan motor formatında 11 oyuncu üretir.
// Diziliş eksikse null döner. Bu fonksiyon kullanıcı takımı için TEK kaynak —
// generateMatchSquad'ın isUser tespitine bağımlı kalmaz.
function _buildUserMatchSquadFromCurrent() {
  if (typeof activePitchPlayers === 'undefined') return null;
  if (!Array.isArray(activePitchPlayers) || activePitchPlayers.length !== 11) return null;

  const POS_GRP = (typeof POS_GROUP !== 'undefined') ? POS_GROUP : {};
  return activePitchPlayers.map((entry, i) => {
    const p = entry.player || {};
    const slotPos = entry.pos || p.pos || 'OS';
    const slotPosGroup = POS_GRP[slotPos] || 'MID';
    const finalRating = (typeof getPlayerEffectiveRating === 'function')
      ? getPlayerEffectiveRating(p, slotPosGroup)
      : (p.overall || p.rating || 70);
    return {
      num: p.num || (i + 1),
      name: p.name || ('Player ' + (i + 1)),
      pos: slotPos,                         // OYNADIĞI mevki (slot)
      rating: finalRating,                  // mevki penalty'li
      level: p.level || 0,
      xp: p.xp || 0,
      x: typeof entry.x === 'number' ? entry.x : 50,
      y: typeof entry.y === 'number' ? entry.y : 50,
      isUser: !!p.isUser || (p.role === 'user'),
      role: p.role || ''
    };
  });
}

// 🆕 İzleyici modu: sunucu (match_state) lineup'ından squad obje üret.
// Uydurma kadro üretmek yerine Edge'in yazdığı gerçek lineup'ı doğrudan kullanır.
// serverLineup yapısı: { players: [{num,name,pos,...}], bench: [...], name, countryCode }
function _buildSquadFromServerLineup(teamData, serverLineup, isHome) {
  const lineupPlayers = Array.isArray(serverLineup && serverLineup.players) ? serverLineup.players : [];
  // 587 — kendisi (oturumdaki kullanıcı) işaretlenir; alt mevki / oynadığı yuva / kimlik taşınır
  const _benId = (typeof authUser !== 'undefined' && authUser && authUser.id) ? authUser.id : null;
  const _ben = (p) => !!(_benId && p && p.userId && p.userId === _benId);
  const players = lineupPlayers.map((p, i) => ({
    num:    p.num || (i + 1),
    name:   p.name || ('Player ' + (i + 1)),
    pos:    p.pos || 'MID',
    posGroup: p.posGroup || null,
    subPos: p.subPos || null, slotPos: p.slotPos || null, slotIdx: (typeof p.slotIdx === 'number') ? p.slotIdx : null,
    id: p.id || null, userId: p.userId || null,
    rating: p.rating || p.overall || 60,
    level:  p.level || 0,
    overall: p.overall || p.rating || 60,
    abilities: p.abilities || null,
    matchRating: typeof p.matchRating === 'number' ? p.matchRating : undefined,
    isUser: _ben(p), role: _ben(p) ? 'user' : '',
    isBot: !!p.isBot,
    x: p.x, y: p.y,
  }));
  // 573 — yedekler de (milli maçta T.D. değişikliği için; izleyicide sunucu değişikliklerini eşlemek için)
  const benchPlayers = (Array.isArray(serverLineup && serverLineup.bench) ? serverLineup.bench : []).map((p, i) => ({
    num:    p.num || (20 + i),
    name:   p.name || ('Yedek ' + (i + 1)),
    pos:    p.pos || 'MID',
    posGroup: p.posGroup || null, subPos: p.subPos || null,
    id: p.id || null, userId: p.userId || null,
    rating: p.rating || p.overall || 60,
    level:  p.level || 0,
    overall: p.overall || p.rating || 60,
    abilities: p.abilities || null,
    isUser: _ben(p), role: _ben(p) ? 'user' : '',
    isBot: !!p.isBot,
  }));
  return {
    id:     isHome ? 'home' : 'away',
    name:   teamData.name,
    short:  teamData.short || (teamData.name || '').slice(0, 3).toUpperCase(),
    rating: (typeof calcTeamPowerAverage === 'function') ? calcTeamPowerAverage(players) : 60,
    players,
    benchPlayers,
  };
}

function generateMatchSquad(teamData, isHome, seed) {
  const template = isHome ? HOME_TEAM : AWAY_TEAM;

  // 🆕 Takım rating'i = oyuncuların ortalaması (DİNAMİK, statik değil).
  // İlk başta tüm oyuncular 10 → tüm takımlar ~10 (eşit). Oyuncular geliştikçe yükselir.
  // Seçilen kadronun (ROSTER_DATA / botPlayers) ortalaması bu fonksiyonun aşağısında
  // hesaplanır. Şimdilik fallback değer kullan (özel test takımları için):
  const teamRating = (teamData.rating && teamData.rating > 15) ? teamData.rating : 10;

  // Bu kullanıcının takımıysa — ROSTER_DATA + activePitchPlayers (diziliş) kullan
  const isUserTeam = !!(teamData.isUser
    || (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName === teamData.name));
  // Test modunda: ev sahibi takımı kullanıcı takımı olarak ele al
  const useUserData = isUserTeam || (isHome && typeof MS !== 'undefined' && MS && MS._testForceCaptain);

  if(useUserData && typeof ROSTER_DATA !== 'undefined' && ROSTER_DATA.length >= 11) {

    // 🆕 Eğer kullanıcı diziliş kısmından 11'i belirlediyse onu kullan
    if (typeof activePitchPlayers !== 'undefined' && Array.isArray(activePitchPlayers) && activePitchPlayers.length === 11) {
      const players = activePitchPlayers.map((entry, i) => {
        const p = entry.player || {};
        const fullName = p.name || ('Player ' + (i + 1));
        // 🆕 Oyuncunun OYNATILDIĞI mevkinin yetenek ortalaması kullanılır.
        // Ana mevki dışına konulursa düşük performans (out-of-position penalty doğal).
        const playedPosGroup = (typeof POS_GROUP !== 'undefined' && POS_GROUP[entry.pos]) || 'MID';
        const finalRating = (typeof getPlayerEffectiveRating === 'function')
          ? getPlayerEffectiveRating(p, playedPosGroup)
          : (() => {
              const baseRating = p.overall || p.rating || teamRating;
              const levelBonus = Math.min(20, (p.level || 0) * 0.8);
              return Math.max(1, Math.min(99, Math.round(baseRating + levelBonus)));
            })();
        return {
          num: p.num || (i + 1),
          name: (fullName.length > 14) ? fullName.split(' ').map((s, j) => j === 0 ? s.charAt(0) + '.' : s).join(' ') : fullName,
          pos: entry.pos || 'OS',
          rating: finalRating,
          level: p.level || 0,
          xp: p.xp || 0,
          x: entry.x, y: entry.y,
          isUser: !!p.isUser || (p.role === 'user'),
        };
      });
      return {
        id: isHome ? 'home' : 'away',
        name: teamData.name,
        short: teamData.short || teamData.name.slice(0, 3).toUpperCase(),
        rating: (typeof calcTeamPowerAverage === 'function') ? calcTeamPowerAverage(players) : teamRating,
        players,
      };
    }

    // Fallback: diziliş yapılmamışsa POS UYUMLU yerleştirme (sıralı index DEĞİL)
    const sortedRoster = [...ROSTER_DATA]
      .sort((a, b) => (b.overall || b.rating || 0) - (a.overall || a.rating || 0));
    const placed = _placeRosterToTemplate(template.players, sortedRoster);

    const players = template.players.map((tp, i) => {
      const p = placed[i] || sortedRoster[i];
      if(!p) return { ...tp };
      // Template'in pos'una göre yetenek (out-of-position penalty doğal)
      const playedPosGroup = (typeof POS_GROUP !== 'undefined' && POS_GROUP[tp.pos]) || 'MID';
      const finalRating = (typeof getPlayerEffectiveRating === 'function')
        ? getPlayerEffectiveRating(p, playedPosGroup)
        : (() => {
            const baseRating = p.overall || p.rating || tp.rating || 70;
            const levelBonus = Math.min(20, (p.level || 0) * 0.8);
            return Math.max(1, Math.min(99, Math.round(baseRating + levelBonus)));
          })();
      return {
        num: p.num || tp.num,
        name: (p.name && p.name.length > 14) ? p.name.split(' ').map((s,j)=>j===0?s.charAt(0)+'.':s).join(' ') : (p.name || tp.name),
        pos: tp.pos,
        rating: finalRating,
        level: p.level || 0,
        xp: p.xp || 0,
        x: tp.x, y: tp.y,
        isUser: !!p.isUser || (p.role === 'user'),
      };
    });
    return {
      id: isHome ? 'home' : 'away',
      name: teamData.name,
      short: teamData.short || teamData.name.slice(0, 3).toUpperCase(),
      rating: (typeof calcTeamPowerAverage === 'function') ? calcTeamPowerAverage(players) : teamRating,
      players,
    };
  }

  // ════════════════════════════════════════════════════
  // teams DB / BOT TAKIMI: Kalıcı kadro sistemi
  // getOrCreateTeamRoster → localStorage cache → her maçta aynı 11
  // 🆕 POS UYUMLU YERLEŞTİRME: template slot pos'una göre eşleşen oyuncu seç
  // (sıralı botPlayers[i] yanlış — stoperi kaleciye koyabiliyordu)
  // ════════════════════════════════════════════════════
  // 🆕 529 — Hazır kadro verilebilir (milli takım maçlarında kulüp kadrosu yok)
  let botPlayers = (Array.isArray(teamData._roster) && teamData._roster.length)
    ? teamData._roster.slice()
    : getOrCreateTeamRoster(teamData);
  // 🆕 529 — Kadro bulunamazsa (ör. takım DB'de yok) maç ekranı ÇÖKMESİN:
  //   şablona göre yer tutucu oyuncular üretilir.
  if (!Array.isArray(botPlayers) || !botPlayers.length) {
    const _tr = Number(teamRating) || 70;
    botPlayers = template.players.map((tp, i) => ({
      num: i + 1, name: (teamData.short || String(teamData.name || '').slice(0, 3).toUpperCase()) + ' ' + (i + 1),
      pos: tp.pos, overall: _tr, rating: _tr, level: 0
    }));
  }
  const placed = _placeRosterToTemplate(template.players, botPlayers);

  const players = template.players.map((tp, i) => {
    const bp = placed[i] || botPlayers[i] || botPlayers[0];
    if (!bp) return { num: i + 1, name: '—', pos: tp.pos, rating: Number(teamRating) || 70, level: 0, x: tp.x, y: tp.y };
    const playedPosGroup = (typeof POS_GROUP !== 'undefined' && POS_GROUP[tp.pos]) || 'MID';
    const effRating = (typeof getPlayerEffectiveRating === 'function')
      ? getPlayerEffectiveRating(bp, playedPosGroup)
      : (bp.rating || bp.overall || 10);
    return {
      num:    bp.num,
      name:   bp.name,
      pos:    tp.pos,       // SLOT pos (oynadığı mevki)
      rating: effRating,    // mevki kuralı uygulanmış
      level:  bp.level || 0,
      x:      tp.x,
      y:      tp.y,
    };
  });

  return {
    id:     isHome ? 'home' : 'away',
    name:   teamData.name,
    short:  teamData.short || teamData.name.slice(0, 3).toUpperCase(),
    rating: (typeof calcTeamPowerAverage === 'function') ? calcTeamPowerAverage(players) : teamRating,
    players,
  };
}




