function rnd(a,b){return Math.floor(Math.random()*(b-a+1))+a}
function pick(arr){return arr[Math.floor(Math.random()*arr.length)]}
function sleep(ms){return new Promise(r=>setTimeout(r,ms))}

// 🆕 LocalStorage quota-aware setItem
// Aşamalı temizlik + yazılan veri büyükse upfront kırpma
// 🆕 Tek maç verisi içeriğini de kırp: events, playerStats, stats çok büyürse çıkar
function _trimMatchEntry(entry) {
  if (!entry || typeof entry !== 'object') return entry;
  const out = { ...entry };
  // En büyük alanları çıkar — sadece skor + meta tutulur
  // events (her dakika), playerStats (oyuncu bazlı), stats (genel istatistik) — bunlar UI'da yeniden simüle edilir
  if (Array.isArray(out.events) && out.events.length > 5) {
    // En önemli olayları tut: goller + kırmızı kartlar (max 5 event)
    out.events = out.events
      .filter(e => e && (e.type === 'goal' || e.type === 'card' || e.type === 'redCard' || e.type === 'yellowCard'))
      .slice(0, 5);
  }
  if (out.playerStats) delete out.playerStats; // her zaman çıkar — çok büyük
  if (out.stats) delete out.stats; // genel istatistikler de UI'da yeniden hesaplanabilir
  if (Array.isArray(out.timeline)) delete out.timeline; // varsa zaman çizelgesi sil
  return out;
}

function _safeSetItem(key, value) {
  try {
    localStorage.setItem(key, value);
    return true;
  } catch(e) {
    if (!e || !(e.name === 'QuotaExceededError' || e.code === 22 || e.code === 1014)) {
      console.warn('[Storage] setItem hatası:', e);
    }
    return false;
  }
}

// 🆕 Manuel storage temizleme — DEV/debug için
window.cftStorageInfo = function() {
  const sizes = [];
  let total = 0;
  for (let i = 0; i < localStorage.length; i++) {
    const k = localStorage.key(i);
    const v = localStorage.getItem(k);
    const kb = Math.round((v || '').length / 1024);
    sizes.push({ key: k, kb });
    total += kb;
  }
  sizes.sort((a, b) => b.kb - a.kb);
  console.table(sizes);
  console.log(`Toplam: ${total} KB / ${(total/1024).toFixed(1)} MB`);
  return sizes;
};

// 🆕 Sayfa açılışında mevcut storage'ı otomatik trim et (eski şişmiş cache temizlenir)
// 🆕 Tüm cft_* keys arasından gereksiz/büyük cache'leri temizle
// (cft_match_results özel trim'den ÖNCE çalışır — daha çok yer açar)
// ⚠️ KULLANICI VERİSİ KORUNUR: cft_chat_*, cft_dm_*, cft_inbox, cft_market, cft_equipment ASLA silinmez
//    SADECE includeOldChats=true ise 30 GÜN+ eski sohbetler silinir (acil durum son çaresi)
function _cftCleanupOtherCaches(includeOldChats) {
  const stats = { freed: 0, removed: [] };
  try {
    // 1) cft_r3_* (bot takım roster cache'leri) — SEED'Lİ deterministik üretim,
    //    silindiğinde aynı seed ile AYNI oyuncular yeniden üretilir → tamamen güvenli
    const rosterKeys = [];
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k && k.startsWith('cft_r3_')) rosterKeys.push(k);
    }
    rosterKeys.forEach(k => {
      try {
        const v = localStorage.getItem(k);
        if (v) stats.freed += v.length;
        localStorage.removeItem(k);
        stats.removed.push(k);
      } catch(_) {}
    });

    // 2) ⚠️ Sohbet temizliği SADECE acil durumda (includeOldChats=true) — 30 GÜN+ eski
    if (includeOldChats === true) {
      const THIRTY_DAYS = 30 * 24 * 60 * 60 * 1000;
      const now = Date.now();
      const chatKeys = [];
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (k && (k.startsWith('cft_chat_') || k.startsWith('cft_dm_'))) chatKeys.push(k);
      }
      chatKeys.forEach(k => {
        try {
          const v = localStorage.getItem(k);
          if (!v) return;
          const data = JSON.parse(v);
          let lastTs = 0;
          if (Array.isArray(data)) {
            data.forEach(m => { if (m && m.ts && m.ts > lastTs) lastTs = m.ts; });
          } else if (data && data.thread && Array.isArray(data.thread)) {
            data.thread.forEach(m => { if (m && m.ts && m.ts > lastTs) lastTs = m.ts; });
          }
          if (lastTs && (now - lastTs) > THIRTY_DAYS) {
            stats.freed += v.length;
            localStorage.removeItem(k);
            stats.removed.push(k);
          }
        } catch(_) {}
      });
    }

    // 3) İçerik cache'leri — UI yenilenince tekrar yüklenir, kullanıcı verisi YOK
    const oldPrefixes = ['cft_meme_', 'cft_event_cache_', 'cft_news_cache_'];
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (!k) continue;
      if (oldPrefixes.some(p => k.startsWith(p))) {
        try {
          const v = localStorage.getItem(k);
          if (v) stats.freed += v.length;
          localStorage.removeItem(k);
          stats.removed.push(k);
        } catch(_) {}
      }
    }
  } catch(_) {}
  return stats;
}

// 🆕 Tüm localStorage doluluğunu ölç (~)
function _cftStorageUsageKB() {
  try {
    let total = 0;
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (!k) continue;
      const v = localStorage.getItem(k);
      total += (k.length + (v ? v.length : 0));
    }
    return Math.round(total / 1024);
  } catch(_) { return 0; }
}

function _cftStartupStorageCleanup() {
  // cft_match_results Supabase'e taşındı — localStorage trim YOK.
  // Sadece genel cache temizliği (sohbetlere dokunmaz).
  try {
    const usageKB = _cftStorageUsageKB();
    if (usageKB > 4000) _cftCleanupOtherCaches(false);
  } catch(_) {}
}
// Sayfa yüklenince hemen çalıştır
_cftStartupStorageCleanup();

// match state
let MS={running:false,minute:0,scoreH:0,scoreA:0,speed:1,script:null,finished:false};

// current match teams (dynamic, set when opening)
let curHome=HOME_TEAM, curAway=AWAY_TEAM;


// ══ KART + SAKATLIK SİSTEMİ ══
// Sezon kuralları:
//   • 4 sarı kart birikimi → 1 maç ceza, sezon sayacı sıfırlanır
//   • 1 kırmızı kart → 1 maç ceza
//   • Sakatlık süresi: 50 saat; Sağlık Merkezi her seviyede %5 kısaltır (Sv1 50s … Sv10 27,5s)
// Veri alanları (her oyuncu için, default 0/null):
//   p.seasonYellow      — sezondaki birikmiş sarı kart sayısı (0-3)
//   p.suspendMatches    — kalan ceza maç sayısı (0+)
//   p.suspendReason     — 'yellow' | 'red' | null
//   p.injuryUntil       — sakatlık bitiş timestamp (ms), 0 = sakat değil

// Sağlık Merkezi seviyesinden sakatlık iyileşme çarpanı.
// Sv 1 → 1.00 (orijinal süre), Sv 2 → 0.95, ..., Sv 10 → 0.55 (%45 indirim).
// Bot takımların kendi cihazlarında simüle edilmediği için bu sadece kullanıcı takımı için anlamlı.
function getMedicalRecoveryMultiplier() {
  const lvl = (typeof FAC_LEVELS !== 'undefined' && FAC_LEVELS && FAC_LEVELS.medical)
    ? FAC_LEVELS.medical : 1;
  return Math.max(0.5, 1 - (lvl - 1) * 0.05);
}

// (511) injury_until kolonu sayı (ms) ya da ISO tarih metni olabilir — ikisini de oku
function _tsMsC(v) {
  if (v === null || v === undefined || v === '') return 0;
  if (typeof v === 'number') return isFinite(v) ? v : 0;
  const n = Number(v); if (isFinite(n)) return n;
  const d = Date.parse(String(v)); return isFinite(d) ? d : 0;
}
// (511) Kadro/diziliş uygunluğu — sakat hiçbir maçta, cezalı resmi maçta oynayamaz.
//   Diziliş lig/turnuva maçları için kaydedildiğinden ikisi de ilk 11'e alınamaz.
function _kadroUygunsuzlukMetni(p) {
  if (!p) return null;
  if (isPlayerInjured(p)) {
    const h = getInjuryRemainingHours(p);
    return '🚑 ' + (p.name || 'Oyuncu') + ' sakat — ' + (h >= 24 ? Math.max(1, Math.round(h / 24)) + ' gün' : h + ' saat') + ' sonra oynayabilir';
  }
  if (isPlayerSuspended(p)) {
    const n = p.suspendMatches || 0;
    return '🟥 ' + (p.name || 'Oyuncu') + ' cezalı — ' + n + ' resmi maç oynayamaz';
  }
  return null;
}
function _kadroUygunMu(p) {
  const m = _kadroUygunsuzlukMetni(p);
  if (m) { try { if (typeof showToast === 'function') showToast(m); else if (typeof showSwapToast === 'function') showSwapToast(m); } catch(e) {} return false; }
  return true;
}
function isPlayerSuspended(p) { return (p && (p.suspendMatches || 0) > 0); }
function isPlayerInjured(p)   { return !!(p && _tsMsC(p.injuryUntil) > Date.now()); }

// 🆕 Bu oyuncu bu maçta oynayabilir mi? (maç tipi duyarlı)
//   isOfficial=true (lig/turnuva): sakat veya cezalı olmamalı
//   isOfficial=false (hazırlık/milli takım): SADECE sakat olmamalı
//     → cezalı oyuncu hazırlık ve milli takım maçında oynayabilir
function isPlayerEligibleForMatch(p, isOfficial) {
  if (!p) return false;
  if (isPlayerInjured(p)) return false;  // sakat hiçbir maçta oynayamaz
  if (isOfficial && isPlayerSuspended(p)) return false;  // cezalı sadece resmi maçta yok
  return true;
}

// 🆕 Maç tipi tespiti — MS objesinden veya parametre olarak verilen referansa göre
//   true = resmi maç (lig, kupa, turnuva), false = hazırlık veya milli takım
function isOfficialMatchContext(ms) {
  ms = ms || (typeof MS !== 'undefined' ? MS : null);
  if (!ms) return true;  // bilinmiyorsa varsayılan: resmi
  if (ms._isFriendly === true) return false;
  if (ms._isNationalTeam === true) return false;
  if (ms.tournament_key === 'friendly') return false;
  if (ms.tournament_key === 'enc') return false;
  if (ms._fixtureRef && (ms._fixtureRef.tournament_key === 'enc')) return false;
  return true;
}

// (512) OYUN KURALI — her sakatlık 50 gerçek saat; Sağlık Merkezi her seviyede %5 kısaltır.
//   Sunucudaki karşılığı: edge/tick-matches _sakatlikSaat(). İkisi aynı kalmalı.
const SAKATLIK_TABAN_SAAT = 50;
function _sakatlikSureSaat(medLvl) {
  const lvl = Math.max(1, Math.min(10, Number(medLvl) || 1));
  return Math.round(SAKATLIK_TABAN_SAAT * (1 - (lvl - 1) * 0.05) * 10) / 10;
}
// Saat (ondalık) → "42s 30dk" / "42h 30m" / "42 Std. 30 Min." — oyun dilinde
function _sureSaatDk(saat) {
  const topDk = Math.max(0, Math.round(Number(saat) * 60));
  const s = Math.floor(topDk / 60), d = topDk % 60;
  const dil = (typeof i18nLang === 'function') ? i18nLang() : 'tr';
  if (dil === 'tr') return s + 's ' + String(d).padStart(2, '0') + 'dk';
  if (dil === 'de') return s + ' Std. ' + String(d).padStart(2, '0') + ' Min.';
  if (dil === 'es' || dil === 'pt' || dil === 'it' || dil === 'fr') return s + ' h ' + String(d).padStart(2, '0') + ' min';
  if (dil === 'ru') return s + ' ч ' + String(d).padStart(2, '0') + ' мин';
  return s + 'h ' + String(d).padStart(2, '0') + 'm';
}
// Kalan süre metni (ms'den) — geri sayım
function _sakatlikKalanMetin(bitisMs) {
  const kalan = (Number(bitisMs) || 0) - Date.now();
  if (kalan <= 0) return null;
  return _sureSaatDk(Math.ceil(kalan / 60000) / 60);
}
// Canlı geri sayım etiketi — her 30 sn'de tüm .inj-cd öğeleri güncellenir
function _sakatlikSayacHtml(p) {
  const b = _tsMsC(p && p.injuryUntil);
  const t = _sakatlikKalanMetin(b);
  if (!t) return '';
  return '<span class="inj-cd" data-noi18n data-inj-bitis="' + b + '">' + t + '</span>';
}
function _sakatlikSayaclariniGuncelle() {
  try {
    document.querySelectorAll('.inj-cd[data-inj-bitis]').forEach(el => {
      const t = _sakatlikKalanMetin(el.getAttribute('data-inj-bitis'));
      if (t) { if (el.textContent !== t) el.textContent = t; }
      else {
        el.textContent = '✓';
        const kap = el.closest('.pr-status-inj,.pmk-sakat,.pl-inj-strip');
        if (kap) kap.classList.add('iyilesti');
      }
    });
  } catch(e) {}
}
if (!window._sakatlikSayacTimer) {
  window._sakatlikSayacTimer = setInterval(() => { if (!document.hidden) _sakatlikSayaclariniGuncelle(); }, 30000);
}
// Sağlık Merkezi bağlantı satırı (yalnızca kendi takımının tesisi biliniyor)
function _sakatlikTesisMetni(p, takimAdi) {
  const dil = (typeof i18nLang === 'function') ? i18nLang() : 'tr';
  const benim = (typeof _userTeam !== 'undefined' && _userTeam && takimAdi && _userTeam.teamName === takimAdi);
  if (benim) {
    const lvl = Math.max(1, Math.min(10, Number((typeof FAC_LEVELS !== 'undefined' && FAC_LEVELS && FAC_LEVELS.medical) || 1)));
    const sure = _sureSaatDk(_sakatlikSureSaat(lvl)), ind = (lvl - 1) * 5;
    if (dil === 'tr') return '🏥 Sağlık Merkezi Sv' + lvl + ' · sakatlık süresi ' + sure + (ind ? ' (−%' + ind + ')' : '');
    if (dil === 'de') return '🏥 Medizinisches Zentrum St. ' + lvl + ' · Ausfallzeit ' + sure + (ind ? ' (−' + ind + '%)' : '');
    if (dil === 'es') return '🏥 Centro médico Nv ' + lvl + ' · tiempo de baja ' + sure + (ind ? ' (−' + ind + '%)' : '');
    if (dil === 'pt') return '🏥 Centro médico Nv ' + lvl + ' · tempo de lesão ' + sure + (ind ? ' (−' + ind + '%)' : '');
    if (dil === 'it') return '🏥 Centro medico Liv ' + lvl + ' · tempo di recupero ' + sure + (ind ? ' (−' + ind + '%)' : '');
    if (dil === 'fr') return '🏥 Centre médical Niv ' + lvl + ' · indisponibilité ' + sure + (ind ? ' (−' + ind + ' %)' : '');
    if (dil === 'ru') return '🏥 Медицинский центр ур. ' + lvl + ' · срок травмы ' + sure + (ind ? ' (−' + ind + '%)' : '');
    return '🏥 Medical Centre Lv ' + lvl + ' · injury time ' + sure + (ind ? ' (−' + ind + '%)' : '');
  }
  if (dil === 'tr') return '🏥 Her sakatlık 50 saat · takımın Sağlık Merkezi her seviyede %5 kısaltır';
  if (dil === 'de') return '🏥 Jede Verletzung 50 Std. · das Medizinische Zentrum verkürzt sie pro Stufe um 5%';
  if (dil === 'es') return '🏥 Cada lesión dura 50 h · el Centro médico del equipo la reduce un 5% por nivel';
  if (dil === 'pt') return '🏥 Cada lesão dura 50 h · o Centro médico do time reduz 5% por nível';
  if (dil === 'it') return '🏥 Ogni infortunio dura 50 h · il Centro medico della squadra lo riduce del 5% per livello';
  if (dil === 'fr') return '🏥 Chaque blessure dure 50 h · le Centre médical de l\'équipe la réduit de 5 % par niveau';
  if (dil === 'ru') return '🏥 Каждая травма длится 50 ч · медицинский центр команды сокращает её на 5% за уровень';
  return '🏥 Every injury lasts 50 h · the team Medical Centre cuts 5% per level';
}

// ═══════════════════════════════════════════════════════════════════
// 🔔 KADRO DURUM BİLDİRİMİ (522) — satır sonundaki zil + ayrıntı modalı
//   İsmin altında sadece rol çipleri kalır; sarı kart / ceza / sakatlık /
//   yorgunluk / moral / transfer listesi bu düğmede toplanır.
//   Kullanıldığı yerler: Takımım (renderRoster), ziyaretçi kadrosu
//   (guestRenderRoster), Milli Takım kadrosu (ntRenderRoster).
// ═══════════════════════════════════════════════════════════════════
var _kdKayit = {};
const _KD_SIRA = ['kirmizi', 'turuncu', 'sari', 'mavi', 'yesil'];
function _kdEsc(s) { return String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c]); }
function _kdBedelStr(eur) {
  const b = Number(eur) || 0;
  return b >= 1000000 ? (b / 1000000).toFixed(1) + 'M €' : b > 0 ? Math.round(b / 1000) + 'K €' : '';
}
// Oyuncunun satıştaki ilanı (takimAdi = satıcı takım)
function _kdTfIlan(p, takimAdi) {
  try {
    if (!p || !takimAdi || typeof getTfList !== 'function') return null;
    const l = getTfList() || [];
    return l.find(it => it && !it.sold && it.sellerTeam === takimAdi && (
      (it.playerNum != null && p.num != null && it.playerNum === p.num) || it.playerId === p.name
    )) || null;
  } catch (e) { return null; }
}
// Durum listesi — her öğe: {t:renk, ic, b:başlık, s:açıklama, s2?, sg:değer html, bar?, barRenk?}
function _kdDurumlar(p, takimAdi, opt) {
  opt = opt || {};
  const d = [];
  if (!p) return d;
  const dil = (typeof i18nLang === 'function') ? i18nLang() : 'tr';
  const yc = p.seasonYellow || 0;
  const susp = p.suspendMatches || 0;
  const sakat = (typeof isPlayerInjured === 'function') && isPlayerInjured(p);
  if (sakat) {
    d.push({ t:'kirmizi', ic:'🚑', b:'Sakat', s:'',
      s2: (typeof _sakatlikTesisMetni === 'function') ? _sakatlikTesisMetni(p, takimAdi) : '',
      sg: (typeof _sakatlikSayacHtml === 'function') ? _sakatlikSayacHtml(p) : '' });
  }
  if (susp > 0) {
    const kir = p.suspendReason === 'red';
    d.push({ t:'kirmizi', ic: kir ? '🟥' : '🟨', b:'Cezalı',
      s: kir ? 'Kırmızı kart cezası · resmi maçlarda oynayamaz' : '4 sarı kart cezası · resmi maçlarda oynayamaz',
      sg:'<span data-noi18n>' + (dil === 'de' ? susp + (susp === 1 ? ' Spiel' : ' Spiele')
        : dil === 'es' ? susp + (susp === 1 ? ' partido' : ' partidos')
        : dil === 'pt' ? susp + (susp === 1 ? ' partida' : ' partidas')
        : dil === 'it' ? susp + (susp === 1 ? ' partita' : ' partite')
        : dil === 'fr' ? susp + (susp === 1 ? ' match' : ' matchs')
        : dil === 'ru' ? susp + ((susp % 10 === 1 && susp % 100 !== 11) ? ' матч' : (susp % 10 >= 2 && susp % 10 <= 4 && (susp % 100 < 12 || susp % 100 > 14)) ? ' матча' : ' матчей')
        : dil === 'tr' ? susp + ' maç' : susp + (susp === 1 ? ' match' : ' matches')) + '</span>' });
  }
  if (yc > 0 && susp === 0) {
    d.push({ t:'sari', ic:'🟨', b:'Sarı kart', s:'Sezon birikimi · 4. sarıda 1 maç ceza',
      sg:'<span data-noi18n>' + yc + '/4</span>', bar: Math.min(100, yc * 25), barRenk:'#ffca28' });
  }
  const st = p.stamina;
  if (typeof st === 'number' && typeof STAMINA_WARNING !== 'undefined' && st < STAMINA_WARNING) {
    const s = Math.max(0, Math.round(st));
    d.push({ t:'turuncu', ic:'🥵', b:'Yorgunluk',
      s: (typeof staminaLabel === 'function' ? staminaLabel(s) : '') ,
      s2:'Kondisyon düşük · dinlenmesi gerekiyor',
      sg:'<span data-noi18n>' + (dil === 'tr' ? '%' + s : s + '%') + '</span>', bar:s, barRenk: s < 30 ? '#ef5350' : '#ff9800' });
  }
  const mor = (typeof p.morale === 'number') ? p.morale : 70;
  if (mor < 40) {
    d.push({ t:'turuncu', ic:'😞', b:'Düşük moral', s:'Maç performansı düşebilir',
      sg:'<span data-noi18n>' + Math.round(mor) + '/100</span>', bar: Math.max(0, mor), barRenk:'#ff9800' });
  } else if (mor >= 90) {
    d.push({ t:'yesil', ic:'🔥', b:'Yüksek moral', s:'Formunun zirvesinde',
      sg:'<span data-noi18n>' + Math.round(mor) + '/100</span>', bar: Math.min(100, mor), barRenk:'#46d17a' });
  }
  if (!opt.tfYok) {
    const ilan = _kdTfIlan(p, takimAdi);
    if (ilan) {
      const bs = _kdBedelStr(ilan.feeEur);
      d.push({ t:'mavi', ic:'🏷️', b:'Transfer listesinde', s:'Satış ilanı aktif',
        sg: bs ? '<span data-noi18n>' + bs + '</span>' : '' });
    }
  }
  return d.sort((a, b) => _KD_SIRA.indexOf(a.t) - _KD_SIRA.indexOf(b.t));
}
// Satır sonu düğmesi — anahtar ile kayıt tutulur, modal açılınca taze hesaplanır
function _kdDugmeHtml(anahtar, p, takimAdi, opt) {
  _kdKayit[anahtar] = { p, takimAdi, opt: opt || {} };
  const d = _kdDurumlar(p, takimAdi, opt);
  if (!d.length) return '<span class="kd-btn bos" aria-hidden="true">🔔</span>';
  const e = d[0].t;
  const k = String(anahtar).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
  return '<button type="button" class="kd-btn s-' + e + '" onclick="event.stopPropagation();kdDurumAc(\'' + k + '\')" title="Durum bildirimleri" aria-label="Durum bildirimleri">'
    + (e === 'kirmizi' ? '⚠️' : '🔔') + '<span class="kd-n" data-noi18n>' + d.length + '</span></button>';
}
// İsmin altındaki rol çipleri satırı
function _kdRolSatiri(html) { return html && String(html).trim() ? '<div class="futc-roller">' + html + '</div>' : ''; }
function kdDurumAc(anahtar) {
  const k = _kdKayit[anahtar];
  if (!k || !k.p) return;
  const p = k.p;
  const d = _kdDurumlar(p, k.takimAdi, k.opt);
  let ov = document.getElementById('kdOv');
  if (!ov) {
    ov = document.createElement('div');
    ov.id = 'kdOv';
    ov.className = 'kd-ov';
    ov.addEventListener('click', ev => { if (ev.target === ov) kdDurumKapat(); });
    document.body.appendChild(ov);
  }
  let av = p.avatar || (p.isBot ? '🤖' : '⭐');
  try {
    if ((p.role === 'user' || p.isUser) && typeof authUser !== 'undefined' && authUser && authUser.avatarId && typeof getAvatarEmoji === 'function') av = getAvatarEmoji(authUser.avatarId, p.pos);
    else if (!p.isBot && p.avatar_id && typeof getAvatarEmoji === 'function') av = getAvatarEmoji(p.avatar_id, p.pos);
  } catch (e) {}
  const poz = (typeof subPosOf === 'function') ? subPosOf(p) : (p.pos || '');
  const govde = d.length ? d.map(x =>
    '<div class="kd-dr ' + x.t + '"><div class="kd-ic">' + x.ic + '</div><div class="kd-tx"><b>' + x.b + '</b>'
    + (x.s ? '<span>' + x.s + '</span>' : '')
    + (x.s2 ? '<span' + (x.s2.indexOf('🏥') === 0 ? ' data-noi18n' : '') + '>' + x.s2 + '</span>' : '')
    + (x.bar != null ? '<div class="kd-bar"><i style="width:' + x.bar + '%;background:' + x.barRenk + '"></i></div>' : '')
    + '</div>' + (x.sg ? '<div class="kd-sg">' + x.sg + '</div>' : '') + '</div>').join('')
    : '<div class="kd-bos"><b>Bildirim yok</b><span>Oyuncu maça hazır</span></div>';
  ov.innerHTML = '<div class="kd-md" role="dialog" aria-modal="true">'
    + '<div class="kd-hd"><div class="futc-av">' + av + '</div><div class="kd-t"><b data-noi18n>' + _kdEsc(p.name) + '</b>'
    + '<span><span data-noi18n>' + _kdEsc(poz) + '</span> · <span>Sv.' + (p.level || 0) + '</span></span></div>'
    + '<button type="button" class="kd-x" onclick="kdDurumKapat()" aria-label="Kapat">✕</button></div>'
    + '<div class="kd-bd">' + govde + '</div>'
    + '<div class="kd-ft"><button type="button" onclick="kdDurumKapat()">Kapat</button></div></div>';
  ov.classList.add('acik');
  try { if (typeof _sakatlikSayaclariniGuncelle === 'function') _sakatlikSayaclariniGuncelle(); } catch (e) {}
}
function kdDurumKapat() { const ov = document.getElementById('kdOv'); if (ov) ov.classList.remove('acik'); }

// Sakatlık geri sayımı saat cinsinden (yukarı yuvarla, min 1)
function getInjuryRemainingHours(p) {
  const ms = _tsMsC(p && p.injuryUntil) - Date.now();
  return ms > 0 ? Math.max(1, Math.ceil(ms / 3600000)) : 0;
}

// 🆕 Sarı/kırmızı kart uygulamaları (applyYellowCard/applyRedCard) Edge function
// _processMatchDiscipline tarafından yapılır — frontend in-memory uygulama kaldırıldı.

// 🆕 Sezon sonu disiplin sıfırlama
// • seasonYellow sıfırlanır (yeni sezon, yeni sayaç)
// • suspendMatches devreder (cezalar yeni sezona taşınır)
// • injuryUntil devreder (sakatlık zamanlı, sezon sınırı yok)
function resetSeasonDiscipline() {
  if(typeof ROSTER_DATA === 'undefined' || !ROSTER_DATA.length) return;
  let changed = 0;
  ROSTER_DATA.forEach(p => {
    if(!p) return;
    if((p.seasonYellow || 0) > 0) {
      p.seasonYellow = 0;
      changed++;
    }
  });
  if(changed > 0) {
    console.info('[discipline] sezon sonu — ' + changed + ' oyuncu sarı kart sayacı sıfırlandı');
    if (typeof rosterSavePersist === 'function') {
      try { rosterSavePersist(); } catch(e) {}
    }
  }
}

// 🆕 applyInjury (frontend in-memory uygulama) Edge _processMatchDiscipline tarafından
// devralındı. Medical bonusu Edge'de team._facilities.medical'den hesaplanır
// (getMedicalRecoveryMultiplier ile aynı formül).

// applyBotMatchOutcome SİLİNDİ — bot maç sonu Edge function'da işleniyor.


// ═══════════════════════════════════════════════════════════════════
//  SERVER-READY MAÇ ADAPTÖRÜ
//  Maç motorunun tüm IO'su bu adapter üzerinden geçer.
//  • LocalAdapter: mevcut tek-client davranışı (offline)
//  • ServerAdapter: backend hazır olduğunda WebSocket bağlanır
//  Kullanım: matchAdapter.startMatch(...)
// ═══════════════════════════════════════════════════════════════════

const MATCH_PROTOCOL = {
  version: '1.0',
  events: {
    // Server → Client mesajları
    MATCH_START: 'match_start',
    TICK: 'tick',                     // Her saniye/tick
    EVENT: 'event',                    // Gol, kart, sub vb.
    HALFTIME: 'halftime',
    FULLTIME: 'fulltime',
    SCORE_UPDATE: 'score_update',
    PLAYER_RATING: 'player_rating',
    // Client → Server komutları (queue'lanır)
    CMD_TACTIC_CHANGE: 'cmd_tactic',
    CMD_SUBSTITUTION: 'cmd_sub',
    CMD_FORMATION_CHANGE: 'cmd_formation'
  }
};

// LocalAdapter — mevcut motor üzerinden çalışır
const LocalMatchAdapter = {
  type: 'local',
  isConnected: false,
  listeners: new Map(),

  // Maçı başlat — local'de generateScript çağırır
  async startMatch(homeTeam, awayTeam, options) {
    options = options || {};
    this.isConnected = true;
    this._emit(MATCH_PROTOCOL.events.MATCH_START, {
      home: homeTeam.name,
      away: awayTeam.name,
      adapter: 'local',
      timestamp: Date.now()
    });
    // Mevcut local motor zaten startMatch ile başlıyor — adapter sadece event yayınlıyor
    // Backend hazır olunca bu metod WebSocket connect olur
  },

  // Komut gönder (queue'la veya direkt uygula)
  sendCommand(cmdType, payload) {
    // Local mode: direkt apply
    if (cmdType === MATCH_PROTOCOL.events.CMD_TACTIC_CHANGE) {
      // Tactic değişikliği zaten activeStrategy'yi etkiler, regenerate çağrılır
      if (typeof regenerateRemainingScript === 'function') regenerateRemainingScript();
    } else if (cmdType === MATCH_PROTOCOL.events.CMD_SUBSTITUTION) {
      // makeSubstitution zaten doğrudan çalışıyor
    }
    // Echo back (test için)
    this._emit('cmd_ack', { cmdType, payload, status: 'applied' });
  },

  // Bağlantıyı kapat
  disconnect() {
    this.isConnected = false;
  },

  // Event listener kayıt
  on(eventType, handler) {
    if (!this.listeners.has(eventType)) this.listeners.set(eventType, new Set());
    this.listeners.get(eventType).add(handler);
  },
  off(eventType, handler) {
    if (this.listeners.has(eventType)) this.listeners.get(eventType).delete(handler);
  },
  _emit(eventType, data) {
    const handlers = this.listeners.get(eventType);
    if (handlers) handlers.forEach(h => { try { h(data); } catch(e){} });
  }
};

// ServerAdapter — backend hazır olduğunda doldurulacak
const ServerMatchAdapter = {
  type: 'server',
  isConnected: false,
  ws: null,
  listeners: new Map(),
  serverUrl: null,
  _commandQueue: [],
  _matchId: null,

  async connect(url) {
    // Backend hazır olunca aktif olacak
    this.serverUrl = url;
    // this.ws = new WebSocket(url);
    // this.ws.onmessage = (e) => this._handleMessage(JSON.parse(e.data));
    // this.ws.onopen = () => { this.isConnected = true; this._flushQueue(); };
    // this.ws.onclose = () => { this.isConnected = false; };
    // this.ws.onerror = (e) => console.warn('Match WS error:', e);
    console.warn('ServerMatchAdapter: backend henüz hazır değil');
  },

  async startMatch(homeTeam, awayTeam, options) {
    if (!this.isConnected) throw new Error('Server not connected');
    const matchReq = {
      type: 'request_match',
      home: { name: homeTeam.name, players: homeTeam.players, strategy: homeTeam.strategy },
      away: { name: awayTeam.name, players: awayTeam.players, strategy: awayTeam.strategy },
      options
    };
    this.ws.send(JSON.stringify(matchReq));
  },

  sendCommand(cmdType, payload) {
    if (!this._matchId) {
      this._commandQueue.push({ cmdType, payload });
      return;
    }
    const msg = {
      type: 'cmd',
      cmdType,
      matchId: this._matchId,
      payload,
      timestamp: Date.now()
    };
    if (this.ws && this.ws.readyState === 1) {
      this.ws.send(JSON.stringify(msg));
    } else {
      this._commandQueue.push({ cmdType, payload });
    }
  },

  _flushQueue() {
    while (this._commandQueue.length && this.ws && this.ws.readyState === 1) {
      const { cmdType, payload } = this._commandQueue.shift();
      this.sendCommand(cmdType, payload);
    }
  },

  _handleMessage(msg) {
    if (msg.matchId) this._matchId = msg.matchId;
    this._emit(msg.type, msg.data || msg);
  },

  disconnect() {
    if (this.ws) this.ws.close();
    this.isConnected = false;
  },

  on(eventType, handler) {
    if (!this.listeners.has(eventType)) this.listeners.set(eventType, new Set());
    this.listeners.get(eventType).add(handler);
  },
  off(eventType, handler) {
    if (this.listeners.has(eventType)) this.listeners.get(eventType).delete(handler);
  },
  _emit(eventType, data) {
    const handlers = this.listeners.get(eventType);
    if (handlers) handlers.forEach(h => { try { h(data); } catch(e){} });
  }
};

// Aktif adapter — global. Backend hazır olunca ServerMatchAdapter'a geçer.
let matchAdapter = LocalMatchAdapter;

// Adapter değiştir (backend bağlandığında çağrılacak)
function switchToServerAdapter(serverUrl) {
  if (matchAdapter && matchAdapter.disconnect) matchAdapter.disconnect();
  matchAdapter = ServerMatchAdapter;
  matchAdapter.connect(serverUrl);
}
function switchToLocalAdapter() {
  if (matchAdapter && matchAdapter.disconnect) matchAdapter.disconnect();
  matchAdapter = LocalMatchAdapter;
}

// ═══════════════════════════════════════════════════════════════════
//  SERVER-AUTHORITATIVE READY: Match State Replication Helper
//  Tüm state değişiklikleri tek noktadan geçer → backend kolayca bağlanır
// ═══════════════════════════════════════════════════════════════════

const MatchStateBus = {
  // Her event tipi için subscriber listesi
  _subscribers: new Map(),

  // State değişikliği yayınla (motor → UI + adapter)
  publish(eventType, data) {
    const subs = this._subscribers.get(eventType);
    if (subs) subs.forEach(fn => { try { fn(data); } catch(e){} });
    // Adapter'a da gönder (server replication için)
    if (matchAdapter && matchAdapter._emit) {
      matchAdapter._emit(eventType, data);
    }
  },

  subscribe(eventType, fn) {
    if (!this._subscribers.has(eventType)) this._subscribers.set(eventType, new Set());
    this._subscribers.get(eventType).add(fn);
    return () => this._subscribers.get(eventType).delete(fn); // unsubscribe
  },

  // Tüm subscribe'ları temizle (test/reset için)
  reset() { this._subscribers.clear(); }
};

// Komut gönderme yardımcısı (tactic, sub, qte)
// Server hazır olunca otomatik backend'e gider, local mode'da direkt uygulanır
function sendMatchCommand(cmdType, payload) {
  if (matchAdapter && matchAdapter.sendCommand) {
    matchAdapter.sendCommand(cmdType, payload);
  }
}


// ═══════════════════════════════════════════════════════════════════
//  MATCH AUTHORITY — Background Headless Simülasyon Otoritesi
//  ─────────────────────────────────────────────────────────────────
//  Vizyon: tüm maçlar (bot ve kullanıcı) tek otorite üzerinden ilerler.
//  Maç saati gelir → otomatik başlar. Kimse manuel başlatamaz, bitiremez.
//  90 dakika boyunca her in-game dakikada _simStepMinute() ile DİNAMİK
//  event üretilir (önceden hesaplama YOK). 90'a ulaşınca finalize, server
//  cache'ine (cft_match_results) yazılır.
//
//  Kullanıcı maça girdiğinde: Authority'den state okur, son sim_minute'tan
//  canlı yayını başlatır (geçmiş olaylar timeline'a yazılır).
//
//  Aşama 1 (BU AŞAMA): Bağımsız iskelet. Henüz hiçbir yere bağlı değil.
//                       Browser console üzerinden test edilebilir:
//                       MatchAuthority.register('test', {name:'A'}, {name:'B'}, Date.now()+5000)
//  Aşama 2: openMatchScreenV2 → MatchAuthority.register
//  Aşama 3: startMatch → MatchAuthority.getState ile join-in-progress
//  Aşama 4: Bot maçları (simulateBotMatch instant yerine) Authority'ye geçir
//  Aşama 5: Tüm lig fixtürleri sayfa açılırken otomatik register
// ═══════════════════════════════════════════════════════════════════

// 🚫 MatchAuthority frontend lokal motoru TAMAMEN SİLİNDİ.
// Tüm maç simülasyonu Supabase Edge Function (tick-matches) içinde çalışır.
// API uyumluluğu için no-op stub bırakıldı — eski çağrı yerleri patlamasın.
const MatchAuthority = {
  register: () => null,
  unregister: () => null,
  getState: () => null,
  getAll: () => [],
  getLive: () => [],
  tick: () => null,
  start: () => null,
  stop: () => null,
  _matches: {}
};
if (typeof window !== 'undefined') window.MatchAuthority = MatchAuthority;



// 🆕 QTE (Quick Time Event) sistemi kaldırıldı — kullanıcı etkisi yok, her şey otomatik


//  Her maç: 11 ilk 11 + 7 yedek = 18 kişilik kadro
//  Stamina < 50 oyuncular T.D.'ye uyarı gösterir
//  T.D. her maç önce 18'i seçer (otomatik veya manuel)
// ═══════════════════════════════════════════════════════════════════

const MATCH_SQUAD_SIZE = 18;
const STARTING_XI = 11;
const BENCH_SIZE = 7;
const STAMINA_WARNING = 60;       // 580 — kondisyon bunun altındaysa "yorgun" uyarısı
const STAMINA_CRITICAL = 40;      // 580 — bunun altı "bitkin" (maçta sakatlık riski artar)

// Maç için 18 kişilik kadroyu otomatik öner
// Öncelik: stamina yüksek + overall yüksek + sakat/cezalı değil
// Pozisyon dağılımı: en az 2 KL, 6 DEF, 6 MID, 4 FWD önerisi
function autoSelectMatchSquad() {
  if (typeof ROSTER_DATA === 'undefined' || !ROSTER_DATA.length) return [];

  // Eligible: sakat değil, cezalı değil
  const eligible = ROSTER_DATA.filter(p =>
    !isPlayerSuspended(p) && !isPlayerInjured(p)
  );
  if (eligible.length < MATCH_SQUAD_SIZE) {
    // Tüm sağlam oyuncular yetmiyorsa, hepsini al
    return eligible.slice(0, MATCH_SQUAD_SIZE).map(p => p.num);
  }

  // Pozisyon dağılımı hedefi (18 kişi)
  const targets = { GK: 2, DEF: 6, MID: 6, FWD: 4 };
  // Pozisyon ailesini bul
  const _fam = (pos) => {
    if (pos === 'KL' || pos === 'GK') return 'GK';
    if (['SB','STB','DEF'].includes(pos)) return 'DEF';
    if (['DOS','OS','CAM','MID'].includes(pos)) return 'MID';
    if (['SAK','FWD'].includes(pos)) return 'FWD';
    return 'MID';
  };

  // Skor: overall (yüksek olan önce) — stamina kapalı
  const _score = (p) => {
    const o = p.overall || 70;
    const m = (typeof p.morale === 'number') ? p.morale : 70;
    return o * (0.85 + m / 200); // moral küçük etkili
  };

  // Pozisyon havuzlarına ayır + skoruna göre sırala
  const pools = { GK: [], DEF: [], MID: [], FWD: [] };
  eligible.forEach(p => {
    pools[_fam(p.pos)].push(p);
  });
  Object.keys(pools).forEach(k => pools[k].sort((a,b) => _score(b) - _score(a)));

  // Hedeflere göre seç, eksik yerleri en iyi kalanlardan doldur
  const selected = [];
  Object.keys(targets).forEach(pos => {
    const need = targets[pos];
    const got = pools[pos].slice(0, need);
    selected.push(...got);
  });

  // 18'i tamamlamak için ek seç (en yüksek skorlu kalan)
  if (selected.length < MATCH_SQUAD_SIZE) {
    const selectedNums = new Set(selected.map(p => p.num));
    const remaining = eligible
      .filter(p => !selectedNums.has(p.num))
      .sort((a,b) => _score(b) - _score(a));
    while (selected.length < MATCH_SQUAD_SIZE && remaining.length) {
      selected.push(remaining.shift());
    }
  }

  return selected.slice(0, MATCH_SQUAD_SIZE).map(p => p.num);
}

// 18'den ilk 11'i seç (en yüksek skor + pozisyon)
function autoSelectStartingXI(squadNums) {
  if (typeof ROSTER_DATA === 'undefined' || !squadNums || !squadNums.length) return [];
  const squad = squadNums.map(n => ROSTER_DATA.find(p => p.num === n)).filter(Boolean);
  if (squad.length < STARTING_XI) return squad.map(p => p.num);

  const _fam = (pos) => {
    if (pos === 'KL' || pos === 'GK') return 'GK';
    if (['SB','STB','DEF'].includes(pos)) return 'DEF';
    if (['DOS','OS','CAM','MID'].includes(pos)) return 'MID';
    return 'FWD';
  };
  const _score = (p) => {
    return p.overall || 70;
  };

  // 4-3-3 dağılımı: 1 GK, 4 DEF, 3 MID, 3 FWD
  const xi_targets = { GK: 1, DEF: 4, MID: 3, FWD: 3 };
  const pools = { GK: [], DEF: [], MID: [], FWD: [] };
  squad.forEach(p => pools[_fam(p.pos)].push(p));
  Object.keys(pools).forEach(k => pools[k].sort((a,b) => _score(b) - _score(a)));

  const xi = [];
  Object.keys(xi_targets).forEach(pos => {
    xi.push(...pools[pos].slice(0, xi_targets[pos]));
  });
  if (xi.length < STARTING_XI) {
    const xiNums = new Set(xi.map(p => p.num));
    const remaining = squad.filter(p => !xiNums.has(p.num)).sort((a,b) => _score(b) - _score(a));
    while (xi.length < STARTING_XI && remaining.length) xi.push(remaining.shift());
  }
  return xi.slice(0, STARTING_XI).map(p => p.num);
}

// Stamina'sı düşük oyuncu var mı uyarısı
function getStaminaWarnings() {
  if (typeof ROSTER_DATA === 'undefined') return [];
  // 580 — yalnızca ilk 11 (kadro dışı / yedek oyuncunun yorgunluğu maçı etkilemez)
  let ilk = null;
  try { if (typeof _DZ !== 'undefined' && _DZ.klub) { const a = _DZ.klub.sahadakiler().filter(Boolean); if (a.length) ilk = new Set(a.map(p => p.num)); } } catch (e) {}
  return ROSTER_DATA.filter(p =>
    typeof p.stamina === 'number' && p.stamina < STAMINA_WARNING && (!ilk || ilk.has(p.num))
  ).map(p => ({
    num: p.num, name: p.name, pos: p.pos,
    stamina: p.stamina,
    label: staminaLabel(p.stamina),
    critical: p.stamina < STAMINA_CRITICAL
  }));
}


//  Maç sonu her oyuncuya FIFA-tarzı bireysel performans notu verilir
//  Olaylara, oynanan dakikaya, takım sonucuna göre hesaplanır
// ═══════════════════════════════════════════════════════════════════

// Bir oyuncunun maç notunu hesapla
// player: roster veya match objesi (num, pos, rating)
// 🆕 GELİŞMİŞ REYTİNG MOTORU — gerçek hayat dinamikleri (FotMob/SofaScore tarzı)
//
// Etki eden faktörler:
//   POZİTİF: gol, asist, key pass, kurtarış, top kapma, blok, ikili mücadele kazanma,
//            kazanılan penaltı, clean sheet, geri dönüş golü, geç gol (90+'da galibiyet)
//   NEGATİF: kırmızı kart, kendi kalesine gol, kaçan penaltı, kaçan büyük şans,
//            sarı kart (zamana göre), gol yenmesi (def/gk için), erken çıkma
//   MODİFİYELER: pozisyon, oynanan dakika, takım sonucu, rakip kalitesi, pas isabeti,
//                topla buluşma, kritik dakika çarpanı
//
// playerEvents: bu oyuncuya ait event'ler
// teamWon: 'win' | 'draw' | 'loss'
// minutesPlayed: oynadığı dakika (1-95)
// teamConceded: takım kaç gol yedi
// ctx: { teamScored, oppRating, teamRating, allEvents, side, fixturePass, fixturePoss, weather, ... }
// calcPlayerRating + ratePlayers + findMatchMVP KALDIRILDI — reyting TEK kaynak: Edge.
// (Frontend çift hesap idi; LIVE canlı reyting _attachLivePlayerStats, kalıcı reyting Edge.)

// Rating renk kodu (UI için)
function ratingColor(r) {
  if (r >= 9.0) return '#ffd700';   // altın — efsane
  if (r >= 8.0) return '#00e676';   // yeşil — harika
  if (r >= 7.0) return '#9ccc65';   // açık yeşil — iyi
  if (r >= 6.0) return '#ffd54f';   // sarı — vasat
  if (r >= 5.0) return '#ff9800';   // turuncu — kötü
  return '#ef5350';                  // kırmızı — felaket
}


//  90 dk maç -25, ağır press (Çok Yüksek) +%30 düşüş
//  1 maç dinlenme +50, sezon sonu otomatik 100'e döner
//  Maç içi xG ve rating'e etki eder
// ═══════════════════════════════════════════════════════════════════

const STAMINA_DEFAULTS = {
  initial: 100,
  perMatchDrop: 25,           // Tam 90 dk oynayan oyuncu için
  benchedRecovery: 50,         // Maçta yedekte kalan oyuncuya
  notInSquadRecovery: 70,      // Kadroda olmayan (dinlenen) oyuncuya
  pressMultiplier: {           // Press yoğunluğuna göre stamina düşüş çarpanı
    'Minimal': 0.80,
    'Orta': 1.00,
    'Yüksek': 1.15,
    'Çok Yüksek': 1.30
  },
  styleFitnessImpact: 0.20,    // Style'ın fitness değeri (0-1) bu kadar etkiler
  partialPlayThreshold: 30,    // 30 dk altı oynayan = yarım stamina düşüşü
};

// Stamina'nın maça etkisi
// 100 stamina = 1.00 (tam performans)
// 70 stamina  = 0.95 (-5% etki)
// 50 stamina  = 0.88 (-12% etki, kritik düşüş)
// 30 stamina  = 0.78 (-22% etki, ciddi yorgunluk)
// 10 stamina  = 0.65 (kollapse)
function getPlayerStaminaMultiplier(p) {
  // 🆕 Stamina sistemi devre dışı — multiplier her zaman 1.0
  // (Backend property kalır, ama hiçbir yerde performans etkisi yok)
  return 1.0;
}

// Bir oyuncunun maç sonu stamina düşüşünü hesapla
// minutes: oynadığı dakika (90 = tam maç, 0 = oynamadı)
// strategy: takımın stratejisi (press yoğunluğu için)
function calcStaminaDrop(p, minutes, strategy) {
  if (!p || minutes <= 0) return 0;
  const def = STAMINA_DEFAULTS;
  // Tam maç düşüşü
  let drop = def.perMatchDrop;
  // Press çarpanı
  const pressMult = (strategy && def.pressMultiplier[strategy.press]) || 1.0;
  drop *= pressMult;
  // Style fitness çarpanı (Gegenpressing 0.90 → +%10 ekstra düşüş)
  const styleMods = (typeof STYLE_MODS !== 'undefined' && strategy) ? STYLE_MODS[strategy.style] : null;
  if (styleMods && typeof styleMods.fitness === 'number') {
    // fitness 1.00 = nötr, 0.90 = -%10 (yorucu), 1.05 = +%5 (rahat)
    const fitnessImpact = (1 / styleMods.fitness - 1) * def.styleFitnessImpact + 1;
    drop *= fitnessImpact;
  }
  // Oynanan dakika oranı (yedek girip 30 dk oynayan yarım drop alır)
  const minuteRatio = Math.min(1, minutes / 90);
  drop *= minuteRatio;
  return Math.round(drop);
}

// Maç sonu: tüm oyunculara stamina değişikliği uygula
// startersNums: ilk 11'in numaraları
// substitutionsApplied: [{outNum, inNum, minute}, ...]
function applyMatchStamina(strategy, startersNums, substitutionsApplied) {
  if (typeof ROSTER_DATA === 'undefined' || !ROSTER_DATA.length) return;
  const def = STAMINA_DEFAULTS;
  const startersSet = new Set(startersNums || []);
  const subbedInSet = new Set((substitutionsApplied || []).map(s => s.inNum));
  const subbedOutMap = {};
  (substitutionsApplied || []).forEach(s => { subbedOutMap[s.outNum] = s.minute; });

  ROSTER_DATA.forEach(p => {
    if (typeof p.stamina !== 'number') p.stamina = def.initial;

    // İlk 11'de mi, yedek mi, kadro dışı mı?
    const isStarter = startersSet.has(p.num);
    const subbedIn = subbedInSet.has(p.num);
    const subbedOut = subbedOutMap[p.num];

    let minutes = 0;
    if (isStarter && !subbedOut) minutes = 90;
    else if (isStarter && subbedOut) minutes = subbedOut; // çıkartıldı
    else if (subbedIn) {
      // Sub'a giren: kalan dk oynar
      const sub = (substitutionsApplied || []).find(s => s.inNum === p.num);
      minutes = sub ? Math.max(0, 90 - sub.minute) : 30;
    }

    if (minutes > 0) {
      // Oynadı → düşüş
      const drop = calcStaminaDrop(p, minutes, strategy);
      p.stamina = Math.max(0, p.stamina - drop);
    } else if (startersSet.has(p.num) === false && subbedIn === false) {
      // Hiç oynamadı, yedek kulübesinde bile değil → tam dinlenme
      p.stamina = Math.min(100, p.stamina + def.notInSquadRecovery);
    } else {
      // Yedek kulübesinde oturdu, oynamadı → orta dinlenme
      p.stamina = Math.min(100, p.stamina + def.benchedRecovery);
    }
  });
}

// Sezon sonu / yeni sezon başında: tüm oyuncuların stamina'sını sıfırla
function resetAllStamina() {
  if (typeof ROSTER_DATA === 'undefined') return;
  ROSTER_DATA.forEach(p => { p.stamina = STAMINA_DEFAULTS.initial; });
  if (typeof rosterSavePersist === 'function') rosterSavePersist();
}

// Stamina renk hesabı (UI için)
function staminaColor(s) {
  if (s >= 80) return '#00e676';      // yeşil — taze
  if (s >= 60) return '#9ccc65';      // açık yeşil
  if (s >= 40) return '#ffd54f';      // sarı — yorgun
  if (s >= 20) return '#ff9800';      // turuncu — kritik
  return '#ef5350';                    // kırmızı — bitkin
}

function staminaLabel(s) {
  // 580 — kondisyon etiketleri (kon.js konEtiket ile aynı)
  if (s >= 80) return 'Dinç';
  if (s >= 60) return 'İyi';
  if (s >= 40) return 'Yorgun';
  return 'Bitkin';
}


// ═══════════════════════════════════════════════════════════════════
//  OYUNCU MORALİ SİSTEMİ (0-100, başlangıç 70)
//  Galibiyet +5, Mağlubiyet -8, Beraberlik 0
//  Gol +6, Asist +3, Sarı kart -3, Kırmızı -10, Sakatlık -8
//  Yedek kalmak -1 (her maç)
// ═══════════════════════════════════════════════════════════════════

// Moralin maç motoruna etkisi: hücum/savunma %0.05 (her +/- 10 moral)
// Yüksek moral (>80) hücum/savunma'yı +5%, düşük moral (<40) -8% etkiler
function getPlayerMoraleMultiplier(p) {
  if (!p || typeof p.morale !== 'number') return 1.0;
  const m = p.morale;
  if (m >= 90) return 1.08;
  if (m >= 75) return 1.04;
  if (m >= 50) return 1.00;
  if (m >= 30) return 0.95;
  return 0.88;
}

// Moral değerini ayarla (oyuncu objesi üzerinde)
function adjustMorale(p, delta, reason) {
  if (!p) return;
  if (typeof p.morale !== 'number') p.morale = 70; // başlangıç
  p.morale = Math.max(0, Math.min(100, p.morale + delta));
}



// ═══════════════════════════════════════════════════════════════════
//  SÖZLEŞME & MAAŞ SİSTEMİ — SEZONLUK 2 TAKSİT (REVİZE 2026)
// ═══════════════════════════════════════════════════════════════════
// Kurallar:
//  • Yıllık maaş 2 taksit: 1. taksit sezonun 19. günü, 2. taksit 38. gün
//  • Botlar maaş almaz (wage = 0)
//  • Sadece sözleşmeli gerçek oyuncular ödenir (şu an: yalnızca kullanıcı)
//  • Kasa tüm ödemeyi karşılayamazsa HİÇ KİMSEYE ödeme yapılmaz
//  • Ödenmemiş oyuncu → "Ayrıl" butonu serbest hâle geçer
//  • İmza parası (signing bonus) sözleşme onaylandığı an ayrı ödenir

// Eski haftalık fonksiyonu nostöp halinde tutuyoruz (eski çağrılar kırılmasın)
function checkWeeklySalaryPayment(){ /* devre dışı — Edge cron'una taşındı */ }

// 🆕 Sözleşme aktif mi? (sezon bazlı) — Edge cron için kullanılıyor değil ama
// canUserLeaveTeam, checkContractExpiration ve diğer akışlar için referans noktası.
function userHasActiveContract() {
  if(typeof _userTeam === 'undefined' || !_userTeam) return false;
  const c = _userTeam.contract;
  if(!c) return false;
  // Sezon bazlı kontrol: sözleşme bitiş sezonu >= mevcut sezon
  const info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : null;
  if(!info) return false;
  // 592 — sunucuyla aynı: bitiş sezonu sayı olmalı (bordronun sözleşmesiz üyeye açtığı kayıt aktif sayılmaz)
  if(typeof c.endsSeason !== 'number' || c.endsSeason < info.season) return false;
  return true;
}

// 🆕 ESKİ FRONTEND MAAŞ ÖDEME ZİNCİRİ SİLİNDİ
// Maaş ödemesi artık Edge function tarafından yapılıyor (_paySalariesForDay).
// Silinen fonksiyonlar:
//   • getPlayerYearlySalary, getPlayerInstallmentAmount, getTeamInstallmentBill
//   • _paidInstallmentsCache, _paidInstallmentsLoadFromServer, getPaidInstallments,
//     savePaidInstallments, isInstallmentPaid, markInstallmentPaid
//   • checkSeasonalSalaryPayment (idempotency Edge'de contract.lastPayKey ile)

// ═══════════════════════════════════════════════════════════════════
//  KONTRAT KONTROLÜ — TAKIMDAN AYRILMA HAKKI
// ═══════════════════════════════════════════════════════════════════
// Kural:
//   • Kaptan: kendi takımını satabilir, "ayrılma" değildir → kullanıcıyı
//     başka akışa yönlendir (öner: "önce takımı sat").
//   • Sözleşmesiz üye (joinTeamDirect ile katılan): istediği zaman ayrılır.
//   • Sözleşmeli üye (teklif kabul ile katılan): sözleşme aktif olduğu sürece
//     KENDİ İSTEĞİYLE AYRILAMAZ.
//   • İstisna: takım maaş taksitini ödeyemezse → contract.canLeaveFreely=true
//     olur ve sözleşmeyi fesheden ayrılma hakkı doğar.
//
// Dönüş: { allowed, reason, requiresConfirm, confirmMsg }
//   - allowed: ayrılabilir mi?
//   - reason: ayrılamıyorsa kullanıcıya gösterilecek mesaj
//   - requiresConfirm: ayrılabiliyor ama ekstra onay isteyecek mi?
//   - confirmMsg: onay mesajı (canLeaveFreely durumunda)
// ═══════════════════════════════════════════════════════════════════
function canUserLeaveTeam() {
  if (typeof _userTeam === 'undefined' || !_userTeam) {
    return { allowed: false, reason: 'Takımın yok.' };
  }
  if (_userTeam.role === 'captain') {
    return {
      allowed: false,
      reason: '⚠️ Kaptan ayrılamaz.\n\nÖnce bir oyuncunun kartından "👑 Kaptan Yap" ile yetkini devret — üye olduktan sonra (sözleşme kuralına göre) ayrılabilirsin.\n\nAlternatif: Takımı Sat — fiyatı sen belirlersin, satılınca elmaslar cüzdanına geçer.'
    };
  }
  const c = _userTeam.contract;
  if (c && typeof userHasActiveContract === 'function' && userHasActiveContract()) {
    if (c.canLeaveFreely || (Number(c.unpaidInstallments) || 0) >= 2) {
      // 🆕 Ayrılma hakkı doğmuş — neden olduğunu mesajda belirt
      const isExpired = (typeof getSeasonInfo === 'function') &&
                        (getSeasonInfo().season > (c.endsSeason || 0));
      const isUnpaid = (c.unpaidInstallments || 0) >= 2;
      const reasonStr = isExpired ? 'sözleşme süren dolduğu için'
                       : isUnpaid ? 'takım maaş ödemesini yapamadığı için'
                       : 'yenileme reddedildiği için';
      return {
        allowed: true,
        requiresConfirm: true,
        confirmMsg: `🔓 SÖZLEŞME FESHİ\n\n` +
                    `${reasonStr} serbestçe ayrılma hakkın doğdu.\n\n` +
                    `Ayrılırsan:\n` +
                    `• ${_userTeam.teamName} sözleşmen iptal edilir\n` +
                    `• Serbest oyuncu olursun\n` +
                    `• İstediğin zaman başka takıma katılabilirsin\n\n` +
                    `Devam etmek istiyor musun?`
      };
    } else {
      // Sözleşme aktif, maaş ödeniyor → ayrılamaz
      const info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : null;
      const remainSeasons = (info && typeof c.endsSeason === 'number')
        ? Math.max(0, c.endsSeason - info.season + 1) : 0;
      const seasonSal = _benimSezonMaasim();
      const salStr = seasonSal > 0
        ? `Sezon maaşı: ${(seasonSal/1000).toLocaleString('tr')}K € (4 taksit)\n` : '';
      return {
        allowed: false,
        reason: `🔒 SÖZLEŞMEN AKTİF\n\n` +
                `${_userTeam.teamName} ile sözleşmen var.\n` +
                (typeof c.endsSeason === 'number'
                  ? `Bitiş: ${c.endsSeason}. sezon sonu (kalan: ${remainSeasons} sezon)\n` : '') +
                salStr +
                `\n` +
                `Sözleşmeli oyuncu kendi isteğiyle takımdan ayrılamaz.\n\n` +
                `Ayrılma hakkı şu durumda doğar:\n` +
                `• Takım 2 maaş taksitini ödeyemezse (kasa yetersiz)\n` +
                `• Sözleşme süresi dolarsa\n` +
                `• Sezon sonu yenileme reddedildiyse\n\n` +
                `Bu durumlardan biri gerçekleşene kadar takımda kalman gerekir.`
      };
    }
  }
  // Sözleşmesiz üye — istediği zaman ayrılır (sadece normal onay yeterli)
  return { allowed: true, requiresConfirm: false };
}

// ── Bir takıma "gerçek kaptan" mı yoksa "bot kaptan" mı? ──
// Backend hazır olunca bu fonksiyon API'den gelecek. Şu an:
// • Kullanıcının kendi takımı (rolü captain) → 'user'
// • Test panelinden "gerçek kaptanlı" işaretlenenler → 'user'
// • Diğer her şey → 'bot'
// 🆕 Gerçek kullanıcı kaptanları RAM cache — players tablosundan periyodik yenilenir
// Format: { "CC:TeamName": { captainUserId, captainName, members: [{userId, role, name}] } }
let _realCaptainsCache = {};
let _realCaptainsCacheTs = 0;
let _realCaptainsLoading = null;
// 🆕 ÖLÇEK: eskiden TÜM gerçek oyuncular (dünyadaki her kullanıcı) tek sorguda
//   çekiliyordu — 20 bin oyuncuda her çağrı 20 bin satır. Artık ÜLKE bazında
//   çekilip cache'e karıştırılıyor; ülke verilmezse kullanıcının kendi ülkesi
//   kullanılır. Ülke başına ayrı tazelik damgası tutulur.
let _realCaptainsCcTs = {};
function _realCaptainsVarsayilanCC() {
  try {
    if (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.countryCode) return _userTeam.countryCode;
    if (typeof getUserNationalityCC === 'function') { const c = getUserNationalityCC(); if (c) return c; }
  } catch(e) {}
  return null;
}

async function _loadRealCaptainsFromServer(cc) {
  if (!window.sb) return _realCaptainsCache;
  const _cc = cc || _realCaptainsVarsayilanCC();
  const _damga = _cc ? (_realCaptainsCcTs[_cc] || 0) : _realCaptainsCacheTs;
  if ((Date.now() - _damga) < 60000 && Object.keys(_realCaptainsCache).length > 0) {
    return _realCaptainsCache;
  }
  if (_realCaptainsLoading) return _realCaptainsLoading;
  _realCaptainsLoading = (async () => {
    try {
      // 🆕 Kapsamlı kullanıcı bilgisi çek: avatar, level, overall, pos, last_seen
      let _q = window.sb.from('players')
        .select('user_id, user_team_data, role, name, avatar, level, overall, rating, pos, pos_group, sub_pos, nationality, nation, last_seen, xp')
        .not('user_id', 'is', null)
        .not('user_team_data', 'is', null);
      if (_cc) _q = _q.eq('country_code', _cc);
      else _q = _q.limit(5000);
      const { data, error } = await _q;
      if (error) { console.warn('[realCaptains] load hata:', error); return _realCaptainsCache; }
      // Ülke bazlı çekimde diğer ülkelerin kayıtları korunur, yalnız bu ülkeninkiler tazelenir.
      const cache = {};
      if (_cc) {
        for (const k in _realCaptainsCache) {
          if (k.slice(0, k.indexOf(':')) !== _cc) cache[k] = _realCaptainsCache[k];
        }
      }
      const ONLINE_THRESHOLD_MS = 5 * 60 * 1000; // 5 dk
      const nowMs = Date.now();
      for (const row of (data || [])) {
        const t = row.user_team_data;
        if (!t || !t.countryCode || !t.teamName) continue;
        const key = t.countryCode + ':' + t.teamName;
        if (!cache[key]) cache[key] = { captainUserId: null, captainName: null, members: [] };
        // Online?
        const lastSeenMs = row.last_seen ? new Date(row.last_seen).getTime() : 0;
        const isOnline = lastSeenMs && (nowMs - lastSeenMs < ONLINE_THRESHOLD_MS);
        // 627 — rol players.role sütunundan: sunucu kaptanlığı devrederken yalnız onu yazar
        const rol = row.role || t.role || 'member';
        cache[key].members.push({
          userId: row.user_id,
          role: rol,
          name: row.name || 'Oyuncu',
          avatar: row.avatar || '👤',
          level: Number(row.level || 0),
          xp: Number(row.xp || 0),
          overall: Number(row.overall || 10),
          rating: Number(row.rating || row.overall || 10),
          pos: row.pos || 'MID',
          posGroup: row.pos_group || row.pos || 'MID', subPos: row.sub_pos,
          nationality: row.nationality || t.countryCode,
          nation: row.nation || null,
          isOnline,
          lastSeen: row.last_seen || null,
        });
        if (rol === 'captain') {
          cache[key].captainUserId = row.user_id;
          cache[key].captainName = row.name || 'Kaptan';
        }
      }
      _realCaptainsCache = cache;
      _realCaptainsCacheTs = Date.now();
      if (_cc) _realCaptainsCcTs[_cc] = Date.now();
      return cache;
    } catch(e) { console.warn('[realCaptains] hata:', e); return _realCaptainsCache; }
    finally { _realCaptainsLoading = null; }
  })();
  return _realCaptainsLoading;
}

// Cache'i hemen geçersiz kılıp yeniden çek (kullanıcı takıma katıldığında/ayrıldığında)
function _invalidateRealCaptainsCache() {
  _realCaptainsCacheTs = 0;
  _realCaptainsCcTs = {};
  _realCaptainsCache = {};
}

function getTeamCaptainType(countryCode, teamName) {
  // Kullanıcı kendi kaptanlı takımı
  if(typeof _userTeam !== 'undefined' && _userTeam
     && _userTeam.countryCode === countryCode
     && _userTeam.teamName === teamName
     && _userTeam.role === 'captain') {
    return 'user';
  }
  // 🆕 Supabase cache'ten kontrol et — başka kullanıcı bu takımın kaptanı mı?
  const key = countryCode + ':' + teamName;
  const entry = _realCaptainsCache[key];
  if (entry && entry.captainUserId) return 'user';
  return 'bot';
}

// Bir takımın gerçek kaptanının adını döndür (mesajlarda göstermek için)
function getTeamRealCaptainName(countryCode, teamName) {
  const key = countryCode + ':' + teamName;
  const entry = _realCaptainsCache[key];
  if (entry && entry.captainName) return entry.captainName;
  return 'Kaptan';
}


// ── Sözleşmenin son sezonu: yenileme modalı ve "sözleşmen bitiyor" bildirimi bu durumu kullanır ──

function _getContractRenewalState() {
  if(typeof _userTeam === 'undefined' || !_userTeam || !_userTeam.contract) return null;
  if(typeof getSeasonInfo !== 'function') return null;
  const info = getSeasonInfo();
  if(info.preSeason) return null;
  const c = _userTeam.contract;
  if(typeof c.endsSeason !== 'number') return null;

  // Sözleşmenin SON sezonu ya da süresi dolmuş (592 — sunucu da ikisinde yenilemeye izin verir;
  //   süresi dolan oyuncu takımda kalır ve yenileme isteyebilir)
  if(c.endsSeason > info.season) return null;
  const bitti = c.endsSeason < info.season;

  const SEASON_LEN_VAL = (typeof SEASON_LEN !== 'undefined') ? SEASON_LEN : 40;
  const daysLeft = bitti ? 0 : SEASON_LEN_VAL - info.dayInSeason;

  return {
    contract: c,
    info,
    daysLeft,
    bitti,
    inWarningWindow: (!bitti && daysLeft >= 0 && daysLeft <= 5),
    alreadyWarned: !!c.renewalWarnedSeason && c.renewalWarnedSeason === info.season,
  };
}

function _calcRenewalOffer(currentContract) {
  // 🆕 SİSTEM HESAPLI YENİ MAAŞ
  // Oyuncunun şu anki seviyesine göre yeni sezon maaşı hesaplanır.
  // Büyüdüyse maaş ARTAR (sistem mantığı), küçülmesi imkansız (level düşmez).
  let player = null;
  try {
    if(typeof ROSTER_DATA !== 'undefined' && Array.isArray(ROSTER_DATA)) {
      player = ROSTER_DATA.find(p => p && p.role === 'user');
    }
  } catch(e){}

  const newSeasonSalary = (typeof getSystemPlayerSalary === 'function' && player)
    ? getSystemPlayerSalary(player)
    : Math.round((currentContract.seasonSalary || currentContract.yearlySalary || 100000) * 1.1);

  const oldSalary = Number(currentContract.seasonSalary || currentContract.yearlySalary || 0);
  const diff = newSeasonSalary - oldSalary;
  const raisePercent = oldSalary > 0 ? Math.round((diff / oldSalary) * 100) : 0;

  return {
    seasonSalary: newSeasonSalary,        // 🆕 yeni sezon maaşı
    yearlySalary: newSeasonSalary,        // backward compat
    durationSeasons: 1,                    // her zaman 1 sezon uzar
    signingDiamond: 0,                     // imza elması yenilemede yok (yeni transfer değil)
    signingBonus: 0,                       // backward compat
    raisePercent,                          // % artış (negatif olabilir teorik, pratikte 0+)
    oldSalary,
    diff,
  };
}


// ── Sözleşme yenileme modal'ı: aç/kapat/kabul/red ──
let _currentRenewalOffer = null;

function openContractRenewalModal() {
  const state = _getContractRenewalState();
  if(!state || !state.contract) {
    if(typeof showToast === 'function') showToast('Aktif yenilenebilir sözleşmen yok');
    return;
  }
  const c = state.contract;
  const offer = _calcRenewalOffer(c);
  _currentRenewalOffer = offer;

  const _f = v => v >= 1000000 ? (v/1000000).toFixed(1)+'M €' : v > 0 ? Math.round(v/1000)+'K €' : '0 €';
  const teamName = _userTeam.teamName || '';
  const flag = (true && _cftGetCountry(_userTeam.countryCode))
    ? (_cftGetCountry(_userTeam.countryCode).flag || '') : '';

  // 🆕 Yeni alan yapısı: seasonSalary + firstSalary
  const curSeason = Number(c.seasonSalary || c.yearlySalary || 0);
  const firstSalary = Number(c.firstSalary || curSeason);
  const newInst = Math.round(offer.seasonSalary / 4);
  const rejectInst = Math.round(firstSalary / 4);
  const raiseColor = offer.raisePercent >= 0 ? 'var(--accent)' : '#ff5722';
  const raiseSign = offer.raisePercent >= 0 ? '+' : '';

  const body = document.getElementById('crmBody');
  if(body) {
    body.innerHTML = `
      <div class="crm-team">${flag} ${teamName}</div>
      <div class="crm-warn">${state.bitti ? `⚠️ Sözleşmen ${c.endsSeason}. sezon sonunda sona erdi` : `⚠️ Sözleşmen ${state.daysLeft} gün içinde sona eriyor`}</div>

      <div class="crm-section">
        <div class="crm-section-title">📋 Mevcut Sözleşme</div>
        <div class="crm-row"><span class="crm-label">Sezon Maaşı</span><span class="crm-val">${_f(curSeason)}</span></div>
        <div class="crm-row"><span class="crm-label">İlk Maaş (sözleşme imzasında)</span><span class="crm-val" style="opacity:.7">${_f(firstSalary)}</span></div>
        <div class="crm-row"><span class="crm-label">Bitiş</span><span class="crm-val">${sozlesmeBitisEtiketi(c.endsSeason)}</span></div>
      </div>

      <div class="crm-arrow">↓</div>

      <div class="crm-section crm-offer">
        <div class="crm-section-title" style="color:var(--gold)">✨ Sistem Tarafından Hesaplanan Yeni Maaş</div>
        <div class="crm-row"><span class="crm-label">Sezon Maaşı</span><span class="crm-val" style="color:${raiseColor}">${_f(offer.seasonSalary)} <small style="opacity:.65;font-weight:600">(${raiseSign}%${offer.raisePercent})</small></span></div>
        <div class="crm-row"><span class="crm-label">Taksit (4× gün 10/20/30/40)</span><span class="crm-val">${_f(newInst)}</span></div>
        <div class="crm-row"><span class="crm-label">Yeni Bitiş</span><span class="crm-val" style="color:var(--gold)">${sozlesmeBitisEtiketi(state.info.season + 1)}</span></div>
      </div>

      <div class="crm-note">📨 Talep göndereceksin. Kaptan onaylarsa yeni maaş aktif olur. <b>Reddederse</b>: maaşın <b>${_f(firstSalary)}</b> ilk imza maaşına düşer (4× ${_f(rejectInst)}) + takımdan ayrılma serbestliği kazanırsın.</div>
    `;
  }

  const ov = document.getElementById('contractRenewalOverlay');
  if(ov) ov.classList.add('open');
}

function closeContractRenewalModal() {
  const ov = document.getElementById('contractRenewalOverlay');
  if(ov) ov.classList.remove('open');
  _currentRenewalOffer = null;
}

// ═══════════════════════════════════════════════════════════════════
// 🆕 OYUNCU → KAPTAN: Sözleşme Yenileme Talebi
// ═══════════════════════════════════════════════════════════════════
// Akış:
//   1. Oyuncu sezon son 5 günde "Yenileme Talebi Gönder" butonuna basar
//   2. Bot kaptan ise → frontend otomatik karar verir (kasa + overall'a göre)
//   3. User kaptan ise → kaptanın inbox'una "Kabul/Red" butonlu mesaj gider
//   4. Kararın geri dönüşü oyuncuya inbox bildirimi ile gelir + contract update
//
// Kaptan bot karar mantığı:
//   • Kasa yetersizse → RED (yeni maaşın 4x'i kasada yoksa)
//   • Oyuncu overall < 30 → RED (yedek seviye)
//   • Aksi → KABUL
async function sendContractRenewalRequest() {
  const offer = _currentRenewalOffer;
  if (!offer) { closeContractRenewalModal(); return; }
  if (typeof _userTeam === 'undefined' || !_userTeam || !_userTeam.contract) {
    closeContractRenewalModal(); return;
  }
  if (!_userTeam.countryCode || !_userTeam.teamName) {
    closeContractRenewalModal(); return;
  }

  // Kaptanı bul
  const cc = _userTeam.countryCode;
  const tn = _userTeam.teamName;
  const key = cc + ':' + tn;

  // Cache fresh değilse yenile
  if (typeof _loadRealCaptainsFromServer === 'function') {
    try { await _loadRealCaptainsFromServer(); } catch(e) {}
  }

  const teamEntry = (typeof _realCaptainsCache !== 'undefined' && _realCaptainsCache[key])
    ? _realCaptainsCache[key] : null;
  const captainUserId = teamEntry && teamEntry.captainUserId;
  const captainName = (teamEntry && teamEntry.captainName) || _userTeam.contract.capName || 'Kaptan';

  // Modal'ı kapat — sonuç toast/inbox ile gelir
  closeContractRenewalModal();

  // 🤖 BOT KAPTAN — kararı sunucu verir (kasa + oyuncu seviyesi); eskiden tarayıcıda veriliyordu
  if (!captainUserId) {
    let _d = null;
    try { const _r = await edgeCall('decide_renewal', { player: (authUser || {}).id || '', karar: 'oto' }); _d = _r && _r.data; } catch (e) {}
    if (!_d || _d.error) {
      const _m = { yenileme_zamani_degil: 'Sözleşmen henüz yenileme döneminde değil.', zaten_karar_verildi: 'Bu sezon yenileme kararı zaten verildi.' }[_d && _d.error];
      if (typeof tfShowToast === 'function') tfShowToast('❌ ' + (_m || 'Yenileme talebi işlenemedi.'), 'var(--red)');
      return;
    }
    try { if (typeof userTeamLoadFromServer === 'function') await userTeamLoadFromServer(); } catch (e) {}
    if (typeof tfShowToast === 'function') tfShowToast(_d.karar === 'accepted' ? '✅ Sözleşmen yenilendi' : '❌ Yenileme reddedildi', _d.karar === 'accepted' ? 'var(--accent)' : 'var(--red)');
    return;
  }

  // 👤 USER KAPTAN — inbox mesajı gönder
  const me = (authUser||{}).name || 'Oyuncu';
  const myUserId = (authUser||{}).id || null;
  const _f = v => v >= 1000000 ? (v/1000000).toFixed(1)+'M €' : v > 0 ? Math.round(v/1000)+'K €' : '0 €';
  const c = _userTeam.contract;
  const oldSalary = Number(c.seasonSalary || c.yearlySalary || 0);
  const firstSal = Number(c.firstSalary || oldSalary);
  const raiseSign = offer.raisePercent >= 0 ? '+' : '';

  const ok = await inboxSendToUser(captainUserId, {
    from: me,
    fromAvatar: '📋',
    type: 'contract_renewal_request',
    subject: `Sözleşme Yenileme Talebi — ${me}`,
    body: `${me} sözleşmesini yenilemek istiyor.\n\n📊 Sistemce hesaplanan yeni maaş:\n• Sezon maaşı: ${_f(offer.seasonSalary)} (${raiseSign}%${offer.raisePercent})\n• Mevcut maaş: ${_f(oldSalary)}\n• İlk imza maaşı: ${_f(firstSal)}\n• Taksit: ${_f(Math.round(offer.seasonSalary/4))} × 4 (gün 10/20/30/40)\n• Yeni bitiş: ${_currentRenewalOffer ? '' : ''}1 sezon uzatma\n\n• Onaylarsan: yeni maaşla devam\n• Reddedersen: oyuncu ${_f(firstSal)} ilk maaşa düşer + ayrılma serbestliği kazanır`,
    renewalRequest: {
      playerUserId: myUserId,
      playerName: me,
      teamCC: cc,
      teamName: tn,
      seasonSalary: offer.seasonSalary,
      oldSalary,
      firstSalary: firstSal,
      raisePercent: offer.raisePercent,
      status: 'pending',                // 'pending' | 'accepted' | 'rejected'
      sentAt: Date.now(),
    },
  });

  if (!ok) {
    if (typeof tfShowToast === 'function')
      tfShowToast('❌ Talep gönderilemedi', 'var(--red)');
    return;
  }

  // Oyuncunun kendi inbox'una "gönderildi" kaydı
  try {
    const msgs = getInboxMsgs();
    msgs.unshift({
      id: 'cr_sent_' + Date.now(),
      from: me,
      to: captainName,
      fromAvatar: '📤',
      type: 'system',
      subject: `Yenileme Talebi Gönderildi — ${tn}`,
      body: `Kaptan ${captainName}'a sözleşme yenileme talebi gönderdin.\n\n• Yeni maaş: ${_f(offer.seasonSalary)} (${raiseSign}%${offer.raisePercent})\n• Karar verildiğinde inbox'una bildirim gelir.`,
      time: new Date().toLocaleDateString('tr'),
      read: true,
      sent: true,
      thread: [],
    });
    saveInboxMsgs(msgs);
    if(typeof inboxUpdateBadge === 'function') inboxUpdateBadge();
  } catch(e){}

  if (typeof tfShowToast === 'function')
    tfShowToast(`✅ Talep gönderildi: ${captainName}`, 'var(--accent2)');
}




// 👑 KAPTAN TARAFI: Inbox mesajındaki "Onayla/Reddet" butonlarından çağrılır
// Oyuncunun players.user_team_data.contract'ını günceller + ona bildirim gönderir.
async function captainDecideRenewalRequest(msgId, decision) {
  if (!window.sb) return;
  // Mevcut inbox mesajını bul
  const msgs = getInboxMsgs();
  const msg = msgs.find(m => m.id === msgId);
  if (!msg || !msg.renewalRequest) {
    if (typeof tfShowToast === 'function') tfShowToast('❌ Mesaj bulunamadı', 'var(--red)');
    return;
  }
  const req = msg.renewalRequest;
  if (req.status !== 'pending') {
    if (typeof tfShowToast === 'function') tfShowToast('⚠️ Bu talep zaten karar verilmiş', '#ff9800');
    return;
  }
  if (!req.playerUserId) {
    if (typeof tfShowToast === 'function') tfShowToast('❌ Oyuncu kimliği eksik', 'var(--red)');
    return;
  }

  // 🔒 F3 · KARAR ARTIK SUNUCUDA.
  //   Eskiden burada BAŞKA bir oyuncunun `players.user_team_data` satırı
  //   doğrudan yazılıyordu: maaş/süre hiç doğrulanmıyordu ve RLS yüzünden
  //   zaten 0 satır etkiliyordu (özellik sessizce çalışmıyordu).
  //   Sunucu artık kaptanlığı doğruluyor, maaşı KENDİ hesaplıyor
  //   (aşağıdaki `req.seasonSalary` yalnızca gösterim için kullanılır)
  //   ve oyuncuya bildirimi de kendisi gönderiyor.
  let _rn = null;
  try {
    _rn = await edgeCall('decide_renewal', {
      player: req.playerUserId,
      karar: (decision === 'accept') ? 'accept' : 'reject'
    });
  } catch(e) {
    if (typeof tfShowToast === 'function') tfShowToast('❌ Bağlantı yok, tekrar dene', 'var(--red)');
    return;
  }
  const _rd = (_rn && _rn.data) || {};
  if (!_rn.ok || _rd.error) {
    const _m = {
      takim_yok: 'Bir takımda değilsin.',
      yetki_yok: 'Sadece kaptan karar verebilir.',
      oyuncu_bulunamadi: 'Oyuncu bulunamadı.',
      ayni_takimda_degil: 'Bu oyuncu artık takımında değil.',
      sozlesme_yok: 'Oyuncunun aktif sözleşmesi yok.',
      zaten_karar_verildi: 'Bu talebe zaten karar verilmiş.',
      talep_yok: 'Oyuncunun bu sezon gönderdiği bir yenileme talebi yok.',
      yenileme_zamani_degil: 'Oyuncunun sözleşmesi henüz yenileme döneminde değil.'
    }[_rd.error] || ('Karar kaydedilemedi: ' + (_rd.error || 'bilinmeyen'));
    if (typeof tfShowToast === 'function') tfShowToast('❌ ' + _m, 'var(--red)');
    if (_rd.error === 'sozlesme_yok' || _rd.error === 'ayni_takimda_degil') {
      msg.renewalRequest.status = 'invalid';
      saveInboxMsgs(msgs);
    }
    if (_rd.error === 'zaten_karar_verildi') {
      msg.renewalRequest.status = _rd.durum || 'accepted';
      saveInboxMsgs(msgs);
    }
    return;
  }

  // Kaptanın inbox'unda mesajı "karar verildi" olarak işaretle
  msg.renewalRequest.status = decision === 'accept' ? 'accepted' : 'rejected';
  msg.renewalRequest.decidedAt = Date.now();
  saveInboxMsgs(msgs);
  if (typeof inboxUpdateBadge === 'function') inboxUpdateBadge();

  if (typeof tfShowToast === 'function')
    tfShowToast(decision === 'accept' ? `✅ Yenileme onaylandı: ${req.playerName}` : `❌ Yenileme reddedildi: ${req.playerName}`,
                decision === 'accept' ? 'var(--accent)' : '#ff5722');

  // Mesaj detay açıksa yeniden render
  try {
    if (typeof inboxRenderDetail === 'function' && _inboxCurrentMsg && _inboxCurrentMsg.id === msgId) {
      _inboxCurrentMsg = msg;
      inboxRenderDetail();
    }
  } catch(e){}
}
// ═══════════════════════════════════════════════════════════════════



// ── 592 · Sözleşme süresi doldu bildirimi ──
//   Sözleşme silinmez: oyuncu takımda kalır, maaşı sürer, istediği an ayrılabilir (sunucu
//   ayrılırken süreye kendisi bakar). Bildirim sözleşme başına bir kez.
function checkContractExpiration() {
  if (typeof _userTeam === 'undefined' || !_userTeam || !_userTeam.contract) return;
  const c = _userTeam.contract, info = getSeasonInfo();
  if (info.preSeason || typeof c.endsSeason !== 'number' || c.endsSeason >= info.season) return;
  const teamName = _userTeam.teamName || '';
  sysMsg({
    id: 'sozlesme_bitti_' + teamName + '_' + c.endsSeason,
    from: '📋 Sözleşme Yönetimi', avatar: '🔓', kind: 'sozlesme',
    subject: `Sözleşmen Sona Erdi — ${teamName}`,
    body: `${teamName} ile sözleşmen ${c.endsSeason}. sezon sonunda doldu.\n\n`
        + `• Takımda kalmaya devam ediyorsun, maaşın ödenmeye devam eder.\n`
        + `• Artık istediğin an takımdan ayrılabilirsin.\n`
        + `• Kalmak istiyorsan Sözleşmem ekranından yenileme talebi gönder.`
  });
}

// ── Bot kaptanlı takım için "satın al yoluyla giriş" yönlendirme modal'ı ──
// Native confirm yerine oyunun stilinde styled modal (jcm-* sınıfları yeniden kullanılıyor)
let _bcwTarget = null;  // {cc, tn}

function showBotCaptainRedirectModal(cc, tn) {
  _bcwTarget = { cc, tn };
  const flag = (true && _cftGetCountry(cc)) ? (_cftGetCountry(cc).flag || '') : '';

  const teamEl = document.getElementById('bcwTeamName');
  if(teamEl) teamEl.textContent = `${flag} ${tn}`;

  const overlay = document.getElementById('botCapWarnOverlay');
  if(overlay) overlay.classList.add('open');
}

window.closeBotCapWarn = function(){
  const overlay = document.getElementById('botCapWarnOverlay');
  if(overlay) overlay.classList.remove('open');
  _bcwTarget = null;
};

window.goBuyTeamFromWarn = function(){
  if(!_bcwTarget) {
    closeBotCapWarn();
    return;
  }
  const { cc, tn } = _bcwTarget;

  // Modal'ları kapat
  closeBotCapWarn();
  if(typeof closeJoinConfirm === 'function') closeJoinConfirm();
  if(typeof closeTeamSearch  === 'function') closeTeamSearch();

  // Satın alma overlay'ini aç
  if(typeof openTeamBuy === 'function'){
    openTeamBuy();
    // İlgili ülkeye direkt git (kullanıcı ülke seçim ekranından geçmesin)
    if(cc && typeof tbmSelectCountry === 'function'){
      // Bir frame bekle ki overlay layout'u tamamlansın, sonra ülke seç
      requestAnimationFrame(() => {
        try { tbmSelectCountry(cc); } catch(e){}
        // İkinci frame'de hedef takımı vurgula (varsa)
        requestAnimationFrame(() => {
          try {
            const list = document.getElementById('tbmTeamList');
            if(!list) return;
            const cards = list.querySelectorAll('.tbm-team-card,[data-tn]');
            cards.forEach(c => {
              const cardName = c.dataset.tn || c.querySelector('.tbm-team-name')?.textContent || '';
              if(cardName.trim() === tn){
                c.scrollIntoView({behavior:'smooth', block:'center'});
                c.style.transition = 'box-shadow .3s';
                c.style.boxShadow = '0 0 0 2px #ff9800, 0 4px 16px rgba(255,152,0,.4)';
                setTimeout(() => { c.style.boxShadow = ''; }, 2400);
              }
            });
          } catch(e){}
        });
      });
    }
  } else if(typeof showPage === 'function'){
    // Fallback
    showPage('team-market', null);
  }
};

// ══════════════════════════════════════════════════════════════
// ŞARTLARLA KATILMA İSTEĞİ — MODAL & SUBMIT
// ══════════════════════════════════════════════════════════════

let _jrwtTarget = null;       // {countryCode, teamName, rating}
let _jrwtSeasons = 2;         // 1-3
let _jrwtSystemSalary = 0;    // sistem belirler (değiştirilemez)
let _jrwtMarketValue  = 0;    // kendi piyasa değerin (profil ile aynı)
let _jrwtSigningDia = 0;      // oyuncunun talep ettiği imza elması

function _jrwtFmt(v){
  if(!v) return '0 €';
  return v >= 1e6 ? (v/1e6).toFixed(2)+'M €'
       : v >= 1e3 ? Math.round(v/1e3)+'K €'
                  : v+' €';
}

window.openJoinRequestWithTermsModal = function(cc, tn, rating){
  // Önce takımsız olduğunu kontrol et
  if(typeof _userTeam !== 'undefined' && _userTeam){
    if(typeof showJoinToast === 'function') {
      showJoinToast('⚠️ Önce mevcut takımdan ayrıl, sonra istek gönderebilirsin.');
    } else {
      alert('Önce mevcut takımdan ayrıl, sonra istek gönderebilirsin.');
    }
    return;
  }

  _jrwtTarget = { countryCode: cc, teamName: tn, rating };
  _jrwtSeasons = 2;
  const _mePlayer = (typeof ROSTER_DATA !== 'undefined' && Array.isArray(ROSTER_DATA))
    ? ROSTER_DATA.find(p => p && p.role === 'user' && !p.isBot) : null;
  _jrwtSystemSalary = (typeof getSystemPlayerSalary === 'function') ? getSystemPlayerSalary(_mePlayer || rating) : 0;
  _jrwtMarketValue  = (_mePlayer && typeof getPlayerMarketValue === 'function') ? getPlayerMarketValue(_mePlayer) : 0;
  _jrwtSigningDia = 0;
  const _diaIn = document.getElementById('jrwtSigningDiamond');
  if(_diaIn) _diaIn.value = '';

  const flag = (true && _cftGetCountry(cc)) ? (_cftGetCountry(cc).flag || '') : '';
  const captainName = (typeof getTeamRealCaptainName === 'function')
    ? getTeamRealCaptainName(cc, tn) : 'Kaptan';

  const teamEl = document.getElementById('jrwtTeamName');
  if(teamEl) teamEl.textContent = `${flag} ${tn} · Kaptan: ${captainName}`;

  // Sezon pillerini sıfırla (default: 2)
  document.querySelectorAll('#jrwtOverlay .jrwt-season-pill').forEach(p => {
    p.classList.toggle('active', p.dataset.seasons === '2');
  });

  // İlk hesap
  _jrwtUpdateSummary();

  document.getElementById('jrwtOverlay').classList.add('open');
};

window.closeJoinRequestWithTerms = function(){
  document.getElementById('jrwtOverlay').classList.remove('open');
  _jrwtTarget = null;
};

window._jrwtSelectSeasons = function(n){
  _jrwtSeasons = n;
  document.querySelectorAll('#jrwtOverlay .jrwt-season-pill').forEach(p => {
    p.classList.toggle('active', parseInt(p.dataset.seasons) === n);
  });
  _jrwtUpdateSummary();
};

window._jrwtUpdateSummary = function(){
  const diaEl = document.getElementById('jrwtSigningDiamond');
  _jrwtSigningDia = Math.max(0, parseInt((diaEl||{}).value) || 0);
  const salary = Number(_jrwtSystemSalary) || 0;
  const inst   = Math.round(salary / 4);
  const set = (id, v) => { const el = document.getElementById(id); if(el) el.textContent = v; };
  set('jrwtSalaryDisplay', _jrwtFmt(salary) + ' /sezon');
  set('jrwtPayD10', _jrwtFmt(inst)); set('jrwtPayD20', _jrwtFmt(inst));
  set('jrwtPayD30', _jrwtFmt(inst)); set('jrwtPayD40', _jrwtFmt(inst));
  set('jrwtSumSalary', _jrwtFmt(salary));
  set('jrwtSumDia',    _jrwtSigningDia.toLocaleString('tr-TR') + ' 💎');
  set('jrwtSumDur',    `${_jrwtSeasons} sezon`);
  set('jrwtBonservisDisplay', _jrwtMarketValue > 0
    ? ('Piyasa değeri: ' + _jrwtFmt(_jrwtMarketValue) + ' · serbest, ödenmez')
    : 'Serbest oyuncu · bonservis yok');
};

window.submitJoinRequestWithTerms = async function(){
  if(!_jrwtTarget) return;
  const cc = _jrwtTarget.countryCode;
  const tn = _jrwtTarget.teamName;

  const signingDia = Math.max(0, parseInt((document.getElementById('jrwtSigningDiamond')||{}).value) || 0);
  const salary = Math.max(0, Number(_jrwtSystemSalary) || 0);  // sistem belirler
  const bonus  = 0;                                            // serbest → bonservis yok

  if(salary <= 0){
    showInfoModal({icon:'⚠️',iconColor:'#f59e0b',title:'Maaş Hesaplanamadı',subtitle:'Oyuncu seviyesi geçersiz, sayfayı yenile.',body:''});
    return;
  }
  if(_jrwtSeasons < 1 || _jrwtSeasons > 4){
    showInfoModal({icon:'⚠️',iconColor:'#f59e0b',title:'Geçersiz Süre',subtitle:'Sözleşme süresi 1-4 sezon arasında olmalı.',body:''});
    return;
  }

  // 🆕 Kadro dolu mu? — Server'dan taze kontrol
  if (typeof _loadRealCaptainsFromServer === 'function') {
    _invalidateRealCaptainsCache();
    try { await _loadRealCaptainsFromServer(cc); } catch(e) {}
  }
  // 768 — sınır takımın kendi kapasitesinden (14 + Takım Kapasitesi seviyesi) ve mevki kontenjanından
  const _engel = (typeof window._mkBasvuruEngel === 'function') ? await window._mkBasvuruEngel(cc, tn).catch(() => null) : null;
  if (_engel && _engel.tur === 'mevki') {
    if (typeof showJoinToast === 'function') showJoinToast('⛔ ' + _engel.metin);
    return;
  }
  const realMemberCount = _engel ? _engel.gercek : 0;
  if (_engel && _engel.tur === 'kadro') {
    showInfoModal({
      icon: '👥', iconColor: '#f59e0b',
      title: 'Kadro Dolu',
      subtitle: `${tn} takımı şu an dolu`,
      body: `
        <div class="info-modal-rows">
          <div class="info-modal-row">
            <div class="info-modal-row-ic">📊</div>
            <div class="info-modal-row-body">
              <div class="info-modal-row-lbl">Mevcut Üye</div>
              <div class="info-modal-row-val">${realMemberCount} oyuncu</div>
            </div>
          </div>
        </div>
        <div class="info-modal-note">💡 Bu takımın kaptanı kadrosunu büyütmediği için yeni istek kabul edilemez. Başka bir takım dene veya bekle.</div>`
    });
    return;
  }

  const flag = (true && _cftGetCountry(cc)) ? (_cftGetCountry(cc).flag || '') : '';

  // Kullanıcı kimliğini al
  let myUserId = (window.authUser || {}).id;
  if (!myUserId && window.sb) {
    try {
      const { data: { user } } = await window.sb.auth.getUser();
      if (user) {
        myUserId = user.id;
        if (!window.authUser) window.authUser = {};
        window.authUser.id = myUserId;
      }
    } catch(e) { console.warn('[join-req] auth çekme hatası:', e); }
  }
  // 🆕 myName HER ZAMAN profilden taze çekilir (cache eski/Oyuncu olabilir)
  let myName = null;
  if (myUserId && window.sb) {
    try {
      const { data: prof } = await window.sb.from('profiles').select('name, username').eq('id', myUserId).maybeSingle();
      if (prof) {
        myName = prof.name || prof.username;
        if (myName) window.authUser.name = myName;
      }
    } catch(e) { console.warn('[join-req] profile çekme hatası:', e); }
  }
  if (!myName) myName = (window.authUser || {}).name || 'Oyuncu';

  const captainName = (typeof getTeamRealCaptainName === 'function')
    ? getTeamRealCaptainName(cc, tn) : 'Kaptan';

  // 1) Bekleyen istek listesine kaydet (Supabase tabanlı)
  try {
    const list = getJoinRequests().slice();
    // Aynı takıma daha önce gönderilmişse atla
    if(list.some(r => r.countryCode === cc && r.teamName === tn && r.status === 'pending')){
      alert(`⚠️ ${flag} ${tn} takımına zaten bekleyen bir isteğin var.`);
      return;
    }
    list.unshift({
      id: 'jr_' + Date.now(),
      countryCode: cc,
      teamName: tn,
      flag,
      sentAt: Date.now(),
      sentDate: new Date().toLocaleDateString('tr'),
      status: 'pending',
      terms: {
        signingBonus: 0,
        signingDiamond: signingDia,
        seasonSalary: salary,
        yearlySalary: salary,
        durationSeasons: _jrwtSeasons,
      },
    });
    saveJoinRequests(list);
  } catch(e){
    alert('Hata: ' + e.message);
    return;
  }

  const reqId = 'jr_msg_' + Date.now();
  const fmt = _jrwtFmt;

  // 2) Kullanıcının inbox'ına "gönderildi" mesajı (kendi kayıt kopyası)
  try {
    const msgs = (typeof getInboxMsgs === 'function') ? getInboxMsgs() : [];
    msgs.unshift({
      id: reqId + '_sent',
      from: myName,
      to: tn + ' Yönetimi',
      fromAvatar: '🤝',
      type: 'join_request',
      subject: `Katılma İsteği — ${tn}`,
      body: `${flag} ${tn} takımına şartlarla katılma isteği gönderdin.\n\n• İmza Talebi: ${signingDia} 💎\n• Sezon Maaşı: ${fmt(salary)}\n• Süre: ${_jrwtSeasons} sezon\n\nKaptan veya yardımcı kaptan onaylarsa sözleşme imzalanacak. Yanıt geldiğinde bilgilendirileceksin.`,
      time: new Date().toLocaleDateString('tr'),
      read: true,
      thread: [],
      sent: true,
      joinReqData: { countryCode: cc, teamName: tn },
    });
    if(typeof saveInboxMsgs === 'function') saveInboxMsgs(msgs);
  } catch(e){}

  // 3) Kaptanın inbox'una gönder (Supabase üzerinden gerçek kullanıcıya)
  try {
    // Kaptanın user_id'sini cache'ten al (önce taze veri için yenile)
    if (typeof _loadRealCaptainsFromServer === 'function') {
      _invalidateRealCaptainsCache();
      await _loadRealCaptainsFromServer(cc);
    }
    const key = cc + ':' + tn;
    const entry = _realCaptainsCache[key];
    const captainUserId = entry ? entry.captainUserId : null;

    // 828 — istek kaptanla birlikte takımın bütün gerçek yardımcı kaptanlarına da gider (ilk karar veren geçerli)
    const _yoneticiler = captainUserId ? [captainUserId] : [];
    try {
      const { data: _yrd } = await window.sb.from('players').select('user_id').eq('country_code', cc).eq('team_name', tn)
        .eq('role', 'vice').eq('is_bot', false).not('user_id', 'is', null);
      (_yrd || []).forEach(v => { if (v.user_id && v.user_id !== myUserId && !_yoneticiler.includes(v.user_id)) _yoneticiler.push(v.user_id); });
    } catch(e) {}
    if (_yoneticiler.length && typeof inboxSendToUser === 'function') {
      for (const _yid of _yoneticiler) await inboxSendToUser(_yid, {
        id: reqId + '_incoming',
        from: myName,
        fromAvatar: '🤝',
        type: 'join_request_incoming',
        subject: `Katılma İsteği — ${myName}`,
        body: `${myName} adlı oyuncu ${flag} ${tn} takımına katılmak istiyor.\n\nÖnerdiği şartlar:\n• İmza Talebi: ${signingDia} 💎\n• Sezon Maaşı: ${fmt(salary)}\n• Süre: ${_jrwtSeasons} sezon\n\nKaptan veya yardımcı kaptan olarak onaylayabilir veya reddedebilirsin.`,
        joinReqIncomingData: {
          requestorUserId: myUserId,
          requestorName: myName,
          countryCode: cc,
          teamName: tn,
          signingBonus: 0,
          signingDiamond: signingDia,
          seasonSalary: salary,
          yearlySalary: salary,
          durationSeasons: _jrwtSeasons,
        },
      });
    }
  } catch(e){ console.warn('[join-req] kaptan inbox hata:', e); }

  closeJoinRequestWithTerms();
  if(typeof closeTeamSearch === 'function') closeTeamSearch();
  if (typeof sctRaporYenile === 'function') sctRaporYenile();   // 829

  if(typeof showJoinToast === 'function'){
    showJoinToast(`📨 ${flag} ${tn} kaptanına katılma isteği gönderildi`);
  }
};

// ══════════════════════════════════════════════════════════════
// KAPTAN TARAFI — Gelen isteği ONAYLA / REDDET
// ══════════════════════════════════════════════════════════════

// 828 — isteğe başka bir yönetici (kaptan / yardımcı) senden önce karar verdi: kopya güncellenir, kimin verdiği gösterilir
function _jrKararGeldi(msg, msgs, durum, veren) {
  const red = durum === 'rejected';
  msg.offerStatus = red ? 'rejected' : 'approved';
  msg.kararVeren = veren || null;
  msg.read = true;
  if (typeof saveInboxMsgs === 'function') saveInboxMsgs(msgs);
  if (typeof inboxUpdateBadge === 'function') inboxUpdateBadge();
  if (typeof inboxRenderDetail === 'function') inboxRenderDetail(msg);
  showInfoModal({ icon: red ? '❌' : '✅', iconColor: red ? '#ef4444' : '#22c55e',
    title: red ? 'Zaten Reddedildi' : 'Zaten Onaylandı',
    subtitle: veren ? `${veren} senden önce karar verdi.` : 'Bu isteğe başka bir yönetici karar verdi.', body: '' });
}

window.inboxApproveJoinRequest = async function(msgId){
  const msgs = (typeof getInboxMsgs === 'function') ? getInboxMsgs() : null;
  if(!msgs) return;
  const idx = msgs.findIndex(m => m.id === msgId);
  if(idx === -1) return;
  const msg = msgs[idx];
  const d   = msg.joinReqIncomingData;
  if(!d) return;

  if(!d.requestorUserId){
    showInfoModal({
      icon:'⚠️', iconColor:'#f59e0b',
      title:'Eski Format Mesaj',
      subtitle:'Bu istek mesajında kullanıcı ID yok',
      body:'<div class="info-modal-note">Bu istek, sistem güncellemesinden önce gönderilmiş. Oyuncudan yeni istek göndermesini iste.</div>'
    });
    return;
  }

  const captainName = (typeof getTeamRealCaptainName === 'function')
    ? getTeamRealCaptainName(d.countryCode, d.teamName) : 'Kaptan';
  const myUserId = (window.authUser || {}).id;
  if(!myUserId){
    showInfoModal({icon:'⚠️',iconColor:'#f59e0b',title:'Oturum Hazır Değil',subtitle:'Sayfayı yenileyip tekrar deneyin',body:''});
    return;
  }

  // 🆕 Edge Function çağrısı — atomik işlem, RLS bypass
  const SUPABASE_URL = 'https://fkmpkfhikhludkgrzvtd.supabase.co';
  let resData = null;
  try {
    const session = await window.sb.auth.getSession();
    const token = session?.data?.session?.access_token;
    const resp = await fetch(SUPABASE_URL + '/functions/v1/approve-join-request', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + (token || ''),
      },
      body: JSON.stringify({
        requestor_user_id: d.requestorUserId,
        captain_user_id: myUserId,
        country_code: d.countryCode,
        team_name: d.teamName,
        signing_bonus: 0,
        signing_diamond: d.signingDiamond || 0,
        yearly_salary: (d.seasonSalary != null ? d.seasonSalary : (d.yearlySalary || 0)),
        duration_seasons: d.durationSeasons || 1,
        captain_name: captainName,
      })
    });
    resData = await resp.json();
    console.info('[approve] edge function sonuç:', resData);
  } catch(e){
    console.error('[approve] edge function exception:', e);
    showInfoModal({icon:'❌',iconColor:'#ef4444',title:'Bağlantı Hatası',subtitle:'Onay servisi yanıt vermedi',body:'<div class="info-modal-note">İnternet bağlantını kontrol et, tekrar dene.</div>'});
    return;
  }

  if (resData && resData.error === 'already_decided') { _jrKararGeldi(msg, msgs, resData.durum, resData.veren); return; }   // 828
  if(!resData || !resData.ok){
    const errMap = {
      missing_params: { t:'Eksik Bilgi', s:'Form alanlarını kontrol et' },
      captain_not_in_team: { t:'Yetkin Yok', s:'Bu takımın kaptanı değilsin' },
      captain_team_mismatch: { t:'Takım Uyumsuz', s:'Sen artık bu takımın kaptanı değilsin' },
      not_authorized: { t:'Yetki Yok', s:'Sadece kaptan veya yardımcı kaptan onaylayabilir' },
      requestor_not_found: { t:'Oyuncu Bulunamadı', s:'İstek yapan kullanıcı sistemde yok' },
      already_in_team: { t:'Zaten Takımda', s:'Bu oyuncu zaten takımda' },
      insufficient_treasury: { t:'Yetersiz Bakiye', s:`Kasada ${resData.treasury}€, gereken ${resData.needed}€` },
      insufficient_diamond: { t:'Yetersiz Elmas', s:`İmza elması için kasada yeterli elmas yok (mevcut: ${resData.treasury||0} 💎)` },
      roster_full: { t:'Kadro Dolu', s:`${resData.current} / ${resData.max} oyuncu — önce kadroda yer aç` },
      players_update_failed: { t:'Veritabanı Hatası', s:resData.detail || 'Oyuncu kaydı yazılamadı' },
      no_pending_request: { t:'İstek Bulunamadı', s:'Oyuncunun bu takıma bekleyen bir isteği yok (geri çekilmiş, onaylanmış ya da 14 günü geçmiş olabilir)' },
      terms_mismatch: { t:'Şartlar Değişmiş', s:'İsteğin şartları değişmiş. Oyuncudan yeni istek göndermesini iste.' },
      requestor_contract_active: { t:'Sözleşmesi Sürüyor', s:'Oyuncunun başka bir takımla sözleşmesi sürüyor' },
    };
    const _mdm = (typeof _mevkiDoluMetin === 'function') ? _mevkiDoluMetin(String(resData.detail || resData.error || '')) : null;   // 686
    const e = /yabanci_dolu/.test(String(resData.detail || resData.error || '')) ? { t:'Yabancı Kontenjanı Dolu', s:'Takımının yabancı oyuncu kontenjanı dolu (10/10).' }
      : _mdm ? { t:'Mevki Kontenjanı Dolu', s:_mdm }
      : errMap[resData.error] || { t:'Hata', s:resData.error || 'Bilinmeyen hata' };
    showInfoModal({icon:'❌',iconColor:'#ef4444',title:e.t,subtitle:e.s,body:''});
    return;
  }

  // BAŞARILI ✅
  // Kaptanın UI'sını güncelle (kasa, inbox, real captains cache)
  msg.offerStatus = 'approved';
  msg.kararVeren = resData.karar_veren || null;   // 828
  msg.read = true;
  if(typeof saveInboxMsgs === 'function') saveInboxMsgs(msgs);
  if(typeof _trsLoadFromServer === 'function') await _trsLoadFromServer();
  if(typeof _inboxLoadFromServer === 'function') await _inboxLoadFromServer();
  if(typeof _invalidateRealCaptainsCache === 'function') _invalidateRealCaptainsCache();
  if(typeof trsSyncHeader === 'function') trsSyncHeader();
  if(typeof inboxUpdateBadge === 'function') inboxUpdateBadge();
  if(typeof inboxRenderDetail === 'function') inboxRenderDetail(msg);
  // 🆕 Kadroyu sunucudan tazele → onaylanan oyuncu kaptanın ekranında ANINDA görünür (sayfa yenilemeye gerek yok)
  if(typeof rosterBuildTeam === 'function' && _userTeam && _userTeam.countryCode){ try{ rosterBuildTeam(_userTeam.countryCode); }catch(e){} }
  if(typeof applyUserTeamUI === 'function') applyUserTeamUI();

  // Toast
  try {
    const fmt = (v) => v >= 1e6 ? (v/1e6).toFixed(2)+'M €' : Math.round(v/1000)+'K €';
    const t = document.createElement('div');
    t.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:linear-gradient(135deg,#00c853,#43a047);color:#fff;padding:14px 24px;border-radius:24px;font-size:14px;font-weight:700;z-index:9999;font-family:Twemoji Country Flags,"Barlow Condensed",sans-serif;letter-spacing:.4px;box-shadow:0 8px 24px rgba(0,0,0,.4)';
    const _dia = Number(d.signingDiamond) || 0;   // 681 — kasadan düşen imza elması (€ imza bonusu yok)
    t.textContent = _dia > 0 ? `✅ ${resData.requestor_name} takıma katıldı! ${_dia.toLocaleString('tr')} 💎 kasadan ödendi.`
                             : `✅ ${resData.requestor_name} takıma katıldı!`;
    document.body.appendChild(t);
    setTimeout(() => { t.style.transition='opacity .4s'; t.style.opacity='0'; setTimeout(()=>t.remove(),400); }, 3500);
  } catch(e){}
};


window.inboxRejectJoinRequest = async function(msgId){
  const msgs = (typeof getInboxMsgs === 'function') ? getInboxMsgs() : null;
  if(!msgs) return;
  const msg = msgs.find(m => m.id === msgId);
  const d = msg && msg.joinReqIncomingData;
  if(!d) return;
  const myUserId = (window.authUser || {}).id;
  if(!d.requestorUserId || !myUserId){
    showInfoModal({icon:'⚠️',iconColor:'#f59e0b',title:'Oturum Hazır Değil',subtitle:'Sayfayı yenileyip tekrar deneyin',body:''});
    return;
  }
  // 828 — red de sunucudan: ilk karar geçerli, oyuncuya red mesajını ve diğer yöneticilerin kopyalarını sunucu işler
  let r = null;
  try {
    const session = await window.sb.auth.getSession();
    const token = session?.data?.session?.access_token;
    const resp = await fetch('https://fkmpkfhikhludkgrzvtd.supabase.co/functions/v1/approve-join-request', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + (token || '') },
      body: JSON.stringify({ karar: 'red', requestor_user_id: d.requestorUserId, captain_user_id: myUserId, country_code: d.countryCode, team_name: d.teamName })
    });
    r = await resp.json();
  } catch(e) {
    showInfoModal({icon:'❌',iconColor:'#ef4444',title:'Bağlantı Hatası',subtitle:'Onay servisi yanıt vermedi',body:'<div class="info-modal-note">İnternet bağlantını kontrol et, tekrar dene.</div>'});
    return;
  }
  if (r && r.error === 'already_decided') { _jrKararGeldi(msg, msgs, r.durum, r.veren); return; }
  if (!r || (!r.ok && r.error !== 'no_pending_request')) {   // süresi geçmiş / geri çekilmiş istekte yalnız kopya kapanır
    const e = {
      not_authorized: { t:'Yetki Yok', s:'Sadece kaptan veya yardımcı kaptan onaylayabilir' },
      captain_not_in_team: { t:'Yetkin Yok', s:'Bu takımın kaptanı değilsin' },
      captain_team_mismatch: { t:'Takım Uyumsuz', s:'Sen artık bu takımın kaptanı değilsin' },
    }[r && r.error] || { t:'Bağlantı Hatası', s:'Onay servisi yanıt vermedi' };
    showInfoModal({icon:'❌',iconColor:'#ef4444',title:e.t,subtitle:e.s,body:''});
    return;
  }
  msg.offerStatus = 'rejected';
  msg.kararVeren = (r && r.karar_veren) || null;
  msg.read = true;
  if(typeof saveInboxMsgs === 'function') saveInboxMsgs(msgs);
  if(typeof inboxUpdateBadge === 'function') inboxUpdateBadge();
  if(typeof inboxRenderDetail === 'function') inboxRenderDetail(msg);

  try {
    const t = document.createElement('div');
    t.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:#ef5350;color:#fff;padding:12px 22px;border-radius:24px;font-size:13px;font-weight:700;z-index:9999;font-family:Twemoji Country Flags,"Barlow Condensed",sans-serif;letter-spacing:.4px;box-shadow:0 8px 24px rgba(0,0,0,.4)';
    t.textContent = `❌ İstek reddedildi.`;
    document.body.appendChild(t);
    setTimeout(() => t.remove(), 2400);
  } catch(e){}
};

// Maç sonu moral güncelleme (processMatchOutcome'dan çağrılır)
function applyMatchMorale(script, userIsHome) {
  if (!script || !script.evs || typeof ROSTER_DATA === 'undefined') return;

  const userSide = userIsHome ? 'home' : 'away';
  const userScore = userIsHome ? (MS.scoreH || 0) : (MS.scoreA || 0);
  const oppScore  = userIsHome ? (MS.scoreA || 0) : (MS.scoreH || 0);
  const matchResult = userScore > oppScore ? 'win' : (userScore < oppScore ? 'loss' : 'draw');

  // Sahaya çıkan top 11 (bench değil) — match etkisi
  const eligible = ROSTER_DATA.filter(p => !isPlayerSuspended(p) && !isPlayerInjured(p));
  const top11 = eligible.sort((a,b) => (b.overall||0) - (a.overall||0)).slice(0, 11);
  const top11Set = new Set(top11.map(p => p.num));

  // Top 11 için sonuç bonusu
  top11.forEach(p => {
    if (matchResult === 'win') adjustMorale(p, 5, 'Galibiyet');
    else if (matchResult === 'loss') adjustMorale(p, -8, 'Mağlubiyet');
    // beraberlik: 0
  });

  // Yedek kalanlar -1 moral
  ROSTER_DATA.forEach(p => {
    if (!top11Set.has(p.num) && !isPlayerSuspended(p) && !isPlayerInjured(p)) {
      adjustMorale(p, -1, 'Yedek kaldı');
    }
  });

  // Olay bazlı moral
  const userEvs = script.evs.filter(e => e.team === userSide);
  userEvs.forEach(ev => {
    // Oyuncu adından eşleştir
    const evPlayer = (ev.player || '').toLowerCase();
    const matched = top11.find(p => {
      const np = (p.name || '').toLowerCase();
      return np === evPlayer || np.startsWith(evPlayer.split(' ')[0]);
    });
    if (!matched) return;

    if (ev.type === 'goal' && !ev.isOwnGoal) adjustMorale(matched, 6, 'Gol attı');
    else if (ev.type === 'yellow') adjustMorale(matched, -3, 'Sarı kart');
    else if (ev.type === 'red') adjustMorale(matched, -10, 'Kırmızı kart');
    else if (ev.type === 'injury') adjustMorale(matched, -8, 'Sakatlandı');
    else if (ev.type === 'save') adjustMorale(matched, 1, 'Kurtarış');

    // Asist
    if (ev.assist && ev.type === 'goal' && !ev.isOwnGoal) {
      const assister = top11.find(p => {
        const np = (p.name || '').toLowerCase();
        const ap = (ev.assist || '').toLowerCase();
        return np === ap || np.startsWith(ap.split(' ')[0]);
      });
      if (assister) adjustMorale(assister, 3, 'Asist yaptı');
    }
  });
}



// 🆕 shortenPlayerName eski isim kısaltma yardımcısı — kart event eşleştirmesi Edge'e
// taşındığı için artık kullanılmıyor (event.player adı doğrudan players tablosuyla eşleşir).

// 🆕 _matchEventPlayer — eski isim eşleştirme yardımcısı, Edge function _processMatchDiscipline
// kullanmıyor (direkt name eşleşmesi). Frontend processMatchOutcome'tan da çıkarıldı.

// Maç sonu: oyuncu istatistiklerini güncelle (moral, stamina, ratings)
// 🆕 Disiplin (kart/sakatlık) Edge function _processMatchDiscipline tarafından işlenir.
// Frontend tarafında ROSTER_DATA in-memory güncellemesi gerekmiyor — bir sonraki
// _loadTeamRosterFromServer ile yeni veri çekilir (sayfa açıldığında veya bootstrap'ta).
function processMatchOutcome(script, userIsHome) {
  if(!script || !script.evs) return;
  if(typeof ROSTER_DATA === 'undefined' || !ROSTER_DATA.length) return;

  // Oyuncu morali güncelle
  if (typeof applyMatchMorale === 'function') {
    try { applyMatchMorale(script, userIsHome); } catch(e) {}
  }

  // Stamina güncelle (yorgunluk düşüşü + dinlenme)
  if (typeof applyMatchStamina === 'function') {
    try {
      // İlk 11'de sahaya çıkanları al
      const userTeam = userIsHome ? curHome : curAway;
      const startersNums = (userTeam && userTeam.players)
        ? userTeam.players.map(p => p.num)
        : [];
      // Sub history'yi MS state'inden topla
      const subs = (MS.subsHistory || []).map(s => ({
        outNum: s.outNum, inNum: s.inNum, minute: s.minute || 60
      }));
      // Strateji
      const strat = (MS.tactic && (userIsHome ? MS.tactic.home : MS.tactic.away))
        ? (userIsHome ? MS.tactic.home.strategy : MS.tactic.away.strategy)
        : null;
      applyMatchStamina(strat, startersNums, subs);
    } catch(e) { console.warn('Stamina uygulanamadı:', e); }
  }

  // 6d) Bireysel maç notları KALDIRILDI — reyting TEK kaynak: Edge (players.match_ratings).
  //   Frontend ratePlayers/_recordMatchToSupabase çift hesap+yazma idi (çakışma+yük), silindi.

  // 🆕 7) MAÇ XP KAZANIMI — kullanıcı oyuncusu için
  try {
    const userPlayer = ROSTER_DATA.find(p => p.role === 'user' && !p.isBot);
    if (userPlayer && !MS._isFriendly) {
      // Maç katılım: 30 XP
      let totalXp = 30;
      let bonuses = [];

      // Kullanıcının kendi olayları (sahaya çıktıysa)
      const meName = userPlayer.name;
      const myEvs = userEvs.filter(ev => {
        const evPlayer = (ev.player || '').toLowerCase();
        return evPlayer === meName.toLowerCase()
            || evPlayer.includes(meName.split(' ')[0].toLowerCase());
      });

      // Gol = +50 XP
      const goals = myEvs.filter(e => e.type === 'goal' && !e.isOwnGoal).length;
      if (goals > 0) { totalXp += goals * 50; bonuses.push(`${goals} gol +${goals*50}XP`); }

      // Asist = +30 XP (e.assist alanı kontrol)
      const assists = userEvs.filter(e =>
        e.assist && e.assist.toLowerCase().includes(meName.split(' ')[0].toLowerCase()) && e.type === 'goal'
      ).length;
      if (assists > 0) { totalXp += assists * 30; bonuses.push(`${assists} asist +${assists*30}XP`); }

      // Galibiyet bonusu = +20 XP
      const userScore = userIsHome ? (MS.scoreH || 0) : (MS.scoreA || 0);
      const oppScore  = userIsHome ? (MS.scoreA || 0) : (MS.scoreH || 0);
      if (userScore > oppScore) { totalXp += 20; bonuses.push('Galibiyet +20XP'); }
      else if (userScore === oppScore) { totalXp += 5; bonuses.push('Beraberlik +5XP'); }

      // Kart cezası (Fix 8: motor 'yellow/red', CFC 'yellowCard/redCard' destekle)
      const yellowCnt = myEvs.filter(e => e.type === 'yellow' || e.type === 'yellowCard').length;
      const redCnt = myEvs.filter(e => e.type === 'red' || e.type === 'redCard').length;
      if (yellowCnt > 0) { totalXp = Math.max(0, totalXp - yellowCnt * 5); }
      if (redCnt > 0) { totalXp = Math.max(0, totalXp - 20); }

      // 🆕 Maç istatistiklerini MS._userStats'e yaz (cft_user_match_log için)
      MS._userStats = {
        goals,
        assists,
        yellowCards: yellowCnt,
        redCards: redCnt,
        played: true,
        xpEarned: totalXp,
      };

      if (totalXp > 0 && typeof rosterAwardXp === 'function') {
        const result = rosterAwardXp(userPlayer.num, totalXp);
        // Maç XP log'u
        try {
          const xpLog = getUserXpLog();
          xpLog.push({
            ts: Date.now(),
            player: meName,
            totalXp,
            bonuses,
            leveled: result.leveled,
            newLevel: result.newLevel,
          });
          saveUserXpLog(xpLog.slice(-50));
        } catch(e) {}

        // İnbox bildirimi (level atladıysa)
        if (result.leveled && typeof getInboxMsgs === 'function') {
          try {
            const inbox = getInboxMsgs();
            inbox.unshift({
              id: 'levelup_' + Date.now(),
              from: '🎯 Antrenör',
              subject: `Seviye ${result.newLevel}'a Yükseldin!`,
              body: `Tebrikler! Maçtaki performansınla ${totalXp} XP kazanarak ${result.newLevel}. seviyeye yükseldin.\n\nKazandığın bonuslar:\n${bonuses.join('\n')}`,
              ts: Date.now(),
              read: false,
              type: 'system'
            });
            saveInboxMsgs(inbox);
            if (typeof inboxUpdateBadge === 'function') inboxUpdateBadge();
          } catch(e) {}
        }
      }
    }
  } catch(e) { console.warn('Maç XP kazanım hatası:', e); }

  // 8) Persist + UI tazele
  if(typeof rosterSavePersist === 'function') rosterSavePersist();
  if(typeof renderRoster === 'function') {
    const rosterEl = document.getElementById('rosterList');
    if(rosterEl) renderRoster(typeof rosterCurrentFilter !== 'undefined' ? (rosterCurrentFilter || 'all') : 'all');
  }
}


