// ═══════════════════════════════════════════════════════════════════
//  FAZ 3 — DRAMA & ÇEŞİTLİLİK
//  • Hava durumu  • Form momentum  • Taraftar atmosferi  • Olay çeşitliliği
//  Her sistem MatchContext'e katkı verir, generateScript okur
// ═══════════════════════════════════════════════════════════════════

// ───── HAVA DURUMU ─────
const WEATHER_TYPES = {
  'sunny':   { label: '☀️ Güneşli',  atk: 1.00, def: 1.00, foul: 1.00, accuracy: 1.00, surprise: 1.00, weight: 35 },
  'cloudy':  { label: '⛅ Bulutlu',   atk: 0.99, def: 1.00, foul: 1.00, accuracy: 0.99, surprise: 1.00, weight: 25 },
  'rain':    { label: '🌧️ Yağmurlu', atk: 0.92, def: 1.05, foul: 1.10, accuracy: 0.88, surprise: 1.15, weight: 20 },
  'storm':   { label: '⛈️ Fırtına',  atk: 0.85, def: 1.10, foul: 1.20, accuracy: 0.78, surprise: 1.25, weight: 8 },
  'snow':    { label: '❄️ Karlı',    atk: 0.88, def: 1.08, foul: 1.15, accuracy: 0.82, surprise: 1.20, weight: 5 },
  'hot':     { label: '🔥 Sıcak',    atk: 0.95, def: 0.97, foul: 1.05, accuracy: 0.95, surprise: 1.05, weight: 7 }
};

function pickWeather(seed) {
  // Geriye dönük uyumluluk için → tarih ve ülke kullanmadan deterministik seçim
  return pickWeatherForDate(seed, new Date(), 'TR');
}

// 🆕 Mevsimsel hava — gerçek tarih + ülke iklimine göre olasılık dağılımı değişir
//   Kuzey yarımküre (varsayılan): kuzey enlemler / Türkiye / Avrupa
//   Yaz: güneşli + sıcak yüksek, kar yok
//   Kış: yağmur + kar yüksek, sıcak yok
//   Bahar/sonbahar: dengeli + bulutlu/yağmur ağırlıklı
function _seasonalWeights(date, cc) {
  // Ülke iklim kategorisi
  const TROPICAL = new Set(['BR', 'AR']);    // Güney yarımküre / sıcak iklim
  const HOT_DRY  = new Set(['TR']);           // Akdeniz / yarı-kurak
  const NORDIC   = new Set(['SE', 'NO', 'FI', 'DK', 'IS']); // Soğuk Kuzey
  const isSouthern = TROPICAL.has(cc);

  let month = date.getMonth(); // 0-11
  // Güney yarımküre için ay'ı 6 ay kaydır (Ocak=Temmuz vb.)
  if (isSouthern) month = (month + 6) % 12;

  // Mevsim: 0=kış (Ara-Şub), 1=ilkbahar (Mar-May), 2=yaz (Haz-Ağu), 3=sonbahar (Eyl-Kas)
  let season;
  if (month === 11 || month <= 1) season = 0;       // kış
  else if (month >= 2 && month <= 4) season = 1;    // ilkbahar
  else if (month >= 5 && month <= 7) season = 2;    // yaz
  else season = 3;                                   // sonbahar

  // Temel ağırlıklar — hot_dry ülkelerde yaz çok daha sıcak
  const isHotDry = HOT_DRY.has(cc);
  const isNordic = NORDIC.has(cc);

  // [sunny, cloudy, rain, storm, snow, hot]
  const W = {
    0: isNordic ? [10, 25, 25, 15, 25, 0] : [25, 35, 25, 8, 7, 0],   // KIŞ
    1: isHotDry  ? [55, 25, 12, 5, 0, 3]   : [40, 30, 22, 5, 0, 3],   // BAHAR
    2: isHotDry  ? [55, 15, 8, 5, 0, 17]   : (isNordic ? [55, 25, 12, 4, 0, 4] : [50, 25, 12, 5, 0, 8]),  // YAZ
    3: isNordic ? [25, 30, 25, 10, 8, 2]   : [35, 35, 22, 5, 1, 2]    // SONBAHAR
  };
  const weights = W[season];
  const codes = ['sunny', 'cloudy', 'rain', 'storm', 'snow', 'hot'];
  return codes.map((c, i) => ({ code: c, weight: weights[i] }));
}

function pickWeatherForDate(seed, date, cc) {
  const dist = _seasonalWeights(date || new Date(), cc || 'TR');
  const total = dist.reduce((s, w) => s + w.weight, 0);
  // Seed → deterministik rng
  let rng = 0;
  if (typeof seed === 'string') {
    let h = 2166136261;
    for (let i = 0; i < seed.length; i++) {
      h ^= seed.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    rng = ((h >>> 0) % 10000) / 10000;
  } else {
    rng = Math.random();
  }
  let acc = 0;
  for (const w of dist) {
    if (w.weight <= 0) continue;
    acc += w.weight / total;
    if (rng <= acc) return { code: w.code, ...WEATHER_TYPES[w.code] };
  }
  return { code: 'sunny', ...WEATHER_TYPES.sunny };
}

// ───── TARAFTAR / ATMOSFER ─────
function calcStadiumAtmosphere(homeTeam, league, isDerby) {
  // Stadyum kapasitesi (kullanıcı için FAC_LEVELS, bot için takım rating)
  let capacity = 30000;
  let isUserHome = false;
  try {
    if (typeof _userTeam !== 'undefined' && _userTeam && homeTeam.name === _userTeam.teamName
        && typeof FAC_LEVELS !== 'undefined' && FAC_LEVELS.stadium) {
      capacity = ekoKapasite(FAC_LEVELS.stadium);
      isUserHome = true;
    } else if (homeTeam.rating) {
      capacity = Math.round(15000 + (homeTeam.rating - 50) * 1500);
    }
  } catch(e) {}
  // Doluluk: maç önemine göre %75-95 + derbi bonus
  let fillRate = 0.75 + Math.random() * 0.20;
  if (isDerby) fillRate = Math.min(1.0, fillRate + 0.10);
  // Kupa final/yarı final maçları daha kalabalık
  if (league && (league.includes('Final') || league.includes('Yarı'))) {
    fillRate = Math.min(1.0, fillRate + 0.08);
  }
  const attendance = Math.round(capacity * fillRate);
  // 🆕 KULLANICI TALEBİ — ev sahibi avantajı çok yüksekti, %60 azaltıldı
  // Atmosfer çarpanı: 0.02 → 0.12 ev sahibi avantajı (eskiden 0.05→0.30)
  const atmosphere = 0.02 + (fillRate - 0.75) * 0.40; // %75=0.02, %95=0.10, %100=0.12
  return {
    capacity, attendance, fillRate,
    homeAdvantage: 0.06 + atmosphere,  // base 0.06 + atmosfer (eskiden 0.15)
    isUserHome,
    label: fillRate > 0.92 ? '🔥 Tribünler Dolu' : (fillRate > 0.85 ? '👥 Yoğun Tribün' : (fillRate > 0.78 ? '👥 İyi Doluluk' : '👥 Tenha Tribün'))
  };
}

// ───── DERBİ TESPİTİ ─────
// Aynı şehir/aynı ülke ve tarihsel rakipler
const DERBY_PAIRS = {
  // Türkiye derbileri (aynı şehir + tarihsel)
  'TR': [
    ['Galatasaray', 'Fenerbahçe'], ['Galatasaray', 'Beşiktaş'], ['Beşiktaş', 'Fenerbahçe'],
    ['Trabzonspor', 'Fenerbahçe'], ['Bursaspor', 'Eskişehirspor']
  ],
  'EN': [['Liverpool', 'Everton'], ['Manchester United', 'Manchester City'], ['Arsenal', 'Tottenham']],
  'ES': [['Real Madrid', 'Barcelona'], ['Real Madrid', 'Atlético Madrid'], ['Sevilla', 'Real Betis']],
  'IT': [['AC Milan', 'Inter'], ['Roma', 'Lazio'], ['Juventus', 'Torino']],
  'DE': [['Bayern Munich', 'Borussia Dortmund'], ['Schalke 04', 'Borussia Dortmund']],
  'PT': [['Porto', 'Benfica'], ['Sporting Lisbon', 'Benfica']],
  'AR': [['Boca Juniors', 'River Plate']],
  'NL': [['Ajax', 'Feyenoord']],
  'GR': [['Olympiakos', 'Panathinaikos']],
};

function isDerbyMatch(homeName, awayName) {
  if (!homeName || !awayName) return false;
  for (const cc in DERBY_PAIRS) {
    for (const [a, b] of DERBY_PAIRS[cc]) {
      if ((homeName.includes(a) && awayName.includes(b)) ||
          (homeName.includes(b) && awayName.includes(a))) return true;
    }
  }
  return false;
}

// ───── FORM / MOMENTUM ─────
// Maç içi anlık momentum: bir takım gol attığında 5 dk hücum bonusu,
// gol yiyince 5 dk şok ceza. Skor 3+ farkla önde olunca rahat (önde) /
// motivasyonlu (geri) olur.
function calcMomentumModifier(team, scoreDiff, lastEventMinute, currentMin, lastEventType) {
  // scoreDiff: bizim - rakip (pozitif önde, negatif geride)
  // lastEventType: 'goalFor', 'goalAgainst', null
  let mult = { atk: 1.0, def: 1.0 };

  // Anlık event etkisi (5 dk pencere)
  if (lastEventType && lastEventMinute != null) {
    const elapsed = currentMin - lastEventMinute;
    if (elapsed >= 0 && elapsed <= 5) {
      const fade = (5 - elapsed) / 5; // 1.0 → 0.0
      if (lastEventType === 'goalFor') {
        mult.atk += 0.15 * fade;
        mult.def += 0.05 * fade;
      } else if (lastEventType === 'goalAgainst') {
        mult.atk -= 0.05 * fade;
        mult.def -= 0.10 * fade;
      }
    }
  }

  // Skor farkı motivasyonu
  if (scoreDiff <= -2) {
    mult.atk += 0.12;  // çok geride: agresif
    mult.def -= 0.05;
  } else if (scoreDiff >= 2) {
    mult.atk -= 0.08;  // çok önde: rahat
    mult.def += 0.10;
  }

  return mult;
}

// ───── OLAY ÇEŞİTLİLİĞİ ─────
// Mevcut: gol, kart, sakatlık, penaltı, kendi kalesi, chance, save
// Yeni: ofsayt iptali, frikik golü, korner golü, kafa golü, dribbling, taç
const NEW_EVENT_TYPES = {
  'offsideGoal': {     // Ofsayt iptali (gol gibi başlar, geri alınır)
    label: 'Ofsayt iptali', icon: '🚩', weightWeather: { rain: 1.2 }
  },
  'freekickGoal': {    // Direk frikikten gol
    label: 'Frikik golü', icon: '🎯', weightWeather: { sunny: 1.0, rain: 0.7 }
  },
  'cornerGoal': {      // Korner sonrası gol
    label: 'Kornerden gol', icon: '⚽', weightWeather: {}
  },
  'headerGoal': {      // Kafa golü
    label: 'Kafa golü', icon: '👤', weightWeather: { rain: 1.3 }
  },
  'longShot': {        // Uzaktan şut golü
    label: 'Uzaktan şut!', icon: '🚀', weightWeather: { rain: 0.6, snow: 0.5 }
  },
  'dribble': {         // Dribbling olayı (gol değil, anchor)
    label: 'Müthiş dribbling', icon: '⚡', weightWeather: { rain: 0.7, snow: 0.5 }
  }
};

// Bir gol için "tip" seç (normal/frikik/kafa/uzun şut/korner)
function pickGoalSubtype(scorer, weather, rngSeed) {
  // Dağılım: %55 normal, %12 kafa, %10 frikik, %8 korner, %8 uzun şut, %7 ofsayt iptali (gol değil ama tetik)
  const rng = (typeof rngSeed === 'number') ? ((rngSeed * 9301 + 49297) % 233280) / 233280 : Math.random();
  // Hava etkili
  const isWet = weather && (weather.code === 'rain' || weather.code === 'storm' || weather.code === 'snow');
  let cum = 0;
  const mults = isWet
    ? { normal: 0.50, header: 0.18, freekick: 0.07, corner: 0.10, longshot: 0.05, offside: 0.10 }
    : { normal: 0.55, header: 0.12, freekick: 0.10, corner: 0.08, longshot: 0.08, offside: 0.07 };
  if (rng < (cum += mults.normal))   return 'normal';
  if (rng < (cum += mults.header))   return 'headerGoal';
  if (rng < (cum += mults.freekick)) return 'freekickGoal';
  if (rng < (cum += mults.corner))   return 'cornerGoal';
  if (rng < (cum += mults.longshot)) return 'longShot';
  return 'offsideGoal';
}

// MatchContext: tüm Faz 3 sistemlerini tek pakette toplar
function buildMatchContext(homeTeam, awayTeam, league, seed) {
  const isDerby = isDerbyMatch(homeTeam.name, awayTeam.name);
  // 🆕 Mevsimsel hava: maç tarihi + ev sahibi ülke kodu kullanılır
  // Tarih kaynağı: MS._fixtureRef.dateTime varsa o, yoksa MS._matchDate, yoksa şimdi
  let matchDate = new Date();
  try {
    if (typeof MS !== 'undefined' && MS && MS._fixtureRef) {
      const fr = MS._fixtureRef;
      if (fr.dateTime) matchDate = new Date(fr.dateTime);
      else if (fr.date) matchDate = new Date(fr.date);
      else if (fr.playedAt) matchDate = new Date(fr.playedAt);
    }
  } catch(e) {}
  const homeCC = homeTeam.countryCode || homeTeam.cc || 'TR';
  const weather = pickWeatherForDate(
    seed || (homeTeam.name + awayTeam.name + (typeof getSeasonInfo === 'function' ? getSeasonInfo().dayInSeason : '')),
    matchDate,
    homeCC
  );
  const atmosphere = calcStadiumAtmosphere(homeTeam, league, isDerby);

  const ctx = {
    weather,
    atmosphere,
    isDerby,
    league: league || '',
    matchDate,
    // Derbi çarpanları
    derbyMods: isDerby
      ? { foul: 1.5, surprise: 1.2, atmosphere: 1.3 }
      : { foul: 1.0, surprise: 1.0, atmosphere: 1.0 }
  };
  return ctx;
}


// ═══════════════════════════════════════════════════════════════════
//  FAZ 3 — Maç İçi Sosyal Reaksiyon (Madde 11)
//  4 emoji butonu, basıldığında ekranda büyük animasyonlu emoji
//  Ardışık basışlarda flood guard (1 saniye)
// ═══════════════════════════════════════════════════════════════════

let _msReactLastTs = 0;
let _msReactCount = 0;

function msReact(emoji) {
  const now = Date.now();
  // Flood guard: minimum 600ms ara
  if (now - _msReactLastTs < 600) return;
  _msReactLastTs = now;
  _msReactCount++;

  const bubble = document.getElementById('msReactBubble');
  if (!bubble) return;

  // Yeni emoji öğesi yarat
  const el = document.createElement('div');
  el.className = 'ms-react-emoji';
  el.textContent = emoji;
  // Random offset (sağ-sol ufak salınım)
  const offsetX = (Math.random() - 0.5) * 60;
  el.style.left = `calc(50% + ${offsetX}px)`;
  bubble.appendChild(el);

  // 1.6 sn sonra DOM'dan kaldır (CSS animasyon süresine bağlı)
  setTimeout(() => el.remove(), 1700);
}

// Reaksiyonları sıfırla (her maç başında)
function _msResetReactions() {
  _msReactCount = 0;
  const bubble = document.getElementById('msReactBubble');
  if (bubble) bubble.innerHTML = '';
}


//  3 hakem profili: sert / yumuşak / normal
//  VAR olayları: gol iptal (offside/foul), penaltı verilmesi, kart yükseltme
// ═══════════════════════════════════════════════════════════════════

const REFEREE_PROFILES = {
  'strict':  { label: '🟨 Sert Hakem',   yellowMult: 1.45, redMult: 1.30, varStrict: 1.20, weight: 25, name: 'Sert' },
  'normal':  { label: '⚖️ Normal Hakem', yellowMult: 1.00, redMult: 1.00, varStrict: 1.00, weight: 50, name: 'Normal' },
  'lenient': { label: '🟢 Yumuşak Hakem', yellowMult: 0.65, redMult: 0.55, varStrict: 0.80, weight: 25, name: 'Yumuşak' }
};

const REFEREE_NAMES = {
  'TR': ['Cüneyt Çakır','Halil Umut Meler','Atilla Karaoğlan','Mete Kalkavan','Ali Palabıyık','Yaşar Kemal Uğurlu'],
  'EN': ['Michael Oliver','Anthony Taylor','Stuart Attwell','Andre Marriner','Paul Tierney'],
  'ES': ['Mateu Lahoz','Jesús Gil Manzano','César Soto Grado'],
  'DE': ['Felix Brych','Daniel Siebert','Manuel Gräfe'],
  'IT': ['Daniele Orsato','Marco Guida','Davide Massa'],
  'FR': ['Clément Turpin','François Letexier'],
  'GENERIC': ['B. Williams','C. Garcia','D. Müller','E. Rossi','F. Lopez','G. Schmidt']
};

function pickReferee(seed) {
  // Seed'den profil seç
  let h = 2166136261;
  const s = String(seed || 'ref');
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  const rng = ((h >>> 0) % 1000) / 1000;
  const profiles = Object.entries(REFEREE_PROFILES);
  const total = profiles.reduce((sum, [, p]) => sum + p.weight, 0);
  let acc = 0;
  let chosen = profiles[1]; // default normal
  for (const [k, p] of profiles) {
    acc += p.weight / total;
    if (rng <= acc) { chosen = [k, p]; break; }
  }
  // İsim seç
  const cc = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.countryCode) || 'TR';
  const namePool = REFEREE_NAMES[cc] || REFEREE_NAMES.GENERIC;
  const nameSeed = ((h >>> 8) % 1000) / 1000;
  const name = namePool[Math.floor(nameSeed * namePool.length)];
  return { code: chosen[0], ...chosen[1], fullName: name };
}

// VAR olayı üret — gol iptal, penaltı verilmesi, kart yükseltme
function maybeVAREvent(refProfile, evs, homeTeam, awayTeam) {
  // Maç başına ortalama 0-2 VAR olayı
  const varCount = Math.floor(Math.random() * (refProfile.varStrict * 2.5));
  const varEvents = [];
  for (let i = 0; i < varCount; i++) {
    const min = 15 + Math.floor(Math.random() * 70);
    const r = Math.random();
    const side = Math.random() < 0.5 ? 'home' : 'away';
    const team = side === 'home' ? homeTeam : awayTeam;
    if (r < 0.35) {
      // VAR: penaltı verildi
      const cands = team.players.filter(p => ['FWD','SAK','OS','CAM'].includes(p.pos));
      if (cands.length) {
        const p = pick(cands);
        const isGoal = Math.random() < 0.78;
        if (isGoal) {
          varEvents.push({
            type: 'goal', team: side, min, player: p.name,
            isPenalty: true, varDecision: 'pen_awarded', subtypeIcon: '📺', subtypeLabel: 'VAR · Penaltı'
          });
          if (side === 'home') hG++; else aG++;
        } else {
          varEvents.push({
            type: 'penaltyMissed', team: side, min, player: p.name,
            varDecision: 'pen_awarded', isVAR: true
          });
        }
      }
    } else if (r < 0.65) {
      // VAR: gol iptal
      varEvents.push({
        type: 'varCancel', team: side, min,
        player: 'VAR İncelemesi',
        text: 'Gol VAR ile iptal edildi (ofsayt)'
      });
    } else {
      // VAR: kart yükseltme (sarı → kırmızı)
      const cands = team.players.filter(p => p.pos !== 'KL');
      if (cands.length) {
        const p = pick(cands);
        varEvents.push({
          type: 'red', team: side, min, player: p.name,
          varDecision: 'card_upgrade', isVAR: true
        });
      }
    }
  }
  return varEvents;
}

// ═══════════════════════════════════════════════════════════════════
//  SAKATLIK TİPLERİ — hafif (1-3 maç) / orta (1-2 hafta) / ağır (1-3 ay) / uzun
//  Pozisyona göre risk dağılımı: kanat = bilek, defans = diz, forvet = kas
// ═══════════════════════════════════════════════════════════════════

const INJURY_TYPES = {
  'minor':    { label: 'Hafif',    matches: [1, 3],   days: [1, 7],     weight: 55 },
  'moderate': { label: 'Orta',     matches: [3, 6],   days: [7, 21],    weight: 28 },
  'severe':   { label: 'Ağır',     matches: [6, 14],  days: [21, 90],   weight: 12 },
  'longterm': { label: 'Uzun',     matches: [15, 30], days: [90, 200],  weight: 5 }
};

const INJURY_BY_POSITION = {
  'KL':  { 'baş': 0.08, 'omuz': 0.20, 'el': 0.40, 'diz': 0.25, 'kas': 0.07 },
  'SB':  { 'bilek': 0.30, 'diz': 0.20, 'kas': 0.30, 'aşil': 0.15, 'sırt': 0.05 },
  'STB': { 'diz': 0.35, 'kas': 0.25, 'bilek': 0.15, 'omuz': 0.15, 'baş': 0.10 },
  'DOS': { 'kas': 0.35, 'diz': 0.20, 'bilek': 0.20, 'aşil': 0.15, 'sırt': 0.10 },
  'OS':  { 'kas': 0.40, 'aşil': 0.20, 'bilek': 0.15, 'diz': 0.15, 'sırt': 0.10 },
  'SAK': { 'bilek': 0.40, 'kas': 0.25, 'aşil': 0.20, 'diz': 0.10, 'omuz': 0.05 },
  'FWD': { 'kas': 0.45, 'diz': 0.20, 'aşil': 0.15, 'bilek': 0.15, 'omuz': 0.05 }
};

function pickInjuryType() {
  const types = Object.entries(INJURY_TYPES);
  const total = types.reduce((s, [, t]) => s + t.weight, 0);
  let rng = Math.random();
  let acc = 0;
  for (const [k, t] of types) {
    acc += t.weight / total;
    if (rng <= acc) return { code: k, ...t };
  }
  return { code: 'minor', ...INJURY_TYPES.minor };
}

function pickInjuryBodyPart(pos) {
  const map = INJURY_BY_POSITION[pos] || INJURY_BY_POSITION['DOS'];
  let rng = Math.random();
  let acc = 0;
  for (const part in map) {
    acc += map[part];
    if (rng <= acc) return part;
  }
  return 'kas';
}

function generateInjuryEvent(player, pos) {
  const type = pickInjuryType();
  const part = pickInjuryBodyPart(pos);
  const matchesOut = Math.floor(type.matches[0] + Math.random() * (type.matches[1] - type.matches[0]));
  const daysOut    = Math.floor(type.days[0] + Math.random() * (type.days[1] - type.days[0]));
  return {
    type: 'injury',
    severity: type.code,
    severityLabel: type.label,
    bodyPart: part,
    matchesOut, daysOut,
    description: `${type.label} ${part} sakatlığı (${matchesOut} maç)`
  };
}

// ═══════════════════════════════════════════════════════════════════
//  SET-PIECE — Frikikçi & Penaltıcı atama
//  Kullanıcı takımı Diziliş'ten frikikçi/penaltıcı seçebilir
//  Bot takımları en yüksek shot rating'li oyuncuyu seçer
// ═══════════════════════════════════════════════════════════════════

function pickSetPieceTaker(team, role) {
  // role: 'penalty' | 'freekick' | 'corner'
  if (!team || !team.players) return null;
  // 🆕 Kullanıcı override'ı: team_data.setpiece (Supabase)
  if (typeof _userTeam !== 'undefined' && _userTeam && team.name === _userTeam.teamName) {
    try {
      const stored = (typeof _setpieceCache !== 'undefined' && _setpieceCache) ? _setpieceCache : {};
      if (stored[role]) {
        const num = stored[role];
        const p = team.players.find(pl => pl.num === num);
        if (p) return p;
      }
    } catch(e) {}
  }
  // Otomatik seçim — pozisyon ve rating bazlı
  const cands = team.players.filter(p => {
    if (role === 'penalty')  return ['FWD','SAK','CAM','OS'].includes(p.pos);
    if (role === 'freekick') return ['FWD','SAK','CAM','OS','DOS'].includes(p.pos);
    if (role === 'corner')   return ['SAK','CAM','OS'].includes(p.pos);
    return true;
  });
  if (!cands.length) return team.players[0];
  // En yüksek rating
  return cands.slice().sort((a,b) => (b.rating||70) - (a.rating||70))[0];
}

// 🆕 Setpiece takers RAM cache (Supabase'ten _trsLoadFromServer benzeri)
let _setpieceCache = {};

async function _setpieceLoadFromServer() {
  if (!window.sb || !_userTeam || !_userTeam.countryCode || !_userTeam.teamName) {
    _setpieceCache = {};
    return;
  }
  try {
    const { data } = await window.sb.from('team_data')
      .select('data')
      .eq('country_code', _userTeam.countryCode)
      .eq('team_name', _userTeam.teamName)
      .eq('data_key', 'setpiece')
      .maybeSingle();
    _setpieceCache = (data && data.data) ? data.data : {};
  } catch(e) { _setpieceCache = {}; }
}

function getUserSetPieceTakers() {
  return _setpieceCache || {};
}

function setUserSetPieceTaker(role, num) {
  try {
    _setpieceCache = _setpieceCache || {};
    _setpieceCache[role] = num;
    // Supabase'e yaz
    if (window.sb && _userTeam && _userTeam.countryCode && _userTeam.teamName) {
      window.sb.from('team_data').upsert({
        country_code: _userTeam.countryCode,
        team_name: _userTeam.teamName,
        data_key: 'setpiece',
        data: _setpieceCache,
        updated_at: new Date().toISOString()
      }, { onConflict: 'country_code,team_name,data_key' }).then(({error}) => {
        if (error) console.warn('[setpiece] save hata:', error.message);
      });
    }
    return true;
  } catch(e) { return false; }
}

// ═══════════════════════════════════════════════════════════════════
//  ANTRENÖR / T.D. BECERİSİ
//  T.D.'ye yetenek puanı (1-100) + 3 etiket (savunma/hücum/motivatör)
//  Takım performansına ±%5 etki eder
// ═══════════════════════════════════════════════════════════════════

const COACH_TRAITS = {
  'attack_specialist':  { label: '⚔️ Hücum Uzmanı',   atkBonus: 0.05, defBonus: 0.00, moraleBonus: 0 },
  'defense_specialist': { label: '🛡️ Savunma Uzmanı', atkBonus: 0.00, defBonus: 0.05, moraleBonus: 0 },
  'motivator':          { label: '🔥 Motivatör',       atkBonus: 0.02, defBonus: 0.02, moraleBonus: 5 },
  'tactician':          { label: '♟️ Taktikçi',        atkBonus: 0.03, defBonus: 0.03, moraleBonus: 0 },
  'youth_dev':          { label: '🌱 Genç Geliştirici', atkBonus: 0.01, defBonus: 0.01, moraleBonus: 2 },
  'old_school':         { label: '📋 Eski Okul',       atkBonus: 0.00, defBonus: 0.04, moraleBonus: 1 }
};

// Bir T.D. için becerileri belirle (federasyon başkanına göre deterministik)
function getCoachProfile(presidentId, isUser) {
  if (!presidentId) {
    return { skill: 50, trait: 'tactician', traitData: COACH_TRAITS.tactician, label: 'Belirsiz' };
  }
  if (isUser) {
    // Kullanıcı T.D. — kendi profili (Supabase user_player.coach_profile)
    const stored = _coachProfileCache;
    if (stored && stored.skill) {
      return {
        skill: stored.skill,
        trait: stored.trait,
        traitData: COACH_TRAITS[stored.trait] || COACH_TRAITS.tactician,
        label: 'Sen'
      };
    }
    // Default: orta seviye, tactician
    return { skill: 60, trait: 'tactician', traitData: COACH_TRAITS.tactician, label: 'Sen' };
  }
  // Bot başkan: deterministik (id'den)
  let h = 2166136261;
  const s = String(presidentId);
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  const skill = 40 + (((h >>> 0) % 50)); // 40-90 arası
  const traitKeys = Object.keys(COACH_TRAITS);
  const trait = traitKeys[((h >>> 8) % traitKeys.length)];
  return {
    skill,
    trait,
    traitData: COACH_TRAITS[trait],
    label: 'Bot T.D.'
  };
}

// Coach skill çarpanı: 50 = nötr, 90 = +%4 boost, 30 = -%4 ceza
function coachSkillMultiplier(coachProfile) {
  if (!coachProfile) return { atk: 1.0, def: 1.0 };
  const skillMod = (coachProfile.skill - 50) / 1000; // 50→0, 90→0.04, 30→-0.02
  const trait = coachProfile.traitData || {};
  return {
    atk: 1.0 + skillMod + (trait.atkBonus || 0),
    def: 1.0 + skillMod + (trait.defBonus || 0),
    moraleBonus: trait.moraleBonus || 0
  };
}


// Composite — tüm strateji çarpanlarını birleştir
function compositeStratMods(s) {
  const sty = STYLE_MODS[s.style]    || STYLE_MODS['Dengeli'];
  const tmp = TEMPO_MODS[s.tempo]    || TEMPO_MODS['Normal'];
  const dfn = DEFENSE_MODS[s.defense]|| DEFENSE_MODS['Normal'];
  const prs = PRESS_MODS[s.press]    || PRESS_MODS['Orta'];
  const sht = SHOOT_MODS[s.shoot]    || SHOOT_MODS['Normal'];
  return {
    atk: sty.atk * tmp.atk * prs.atk,
    def: sty.def * tmp.def * dfn.def,
    foul: sty.foul * tmp.foul * prs.foul,
    surprise: sty.surprise,
    fitness: sty.fitness * prs.fitness,
    shots: sht.shots,
    accuracy: sht.accuracy,
    ofsides: dfn.ofsides,
    attack: ATTACK_MODS[s.attack] || ATTACK_MODS['Dengeli'],
  };
}

// Bot için rastgele strateji üret (deterministik isim seed)
function generateBotStrategy(team) {
  const seed = (team && team.name) ? team.name : 'bot';
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) {
    h ^= seed.charCodeAt(i); h = Math.imul(h, 16777619);
  }
  const rng = () => {
    h = (h + 0x6D2B79F5) | 0;
    let t = h; t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  const pickFrom = (arr) => arr[Math.floor(rng() * arr.length)];
  return {
    style:   pickFrom(['Dengeli','Dengeli','Agresif Baskı','Defansif Blok','Tiki-Taka','Gegenpressing']),
    tempo:   pickFrom(['Normal','Normal','Hızlı & Direk','Yavaş Yapılandırma']),
    attack:  pickFrom(['Dengeli','Sol Kanat','Sağ Kanat','Orta Alan']),
    defense: pickFrom(['Normal','Normal','Yüksek Hat','Çok Derin']),
    press:   pickFrom(['Orta','Orta','Yüksek','Minimal']),
    shoot:   pickFrom(['Normal','Normal','Sık']),
  };
}

// 🆕 Geriye dönük uyumluluk: eski MENTALITY_MODS aliası
const MENTALITY_MODS = {
  defensive: { atk: 0.72, def: 1.25, foul: 1.00, surprise: 0.70, fitness: 0.95 },
  balanced:  { atk: 1.00, def: 1.00, foul: 1.00, surprise: 1.00, fitness: 1.00 },
  attacking: { atk: 1.30, def: 0.78, foul: 1.18, surprise: 1.20, fitness: 1.05 },
  all_out:   { atk: 1.62, def: 0.50, foul: 1.45, surprise: 1.55, fitness: 1.12 },
};

function avgPlayerRating(players) {
  if (!players || !players.length) return 70;
  const sum = players.reduce((s, p) => s + (p.rating || p.overall || 70), 0);
  return sum / players.length;
}

function teamFormScore(team) {
  // Son 5 maçtan form puanı (-0.5 to +0.5)
  try {
    const f = (typeof getTeamLast5Matches === 'function') ? getTeamLast5Matches(team) : [];
    if (!f.length) return 0;
    const w = f.filter(x => x === 'W').length;
    const d = f.filter(x => x === 'D').length;
    const l = f.filter(x => x === 'L').length;
    return (w * 0.1 + d * 0.02 - l * 0.08); // ~ -0.4..+0.5
  } catch(e) { return 0; }
}

// Bot AI: rating ve mentalite seçimi
function pickAIMentality(myTeam, oppTeam) {
  const myR = myTeam.rating || 70;
  const oppR = oppTeam.rating || 70;
  const diff = myR - oppR;
  if (diff > 7) return 'attacking';     // güçlüyse hücum
  if (diff < -7) return 'defensive';    // zayıfsa defansif
  if (Math.random() < 0.18) return 'attacking'; // bazen sürpriz
  return 'balanced';
}

// Poisson dağılımı (gol sayısı)
function poissonSample(lambda) {
  let L = Math.exp(-lambda), k = 0, p = 1;
  do { k++; p *= Math.random(); } while (p > L);
  return k - 1;
}

// Gol dakikası dağılımı (gerçekçi: ilk 15 az, son 15 çok)
function spreadGoalMinutes(n) {
  const mins = [];
  for (let i = 0; i < n; i++) {
    const r = Math.random();
    let m;
    if (r < 0.10) m = rnd(2, 15);
    else if (r < 0.35) m = rnd(16, 44);
    else if (r < 0.55) m = rnd(46, 65);
    else if (r < 0.85) m = rnd(66, 85);
    else m = rnd(86, 92);  // %15 son 6 dakika golü
    mins.push(m);
  }
  return mins.sort((a, b) => a - b);
}

// Pozisyon ağırlıklı oyuncu seçimi (gol için forvet, kart için orta saha vs.)
function pickWeighted(players, weightFn) {
  if (!players.length) return null;
  const weights = players.map(weightFn);
  const total = weights.reduce((s, w) => s + w, 0);
  let r = Math.random() * total;
  for (let i = 0; i < players.length; i++) {
    r -= weights[i];
    if (r <= 0) return players[i];
  }
  return players[players.length - 1];
}

