// 🆕 GENEL CANLI MAÇ İZLEME — SONUÇLAR ve GÜNÜN MAÇLARI'ndan çağrılır
// Gerçek motor (simulateBotMatch) ile 90 dakikalık tam simulasyon üretir,
// sonra şu anki dakikaya kadar olan event'leri filtreleyerek live görünüm sunar.
// matchData: { home, away, homeShort, awayShort, scheduledTime, season, day,
//              leagueName, leagueFlag, countryCode, tierIdx }
// kickoffMs: opsiyonel, yoksa scheduledTime + selectedDate'ten hesaplanır
function liveMatchOpen(matchData, kickoffMs) {
  if (!matchData) return;
  const m = matchData;

  // Kullanıcı maçı + MS aktif → kullanıcı maç ekranına yönlendir
  const userTeamName = (typeof _userTeam !== 'undefined' && _userTeam) ? _userTeam.teamName : null;
  const isUserMatch = userTeamName && (m.home === userTeamName || m.away === userTeamName);
  if (isUserMatch && typeof MS !== 'undefined' && MS && MS.matchActive) {
    if (typeof showPage === 'function') showPage('home', null);
    return;
  }

  // 🆕 SERVER-ONLY: Lokal motor YOK
  // 1) Kickoff zamanını match_state veya match_results'tan al
  // 2) Canlı poll: match_state'ten sim_minute, score, events oku
  
  // matchKey üret (frontend convention)
  const cacheKey = `${m.season || 1}_${m.day || 0}_${m.home}_${m.away}`;
  
  // kickoff hesabı: önce match_state'ten, sonra m.matchDateTime'dan
  if (!kickoffMs) {
    // _liveMatchCache'te varsa kickoff_at'i kullan
    const liveRow = (typeof _liveMatchCache === 'object' && _liveMatchCache) ?
      Object.values(_liveMatchCache).find(r =>
        r && r.season === (m.season || 1) && r.day_in_season === (m.day || 0) &&
        r.home_team === m.home && r.away_team === m.away
      ) : null;
    if (liveRow && liveRow.kickoff_at) {
      kickoffMs = new Date(liveRow.kickoff_at).getTime();
    } else if (m.matchDateTime) {
      kickoffMs = new Date(m.matchDateTime).getTime();
    } else {
      const [hh, mm] = (m.scheduledTime || '15:00').split(':').map(n => parseInt(n) || 0);
      const baseDate = (typeof _resState !== 'undefined' && _resState.selectedDate) ? _resState.selectedDate : new Date();
      const k = new Date(baseDate.getFullYear(), baseDate.getMonth(), baseDate.getDate(), hh, mm, 0, 0);
      kickoffMs = k.getTime();
    }
  }

  // State kaydet (refresh için)
  window._resLiveMatchKey = cacheKey;
  window._resLiveMatchData = m;
  window._resLiveKickoffMs = kickoffMs;

  // Modal aç
  const overlay = document.getElementById('resLiveOverlay');
  if (!overlay) return;
  if (overlay.parentElement !== document.body) document.body.appendChild(overlay);

  const set = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
  set('resLmComp', `${m.leagueFlag || '🏆'} ${m.leagueName || 'Maç'}`);
  set('resLmHomeName', m.home || '?');
  set('resLmAwayName', m.away || '?');
  set('resLmHomeShort', m.homeShort || (m.home || '').slice(0,3).toUpperCase());
  set('resLmAwayShort', m.awayShort || (m.away || '').slice(0,3).toUpperCase());

  // 🆕 Açılışta 0-0 "yetişme" flash'ını önle: listedeki GÜNCEL skor+dakikayı _liveMatchCache'e HEMEN seed et
  try {
    const _sk = m.matchKey || cacheKey;
    if (m.isLive && _sk && typeof _liveMatchCache === 'object' && _liveMatchCache && !_liveMatchCache[_sk]) {
      _liveMatchCache[_sk] = {
        match_key: _sk, season: m.season || 1, day_in_season: m.day || 0,
        home_team: m.home, away_team: m.away, status: 'running',
        home_score: m.hs ?? 0, away_score: m.as ?? 0, sim_minute: m.liveMinute ?? 0,
        events: [], started_at: null
      };
    }
  } catch(e){}

  _resLiveUpdate();
  overlay.classList.add('open');

  // 🆕 Tam satırı (events/started_at dahil) HEMEN çek → 7sn poll'u bekleme, güncel skor+olaylar anında
  (async () => {
    try {
      const _mk = m.matchKey || cacheKey;
      if (_mk && window.sb) {
        const { data: _one } = await window.sb.from('match_state')
          .select('match_key,season,day_in_season,country_code,tier,league_name,home_team,away_team,status,sim_minute,home_score,away_score,events,stats,started_at,kickoff_at,tournament_key,tournament_phase,viewer_count')
          .eq('match_key', _mk).maybeSingle();
        if (_one && typeof _liveMatchCache === 'object' && _liveMatchCache) { _liveMatchCache[_mk] = _one; _resLiveUpdate(); }
      }
    } catch(e){}
  })();

  // 🆕 Her 7sn'de SADECE bu maçın satırını çek (tüm canlı maçları değil — CPU dostu).
  //   Tıklanan maçta olaylar görünür, o yüzden events+stats dahil.
  if (window._resLiveModalTimer) clearInterval(window._resLiveModalTimer);
  window._resLiveModalTimer = setInterval(async () => {
    if (document.hidden) return;  // 🆕 sekme gizliyse modal poll yok
    try {
      const mk = m.matchKey || (window._resLiveMatchData && window._resLiveMatchData.matchKey);
      if (mk && window.sb) {
        const { data: _one } = await window.sb.from('match_state')
          .select('match_key,season,day_in_season,country_code,tier,league_name,home_team,away_team,status,sim_minute,home_score,away_score,events,stats,started_at,kickoff_at,tournament_key,tournament_phase,viewer_count')
          .eq('match_key', mk)
          .maybeSingle();
        if (_one && typeof _liveMatchCache === 'object' && _liveMatchCache) _liveMatchCache[mk] = _one;
      }
    } catch(e) {}
    _resLiveUpdate();
  }, 7000);
}

// SONUÇLAR sayfası — index ile çağrı
function resOpenLiveMatch(idx) {
  const arr = window._resClickableMatches || [];
  const key = arr[idx];
  if (!key) return;
  const m = window._resCurrentMatches && window._resCurrentMatches[key];
  if (!m) return;
  liveMatchOpen(m);
}

// 🆕 Canlı modal güncelleme — her 3sn çağrılır.
// SERVER-ONLY: lokal sim yok, match_state ve match_results'tan oku.
function _resLiveUpdate() {
  const m = window._resLiveMatchData;
  const kickoff = window._resLiveKickoffMs;
  if (!m) return;

  const set = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };

  // Kullanıcı maçı?
  const userTeamName = (typeof _userTeam !== 'undefined' && _userTeam) ? _userTeam.teamName : null;
  const isUserMatch = userTeamName && (m.home === userTeamName || m.away === userTeamName);

  let hs = 0, as = 0, minute = 0, isHT = false, ratio = 0, events = [], statusMode = 'pre', _uzK = null;
  // statusMode: 'pre' | 'live' | 'ht' | 'finished'

  if (isUserMatch && typeof MS !== 'undefined' && MS && MS.matchActive) {
    hs = MS.scoreH || 0;
    as = MS.scoreA || 0;
    minute = MS.minute || 0;
    ratio = Math.min(1, minute / 90);
    events = (MS.script && MS.script.evs) || [];
    statusMode = minute >= 90 ? 'finished' : 'live';
  } else {
    // 🆕 1) Önce match_state'ten canlı durum kontrolü (her tick güncellenir)
    let liveRow = null;
    if (typeof _liveMatchCache === 'object' && _liveMatchCache) {
      for (const k in _liveMatchCache) {
        const r = _liveMatchCache[k];
        if (r && r.season === (m.season || 1) && r.day_in_season === (m.day || 0) &&
            r.home_team === m.home && r.away_team === m.away) {
          liveRow = r; break;
        }
      }
    }

    _uzK = (liveRow && liveRow.status === 'finished') ? _uzListeDurum(_uzSatir(liveRow)) : null;   // 720
    if (_uzK) {
      minute = _uzK.dk; hs = _uzK.hs; as = _uzK.as; ratio = 1; statusMode = 'live';
      events = (Array.isArray(liveRow.events) ? liveRow.events : [])
        .concat(_uzK.goller.map(g => ({ type: 'goal', team: g[0] === 0 ? 'home' : 'away', player: g[2], min: g[1] })));
    } else if (liveRow && (liveRow.status === 'running' || liveRow.status === 'scheduled')) {
      // 🆕 CANLI: server'dan gelen anlık veri (dakika smoothing ile hesaplanır)
      minute = (typeof _computeLiveSimMinute === 'function') ? _computeLiveSimMinute(liveRow) : (liveRow.sim_minute || 0);  // 🆕 liste ile AYNI: started_at saati
      hs = liveRow.home_score || 0;
      as = liveRow.away_score || 0;
      events = Array.isArray(liveRow.events) ? liveRow.events : [];
      ratio = Math.min(1, minute / 90);
      if (liveRow.status === 'scheduled' && (Date.now() < (kickoff || 0))) {
        statusMode = 'pre';
      } else if (minute === 45 && (Date.now() - (liveRow.started_at ? new Date(liveRow.started_at).getTime() : 0)) > 5*60*1000 && (Date.now() - (liveRow.started_at ? new Date(liveRow.started_at).getTime() : 0)) < 7*60*1000) {
        isHT = true; statusMode = 'ht';
      } else {
        statusMode = 'live';
      }
    } else {
      // 🆕 2) match_state'te yok → match_results'tan bitmiş skoru göster
      let mrCache = {};
      try { mrCache = (typeof _matchResultsLoad === 'function') ? _matchResultsLoad() : {}; } catch(e) {}
      const finishedKey = `${m.season || 1}_${m.day || 0}_${m.home}_${m.away}`;
      const mr = mrCache[finishedKey];
      
      if (mr && typeof mr.hs === 'number') {
        hs = mr.hs; as = mr.as;
        minute = 90; ratio = 1;
        statusMode = 'finished';
        // events varsa kullan (lazy load gerekiyor olabilir)
        if (Array.isArray(mr.events)) events = mr.events;
        else if (mr.data && Array.isArray(mr.data.events)) events = mr.data.events;
      } else if (Date.now() < (kickoff || 0)) {
        // 3) Maç henüz başlamadı
        statusMode = 'pre';
        minute = 0; ratio = 0;
      } else {
        // Maç başlamış olmalı ama server kayıt yok → "bekleniyor"
        statusMode = 'pre';
        minute = 0; ratio = 0;
      }
    }
  }

  set('resLmHomeScore', hs);
  set('resLmAwayScore', as);

  // Dakika gösterimi
  const minuteText = document.getElementById('resLmMinuteText');
  if (minuteText) {
    if (statusMode === 'ht') {
      minuteText.classList.add('is-ht');
      minuteText.innerHTML = '⏸️ <b>DEVRE ARASI</b>';
    } else if (statusMode === 'finished') {
      minuteText.classList.remove('is-ht');
      minuteText.innerHTML = '✅ <b>MAÇ BİTTİ</b>';
    } else if (statusMode === 'pre') {
      minuteText.classList.remove('is-ht');
      const kickoffDate = new Date(kickoff || 0);
      const tStr = kickoffDate.toTimeString().slice(0,5);
      minuteText.innerHTML = `⏰ <b>${tStr}</b> başlayacak`;
    } else {
      minuteText.classList.remove('is-ht');
      minuteText.innerHTML = (_uzK && _uzK.metin === 'PEN') ? '<b>PENALTILAR</b>' : `<b>${minute}'</b> dakika`;
    }
  }

  const fill = document.getElementById('resLmMinuteFill');
  if (fill) fill.style.width = Math.round(ratio * 100) + '%';

  // Olay listesi (son 5, en yeni üstte)
  const evList = document.getElementById('resLmEvents');
  if (evList) {
    const relevantEvs = (events || [])
      .filter(e => e && (typeof e.min === 'number' ? e.min <= minute : true) && ['goal','red','yellow','injury','sub','penalty'].includes(e.type))
      .slice(-5)
      .reverse();

    if (relevantEvs.length === 0) {
      evList.innerHTML = '<div class="res-lm-no-events">Henüz önemli olay yok...</div>';
    } else {
      evList.innerHTML = relevantEvs.map(e => {
        const isHome = e.team === 'home';
        const sideLabel = isHome ? 'EV' : 'DEP';
        let icon = '⚽', cls = '', text = '';
        if (e.type === 'goal')        { icon = '⚽'; cls = 'is-goal';   text = `Gol! ${e.player || '?'}`; }
        else if (e.type === 'red')    { icon = '🟥'; cls = 'is-red';    text = `Kırmızı kart · ${e.player || '?'}`; }
        else if (e.type === 'yellow') { icon = '🟨'; cls = 'is-yellow'; text = `Sarı kart · ${e.player || '?'}`; }
        else if (e.type === 'injury') { icon = '🩹'; cls = '';          text = `Sakatlık · ${e.player || '?'}`; }
        else if (e.type === 'sub')    { icon = ''; cls = 'is-sub';    text = `<span class="in">▲ ${e.player || '?'}</span> <span class="out">▼ ${e.playerOut || '?'}</span>`; }
        else if (e.type === 'penalty'){ icon = '🎯'; cls = '';          text = `Penaltı! ${e.player || '?'}`; }
        return `<div class="res-lm-event ${cls}">
          <span class="res-lm-event-min">${e.min}'</span>
          <span class="res-lm-event-icon">${icon}</span>
          <span class="res-lm-event-text">${text}</span>
          <span class="res-lm-event-team">${sideLabel}</span>
        </div>`;
      }).join('');
    }
  }

  // Status mesajı
  const statusEl = document.getElementById('resLmStatus');
  if (statusEl) {
    if (statusMode === 'finished') {
      statusEl.innerHTML = '🏁 <b>Maç sona erdi.</b> Sonuç kaydedildi.';
    } else if (statusMode === 'ht') {
      statusEl.textContent = '☕ Devre arası — oyuncular dinleniyor.';
    } else if (statusMode === 'pre') {
      statusEl.textContent = '⏰ Maç başlamayı bekliyor...';
    } else if (minute < 5) {
      statusEl.textContent = '🚀 Maç yeni başladı, takımlar tempoyu yakalıyor.';
    } else if (minute < 30) {
      statusEl.textContent = '⚽ İlk yarı — temkin ve gözlem dönemi.';
    } else if (minute < 45) {
      statusEl.textContent = '🔥 İlk yarı sonu yaklaşıyor, baskılar artıyor.';
    } else if (minute < 70) {
      statusEl.textContent = '⚡ İkinci yarı — taktiksel hamleler yapılıyor.';
    } else {
      statusEl.textContent = '🎯 Son düzlük — her saniye değerli.';
    }
  }

  // 🆕 Maç bitti → otomatik kapat (lokal cache yazımı YOK — server zaten match_results'a yazar)
  if (statusMode === 'finished' && !window._resLiveModalAutoClose) {
    window._resLiveModalAutoClose = true;
    setTimeout(() => {
      if (window._resLiveMatchKey) resCloseLiveMatch();
    }, 5000);
  }
}

// 🆕 Canlı modal kapat
function resCloseLiveMatch() {
  const overlay = document.getElementById('resLiveOverlay');
  if (overlay) overlay.classList.remove('open');
  if (window._resLiveModalTimer) {
    clearInterval(window._resLiveModalTimer);
    window._resLiveModalTimer = null;
  }
  window._resLiveMatchKey = null;
  window._resLiveMatchData = null;
  window._resLiveKickoffMs = null;
  window._resLiveModalAutoClose = false;
}

// 🆕 MAÇI İZLE — Mini overlay'ı kapat, izleyici modunda match-screen aç.
// Sunucu lineup'ını kullanır (uydurma kadro yok), kontroller kapalıdır.
async function resLmOpenFullScreen() {
  const m = window._resLiveMatchData;
  if (!m) {
    if (typeof showToast === 'function') showToast('Maç verisi bulunamadı');
    return;
  }
  // match_key — _resLiveMatchData'da yoksa _liveMatchCache'ten ara
  let matchKey = m.matchKey || m.match_key || null;
  if (!matchKey && typeof _liveMatchCache === 'object' && _liveMatchCache) {
    const found = Object.values(_liveMatchCache).find(r =>
      r && r.home_team === m.home && r.away_team === m.away
    );
    if (found) matchKey = found.match_key;
  }
  if (!matchKey) {
    if (typeof showToast === 'function') showToast('Maç anahtarı bulunamadı');
    return;
  }

  // Sunucu lineup'ını çek (uydurma kadro üretme, gerçek match_state'i kullan)
  let serverRow = null;
  try {
    if (window.sb) {
      const { data } = await window.sb.from('match_state')
        .select('match_key,home_team,away_team,country_code,tier,league_name,home_score,away_score,status,sim_minute,started_at,kickoff_at,events,home_lineup,away_lineup,tournament_key,tournament_phase,viewer_count')
        .eq('match_key', matchKey)
        .maybeSingle();
      serverRow = data || null;
    }
  } catch(e) { console.warn('[resLmOpenFullScreen] match_state çek hata:', e); }

  if (!serverRow) {
    if (typeof showToast === 'function') showToast('Maç sunucuda bulunamadı');
    return;
  }

  // 688 — TARAFTAR: kendi kulübünün / milli takımının maçı değilse maç açılmadan taraf seçilir
  if (serverRow.status !== 'finished' && typeof window._izTarafHazirla === 'function') {
    const _taraf = await window._izTarafHazirla(serverRow);
    if (!_taraf) return;   // vazgeçti → canlı yayın penceresi açık kalır
  }

  // İzleyici modu işareti — initTacticControls bunu kullanır
  if (typeof MS !== 'undefined' && MS) {
    MS._spectatorMode = true;
    MS._matchActive = false;
    MS.match_key = matchKey;
  }
  window._spectatorMatchKey = matchKey;

  // Mini overlay'ı kapat
  resCloseLiveMatch();

  // Match-screen'i aç — skipPreview, kickoff zaten geçti
  const hClass = 'c1', aClass = 'c2';
  const league = m.leagueName || serverRow.league_name || 'Maç';
  const venue = (m.home || serverRow.home_team) + ' Stadyumu';
  const kickoffMs = serverRow.kickoff_at ? new Date(serverRow.kickoff_at).getTime() : Date.now();

  if (typeof openMatchScreenV2 === 'function') {
    // Sunucu lineup'ından home/away data inşa et
    const homeData = {
      name: serverRow.home_team,
      short: (m.homeShort) || (serverRow.home_team || '').slice(0,3).toUpperCase(),
      rating: 74,
      countryCode: serverRow.country_code || 'TR',
      _serverLineup: serverRow.home_lineup || null,
    };
    const awayData = {
      name: serverRow.away_team,
      short: (m.awayShort) || (serverRow.away_team || '').slice(0,3).toUpperCase(),
      rating: 74,
      countryCode: serverRow.country_code || 'TR',
      _serverLineup: serverRow.away_lineup || null,
    };
    openMatchScreenV2({
      home: homeData,
      away: awayData,
      league,
      venue,
      hClass, aClass,
      kickoff: kickoffMs,
      skipPreview: true,    // 🆕 maç çoktan başlamış, preview gösterme
      spectator: true,      // 🆕 izleyici modu
      matchKey: matchKey,
    });
  }
}

// 🆕 BİTEN MAÇ MODALI — beyaz tema, skor + goller + maçın adamı
// 🆕 Maç özeti modalı — sekme değiştirici
function resFmTab(ad, btn) {
  try {
    document.querySelectorAll('#resFmTabs .res-fm-tab').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');
    document.querySelectorAll('#resFmBody .res-fm-pane').forEach(p => {
      p.style.display = (p.getAttribute('data-pane') === ad) ? '' : 'none';
    });
    const gvd = document.getElementById('resFmBody');
    if (gvd) gvd.scrollTop = 0;
  } catch(e) {}
}
window.resFmTab = resFmTab;

// Veri olmayan sekmeyi pasifleştir, ilk dolu sekmeyi seç
function _resFmSekmeDurum() {
  try {
    const dolu = {
      ozet:    true,
      ist:     document.getElementById('resFmStatsSec')?.style.display !== 'none',
      reyting: document.getElementById('resFmRatingsSec')?.style.display !== 'none',
    };
    let ilkAktif = null;
    document.querySelectorAll('#resFmTabs .res-fm-tab').forEach(b => {
      const ad = b.getAttribute('data-tab');
      const v = !!dolu[ad];
      b.disabled = !v;
      if (v && !ilkAktif) ilkAktif = b;
    });
    const aktif = document.querySelector('#resFmTabs .res-fm-tab.active');
    if (!aktif || aktif.disabled) resFmTab('ozet', document.querySelector('#resFmTabs .res-fm-tab[data-tab="ozet"]'));
  } catch(e) {}
}

async function resOpenFinishedMatch(matchKey) {
  // Modal'ı body'ye taşı (page kapalıyken de görünür olsun)
  const overlay = document.getElementById('resFmOverlay');
  if (overlay && overlay.parentNode !== document.body) {
    document.body.appendChild(overlay);
  }

  // matchKey ya doğrudan string ya da _resClickableMatches index
  let key = matchKey;
  if (typeof matchKey === 'number') {
    key = (window._resClickableMatches && window._resClickableMatches[matchKey]) || null;
  }
  if (!key) return;
  const m = (window._resCurrentMatches && window._resCurrentMatches[key]) || null;
  if (!m) return;

  // 🆕 Önce modal'ı aç ve "yükleniyor" göster — sonra veriyi çek
  if (overlay) overlay.classList.add('open');

  // Skor + takım adları — anında
  // 🆕 Turnuva maçlarında lig adı boş geliyordu → turnuva + aşama göster
  const _TRN_AD = { chm:'Championship', eli:'Elite', con:'Convergence',
                    enc:'EURO Nations Cup', friendly:'Hazırlık Maçı' };
  const _FAZ_AD = { group:'Grup Aşaması', r32:'Son 32', r16:'Son 16',
                    qf:'Çeyrek Final', sf:'Yarı Final', final:'Final' };
  let comp;
  if (m.tournament_key) {
    comp = _TRN_AD[m.tournament_key] || 'Turnuva';
    const faz = _FAZ_AD[m.tournament_phase] || m.tournament_phase;
    if (faz) comp += ' · ' + faz;
  } else {
    comp = m.leagueName || m.tournamentName || 'Maç';
  }
  const compEl = document.getElementById('resFmComp');
  if (compEl) compEl.textContent = `${m.leagueFlag || ''} ${comp}`.trim();
  const hsEl = document.getElementById('resFmHomeScore');
  const asEl = document.getElementById('resFmAwayScore');
  if (hsEl) hsEl.textContent = m.hs;
  if (asEl) asEl.textContent = m.as;
  const hNameEl = document.getElementById('resFmHomeName');
  const aNameEl = document.getElementById('resFmAwayName');
  if (hNameEl) {
    hNameEl.textContent = m.home;
    hNameEl.className = 'res-fm-team-name' + (m.hs > m.as ? ' winner' : '');
  }
  if (aNameEl) {
    aNameEl.textContent = m.away;
    aNameEl.className = 'res-fm-team-name' + (m.as > m.hs ? ' winner' : '');
  }
  const hShortEl = document.getElementById('resFmHomeShort');
  const aShortEl = document.getElementById('resFmAwayShort');
  if (hShortEl) hShortEl.textContent = m.homeShort || (m.home || '').slice(0,3).toUpperCase();
  if (aShortEl) aShortEl.textContent = m.awayShort || (m.away || '').slice(0,3).toUpperCase();

  // Loading state — goller + maçın adamı
  const goalsElLoading = document.getElementById('resFmGoals');
  if (goalsElLoading) goalsElLoading.innerHTML = '<div class="res-fm-no-goals">Yükleniyor…</div>';
  const motmLoading = document.getElementById('resFmMotmWrap');
  if (motmLoading) motmLoading.innerHTML = '<div class="res-fm-no-motm">Yükleniyor…</div>';

  // 🆕 Lazy fetch: cache'te yoksa o maçı tek satır çek (44MB transfer YOK)
  let events = [];
  let homeLineup = [];
  let awayLineup = [];
  let entry = (typeof _matchEventsCache !== 'undefined' && _matchEventsCache && _matchEventsCache.byKey)
    ? _matchEventsCache.byKey[key] : null;
  // 🆕 Maç oynanırken alınmış önbellek eksik/eski olur → bitmiş maçta yeniden çek
  if (entry && entry._status && entry._status !== 'finished') entry = null;
  // 🔑 ESKİ HATA: sorguda listeden türetilen sahte anahtar (sezon_gün_ev_dep)
  //    kullanılıyordu. Lig maçlarında rastlantıyla tutuyor, TURNUVA maçlarında
  //    tutmuyordu → modal boş açılıyordu. Artık gerçek match_key kullanılır.
  const _dbKey = (m && m.matchKey) ? m.matchKey : key;
  if (!entry && _dbKey && window.sb) {
    try {
      const { data, error } = await window.sb.from('match_state')
        .select('events,stats,home_lineup,away_lineup,home_score,away_score,status,sim_minute,season,day_in_season,home_team,away_team')
        .eq('match_key', _dbKey)
        .maybeSingle();
      if (!error && data) {
        // 🆕 ARŞİV YEDEĞİ — eski maçlarda match_state'teki olay/istatistik verisi
        //   temizlenmiş olabilir (aynı veri match_results.data içinde duruyor).
        //   Boşsa oradan oku; modal "gol atılmadı" demesin.
        if ((!Array.isArray(data.events) || !data.events.length) && data.status === 'finished') {
          try {
            // 🆕 563 — yalnız olaylar ve istatistik (data'nın tamamı değil)
            const { data: _mr } = await window.sb.from('match_results')
              .select('ev:data->events,st:data->stats')
              .eq('season', data.season).eq('day_in_season', data.day_in_season)
              .eq('home_team', data.home_team).eq('away_team', data.away_team)
              .maybeSingle();
            if (_mr) {
              if (Array.isArray(_mr.ev)) data.events = _mr.ev;
              if (_mr.st && !data.stats) data.stats = _mr.st;
            }
          } catch(e) { console.warn('[fm] arşiv yedeği hata:', e); }
        }
        entry = {
          events: data.events,
          stats: data.stats,
          home_lineup: data.home_lineup,
          away_lineup: data.away_lineup,
          _hs: data.home_score,
          _as: data.away_score,
          _status: data.status,
          _min: data.sim_minute
        };
        // Cache'e koy ki bir daha çekmesin
        if (typeof _matchEventsCache !== 'undefined' && _matchEventsCache && _matchEventsCache.byKey) {
          _matchEventsCache.byKey[key] = entry;
        }
      }
    } catch(e) { console.warn('[fm] events fetch hata:', e); }
  }
  if (entry) {
    // 🆕 Skor: sunucudaki gerçek değer (liste satırı bayatsa düzeltir)
    try {
      if (typeof entry._hs === 'number' && typeof entry._as === 'number') {
        if (hsEl) hsEl.textContent = entry._hs;
        if (asEl) asEl.textContent = entry._as;
        if (hNameEl) hNameEl.className = 'res-fm-team-name' + (entry._hs > entry._as ? ' winner' : '');
        if (aNameEl) aNameEl.className = 'res-fm-team-name' + (entry._as > entry._hs ? ' winner' : '');
        // Liste önbelleğini de düzelt ki listede de doğru görünsün
        if (m) { m.hs = entry._hs; m.as = entry._as; }
        try {
          const _c = (_matchStateCache && _matchStateCache.byKey) ? _matchStateCache.byKey[key] : null;
          if (_c) { _c.home_score = entry._hs; _c.away_score = entry._as; if (entry._status) _c.status = entry._status; }
        } catch(e) {}
      }
    } catch(e) {}
    events = Array.isArray(entry.events) ? entry.events : [];
    homeLineup = (entry.home_lineup && Array.isArray(entry.home_lineup.players))
      ? entry.home_lineup.players : (Array.isArray(entry.home_lineup) ? entry.home_lineup : []);
    awayLineup = (entry.away_lineup && Array.isArray(entry.away_lineup.players))
      ? entry.away_lineup.players : (Array.isArray(entry.away_lineup) ? entry.away_lineup : []);
    // 🆕 (511) Oyuna sonradan giren yedekler de sunucu reytingiyle listelensin (tek reyting kaynağı)
    const _girenYedek = (lu) => (lu && Array.isArray(lu.bench)) ? lu.bench.filter(b => b && typeof b.matchRating === 'number') : [];
    homeLineup = homeLineup.concat(_girenYedek(entry.home_lineup));
    awayLineup = awayLineup.concat(_girenYedek(entry.away_lineup));
  }

  // Goller listesi — sadece type=goal, cancelled hariç
  const goals = events.filter(e => e && e.type === 'goal' && !e.cancelled)
    .sort((a, b) => (a.min || 0) - (b.min || 0));
  const goalsEl = document.getElementById('resFmGoals');
  if (goalsEl) {
    if (goals.length === 0) {
      goalsEl.innerHTML = '<div class="res-fm-no-goals">Maçta gol atılmadı</div>';
    } else {
      goalsEl.innerHTML = goals.map(g => {
        // 🆕 Kendi kalesine: golü SAYAN taraf rakiptir → doğru takıma yaz
        const own = !!(g.isOwnGoal || g.ownGoal);
        const scoringSide = own ? (g.team === 'home' ? 'away' : 'home') : g.team;
        const teamName = scoringSide === 'home' ? m.home : m.away;
        const teamShort = scoringSide === 'home' ? (m.homeShort || (m.home || '').slice(0,3).toUpperCase())
                                                 : (m.awayShort || (m.away || '').slice(0,3).toUpperCase());
        const assistHtml = (!own && g.assist) ? `<div class="res-fm-goal-assist">↳ Asist: ${g.assist}</div>` : '';
        const pen = (g.isPenalty || g.penalty) ? ' <span style="color:var(--text3);font-size:9.5px">(P)</span>' : '';
        const ownTag = own ? ' <span style="color:#ff8fa3;font-size:9.5px">(k.k.)</span>' : '';
        return `
          <div class="res-fm-goal">
            <div class="res-fm-goal-min">${g.min}'</div>
            <div class="res-fm-goal-icon">${own ? '🥅' : '⚽'}</div>
            <div class="res-fm-goal-info">
              <div class="res-fm-goal-scorer">${g.player || '?'}${ownTag}${pen}</div>
              ${assistHtml}
            </div>
            <div class="res-fm-goal-team">${teamShort}</div>
          </div>
        `;
      }).join('');
    }
  }

  // Maçın Adamı — lineup'ta sunucunun yazdığı GERÇEK matchRating'i kullan (uydurma hesap YOK)
  let motm = null;
  let motmTeam = null;
  let motmRating = 0;
  function _pickMotm(lineup, teamName) {
    if (!Array.isArray(lineup)) return;
    lineup.forEach(p => {
      if (!p || !p.name || typeof p.matchRating !== 'number') return;
      if (p.matchRating > motmRating) {
        motmRating = p.matchRating;
        motm = p;
        motmTeam = teamName;
      }
    });
  }
  // 756 — sunucunun seçtiği maçın adamı (eşitlikte istemci kendisi seçmesin); yoksa en yüksek reyting
  const _mmS = entry && ((entry.home_lineup && entry.home_lineup.motm) || (entry.away_lineup && entry.away_lineup.motm));
  const _mmP = _mmS && _mmS.ad ? (_mmS.ev ? homeLineup : awayLineup).find(p => p && p.name === _mmS.ad && typeof p.matchRating === 'number') : null;
  if (_mmP) { motm = _mmP; motmRating = _mmP.matchRating; motmTeam = _mmS.ev ? m.home : m.away; }
  else { _pickMotm(homeLineup, m.home); _pickMotm(awayLineup, m.away); }
  const motmWrap = document.getElementById('resFmMotmWrap');
  if (motmWrap) {
    if (motm && motmRating > 0) {
      const teamShort = motmTeam === m.home ? (m.homeShort || m.home.slice(0,3).toUpperCase())
                                            : (m.awayShort || m.away.slice(0,3).toUpperCase());
      const playerGoals = goals.filter(g => g.player === motm.name).length;
      const playerAssists = goals.filter(g => g.assist === motm.name).length;
      const statLine = [];
      if (playerGoals > 0) statLine.push(`${playerGoals} gol`);
      if (playerAssists > 0) statLine.push(`${playerAssists} asist`);
      const statStr = statLine.length > 0 ? statLine.join(' · ') : '—';
      motmWrap.innerHTML = `
        <div class="res-fm-motm">
          <div class="res-fm-motm-icon">⭐</div>
          <div class="res-fm-motm-info">
            <div class="res-fm-motm-label">Maçın Adamı</div>
            <div class="res-fm-motm-name">${motm.name}</div>
            <div class="res-fm-motm-meta">${teamShort} · <span data-noi18n>${subPosOf(motm)}</span> · ${statStr}</div>
          </div>
          <div class="res-fm-motm-rating">${motmRating.toFixed(1)}</div>
        </div>
      `;
    } else {
      motmWrap.innerHTML = '<div class="res-fm-no-motm">Maçın adamı verisi yok</div>';
    }
  }

  // ═══ 🆕 MAÇ İSTATİSTİKLERİ — sunucudaki gerçek stats ═══
  try {
    const st = (entry && (entry.stats || entry._stats)) ? (entry.stats || entry._stats) : null;
    const secS = document.getElementById('resFmStatsSec');
    const boxS = document.getElementById('resFmStats');
    const _ikili = (v) => Array.isArray(v) ? v : [0, 0];
    if (st && boxS) {
      const SATIR = [
        ['possession', 'Topla Oynama', '%'],
        ['shots', 'Şut', ''],
        ['shotsOnTarget', 'İsabetli Şut', ''],
        ['corners', 'Korner', ''],
        ['fouls', 'Faul', ''],
        ['yellowCards', 'Sarı Kart', ''],
        ['redCards', 'Kırmızı Kart', ''],
        ['passAcc', 'Pas İsabeti', '%'],
      ];
      const html = SATIR.map(([k, ad, ek]) => {
        const v = _ikili(st[k]);
        const h = Number(v[0]) || 0, a = Number(v[1]) || 0;
        const top = h + a;
        const hp = top > 0 ? Math.round(h / top * 100) : 50;
        if (top === 0 && k !== 'possession') return '';
        return `<div class="rfm-stat">
          <span class="v l">${h}${ek}</span>
          <span class="b l"><i style="width:${hp}%;background:var(--accent2,#00b0ff)"></i></span>
          <span class="k">${ad}</span>
          <span class="b"><i style="width:${100 - hp}%;background:#ef5350"></i></span>
          <span class="v r">${a}${ek}</span>
        </div>`;
      }).filter(Boolean).join('');
      if (html) { boxS.innerHTML = html; if (secS) secS.style.display = 'block'; }
      else if (secS) secS.style.display = 'none';
    } else if (secS) { secS.style.display = 'none'; }
  } catch(e) {}

  // ═══ 🆕 OYUNCU REYTİNGLERİ — lineup.matchRating (sunucu otoritesi) ═══
  try {
    const secR = document.getElementById('resFmRatingsSec');
    const boxR = document.getElementById('resFmRatings');
    const golAt = {}, asistAt = {}, sari = {}, kirmizi = {}, cikan = {}, giren = {};
    (events || []).forEach(e => {
      if (!e) return;
      if (e.type === 'goal' && !e.cancelled) {
        golAt[e.player] = (golAt[e.player] || 0) + 1;
        if (e.assist) asistAt[e.assist] = (asistAt[e.assist] || 0) + 1;
      } else if (e.type === 'yellow') sari[e.player] = true;
      else if (e.type === 'red') kirmizi[e.player] = true;
      else if (e.type === 'sub') { if (e.playerOut) cikan[e.playerOut] = e.min; if (e.player) giren[e.player] = e.min; }
    });
    const takimHtml = (ad, lineup, kisa) => {
      const pl = (Array.isArray(lineup) ? lineup : [])
        .filter(p => p && p.name && typeof p.matchRating === 'number')
        .sort((a, b) => (b.matchRating || 0) - (a.matchRating || 0));
      if (!pl.length) return '';
      const satirlar = pl.map(p => {
        const r = Number(p.matchRating) || 0;
        const cls = r >= 7.5 ? 'hi' : (r < 6.5 ? 'lo' : 'mid');
        const ikon = [
          golAt[p.name] ? '⚽'.repeat(Math.min(3, golAt[p.name])) : '',
          asistAt[p.name] ? '🅰️' : '',
          sari[p.name] ? '🟨' : '',
          kirmizi[p.name] ? '🟥' : '',
          cikan[p.name] ? '🔻' : '',
          giren[p.name] ? '🔺' : ''
        ].filter(Boolean).join(' ');
        return `<div class="rfm-rt">
          <span class="no">${p.num != null ? p.num : ''}</span>
          <span class="nm">${_escapeHtml(p.name)}</span>
          <span class="ic">${ikon}</span>
          <span class="rt ${cls}">${r.toFixed(1)}</span>
        </div>`;
      }).join('');
      return `<div class="rfm-rt-team"><div class="rfm-rt-hd">${_escapeHtml(kisa)} · ${_escapeHtml(ad)}</div>${satirlar}</div>`;
    };
    const h1 = takimHtml(m.home, homeLineup, m.homeShort || (m.home || '').slice(0, 3).toUpperCase());
    const h2 = takimHtml(m.away, awayLineup, m.awayShort || (m.away || '').slice(0, 3).toUpperCase());
    if (boxR && (h1 || h2)) { boxR.innerHTML = h1 + h2; if (secR) secR.style.display = 'block'; }
    else if (secR) secR.style.display = 'none';
  } catch(e) {}

  // 🆕 UZATMA / PENALTI — eleme maçı berabere bittiyse kimin turu geçtiği
  //    skorun hemen altında açıkça yazılır ve kazanan takım işaretlenir.
  let _penInfo = null;
  try {
    _penInfo = _penNormalize(entry && entry.stats);
    if (m && m.matchKey) window._penCache.byKey[m.matchKey] = _penInfo;
    const penEl = document.getElementById('resFmPen');
    if (penEl) {
      if (_penInfo && (_penInfo.pens || _penInfo.et)) {
        const taraf = _penKazananTaraf(_penInfo, m.home, m.away);
        let ic = '';
        if (_penInfo.et) {
          ic += '<div class="res-fm-pen-row"><span class="rfp-et">UZATMA</span>'
              + '<b>' + _penInfo.et[0] + ' - ' + _penInfo.et[1] + '</b></div>';
        }
        if (_penInfo.pens) {
          ic += '<div class="res-fm-pen-row"><span class="rfp-p">PENALTILAR</span>'
              + '<b>' + _penInfo.pens[0] + ' - ' + _penInfo.pens[1] + '</b></div>';
        }
        const kzAd = _penInfo.kazanan || (taraf === 'ev' ? m.home : (taraf === 'dep' ? m.away : ''));
        if (kzAd) ic += '<div class="res-fm-pen-win">🏆 ' + _escapeHtml(kzAd) + ' turu geçti</div>';
        penEl.innerHTML = ic;
        penEl.style.display = ic ? 'block' : 'none';
        // Skor tablosunda kazananı işaretle (90 dk berabere olduğu için
        // normal "winner" sınıfı kimseye verilmiyordu)
        try {
          const hN = document.getElementById('resFmHomeName');
          const aN = document.getElementById('resFmAwayName');
          if (taraf && hN && aN) {
            hN.className = 'res-fm-team-name' + (taraf === 'ev' ? ' winner' : '');
            aN.className = 'res-fm-team-name' + (taraf === 'dep' ? ' winner' : '');
          }
        } catch(e) {}
      } else {
        penEl.style.display = 'none';
        penEl.innerHTML = '';
      }
    }
  } catch(e) {}

  // Status
  const statusEl = document.getElementById('resFmStatus');
  if (statusEl) {
    const _st = entry && entry._status;
    if (_st && _st !== 'finished') {
      statusEl.innerHTML = `🔴 Devam ediyor · <b>${(entry._min || 0)}'</b>`;
    } else {
      const _gc = goals.length;
      const _sh = (entry && typeof entry._hs === 'number') ? entry._hs : m.hs;
      const _sa = (entry && typeof entry._as === 'number') ? entry._as : m.as;
      const _mismatch = (Number(_sh) + Number(_sa)) !== _gc;
      const _sure = (_penInfo && _penInfo.pens) ? 'penaltılar'
                  : ((_penInfo && _penInfo.et) ? "120'" : "90'");
      statusEl.innerHTML = `⚽ Maç tamamlandı · <b>${_sure}</b>` +
        (_mismatch ? ` <span style="color:var(--text3);font-size:10px">· ${_gc} gol kaydı</span>` : '');
    }
  }

  // 🆕 Sekmeler: veri olmayanı pasifleştir, Özet'e dön
  try { _resFmSekmeDurum(); } catch(e) {}
}

function resCloseFinishedMatch() {
  const overlay = document.getElementById('resFmOverlay');
  if (overlay) overlay.classList.remove('open');
}

// 🆕 SONUÇLAR sayfasından maç sonu görüntüleme — ödül gizli, "Listeye Geri Dön"
function resOpenMatchView(matchKey) {
  const m = window._resCurrentMatches && window._resCurrentMatches[matchKey];
  if (!m) return;
  if (!m.played) return;

  // _fixtureData benzeri bir maç objesi inşa et (showHistoricalMatchResult ile uyumlu)
  const matchObj = {
    season: m.season || 1,
    day: m.day || 0,
    home: { name: m.home, short: m.homeShort, rating: 75 },
    away: { name: m.away, short: m.awayShort, rating: 75 },
    hs: m.hs, as: m.as,
    isPast: true,
    comp: m.leagueName || '',
    competition: m.competition || 'league'
  };

  // 🆕 Bayrak: SONUÇLAR'dan açıldı (ödül gizle, Listeye Geri Dön)
  if (typeof MS !== 'undefined') MS._fromResults = true;

  // Geri dönüşte bu sayfaya dönmek için kayıt
  window._resReturnAfter = { mode: 'results' };

  if (typeof showHistoricalMatchResult === 'function') {
    showHistoricalMatchResult(matchObj, null);
  }
}

// ── Fikstür kartından maç ekranına geçiş ──
// Tıklanan maç index'i ile _fixtureData'dan veriyi alır, openMatchScreen'i çağırır.
function openMatchFromFixture(idx) {
  if(typeof _fixtureData === 'undefined' || !_fixtureData) {
    console.warn('Fikstür verisi yok'); return;
  }
  const m = _fixtureData[idx];
  if(!m) { console.warn('Maç bulunamadı: idx', idx); return; }

  // 🆕 Hazırlık maçı zaten oynanmış — yeniden oynatma, skor bilgisi göster
  if (m.isFriendly && m.isPast) {
    if (typeof showJoinToast === 'function') {
      showJoinToast(`⚽ Hazırlık Maçı · ${m.home.name} ${m.hs}–${m.as} ${m.away.name}`);
    }
    return;
  }

  // 🆕 Geçmiş maçlar tekrar izlenmez — doğrudan maç sonu ekranını göster
  if (m.isPast && m.hs !== null && m.hs !== undefined) {
    if (typeof showHistoricalMatchResult === 'function') {
      showHistoricalMatchResult(m, idx);
    }
    return;
  }

  // Takım kısaltmaları için class sınıfı (renk paletinden)
  // hClass/aClass: c1, c2, c3, c4, c5 — ev sahibi/deplasman renk varyantı
  const hClass = 'c1';
  const aClass = 'c2';

  // Lig/turnuva adı — m.comp ('⚽ Süper Lig', '🏆 Championship' gibi)
  const league = (m.comp || 'Maç') + (m.round ? ' · ' + m.round : '');

  // Stadyum adı — ev sahibi takımdan üret
  const venue = (m.home && m.home.name) ? `${m.home.name} Stadyumu` : 'Stadyum';

  // openMatchScreen v1 çağrısı (teams DB'den rating bulup V2'ye delegate edecek)
  openMatchScreen(
    m.home.name,
    m.away.name,
    hClass,
    aClass,
    m.home.short,
    m.away.short,
    league,
    venue,
    m.date  // kickoff tarihi/saati
  );

  // 🆕 Fikstür referansını MS state'e kaydet → maç sonu lig tablosuna sonuç yansıyacak
  if (typeof MS !== 'undefined') {
    MS._fixtureRef = m;
    MS._fixtureIdx = idx;
  }

  // 🆕 Cache'ten istatistik ve olayları çek (varsa) — cache hit'te detay gösterimi için
  let _matchCacheData = null;
  try {
    const _cache = _matchResultsLoad();
    _matchCacheData = _cache[`${m.season}_${m.day}_${m.home.name}_${m.away.name}`] || null;
  } catch(e) {}

  // Eğer maç GEÇMIŞ ise: skoru ekrana yansıt + preview-mode'dan çık + istatistikleri göster
  if(m.isPast && m.hs !== null && m.hs !== undefined) {
    setTimeout(() => {
      // Geçmiş maç → preview gösterme, direkt sonuç + saha
      const ms = document.getElementById('match-screen');
      if (ms) ms.classList.remove('preview-mode');

      const sH = document.getElementById('scoreH');
      const sA = document.getElementById('scoreA');
      const clk = document.getElementById('matchClock');
      const sb = document.getElementById('statusBadge');
      const btnStart = document.getElementById('btnStart');
      if(sH) sH.textContent = String(m.hs);
      if(sA) sA.textContent = String(m.as);
      if(clk) { clk.textContent = "90'"; clk.className = 'match-clock'; }
      if(sb) { sb.className = 'status-badge sb-ft'; sb.innerHTML = '🏁 Maç Sonu'; }
      if(btnStart) { btnStart.disabled = true; btnStart.textContent = '✓ Tamamlandı'; }

      // 🆕 İstatistik DOM'unu kur + cache verisi ile doldur
      try {
        if (typeof initStats === 'function') initStats();
        if (typeof updateStats === 'function') {
          // ÖNCELİK: Edge'in yazdığı gerçek server stats. Yoksa server'dan çek, o da yoksa olaylardan hesapla.
          let _fmStats = (_matchCacheData && _matchCacheData.stats && Array.isArray(_matchCacheData.stats.possession))
            ? _matchCacheData.stats : null;
          if (_fmStats) {
            updateStats(_fmStats, 1);
          } else if (m.matchKey && window.sb) {
            // Server'dan gerçek stats'i ayrı çek (liste cache'i stats taşımıyor — boyut sebebiyle)
            (async () => {
              try {
                const { data } = await window.sb.from('match_state')
                  .select('stats,events').eq('match_key', m.matchKey).maybeSingle();
                let s = (data && data.stats && Array.isArray(data.stats.possession)) ? data.stats : null;
                if (!s && data && Array.isArray(data.events) && typeof _computeMatchStatsFromEvents === 'function') {
                  s = _computeMatchStatsFromEvents(data.events, 90);
                }
                if (s && typeof updateStats === 'function') updateStats(s, 1);
              } catch(e) {}
            })();
          } else if (_matchCacheData && Array.isArray(_matchCacheData.events) && typeof _computeMatchStatsFromEvents === 'function') {
            updateStats(_computeMatchStatsFromEvents(_matchCacheData.events, 90), 1);
          }
        }
      } catch(e) {}

      // 🆕 Olaylar listesini cache'ten doldur
      try {
        const evList = document.getElementById('evList');
        if (evList && _matchCacheData && _matchCacheData.events && _matchCacheData.events.length) {
          evList.innerHTML = '';
          const sortedEv = [..._matchCacheData.events].sort((a,b) => (a.min||0) - (b.min||0));
          sortedEv.forEach(ev => {
            try { if (typeof addEvent === 'function') addEvent(ev); } catch(e) {}
          });
          if (!evList.children.length) {
            evList.innerHTML = '<div style="padding:30px 16px;text-align:center;color:var(--text3);font-size:12px">Maç tamamlandı — özel olay kaydı yok</div>';
          }
        } else if (evList) {
          evList.innerHTML = '<div style="padding:30px 16px;text-align:center;color:var(--text3);font-size:12px">Maç tamamlandı — olay kaydı yok</div>';
        }
      } catch(e) {}

      // 🆕 KADRO sekmesi — cache'teki playerStats'tan oyunculara matchRating bağla
      try {
        if (_matchCacheData && _matchCacheData.playerStats && curHome && curAway) {
          const ps = _matchCacheData.playerStats;
          const _attachRatings = (team) => {
            if (!team || !team.players) return;
            const teamData = ps[team.name];
            if (!Array.isArray(teamData)) return;
            const map = {};
            teamData.forEach(d => { map[d.name] = { rating: d.rating, goals: d.goals, assists: d.assists }; });
            team.players.forEach(p => {
              const m = map[p.name];
              if (m) {
                p.matchRating = m.rating;
                p.matchGoals = m.goals;
                p.matchAssists = m.assists;
              }
            });
          };
          _attachRatings(curHome);
          _attachRatings(curAway);
          if (typeof renderLineup === 'function') renderLineup();
        }
      } catch(e) { console.warn('Cache reyting yükleme:', e); }

      // 🆕 İlk açılan sekme: Olaylar
      try {
        const tabs = document.querySelectorAll('.eng-tab');
        if (tabs && tabs.length >= 1 && typeof showEngTab === 'function') {
          showEngTab('events', tabs[0]);
        }
      } catch(e) {}
    }, 50);
  }

  // CANLI maç (bugünkü) için Başlat butonunu vurgula
  if(m.isCurrentDay) {
    setTimeout(() => {
      const sb = document.getElementById('statusBadge');
      if(sb) { sb.className = 'status-badge sb-pre'; sb.innerHTML = '🔴 Bugün'; }
    }, 50);
  }
}

//   openMatchScreen(hName, aName, hClass, aClass, hShort, aShort, league, venue)
//
// Yeni API (daha temiz):
//   openMatchScreenV2({ home: teamData, away: teamData, league, venue, season, day })
//   teamData = { name, short, countryCode, rating, isUser? }
//
// V1 çağrısı V2'ye delegasyon yapar.
function openMatchScreen(hName,aName,hClass,aClass,hShort,aShort,league,venue,kickoff){
  try { _msApplyKitColors(); } catch(e) {}
  // V1 → V2 adaptasyonu (teams DB'den takım bul, yoksa basit nesne kullan)
  function findTeamByName(name) {
    if(false) return null;
    for(const cc of _cftGetCountryCodes()) {
      const country = _cftGetCountry(cc);
      for(const lg of (country.leagues||[])) {
        const t = (lg.teams||[]).find(x => x.name === name);
        // oz alanını da geçir (getOrCreateTeamRoster effectiveRating için)
        if(t) return { ...t, countryCode: cc, cc };
      }
    }
    return null;
  }

  const homeData = findTeamByName(hName) || { name: hName, short: hShort, rating: 74, countryCode: (authUser && authUser.nationality) || 'TR' };
  const awayData = findTeamByName(aName) || { name: aName, short: aShort, rating: 78, countryCode: (authUser && authUser.nationality) || 'TR' };

  // Kullanıcının kendi takımıysa işaretle
  if(typeof _userTeam !== 'undefined' && _userTeam) {
    if(_userTeam.teamName === hName) homeData.isUser = true;
    if(_userTeam.teamName === aName) awayData.isUser = true;
  }

  return openMatchScreenV2({
    home: homeData,
    away: awayData,
    league: league || 'Maç',
    venue: venue || homeData.name + ' Stadyumu',
    hClass: hClass || 'c1',
    aClass: aClass || 'c2',
    kickoff: kickoff || new Date(),
  });
}



// ══════════════════════════════════════════════════════
//  MATCH PREVIEW HELPER FONKSİYONLARI
// ══════════════════════════════════════════════════════

// Tarih formatı (TR): "26 Nis 2026 Pzr"
function fmtMatchDate(date) {
  if (!date || !(date instanceof Date)) return '—';
  const months = ['Oca','Şub','Mar','Nis','May','Haz','Tem','Ağu','Eyl','Eki','Kas','Ara'];
  const days = ['Pzr','Pzt','Sal','Çar','Per','Cum','Cmt'];
  return `${date.getDate()} ${months[date.getMonth()]} ${date.getFullYear()} ${days[date.getDay()]}`;
}

// Saat formatı: "19:30"
function fmtMatchTime(date) {
  if (!date || !(date instanceof Date)) return '19:00';
  const h = String(date.getHours()).padStart(2, '0');
  const m = String(date.getMinutes()).padStart(2, '0');
  return `${h}:${m}`;
}

// Para formatı (€): 1.5M, 850K, 12K
function fmtEUR(v) {
  if (!v || v < 0) return '— €';
  if (v >= 1e9) return (v/1e9).toFixed(1).replace(/\.0$/, '') + 'B €';
  if (v >= 1e6) return (v/1e6).toFixed(1).replace(/\.0$/, '') + 'M €';
  if (v >= 1e3) return Math.round(v/1e3) + 'K €';
  return v + ' €';
}

// Son 5 maç W/D/L — gerçek cft_match_results cache'inden
// Yetersiz veri varsa "?" ile doldurulur
function getTeamLast5Matches(team) {
  const teamName = team.name || team.teamName || 'Team';

  let cache = {};
  try { cache = _matchResultsLoad(); } catch(e) {}

  // Bu takımın tüm oynanmış maçlarını topla
  const matches = [];
  Object.values(cache).forEach(m => {
    if (!m || (m.home !== teamName && m.away !== teamName)) return;
    if (m.hs === undefined || m.hs === null) return;

    let result;
    if (m.hs === m.as) result = 'D';
    else if (m.home === teamName) result = (m.hs > m.as) ? 'W' : 'L';
    else result = (m.as > m.hs) ? 'W' : 'L';

    matches.push({
      result,
      ts: m.playedAt || (((m.season || 1) * 1000 + (m.day || 0)) * 86400000) // fallback
    });
  });

  // En yeniden eskiye sırala, en yeni 5'i al
  matches.sort((a, b) => b.ts - a.ts);
  const last5 = matches.slice(0, 5);

  // Sonuçları eski → yeni sırasına çevir (UI sağda en yeni gösterir)
  const results = last5.reverse().map(m => m.result);

  // Eksikleri "?" ile doldur (en eski tarafta)
  while (results.length < 5) {
    results.unshift('?');
  }

  return results;
}

// Takım değeri (€)
// ═══════════════════════════════════════════════════════════════════
//  TAKIM PİYASA DEĞERİ — Oyuncuların toplamı (botlar dahil)
// ═══════════════════════════════════════════════════════════════════
// Takım piyasa değeri statik bir formül DEĞİLDİR; her oyuncunun (kullanıcı +
// bot) piyasa değerinin TOPLAMI olarak hesaplanır. Tam 15 kişilik kadro
// üzerinden hesaplanır (sadece sahada olan 11 değil).
//
// Oyuncu piyasa değeri: getPlayerMarketValue() → captainMV override veya
// otomatik tahmin (overall² × 200 + level × 50K).
//
// Maç önizleme ekranı (fillPreMatchPreview) bu değeri okur. Maç önizlemesinde
// 11 kişilik squad gelse bile fonksiyon teams DB'den tam kadroyu bulur.
// ═══════════════════════════════════════════════════════════════════
// 🆕 TEK KAYNAK piyasa değeri: teams.market_value (edge). _cftDb[].oz'a yüklenir
//   (bootstrap + _rkRefreshStats + antrenman sonrası recompute). Hero ve Sıralama AYNI değeri okur.
function _teamStoredMV(cc, name){
  try {
    const country = (typeof _cftGetCountry === 'function') ? _cftGetCountry(cc) : null;
    if (country && Array.isArray(country.leagues)) {
      for (const lg of country.leagues) {
        const t = (lg.teams || []).find(x => x && x.name === name);
        if (t && Number.isFinite(Number(t.oz))) return Number(t.oz);
      }
    }
  } catch(e) {}
  return 0;
}
function calculateTeamValue(team) {
  if (!team) return 0;
  const teamName = team.name || team.teamName || '';
  const cc       = team.countryCode || team.cc || null;
  const isUserTeam = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName === teamName);

  // Helper: bir oyuncu listesinin toplam piyasa değeri
  const _sumValues = (players) => {
    if (!Array.isArray(players) || !players.length) return 0;
    let total = 0;
    for (const p of players) {
      if (!p) continue;
      total += (typeof getPlayerMarketValue === 'function') ? getPlayerMarketValue(p) : 0;
    }
    return total;
  };

  // Helper: teams DB'de takım adına göre tam kayıt (countryCode dahil) bul
  const _lookupInDB = (name) => {
    if (!name || false) return null;
    for (const xcc of _cftGetCountryCodes()) {
      const country = _cftGetCountry(xcc);
      if (!country || !Array.isArray(country.leagues)) continue;
      for (const lg of country.leagues) {
        if (!lg || !Array.isArray(lg.teams)) continue;
        const found = lg.teams.find(x => x.name === name);
        if (found) return { ...found, countryCode: xcc, cc: xcc };
      }
    }
    return null;
  };

  // 1) Kullanıcı takımı → ROSTER_DATA (tam 15 kişilik kadro)
  if (isUserTeam && typeof ROSTER_DATA !== 'undefined' && ROSTER_DATA.length) {
    return _sumValues(ROSTER_DATA);
  }

  // 2) Bot takım, countryCode biliniyor → direkt kadroyu al
  if (typeof getOrCreateTeamRoster === 'function' && teamName && cc) {
    try {
      return _sumValues(getOrCreateTeamRoster(team));
    } catch(e) {}
  }

  // 3) Sadece isim biliniyor (ör. matchday squad obj'i) → teams DB'de ara
  //    Bu, fillPreMatchPreview'in 11'lik squad ile çağırdığı durumu yakalar.
  if (typeof getOrCreateTeamRoster === 'function' && teamName) {
    const found = _lookupInDB(teamName);
    if (found) {
      try {
        return _sumValues(getOrCreateTeamRoster(found));
      } catch(e) {}
    }
  }

  // 4) Son çare: nesnedeki players listesi (matchday squad fallback)
  if (Array.isArray(team.players) && team.players.length) {
    return _sumValues(team.players);
  }

  return 0;
}

// Takım gelişim yüzdesi (sadece kullanıcı takımı için, diğerleri null)
function getTeamDevPercent(team) {
  const teamName = team.name || team.teamName || 'Team';
  const isUserTeam = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName === teamName);

  if (isUserTeam && typeof calcDevLevel === 'function') {
    return calcDevLevel().pct;
  }
  // Bot takımları için sentetik (rating - 60) ile yaklaşık
  const rating = team.rating || team.overall || 70;
  return Math.max(10, Math.min(95, Math.round((rating - 50) * 1.6)));
}

// 🆕 Hat güçleri: GK / DEF / MID / FWD ortalamaları (oyuncu posGroup üzerinden)
function calcLineStrengths(team) {
  const teamName = team && (team.name || team.teamName) || '';
  // 🆕 TEK KAYNAK: Supabase teams.team_lines (edge yazar). Varsa direkt oku — frontend hesap YOK.
  try {
    const _ut = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName === teamName);
    const _cc = (team && (team.countryCode || team.cc)) || (_ut ? _userTeam.countryCode : null);
    let _L = null;
    if (_cc && window._teamLinesMap) _L = window._teamLinesMap[_cc + ':' + teamName];
    if (!_L && _cc && typeof _cftGetCountry === 'function') {
      const c = _cftGetCountry(_cc);
      if (c && Array.isArray(c.leagues)) {
        for (const lg of c.leagues) { const t = (lg.teams||[]).find(x => x && x.name === teamName); if (t && t.teamLines) { _L = t.teamLines; break; } }
      }
    }
    if (_L && typeof _L.GK === 'number' && typeof _L.DEF === 'number' && typeof _L.MID === 'number' && typeof _L.FWD === 'number') {
      return { GK: _L.GK, DEF: _L.DEF, MID: _L.MID, FWD: _L.FWD };
    }
  } catch(e) {}
  const isUserTeam = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName === teamName);
  const teamRating = (team && (team.rating || team.overall)) || 70;
  const POSGRP = (typeof POS_GROUP !== 'undefined') ? POS_GROUP
    : { KL:'GK', STB:'DEF', SB:'DEF', DOS:'MID', OS:'MID', SAK:'MID', FWD:'FWD' };

  // 🆕 Her oyuncunun GERÇEK overall değeri:
  //   - Kullanıcı (role='user') → Supabase user_player.overall (skill ortalaması)
  //   - Bot → abilities tablosundan ana mevkinin yetenek ortalaması
  //   - Gerçek başka kullanıcı → DB overall
  // p.overall stale olabilir (cache), bu yüzden TEK KAYNAK getPlayerMainOverall.
  // Hat değeri = oyuncunun GENEL OVR'i (kart OVR = getPlayerMainOverall). Hat = o hattaki oyuncuların genel OVR ortalaması.
  const _getOvr = (p) => {
    if (typeof getPlayerMainOverall === 'function') return getPlayerMainOverall(p);
    return p.overall || p.rating || 10;
  };

  let players = [];
  // Kullanıcı takımı → ROSTER_DATA
  if (isUserTeam && typeof ROSTER_DATA !== 'undefined' && ROSTER_DATA && ROSTER_DATA.length) {
    players = ROSTER_DATA.map(p => { const grp = p.posGroup || POSGRP[p.pos] || 'MID'; return { grp, ovr: _getOvr(p, grp) }; });
  } else if (team && Array.isArray(team.players) && team.players.length) {
    players = team.players.map(p => { const grp = p.posGroup || POSGRP[p.pos] || 'MID'; return { grp, ovr: _getOvr(p, grp) }; });
  }

  if (!players.length) {
    return { GK: teamRating, DEF: teamRating, MID: teamRating, FWD: teamRating };
  }

  const groups = { GK: [], DEF: [], MID: [], FWD: [] };
  players.forEach(p => { if (groups[p.grp]) groups[p.grp].push(p.ovr); });
  const avg = arr => arr.length
    ? Math.round(arr.reduce((s,v)=>s+v,0) / arr.length)
    : teamRating;

  return {
    GK:  avg(groups.GK),
    DEF: avg(groups.DEF),
    MID: avg(groups.MID),
    FWD: avg(groups.FWD)
  };
}

// 🆕 Hat güçlerini ana sayfa preview'una uygula (text + bar + altın vurgu)
function _hmFillLines(home, away) {
  if (typeof calcLineStrengths !== 'function') return;
  const hL = calcLineStrengths(home);
  const aL = calcLineStrengths(away);
  if (!hL || !aL) return;

  const setText = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
  const setBar  = (id, v) => {
    const el = document.getElementById(id);
    if (el) el.style.width = Math.max(0, Math.min(100, v)) + '%';
  };

  // Sayılar
  setText('hmNmHomeGK', hL.GK);  setText('hmNmHomeDF', hL.DEF);
  setText('hmNmHomeMD', hL.MID); setText('hmNmHomeFW', hL.FWD);
  setText('hmNmAwayGK', aL.GK);  setText('hmNmAwayDF', aL.DEF);
  setText('hmNmAwayMD', aL.MID); setText('hmNmAwayFW', aL.FWD);

  // Bar genişlikleri (0–100)
  setBar('hmNmHomeGKBar', hL.GK);  setBar('hmNmHomeDFBar', hL.DEF);
  setBar('hmNmHomeMDBar', hL.MID); setBar('hmNmHomeFWBar', hL.FWD);
  setBar('hmNmAwayGKBar', aL.GK);  setBar('hmNmAwayDFBar', aL.DEF);
  setBar('hmNmAwayMDBar', aL.MID); setBar('hmNmAwayFWBar', aL.FWD);

  // Daha güçlü hat → satıra altın vurgu
  const mark = (hId, aId, hVal, aVal) => {
    const hEl = document.getElementById(hId);
    const aEl = document.getElementById(aId);
    const hP = hEl ? hEl.parentElement : null;
    const aP = aEl ? aEl.parentElement : null;
    if (hP) hP.classList.toggle('better', hVal > aVal);
    if (aP) aP.classList.toggle('better', aVal > hVal);
  };
  mark('hmNmHomeGK','hmNmAwayGK', hL.GK,  aL.GK);
  mark('hmNmHomeDF','hmNmAwayDF', hL.DEF, aL.DEF);
  mark('hmNmHomeMD','hmNmAwayMD', hL.MID, aL.MID);
  mark('hmNmHomeFW','hmNmAwayFW', hL.FWD, aL.FWD);
}

// ════════════════════════════════════════════════════════════════
// 🆕 TURNUVA MAÇI — ANA SAYFA PREVIEW ENTEGRASYONU
// ════════════════════════════════════════════════════════════════

// 4 takımlı grupta klasik round-robin (Berger tablosu)
// 6 matchday × 2 maç = 12 maç (ev + deplasman çifti)
const _TRN_GROUP_MATCHDAYS = [
  [[0,3], [1,2]], // MD1
  [[0,2], [3,1]], // MD2
  [[0,1], [2,3]], // MD3
  [[3,0], [2,1]], // MD4 = rövanş MD1
  [[2,0], [1,3]], // MD5 = rövanş MD2
  [[1,0], [3,2]], // MD6 = rövanş MD3
];

function _trnGroupGetUserMatch(groupTeams, userIdx, matchdayN) {
  const md = _TRN_GROUP_MATCHDAYS[matchdayN - 1];
  if (!md || userIdx < 0 || userIdx >= 4 || !groupTeams || groupTeams.length < 4) return null;
  for (const [hi, ai] of md) {
    if (hi === userIdx) return { home: groupTeams[hi], away: groupTeams[ai], userIsHome: true };
    if (ai === userIdx) return { home: groupTeams[hi], away: groupTeams[ai], userIsHome: false };
  }
  return null;
}

// Bracket round'unda kullanıcının maçını bul (leg 1 = orijinal sıra, leg 2 = rövanş)
function _trnBracketGetUserMatch(bracket, userTeamName, userCountry, roundIdx, leg) {
  if (!bracket || !bracket[roundIdx] || !bracket[roundIdx].matches) return null;
  const matches = bracket[roundIdx].matches;
  const m = matches.find(mt => mt && mt.home && mt.away && (
    (mt.home.name === userTeamName && mt.home.countryKey === userCountry) ||
    (mt.away.name === userTeamName && mt.away.countryKey === userCountry)
  ));
  if (!m) return null;
  const userOrigIsHome = (m.home.name === userTeamName && m.home.countryKey === userCountry);
  const userIsHome = (leg === 1) ? userOrigIsHome : !userOrigIsHome;
  // userIsHome'a göre home/away seç
  return userIsHome
    ? { home: userOrigIsHome ? m.home : m.away, away: userOrigIsHome ? m.away : m.home, userIsHome: true }
    : { home: userOrigIsHome ? m.away : m.home, away: userOrigIsHome ? m.home : m.away, userIsHome: false };
}

// 🆕 Kullanıcının uyruğu (asıl pasaport CC) - milli takım maçları için
function getUserNationalityCC() {
  if (typeof authUser === 'undefined' || !authUser) return null;
  return authUser.nationality || authUser.countryCode || null;
}
// 820 — ana sayfa önizlemesinde "benim milli takımım": uyruğu oyundaki 32 ülkeden biriyse o; değilse oynadığı ligin ülkesi
//   (milli takımı oyunda olmayan uyruktaki oyuncu, oynadığı ülkenin milli maçlarını önizlemede görür)
function _hmMilliCC() {
  const nat = getUserNationalityCC();
  try {
    if (typeof _cftGetCountry !== 'function') return nat;
    if (nat && _cftGetCountry(nat)) return nat;
    const tc = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.countryCode) || null;
    if (tc && _cftGetCountry(tc)) return tc;
  } catch (e) {}
  return nat;
}

// 🆕 Kullanıcı milli takım kadrosunda mı? (oynayabilir mi)
function isUserInNationalSquad() {
  // 572 — sunucuyla aynı kural (başkanın kadrosu ya da otomatik kadro)
  const cc = getUserNationalityCC();
  if (!cc) return false;
  try { return (typeof ntKullaniciKadrodaMi === 'function') ? ntKullaniciKadrodaMi(cc) : false; }
  catch(e) { return false; }
}

// 🆕 Kullanıcının uyruğunun bir sonraki milli takım (EURO Cup) maçını döndürür
// Tüm o uyruklu oyuncular için ana sayfada görünür. NT kadrosundakiler oynar,
// diğerleri izleyici modunda seyreder.
function getNextNationalTeamMatch(ccArg) {
  // 572 — ccArg: başka ülkenin milli takımını yöneten T.D. / yardımcı için o ülke
  const cc = ccArg || getUserNationalityCC();
  if (!cc) return null;
  if (typeof getSeasonInfo !== 'function') return null;
  if (typeof encLoad !== 'function') return null;

  const info = getSeasonInfo();
  if (info.preSeason) return null;
  const season = info.season;

  // EURO Cup sezon 2'den itibaren oynanır
  if (season < 2) return null;

  const state = encLoad(season);
  if (!state || !state.groups) return null;

  // SEASON_TEMPLATE'te EURO Cup günleri (gün → tur)
  const ENC_DAYS = {
    34: 'Grup 1. Maç',
    35: 'Grup 2. Maç',
    36: 'Grup 3. Maç',
    37: 'Son 16',
    38: 'Çeyrek Final',
    39: 'Yarı Final',
    40: 'Final 🏆',
  };

  const seasonStart = info.seasonStart ? new Date(info.seasonStart) : null;
  if (!seasonStart) return null;

  // Bugünden itibaren gelecek olan ilk maç günü
  const dayInSeason = info.dayInSeason || 1;
  const candidateDays = Object.keys(ENC_DAYS).map(Number).sort((a,b) => a - b);
  const upcomingDays = candidateDays.filter(d => d >= dayInSeason);
  if (!upcomingDays.length) return null;

  // Her aday günde kullanıcı ülkesinin maçı var mı bul
  for (const matchDay of upcomingDays) {
    const round = ENC_DAYS[matchDay];

    // Grup maçları (gün 34-36 → grup 1/2/3)
    if (matchDay >= 34 && matchDay <= 36) {
      const groupRound = matchDay - 33; // 1, 2, 3
      const userMatch = (() => {
        for (const g of state.groups) {
          for (const m of (g.matches || [])) {
            if (m.day === groupRound && (m.home === cc || m.away === cc)) return m;
          }
        }
        return null;
      })();
      if (userMatch) {
        const matchDate = new Date(seasonStart.getTime() + (matchDay - 1) * 86400000);
        matchDate.setHours(20, 0, 0, 0); // 20:00 default
        return {
          cc,
          match: userMatch,
          round: 'Grup ' + groupRound + '. Maç',
          date: matchDate,
          day: matchDay,
          phase: 'group',
        };
      }
    }

    // Knockout maçları (gün 37-40)
    if (matchDay >= 37 && matchDay <= 40 && state.knockout) {
      const k = state.knockout;
      let stageMatches = [];
      if (matchDay === 37) stageMatches = k.r16 || [];
      else if (matchDay === 38) stageMatches = k.qf || [];
      else if (matchDay === 39) stageMatches = k.sf || [];
      else if (matchDay === 40) stageMatches = k.final ? [k.final] : [];

      const userMatch = stageMatches.find(m => m && (m.home === cc || m.away === cc));
      if (userMatch) {
        const matchDate = new Date(seasonStart.getTime() + (matchDay - 1) * 86400000);
        matchDate.setHours(20, 0, 0, 0);
        return {
          cc,
          match: userMatch,
          round,
          date: matchDate,
          day: matchDay,
          phase: 'knockout',
        };
      }
    }
  }

  return null;
}

// Kullanıcının sıradaki turnuva maçı (grup veya eleme)
function getNextUserTournamentMatch() {
  if (typeof _userTeam === 'undefined' || !_userTeam) return null;
  // 🆕 Sezon 1'de europeanCup boş olabilir — getUserTurnuva() Sezon 1 fallback verir
  const trnType = (_userTeam.europeanCup) ||
                  ((typeof getUserTurnuva === 'function') ? getUserTurnuva() : null);
  if (!trnType) return null;
  if (typeof getSeasonInfo !== 'function' || typeof SEASON_TEMPLATE === 'undefined') return null;
  if (typeof trn2GetQualifiers !== 'function' || typeof trn2BuildPlayoff !== 'function') return null;
  if (typeof trn2BuildGroups !== 'function' || typeof trn2BuildBracket !== 'function') return null;

  const TYPE_TO_TKEY = { chm: 'champ', eli: 'elite', con: 'conv' };
  const trnKey  = TYPE_TO_TKEY[trnType];        // 'champ' | 'elite' | 'conv'
  if (!trnKey) return null;

  const info = getSeasonInfo();
  if (info.preSeason) return null;
  const { season, dayInSeason, seasonStart, SEASON_LEN } = info;

  const userTeamName = _userTeam.teamName;
  const userCountry  = _userTeam.countryCode;

  // Yapıları kur (playoff + groups + bracket)
  let playoff = null, groups = null, bracket = null, userGroup = null, userIdx = -1;
  let status = null;
  try {
    if (typeof trn2GetUserStatus === 'function') status = trn2GetUserStatus(trnKey, season);
    const qual = trn2GetQualifiers(season);
    if (!qual[trnKey] || qual[trnKey].length === 0) return null;
    playoff = trn2BuildPlayoff(qual[trnKey], season, trnKey);
    if (status && status.won) {
      const winners = playoff.map(m => m.winner);
      groups = trn2BuildGroups(winners, season, trnKey);
      groups.forEach(g => {
        const i = g.teams.findIndex(t => t.name === userTeamName && t.countryKey === userCountry);
        if (i !== -1) { userGroup = g; userIdx = i; }
      });
      if (userGroup) bracket = trn2BuildBracket(groups, season, trnKey);
    }
  } catch(e) { return null; }

  // Sezon takvimini bugünden itibaren ileri tara
  for (let d = dayInSeason; d <= SEASON_LEN; d++) {
    const evs = SEASON_TEMPLATE[d];
    if (!evs) continue;
    const ev = evs.find(e => e && e.type === trnType);
    if (!ev) continue;

    const round = ev.round || '';
    let userMatch = null;
    let roundLabel = round;

    if (/Play-off/i.test(round)) {
      if (playoff) {
        const m = playoff.find(mm =>
          (mm.home.name === userTeamName && mm.home.countryKey === userCountry) ||
          (mm.away.name === userTeamName && mm.away.countryKey === userCountry));
        if (m) {
          const isHome = (m.home.name === userTeamName && m.home.countryKey === userCountry);
          userMatch = { home: m.home, away: m.away, userIsHome: isHome };
        }
      }
      roundLabel = 'Play-off';
    } else {
      const grupMatch = round.match(/Grup\s*(\d+)\.\s*Maç/i);
      if (grupMatch && userGroup) {
        const matchdayN = parseInt(grupMatch[1], 10);
        userMatch = _trnGroupGetUserMatch(userGroup.teams, userIdx, matchdayN);
        roundLabel = `Grup ${matchdayN}. Maç`;
      } else if (/Son 16/i.test(round)) {
        const leg = /\b2\.\s*Maç/i.test(round) ? 2 : 1;
        userMatch = _trnBracketGetUserMatch(bracket, userTeamName, userCountry, 0, leg);
        roundLabel = `Son 16 · ${leg}. Maç`;
      } else if (/Çeyrek/i.test(round)) {
        const leg = /-\s*2/.test(round) ? 2 : 1;
        userMatch = _trnBracketGetUserMatch(bracket, userTeamName, userCountry, 1, leg);
        roundLabel = `Çeyrek Final · ${leg}. Maç`;
      } else if (/Yarı Final/i.test(round)) {
        const leg = /-\s*2/.test(round) ? 2 : 1;
        userMatch = _trnBracketGetUserMatch(bracket, userTeamName, userCountry, 2, leg);
        roundLabel = `Yarı Final · ${leg}. Maç`;
      } else if (/Final/i.test(round)) {
        userMatch = _trnBracketGetUserMatch(bracket, userTeamName, userCountry, 3, 1);
        roundLabel = 'Final 🏆';
      }
    }

    if (!userMatch) continue;

    // Tarih & saat (turnuva 19:00–22:00 deterministik)
    const date = new Date(seasonStart);
    date.setDate(seasonStart.getDate() + (d - 1));
    const hourSeed = ((season * 71 + d * 13 + trnKey.charCodeAt(0)) & 0x7fffffff) % 4;
    date.setHours(19 + hourSeed, (hourSeed * 15) % 60, 0, 0);

    // Geçmiş maç (kickoff + 120dk geçti) → atla
    if (Date.now() > date.getTime() + 120 * 60 * 1000) continue;

    return {
      type: 'tournament',
      home: userMatch.home,
      away: userMatch.away,
      date,
      trnType,
      trnKey,
      round: roundLabel,
      userIsHome: userMatch.userIsHome
    };
  }

  return null;
}

// 🆕 Turnuva maçını ana sayfa hm-nm panelinde render et
function _renderHmTournamentMatch(t) {
  try { _hmBtnNormal(); } catch(e) {}          // 🆕 buton normal davranışa dönsün

  const panel   = document.getElementById('hmNextMatch');
  const noMatch = document.getElementById('hmNoMatch');
  if (!panel || !noMatch) return;
  if (!t || !t.home || !t.away) return;

  // teams DB'den tam takım objesi (rating + players + bg/tc renkleri için)
  const _findTeam = (cc, name) => {
    if (false || !_cftGetCountry(cc)) return null;
    for (const lg of (_cftGetCountry(cc).leagues || [])) {
      const tm = (lg.teams || []).find(x => x.name === name);
      if (tm) return tm;
    }
    return null;
  };
  const home = _findTeam(t.home.countryKey, t.home.name) || t.home;
  const away = _findTeam(t.away.countryKey, t.away.name) || t.away;

  // Tarih & saat
  const d = (t.date instanceof Date) ? t.date : new Date(t.date);
  const DAYS   = ['Paz','Pzt','Sal','Çar','Per','Cum','Cmt'];
  const MONTHS = ['Oca','Şub','Mar','Nis','May','Haz','Tem','Ağu','Eyl','Eki','Kas','Ara'];
  let dateStr = '—', hourStr = '—';
  if (!isNaN(d.getTime())) {
    dateStr = `${DAYS[d.getDay()]} ${d.getDate()} ${MONTHS[d.getMonth()]}`;
    hourStr = `${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
  }

  const homeForm = (typeof getTeamLast5Matches === 'function') ? getTeamLast5Matches(home) : [];
  const awayForm = (typeof getTeamLast5Matches === 'function') ? getTeamLast5Matches(away) : [];
  const formHtml = (results, rev) => {
    const cells = Array(5).fill('q');
    results.slice(-5).forEach((r, i) => { cells[i] = (r === '?' ? 'q' : r.toLowerCase()); });
    const _lk = window._ligKolon(); const labels = { w:_lk.g, d:_lk.b, l:_lk.m, q:'?' };
    const arr = rev ? [...cells].reverse() : cells;
    return arr.map(r => `<div class="hm-nm-fc ${r}">${labels[r]||'?'}</div>`).join('');
  };

  const homeRating = home.rating || home.overall || 70;
  const awayRating = away.rating || away.overall || 70;
  const totalRating = homeRating + awayRating || 1;
  const homePct = Math.round(homeRating / totalRating * 100);
  const homeDev = (typeof getTeamDevPercent === 'function') ? getTeamDevPercent(home) : Math.round((homeRating - 50) * 1.4);
  const awayDev = (typeof getTeamDevPercent === 'function') ? getTeamDevPercent(away) : Math.round((awayRating - 50) * 1.4);
  const homeVal = (typeof fmtEUR === 'function' && typeof calculateTeamValue === 'function') ? fmtEUR(calculateTeamValue(home)) : homeRating + 'puan';
  const awayVal = (typeof fmtEUR === 'function' && typeof calculateTeamValue === 'function') ? fmtEUR(calculateTeamValue(away)) : awayRating + 'puan';

  const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
  const setHtml = (id, v) => { const el = document.getElementById(id); if (el) el.innerHTML = v; };

  const TRN_LABEL = { chm: 'Championship', eli: 'Elite', con: 'Convergence' };
  _hmCompYaz(_cupLogoInline(_trnTypeToCupKey(t.trnType), 24), TRN_LABEL[t.trnType] || 'Turnuva', t.round || '', TRN_LABEL[t.trnType] ? 'en' : '');
  _hmTarihYaz(dateStr, hourStr);
  set('hmNmHomeName', home.name);
  set('hmNmAwayName', away.name);
  set('hmNmVenue',    home.name + ' Stad.');

  _setRatingBadge('hmNmHomeStrength', homeRating);
  _setRatingBadge('hmNmAwayStrength', awayRating);
  set('hmNmHomeDev',  (homeDev >= 0 ? '+' : '') + homeDev + '%');
  set('hmNmAwayDev',  (awayDev >= 0 ? '+' : '') + awayDev + '%');
  set('hmNmHomeVal',  homeVal);
  set('hmNmAwayVal',  awayVal);

  try { _hmFillLines(home, away); } catch(e) {}

  _hmGucYaz(homePct);

  setHtml('hmNmHomeForm', formHtml(homeForm, false));
  setHtml('hmNmAwayForm', formHtml(awayForm, true));

  const setCrest = (id, team) => {
    const el = document.getElementById(id);
    if (!el) return;
    if (typeof applyCrestToEl === 'function') {
      applyCrestToEl(el, team.name, team.short || (team.name ? team.name.slice(0,3).toUpperCase() : '—'));
    } else {
      el.textContent = team.short || (team.name ? team.name.slice(0,3).toUpperCase() : '—');
      if (team.bg) el.style.background = team.bg;
      if (team.tc) el.style.color = team.tc;
    }
  };
  setCrest('hmNmHomeCrest', home);
  setCrest('hmNmAwayCrest', away);

  // 🆕 Crest tıklama
  _hmAttachCrestClick('hmNmHomeCrest', home, null);
  _hmAttachCrestClick('hmNmAwayCrest', away, null);

  // 🆕 Buton — lig maçıyla aynı: canlı geri sayım + 2dk içinde "Maça Git" (turnuva altın varyant)
  const btn = document.getElementById('hmNmBtn');
  if (btn) {
    if (window._hmNmBtnTimer) {
      clearInterval(window._hmNmBtnTimer);
      window._hmNmBtnTimer = null;
    }
    const kickoffTime = d ? d.getTime() : null;

    function _updateTrnBtn() {
      if (!kickoffTime) {
        _hmBtnYaz(btn, '', 'Turnuva Maçı');
        btn.disabled = false;
        return;
      }
      const diffMs = kickoffTime - Date.now();
      const TWO_MIN = 2 * 60 * 1000;
      const MATCH_DURATION = 15 * 60 * 1000;

      if (diffMs < -MATCH_DURATION) {
        clearInterval(window._hmNmBtnTimer);
        window._hmNmBtnTimer = null;
        if (typeof renderHomeNextMatch === 'function') {
          try { renderHomeNextMatch(); } catch(e){}
        }
        return;
      }

      if (diffMs <= TWO_MIN) {
        _hmBtnYaz(btn, 'Canlı', 'Maça Git', 'canli');
        btn.disabled = false;
      } else {
        const totalSec = Math.floor(diffMs / 1000);
        const h = Math.floor(totalSec / 3600);
        const mn = Math.floor((totalSec % 3600) / 60);
        const s = totalSec % 60;
        const pad = n => String(n).padStart(2, '0');
        _hmBtnSayac(btn, `${pad(h)}:${pad(mn)}:${pad(s)}`);
        btn.disabled = false;
      }
    }

    _updateTrnBtn();
    window._hmNmBtnTimer = setInterval(() => {
      if (!document.body.contains(btn)) {
        clearInterval(window._hmNmBtnTimer);
        window._hmNmBtnTimer = null;
        return;
      }
      if (document.hidden) return;      // 🆕 arka planda geri sayım yazma
      _updateTrnBtn();
    }, 1000);
  }

  panel._nextMatchRef = { isTournament: true, tournamentData: t };
  panel.style.display = 'block';
  noMatch.style.display = 'none';
}




// Pre-match preview ekranını doldur
function fillPreMatchPreview(home, away, league, venue, kickoff) {
  // Header
  const dateEl = document.getElementById('mpDate');
  const timeEl = document.getElementById('mpTime');
  const compEl = document.getElementById('mpComp');
  const venueEl = document.getElementById('mpVenue');
  if (compEl) compEl.textContent = league || '⚽ Maç';
  if (venueEl) venueEl.textContent = '📍 ' + (venue || 'Stadyum');
  if (dateEl) dateEl.textContent = fmtMatchDate(kickoff);
  if (timeEl) timeEl.textContent = fmtMatchTime(kickoff);

  // Takım blokları - logo varsa storage'dan, yoksa short text fallback
  const _mpHomeCrest = document.getElementById('mpHomeCrest');
  const _mpAwayCrest = document.getElementById('mpAwayCrest');
  const _hShort = home.short || home.name.substring(0,3).toUpperCase();
  const _aShort = away.short || away.name.substring(0,3).toUpperCase();
  if (typeof applyCrestToEl === 'function') {
    applyCrestToEl(_mpHomeCrest, home.name, _hShort);
    applyCrestToEl(_mpAwayCrest, away.name, _aShort);
  } else {
    _mpHomeCrest.textContent = _hShort;
    _mpAwayCrest.textContent = _aShort;
  }
  document.getElementById('mpHomeName').textContent = home.name;
  document.getElementById('mpAwayName').textContent = away.name;

  // 🆕 Takım logosuna tıklama → takım sayfası aç
  // Kullanıcının takımı ise: kendi takım sayfasına (showPage)
  // Bot takımı ise: ziyaretçi modunda (viewTeam)
  function _openTeamFromMatch(t) {
    if (!t || !t.name) return;
    const cc = t.countryCode || t.cc || null;
    const isUserTeam = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName === t.name);
    if (isUserTeam) {
      // Kendi takımı → ziyaretçi modunda değilse showPage, modunda ise çıkış
      if (typeof exitGuestMode === 'function' && typeof _viewingTeam !== 'undefined' && _viewingTeam) {
        try { exitGuestMode(true); return; } catch(e) {}
      }
      if (typeof showPage === 'function') {
        try { showPage('team', null); } catch(e) {}
      }
    } else {
      // Bot takımı → ziyaretçi modunda aç
      if (typeof viewTeam === 'function' && cc) {
        try { viewTeam(cc, t.name); } catch(e) { console.warn('viewTeam hata:', e); }
      }
    }
  }
  // Sadece crest (logo) tıklanabilir
  const homeCrestEl = document.getElementById('mpHomeCrest');
  const awayCrestEl = document.getElementById('mpAwayCrest');
  if (homeCrestEl) {
    homeCrestEl.style.cursor = 'pointer';
    homeCrestEl.onclick = (e) => { e.stopPropagation(); _openTeamFromMatch(home); };
  }
  if (awayCrestEl) {
    awayCrestEl.style.cursor = 'pointer';
    awayCrestEl.onclick = (e) => { e.stopPropagation(); _openTeamFromMatch(away); };
  }

  // 🆕 Rating = takım gücü, HERO/SIRALAMA ile AYNI kaynaktan (_teamPowerFromPlayers).
  //   Tekrar hesap YOK: kullanıcı takımı → _userTeamDbOvr (hero'daki değer), rakip → edge team_ovr.
  const _mpPow = (t) => {
    if (!t || !t.name) return 10;
    const cc = t.countryCode || t.cc || null;
    if (typeof _teamPowerFromPlayers === 'function') {
      return _teamPowerFromPlayers(cc, t.name, t.rank || 1);
    }
    return t.rating || t.overall || 10;
  };
  const homeRating = _mpPow(home);
  const awayRating = _mpPow(away);
  const hRatEl = document.getElementById('mpHomeRating');
  const aRatEl = document.getElementById('mpAwayRating');
  hRatEl.textContent = homeRating;
  aRatEl.textContent = awayRating;
  // Renkli vurgu (üstün olan)
  hRatEl.className = 'mp-stat-h' + (homeRating > awayRating ? ' mp-better' : (homeRating === awayRating ? ' mp-tied' : ''));
  aRatEl.className = 'mp-stat-a' + (awayRating > homeRating ? ' mp-better' : (homeRating === awayRating ? ' mp-tied' : ''));

  // Rating bar
  const totalR = homeRating + awayRating;
  const hPct = (homeRating / totalR) * 100;
  const aPct = (awayRating / totalR) * 100;
  setTimeout(() => {
    document.getElementById('mpHomeBarRating').style.width = hPct + '%';
    document.getElementById('mpAwayBarRating').style.width = aPct + '%';
  }, 100);

  // Takım değeri
  const hVal = calculateTeamValue(home);
  const aVal = calculateTeamValue(away);
  const hValEl = document.getElementById('mpHomeValue');
  const aValEl = document.getElementById('mpAwayValue');
  hValEl.textContent = fmtEUR(hVal);
  aValEl.textContent = fmtEUR(aVal);
  hValEl.className = 'mp-stat-h' + (hVal > aVal ? ' mp-better' : (hVal === aVal ? ' mp-tied' : ''));
  aValEl.className = 'mp-stat-a' + (aVal > hVal ? ' mp-better' : (hVal === aVal ? ' mp-tied' : ''));

  // Gelişim
  const hDev = getTeamDevPercent(home);
  const aDev = getTeamDevPercent(away);
  const hDevEl = document.getElementById('mpHomeDev');
  const aDevEl = document.getElementById('mpAwayDev');
  hDevEl.textContent = (hDev !== null ? '%' + hDev : '—');
  aDevEl.textContent = (aDev !== null ? '%' + aDev : '—');
  hDevEl.className = 'mp-stat-h' + ((hDev !== null && aDev !== null) ? (hDev > aDev ? ' mp-better' : (hDev === aDev ? ' mp-tied' : '')) : '');
  aDevEl.className = 'mp-stat-a' + ((hDev !== null && aDev !== null) ? (aDev > hDev ? ' mp-better' : (hDev === aDev ? ' mp-tied' : '')) : '');

  // Son 5 Maç
  const homeForm = getTeamLast5Matches(home);
  const awayForm = getTeamLast5Matches(away);
  const homeFormEl = document.getElementById('mpHomeForm');
  const awayFormEl = document.getElementById('mpAwayForm');
  // ? karakteri CSS class olamaz → Q'ya çevir
  const _formCell = r => {
    const cls = r === '?' ? 'Q' : r;
    return `<div class="mp-form-cell ${cls}">${r}</div>`;
  };
  homeFormEl.innerHTML = homeForm.map(_formCell).join('');
  awayFormEl.innerHTML = awayForm.map(_formCell).join('');


  // 🆕 Otomatik başlatma: kickoff zamanı geldiğinde startMatch() çağır
  // Mevcut zamanlayıcıyı temizle (önceki maç kalıntısı)
  if (window._mpAutoStartTimer) {
    clearInterval(window._mpAutoStartTimer);
    window._mpAutoStartTimer = null;
  }

  const kickoffMs = (kickoff instanceof Date) ? kickoff.getTime() : new Date(kickoff).getTime();
  const autoText = document.getElementById('mpAutoStartText');

  const updateAutoStart = () => {
    if (!autoText) return false;
    const ms = document.getElementById('match-screen');
    // Maç ekranı kapatılmışsa veya preview-mode kalktıysa zamanlayıcıyı durdur
    if (!ms || !ms.classList.contains('open') || !ms.classList.contains('preview-mode')) {
      return false;
    }

    const now = Date.now();
    const diff = kickoffMs - now;

    if (diff <= 0) {
      // Maç saati geldi → otomatik başlat
      autoText.textContent = 'Maç başlıyor...';
      if (typeof startMatch === 'function') {
        setTimeout(() => startMatch(), 400);
      }
      return false; // zamanlayıcıyı durdur
    }

    // Geri sayım metni
    const totalSec = Math.floor(diff / 1000);
    const days = Math.floor(totalSec / 86400);
    const hours = Math.floor((totalSec % 86400) / 3600);
    const mins = Math.floor((totalSec % 3600) / 60);
    const secs = totalSec % 60;

    let countdownText;
    if (days > 0) countdownText = `${days} gün ${hours} sa sonra`;
    else if (hours > 0) countdownText = `${hours} sa ${mins} dk sonra`;
    else if (mins > 0) countdownText = `${mins} dk ${String(secs).padStart(2,'0')} sn sonra`;
    else countdownText = `${secs} saniye sonra`;

    autoText.textContent = `Maç ${countdownText} otomatik başlayacak`;
    return true;
  };

  // İlk render
  updateAutoStart();

  // Saniye bazlı güncelleme
  window._mpAutoStartTimer = setInterval(() => {
    if (!updateAutoStart()) {
      clearInterval(window._mpAutoStartTimer);
      window._mpAutoStartTimer = null;
    }
  }, 1000);

  // 🆕 STAMINA UYARISI — kullanıcının takımındaki yorgun oyuncular
  try {
    const isUserHome = !!(typeof _userTeam !== 'undefined' && _userTeam && home && home.name === _userTeam.teamName);
    const isUserAway = !!(typeof _userTeam !== 'undefined' && _userTeam && away && away.name === _userTeam.teamName);
    if ((isUserHome || isUserAway) && typeof getStaminaWarnings === 'function') {
      const warnings = getStaminaWarnings();
      // Mevcut banner'ı temizle
      const existing = document.getElementById('mpStaminaWarn');
      if (existing) existing.remove();
      if (warnings.length > 0) {
        const previewWrap = document.querySelector('.match-preview') || document.querySelector('#match-screen .preview-mode-content');
        const insertHost = previewWrap || document.getElementById('match-screen');
        if (insertHost) {
          const banner = document.createElement('div');
          banner.id = 'mpStaminaWarn';
          banner.className = 'squad-warn-banner';
          const critCount = warnings.filter(w => w.critical).length;
          const warnCount = warnings.length - critCount;
          let msg = '';
          if (critCount > 0) msg += `<b>${critCount} oyuncu</b> bitkin (kondisyon %40 altı) `;
          if (warnCount > 0) msg += (msg ? `· ` : '') + `${warnCount} oyuncu yorgun`;
          banner.innerHTML = `
            <span class="squad-warn-icon">⚠️</span>
            <div>${msg}. Diziliş'ten yedek oyuncularla rotasyon yapmanı öneririz.</div>
          `;
          // Preview header'ından sonra ekle
          const preview = document.querySelector('.match-preview-content') || insertHost.firstElementChild;
          if (preview && preview.parentNode) {
            preview.parentNode.insertBefore(banner, preview.nextSibling);
          } else {
            insertHost.insertBefore(banner, insertHost.firstChild);
          }
        }
      }
    }
  } catch (e) { console.warn('Stamina banner hatası:', e); }

  // 🆕 FAZ 3 — HAVA + ATMOSFER + DERBİ BADGE'LERİ (pre-match)
  try {
    const seed = (home.name || '') + '|' + (away.name || '') + '|' + (typeof getSeasonInfo === 'function' ? getSeasonInfo().dayInSeason : '');
    const ctx = (typeof buildMatchContext === 'function')
      ? buildMatchContext(home, away, league, seed)
      : null;
    const existing = document.getElementById('mpFaz3Bar');
    if (existing) existing.remove();
    // 🆕 TEK KAYNAK: hava / stadyum / seyirci bilgisi skorbord şeridinde (.mh-info) gösteriliyor.
    //   Bu bar maç ekranına da basılınca ÇİFT hava + ÇİFT seyirci + ÇİFT stadyum görünüyordu.
    //   Context'i sakla, barı yalnızca gerçek bir .match-preview host'u varsa çiz.
    if (ctx) { try { if (typeof MS !== 'undefined' && MS) MS._matchCtx = ctx; } catch(e) {} }
    if (ctx && document.querySelector('.match-preview')) {
      const insertHost = document.querySelector('.match-preview');
      if (insertHost) {
        const bar = document.createElement('div');
        bar.id = 'mpFaz3Bar';
        bar.className = 'mp-faz3-bar';
        const w = ctx.weather;
        const a = ctx.atmosphere;
        const isDerby = ctx.isDerby;
        const homeCC = home.countryCode || home.cc || 'TR';
        const awayCC = away.countryCode || away.cc || 'TR';
        let homeCoach = null, awayCoach = null;
        if (typeof getCoachProfile === 'function' && typeof fedGetPresident === 'function') {
          const hp = fedGetPresident(homeCC);
          const ap = fedGetPresident(awayCC);
          if (hp) homeCoach = getCoachProfile(hp.id, !!hp.isUser);
          if (ap) awayCoach = getCoachProfile(ap.id, !!ap.isUser);
        }
        bar.innerHTML = `
          <div class="mp-f3-weather">
            <span class="mp-f3-w-ic">${(w.label || '').split(' ')[0] || '☀️'}</span>
            <span class="mp-f3-w-lbl">${(w.label || '').split(' ').slice(1).join(' ') || w.code}</span>
          </div>
          ${isDerby ? `<span class="mp-f3-derby-pill">🔥 DERBİ</span>` : ''}
          <div class="mp-f3-stadium">
            <div class="mp-f3-stad-name" title="${venue || ''}">📍 ${venue || (home.name || '') + ' Stadyumu'}</div>
            <div class="mp-f3-stad-att">👥 ${a.attendance.toLocaleString('tr-TR')} · ${Math.round(a.fillRate*100)}%</div>
          </div>
        `;
        const stamBanner = document.getElementById('mpStaminaWarn');
        if (stamBanner && stamBanner.parentNode) {
          stamBanner.parentNode.insertBefore(bar, stamBanner.nextSibling);
        } else {
          const preview = document.querySelector('.match-preview-content') || insertHost.firstElementChild;
          if (preview && preview.parentNode) {
            preview.parentNode.insertBefore(bar, preview.nextSibling);
          } else {
            insertHost.insertBefore(bar, insertHost.firstChild);
          }
        }
      }
    }
  } catch (e) { console.warn('Faz 3 bar hatası:', e); }
}

// Top Eleven tarzı kickoff animasyonu — 2.5 saniye, sonra callback
function showKickoffAnimation(homeName, awayName, callback) {
  const ov = document.getElementById('kickoff-overlay');
  if (!ov) { if (callback) callback(); return; }

  document.getElementById('koHome').textContent = homeName;
  document.getElementById('koAway').textContent = awayName;
  // 🆕 Takım logoları storage'den
  if (typeof applyCrestToEl === 'function') {
    const _hLogo = document.getElementById('koHomeLogo');
    const _aLogo = document.getElementById('koAwayLogo');
    if (_hLogo) applyCrestToEl(_hLogo, homeName, (homeName || '').slice(0,3).toUpperCase());
    if (_aLogo) applyCrestToEl(_aLogo, awayName, (awayName || '').slice(0,3).toUpperCase());
  }

  ov.classList.remove('fade-out');
  ov.classList.add('active');

  setTimeout(() => {
    ov.classList.add('fade-out');
    setTimeout(() => {
      ov.classList.remove('active', 'fade-out');
      if (callback) callback();
    }, 500);
  }, 2200);
}

function openMatchScreenV2(opts) {
  const { home, away, league, venue, hClass, aClass } = opts;

  // 🆕 Canlı başlangıç dakikasını koru (window'dan)
  const _preservedLiveStart = (typeof window._pendingLiveStartMin === 'number')
    ? window._pendingLiveStartMin : null;

  // Reset state
  MS = { running:false, minute:0, scoreH:0, scoreA:0, speed:1, script:null, finished:false };
  // 574 — gol sesini maç ekranı açılırken hazırla (ilk golde çözme gecikmesi olmasın)
  try {
    if (typeof _resGoalAudio !== 'undefined' && !_resGoalAudio && typeof _GOAL_SND_URI === 'string') {
      _resGoalAudio = new Audio(_GOAL_SND_URI); _resGoalAudio.preload = 'auto'; _resGoalAudio.volume = 0.9;
      try { _resGoalAudio.load(); } catch(e) {}
    }
  } catch(e) {}
  // 573 — milli maç: yönetilen taraf (T.D. / yardımcı) açılışta bilinsin — kontroller buna bakar
  if (opts.national) {
    MS._isNational = true;
    if (opts.ntTaraf === 'home' || opts.ntTaraf === 'away') MS._ntTaraf = opts.ntTaraf;
  }

  // 🆕 İZLEYİCİ MODU — opts.spectator true ise:
  //   • Maç ekranı kontrolleri pasif (initTacticControls bunu okur)
  //   • Match_key ile sunucu lineup'ı kullanılır (uydurma kadro yok)
  //   • Skipreview otomatik (maç çoktan başlamış)
  if (opts.spectator) {
    MS._spectatorMode = true;
    MS.match_key = opts.matchKey || null;
  }
  if (opts.matchKey) {
    MS.match_key = opts.matchKey;
  }

  // 🆕 SERVER-TIME: Maç kickoff zamanı (Date veya ms olarak gelebilir)
  // Hedef: maç saat geldiğinde başlar, elle başlatılamaz, bitmişse izlenemez,
  //        izlemeden çıkıp dönünce kalan dakikadan devam eder.
  if (opts.kickoff) {
    MS.kickoffMs = (opts.kickoff instanceof Date)
      ? opts.kickoff.getTime()
      : Number(opts.kickoff);
  } else {
    MS.kickoffMs = Date.now();  // fallback: şimdi başla (test maçı vs)
  }

  // Canlı başlangıcı geri yükle (varsa)
  if (_preservedLiveStart !== null) {
    MS._liveStartMinute = _preservedLiveStart;
    delete window._pendingLiveStartMin;
  }

  // 🆕 Squad üret — izleyici modunda SUNUCU lineup'ı kullan (uydurma yok)
  // 🆕 529 — milli maçta da (izleyici olmasa bile) sunucu kadrosu kullanılır
  if ((opts.spectator || opts.national) && home._serverLineup && away._serverLineup) {
    curHome = _buildSquadFromServerLineup(home, home._serverLineup, true);
    curAway = _buildSquadFromServerLineup(away, away._serverLineup, false);
  } else {
    const matchSeed = `${home.name}-${away.name}-${league}`;
    curHome = generateMatchSquad(home, true,  matchSeed + '-H');
    curAway = generateMatchSquad(away, false, matchSeed + '-A');
  }

  // Update scoreboard UI
  document.getElementById('homeNameSb').textContent = curHome.name;
  document.getElementById('awayNameSb').textContent = curAway.name;
  document.getElementById('scoreH').textContent = '0';
  document.getElementById('scoreA').textContent = '0';
  // 🆕 MİLLİ MAÇ → skorbordda kulüp arması yerine ÜLKE BAYRAĞI
  //    (rakipler ülke olduğu için arma aranması boşuna, kısaltma kalıyordu)
  const _msMilli = /EURO|Milli|National/i.test(String(league || ''))
                || (typeof MS !== 'undefined' && MS && MS._isNational === true);
  const _msBayrakBas = (el, ad, kisa) => {
    if (!el) return false;
    if (!_msMilli || typeof _hmUlkeBayrak !== 'function') return false;
    const bay = _hmUlkeBayrak(ad);
    if (!bay) return false;
    el.classList.remove('crest-has-logo');
    el.classList.add('crest-flag');
    el.innerHTML = '';
    el.textContent = bay;
    el.style.backgroundImage = '';
    return true;
  };
  {
    const _hc = document.getElementById('homeCrest');
    const _ac = document.getElementById('awayCrest');
    const _hb = _msBayrakBas(_hc, curHome.name, curHome.short);
    const _ab = _msBayrakBas(_ac, curAway.name, curAway.short);
    if (!_hb || !_ab) {
      // 🆕 Logo varsa storage'den çek, yoksa renkli short text fallback
      if (typeof applyCrestToEl === 'function') {
        if (!_hb) applyCrestToEl(_hc, curHome.name, curHome.short);
        if (!_ab) applyCrestToEl(_ac, curAway.name, curAway.short);
      } else {
        if (!_hb && _hc) { _hc.textContent = curHome.short; _hc.className = 'team-crest ' + (hClass || 'c1'); }
        if (!_ab && _ac) { _ac.textContent = curAway.short; _ac.className = 'team-crest ' + (aClass || 'c2'); }
      }
    }
  }
  // Lig adının başında "Ülke - " prefix'i varsa temizle (örn: "Türkiye - Türkiye 5. Lig" → "Türkiye 5. Lig")
  // 🆕 İlgili ülkenin bayrağını başa ekle (hangi ülkenin ligi olduğu belli olsun)
  {
    const _cleanLeague = league.replace(/^[^-·]+?\s*-\s*/, '');
    let _lgFlag = '';
    try {
      // Uluslararası turnuvalarda ülke bayrağı YANLIŞ olur — sadece ulusal liglerde bayrak koy.
      const _isIntl = /Şampiyonlar|Elit Ligi|Konferans|EURO|Avrupa|Champion|Elite|Conv/i.test(_cleanLeague);
      if (!_isIntl) {
        const _cc = (home && (home.countryCode || home.cc)) || (away && (away.countryCode || away.cc)) || null;
        if (_cc && typeof _cftGetCountry === 'function') {
          const _c = _cftGetCountry(_cc);
          if (_c && _c.flag) _lgFlag = _c.flag + ' ';
        }
      }
    } catch(e) {}
    document.getElementById('msLeagueRow').textContent = _lgFlag + _cleanLeague;
  }
  document.getElementById('msTitleText').textContent = `${curHome.name} - ${curAway.name}`;
  try { _gmAcilis(); } catch(e) {}   // 574 — gece mavisi: takım renkleri + sıfırlama
  // 🆕 msLeagueBadge kaldırıldı (yerine X kapatma butonu kondu) — null check
  const _lgBadge = document.getElementById('msLeagueBadge');
  if (_lgBadge) _lgBadge.textContent = league.split('·')[0].trim();
  document.getElementById('msVenueTxt').textContent = `📍 ${venue}`;
  // 🆕 Üst şerit: hava durumu + seyirci sayısı
  try { _msFillTopInfo(curHome, curAway, league); } catch(e) {}

  // Reset clock & status
  document.getElementById('matchClock').textContent = 'PRE';
  document.getElementById('matchClock').className = 'match-clock';
  document.getElementById('statusBadge').className = 'status-badge sb-pre';
  document.getElementById('statusBadge').innerHTML = '⏳ Başlamadı';
  document.getElementById('possH').textContent = '50';
  document.getElementById('possA').textContent = '50';
  document.getElementById('possBarH').style.width = '50%';
  document.getElementById('possBarA').style.width = '50%';

  // Reset events
  document.getElementById('evList').innerHTML = '<div style="padding:40px 16px;text-align:center;color:var(--text3);font-size:13px">Maç henüz başlamadı…</div>';

  // Reset controls (btnSkip/btnSpeed kaldırıldı; defensive null check)
  const _btnStart = document.getElementById('btnStart'); if(_btnStart) _btnStart.disabled = false;
  const _btnSkip  = document.getElementById('btnSkip');  if(_btnSkip)  _btnSkip.disabled  = true;
  const _btnSpeed = document.getElementById('btnSpeed'); if(_btnSpeed){ _btnSpeed.textContent = '⏩ Hızlı'; _btnSpeed.style.color = ''; }

  // Update lineup labels
  document.getElementById('luHome').innerHTML = '';
  document.getElementById('luAway').innerHTML = '';

  initPitch();
  renderLineup();
  initStats();
  showEngTab('events', document.querySelectorAll('.eng-tab')[0]);

  // PRE-MATCH PREVIEW EKRANINI HAZIRLA
  // (geçmiş maç değilse, henüz oynanmamış maç için preview göster)
  const ms = document.getElementById('match-screen');
  ms.classList.add('open');
  
  // Geçmiş maç override (openMatchFromFixture içinde m.isPast geliyorsa)
  // bu fonksiyon dışında handle ediliyor. Burada default: preview-mode aktif.
  if (!opts.skipPreview) {
    fillPreMatchPreview(curHome, curAway, league, venue, opts.kickoff || new Date());
    ms.classList.add('preview-mode');
  } else {
    ms.classList.remove('preview-mode');
  }
  
  // 🆕 Kickoff zamanı geçtiyse: cache'te satır var mı yok mu bakma, direkt startMatch çağır.
  // startMatch içinde 3 saniyede bir match_state poll'ü var — Edge Function tick attığında
  // satır oluşur/günceller, poll yakalar ve ekrana yansıtır.
  // Önceki tasarım liveRow bulamazsa hiç tetiklemiyordu → kısırdöngü.
  try {
    const _now = Date.now();
    const _kickoffMs = (opts.kickoff && typeof opts.kickoff === 'object' && opts.kickoff.getTime)
      ? opts.kickoff.getTime()
      : (typeof opts.kickoff === 'number' ? opts.kickoff : 0);
    if (_kickoffMs && _now >= _kickoffMs) {
      MS.kickoffMs = _kickoffMs;
      // Preview kapat → izleme moduna geç
      ms.classList.remove('preview-mode');
      // Status badge: SİMÜLE EDİLİYOR (Edge Function tick'ini bekliyoruz)
      const sb = document.getElementById('statusBadge');
      if (sb) {
        sb.className = 'status-badge sb-live';
        sb.innerHTML = '🔴 CANLI';
      }
      // startMatch poll'u başlat — match_state oluşur oluşmaz dakika/skor güncellenir
      if (typeof startMatch === 'function') startMatch();
    }
  } catch(e) { console.warn('[openMatchScreenV2] live auto-start hata:', e); }

  // 🆕 SUNUCU DOĞRULAMASI — kickoff bilgisi hiç gelmediyse veya yanlışsa ekran
  //   PRE'de kalıyordu (maç sunucuda oynanırken!). Artık açılışta match_state'e
  //   bakıyoruz: satır 'running' ise önizlemeyi kapatıp canlı moda geçiyoruz.
  (async () => {
    try {
      if (!window.sb || !curHome || !curAway) return;
      const msEl0 = document.getElementById('match-screen');
      if (!msEl0 || !msEl0.classList.contains('open')) return;
      const { data: _rows } = await window.sb.from('match_state')
        .select('match_key,status,sim_minute,home_score,away_score,started_at,kickoff_at')
        .eq('home_team', curHome.name)
        .eq('away_team', curAway.name)
        .order('kickoff_at', { ascending: false })
        .limit(6);
      if (!_rows || !_rows.length) return;
      const _row = _rows.find(r => r.status === 'running')
                || _rows.find(r => r.status === 'scheduled')
                || _rows[0];
      if (!_row) return;
      if (!MS.match_key) MS.match_key = _row.match_key;
      try { if (typeof _msStartViewerBeat === 'function') _msStartViewerBeat(_row.match_key); } catch(e) {}
      // Kickoff'u sunucudan al — yerel saat yanlışsa startMatch "henüz başlamadı" diyordu
      const _ko = _row.started_at ? new Date(_row.started_at).getTime()
                : (_row.kickoff_at ? new Date(_row.kickoff_at).getTime() : 0);
      if (_row.status === 'running') {
        const msEl = document.getElementById('match-screen');
        if (!msEl || !msEl.classList.contains('open')) return;
        MS.kickoffMs = _ko || (Date.now() - 1000);
        msEl.classList.remove('preview-mode');
        const _sb2 = document.getElementById('statusBadge');
        if (_sb2) { _sb2.className = 'status-badge sb-live'; _sb2.innerHTML = '🔴 CANLI'; }
        // Skoru/dakikayı beklemeden bas — poll 7sn sonra tazeleyecek
        try {
          const _sh = document.getElementById('scoreH'), _sa = document.getElementById('scoreA');
          if (_sh) _sh.textContent = _row.home_score ?? 0;
          if (_sa) _sa.textContent = _row.away_score ?? 0;
          const _ck = document.getElementById('matchClock');
          if (_ck && (_row.sim_minute || 0) > 0) _ck.textContent = (_row.sim_minute || 0) + "'";
        } catch(e) {}
        if (!MS.running && !MS.finished && typeof startMatch === 'function') startMatch();
        console.log('[match-screen] sunucuda CANLI bulundu → önizleme kapatıldı:', _row.match_key);
      } else if (_ko && Date.now() >= _ko && _row.status === 'scheduled') {
        // Saati gelmiş ama sunucu henüz tick atmamış: yine de izleme moduna geç
        MS.kickoffMs = _ko;
        const msEl = document.getElementById('match-screen');
        if (msEl) msEl.classList.remove('preview-mode');
        if (!MS.running && !MS.finished && typeof startMatch === 'function') startMatch();
      }
    } catch(e) { console.warn('[openMatchScreenV2] sunucu canlı kontrolü hata:', e); }
  })();

  // 🆕 İZLEYİCİ BEAT — match-screen açıldıktan sonra her 15sn beat at.
  //   Edge action=viewer_beat → match_viewers tablosu + viewer_count günceller.
  //   Response içinde 'viewers' (kullanıcı listesi) gelir — modal için cache'lenir.
  try {
    const _beatMatchKey = (opts && opts.matchKey) || (MS && MS.match_key) || null;
    // match_key açılışta bilinmiyorsa (ana sayfadan "maça git") beat başlatılamaz;
    // poll match_key'i çözünce _msStartViewerBeat tekrar çağrılır.
    _msStartViewerBeat(_beatMatchKey);
  } catch(e) { console.warn('[openMatchScreenV2] viewer beat hata:', e); }
}

// 🆕 İZLEYİCİ SAYACI — match_key ne zaman bilinirse o zaman başlar.
//   Eskiden yalnızca openMatchScreen'e matchKey verildiğinde çalışıyordu; ana
//   sayfadan girişte anahtar sonradan çözüldüğü için sayaç hiç görünmüyordu.
function _msStartViewerBeat(mk) {
  const badgeEl = document.getElementById('msViewerBadge');
  if (!mk || !window.authUser || !window.authUser.id ||
      typeof SUPABASE_URL === 'undefined' || typeof SUPABASE_KEY === 'undefined') {
    if (badgeEl && !window._viewerBeatTimer) badgeEl.classList.remove('is-visible');
    return;
  }
  // Aynı maç için zaten çalışıyorsa dokunma
  if (window._viewerBeatTimer && window._viewerBeatMatchKey === mk) return;
  if (window._viewerBeatTimer) { clearInterval(window._viewerBeatTimer); window._viewerBeatTimer = null; }
  window._viewerBeatMatchKey = mk;
  try { if (typeof window.rtWatchMatch === 'function') window.rtWatchMatch(mk); } catch(e) {}
  if (badgeEl) {
    badgeEl.classList.add('is-visible');
    badgeEl.style.cursor = 'pointer';
    badgeEl.onclick = () => { if (typeof showViewersModal === 'function') showViewersModal(); };
  }
  // 🆕 561 — 15 sn → 30 sn; maç bitince atılmaz; izleyici listesi (3 ek sorgu)
  //   yalnız liste penceresi açıkken istenir.
  const doBeat = (listeZorla) => {
    if (document.hidden || (authUser && authUser.gizli)) return;   // 629 — gizli hesap izleyici listesinde görünmez
    const key = window._viewerBeatMatchKey;
    if (!key) return;
    if (typeof MS !== 'undefined' && MS && MS.finished && !listeZorla) return;
    const _liste = (listeZorla === true || !!document.getElementById('viewersModal')) ? '&liste=1' : '';
    // 688 — TARAFTAR: seçilen taraf (kendi kulübü / milli takımı sunucuda otomatik)
    const _tr = (typeof window._izTarafOku === 'function') ? window._izTarafOku(key) : null;
    const _trQ = _tr ? '&taraf=' + _tr : '';
    // 🔒 565 — kimlik oturumdan (sunucu adresteki user_id'ye artık bakmıyor)
    _oturumJwt().then(_jwt => _jwt ? fetch(`${SUPABASE_URL}/functions/v1/tick-matches?action=viewer_beat&match_key=${encodeURIComponent(key)}&user_id=${encodeURIComponent(window.authUser.id)}${_liste}${_trQ}`, {
      headers: { 'Authorization': 'Bearer ' + _jwt, 'apikey': SUPABASE_KEY }
    }) : null).then(r => (r && r.ok) ? r.json() : null)
      .then(d => {
        if (d && typeof d.viewer_count === 'number') {
          const el = document.getElementById('msViewerCount');
          if (el) el.textContent = d.viewer_count;
        }
        // 688 — sunucunun belirlediği taraf + taraftar sayıları
        if (d && (d.taraf === 'home' || d.taraf === 'away') && typeof window._izTarafYaz === 'function') window._izTarafYaz(key, d.taraf);
        if (d && d.taraftar && typeof d.taraftar === 'object') window._taraftarCache = { mk: key, h: Number(d.taraftar.h) || 0, a: Number(d.taraftar.a) || 0 };
        if (d && Array.isArray(d.viewers)) {
          window._viewersListCache = d.viewers;
          window._viewersListKey = key;
          if (document.getElementById('viewersModal') && typeof _renderViewersModalList === 'function') {
            _renderViewersModalList();
          }
        }
      }).catch(() => {});
  };
  window._viewerBeatNow = doBeat;
  doBeat();
  window._viewerBeatTimer = setInterval(doBeat, 30000);
}
window._msStartViewerBeat = _msStartViewerBeat;



