// ── Helper: Hangi takım kullanıcının? (test modu desteği ile) ──
// (511) Sunucunun yaptığı değişikliği (sakatlık/bot/diğer cihazdan) ekrandaki kadroya
//   uygula: çıkan oyuncunun yerine giren oyuncu aynı slotta görünür (kendi takımında
//   değişiklik ekranı da yeniden çizilir).
function _msSunucuSubUygula(ev) {
  if (!ev || ev.type !== 'sub' || !ev.player || !ev.playerOut) return;
  const team = ev.team === 'home' ? curHome : (ev.team === 'away' ? curAway : null);
  if (!team || !Array.isArray(team.players)) return;
  const idx = team.players.findIndex(p => p && p.name === ev.playerOut);
  if (idx === -1) return;                                   // zaten uygulanmış
  const cikan = team.players[idx];
  const yedekler = Array.isArray(team.benchPlayers) ? team.benchPlayers : [];
  let giren = yedekler.find(b => b && b.name === ev.player);
  if (!giren) {
    try {
      const lr = (typeof _liveMatchCache === 'object' && _liveMatchCache && MS.match_key) ? _liveMatchCache[MS.match_key] : null;
      const lu = lr && (ev.team === 'home' ? lr.home_lineup : lr.away_lineup);
      giren = lu && Array.isArray(lu.bench) ? lu.bench.find(b => b && b.name === ev.player) : null;
    } catch(e) {}
  }
  if (!giren) giren = { name: ev.player, num: ev.inNum, pos: cikan.pos, rating: cikan.rating };
  const { myTeam } = _whichSideIsUser();
  if (myTeam && myTeam === team) {
    _msubSyncStateAfterSwap(idx, giren);
  } else {
    team.players[idx] = { ...giren, pos: cikan.pos, x: cikan.x, y: cikan.y, _slotIdx: cikan._slotIdx, slotIdx: cikan.slotIdx, slotPos: cikan.slotPos };
  }
  if (!MS.subsHistory) MS.subsHistory = [];
  const kayit = MS.subsHistory.find(s => s && s.in === ev.player && s.out === ev.playerOut);
  if (kayit && !kayit.outSnapshot) {
    kayit.outSnapshot = { ...cikan, team: ev.team, _exitMin: ev.min,
      injuredOut: ev.reason === 'injury' };
  }
}

function _whichSideIsUser() {
  // 573 — milli maçta yönetilen taraf
  try {
    if (typeof MS !== 'undefined' && MS && MS._isNational && (MS._ntTaraf === 'home' || MS._ntTaraf === 'away')) {
      const h = MS._ntTaraf === 'home';
      return { userInHome: h, userInAway: !h, myTeam: h ? curHome : curAway };
    }
  } catch(e) {}
  let userInHome = !!(curHome && (curHome.players||[]).some(p => p.isUser))
                || !!(typeof _userTeam !== 'undefined' && _userTeam && curHome && curHome.name === _userTeam.teamName);
  let userInAway = !!(curAway && (curAway.players||[]).some(p => p.isUser))
                || !!(typeof _userTeam !== 'undefined' && _userTeam && curAway && curAway.name === _userTeam.teamName);
  // 🎯 Test modu: forceCaptain açıksa ev sahibi takımı kullanıcı takımı varsay
  if (!userInHome && !userInAway && MS && MS._testForceCaptain) userInHome = true;
  return { userInHome, userInAway, myTeam: userInHome ? curHome : (userInAway ? curAway : null) };
}

// ── Saha + yedekler (625: maçın kadrosundan) — maç başında ve her değişiklikten sonra ──
function buildSubstitutesList() {
  renderMatchSubPitch();
  renderMatchSubBench();
}


// ══════════════════════════════════════════════════════════════════

// ══════════════════════════════════════════════════════════
// 🆕 CANLI MAÇ TUTARLILIK YARDIMCILARI
// ══════════════════════════════════════════════════════════
// 1) Değişiklik hakkı SUNUCUDAKİ olaylardan türetilir (istemci sayacı ayrışmasın).
//    Sakatlık kaynaklı otomatik değişiklikler de hakkı tüketir (motorla aynı kural).
function _msSyncSubsFromServer() {
  try {
    if (typeof MS === 'undefined' || !MS) return;
    const evs = (MS.script && Array.isArray(MS.script.evs)) ? MS.script.evs
              : (Array.isArray(MS.events) ? MS.events : []);
    if (!evs.length) return;
    const ut = (typeof _userTeam !== 'undefined' && _userTeam) ? _userTeam.teamName : null;
    let mySide = (MS._isNational && (MS._ntTaraf === 'home' || MS._ntTaraf === 'away')) ? MS._ntTaraf : null;
    if (!mySide && ut && typeof curHome !== 'undefined' && curHome && curHome.name === ut) mySide = 'home';
    else if (!mySide && ut && typeof curAway !== 'undefined' && curAway && curAway.name === ut) mySide = 'away';
    if (!mySide) return;
    let used = 0, auto = 0;
    const sunucuSub = new Set();
    evs.forEach(e => {
      if (!e || e.type !== 'sub' || e.team !== mySide) return;
      used++; if (e.isAuto) auto++;
      sunucuSub.add((e.player || '') + '|' + (e.playerOut || ''));
    });
    // (511) Sunucuya iletilmiş ama motorun henüz uygulamadığı değişiklikler de hak düşürür
    if (Array.isArray(MS.subsHistory)) MS.subsHistory.forEach(s => {
      if (!s || !s._pending) return;
      if (sunucuSub.has((s.in || '') + '|' + (s.out || ''))) { s._pending = false; return; }
      used++;
    });
    const left = Math.max(0, 5 - used);
    if (MS.subsLeft !== left) {
      MS.subsLeft = left;
      const el = document.getElementById('tacSubsLeft');
      if (el) el.textContent = left;
      try { if (typeof _gmModBant === 'function') _gmModBant(); } catch(e) {}
      if (auto > 0) {
        const info = document.getElementById('tacSubsAutoInfo');
        if (info) info.textContent = auto + ' hak sakatlık değişikliğine gitti';
      }
    }
  } catch(e) {}
}

// 2) Görünen dakika SUNUCUYU AŞMASIN (tick gecikirse ekran ileri gidiyordu)
function _msClampDisplayMinute(serverMin) {
  try {
    if (typeof MS === 'undefined' || !MS) return;
    const sm = Number(serverMin);
    if (!isFinite(sm) || sm <= 0) return;
    if (typeof MS._displayMin === 'number' && MS._displayMin > sm) MS._displayMin = sm;
  } catch(e) {}
}

// 3) Uzatma göstergesi — olaylarda extraTime varsa veya 90+ dakika
function _msExtraTimeBadge(evs, minute) {
  try {
    const has = Array.isArray(evs) && evs.some(e => e && (e.extraTime || e.type === 'extraTimeStart'));
    return (has || (Number(minute) || 0) > 90) ? '<span class="ms-et-badge">UZT</span>' : '';
  } catch(e) { return ''; }
}

// 🆕 CANLI DİZİLİŞ GÖRÜNÜMÜ — maç ekranı taktik sekmesi
//   Eskiden takım sayfasının sahası klonlanıyordu: izleyicide KENDİ takımın
//   görünüyor, kırmızı kart / sakatlık / oyuncu değişimi yansımıyordu.
//   Artık canlı maç verisinden (curHome/curAway) çizilir.
// ══════════════════════════════════════════════════════════════════
function _msLiveOut(p) {
  if (!p) return null;
  if (p.sentOff || p.redCard) return 'red';
  if (p.matchInjured || p.injuredOut) return 'inj';
  if (p.subbedOut) return 'sub';
  return null;
}

// Formasyona göre saha yerleşimi (11 oyuncu) — yüzde konum
function _msPitchSlots(n) {
  // GK + 10; basit 4-3-3 benzeri yerleşim, oyuncu sayısına göre esner
  const rows = [
    [[50, 90]],                                   // GK
    [[16, 72], [38, 76], [62, 76], [84, 72]],     // DEF
    [[24, 52], [50, 55], [76, 52]],               // MID
    [[22, 26], [50, 20], [78, 26]]                // FWD
  ];
  const flat = [];
  rows.forEach(r => r.forEach(xy => flat.push(xy)));
  return flat.slice(0, Math.max(1, n));
}

function _msTeamPitchHtml(team, title, opts) {
  opts = opts || {};
  const players = (team && Array.isArray(team.players)) ? team.players.slice(0, 11) : [];
  const bench = (team && Array.isArray(team.benchPlayers)) ? team.benchPlayers : [];
  const slots = _msPitchSlots(players.length || 11);
  const dots = players.map((p, i) => {
    const xy = slots[i] || [50, 50];
    const out = _msLiveOut(p);
    const cls = out === 'red' ? ' is-red' : (out === 'inj' ? ' is-inj' : (out === 'sub' ? ' is-sub' : ''));
    const mark = out === 'red' ? '<span class="mlp-mark red">🟥</span>'
               : out === 'inj' ? '<span class="mlp-mark">🚑</span>'
               : (out === 'sub' ? '<span class="mlp-mark sub">▼</span>' : '');
    const rating = (typeof p.matchRating === 'number') ? `<span class="mlp-rt">${p.matchRating.toFixed(1)}</span>` : '';
    const gl = (p.matchGoals > 0) ? '<span class="mlp-g">⚽' + (p.matchGoals > 1 ? p.matchGoals : '') + '</span>' : '';
    return `<div class="mlp-dot${cls}" style="left:${xy[0]}%;top:${xy[1]}%">
        <div class="mlp-num">${p.num != null ? p.num : ''}</div>
        <div class="mlp-nm">${(p.name || '').split(' ').slice(-1)[0]}</div>
        ${mark}${gl}${rating}
      </div>`;
  }).join('');

  const benchIn = bench.filter(b => b && b.matchRating != null).map(b => (b.name || '').split(' ').slice(-1)[0]);
  const benchTxt = bench.length
    ? `<div class="mlp-bench"><b>Yedekler:</b> ${bench.slice(0, 7).map(b => {
        const nm = (b && b.name ? b.name.split(' ').slice(-1)[0] : '—');
        const inGame = benchIn.indexOf(nm) >= 0;
        return `<span class="${inGame ? 'in' : ''}">${nm}${inGame ? ' ▲' : ''}</span>`;
      }).join('')}</div>`
    : '';

  return `<div class="mlp-wrap">
      <div class="mlp-title">${title || ''}</div>
      <div class="mlp-pitch">
        <div class="mlp-lines"></div>
        ${dots}
      </div>
      ${benchTxt}
    </div>`;
}

// ══════════════════════════════════════════════════════════════════
// 🆕 İZLEYİCİ TAKTİK GÖRÜNÜMÜ — tek saha, forma renkli futbolcu kartları
//   • Kaptan/yardımcı DIŞINDAKİ herkes (kendi takımında bile) bunu görür
//   • Salt okunur: yedek listesi yok, müdahale yok
//   • Oyuncu değişikliği / sakatlık / kırmızı kart canlı işlenir
// ══════════════════════════════════════════════════════════════════
function _mspHex2Rgb(h) {
  h = String(h || '#333').replace('#', '');
  if (h.length === 3) h = h.split('').map(c => c + c).join('');
  const n = parseInt(h.slice(0, 6), 16);
  if (!isFinite(n)) return [51, 51, 51];
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
function _mspRgba(h, a) { const c = _mspHex2Rgb(h); return `rgba(${c[0]},${c[1]},${c[2]},${a})`; }
function _mspLum(h) { const c = _mspHex2Rgb(h); return (0.299*c[0] + 0.587*c[1] + 0.114*c[2]) / 255; }

// Takım görsel kimliği: forma renkleri + logo (kulüp DB'sinden)
function _mspTeamMeta(team, fallbackName) {
  const name = (team && team.name) || fallbackName || '—';
  const meta = { name, short: (team && team.short) || name.slice(0, 3).toUpperCase(),
                 bg: '#37474f', tc: '#ffffff', logo: null };
  try {
    let cc = (team && (team.countryCode || team.countryKey)) || null;
    if (!cc && typeof _bracketCcByName === 'function') cc = _bracketCcByName(name);
    if (!cc && typeof MS !== 'undefined' && MS && MS.countryCode) cc = MS.countryCode;
    const t = (cc && typeof _cftFindTeam === 'function') ? _cftFindTeam(cc, name) : null;
    if (t) {
      meta.bg = t.bg || meta.bg;
      meta.tc = t.tc || meta.tc;
      meta.short = t.short || meta.short;
      if (typeof teamLogoUrl === 'function') { try { meta.logo = teamLogoUrl(t) || null; } catch(e) {} }
    }
  } catch(e) {}
  return meta;
}

// Oyuncuları mevki grubuna göre kendi yarı sahasına yerleştir
function _mspPlace(players, isHome) {
  const all = (players || []).filter(Boolean);

  // ═══ 1) GERÇEK DİZİLİŞ KOORDİNATLARI (sunucu lineup / FORMATIONS) ═══
  //   Oyuncular x:0-100 (sol→sağ) ve y:0-100 (kendi kalesi 88 → rakip kalesi ~17)
  //   taşır. Bunları tek sahaya haritalarız: ev sahibi alt yarı, deplasman üst yarı
  //   (deplasman ayrıca x ekseninde aynalanır — kendi kalesine doğru bakar).
  const xy = all.filter(p => typeof p.x === 'number' && typeof p.y === 'number' &&
                             p.x >= 0 && p.x <= 100 && p.y >= 0 && p.y <= 100);
  if (xy.length >= 7) {
    return xy.slice(0, 11).map(p => ({
      p,
      x: Math.round(isHome ? p.x : (100 - p.x)),
      y: Math.round(isHome ? (50 + p.y * 0.47) : (50 - p.y * 0.47)),
      posLbl: p.pos || ''
    }));
  }

  // ═══ 2) YEDEK: koordinat yoksa mevkiye göre satır ═══
  const POSGRP = (typeof POS_GROUP !== 'undefined') ? POS_GROUP : null;
  const grp = p => {
    const g = (p && (p.posGroup || (POSGRP && POSGRP[p.pos]))) || null;
    if (g === 'GK' || p.pos === 'KL' || p.pos === 'GK') return 'GK';
    if (g === 'DEF' || g === 'DF') return 'DEF';
    if (g === 'FWD' || g === 'FW') return 'FWD';
    if (g === 'MID') return 'MID';
    return 'MID';
  };
  const rows = { GK: [], DEF: [], MID: [], FWD: [] };
  all.slice(0, 11).forEach(p => { rows[grp(p)].push(p); });
  const Y = isHome ? { GK: 93, DEF: 82, MID: 70, FWD: 58 }
                   : { GK: 7,  DEF: 18, MID: 30, FWD: 42 };
  const out = [];
  ['GK','DEF','MID','FWD'].forEach(k => {
    const list = rows[k];
    const n = list.length;
    list.forEach((p, i) => {
      // kaleciler ortada toplanır (köşedeki takım etiketiyle çakışmasın)
      const x = (n <= 1) ? 50
              : (k === 'GK' ? Math.round(50 + (i - (n - 1) / 2) * 26)
                            : Math.round(12 + (76 * i / (n - 1))));
      out.push({ p, x, y: Y[k], posLbl: (p.pos || k) });
    });
  });
  return out;
}

// Maç olayları (sunucu otoritesi) — sub / injury / red
function _mspEvents() {
  try {
    if (typeof MS === 'undefined' || !MS) return [];
    const evs = (MS.script && Array.isArray(MS.script.evs)) ? MS.script.evs
              : (Array.isArray(MS.events) ? MS.events : []);
    return evs.filter(e => e && (e.type === 'sub' || e.type === 'injury' || e.type === 'red'));
  } catch(e) { return []; }
}

function _mspCard(item, meta, evs, side) {
  const p = item.p;
  const acik = _mspLum(meta.bg) > 0.62;
  const ad = (p.name || '').split(' ').slice(-1)[0] || (p.name || '');
  // Canlı durum
  const out = (typeof _msLiveOut === 'function') ? _msLiveOut(p) : null;
  let cls = out === 'red' ? ' red' : (out === 'inj' ? ' inj' : (out === 'sub' ? ' out' : ''));
  let mk = out === 'red' ? '🟥' : (out === 'inj' ? '🚑' : (out === 'sub' ? '🔻' : ''));
  // Oyuna sonradan girdi mi? (aynı taraftaki sub olaylarında 'player' = giren)
  if (!mk) {
    const girdi = evs.some(e => e.type === 'sub' && e.team === side &&
      String(e.player || '').split(' ').slice(-1)[0] === ad);
    if (girdi) { cls = ' inn'; mk = '🔺'; }
  }
  const rt = (typeof p.matchRating === 'number') ? p.matchRating : null;
  const rc = rt == null ? '' : (rt >= 7.5 ? ' hi' : (rt < 6.5 ? ' lo' : ''));
  const gl = (p.matchGoals > 0) ? '<span class="msp-gl">⚽</span>' : '';
  const body = `linear-gradient(180deg,${_mspRgba(meta.bg, acik?0.10:0.20)},${_mspRgba(meta.bg, acik?0.04:0.08)}),rgba(11,14,19,.86)`;
  const bar  = `linear-gradient(90deg,${meta.bg},${_mspRgba(meta.bg,0.55)})`;
  const noBg = acik ? meta.bg : _mspRgba(meta.bg, 0.9);
  return `<div class="msp-pc${cls}" style="left:${item.x}%;top:${item.y}%;background:${body};border-color:${_mspRgba(meta.bg,0.45)}">
      <div class="bar" style="background:${bar}"></div>
      <div class="r1"><span class="no" style="background:${noBg};color:${meta.tc};border:1px solid ${_mspRgba(meta.tc,0.25)}">${p.num != null ? p.num : ''}</span>
        <span class="nm">${ad}</span></div>
      <div class="r2"><span class="pos">${item.posLbl}</span>${rt != null ? `<span class="rt${rc}">${rt.toFixed(1)}</span>` : '<span class="rt" style="color:#4a5160">—</span>'}</div>
      ${mk ? `<span class="msp-mk">${mk}</span>` : ''}${gl}
    </div>`;
}

function _mspTag(meta, cls) {
  const acik = _mspLum(meta.bg) > 0.62;
  const logo = meta.logo
    ? `<span class="lg"><img src="${meta.logo}" alt="" loading="lazy"></span>`
    : `<span class="lg" style="background:${meta.bg};color:${meta.tc}">${meta.short}</span>`;
  return `<div class="msp-tag ${cls}" style="border:1px solid ${_mspRgba(meta.bg,0.45)}">
      ${logo}<b style="color:${acik ? meta.bg : '#e7eaf0'}">${(meta.name || '').toUpperCase()}</b></div>`;
}

function _mspChangesHtml(hMeta, aMeta) {
  const evs = _mspEvents().slice().sort((a, b) => (Number(b.min) || 0) - (Number(a.min) || 0)).slice(0, 14);
  if (!evs.length) return `<div class="msp-chg"><div class="msp-chg-h"><b>MAÇ İÇİ DEĞİŞİKLİKLER</b>
      <span class="msp-live"><s></s>CANLI</span></div>
      <div class="msp-empty">Henüz değişiklik yok</div></div>`;
  const rows = evs.map(e => {
    const m = (e.team === 'home') ? hMeta : aMeta;
    let ic, tx;
    if (e.type === 'sub') {
      ic = '<div class="msp-ic sub"><i class="up">▲</i><i class="dn">▼</i></div>';
      tx = `<span class="o">▼ ${e.playerOut || '—'}</span> &nbsp; <span class="i">▲ ${e.player || '—'}</span>
            <span>${e.isAuto ? 'Zorunlu değişiklik' : 'Taktik değişiklik'}</span>`;
    } else if (e.type === 'injury') {
      ic = '<div class="msp-ic inj">🚑</div>';
      tx = `<b>${e.player || '—'}</b><span>${e.description || 'Sakatlık'}</span>`;
    } else {
      ic = '<div class="msp-ic red">🟥</div>';
      tx = `<b>${e.player || '—'}</b><span>${e.secondYellow ? 'İkinci sarı — oyundan atıldı' : 'Kırmızı kart — oyundan atıldı'}</span>`;
    }
    return `<div class="msp-row"><span class="msp-min">${e.min != null ? e.min + "'" : ''}</span>${ic}
        <div class="msp-tx">${tx}</div>
        <span class="msp-tm" style="background:${m.bg};color:${m.tc}">${m.short}</span></div>`;
  }).join('');
  return `<div class="msp-chg"><div class="msp-chg-h"><b>MAÇ İÇİ DEĞİŞİKLİKLER</b>
      <span class="msp-live"><s></s>CANLI</span></div>${rows}</div>`;
}

// İzleyici (veya yetkisiz) görünüm: tek saha, iki takım kendi yarısında — salt-okunur
function _msRenderSpectatorLineups() {
  // 574 — Gece Mavisi: takım seçici + aktif taktik + tek takım sahası + maç içi değişiklikler
  const target = document.getElementById('msLiveLineups');
  if (!target) return false;
  try { _gmModBant(); } catch(e) {}
  try { _gmIzleyiciCiz(target); }
  catch(e) { target.innerHTML = '<div class="gm-bos">Diziliş verisi yok</div>'; }
  return true;
}

// 🆕 Kaptanın takımının forma rengini taktik ekranına CSS değişkeni olarak taşı
//    (yalnızca görünüm — hiçbir veri veya sürükle-bırak mantığı etkilenmez)
// 🆕 Skorbord/olay akışı için iki takımın forma renkleri
// 🆕 Skorbord üst şeridi: solda hava durumu, sağda seyirci sayısı
function _msFillTopInfo(home, away, league) {
  try {
    const wEl = document.getElementById('msWeatherTxt');
    const aEl = document.getElementById('msAttendTxt');
    // 🆕 TEK KAYNAK: buildMatchContext — maç önizlemesiyle BİREBİR aynı seed,
    //   aksi halde ekranda iki farklı hava / iki farklı seyirci sayısı çıkıyordu.
    let ctx = null;
    try {
      if (typeof MS !== 'undefined' && MS && MS._matchCtx) ctx = MS._matchCtx;
      if (!ctx && typeof buildMatchContext === 'function' && home && away) {
        const seed = (home.name || '') + '|' + (away.name || '') + '|'
                   + ((typeof getSeasonInfo === 'function') ? getSeasonInfo().dayInSeason : '');
        ctx = buildMatchContext(home, away, league, seed);
        if (typeof MS !== 'undefined' && MS) MS._matchCtx = ctx;
      }
    } catch(e) {}
    // Hava
    if (wEl) {
      let txt = (ctx && ctx.weather && ctx.weather.label) ? ctx.weather.label : '';
      if (!txt) {
        try {
          if (typeof pickWeatherForDate === 'function') {
            const cc = (home && (home.countryCode || home.cc)) || 'TR';
            const seed = (home && home.name || '') + '|' + (away && away.name || '') + '|'
                       + ((typeof getSeasonInfo === 'function') ? getSeasonInfo().dayInSeason : '');
            const w = pickWeatherForDate(seed, new Date(), cc);
            if (w && w.label) txt = w.label;
          }
        } catch(e) {}
      }
      wEl.textContent = txt || '🌤️ Açık';
    }
    // Seyirci
    if (aEl) {
      let n = 0;
      try {
        if (ctx && ctx.atmosphere) n = Math.round(ctx.atmosphere.attendance || 0);
        if (!n && typeof calcStadiumAtmosphere === 'function' && home) {
          const at = calcStadiumAtmosphere(home, league || '', false);
          n = Math.round((at && at.attendance) || 0);
        }
      } catch(e) {}
      aEl.textContent = n > 0 ? ('👥 ' + n.toLocaleString('tr')) : '';
    }
  } catch(e) {}
}

function _msApplyKitColors() {
  try {
    const host = document.getElementById('match-screen');
    if (!host) return;
    const pick = (t, fb) => {
      try {
        if (!t || !t.name) return fb;
        let cc = t.countryCode || t.countryKey || null;
        if (!cc && typeof _bracketCcByName === 'function') cc = _bracketCcByName(t.name);
        if (!cc && typeof MS !== 'undefined' && MS && MS.countryCode) cc = MS.countryCode;
        const x = (cc && typeof _cftFindTeam === 'function') ? _cftFindTeam(cc, t.name) : null;
        return (x && x.bg) ? x.bg : fb;
      } catch(e) { return fb; }
    };
    const H = (typeof curHome !== 'undefined') ? curHome : null;
    const A = (typeof curAway !== 'undefined') ? curAway : null;
    host.style.setProperty('--kitH', pick(H, '#c62828'));
    host.style.setProperty('--kitA', pick(A, '#1565c0'));
  } catch(e) {}
}

function _tacApplyKitColor() {
  try {
    const host = document.getElementById('eng-tactic');
    if (!host) return;
    const ut = (typeof _userTeam !== 'undefined') ? _userTeam : null;
    if (!ut || !ut.teamName) return;
    let bg = '#37474f', tc = '#ffffff';
    const t = (typeof _cftFindTeam === 'function') ? _cftFindTeam(ut.countryCode, ut.teamName) : null;
    if (t) { bg = t.bg || bg; tc = t.tc || tc; }
    host.style.setProperty('--kit', bg);
    host.style.setProperty('--kitTc', tc);
  } catch(e) {}
}

function renderMatchSubPitch() {
  const dst = document.getElementById('msubPitchPlayers');
  if (!dst) return;
  try { _tacApplyKitColor(); } catch(e) {}
  try { if (typeof _gmModBant === 'function') _gmModBant(); } catch(e) {}   // 574 — izleyici/kaptan bandı + takım rengi

  // 🆕 İzleyici / yetkisiz: kendi takımının sahasını klonlama — iki takımın CANLI dizilişi
  try {
    if (typeof _msCanControlTactics === 'function' && !_msCanControlTactics()) {
      const ok = _msRenderSpectatorLineups();
      if (ok) return;
    }
  } catch(e) {}
  // 625 — saha (kulüp ve milli maç) maçın kadrosundan çizilir; Takımım dizilişi klonlanmaz
  _msubSahaCiz(dst);
}

// 573 — Oyundan çıkan (tekrar giremeyen) oyuncular: bu cihazdan yapılan değişiklikler +
//   sunucu olayları (sakatlık değişikliği, yardımcının başka cihazdan yaptığı değişiklik).
function _msCikanlar() {
  const out = new Map();   // ad → dakika
  try {
    if (Array.isArray(MS.subsHistory)) MS.subsHistory.forEach(s => { if (s && s.out && !out.has(s.out)) out.set(s.out, s.min); });
    const taraf = _msBenimTaraf();
    const evs = (MS.script && Array.isArray(MS.script.evs)) ? MS.script.evs : (Array.isArray(MS.events) ? MS.events : []);
    evs.forEach(e => {
      if (!e || e.type !== 'sub' || !e.playerOut) return;
      if (taraf && e.team !== taraf) return;
      if (!out.has(e.playerOut)) out.set(e.playerOut, e.min);
    });
  } catch(e) {}
  return out;
}
function _msBenimTaraf() {
  try {
    if (MS && (MS._ntTaraf === 'home' || MS._ntTaraf === 'away')) return MS._ntTaraf;
    const w = _whichSideIsUser();
    return w.userInHome ? 'home' : (w.userInAway ? 'away' : null);
  } catch(e) { return null; }
}
// Görünür bilgi satırı: "Oyundan çıkanlar tekrar giremez: …"
function _msCikanlarBilgi() {
  const el = document.getElementById('tacCikanlar');
  if (!el) return;
  const c = _msCikanlar();
  if (!c.size) { el.style.display = 'none'; el.innerHTML = ''; return; }
  const bas = (typeof T === 'function') ? T('⛔ Oyundan çıkanlar tekrar giremez:') : '⛔ Oyundan çıkanlar tekrar giremez:';
  el.innerHTML = `<b>${_escapeHtml(bas)}</b>` + Array.from(c.entries())
    .map(([ad, dk]) => `<span class="tc-p" data-noi18n>${_escapeHtml(ad)}${dk != null ? ' ' + dk + "'" : ''}</span>`).join('');
  el.style.display = 'flex';
}
function _msCikanUyari(ad, dk) {
  showTacticFlash('⛔ ' + ad + (dk != null ? ' ' + dk + "'" : '') + ' oyundan çıktı — tekrar oyuna giremez');
  try { if (typeof cftTitret === 'function') cftTitret(20); } catch(e) {}
}

// 625 — MAÇ İÇİ DİZİLİŞ (kulüp + milli maç): saha ve yedekler maçın kadrosundan çizilir.
//   Kırmızı kart gören oyuncunun yeri boş kalır (soluk, kırmızı kart işaretli): sahadaki başka bir
//   oyuncu o boşluğa kaydırılabilir, yedekten oyuncu alınamaz. Sakatlananın yerine yedek alınır.
function _msKadroDurum(p, taraf) {
  if (!p || !p.name) return null;
  const evs = (MS.script && Array.isArray(MS.script.evs)) ? MS.script.evs : (Array.isArray(MS.events) ? MS.events : []);
  let kir = null, sak = null;
  evs.forEach(e => {
    if (!e || e.cancelled || e.player !== p.name || (taraf && e.team !== taraf)) return;
    if ((e.type === 'red' || e.type === 'secondyellow') && kir === null) kir = e.min;
    if (e.type === 'injury' && sak === null) sak = e.min;
  });
  if (kir !== null || p.sentOff || p.redCard) return { d: 'red', dk: kir };
  if (sak !== null || p.matchInjured || p.injuredOut) return { d: 'inj', dk: sak };
  return null;
}
function _msKendiAlt(p) {
  const s = p && (p.subPos || p.sub_pos);
  if (s && typeof SUBPOS_GROUP !== 'undefined' && SUBPOS_GROUP[s]) return s;
  return (typeof subPosOf === 'function') ? subPosOf(p) : ((p && p.pos) || '');
}
// Kulüp: "Özcan Y." (ilk ad + diğerlerinin baş harfi) · milli: ilk ad + soyadın baş harfi
function _msubKisaAd(ad, milli) {
  const s = String(ad || '');
  if (milli) { const par = s.split(/\s+/); return par.length > 1 ? par[0] + ' ' + par[par.length - 1].charAt(0) + '.' : s; }
  const par = (s.split('_')[1] || s).trim().split(/\s+/);
  return par.length > 1 ? par[0] + ' ' + par.slice(1).map(w => w.charAt(0).toUpperCase() + '.').join(' ') : par[0];
}
function _msubKart(p, yedek, milli) {
  const ovr = Math.round(Number(p.rating || p.overall) || 0);
  const ad = String(p.name || '');
  const pos = milli ? (p.pos || '') : _msKendiAlt(p);
  const pcls = (() => { try { return 'pos-' + subPosGroupOf(subPosOf(p)); } catch(e) { return ''; } })();
  if (yedek) {
    return `<div class="bench-card-top"><span class="bench-card-flag"></span><span class="bench-card-ovr">${ovr}</span></div>
      <div class="bench-card-name" data-noi18n>${_escapeHtml(milli ? ad : _msubKisaAd(ad, false))}</div>
      <div class="bench-card-bottom"><span class="bench-card-pos ${pcls}">${_escapeHtml(pos)}</span><span class="bench-card-num">#${p.num || ''}</span></div>`;
  }
  return `<div class="fpn-circle"><div class="fpn-top"><span class="fpn-flag"></span><span class="fpn-ovr">${ovr}</span></div>
    <div class="fpn-name" data-noi18n>${_escapeHtml(_msubKisaAd(ad, milli))}</div>
    <div class="fpn-bottom"><span class="fpn-pos ${pcls}">${_escapeHtml(pos)}</span><span class="fpn-num2">#${p.num || ''}</span></div></div>`;
}
// Kırmızı kart: boş yuva — soluk, kesik çerçeve, kırmızı kart + dakika, oyuncunun adı silik
function _msubBosKart(p, dk, milli) {
  return `<div class="fpn-circle"><div class="fpn-bos"><i class="fpn-kk"></i>${dk != null ? `<b>${dk}'</b>` : ''}</div>
    <div class="fpn-name" data-noi18n>${_escapeHtml(_msubKisaAd(p.name, milli))}</div></div>`;
}
function _msubSahaCiz(dst) {
  const { myTeam } = _whichSideIsUser();
  const milli = !!MS._isNational;
  const taraf = _msBenimTaraf();
  dst.innerHTML = '';
  const oy = (myTeam && Array.isArray(myTeam.players)) ? myTeam.players : [];
  if (!oy.length) { dst.innerHTML = '<div class="mlp-empty">Diziliş bulunamadı.</div>'; return; }
  // Konum: sunucu x/y (0-100, kendi kalesi altta) varsa o; yoksa mevkiye göre satır
  const xyVar = oy.filter(p => p && typeof p.x === 'number' && typeof p.y === 'number').length >= 7;
  const satir = { GK: [], DEF: [], MID: [], FWD: [] };
  const grp = (p) => {
    if (['LW','RW','LF','RF','ST','CF','FWD','SAK'].indexOf(p.pos) !== -1) return 'FWD';
    if (milli && typeof _ntGrp === 'function') return _ntGrp(p);
    return (typeof POS_GROUP !== 'undefined' && POS_GROUP[p.pos]) || 'MID';
  };
  if (!xyVar) oy.forEach((p, i) => { if (p) satir[grp(p)].push(i); });
  const yer = {};
  if (!xyVar) {
    const Y = { GK: 90, DEF: 71, MID: 48, FWD: 24 };
    Object.keys(satir).forEach(k => { const L = satir[k]; L.forEach((mi, j) => { yer[mi] = { x: L.length <= 1 ? 50 : Math.round(14 + 72 * j / (L.length - 1)), y: Y[k] }; }); });
  }
  oy.forEach((p, mi) => {
    if (!p) return;
    const node = document.createElement('div');
    node.className = 'fpn';
    node.id = 'msubFpn_' + mi;
    node.dataset.msIdx = mi;
    const x = xyVar ? Math.max(6, Math.min(94, Number(p.x))) : yer[mi].x;
    const y = xyVar ? Math.max(6, Math.min(94, Number(p.y))) : yer[mi].y;
    node.style.left = x + '%'; node.style.top = y + '%';
    const dr = _msKadroDurum(p, taraf);
    if (dr && dr.d === 'red') {
      node.classList.add('is-red');
      node.innerHTML = _msubBosKart(p, dr.dk, milli);
      node.addEventListener('click', () => { if (node._wasDragging) { node._wasDragging = false; return; }
        showTacticFlash('🟥 ' + p.name + ' oyundan atıldı — sahadan bir oyuncuyu bu boşluğa kaydırabilirsin'); });
    } else {
      node.innerHTML = _msubKart(p, false, milli);
      if (typeof p.matchRating === 'number') { const _bt = node.querySelector('.fpn-bottom'); if (_bt) _bt.insertAdjacentHTML('beforeend', `<span class="gm-rt" style="background:${_gmRRenk(p.matchRating)}">${p.matchRating.toFixed(1)}</span>`); }
      if (dr && dr.d === 'inj') { node.classList.add('is-inj'); node.insertAdjacentHTML('beforeend', '<span class="mlp-mark">🚑</span>'); }
    }
    node.addEventListener('dragover',  e => { e.preventDefault(); node.classList.add('drop-hover'); });
    node.addEventListener('dragleave', () => node.classList.remove('drop-hover'));
    node.addEventListener('drop',      e => { e.preventDefault(); node.classList.remove('drop-hover'); doMsubBenchToPitchSwap(mi); });
    msubMakeDraggable(node, mi);
    dst.appendChild(node);
  });
}
function _msubYedekCiz(dst) {
  const { myTeam } = _whichSideIsUser();
  const milli = !!MS._isNational;
  const yedek = (myTeam && Array.isArray(myTeam.benchPlayers)) ? myTeam.benchPlayers : [];
  const cik = _msCikanlar();
  dst.innerHTML = '';
  MS._currentBench = [];
  if (!yedek.length) { dst.innerHTML = '<div style="padding:18px;text-align:center;color:var(--text3);font-size:11px">Yedek yok.</div>'; return; }
  yedek.forEach((p, i) => {
    const kapali = !p || cik.has(p.name);
    MS._currentBench.push(kapali ? null : p);
    if (!p) return;
    const node = document.createElement('div');
    node.className = 'bench-card' + (kapali ? ' bench-disabled' : '');
    node.id = 'msubBench_' + i;
    node.dataset.ad = p.name;
    node.style.position = 'relative';
    node.innerHTML = _msubKart(p, true, milli);
    if (kapali) {
      const dk = cik.get(p.name);
      node.insertAdjacentHTML('beforeend', `<div style="position:absolute;top:4px;right:6px;background:#ef5350;color:#fff;font-size:10px;font-weight:800;padding:2px 5px;border-radius:8px;line-height:1;z-index:5;pointer-events:none">↓ ${dk != null ? dk + "'" : ''}</div>`);
      node.addEventListener('click', (e) => { e.preventDefault(); e.stopPropagation(); _msCikanUyari(p.name, dk); });
    } else {
      node.draggable = true;
      node.addEventListener('dragstart', e => msubBenchDragStart(e, i));
      node.addEventListener('dragend',   e => msubBenchDragEnd(e));
      msubMakeBenchTouchDraggable(node, i);
    }
    dst.appendChild(node);
  });
}

function renderMatchSubBench() {
  try { _msCikanlarBilgi(); } catch(e) {}
  const dst = document.getElementById('msubBenchList');
  if (!dst) return;
  _msubYedekCiz(dst);
  try { _gmModBant(); _gmYedekDuzenle(); } catch(e) {}
}

// 625 — Değişiklik maçın kadrosuna işlenir: giren çıkanın yuvasına geçer, çıkan yedeklerde
//   "çıktı · giremez" olarak kalır. Takımım dizilişine dokunulmaz (maç içi değişiklik geçicidir;
//   Takımım ekranı maç dizilişini canlı eşlemeden alır).
function _msubSyncStateAfterSwap(pitchIdx, giren) {
  const { myTeam } = _whichSideIsUser();
  const eski = myTeam && Array.isArray(myTeam.players) ? myTeam.players[pitchIdx] : null;
  if (eski) {
    if (!Array.isArray(myTeam.benchPlayers)) myTeam.benchPlayers = [];
    const bi = myTeam.benchPlayers.findIndex(p => p && p.name === giren.name);
    if (bi !== -1) myTeam.benchPlayers[bi] = eski;
    else myTeam.benchPlayers.push(eski);
    myTeam.players[pitchIdx] = { ...giren, pos: eski.pos, x: eski.x, y: eski.y, _slotIdx: eski._slotIdx, slotIdx: eski.slotIdx,
      slotPos: eski.slotPos, isUser: !!(giren.isUser || giren.role === 'user') };
  }
  setTimeout(() => { renderMatchSubPitch(); renderMatchSubBench(); }, 0);
}

// 625 — Saha içi yer değişikliği: iki oyuncunun YUVASI değişir (kimlik, kart, reyting oyuncuda kalır)
function _msubYerDegis(a, b) {
  ['x', 'y', '_slotIdx', 'slotIdx', 'slotPos', 'pos'].forEach(k => { const t = a[k]; a[k] = b[k]; b[k] = t; });
}

// 🆕 Yakındaki swap hedefini bul (saha içi mesafe, % cinsinden)
// 🆕 Hedef kartı EKRANDAKİ gerçek konumlardan bul.
//    Eski sürüm sunucudaki myTeam.players[i].x/y değerlerine bakıyordu; bunlar
//    sahadaki kartların gerçek yerleriyle örtüşmediği için yanlış slota bırakıyor
//    ya da hiç hedef bulamıyordu. Ayrıca ilk eşleşeni değil, EN YAKIN olanı seçer.
function _msubFindSwapTarget(srcIdx, x, y, threshold) {
  let best = -1, bestD = (typeof threshold === 'number' ? threshold : 12);
  try {
    const nodes = document.querySelectorAll('#msubPitchPlayers .fpn');
    nodes.forEach(n => {
      const i = parseInt(String(n.id).replace('msubFpn_', ''), 10);
      if (!isFinite(i) || i === srcIdx) return;
      const nx = parseFloat(n.style.left), ny = parseFloat(n.style.top);
      if (!isFinite(nx) || !isFinite(ny)) return;
      const d = Math.sqrt((nx - x) * (nx - x) + (ny - y) * (ny - y));
      if (d <= bestD) { bestD = d; best = i; }
    });
  } catch(e) {}
  return best;
}

// 🆕 Pitch-to-pitch sürükle-bırak — iki oyuncu yuva değiştirir (625: kimlik değil yuva takası).
//   Kırmızı kartın boş yerine sahadan oyuncu kaydırılabilir. Sub değildir → hak düşmez.
function msubMakeDraggable(node, idx) {
  let startX, startY, startLeft, startTop, dragging = false;
  let originalLeft, originalTop, totalMove = 0;
  const SWAP_THRESHOLD = 12; // % cinsinden

  function _getPitch() {
    return document.getElementById('msubPitch') || node.parentElement;
  }

  function onStart(e) {
    // 🆕 Yetki kontrolü: yalnızca kendi takımının kaptan/yardımcısı sürükleyebilir
    if (!_msCanControlTactics()) { _msDenyTactic(); return; }
    if (node.classList.contains('is-red') || node.classList.contains('is-inj')) return;   // 625 — oyunda olmayan oyuncu taşınmaz
    // 🆕 DOKUNMATİK: hemen preventDefault ETME — yoksa sayfa hiç kaydırılamıyor.
    //    Parmak 200 ms sabit kalırsa sürükleme başlar; erken hareket ederse
    //    tarayıcı normal kaydırmayı yapar.
    const _isTouch = !!e.touches;
    if (!_isTouch) e.preventDefault();
    const touch = e.touches ? e.touches[0] : e;
    startX = touch.clientX;
    startY = touch.clientY;
    startLeft = parseFloat(node.style.left);
    startTop  = parseFloat(node.style.top);
    originalLeft = startLeft;
    originalTop  = startTop;
    totalMove = 0;
    node._wasDragging = false;
    node._gmBench = null;
    try { node._gmScroll0 = (document.getElementById('match-screen') || {}).scrollTop || 0; } catch(e) { node._gmScroll0 = 0; }

    const _basla = () => {
      dragging = true;
      node.style.transition = 'none';
      node.style.zIndex = '20';
      node.classList.add('is-dragging');
      cftTitret(12);
    };

    if (_isTouch) {
      // 573 — bekleme yok: yatay hareket anında sürükler; dikey hareket sayfayı kaydırır;
      //   parmak hareketsiz 120 ms durursa da sürükleme başlar (her yöne taşımak için).
      node._holdT = setTimeout(() => { node._holdT = null; _basla(); }, 120);
      const _iptal = (ev) => {
        const t = ev.touches ? ev.touches[0] : ev;
        if (!t || dragging) return;
        const _dx = t.clientX - startX, _dy = t.clientY - startY;
        if (Math.abs(_dx) + Math.abs(_dy) > 6) {
          if (node._holdT) { clearTimeout(node._holdT); node._holdT = null; }
          document.removeEventListener('touchmove', _iptal);
          if (Math.abs(_dx) > Math.abs(_dy)) _basla();
        }
      };
      document.addEventListener('touchmove', _iptal, { passive: true });
      node._holdCancel = _iptal;
    } else {
      _basla();
    }

    // 🆕 Scoped listener — sadece drag boyunca doc'a takılır, sonunda silinir
    document.addEventListener('mousemove',  onMove);
    document.addEventListener('touchmove',  onMove, { passive: false });
    document.addEventListener('mouseup',    onEnd);
    document.addEventListener('touchend',   onEnd);
    document.addEventListener('touchcancel', onEnd);
  }
  function onMove(e) {
    if (!dragging) return;
    const pitch = _getPitch();
    if (!pitch) return;
    e.preventDefault();
    const touch = e.touches ? e.touches[0] : e;
    const pr = pitch.getBoundingClientRect();
    // 574 — ekran kayarsa (otomatik kaydırma) parmak konumunu telafi et
    let _sd = 0; try { _sd = ((document.getElementById('match-screen') || {}).scrollTop || 0) - (node._gmScroll0 || 0); } catch(e) {}
    const dx = ((touch.clientX - startX) / pr.width) * 100;
    const dy = ((touch.clientY + _sd - startY) / pr.height) * 100;
    // 574 — saha → yedek: parmak bir yedek kartın üstündeyse onu hedefle
    try {
      if (typeof _gmOtoKaydir === 'function') _gmOtoKaydir(touch.clientY);
      const _bc = (typeof _gmYedekAltinda === 'function') ? _gmYedekAltinda(touch.clientX, touch.clientY) : null;
      document.querySelectorAll('#msubBenchList .bench-card.drop-hover').forEach(el => { if (el !== _bc) el.classList.remove('drop-hover'); });
      if (_bc && !_bc.classList.contains('bench-disabled')) _bc.classList.add('drop-hover');
      node._gmBench = _bc;
    } catch(e) {}
    totalMove = Math.max(totalMove, Math.abs(dx) + Math.abs(dy));
    if (totalMove > 1.5) node._wasDragging = true;
    const nx = Math.max(2, Math.min(98, startLeft + dx));
    const ny = Math.max(2, Math.min(98, startTop  + dy));
    node.style.left = nx + '%';
    node.style.top  = ny + '%';

    const targetIdx = _msubFindSwapTarget(idx, nx, ny, SWAP_THRESHOLD);
    document.querySelectorAll('#msubPitchPlayers .fpn.swap-target').forEach(el => el.classList.remove('swap-target'));
    if (targetIdx !== -1) {
      const tEl = document.getElementById('msubFpn_' + targetIdx);
      if (tEl) tEl.classList.add('swap-target');
    }
  }
  function onEnd(e) {
    // 🆕 Basılı-tut bekçisini temizle
    if (node._holdT) { clearTimeout(node._holdT); node._holdT = null; }
    if (node._holdCancel) { document.removeEventListener('touchmove', node._holdCancel); node._holdCancel = null; }
    if (!dragging) { document.removeEventListener('mousemove', onMove); document.removeEventListener('touchmove', onMove);
      document.removeEventListener('mouseup', onEnd); document.removeEventListener('touchend', onEnd);
      document.removeEventListener('touchcancel', onEnd); return; }
    if (!dragging) return;
    dragging = false;
    // 🆕 Scoped listener cleanup
    document.removeEventListener('mousemove',  onMove);
    document.removeEventListener('touchmove',  onMove);
    document.removeEventListener('mouseup',    onEnd);
    document.removeEventListener('touchend',   onEnd);
    document.removeEventListener('touchcancel', onEnd);

    node.style.transition = '';
    node.style.zIndex = '';
    node.classList.remove('is-dragging');
    document.querySelectorAll('#msubPitchPlayers .fpn.swap-target').forEach(el => el.classList.remove('swap-target'));
    document.querySelectorAll('#msubBenchList .bench-card.drop-hover').forEach(el => el.classList.remove('drop-hover'));
    // 574 — saha → yedek bırakma: oyuncu değişikliği
    if (node._gmBench && node._wasDragging) {
      const _bc = node._gmBench; node._gmBench = null;
      node.style.left = originalLeft + '%';
      node.style.top  = originalTop + '%';
      const _bi = parseInt(String(_bc.id || '').replace('msubBench_', ''), 10);
      if (_bc.classList.contains('bench-disabled')) { try { _bc.click(); } catch(e) {} return; }
      if (isFinite(_bi) && typeof _doMsubSwap === 'function') _doMsubSwap(idx, _bi);
      return;
    }

    const curLeft = parseFloat(node.style.left);
    const curTop  = parseFloat(node.style.top);
    const targetIdx = _msubFindSwapTarget(idx, curLeft, curTop, SWAP_THRESHOLD);

    if (targetIdx !== -1 && node._wasDragging) {
      const myTeam = _whichSideIsUser().myTeam;
      node.style.left = originalLeft + '%';
      node.style.top  = originalTop + '%';
      const a = myTeam && myTeam.players && myTeam.players[idx];
      const b = myTeam && myTeam.players && myTeam.players[targetIdx];
      if (a && b) {
        const drB = _msKadroDurum(b, _msBenimTaraf());
        // Sakatın yerine önce yedekten oyuncu alınır (hak kaldıysa); kırmızının yerine alınamaz → boşluğa kaydırılır
        if (drB && drB.d === 'inj' && (MS.subsLeft || 0) > 0) { showTacticFlash('🚑 ' + b.name + ' sakatlandı — yerine yedekten oyuncu al'); return; }
        _msubYerDegis(a, b);
        // 584 — kalıcı kayıt yok; yer değişikliği maça gider (yalnız bu maç)
        try { if (typeof macTaktikGonder === 'function') macTaktikGonder('dizilis'); } catch(e) {}
        showSwapToast(drB ? `${a.name} → ${b.slotPos || b.pos || ''}` : `${a.name} ↔ ${b.name}`);
        renderMatchSubPitch();
      }
    } else {
      node.style.left = originalLeft + '%';
      node.style.top  = originalTop + '%';
    }
  }
  node.addEventListener('mousedown',  onStart);
  node.addEventListener('touchstart', onStart, { passive: false });
}

// 🆕 MOBİL TOUCH DRAG — Yedek oyuncuyu sahadaki bir oyuncuya sürükleyerek sub yap
//    (HTML5 native dragstart/drop mobilde tetiklenmez, manuel touch ile çözüyoruz)
function msubMakeBenchTouchDraggable(node, idx) {
  let dragging = false;
  let ghost = null;
  let startX = 0, startY = 0, totalMove = 0;
  let lastTargetEl = null;

  function _clearTargetHighlight() {
    document.querySelectorAll('#msubPitchPlayers .fpn.drop-hover').forEach(el => {
      el.classList.remove('drop-hover');
    });
  }

  function _findPitchTargetAt(x, y) {
    // Saha içindeki .fpn elemanlarını dolaş, x/y pointer'ı içeren ilkini döndür
    // (Kaleci filtresi kaldırıldı — KL→KL sub için kaleci hedef olabilmeli)
    const pitchEls = document.querySelectorAll('#msubPitchPlayers .fpn');
    for (const el of pitchEls) {
      const r = el.getBoundingClientRect();
      if (x >= r.left && x <= r.right && y >= r.top && y <= r.bottom) {
        return el;
      }
    }
    return null;
  }

  function onStart(e) {
    // 🆕 Yetki kontrolü
    if (!_msCanControlTactics()) { _msDenyTactic(); return; }
    if (MS.subsLeft <= 0) { showTacticFlash('❌ Değişiklik hakkın bitti'); return; }
    // Sadece touch event'lerde ghost drag başlat (desktop'ta native drag çalışır)
    const isTouch = !!e.touches;
    if (!isTouch) return;
    const t = e.touches[0];
    startX = t.clientX;
    startY = t.clientY;
    totalMove = 0;
    node._wasDragging = false;
    // 573 — BEKLEME YOK: yedek kartı hangi yöne çekilirse çekilsin sürükleme ANINDA başlar
    //   (kartlarda touch-action:none; sayfa kartların dışından kaydırılır). Dokunup bırakmak
    //   eskisi gibi seçimdir.
    node._holdT = setTimeout(() => { node._holdT = null; _benchBasla(); }, 120);
    const _iptal = (ev) => {
      const tt = ev.touches ? ev.touches[0] : ev;
      if (!tt || dragging) return;
      const _dx = tt.clientX - startX, _dy = tt.clientY - startY;
      if (Math.abs(_dx) + Math.abs(_dy) > 6) {
        if (node._holdT) { clearTimeout(node._holdT); node._holdT = null; }
        document.removeEventListener('touchmove', _iptal);
        _benchBasla();
        if (ghost) { ghost.style.left = (tt.clientX - 60) + 'px'; ghost.style.top = (tt.clientY - 30) + 'px'; }
      }
    };
    document.addEventListener('touchmove', _iptal, { passive: true });
    node._holdCancel = _iptal;

    function _benchBasla() {
    dragging = true;
    _msubDragBenchIdx = idx;
    cftTitret(12);
    // Ghost element (sürüklenen kopyası)
    ghost = node.cloneNode(true);
    ghost.classList.add('msub-drag-ghost');   // 🆕 #msubBenchList kapsamı dışında da aynı görünsün
    ghost.style.position = 'fixed';
    ghost.style.left = (startX - 60) + 'px';
    ghost.style.top  = (startY - 30) + 'px';
    ghost.style.width = node.offsetWidth + 'px';
    ghost.style.zIndex = '9999';
    ghost.style.opacity = '0.85';
    ghost.style.pointerEvents = 'none';
    ghost.style.transform = 'scale(0.96) rotate(-1.5deg)';
    ghost.style.boxShadow = '0 12px 30px rgba(0,0,0,0.5)';
    ghost.style.transition = 'none';
    document.body.appendChild(ghost);
    node.style.opacity = '0.35';
    document.querySelectorAll('#msubPitchPlayers .fpn').forEach(el => {
      el.classList.add('swap-target');
    });
    }
    document.addEventListener('touchmove',   onMove, { passive: false });
    document.addEventListener('touchend',    onEnd);
    document.addEventListener('touchcancel', onEnd);
  }

  function onMove(e) {
    if (!dragging || !ghost) return;
    e.preventDefault();
    const t = e.touches[0];
    const dx = t.clientX - startX;
    const dy = t.clientY - startY;
    totalMove = Math.max(totalMove, Math.abs(dx) + Math.abs(dy));
    if (totalMove > 6) node._wasDragging = true;
    ghost.style.left = (t.clientX - 60) + 'px';
    ghost.style.top  = (t.clientY - 30) + 'px';
    try { if (typeof _gmOtoKaydir === 'function') _gmOtoKaydir(t.clientY); } catch(e) {}
    const target = _findPitchTargetAt(t.clientX, t.clientY);
    if (target !== lastTargetEl) {
      _clearTargetHighlight();
      if (target) target.classList.add('drop-hover');
      lastTargetEl = target;
    }
  }

  function onEnd(e) {
    // 🆕 Basılı-tut bekçisini temizle
    if (node._holdT) { clearTimeout(node._holdT); node._holdT = null; }
    if (node._holdCancel) { document.removeEventListener('touchmove', node._holdCancel); node._holdCancel = null; }
    if (!dragging) { document.removeEventListener('touchmove', onMove);
      document.removeEventListener('touchend', onEnd); document.removeEventListener('touchcancel', onEnd); return; }
    if (!dragging) return;
    dragging = false;
    document.removeEventListener('touchmove',   onMove);
    document.removeEventListener('touchend',    onEnd);
    document.removeEventListener('touchcancel', onEnd);
    if (ghost && ghost.parentNode) ghost.parentNode.removeChild(ghost);
    ghost = null;
    node.style.opacity = '';
    document.querySelectorAll('#msubPitchPlayers .fpn').forEach(el => {
      el.classList.remove('swap-target', 'drop-hover');
    });
    const lastTouch = (e.changedTouches && e.changedTouches[0]) || null;
    if (!lastTouch || !node._wasDragging) {
      // Drag çok kısaysa → tıklama olarak işle (msubBenchClick zaten handle eder)
      _msubDragBenchIdx = null;
      return;
    }
    const target = _findPitchTargetAt(lastTouch.clientX, lastTouch.clientY);
    if (target && target.id && target.id.startsWith('msubFpn_')) {
      const pitchIdx = parseInt(String(target.id).replace('msubFpn_', ''), 10);   // 🆕 slice(9) → ilk rakamı yiyordu
      if (!isNaN(pitchIdx)) {
        // Sub uygula!
        if (typeof _doMsubSwap === 'function') {
          _doMsubSwap(pitchIdx, idx);
        } else if (typeof doMsubBenchToPitchSwap === 'function') {
          doMsubBenchToPitchSwap(pitchIdx);
        }
      }
    }
    _msubDragBenchIdx = null;
  }

  node.addEventListener('touchstart', onStart, { passive: false });
}


// 🆕 Sahadaki oyuncuya tıklama — seç (bench seçili ise → swap)
function msubPitchClick(idx) {
  // 574 — dokun-seç kaldırıldı: değişiklik yalnız sürükle-bırak ile (yedek → saha, saha → yedek)
  return;
  if (!MS._tacticControlsActive) {
    showTacticFlash('Bu maçta taktik kontrolü yok!');
    return;
  }
  if (MS.subsLeft <= 0) {
    showTacticFlash('❌ Değişiklik hakkın bitti');
    return;
  }
  const { myTeam } = _whichSideIsUser();
  if (!myTeam) return;
  const p = myTeam.players[idx];
  if (!p) return;
  // Kaleci kontrolü _doMsubSwap'ta yapılıyor — kaleci → kaleci sub destekleniyor

  // Bench seçili ise → bench'i sahaya getir
  if (MS._tacSelectedBenchIdx !== null && MS._tacSelectedBenchIdx !== undefined) {
    doMsubBenchToPitchSwap(idx);
    return;
  }

  // Aynı pitch oyuncusu tekrar → deselect
  if (MS._tacSelectedPitchIdx === idx) {
    MS._tacSelectedPitchIdx = null;
  } else {
    MS._tacSelectedPitchIdx = idx;
  }
  renderMatchSubPitch();

  const help = document.getElementById('tacSubsHelp');
  if (help) {
    if (MS._tacSelectedPitchIdx !== null) {
      help.innerHTML = `<span style="color:#00e676">✓ ${_escapeHtml(p.name)}</span> seçildi → yedeklerden seç veya sürükle.`;
    } else {
      help.innerHTML = 'Sahadaki bir oyuncuya tıkla → yedeklerden birini seç. Veya yedeği sahaya sürükle.';
    }
  }
}

// 🆕 Bench tıklama — seçili pitch oyuncusu varsa swap, yoksa bench seç
function msubBenchClick(benchIdx) {
  return;   // 574 — dokun-seç kaldırıldı (yalnız sürükle-bırak)
  if (!MS._tacticControlsActive) {
    showTacticFlash('Bu maçta taktik kontrolü yok!');
    return;
  }
  if (MS.subsLeft <= 0) {
    showTacticFlash('❌ Değişiklik hakkın bitti');
    return;
  }
  // Pitch seçili ise → sub uygula
  if (MS._tacSelectedPitchIdx !== null && MS._tacSelectedPitchIdx !== undefined) {
    _doMsubSwap(MS._tacSelectedPitchIdx, benchIdx);
    return;
  }
  // Aynı bench tekrar → deselect
  if (MS._tacSelectedBenchIdx === benchIdx) {
    MS._tacSelectedBenchIdx = null;
  } else {
    MS._tacSelectedBenchIdx = benchIdx;
  }
  renderMatchSubBench();

  const help = document.getElementById('tacSubsHelp');
  if (help) {
    if (MS._tacSelectedBenchIdx !== null) {
      const bp = (MS._currentBench || [])[benchIdx];
      help.innerHTML = `<span style="color:#00e676">${_escapeHtml('✓ ' + (bp ? bp.name : 'Yedek'))}</span> seçildi → sahadan değişecek oyuncuyu seç.`;
    } else {
      help.innerHTML = 'Sahadaki bir oyuncuya tıkla → yedeklerden birini seç. Veya yedeği sahaya sürükle.';
    }
  }
}

// 🆕 Bench drag start
let _msubDragBenchIdx = null;
function msubBenchDragStart(e, idx) {
  if (!MS._tacticControlsActive || MS.subsLeft <= 0) {
    e.preventDefault();
    return;
  }
  _msubDragBenchIdx = idx;
  e.dataTransfer.effectAllowed = 'move';
  e.dataTransfer.setData('text/plain', String(idx));
  // Tüm pitch oyuncularını drop hedefi yap (kaleci dahil — KL→KL sub destekli)
  document.querySelectorAll('#msubPitchPlayers .fpn').forEach(n => {
    n.classList.add('swap-target');
  });
  setTimeout(() => {
    const el = document.getElementById('msubBench_' + idx);
    if (el) el.style.opacity = '0.4';
  }, 0);
}
function msubBenchDragEnd(e) {
  _msubDragBenchIdx = null;
  document.querySelectorAll('#msubPitchPlayers .fpn').forEach(n => n.classList.remove('swap-target', 'drop-hover'));
  document.querySelectorAll('#msubBenchList .bench-item').forEach(b => b.style.opacity = '');
}
// Drag → drop hedefine sub uygula
function doMsubBenchToPitchSwap(pitchIdx) {
  if (_msubDragBenchIdx === null) return;
  _doMsubSwap(pitchIdx, _msubDragBenchIdx);
  _msubDragBenchIdx = null;
}


// 🆕 CANLI OYUNCU DEĞİŞİKLİĞİNİ SUNUCUYA BİLDİR
//   Motor match_state.home_lineup/away_lineup içindeki pendingSubs listesini okuyup
//   ilgili dakikada uyguluyor (appliedSubKeys ile idempotent). İstemci bunu yazmıyordu,
//   bu yüzden maç içi değişiklikler simülasyona yansımıyordu.
async function _msPushSubToServer(outNum, inNum) {
  // (511) Tek yol: sunucu (match_sub) — yetki + kural denetimi orada. İstemci
  //   match_state'e doğrudan yazmaz. Dönüş: { ok, error }
  try {
    if (typeof MS === 'undefined' || !MS || !MS.match_key) return { ok: false, error: 'mac_yok' };
    if (typeof _msCanControlTactics === 'function' && !_msCanControlTactics()) return { ok: false, error: 'yetki_yok' };
    const _res = await edgeCall('match_sub', { match_key: MS.match_key, out: outNum, in: inNum }, { zamanAsimi: 10000 });
    try { MS._kadroZorla = true; } catch(e) {}   // 🆕 563 — bekleyen değişiklik kadroda görünsün
    const _d = _res && _res.data;
    if (!_res || !_res.ok || !_d || _d.error) return { ok: false, error: (_d && _d.error) || 'sunucu_hatasi' };
    return { ok: true, minute: _d.minute };
  } catch(e) { console.warn('[sub] hata:', e); return { ok: false, error: 'baglanti' }; }
}

// (511) Sunucu hata kodu → oyuncuya anlaşılır mesaj
function _msSubHataMetni(kod) {
  const M = {
    oyuncu_sahada_degil: 'Bu oyuncu artık sahada değil',
    oyundan_cikan_tekrar_giremez: 'Oyundan çıkan oyuncu tekrar giremez',
    yedek_bulunamadi: 'Bu yedek maç kadrosunda yok',
    degisiklik_hakki_bitti: 'Değişiklik hakkın bitti',
    mac_bitti: 'Maç bitti',
    yetki_yok: 'Değişiklik yetkin yok',
    bu_mac_senin_degil: 'Bu maç senin takımının değil',
    oyuncu_zaten_degisiyor: 'Bu oyuncu için bekleyen bir değişiklik var',
    baglanti: 'Bağlantı yavaş — değişiklik iletilemedi, tekrar dene',
  };
  return M[kod] || 'Değişiklik sunucuya iletilemedi';
}

// 🆕 Asıl sub işlemi — kontroller + motor entegrasyonu
//   625 — Ekran beklemeden güncellenir (sürükle-bırak anında işler); sunucu (match_sub) kuralı
//   denetler, reddederse ya da bağlantı zaman aşımına uğrarsa değişiklik ekranda geri alınır.
async function _doMsubSwap(pitchIdx, benchIdx) {
  // 🆕 Yetki kontrolü — izleyici veya yetkisiz üye değişiklik yapamaz
  if (!_msCanControlTactics()) return _msDenyTactic();
  if (MS.subsLeft <= 0) { showTacticFlash('❌ Değişiklik hakkın bitti'); return; }
  const { myTeam, userInHome } = _whichSideIsUser();
  if (!myTeam) return;
  const playerOut = myTeam.players[pitchIdx];
  if (!playerOut) return;
  const _durum = _msKadroDurum(playerOut, _msBenimTaraf());
  if (_durum && _durum.d === 'red') { showTacticFlash('🟥 Kırmızı kart gören oyuncunun yerine oyuncu alınamaz'); return; }
  const benchPlayer = (MS._currentBench || [])[benchIdx];
  if (!benchPlayer) { showTacticFlash('⛔ Bu oyuncu oyundan çıktı — tekrar oyuna giremez'); return; }
  const _outNum = (typeof playerOut.num === 'number') ? playerOut.num : null;
  const _inNum  = (typeof benchPlayer.num === 'number') ? benchPlayer.num : null;
  if (_outNum == null || _inNum == null) { showTacticFlash('⚠️ Oyuncu numarası bulunamadı'); return; }

  // Doğru dakika: skorborddakiyle aynı (MS._displayMin smoothing timer'dan gelir)
  let curMin = Math.floor(MS._displayMin > 0 ? MS._displayMin : (MS.minute > 0 ? MS.minute : 1));
  if (curMin < 1) curMin = 1;
  // outSnapshot: çıkan oyuncunun kopyası (KADROLAR listesinde kalsın)
  const kayit = {
    in: benchPlayer.name, out: playerOut.name, min: curMin, _pending: true,
    outSnapshot: { name: playerOut.name, num: playerOut.num, pos: playerOut.pos,
      rating: playerOut.rating || playerOut.overall || 70, overall: playerOut.overall || playerOut.rating || 70,
      matchRating: typeof playerOut.matchRating === 'number' ? playerOut.matchRating : null,
      matchGoals: playerOut.matchGoals || 0, matchAssists: playerOut.matchAssists || 0,
      isUser: !!playerOut.isUser, team: userInHome ? 'home' : 'away', _exitMin: curMin }
  };
  const hakYaz = () => { const el = document.getElementById('tacSubsLeft'); if (el) el.textContent = MS.subsLeft; try { _gmModBant(); } catch(e) {} };
  MS.subsHistory = MS.subsHistory || [];
  MS.subsHistory.push(kayit);
  MS.subsLeft = Math.max(0, (MS.subsLeft || 0) - 1);
  hakYaz();
  _msubSyncStateAfterSwap(pitchIdx, benchPlayer);
  showTacticFlash(`▲ ${benchPlayer.name} · ▼ ${playerOut.name}`);
  try { if (typeof renderLineup === 'function') renderLineup(); } catch(e) {}

  const _sonuc = await _msPushSubToServer(_outNum, _inNum);
  if (_sonuc && _sonuc.ok) {
    if (typeof _sonuc.minute === 'number' && _sonuc.minute > 0) { kayit.min = _sonuc.minute + 1; kayit.outSnapshot._exitMin = kayit.min; }
    return;
  }
  // Geri al: giren yedeğe, çıkan yuvasına döner; hak iade edilir
  const gi = myTeam.players.findIndex(p => p && p.num === _inNum);
  if (gi !== -1) myTeam.players[gi] = playerOut;
  const ci = Array.isArray(myTeam.benchPlayers) ? myTeam.benchPlayers.findIndex(p => p && p.num === _outNum) : -1;
  if (ci !== -1) myTeam.benchPlayers[ci] = benchPlayer;
  MS.subsHistory = MS.subsHistory.filter(x => x !== kayit);
  MS.subsLeft = Math.min(5, (MS.subsLeft || 0) + 1);
  hakYaz();
  showTacticFlash('❌ ' + _msSubHataMetni(_sonuc && _sonuc.error));
  renderMatchSubPitch();
  renderMatchSubBench();
  try { if (typeof renderLineup === 'function') renderLineup(); } catch(e) {}
}

// 🆕 Geriye dönük uyumluluk — eski fonksiyonlar yeni sistemi çağırsın
function renderTacticPitch() { renderMatchSubPitch(); }
function renderTacticBench() { renderMatchSubBench(); }
function tacPitchPlayerClick(idx) { msubPitchClick(idx); }
function tacBenchClick(benchIdx) { msubBenchClick(benchIdx); }

// Anlık etki bildirimi göster
function showTacticFlash(msg) {
  const f = document.getElementById('tacticFlash');
  if (!f) return;
  // 573 — Balon maç ekranının içindeydi: `#match-screen > *{position:relative}` kuralı
  //   position:fixed'i eziyor ve mesaj sayfanın EN ALTINDA kalıyordu (görünmüyordu).
  //   Gövdeye taşınınca ekranın üstünde, her kaydırma konumunda görünür.
  if (f.parentNode !== document.body) { try { document.body.appendChild(f); } catch(e) {} }
  f.textContent = (typeof T === 'function') ? T(String(msg)) : msg;
  f.setAttribute('data-noi18n', '');
  f.classList.add('show');
  clearTimeout(f._timer);
  f._timer = setTimeout(() => f.classList.remove('show'), 2400);
}

function closeMatchScreen(){
  // Pre-match auto-start zamanlayıcısını temizle
  if (window._mpAutoStartTimer) { clearInterval(window._mpAutoStartTimer); window._mpAutoStartTimer = null; }
  // 🆕 İzleyici beat timer temizle + leave sinyali gönder
  if (window._viewerBeatTimer) {
    clearInterval(window._viewerBeatTimer);
    window._viewerBeatTimer = null;
  }
  try {
    if (window._viewerBeatMatchKey && window.authUser && window.authUser.id &&
        typeof SUPABASE_URL !== 'undefined' && typeof SUPABASE_KEY !== 'undefined') {
      const _mkL = window._viewerBeatMatchKey;
      const _uidL = window.authUser.id;
      _oturumJwt().then(_jwt => { if (_jwt) return fetch(`${SUPABASE_URL}/functions/v1/tick-matches?action=viewer_leave&match_key=${encodeURIComponent(_mkL)}&user_id=${encodeURIComponent(_uidL)}`, {
        headers: { 'Authorization': 'Bearer ' + _jwt, 'apikey': SUPABASE_KEY }
      }); }).catch(() => {});
    }
  } catch(e) {}
  window._viewerBeatMatchKey = null;
  try { if (typeof window.rtWatchMatch === 'function') window.rtWatchMatch(null); } catch(e) {}
  // İzleyici badge'i gizle
  try {
    const _vb = document.getElementById('msViewerBadge');
    if (_vb) _vb.classList.remove('is-visible');
  } catch(e) {}
  // İzleyici modu işaretini temizle
  if (typeof MS !== 'undefined' && MS) {
    MS._spectatorMode = false;
    // 🆕 Sonraki maça karışmasın diye event/goal cache state'lerini de temizle
    MS._notifiedGoals = null;
    MS._renderedEventKeys = null;
    MS._serverSimMin = 0;
    MS._matchStartedAt = null;
    MS._displayMin = 0;
    MS._htShown = false;
    MS._evDebugLogged = false;
    MS.match_key = null;
  }
  // Maç sonu overlay'i kapat
  const ov = document.getElementById('match-result-overlay');
  if (ov) ov.classList.remove('show');
  // Fixture ref temizle (overlay kullandı, artık güvenli)
  if (typeof MS !== 'undefined') {
    MS._fixtureRef = null;
    MS._fixtureIdx = null;
    MS._isFriendly = false;
  }
  MS.running=false;
  document.getElementById('match-screen').classList.remove('open');

  // 🆕 Maç içi sub'lar activePitchPlayers/benchPlayers'ı (takım sayfası RAM state'i) geçici
  //   değiştirmiş olabilir. Kalıcı taktik (kayıtlı strateji) BOZULMADI — RAM görselini de
  //   kayıtlı stratejiden geri yükle ki takım sayfası kayıtlı dizilişe dönsün.
  try {
    if (typeof loadTeamStrategy === 'function' && _teamStrategyCache) {
      loadTeamStrategy();
      if (typeof renderPitch === 'function') renderPitch();
      if (typeof renderBench === 'function') renderBench();
    }
  } catch(e) {}
}

// 🆕 Maç ekranını kapat ve doğrudan ana sayfaya dön (sağ üst X butonu)
function closeMatchToHome(){
  try { closeMatchScreen(); } catch(e) {}
  try {
    if (typeof showPage === 'function') {
      // Ana sayfa nav butonu (genelde ilk .nav-btn)
      const navBtns = document.querySelectorAll('.nav-btn');
      let homeBtn = null;
      navBtns.forEach(b => {
        const onclick = b.getAttribute('onclick') || '';
        if (onclick.includes("'home'") && !homeBtn) homeBtn = b;
      });
      showPage('home', homeBtn || (navBtns[0] || null));
    }
  } catch(e) { console.warn('closeMatchToHome:', e); }
}

// 🆕 ═══════════ HIZLI TEST MAÇI ═══════════
// Yeni motoru görmek için iki takım seçer ve canlı maç ekranını açar.
// Her test farklı sonuç verir (test salt seed). Lig tablosuna yansımaz.
function runQuickTestMatch() {
  try {
    // Takım seçimi: kullanıcı takımı varsa kullan, yoksa teams DB'den 2 random
    let homeData = null, awayData = null;

    function _findInDB(name) {
      if (false) return null;
      for (const cc of _cftGetCountryCodes()) {
        for (const lg of (_cftGetCountry(cc).leagues || [])) {
          const t = (lg.teams || []).find(x => x.name === name);
          if (t) return { ...t, countryCode: cc };
        }
      }
      return null;
    }
    function _topLeagueTeams(cc) {
      if (false || !_cftGetCountry(cc)) return [];
      const top = (_cftGetCountry(cc).leagues || [])[0];
      return (top && top.teams) ? top.teams.map(t => ({ ...t, countryCode: cc })) : [];
    }

    if (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName) {
      homeData = _findInDB(_userTeam.teamName) || {
        name: _userTeam.teamName, short: _userTeam.teamName.slice(0, 3).toUpperCase(),
        rating: 75, countryCode: (typeof authUser !== 'undefined' && authUser && authUser.nationality) || 'TR'
      };
      // Aynı ülkeden farklı bir Süper Lig takımı seç
      const cc = homeData.countryCode || 'TR';
      const peers = _topLeagueTeams(cc).filter(t => t.name !== homeData.name);
      if (peers.length) {
        awayData = peers[Math.floor(Math.random() * peers.length)];
      }
    }

    if (!homeData || !awayData) {
      // Fallback: kullanıcının uyruğu Süper Lig'inden 2 random
      const cc = (typeof authUser !== 'undefined' && authUser && authUser.nationality) || 'TR';
      let pool = _topLeagueTeams(cc);
      if (pool.length < 2) {
        // Son fallback: tüm DB'den top lig'lerden bir araya getir
        if (true) {
          pool = [];
          for (const c of _cftGetCountryCodes()) {
            const lg = (_cftGetCountry(c).leagues || [])[0];
            if (lg && lg.teams) lg.teams.forEach(t => pool.push({ ...t, countryCode: c }));
          }
        }
      }
      if (pool.length < 2) {
        alert('Test maçı için takım bulunamadı.');
        return;
      }
      const i = Math.floor(Math.random() * pool.length);
      let j = Math.floor(Math.random() * pool.length);
      while (j === i) j = Math.floor(Math.random() * pool.length);
      homeData = pool[i];
      awayData = pool[j];
    }

    // Maç ekranını preview'sız aç
    openMatchScreenV2({
      home: homeData,
      away: awayData,
      league: '🧪 Test Maçı',
      venue: (homeData.name || 'Test') + ' Stadyumu',
      hClass: 'c1',
      aClass: 'c2',
      skipPreview: true,
      kickoff: new Date()
    });

    // Hazırlık + test mode flag (lig tablosu/cache etkilenmez, fresh seed)
    if (typeof MS !== 'undefined') {
      MS._isFriendly = true;
      MS._testMode = true;
    }

    // Kısa delay sonra start (DOM ready olsun)
    setTimeout(() => {
      try { if (typeof startMatch === 'function') startMatch(); } catch(e) { console.warn('test startMatch:', e); }
    }, 250);
  } catch(e) {
    console.error('runQuickTestMatch hatası:', e);
    alert('Test maçı başlatılamadı: ' + e.message);
  }
}

