// ═══════════ STATS ═══════════
function initStats(){
  // 574 — Gece Mavisi: topa sahip olma halkası + gruplar (Genel · Pas · Savunma · Disiplin)
  const G = [
    ['Genel',    [['shots','Şut'],['shotsOnTarget','İsabetli Şut'],['corners','Korner'],['offsides','Ofsayt']]],
    ['Pas',      [['passes','Pas'],['passAcc','Pas İsabeti','%']]],
    ['Savunma',  [['tackles','Top Kapma'],['aerials','Hava Topu']]],
    ['Disiplin', [['fouls','Faul'],['yellowCards','Sarı Kart'],['redCards','Kırmızı Kart'],['injuries','Sakatlık']]]
  ];
  const hN = (typeof curHome !== 'undefined' && curHome && curHome.name) || '';
  const aN = (typeof curAway !== 'undefined' && curAway && curAway.name) || '';
  const C = 2 * Math.PI * 44;
  const satir = ([k, lbl, u]) => `
    <div class="eng-stat-row"><div class="gm-isr"><b class="sv-h" id="svh_${k}">0${u||''}</b><span class="sn">${lbl}</span><b class="sv-a" id="sva_${k}">0${u||''}</b></div>
      <div class="gm-cift"><div class="sb-inner"><div class="sb-fill-h" id="sbh_${k}" style="width:0%"></div></div><div class="sb-inner"><div class="sb-fill-a" id="sba_${k}" style="width:0%"></div></div></div></div>`;
  document.getElementById('statsContainer').innerHTML = `<div class="gm-ist">
    <div class="gm-ist-ust">
      <div class="gm-ist-tk"><i style="background:var(--kitH)"></i><span id="gmIstH" data-noi18n>${_escapeHtml(hN)}</span></div>
      <div class="gm-halka"><svg viewBox="0 0 112 112"><circle cx="56" cy="56" r="44" fill="none" stroke="var(--kitA)" stroke-width="12"/>
        <circle id="gmHalkaH" cx="56" cy="56" r="44" fill="none" stroke="var(--kitH)" stroke-width="12" stroke-dasharray="${(C/2).toFixed(1)} ${C.toFixed(1)}"/></svg>
        <div class="ic"><b id="gmHalkaT" data-noi18n>50–50</b><small>Topla Oynama</small></div></div>
      <div class="gm-ist-tk"><span id="gmIstA" data-noi18n>${_escapeHtml(aN)}</span><i style="background:var(--kitA)"></i></div>
    </div>
    ${G.map(([g, rows]) => `<div class="gm-ist-grup"><h4>${g}</h4>${rows.map(satir).join('')}</div>`).join('')}
  </div>`;
}

// 🆕 Match olaylarından (Edge Function events jsonb) istatistik objesi üretir.
// updateStats() formatına uyumlu: { possession:[h,a], shots:[h,a], ... }
// Edge Function (tick-matches) event tipleri:
//   goal, shotOff, save, corner, foul, foulDrawn, yellow, red, injury, offside,
//   duelLost, interception, keyPass, dribble, bigChanceMissed, throwin, penaltyMissed,
//   halftime, fulltime, sub, freekick
function _computeMatchStatsFromEvents(events, currentMinute) {
  if (!Array.isArray(events)) events = [];
  const s = {
    shots: [0, 0],
    shotsOnTarget: [0, 0],
    corners: [0, 0],
    fouls: [0, 0],
    passes: [0, 0],
    aerials: [0, 0],
    tackles: [0, 0],
    yellowCards: [0, 0],
    redCards: [0, 0],
    injuries: [0, 0],
    offsides: [0, 0]
  };
  // Hâkimiyet hesaplama için ham sayaçlar
  const actions = [0, 0]; // takım başına aksiyon sayısı (top'a ait olma süresi tahmini)
  
  for (const ev of events) {
    if (!ev) continue;
    const side = ev.team || ev.side;
    const i = side === 'home' ? 0 : (side === 'away' ? 1 : -1);
    if (i < 0) continue;
    const t = ev.type || '';
    
    // ── ŞUTLAR ──
    // Gol = isabetli şut
    if (t === 'goal') {
      s.shots[i]++;
      s.shotsOnTarget[i]++;
      actions[i]++;
    }
    // shotOff = direkt şut ama isabetsiz (auta gitti veya direkten döndü)
    else if (t === 'shotOff') {
      s.shots[i]++;
      actions[i]++;
    }
    // save → karşı takım isabetli şut atıp KALECI tarafından kurtarıldı
    else if (t === 'save') {
      const j = 1 - i; // şutu atan: i'nin karşıtı
      s.shots[j]++;
      s.shotsOnTarget[j]++;
      actions[j]++;
    }
    // Kaçan penaltı = şut (isabetsiz sayılır)
    else if (t === 'penaltyMissed') {
      s.shots[i]++;
      actions[i]++;
    }
    // Iptal edilmiş gol (varCancel/offsideGoal) — varsa, şut olarak say
    else if (t === 'offsideGoal' || t === 'varCancel') {
      s.shots[i]++;
      s.shotsOnTarget[i]++;
      actions[i]++;
    }
    // bigChanceMissed = pozisyon (şut sayılmaz aslında ama yakın)
    else if (t === 'bigChanceMissed') {
      actions[i]++;
    }
    
    // ── KORNER ──
    else if (t === 'corner') {
      s.corners[i]++;
      actions[i]++;
    }
    
    // ── FAUL ──
    else if (t === 'foul') {
      s.fouls[i]++;
    }
    
    // ── KARTLAR ──
    else if (t === 'yellow') s.yellowCards[i]++;
    else if (t === 'red') s.redCards[i]++;
    
    // ── SAKATLIK ──
    else if (t === 'injury') s.injuries[i]++;
    
    // ── OFSAYT ──
    else if (t === 'offside') s.offsides[i]++;
    
    // ── TOP KAPMA ──
    else if (t === 'interception') {
      s.tackles[i]++;
      actions[i]++;
    }
    
    // ── HÂKİMİYET KATKILARI ──
    else if (t === 'keyPass' || t === 'dribble' || t === 'throwin' || t === 'freekick' || t === 'foulDrawn') {
      actions[i]++;
    }
    // duelLost → bu takım topu kaybetti; karşı takıma aksiyon
    else if (t === 'duelLost') {
      const j = 1 - i;
      actions[j]++;
    }
  }
  
  // ── PAS — yaklaşık (motorda explicit pass event'i yok)
  // Aksiyon × 7 ≈ pas sayısı (her aksiyon ortalama ~7 pas gerektirir)
  s.passes[0] = actions[0] * 7;
  s.passes[1] = actions[1] * 7;
  // Pas isabeti — yaklaşık (her takımın hâkimiyetine göre %78-88 arası)
  const totalA = actions[0] + actions[1];
  if (totalA > 0) {
    const dom0 = actions[0] / totalA;
    s.passAcc = [
      Math.round(78 + dom0 * 12),
      Math.round(78 + (1 - dom0) * 12)
    ];
  } else {
    s.passAcc = [80, 80];
  }
  
  // ── HÂKİMİYET ──
  const possession = [50, 50];
  if (totalA > 0) {
    // 574 — her iki tarafa 6 aksiyonluk taban + 28–72 bandı (sunucu hesabıyla aynı mantık)
    const p0 = Math.round((actions[0] + 6) / (totalA + 12) * 100);
    possession[0] = Math.max(28, Math.min(72, p0));
    possession[1] = 100 - possession[0];
  }
  s.possession = possession;
  
  // ── HAVA TOPU ── (motorda explicit yok, ofsaytın yarısı + korner ile yaklaşık)
  s.aerials[0] = Math.round(s.corners[0] * 0.6);
  s.aerials[1] = Math.round(s.corners[1] * 0.6);
  
  return s;
}

function updateStats(stats,frac){
  const units={possession:'%',passAcc:'%'};
  Object.keys(stats).forEach(key=>{
    let h, a;
    if (key === 'possession' || key === 'passAcc') {
      // Yüzde değerleri frac ile çarpma — direkt gerçek değeri kullan
      h = stats[key][0];
      a = stats[key][1];
    } else {
      h = Math.round(stats[key][0] * frac);
      a = Math.round(stats[key][1] * frac);
    }
    const u=units[key]||'';
    const svh=document.getElementById('svh_'+key);
    const sva=document.getElementById('sva_'+key);
    const sbh=document.getElementById('sbh_'+key);
    const sba=document.getElementById('sba_'+key);
    if(svh)svh.textContent=h+u;
    if(sva)sva.textContent=a+u;
    const tot=h+a||1;
    if(sbh)sbh.style.width=(h/tot*100)+'%';
    if(sba)sba.style.width=(a/tot*100)+'%';
    // 574 — öndeki taraf vurgulu
    const hu = (h + a) > 0 && h >= a, au = (h + a) > 0 && a >= h;
    if (svh) svh.classList.toggle('us', hu); if (sbh) sbh.classList.toggle('us', hu);
    if (sva) sva.classList.toggle('us', au); if (sba) sba.classList.toggle('us', au);
  });
  // 574 — topa sahip olma halkası + takım adları
  try {
    if (stats && Array.isArray(stats.possession)) {
      const ph = Math.max(0, Math.min(100, Math.round(Number(stats.possession[0]) || 50)));
      const C = 2 * Math.PI * 44;
      const r = document.getElementById('gmHalkaH'); if (r) r.setAttribute('stroke-dasharray', (ph / 100 * C).toFixed(1) + ' ' + C.toFixed(1));
      const t = document.getElementById('gmHalkaT'); if (t) t.textContent = ph + '–' + (100 - ph);
    }
    const hI = document.getElementById('gmIstH'), aI = document.getElementById('gmIstA');
    if (hI && typeof curHome !== 'undefined' && curHome && hI.textContent !== curHome.name) hI.textContent = curHome.name || '';
    if (aI && typeof curAway !== 'undefined' && curAway && aI.textContent !== curAway.name) aI.textContent = curAway.name || '';
  } catch(e) {}
}

// ═══════════ LINEUP ═══════════
// 🆕 (511) TEK REYTİNG FORMÜLÜ — sunucudaki _calcMatchRating + _collectPlayerStats'in
//   BİREBİR kopyası (edge/tick-matches). Canlı KADRO sekmesi, maç sonu ekranı, sonuç
//   modalı ve haftanın yıldızı artık aynı sayıyı gösterir. Birini değiştirirsen diğerini de.
function _cscPg(p) {
  const M = { KL:'GK', GK:'GK', STB:'DEF', SB:'DEF', CB:'DEF', RB:'DEF', LB:'DEF', DEF:'DEF',
    DOS:'MID', OS:'MID', SAK:'MID', SOK:'MID', CAM:'MID', DM:'MID', CM:'MID', RM:'MID', LM:'MID', AM:'MID', MID:'MID',
    FWD:'FWD', RF:'FWD', LF:'FWD', ST:'FWD' };
  if (!p) return 'MID';
  const g = p.playedGroup || p.posGroup || p.pos_group;
  if (g && M[g]) return M[g];
  return M[p.pos] || 'MID';
}
function _cscOyuncuOlaylari(evs, isim) {
  const s = { goals:0, assists:0, keyPasses:0, ownGoals:0, yellows:0, reds:0, yellowMins:[], redMins:[],
    saves:0, greatSaves:0, tackles:0, blocks:0, clearances:0, interceptions:0, duelsWon:0, duelsLost:0,
    dribbles:0, missedPens:0, wonPens:0, missedBigChances:0, fouls:0, foulsDrawn:0, offsides:0, injuries:0, goalMins:[] };
  for (const ev of (evs || [])) {
    if (!ev || ev.cancelled) continue;
    const t = ev.type || '', min = (ev.min !== undefined) ? ev.min : (ev.minute || 0);
    if (t === 'goal') {
      if (ev.player === isim) { if (ev.isOwnGoal) s.ownGoals++; else { s.goals++; s.goalMins.push(min); } }
      if (ev.assist === isim) s.assists++;
      continue;
    }
    if (ev.player !== isim) continue;
    switch (t) {
      case 'keyPass': s.keyPasses++; break;
      case 'yellow': s.yellows++; s.yellowMins.push(min); break;
      case 'red': s.reds++; s.redMins.push(min); break;
      case 'save': s.saves++; if (ev.greatSave) s.greatSaves++; break;
      case 'tackle': s.tackles++; break;
      case 'block': s.blocks++; break;
      case 'clearance': s.clearances++; break;
      case 'interception': s.interceptions++; break;
      case 'duelWon': s.duelsWon++; break;
      case 'duelLost': s.duelsLost++; break;
      case 'dribble': s.dribbles++; break;
      case 'penaltyMissed': s.missedPens++; break;
      case 'penaltyWon': s.wonPens++; break;
      case 'bigChanceMissed': s.missedBigChances++; break;
      case 'foul': s.fouls++; break;
      case 'foulDrawn': s.foulsDrawn++; break;
      case 'offside': s.offsides++; break;
      case 'injury': s.injuries++; break;
    }
  }
  return s;
}
// 🆕 (511) TEK REYTİNG FORMÜLÜ — sunucudaki _calcMatchRating'in (edge/tick-matches) BİREBİR kopyası.
//   index.html'deki mevcut _cscMacReytingi() yerine konur; mevki grubu için mevcut _cscPg() kullanılır
//   (sunucudaki _pg ile aynı eşleme). _cscOyuncuOlaylari() değişmez. Birini değiştirirsen diğerini de.
// 🆕 (756) YENİDEN KALİBRASYON — 6 600 maçlık simülasyon (eşit/farklı güç, bot yolu, karışık kadrolar;
//   183 877 oyuncu-maç), üretimdeki akışla (_simKatilimcilar → _collectPlayerStats → bu fonksiyon):
//     ort 6.80 · sd 0.64 · 8.0+ %4.9 · 9.0+ %0.46 · 9.5+ %0.06 · 10.0 hiç (tavan 9.9, en yüksek görülen 9.8)
//     (örneklem dışı 1 760 taze maçta: 6.80 · 0.63 · %4.7 · %0.43 · %0.02 · 10.0 hiç)
//     mevki ortalaması GK 6.79 · DEF 6.81 · MID 6.80 · FWD 6.81 (≥60 dk: 6.80 / 6.87 / 6.83 / 6.93)
//     maçın adamı payı GK %11 · DEF %23 · MID %31 · FWD %35 (eski formül: 9 / 22 / 43 / 26)
//     çapalar: forvet hat-trick + galibiyet ≈ 9.3 · iki gol ≈ 8.8 · tek gol ≈ 7.9–8.0 · kaleci gol yemeden
//     5 kurtarış + galibiyet ≈ 8.2 · 6 kurtarış (2 büyük) ≈ 8.8 · baskın stoper (20 savunma olayı, gol yemeden) ≈ 8.0
//   Yöntem: motorun bol ürettiği savunma/çalım/pas olayları mevkinin 90 dk beklentisine göre MERKEZLENİR
//   (ortalama oyuncu ±0 alır, sapma ödüllenir); taban mevkiye göre ayarlıdır → mevkiler arası ortalama eşit.
//   Forvetin golsüz maçı düşük, golü değerli; orta saha/defansın tabanı yüksek, golü biraz daha az değerli
//   → tek gollü galibiyette forvet ve orta saha ≈ 7.9, gol + gol yememe ile defans ≈ 8.4.
//   8.4 üstü yumuşak sıkıştırılır (9.9'a asimptotik) → çok gol azalan getirir, 10.0 çıkamaz.
function _cscMacReytingi(player, s, teamWon, teamDraw, teamConceded, minutesPlayed) {
  if (!player) return 6.0;
  s = s || {};
  const g = _cscPg(player);
  const isGK = g === 'GK', isDef = g === 'DEF', isMid = g === 'MID', isFwd = g === 'FWD';
  const pm = Math.max(1, Math.min(90, minutesPlayed || 90));
  const f90 = pm / 90;
  const gc = Math.max(0, (teamConceded || 0) | 0);
  // Mevki beklentileri (90 dk başına, simülasyon ortalaması): anahtar pas, çalım, faul kazanma, ikili kayıp
  const eKp = isDef ? 0.38 : (isMid ? 0.94 : (isFwd ? 0.71 : 0));
  const eDr = isDef ? 1.27 : (isMid ? 1.89 : (isFwd ? 1.88 : 0));
  const eFd = isMid ? 0.46 : (isFwd ? 0.47 : 0);
  const eDl = isDef ? 2.17 : (isMid ? 3.07 : (isFwd ? 3.11 : 0));

  // 1) Oyun katkısı (mevki tabanı + beklentiye göre merkezli hacim istatistikleri)
  let a = isGK ? 6.25 : (isDef ? 6.91 : (isMid ? 6.76 : 6.55));
  a += (isGK ? 0 : (isFwd ? 0.14 : 0.08)) * ((s.keyPasses || 0) - eKp * f90);
  a += (isGK ? 0 : (isFwd ? 0.10 : 0.04)) * ((s.dribbles || 0) - eDr * f90);
  a += 0.03 * ((s.foulsDrawn || 0) - eFd * f90);
  if (isDef || isMid) {
    // Savunma olayları: motor maç başı defansa ~11.6, orta sahaya ~6.6 üretir → beklentiden sapma ödüllenir
    const d = (s.tackles || 0) + (s.interceptions || 0) + 1.2 * (s.blocks || 0) + 0.6 * (s.clearances || 0) + 0.8 * (s.duelsWon || 0);
    a += (isDef ? 0.05 : 0.035) * (d - (isDef ? 11.6 : 6.6) * f90);
  } else if (isFwd) {
    a += 0.05 * ((s.tackles || 0) + (s.interceptions || 0) + (s.blocks || 0) + (s.clearances || 0)) + 0.04 * (s.duelsWon || 0);
  }
  a -= 0.04 * ((s.duelsLost || 0) - eDl * f90);
  // 2) Kaleci: kurtarış + yenen gol
  if (isGK) {
    a += 0.18 * (s.saves || 0) + 0.25 * (s.greatSaves || 0);   // büyük kurtarış yalnız kaleci diving ≥ 75 iken çıkar → küçük ek
    if (gc === 0) a += 0.70;
    else if (gc === 1) a += 0.13;
    else if (gc === 2) a -= 0.19;
    else if (gc === 3) a -= 0.60;
    else a -= 0.90 + 0.25 * (gc - 4);
  } else if (isDef) {
    // 3) Defans: gol yememe / çok gol yeme
    if (gc === 0) a += 0.34;
    else if (gc === 2) a -= 0.17;
    else if (gc >= 3) a -= 0.45 + 0.10 * (gc - 3);
  } else if (isMid) {
    if (gc === 0) a += 0.05;
    else if (gc >= 3) a -= 0.10;
  }
  // 4) Kaçan büyük fırsat, ofsayt, faul, kazanılan penaltı
  a -= 0.15 * (s.missedBigChances || 0) + 0.03 * (s.offsides || 0) + 0.04 * (s.fouls || 0);
  a += 0.30 * (s.wonPens || 0);
  // 5) Maç sonucu
  a += (teamWon === true) ? 0.30 : (teamDraw ? 0.05 : -0.31);

  // 6) Gol / asist — azalan getiri (her ek gol ×0.89, her ek asist ×0.90); 80+ dk golü +0.15
  const gv = isFwd ? 1.09 : (isMid ? 0.82 : 0.89);
  let b = 0;
  for (let i = 0; i < (s.goals || 0); i++) b += gv * Math.pow(0.89, i);
  for (const mn of (s.goalMins || [])) if (mn >= 80) b += 0.15;
  for (let i = 0; i < (s.assists || 0); i++) b += 0.68 * Math.pow(0.90, i);

  // 7) Oynanan süre: az veri → 6.5'e çekilir (0–60 dk doğrusal 0.2→1.0; eski formüldeki 30. dk sıçraması yok).
  //    Gol/asist daha az çekilir (yedekten girip gol atan belirgin ödül alır).
  const k = Math.min(1, 0.2 + 0.8 * pm / 60);
  let r = 6.5 + (a - 6.5) * k + b * (0.5 + 0.5 * k);

  // 8) Disiplin ve hatalar — süreden bağımsız, tam uygulanır (erken kırmızı kısa süreyle sulanmaz)
  for (const mn of (s.yellowMins || [])) r -= mn < 30 ? 0.35 : (mn < 60 ? 0.25 : 0.20);
  for (const mn of (s.redMins || [])) r -= mn < 30 ? 1.50 : (mn < 60 ? 1.30 : 1.00);
  r -= (s.ownGoals || 0) * 1.00;
  r -= (s.missedPens || 0) * 0.80;

  // 9) Deterministik küçük varyasyon (oyuncu adından — random DEĞİL, her yerde aynı) ±0.10
  let h = 2166136261;
  const seed = (player.name || '') + '|' + (s.goals || 0) + (s.saves || 0) + (s.tackles || 0);
  for (let i = 0; i < seed.length; i++) { h ^= seed.charCodeAt(i); h = Math.imul(h, 16777619); }
  r += (((h >>> 0) % 1000) / 1000 - 0.5) * 0.20;

  // 10) 8.4 üstü yumuşak sıkıştırma (9.9'a asimptotik) + sınırlar
  if (r > 8.4) r = 8.4 + 1.5 * (1 - Math.exp(-(r - 8.4) / 1.5));
  return Math.max(3.0, Math.min(9.9, Math.round(r * 10) / 10));
}

// 🆕 Maç sürerken her oyuncuya anlık stats ekle (matchRating, matchGoals, matchAssists)
//    KADRO sekmesinde canlı reyting göstermek için renderLineup öncesi çağrılır
//    (511) Sunucu formülüyle — maç sonunda sunucunun yazdığı değerle aynı sonuca varır.
function _attachLivePlayerStats() {
  if (typeof MS === 'undefined' || !MS || !MS.script || !MS.script.evs) return;
  if (!curHome || !curAway || !curHome.players || !curAway.players) return;

  const evs = MS.script.evs;
  const minNow = Math.max(0, Math.min(90, Math.floor(MS._displayMin || MS.minute || 0)));

  // Giriş/çıkış dakikaları olaylardan (değişiklik, kırmızı, sakatlık)
  const giris = { home:{}, away:{} }, cikis = { home:{}, away:{} };
  evs.forEach(ev => {
    if (!ev || !ev.team || !giris[ev.team]) return;
    const mn = typeof ev.min === 'number' ? ev.min : 0;
    if (ev.type === 'sub') {
      if (ev.player) giris[ev.team][ev.player] = mn;
      if (ev.playerOut && cikis[ev.team][ev.playerOut] == null) cikis[ev.team][ev.playerOut] = mn;
    } else if ((ev.type === 'red' || ev.type === 'injury') && ev.player && cikis[ev.team][ev.player] == null) {
      cikis[ev.team][ev.player] = mn;
    }
  });

  [curHome, curAway].forEach((team, ti) => {
    const side   = ti === 0 ? 'home' : 'away';
    const ours   = ti === 0 ? (MS.scoreH || 0) : (MS.scoreA || 0);
    const theirs = ti === 0 ? (MS.scoreA || 0) : (MS.scoreH || 0);
    const takimEvs = evs.filter(ev => ev && ev.team === side);
    const hesapla = (p, girdi) => {
      const g = girdi ? (giris[side][p.name] || 0) : 0;
      const c = (cikis[side][p.name] != null) ? cikis[side][p.name] : minNow;
      const s = _cscOyuncuOlaylari(takimEvs, p.name);
      p.matchRating  = _cscMacReytingi(p, s, ours > theirs, ours === theirs, theirs, Math.max(1, c - g));
      p.matchGoals   = s.goals;
      p.matchAssists = s.assists;
      p.yellowCards  = s.yellows;
      p.redCard      = s.reds > 0;
      p.sentOff      = s.reds > 0;
      p.matchInjured = s.injuries > 0;
    };
    team.players.forEach(p => { if (p && p.name) hesapla(p, giris[side][p.name] != null); });
    // Yedekler — SADECE sahaya çıkanlara reyting; girmeyenler "-" görünür
    const bench = Array.isArray(team.benchPlayers) ? team.benchPlayers : [];
    bench.forEach(p => {
      if (!p || !p.name) return;
      if (giris[side][p.name] == null) { p.matchRating = null; p.matchGoals = 0; p.matchAssists = 0; return; }
      hesapla(p, true);
    });
  });
}

function renderLineup(){
  // 🆕 Maç sürerken canlı stats güncelle
  if (typeof MS !== 'undefined' && MS && MS.running && !MS.finished) {
    _attachLivePlayerStats();
  }

  // 🆕 ORIJINAL İLK 11 SNAPSHOT (ilk çağrıda dondur)
  // Sub yapıldıktan sonra bile orijinal ilk 11 listede kalır.
  // Çıkanlar [↓ ÇIKTI] badge ile burada görünür; girenler sadece yedekler kısmında [↑ GİRDİ] ile.
  if (typeof MS !== 'undefined' && MS && !MS._originalStarters) {
    MS._originalStarters = {
      home: (curHome && Array.isArray(curHome.players))
        ? curHome.players.map(p => ({ ...p })) : [],
      away: (curAway && Array.isArray(curAway.players))
        ? curAway.players.map(p => ({ ...p })) : []
    };
  }

  const ratColor=r=>r>=80?'#ef5350':r>=75?'var(--gold)':'var(--text2)';
  // 🆕 Maç reytingi rengi (1-10 skalası, WhoScored mantığı)
  const matchRatColor = r => {
    if (r == null) return 'var(--text3)';
    if (r >= 8.5) return '#00e676';   // mükemmel
    if (r >= 7.5) return '#76ff03';   // çok iyi
    if (r >= 6.8) return '#ffd54f';   // iyi
    if (r >= 6.0) return '#ff9800';   // ortalama
    return '#ef5350';                  // zayıf
  };
  // 🆕 Başlıkları gerçek takım isimleriyle güncelle
  const hHdr = document.getElementById('luHomeHdr');
  const aHdr = document.getElementById('luAwayHdr');
  if (hHdr) hHdr.innerHTML = `<span data-noi18n>${_escapeHtml((curHome && curHome.name) || '')}</span>`;
  if (aHdr) aHdr.innerHTML = `<span data-noi18n>${_escapeHtml((curAway && curAway.name) || '')}</span>`;

  // ═══ YEDEK GİRİŞ/ÇIKIŞ İŞARETLERİ (kullanıcı isteği) ═══
  // MS.subsHistory: [{ in: 'Yeni', out: 'Eski', min: 65 }, ...]
  // Map kullan: name → dakika (badge'de göstereceğiz)
  const subsInMin = new Map();   // yedek olarak girip oyuna dahil olanlar → dakika
  const subsOutMin = new Map();  // ilk 11'den çıkanlar → dakika
  if (typeof MS !== 'undefined' && MS && Array.isArray(MS.subsHistory)) {
    MS.subsHistory.forEach(s => {
      if (s && s.in)  subsInMin.set(s.in, s.min);
      if (s && s.out) subsOutMin.set(s.out, s.min);
    });
  }
  // Set sürümleri (eski kontroller için)
  const subsIn = new Set(subsInMin.keys());
  const subsOut = new Set(subsOutMin.keys());

  // 🆕 Bir oyuncu için satır üret — maç reytingi varsa rozetle göster
  //    options: { isBench: true → yedek (opacity düşük), isExited: true → çıkan oyuncu snapshot }
  const _row = (p, opts) => {
    opts = opts || {};
    const baseRating = p.rating || p.overall || 70;
    const mr = (typeof p.matchRating === 'number') ? p.matchRating : null;
    const mrTxt = mr != null ? mr.toFixed(1) : '';
    // 🆕 mr null ise tire göster (oyuna hiç girmeyen yedekler)
    const mrChip = mr != null
      ? `<div class="lu-mr" style="background:${matchRatColor(mr)};color:#000">${mrTxt}</div>`
      : `<div class="lu-mr" style="background:rgba(120,160,255,.08);color:rgba(180,200,240,.5);font-weight:700">—</div>`;
    // 🆕 Gol/asist göstergesi aşağıda gaBadge olarak status hücresine yerleştirilir
    // Giriş/çıkış işareti — sade arrow + dakika (kullanıcı isteği)
    // OUT: ↓ + dakika (kırmızı)
    // IN: ↑ + dakika (yeşil)
    // 🆕 Badge'ler artık ayrı status hücresinde — margin-left kaldırıldı (status container gap kullanıyor)
    const badgeStyle = 'display:inline-flex;align-items:center;gap:1px;font-size:10px;font-weight:800;'
                     + 'padding:2px 5px;border-radius:8px;line-height:1';
    // outSnapshot için snapshot.team değerine dakika bakmak gerek — burda outMark'ı tetikleyen
    // isExited ise snapshot zaten subsOutMin'de olmalı (snapshot.name aynı orig.name)
    const outMin = subsOutMin.get(p.name);
    const showOutMark = subsOut.has(p.name);
    const outMark = showOutMark
      ? `<span style="${badgeStyle};background:#ef5350;color:#fff;box-shadow:0 0 5px rgba(239,83,80,.4)" title="Oyundan çıktı (${outMin}')">↓ ${outMin}'</span>`
      : '';
    const inMin = subsInMin.get(p.name);
    const inMark = (opts.isBench && subsIn.has(p.name))
      ? `<span style="${badgeStyle};background:#00e676;color:#000;box-shadow:0 0 5px rgba(0,230,118,.4)" title="Oyuna girdi (${inMin}')">↑ ${inMin}'</span>`
      : '';

    // 🆕 KART İŞARETLERİ (sarı/kırmızı) — kullanıcı isteği
    //    Motor: p.yellowCards (0-2), p.redCard (bool), p.sentOff (bool)
    //    Live obj'den alınır; sub edilen snapshot'lar son durumu saklar.
    const yellowCnt = (p.yellowCards != null) ? p.yellowCards :
                      (p.matchStatsLive && p.matchStatsLive.yellowCards) || 0;
    const hasRed = !!(p.redCard || p.sentOff);
    let cardMark = '';
    if (hasRed) {
      // 🆕 Kırmızı kart emoji oyuncu satırı solduğunda bile PARLAK kalır (opacity bypass)
      cardMark = `<span style="display:inline-block;width:9px;height:13px;background:#ef5350;border-radius:1.5px;box-shadow:0 0 6px rgba(239,83,80,.8);opacity:1 !important;filter:none !important" title="Kırmızı kart — atıldı"></span>`;
    } else if (yellowCnt >= 1) {
      // 1 sarı görünür — 2. sarı kırmızıya dönüşmüş olur
      cardMark = `<span style="display:inline-block;width:9px;height:13px;background:#ffd600;border-radius:1.5px;box-shadow:0 0 4px rgba(255,214,0,.5);opacity:1 !important;filter:none !important" title="Sarı kart"></span>`;
    }

    // Görsel stiller — opacity KULLANMA (parent opacity child'ı da soldurur, kart emoji görünmez kalır)
    // Bunun yerine sadece text rengini soldur, kart işaretleri kendi rengini korur
    const isBenchPlayed = opts.isBench && subsIn.has(p.name);
    let rowStyle = '';
    if (hasRed) {
      // 🆕 Kırmızı kart - text griye dönsün ama kart işareti parlak kalsın
      rowStyle = 'color:rgba(180,180,180,.5);text-decoration:line-through;text-decoration-color:rgba(239,83,80,.6)';
    } else if (opts.isExited) {
      rowStyle = 'color:rgba(180,180,180,.7)';
    } else if (opts.isBench && !isBenchPlayed) {
      rowStyle = 'color:rgba(220,220,220,.75)';
    }
    // 🆕 ga (gol/asist/sakatlık) badge — status hücresinde, margin'siz
    const g = p.matchGoals || 0;
    const a = p.matchAssists || 0;
    const inj = !!p.matchInjured;
    const gaBadge = (g + a > 0 || inj)
      ? `<span class="lu-ga" style="margin-left:0">${g > 0 ? '⚽'.repeat(Math.min(g, 3)) : ''}${a > 0 ? '🅰️'.repeat(Math.min(a, 3)) : ''}${inj ? '🚑' : ''}</span>`
      : '';

    return `
      <div class="lu-pl" style="${rowStyle}">
        <div class="lu-n">${p.num || '—'}</div>
        <div class="lu-nm">${p.name||''}${p.isUser?' ⭐':''}</div>
        <div class="lu-status">${cardMark}${outMark}${inMark}${gaBadge}</div>
        <div class="lu-pos" data-noi18n>${subPosOf(p)}</div>
        <div class="lu-rt" style="color:${ratColor(baseRating)}">${baseRating}</div>
        ${mrChip}
      </div>`;
  };

  // Yedek ayraç başlığı
  const _benchHdr = () => `
    <div style="margin-top:10px;padding:6px 0 4px;border-top:1px solid rgba(120,160,255,.2);
                font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;font-size:10px;font-weight:800;
                color:rgba(180,200,240,.6);text-transform:uppercase;letter-spacing:1.5px;
                display:flex;align-items:center;gap:6px">
      <span>🪑 Yedekler</span>
      <span style="flex:1;height:1px;background:rgba(120,160,255,.12)"></span>
    </div>`;

  // İlk 11 + yedekler (giren yedekler [↑ GİRDİ] badge ile yedekler kısmında, ÇIKAN ise ilk 11'de [↓ ÇIKTI] ile)

  // 🆕 ORIJINAL ilk 11'i kullan (sub yapıldıktan sonra bile değişmez)
  //    Çıkan oyuncular doğal olarak burada kalır → subsOut.has(p.name) → [↓ ÇIKTI] badge
  const homeStarters = (MS && MS._originalStarters && Array.isArray(MS._originalStarters.home) && MS._originalStarters.home.length)
    ? MS._originalStarters.home
    : (curHome.players || []);
  const awayStarters = (MS && MS._originalStarters && Array.isArray(MS._originalStarters.away) && MS._originalStarters.away.length)
    ? MS._originalStarters.away
    : (curAway.players || []);

  // 🆕 Display player resolver: çıktıysa snapshot, sahadaysa canlı player obj (matchRating'li)
  //    Bu sayede ÇIKAN oyuncuda son durum (gol/asist/rating) dondurulur,
  //    SAHADAKI oyuncuda anlık reyting yansır.
  const _resolveDisplay = (origP, teamId) => {
    // Çıkmış mı?
    if (Array.isArray(MS.subsHistory)) {
      const subRec = MS.subsHistory.find(s =>
        s && s.outSnapshot && s.outSnapshot.team === teamId && s.outSnapshot.name === origP.name
      );
      if (subRec) return subRec.outSnapshot;
    }
    // Sahada mı? curHome/curAway.players içindeki canlı obj'i al (matchRating güncel)
    const teamArr = teamId === 'home' ? (curHome.players || []) : (curAway.players || []);
    const live = teamArr.find(x => x && x.name === origP.name);
    return live || origP;
  };

  // 🆕 YEDEKLERIN ŞAMPIYONLARI:
  // - Hiç oyuna girmemiş yedekler (rating: "—")
  // - Sahaya giren yedekler ([↑ GİRDİ] badge, canlı rating)

  // benchPlayers (snapshot — sub'tan etkilenmez ki yedekte gözüksün)
  // 🆕 ORIJINAL BENCH SNAPSHOT (ilk çağrıda dondur — sub değişiklikleri yansıtma)
  if (typeof MS !== 'undefined' && MS && !MS._originalBench) {
    let _hb = (curHome && Array.isArray(curHome.benchPlayers)) ? curHome.benchPlayers.slice() : [];
    let _ab = (curAway && Array.isArray(curAway.benchPlayers)) ? curAway.benchPlayers.slice() : [];
    // FALLBACK: benchPlayers boşsa global benchPlayers veya rosterFallback
    if (_hb.length === 0 && curHome) {
      try {
        const isUserHomeT = !!(typeof _userTeam !== 'undefined' && _userTeam && curHome.name === _userTeam.teamName)
                         || !!(MS && MS._testForceCaptain)
                         || !!(curHome.players && curHome.players.some(p => p && p.isUser));
        if (isUserHomeT && typeof benchPlayers !== 'undefined' && Array.isArray(benchPlayers)) {
          _hb = benchPlayers.filter(b => b && b.name).slice(0, 7);
        } else if (typeof getOrCreateTeamRoster === 'function') {
          const fullRoster = getOrCreateTeamRoster(curHome) || [];
          const startersNames = new Set(curHome.players.map(p => p.name));
          _hb = fullRoster.filter(p => p && !startersNames.has(p.name)).slice(0, 7);
        }
      } catch(e) {}
    }
    if (_ab.length === 0 && curAway) {
      try {
        const isUserAwayT = !!(typeof _userTeam !== 'undefined' && _userTeam && curAway.name === _userTeam.teamName)
                         || !!(curAway.players && curAway.players.some(p => p && p.isUser));
        if (isUserAwayT && typeof benchPlayers !== 'undefined' && Array.isArray(benchPlayers)) {
          _ab = benchPlayers.filter(b => b && b.name).slice(0, 7);
        } else if (typeof getOrCreateTeamRoster === 'function') {
          const fullRoster = getOrCreateTeamRoster(curAway) || [];
          const startersNames = new Set(curAway.players.map(p => p.name));
          _ab = fullRoster.filter(p => p && !startersNames.has(p.name)).slice(0, 7);
        }
      } catch(e) {}
    }
    MS._originalBench = {
      home: _hb.map(p => ({ ...p })),
      away: _ab.map(p => ({ ...p }))
    };
  }

  const homeBench = (MS && MS._originalBench && Array.isArray(MS._originalBench.home)) ? MS._originalBench.home : [];
  const awayBench = (MS && MS._originalBench && Array.isArray(MS._originalBench.away)) ? MS._originalBench.away : [];

  // Yedek için display: girdiyse curHome.players içinden canlı obj'i al (matchRating güncel)
  const _resolveBenchDisplay = (benchP, teamId) => {
    if (subsIn.has(benchP.name)) {
      const teamArr = teamId === 'home' ? (curHome.players || []) : (curAway.players || []);
      const live = teamArr.find(x => x && x.name === benchP.name);
      if (live) return live;
    }
    return benchP;
  };

  // Render et — ilk 11 (orijinal, çıkanlar [↓ ÇIKTI] badge'li dahil) + yedekler (girenler [↑ GİRDİ] badge'li)
  const homeStartersHTML = homeStarters.map(orig => _row(_resolveDisplay(orig, 'home'))).join('');
  const awayStartersHTML = awayStarters.map(orig => _row(_resolveDisplay(orig, 'away'))).join('');
  const homeBenchHTML = homeBench.length > 0
    ? _benchHdr() + homeBench.map(b => _row(_resolveBenchDisplay(b, 'home'), { isBench: true })).join('')
    : '';
  const awayBenchHTML = awayBench.length > 0
    ? _benchHdr() + awayBench.map(b => _row(_resolveBenchDisplay(b, 'away'), { isBench: true })).join('')
    : '';

  document.getElementById('luHome').innerHTML = homeStartersHTML + homeBenchHTML;
  document.getElementById('luAway').innerHTML = awayStartersHTML + awayBenchHTML;
  try { if (typeof _gmKadroSahaCiz === 'function') _gmKadroSahaCiz(); } catch(e) {}   // 574 — iki takım tek sahada
}

// ═══════════ EVENT/COMMENTARY RENDERING ═══════════
const EV_MAP={
  goal:{icon:'⚽',cls:'ev-goal'},yellow:{icon:'🟨',cls:'ev-yellow'},red:{icon:'🟥',cls:'ev-red'},
  sub:{icon:'',cls:'ev-sub-ev'},chance:{icon:'💥',cls:'ev-chance'},save:{icon:'🧤',cls:'ev-save'},
  // 🆕 Zenginleştirilen olay tipleri
  shotOff:{icon:'🎯',cls:''},corner:{icon:'🚩',cls:''},foul:{icon:'⚠️',cls:''},
  freekick:{icon:'🆓',cls:''},offside:{icon:'🚩',cls:''},throwin:{icon:'👐',cls:''}
};

// 🆕 Önemli olaylarda skorbord altı şerit animasyonu (sağdan kayar gelir, ortada durur, sola çıkar)
//   Tipler: 'goal','offside','yellow','red','penalty','penaltyMissed','varCancel','corner','foul'
function showEventBanner(type, player, detail) {
  const config = {
    goal:          { word:'GOL!',           icon:'⚽' },
    offside:       { word:'OFSAYT!',         icon:'🚩' },
    yellow:        { word:'SARI KART',       icon:'🟨' },
    red:           { word:'KIRMIZI KART!',   icon:'🟥' },
    penalty:       { word:'PENALTI!',        icon:'🎯' },
    penaltyMissed: { word:'PENALTI KAÇTI!',  icon:'❌' },
    varCancel:     { word:'VAR İPTALİ!',     icon:'📺' },
    corner:        { word:'KORNER',          icon:'🚩' },
    foul:          { word:'FAUL',            icon:'⚠️' }
  }[type];
  if (!config) return;
  if (type === 'goal') return;   // 🆕 gol şeridi yok

  const strip = document.getElementById('msEventStrip');
  if (!strip) return;
  const ic = document.getElementById('mesIcon');
  const wd = document.getElementById('mesWord');
  const dt = document.getElementById('mesDetail');

  if (ic) ic.textContent = config.icon;
  if (wd) wd.textContent = config.word;
  if (dt) {
    let detailText = '';
    if (player && detail) detailText = `${player} · ${detail}`;
    else if (player) detailText = player;
    else if (detail) detailText = detail;
    dt.textContent = detailText;
    dt.style.display = detailText ? '' : 'none';
  }

  strip.dataset.type = type;
  // Önceki animasyonları sıfırla
  strip.classList.remove('show-in', 'show-out');
  void strip.offsetWidth; // force reflow
  strip.classList.add('show-in');

  // 1.5 saniye dur, sonra sola çık
  if (window._evtBannerTimer)  clearTimeout(window._evtBannerTimer);
  if (window._evtBannerTimer2) clearTimeout(window._evtBannerTimer2);
  window._evtBannerTimer = setTimeout(() => {
    strip.classList.remove('show-in');
    strip.classList.add('show-out');
    window._evtBannerTimer2 = setTimeout(() => {
      strip.classList.remove('show-out');
    }, 420);
  }, 1500);
}

