// Cümleyi seç + parametreleri doldur
function liveTemplate(key, params = {}) {
  const arr = LIVE_TEMPLATES[key];
  if (!Array.isArray(arr) || arr.length === 0) return '';
  let tpl = arr[Math.floor(Math.random() * arr.length)];
  for (const k in params) {
    tpl = tpl.split('{' + k + '}').join(params[k] || '');
  }
  return tpl;
}

// 🆕 Live header güncelleyici — dakika + atak baskısı
function updateLiveHeader(minute, status, attackHome, attackAway) {
  try {
    const minEl = document.getElementById('liveMinDisplay');
    const stEl = document.getElementById('liveStatusText');
    const ahEl = document.getElementById('liveAttackH');
    const aaEl = document.getElementById('liveAttackA');
    if (minEl && typeof minute === 'number') minEl.textContent = minute + "'";
    if (stEl && status) stEl.textContent = status;
    if (ahEl && typeof attackHome === 'number') ahEl.style.width = Math.max(5, Math.min(95, attackHome)) + '%';
    if (aaEl && typeof attackAway === 'number') aaEl.style.width = Math.max(5, Math.min(95, attackAway)) + '%';
  } catch(e) {}
}

// 🆕 Gol flash overlay
function triggerGoalFlash() {
  try {
    const old = document.querySelector('.goal-flash');
    if (old) old.remove();
    const f = document.createElement('div');
    f.className = 'goal-flash';
    document.body.appendChild(f);
    setTimeout(() => { try { f.remove(); } catch(e) {} }, 1100);
  } catch(e) {}
}

function addEvent(ev){
  // 🆕 Arka plan event'leri (rating motoru için) — UI'da gösterme
  const HIDDEN_EVENT_TYPES = new Set([
    'tackle', 'interception', 'block', 'clearance',
    'duelWon', 'duelLost', 'dribble',
    'keyPass', 'bigChanceMissed', 'foulDrawn'
  ]);
  if (ev && HIDDEN_EVENT_TYPES.has(ev.type)) return;

  const list = document.getElementById('evList');
  if (!list) return;
  // İlk event eklenirken placeholder'ı temizle
  if (list.querySelector('div[style*="text-align:center"]')) list.innerHTML = '';

  const min = Math.floor(ev.min || 0);
  const team = ev.team === 'home' ? curHome : curAway;
  const teamShort = team ? (team.short || '—') : '—';
  const col = ev.team === 'home' ? 'var(--accent2)' : '#ef5350';
  let icon, title, sub = '';
  let cls = '';

  switch(ev.type) {
    case 'goal':
      // Faz 3: gol alt-tipi
      const subIcon = ev.subtypeIcon || '';
      const subLabel = ev.subtypeLabel || '';
      icon = ev.isOwnGoal ? '😱' : (ev.isPenalty ? '🎯' : (subIcon || '⚽'));
      title = ev.isOwnGoal
        ? `<span style="color:${col}">KENDİ KALESİNE!</span> ${ev.player} <span style="color:var(--text3);font-size:11px">(${teamShort})</span>`
        : (ev.isPenalty
            ? `<span style="color:${col}">PENALTI GOLÜ!</span> ${ev.player} <span style="color:var(--text3);font-size:11px">(${teamShort})</span>`
            : (subLabel
                ? `<span style="color:${col}">${subLabel.toUpperCase()}!</span> ${ev.player} <span style="color:var(--text3);font-size:11px">(${teamShort})</span>`
                : `<span style="color:${col}">GOL!</span> ${ev.player} <span style="color:var(--text3);font-size:11px">(${teamShort})</span>`));
      // 🆕 Türkçe yorum cümlesi — alt tipe göre template
      const goalTplKey = ev.isOwnGoal ? 'goal_owngoal'
        : ev.isPenalty ? 'goal_penalty'
        : ev.subtype === 'longShot' ? 'goal_longshot'
        : ev.subtype === 'headerGoal' ? 'goal_header'
        : ev.subtype === 'freekickGoal' ? 'goal_freekick'
        : ev.subtype === 'cornerGoal' ? 'goal_corner'
        : 'goal_normal';
      const goalLine = liveTemplate(goalTplKey, { player: ev.player });
      sub = goalLine;
      if (ev.assist) sub += `<br><span style="opacity:.7">Asist: ${ev.assist}</span>`;
      cls = 'ev-goal';
      // 🆕 Gol flash
      try { triggerGoalFlash(); } catch(e) {}
      break;
    case 'offsideGoal':
      icon = '🚩';
      title = `<span style="color:#ffa726">OFSAYT İPTALİ!</span> ${ev.player} <span style="color:${col};font-size:11px">(${teamShort})</span>`;
      sub = 'Hakem bayrak kaldırdı';
      cls = 'ev-pen-miss';
      break;
    case 'yellow':
      icon = '🟨';
      title = `${ev.player} <span style="color:${col};font-size:11px">(${teamShort})</span> sarı kart`;
      sub = liveTemplate('yellow_card', { player: ev.player });
      cls = 'ev-yellow';
      break;
    case 'red':
      icon = '🟥';
      title = `<span style="color:#ef5350">KIRMIZI KART!</span> ${ev.player} <span style="color:${col};font-size:11px">(${teamShort})</span>`;
      sub = liveTemplate('red_card', { player: ev.player });
      cls = 'ev-red';
      break;
    case 'injury':
      icon = '🤕';
      // Faz 3: sakatlık tipi varsa detay göster
      if (ev.severity && ev.severityLabel && ev.bodyPart) {
        const sevColor = ev.severity === 'minor' ? '#ffd54f' :
                         ev.severity === 'moderate' ? '#ff9800' :
                         ev.severity === 'severe' ? '#ef5350' : '#b71c1c';
        title = `<span style="color:${sevColor}">${ev.severityLabel.toUpperCase()} SAKATLIK!</span> ${ev.player} <span style="color:${col};font-size:11px">(${teamShort})</span>`;
        sub = (ev.hoursOut != null)
          ? `${ev.bodyPart} sakatlığı · ${_sureSaatDk(ev.hoursOut)} sahalardan uzak`
          : `${ev.bodyPart} sakatlığı · ~${ev.matchesOut} maç dışında`;
      } else {
        title = `${ev.player} <span style="color:${col};font-size:11px">(${teamShort})</span> sakatlandı`;
      }
      break;
    case 'varCancel':
      icon = '📺';
      title = `<span style="color:#ffa726">VAR İPTALİ!</span> Gol VAR ile geri alındı`;
      sub = ev.text || '';
      cls = 'ev-pen-miss';
      break;
    case 'penaltyMissed':
      icon = '❌';
      title = `<span style="color:#ffa726">PENALTI KAÇTI!</span> ${ev.player} <span style="color:${col};font-size:11px">(${teamShort})</span>`;
      cls = 'ev-pen-miss';
      break;
    case 'chance':
      icon = '🎯';
      title = `${ev.player} <span style="color:${col};font-size:11px">(${teamShort})</span> şans yakaladı`;
      break;
    case 'save':
      icon = '🧤';
      title = `<span style="color:${col}">${ev.player}</span> <span style="color:var(--text3);font-size:11px">(${teamShort})</span> kurtardı`;
      if (ev.shooter) sub = `${ev.shooter} şutunu çevirdi`;
      break;
    // 🆕 Yeni olay tipleri
    case 'shotOff':
      icon = '🎯';
      const variantLabel = ev.variant === 'wide'    ? 'yan dışına gönderdi'
                         : ev.variant === 'over'    ? 'üstten gönderdi'
                         : ev.variant === 'blocked' ? 'şutu blokladı'
                         : 'şutu hedefi bulmadı';
      title = `<span style="color:${col}">${ev.player}</span> <span style="color:var(--text3);font-size:11px">(${teamShort})</span> ${variantLabel}`;
      cls = 'ev-shot-off';
      break;
    case 'corner':
      icon = '🚩';
      title = `<span style="color:${col}">${teamShort}</span> köşe vuruşu · <span style="color:var(--text2)">${ev.player}</span>`;
      cls = 'ev-corner';
      break;
    case 'foul':
      icon = '⚠️';
      title = `${ev.player} <span style="color:${col};font-size:11px">(${teamShort})</span> faul yaptı`;
      cls = 'ev-foul';
      break;
    case 'freekick':
      icon = '🆓';
      title = `<span style="color:${col}">${teamShort}</span> serbest vuruş · <span style="color:var(--text2)">${ev.player}</span>`;
      if (ev.foulBy) sub = `Faul: ${ev.foulBy}`;
      cls = 'ev-freekick';
      break;
    case 'offside':
      icon = '🚩';
      title = `<span style="color:#ffa726">OFSAYT!</span> ${ev.player} <span style="color:${col};font-size:11px">(${teamShort})</span>`;
      cls = 'ev-offside';
      break;
    case 'throwin':
      icon = '👐';
      title = `<span style="color:${col}">${teamShort}</span> taç atışı · <span style="color:var(--text2)">${ev.player}</span>`;
      cls = 'ev-throwin';
      break;
    case 'sub':
      icon = '';
      title = `<span style="color:var(--accent2)">↑ ${ev.player}</span> / <span style="color:#ef5350">↓ ${ev.playerOut}</span>`;
      sub = team ? team.name : '';
      cls = 'ev-sub';
      break;
    case 'tactic':
      icon = '⚔️';
      title = ev.text || 'Taktik değişikliği';
      cls = 'ev-tactic';
      break;
    // 🆕 Devre arası
    case 'halftime':
      icon = '⏸';
      title = liveTemplate('halftime');
      cls = 'ev-half';
      break;
    // 🆕 Maç sonu
    case 'fulltime':
      icon = '🏁';
      title = liveTemplate('fulltime');
      sub = `Final: ${MS.scoreH} - ${MS.scoreA}`;
      cls = 'ev-fulltime';
      break;
    // 🆕 Uzatma başlangıcı
    case 'extratimeStart':
      icon = '⏰';
      title = liveTemplate('extratime_start');
      cls = 'ev-half';
      break;
    case 'extratimeHalf':
      icon = '🔃';
      title = liveTemplate('extratime_half');
      cls = 'ev-half';
      break;
    // 🆕 Penaltı atışları başlangıcı
    case 'shootoutStart':
      icon = '🎯';
      title = liveTemplate('shootout_start');
      cls = 'ev-half';
      break;
    // 🆕 Penaltı atışı (sequence içinden gelen her atış)
    case 'shootoutKick':
      icon = ev.scored ? '⚽' : '❌';
      const ssh = ev.scored ? 'shootout_scored' : 'shootout_missed';
      title = liveTemplate(ssh, {
        player: ev.player || '?',
        goalkeeper: ev.goalkeeper || 'Kaleci',
        score: `${ev.homeScore || 0} - ${ev.awayScore || 0}`
      });
      sub = `<span style="color:${col}">${teamShort}</span> · ${ev.sudden ? 'Ani ölüm' : `${ev.round}. atış`}`;
      cls = ev.scored ? 'ev-goal' : 'ev-shot-off';
      break;
    case 'shootoutWinner':
      icon = '🏆';
      title = liveTemplate('shootout_winner', { team: ev.team === 'home' ? curHome.name : curAway.name });
      cls = 'ev-fulltime';
      try { triggerGoalFlash(); } catch(e) {}
      break;
    default:
      icon = '📌';
      title = ev.text || ev.type;
  }

  const el = document.createElement('div');
  // 🆕 Side class — home → sol, away → sağ, neutral → orta tam genişlik
  const _addSideCls = ev.team === 'home' ? 'ev-home' :
                      ev.team === 'away' ? 'ev-away' : 'ev-neutral';
  el.className = 'ev-item ' + cls + ' ' + _addSideCls;
  el.innerHTML = `
    <div class="ev-min">${min}'</div>
    <div class="ev-ico">${icon}</div>
    <div class="ev-body">
      <div class="ev-title">${title}</div>
      ${sub ? `<div class="ev-sub">${sub}</div>` : ''}
    </div>`;
  list.insertBefore(el, list.firstChild);
}

