async function processMatchEvent(ev) {
  if (!ev) return;

  // Server-ready: tüm event'leri bus'a yayınla (backend kolayca subscribe olur)
  if (typeof MatchStateBus !== 'undefined') {
    MatchStateBus.publish('event', ev);
  }

  // Hız çarpanı — banner gösterim süresi
  const slow = MS.speed === 1;

  if (ev.type === 'goal') {
    updateScore(ev.team);
    addEvent(ev);
    // 🆕 Penaltı golünde önce penalty banner, sonra GOL animasyonu
    if (ev.isPenalty && typeof showEventBanner === 'function') {
      showEventBanner('penalty', ev.player, 'penaltı golü');
      await sleep(slow ? 900 : 120);
    }
    if (typeof showGoal === 'function') showGoal(ev.player, Math.floor(ev.min));
    // Server-ready: skor güncellemesi de ayrı yayınla
    if (typeof MatchStateBus !== 'undefined') {
      MatchStateBus.publish('score_update', {
        scoreH: MS.scoreH || 0, scoreA: MS.scoreA || 0, minute: ev.min
      });
    }
    await sleep(slow ? 1200 : 200);
  } else if (ev.type === 'offsideGoal') {
    // 🆕 Ofsayt nedeniyle iptal edilen gol → banner
    addEvent(ev);
    if (typeof showEventBanner === 'function') showEventBanner('offside', ev.player, 'gol iptal edildi');
    await sleep(slow ? 1100 : 150);
  } else if (ev.type === 'offside') {
    // 🆕 Ofsayt → banner
    addEvent(ev);
    if (typeof showEventBanner === 'function') showEventBanner('offside', ev.player, 'pozisyona geç çıktı');
    await sleep(slow ? 900 : 120);
  } else if (ev.type === 'red') {
    // 🆕 Kırmızı kart → banner
    addEvent(ev);
    if (typeof showEventBanner === 'function') showEventBanner('red', ev.player, '10 kişi kaldı');
    await sleep(slow ? 1100 : 150);
  } else if (ev.type === 'yellow') {
    // 🆕 Sarı kart → banner (kısa)
    addEvent(ev);
    if (typeof showEventBanner === 'function') showEventBanner('yellow', ev.player, '');
    await sleep(slow ? 700 : 100);
  } else if (ev.type === 'penaltyMissed') {
    // 🆕 Penaltı kaçtı → banner
    addEvent(ev);
    if (typeof showEventBanner === 'function') showEventBanner('penaltyMissed', ev.player, 'şutu kaçırdı');
    await sleep(slow ? 1000 : 130);
  } else if (ev.type === 'varCancel') {
    // 🆕 VAR iptali → banner
    addEvent(ev);
    if (typeof showEventBanner === 'function') showEventBanner('varCancel', '', 'gol geri alındı');
    await sleep(slow ? 900 : 120);
  } else if (ev.type === 'corner') {
    // 🆕 Korner → banner
    addEvent(ev);
    if (typeof showEventBanner === 'function') showEventBanner('corner', ev.player || '', '');
    await sleep(slow ? 500 : 80);
  } else if (ev.type === 'foul') {
    // 🆕 Faul → banner (kısa)
    addEvent(ev);
    if (typeof showEventBanner === 'function') {
      // 🆕 Hava bağlı kayma faulu → özel detay
      let detail = '';
      if (ev.weatherCause === 'rain')  detail = '🌧️ Islak zeminde kaydı';
      else if (ev.weatherCause === 'snow')  detail = '❄️ Karda kaydı';
      else if (ev.weatherCause === 'storm') detail = '⛈️ Fırtınada kaydı';
      showEventBanner('foul', ev.player || '', detail);
    }
    await sleep(slow ? 400 : 70);
  } else {
    addEvent(ev);
  }
}



// ══════════════════════════════════════════════════════════
