// 623 — TEK EKONOMİ TABLOSU (sunucudaki EKONOMI ile birebir; kademe 1 = Süper Lig … 6 = 5. Lig).
//   Ödemeleri sunucu yapar; buradaki kopya yalnız ekranlarda gösterilir.
//   Aşama bonusları birikimlidir: takım ulaştığı her aşamanın bonusunu bir kez alır.
const EKONOMI = {
  lig: {
    1: { bilet: 14, galibiyet: 75000, beraberlik: 25000, sampiyon: 2000000 },
    2: { bilet: 12, galibiyet: 62000, beraberlik: 21000, sampiyon: 1600000 },
    3: { bilet: 11, galibiyet: 55000, beraberlik: 18000, sampiyon: 1400000 },
    4: { bilet: 10, galibiyet: 50000, beraberlik: 17000, sampiyon: 1300000 },
    5: { bilet: 10, galibiyet: 48000, beraberlik: 16000, sampiyon: 1200000 },
    6: { bilet: 9,  galibiyet: 46000, beraberlik: 15000, sampiyon: 1150000 },
  },
  siraEgri: [1, 0.80, 0.66, 0.56, 0.48, 0.42, 0.37, 0.33, 0.30, 0.27, 0.24, 0.22, 0.20, 0.18, 0.16, 0.15],
  kupa: {
    champ: { bilet: 16, galibiyet: 80000, beraberlik: 27000,
             asama: { group: 300000, r16: 300000, qf: 400000, sf: 500000, finalist: 700000, champion: 1000000 } },
    elite: { bilet: 15, galibiyet: 70000, beraberlik: 23000,
             asama: { po2: 100000, group: 200000, r32: 200000, r16: 250000, qf: 300000, sf: 400000, finalist: 550000, champion: 800000 } },
    conv:  { bilet: 14, galibiyet: 60000, beraberlik: 20000,
             asama: { po2: 80000, group: 150000, r32: 150000, r16: 200000, qf: 250000, sf: 300000, finalist: 400000, champion: 600000 } },
  },
};
function ekoKapasite(sv) {
  return 5000 + 1500 * (Math.max(1, Math.min(10, Math.floor(Number(sv) || 1))) - 1);
}
// Sezon sonu sıralama ödülü (tier 1–6, sıra 1–16). `sezon` verilirse yeni tablodan önceki
//   sezonlar o dönem gerçekten ödenen eski tabloyla hesaplanır (sunucu world_state.eko623_sezon).
function ekoSiraOdulu(tier, sira, sezon) {
  const ws = (typeof loadWorldState === 'function') ? loadWorldState() : null;
  const ilk = ws ? Number(ws.eko623_sezon) : 0;
  if (sezon != null && !(ilk > 0 && sezon >= ilk)) {
    const eski = [5000000,3000000,2000000,1400000,1000000,800000,650000,550000,450000,380000,320000,270000,220000,180000,150000,120000][sira - 1] || 0;
    return Math.round(eski * ({ 1: 0.55, 2: 0.32, 3: 0.20, 4: 0.12, 5: 0.07 }[tier] || 0.04) / 1000) * 1000;
  }
  const t = EKONOMI.lig[tier], e = EKONOMI.siraEgri[sira - 1];
  return t && e ? Math.round(t.sampiyon * e / 1000) * 1000 : 0;
}



// EUR formatla (1.5M €, 850K €, 12.500 €)
function _fmtMatchEUR(v) {
  if (!v) return '€0';
  if (v >= 1000000) return '€' + (v / 1000000).toFixed(v >= 10000000 ? 0 : 1) + 'M';
  if (v >= 1000) return '€' + Math.round(v / 1000) + 'K';
  return '€' + v.toLocaleString('tr-TR');
}

// Ana fonksiyon: Maç sonu ekranını göster
function showMatchResult() {
  const overlay = document.getElementById('match-result-overlay');
  if (!overlay) return;

  // 🆕 MAÇ BİTTİ → reyting tutarlılığı: edge'in lineup'a yazdığı GERÇEK matchRating'i kullan
  //   (bitmiş maç modalıyla aynı kaynak). Frontend'in canlı tahmini (_attachLivePlayerStats)
  //   maç sonunda ezilir. İsim eşleştirmesiyle curHome/curAway players'a aktar.
  try {
    if (typeof _liveMatchCache !== 'undefined' && _liveMatchCache && MS.match_key) {
      const _lr = _liveMatchCache[MS.match_key];
      if (_lr) {
        const _applyServerRatings = (lineup, players) => {
          if (!lineup || !Array.isArray(players)) return;
          const arr = (Array.isArray(lineup.players) ? lineup.players
                    : Array.isArray(lineup) ? lineup : [])
                    .concat(Array.isArray(lineup.bench) ? lineup.bench : []);
          if (!arr.length) return;
          const byName = {};
          arr.forEach(sp => { if (sp && sp.name && typeof sp.matchRating === 'number') byName[sp.name] = sp.matchRating; });
          // 🆕 (511) Sunucunun maç sonu reyting haritası (sahaya çıkan herkes, yedekler dahil)
          if (lineup.ratings && typeof lineup.ratings === 'object') {
            for (const k in lineup.ratings) if (typeof lineup.ratings[k] === 'number') byName[k] = lineup.ratings[k];
          }
          players.forEach(p => { if (p && p.name && typeof byName[p.name] === 'number') p.matchRating = byName[p.name]; });
        };
        if (curHome) _applyServerRatings(_lr.home_lineup, curHome.players);
        if (curAway) _applyServerRatings(_lr.away_lineup, curAway.players);
        if (curHome && Array.isArray(curHome.benchPlayers)) _applyServerRatings(_lr.home_lineup, curHome.benchPlayers);
        if (curAway && Array.isArray(curAway.benchPlayers)) _applyServerRatings(_lr.away_lineup, curAway.benchPlayers);
      }
    }
  } catch(e) { console.warn('[showMatchResult] server rating aktarım hata:', e); }

  const script = MS.script;
  // 🆕 Skor: MS'den oku, 0 ise Edge Function row'undan fallback (poll güncellemesi gecikti olabilir)
  let scoreH = MS.scoreH || 0;
  let scoreA = MS.scoreA || 0;
  if ((scoreH === 0 && scoreA === 0) && typeof _liveMatchCache !== 'undefined' && _liveMatchCache && MS.match_key) {
    const liveRow = _liveMatchCache[MS.match_key];
    if (liveRow) {
      scoreH = liveRow.home_score || scoreH;
      scoreA = liveRow.away_score || scoreA;
      // MS'e de yansıt
      MS.scoreH = scoreH;
      MS.scoreA = scoreA;
    }
  }
  // Yine 0-0 ise events'ten say (script.evs varsa)
  if (scoreH === 0 && scoreA === 0 && script && Array.isArray(script.evs)) {
    for (const ev of script.evs) {
      if (!ev || ev.type !== 'goal' || ev.cancelled === true) continue;
      if (ev.team === 'home') scoreH++;
      else if (ev.team === 'away') scoreA++;
    }
    MS.scoreH = scoreH;
    MS.scoreA = scoreA;
  }

  // Kullanıcı maçta mı?
  const userIsHome = !!(curHome && (curHome.players||[]).some(p => p.isUser))
                  || !!(typeof _userTeam !== 'undefined' && _userTeam && curHome && curHome.name === _userTeam.teamName);
  const userIsAway = !!(curAway && (curAway.players||[]).some(p => p.isUser))
                  || !!(typeof _userTeam !== 'undefined' && _userTeam && curAway && curAway.name === _userTeam.teamName);
  const forceUser  = !!(MS && MS._testForceCaptain);
  const userInMatch = userIsHome || userIsAway || forceUser;
  const finalUserIsHome = userIsHome || (forceUser && !userIsAway);

  // ── 592 — Kasaya giren: sunucunun maç bitiminde yatırdığı tutar (lineup.gelir). Eskiden tarayıcı
  //   rastgele seyirciyle tahmin ediyordu; turnuva tur primi gibi ödenmeyen kalemler de görünüyordu.
  let _odul = null;
  if (!MS._fromResults && typeof _userTeam !== 'undefined' && _userTeam) {
    const _taraf = (curHome && curHome.name === _userTeam.teamName) ? 'home' : ((curAway && curAway.name === _userTeam.teamName) ? 'away' : null);
    const _lr = (_taraf && typeof _liveMatchCache === 'object' && _liveMatchCache && MS.match_key) ? _liveMatchCache[MS.match_key] : null;
    const g = _lr && _lr[_taraf + '_lineup'] && _lr[_taraf + '_lineup'].gelir;
    if (g) {
      const items = [];
      if (g.bilet > 0) {
        items.push({ icon: '🎟️', name: `Bilet Geliri (${Number(g.seyirci).toLocaleString('tr-TR')} / ${Number(g.kapasite).toLocaleString('tr-TR')} kapasite)`, amount: Number(g.taban) || g.bilet });
        if (g.bilet > (Number(g.taban) || g.bilet)) items.push({ icon: '💼', name: `Finans Merkezi Bonus (+%${g.finans})`, amount: g.bilet - g.taban });
      }
      if (g.prim > 0) items.push({ icon: g.primTur === 'beraberlik' ? '🤝' : '🏆', name: g.primTur === 'beraberlik' ? 'Beraberlik Primi' : 'Galibiyet Primi', amount: g.prim });
      if (items.length) _odul = { items, total: items.reduce((t, x) => t + x.amount, 0), seyirci: g.bilet > 0 ? g.seyirci : null, takim: _userTeam.teamName };
    }
  }

  // ── 591 — Maç sonu ekranı (skor · maçın adamı · istatistik · kasaya giren · kadrolar)
  try {
    msSonuCiz({ scoreH, scoreA, userSide: userInMatch ? (finalUserIsHome ? 'home' : 'away') : null, odul: _odul });
  } catch (e) { console.warn('[maç sonu] çizim hatası:', e); }

  // 🆕 Buton metni: returnMode'a göre
  // - home (GÜNÜN MAÇLARI'ndan açıldı) → "🏠 Ana Sayfa"
  // - results (SONUÇLAR'dan açıldı) → "↩️ Listeye Geri Dön"
  // - normal maç sonu → "🏠 Ana Menüye Dön"
  const homeBtn = overlay.querySelector('.mr-btn-home');
  if (homeBtn) homeBtn.textContent = MS._returnMode === 'home' ? 'Ana Sayfa' : (MS._fromResults ? 'Listeye Geri Dön' : 'Ana Menüye Dön');

  // Overlay'i göster
  overlay.classList.add('show');

  // 🆕 YARIŞ DÜZELTMESİ: Edge'in lineup reytingi henüz gelmemişse, gelene kadar arka planda
  //   çekip ANINDA uygula + ekranı tazele (canlı tahmin asla takılı kalmasın).
  try {
    const _lrChk = (typeof _liveMatchCache === 'object' && _liveMatchCache && MS && MS.match_key) ? _liveMatchCache[MS.match_key] : null;
    const _hasEdge = (lu) => { const a = (lu && Array.isArray(lu.players)) ? lu.players : (Array.isArray(lu) ? lu : []); return a.some(p => p && typeof p.matchRating === 'number'); };
    const _edgeReady = _lrChk && (_hasEdge(_lrChk.home_lineup) || _hasEdge(_lrChk.away_lineup));
    if (!_edgeReady && !window._matchEndRatingRetry) {
      window._matchEndRatingRetry = true;
      _ensureEdgeMatchRatings(0);
    } else if (_edgeReady) {
      window._matchEndRatingRetry = false;
    }
  } catch(e) {}
}

// 🆕 Edge maç reytingi gelene kadar tekrar dene; gelince showMatchResult'ı yeniden çalıştırıp
//   uygula + KADROLAR'ı tazele. Overlay kapanınca veya ~30sn sonra durur.
async function _ensureEdgeMatchRatings(attempt) {
  attempt = attempt || 0;
  try {
    const ov = document.getElementById('match-result-overlay');
    if (!ov || !ov.classList.contains('show')) { window._matchEndRatingRetry = false; return; }
    if (typeof MS === 'undefined' || !MS || !MS.match_key) { window._matchEndRatingRetry = false; return; }
    const _hasEdge = (lu) => { const a = (lu && Array.isArray(lu.players)) ? lu.players : (Array.isArray(lu) ? lu : []); return a.some(p => p && typeof p.matchRating === 'number'); };
    if (window.sb) {
      try {
        const { data } = await window.sb.from('match_state')
          .select('match_key,home_lineup,away_lineup').eq('match_key', MS.match_key).maybeSingle();
        if (data) {
          if (typeof _liveMatchCache !== 'object' || !_liveMatchCache) window._liveMatchCache = {};
          _liveMatchCache[MS.match_key] = { ...(_liveMatchCache[MS.match_key] || {}), home_lineup: data.home_lineup, away_lineup: data.away_lineup };
        }
      } catch(e) {}
    }
    const lr = (typeof _liveMatchCache === 'object' && _liveMatchCache) ? _liveMatchCache[MS.match_key] : null;
    if (lr && (_hasEdge(lr.home_lineup) || _hasEdge(lr.away_lineup))) {
      window._matchEndRatingRetry = false;               // showMatchResult yeniden retry başlatmasın
      try { if (typeof showMatchResult === 'function') showMatchResult(); } catch(e) {}
      try { if (typeof renderLineup === 'function') renderLineup(); } catch(e) {}
      return;
    }
  } catch(e) {}
  if (attempt < 12) { setTimeout(() => _ensureEdgeMatchRatings(attempt + 1), 2500); }
  else { window._matchEndRatingRetry = false; }
}

function closeMatchResultOverlay() {
  const ov = document.getElementById('match-result-overlay');
  if (ov) ov.classList.remove('show');
}

function mrGoHome() {
  // 🆕 SONUÇLAR sayfasından açıldıysa: sonuçlar sayfasına dön
  // GÜNÜN MAÇLARI'ndan açıldıysa: ana sayfaya dön
  const fromResults = !!(typeof MS !== 'undefined' && MS._fromResults);
  const returnMode = (typeof MS !== 'undefined' && MS._returnMode) || (fromResults ? 'results' : 'home');

  // 🆕 Geçmiş maç görüntülemesi sonrası: orijinal MS state'ini geri yükle
  if (typeof MS !== 'undefined' && MS._historicalSnapshot) {
    const snap = MS._historicalSnapshot;
    if (snap._prevMS) {
      // Sadece kritik alanları restore et (tüm MS yerine)
      Object.keys(MS).forEach(k => {
        if (!(k in snap._prevMS)) delete MS[k];
      });
      Object.assign(MS, snap._prevMS);
    }
    // 🔧 curHome/curAway let değişkenlerini restore et
    if (snap._prevCurHome !== null && typeof curHome !== 'undefined') curHome = snap._prevCurHome;
    if (snap._prevCurAway !== null && typeof curAway !== 'undefined') curAway = snap._prevCurAway;
    delete MS._historicalSnapshot;
  }
  // Bayrakları temizle (scrollY'i restore'dan önce alıyoruz)
  let scrollY = null;
  if (typeof MS !== 'undefined') {
    if (typeof MS._returnScrollY === 'number') scrollY = MS._returnScrollY;
    delete MS._fromResults;
    delete MS._returnMode;
    delete MS._returnScrollY;
  }

  closeMatchResultOverlay();
  if (typeof closeMatchScreen === 'function') closeMatchScreen();
  if (typeof showPage === 'function') {
    if (returnMode === 'results') {
      const resultsBtn = document.querySelector('.nav-btn[onclick*="results"]');
      showPage('results', resultsBtn);
    } else {
      const homeBtn = document.querySelector('.nav-btn');
      // 🆕 Flicker engellemek için: ana sayfayı görünmez yap, scroll'u ayarla, sonra göster
      if (scrollY !== null) {
        const homePage = document.getElementById('page-home');
        if (homePage) homePage.style.visibility = 'hidden';
        showPage('home', homeBtn);
        // showPage scroll'u 0'a çekmeden önce yakala — requestAnimationFrame ile bir frame bekle
        requestAnimationFrame(() => {
          window.scrollTo(0, scrollY);
          // Bir frame daha bekle ki layout uygulanmış olsun, sonra görünür yap
          requestAnimationFrame(() => {
            if (homePage) homePage.style.visibility = '';
          });
        });
      } else {
        showPage('home', homeBtn);
      }
    }
  }
}



