//  SEZON SONU SİSTEMİ — kupa, promosyon/düşme, Avrupa, yeni sezon
// ═══════════════════════════════════════════════════════════════════

// Lig sıralamasını gerçek maç sonuçlarından hesapla
function computeLeagueStandings(countryCode, tierIdx, seasonNum) {
  // 🆕 SUPABASE TEK KAYNAK — _matchResultsLoad cache çağrısı kaldırıldı.
  const country = _cftGetCountry(countryCode);
  if (!country || !country.leagues || !country.leagues[tierIdx]) return [];
  const league = country.leagues[tierIdx];
  const teams = (league.teams || []).slice();
  const tier1 = tierIdx + 1;

  const stats = {};
  teams.forEach(t => {
    stats[t.name] = {
      team: t,
      games: 0, wins: 0, draws: 0, losses: 0,
      goalsFor: 0, goalsAgainst: 0, goalDiff: 0, points: 0
    };
  });

  if (_matchStateCache && _matchStateCache.byKey) {
    for (const ms of Object.values(_matchStateCache.byKey)) {
      if (!ms) continue;
      if (ms.tournament_key) continue;
      if (ms.countryCode !== countryCode) continue;
      if (ms.tier !== tier1) continue;
      if (ms.season !== seasonNum) continue;
      if (ms.status !== 'finished') continue;
      const h = stats[ms.home], a = stats[ms.away];
      if (!h || !a) continue;
      const hs = Number(ms.home_score) || 0;
      const as_ = Number(ms.away_score) || 0;
      h.games++; a.games++;
      h.goalsFor += hs; h.goalsAgainst += as_;
      a.goalsFor += as_; a.goalsAgainst += hs;
      if (hs > as_) { h.wins++; a.losses++; h.points += 3; }
      else if (hs < as_) { a.wins++; h.losses++; a.points += 3; }
      else { h.draws++; a.draws++; h.points += 1; a.points += 1; }
    }
  }

  Object.values(stats).forEach(s => { s.goalDiff = s.goalsFor - s.goalsAgainst; });

  const sorted = Object.values(stats).sort((a, b) => {
    if (b.points !== a.points) return b.points - a.points;
    if (b.goalDiff !== a.goalDiff) return b.goalDiff - a.goalDiff;
    return b.goalsFor - a.goalsFor;
  });

  return sorted;
}

// 🆕 Kullanıcının takımının GERÇEK tier'ını teams DB'den bul (cache'lenmiş tierIdx'e güvenme)
function getUserRealTierIdx() {
  if (typeof _userTeam === 'undefined' || !_userTeam || !_userTeam.teamName || !_userTeam.countryCode) return 0;
  const country = _cftGetCountry(_userTeam.countryCode);
  if (!country || !country.leagues) return _userTeam.tierIdx || 0;
  for (let li = 0; li < country.leagues.length; li++) {
    const lg = country.leagues[li];
    if (lg && lg.teams && lg.teams.some(t => t.name === _userTeam.teamName)) {
      return li;
    }
  }
  return _userTeam.tierIdx || 0;
}

// Kullanıcı takımının final pozisyonunu bul
function getUserFinalRank(seasonNum) {
  if (typeof _userTeam === 'undefined' || !_userTeam) return null;
  const cc = _userTeam.countryCode || 'TR';
  // 🔑 ESKİ HATA: her zaman ŞU ANKİ lig kademesine bakılıyordu. Terfi/düşme
  //    sonrası geçen sezonun tablosunda kendini bulamıyor, sıralama ve
  //    istatistikler sıfır çıkıyordu. Artık takımın o sezon HANGİ LİGDEYSE
  //    o tabloya bakılır — bulunamazsa tüm kademeler taranır.
  const suanki = getUserRealTierIdx();
  const denenecek = [suanki];
  for (let t = 0; t < 8; t++) if (t !== suanki) denenecek.push(t);

  let standings = null, idx = -1, tierIdx = suanki;
  for (const t of denenecek) {
    let st = [];
    try { st = computeLeagueStandings(cc, t, seasonNum) || []; } catch(e) { continue; }
    if (!st.length) continue;
    const k = st.findIndex(x => x && x.team && x.team.name === _userTeam.teamName);
    if (k >= 0) {
      // Oynanmış maçı olan tabloyu tercih et (boş tabloya takılma)
      const oynanmis = st.some(x => x && x.standing
        ? ((x.standing.wins||0)+(x.standing.draws||0)+(x.standing.losses||0)) > 0
        : ((x.wins||0)+(x.draws||0)+(x.losses||0)) > 0);
      standings = st; idx = k; tierIdx = t;
      if (oynanmis) break;
    }
  }
  if (!standings || idx < 0) return null;
  return {
    rank: idx + 1,
    standing: standings[idx],
    standings,
    tierIdx,
    leagueName: (_cftGetCountry(cc).leagues[tierIdx] || {}).name || ''
  };
}

// Sezon sonu UI gösterimini session içinde tekrar tetiklenmemek için işaretle
// (RAM cache — refresh'te tekrar görünebilir, session boyunca bir kez)
// localStorage YOK — kullanıcı kuralı + backend tek doğruluk kaynağı.
const _SEZ_TOREN_KEY = 'cft_sezon_toren';
function _sezTorenSet() {
  try { const a = JSON.parse(localStorage.getItem(_SEZ_TOREN_KEY) || '[]');
        return new Set(Array.isArray(a) ? a : []); } catch(e) { return new Set(); }
}
function isSeasonEndProcessed(seasonNum) {
  if (window._seasonEndShown && window._seasonEndShown[seasonNum]) return true;
  return _sezTorenSet().has(Number(seasonNum));
}
function markSeasonEndProcessed(seasonNum) {
  window._seasonEndShown = window._seasonEndShown || {};
  window._seasonEndShown[seasonNum] = true;
  try {
    const st = _sezTorenSet();
    st.add(Number(seasonNum));
    localStorage.setItem(_SEZ_TOREN_KEY, JSON.stringify(Array.from(st).slice(-20)));
  } catch(e) {}
}

// ═══════════════════════════════════════════════════════════════════
//  🆕 FAZ 5 — DÜNYA STATE: MERKEZİ DİNAMİK DURUM YÖNETİMİ
// ═══════════════════════════════════════════════════════════════════
//
// MIMARI:
//   teams DB = takımların kalıcı yapısı (statik + dinamik alanlar bir arada)
//     - Statik alanlar (asla değişmez): name, city, pop, short, code
//     - Dinamik alanlar (sezon ilerledikçe değişir): tier, rating, oz, rank, bg, tc
//
//   WorldState (cft_world_state localStorage anahtarı) = dinamik alanların
//   merkezi overlay'i. Sayfa açıldığında teams DB'ye uygulanır, mutasyon
//   olduğunda kaydedilir. Şu an localStorage ile mock — ileride backend
//   API'sine bağlanacak (POST/GET /api/world/state).
//
// ÖNEMLİ:
//   - Bu online multi-server bir oyun. Bir dünya başlatıldığında
//     admin müdahalesi olmadan sonsuza dek devam eder.
//   - Kullanıcı tarafında "oyunu sıfırla" diye bir özellik YOK.
//   - localStorage temizlemek dünyayı sıfırlamaz, sadece lokal cache.
//   - Yeni oyuncu katılırsa o anki dünya state'ine dahil olur.
//
// API:
//   loadWorldState()              → state objesini getir (yoksa boş döner)
//   saveWorldState(state)         → state'i persist et (mock: localStorage,
//                                  ileride: POST /api/world/state)
//   applyWorldStateToCFTDB()      → sayfa açılınca teams DB'ye uygula
//   recordFinalStandings(s, snap) → sezon sonu sıralama kaydı (UI cache)
//   readFinalStandings(season)    → sezon sıralamasını oku
//
// STATE ŞEMASI:
//   {
//     schemaVersion: 1,
//     bot_promrel:      { [seasonNum]: { [cc]: [{tier, teamNames[]}] } },
//     final_standings:  { [seasonNum]: { [cc]: [name1..name6] } },
//     // Gelecekteki uzantılar için yer ayrıldı:
//     // team_ratings:  { [teamName]: rating },
//     // team_oz:       { [teamName]: oz },
//     // player_transfers: [...]
//   }
// ═══════════════════════════════════════════════════════════════════

const _WORLD_STATE_KEY = 'cft_world_state';
const _WORLD_STATE_SCHEMA_VERSION = 1;

// 🆕 Supabase tek kaynak. RAM cache sync API'yi korur (loadWorldState yüzlerce yerden sync çağrılıyor).
// Bootstrap'te bir kere Supabase'ten çekilir → cache dolar. Her save sonrası debounced UPDATE.
let _worldStateCache = null;
let _worldStateSaveTimer = null;

async function _worldStateLoadFromServer() {
  try {
    if (!window.sb) { _worldStateCache = _emptyWorldState(); return; }
    const { data, error } = await window.sb.from('world_state')
      .select('data').eq('id', 1).maybeSingle();
    if (error) { console.warn('[WorldState] load hata:', error.message); _worldStateCache = _emptyWorldState(); return; }
    const obj = (data && data.data && typeof data.data === 'object') ? data.data : {};
    if (!obj.bot_promrel) obj.bot_promrel = {};
    if (!obj.final_standings) obj.final_standings = {};
    if (!obj.team_jerseys) obj.team_jerseys = {};
    if (!obj.season_fixtures) obj.season_fixtures = {};
    if (!obj.schemaVersion) obj.schemaVersion = _WORLD_STATE_SCHEMA_VERSION;
    _worldStateCache = obj;
    try { if (typeof _formaKanalBagla === 'function') _formaKanalBagla(); } catch(e) {}   // 713
    // 🆕 SEASON_EPOCH'u server'dan gelen gameStartDate ile senkronize et.
    //   ISO string UTC olarak parse edilir, SEASON_EPOCH UTC midnight kalır.
    //   getSeasonInfo UTC bazlı hesaplama yapar → tüm dünyada aynı dayInSeason.
    try {
      if (obj.gameStartDate && typeof SEASON_EPOCH !== 'undefined') {
        const d = new Date(obj.gameStartDate);
        if (!isNaN(d.getTime())) SEASON_EPOCH = d;
      }
    } catch(e) {}
  } catch(e) { console.warn('[WorldState] load hata:', e); _worldStateCache = _emptyWorldState(); }
}

async function _worldStateSaveImpl() {
  try {
    if (!window.sb || !_worldStateCache) return;
    // 🔒 world_state İSTEMCİDEN YAZILMAZ — tüm dünyanın sezon/faz bilgisi.
    //   Yalnızca sunucu (tick-matches) günceller. Burada yazım devre dışı.
    if (false) await window.sb.from('world_state').update({ data: _worldStateCache, updated_at: new Date().toISOString() }).eq('id', 1);
  } catch(e) { console.warn('[WorldState] save hata:', e); }
}

// Sync API — RAM cache döner. Bootstrap çağrılmadan önce çağrılırsa boş state döner.
function loadWorldState() {
  if (!_worldStateCache) _worldStateCache = _emptyWorldState();
  return _worldStateCache;
}

function _emptyWorldState() {
  return {
    schemaVersion: _WORLD_STATE_SCHEMA_VERSION,
    bot_promrel: {},
    final_standings: {},
    gameStartDate: null,  // 🆕 ISO string, null=default kullan
    team_jerseys: {},     // 🆕 { [teamName]: { setA:{shirt,short}, setB:{shirt,short}, changeCount:N } }
    season_fixtures: {}   // 🆕 { [seasonNum]: { drawnAt, dayMap: { dayInSeason: [matches] } } } — kalıcı fikstür
  };
}

