  if (gol) _pdSesCal('ag', 0.56); else _pdSesCal('alkis', 0.5);
  if (PD.sahneHazir) { try { await Promise.race([Sahne3D.atis(atis, dalis, gol, kacis), _pdBekle(1800)]); } catch (e) { await _pdBekle(900); } }   // arka planda kare durursa atış sırası kaymasın
  else await _pdBekle(900);
  const y = _pd$('pdSonucYazi');
  y.textContent = gol ? 'Gol!' : kacis === 'direk' ? 'Direkte!' : kacis === 'aut' ? 'Dışarı!' : 'Kurtardı!';
  y.className = 'pd-sonuc-yazi on ' + (gol ? 'gol' : 'kur');
