function _finalizeMatch(script) {
  updateClock(90);
  if (script && script.stats) updateStats(script.stats, 1);
  const skipBtn = document.getElementById('btnSkip');
  if (skipBtn) skipBtn.disabled = true;
  MS.finished = true;
  MS.running = false;

  // 🆕 Olay listesine "MAÇ BİTTİ" satırı ekle + live header
  try {
    if (typeof addEvent === 'function') addEvent({ type: 'fulltime', min: MS._uzt ? 120 : 90 });
    if (typeof updateLiveHeader === 'function') updateLiveHeader(MS._uzt ? 120 : 90, 'Maç bitti', 50, 50);
  } catch(e) {}

  // 🆕 Maç bitti: arka plan müziğini (ayar açıksa) tekrar başlat
  window._cftMatchInProgress = false;
  if (typeof _cftMusicEnabled !== 'undefined' && _cftMusicEnabled && typeof _cftMusicStart === 'function') {
    setTimeout(() => {
      try { _cftMusicStart(); } catch(e){}
    }, 800); // Kısa gecikme: maç sonu UI'sı oturduktan sonra
  }

  // Maç sonu: Kart/sakatlıkları ROSTER_DATA'ya işle
  let userIsHome = false;
  let userInMatch = false;
  try {
    if(MS.script && typeof processMatchOutcome === 'function') {
      userIsHome = !!(curHome && (curHome.players||[]).some(pl => pl.isUser))
                || !!(typeof _userTeam !== 'undefined' && _userTeam && curHome && curHome.name === _userTeam.teamName);
      userInMatch = userIsHome
                 || !!(curAway && (curAway.players||[]).some(pl => pl.isUser))
                 || !!(typeof _userTeam !== 'undefined' && _userTeam && curAway && curAway.name === _userTeam.teamName);
      if(userInMatch && !MS._isHistorical) {
        processMatchOutcome(MS.script, userIsHome);
        // 🆕 Edge maç bitiminde players tablosuna kart/sakatlık yazdı.
        //   ROSTER_DATA in-memory cache'i tazeleyip yeni disiplin verisini görelim.
        //   Asenkron — UI'yi blok etmesin.
        try {
          if (typeof _loadTeamRosterFromServer === 'function') {
            _loadTeamRosterFromServer().then(() => {
              if (typeof renderRoster === 'function') renderRoster('all');
            }).catch(()=>{});
          }
        } catch(e) {}
      }
    }
  } catch(e) { console.warn('Match outcome processing failed:', e); }

  // 🆕 LİG FİKSTÜR GÜNCELLEMESİ — eğer maç bir lig fikstüründen başlatıldıysa
  // Skor lig tablosuna yansıt, fikstür "geçmiş" olarak işaretle
  // (geçmiş maç görüntülemesinde atla)
  try {
    if (MS._fixtureRef && !MS._isHistorical) {
      const m = MS._fixtureRef;
      m.hs = MS.scoreH || 0;
      m.as = MS.scoreA || 0;
      m.isPast = true;
      m.isCurrentDay = false;
      // Canlı flag temizle (Fix 7)
      m.isLive = false;
      delete m.liveMinute;

      // Lig sıralaması yeniden hesapla (eğer fonksiyon varsa)
      if (typeof renderLeagueStandings === 'function') {
        try { renderLeagueStandings(); } catch(e) {}
      }
      if (typeof refreshLeagueAfterMatch === 'function') {
        try { refreshLeagueAfterMatch(m); } catch(e) {}
      }
    }
  } catch(e) { console.warn('Lig fikstür güncellemesi başarısız:', e); }

  // Lokal match_log yazım bloğu SİLİNDİ.
  //   Supabase match_state zaten kullanıcının olduğu maçların events'ini kayıtlı tutuyor.
  //   Profil/form puanı match_state'ten beslenmeli.


  // 🆕 Hazırlık maçı sonucunu cft_friendly_matches'a yaz (skor + tarih + result)
  try {
    if (MS._isFriendly && MS._friendlyMatchId && typeof frmGetMatches === 'function') {
      const all = frmGetMatches();
      const idx = all.findIndex(x => x.id === MS._friendlyMatchId);
      if (idx !== -1) {
        const hs = MS.scoreH || 0;
        const as = MS.scoreA || 0;
        all[idx].hs = hs;
        all[idx].as = as;
        all[idx].played = true;
        all[idx].playedAt = Date.now();
        all[idx].result = hs > as ? 'home' : (hs < as ? 'away' : 'draw');
        frmSaveMatches(all);
      }
    }
  } catch(e) { console.warn('Hazırlık maçı kaydı başarısız:', e); }

  // Lokal motor maç sonu lokal stat kayıt bloğu SİLİNDİ.
  //   Supabase Edge function (tick-matches) zaten her maçı match_state'e
  //   events + lineup ile birlikte yazıyor. Lokal kopyaya gerek yok.

  // 🆕 UI tazele — lig sayfası + ana sayfa next match
  try {
    if (typeof renderFixture === 'function') renderFixture();
    if (typeof renderHomeNextMatch === 'function') renderHomeNextMatch();
  } catch(e) {}

  // 🆕 SONUCU ÖNBELLEĞE YAZ — lig puan durumu ve sonuçlar sayfası maç biter
  //   bitmez güncellensin (eskiden bir sonraki sunucu yüklemesini bekliyordu).
  try {
    const _mk = MS.match_key;
    if (_mk) {
      const _hs = MS.scoreH || 0, _as = MS.scoreA || 0;
      if (typeof _matchStateCache === 'object' && _matchStateCache && _matchStateCache.byKey) {
        const _c = _matchStateCache.byKey[_mk];
        if (_c) {
          _c.status = 'finished';
          _c.home_score = _hs; _c.hs = _hs;
          _c.away_score = _as; _c.as = _as;
          _c.sim_minute = 90;
        }
      }
      if (typeof _liveMatchCache === 'object' && _liveMatchCache && _liveMatchCache[_mk]) {
        _liveMatchCache[_mk].status = 'finished';
        _liveMatchCache[_mk].home_score = _hs;
        _liveMatchCache[_mk].away_score = _as;
        _liveMatchCache[_mk].sim_minute = 90;
      }
      // wrapper cache'i geçersiz kıl (puan durumu yeniden hesaplansın)
      try { _mrWrapperCache = null; } catch(e) {}
    }
  } catch(e) {}
  // Puan durumu / sonuçlar / fikstür tazele
  try {
    if (typeof lgRender === 'function') lgRender();
    if (typeof renderResultsPage === 'function') renderResultsPage();
    if (typeof renderHomeLeagueScene === 'function') renderHomeLeagueScene();
  } catch(e) {}

  // 🆕 MAÇ SONU EKRANINI GÖSTER (1 saniye sonra)
  try {
    setTimeout(() => {
      if (typeof showMatchResult === 'function') showMatchResult();
    }, 800);
  } catch(e) { console.warn('showMatchResult hatası:', e); }

  // 🆕 Ana sayfa "Maça Git" butonunu tazele — bitmiş maç butondan düşsün
  try {
    if (typeof _liveMatchLoadFromServer === 'function') {
      _liveMatchLoadFromServer().then(() => {
        if (typeof frmEnsurePlayed === 'function') { try { frmEnsurePlayed(); } catch(e){} }
        if (typeof renderHomeNextMatch === 'function') { try { renderHomeNextMatch(); } catch(e){} }
      });
    } else {
      if (typeof frmEnsurePlayed === 'function') { try { frmEnsurePlayed(); } catch(e){} }
      if (typeof renderHomeNextMatch === 'function') { try { renderHomeNextMatch(); } catch(e){} }
    }
  } catch(e) { console.warn('home next match refresh hatası:', e); }

  // 🆕 KADRO + DİZİLİŞ sayfaları açıksa yenile (kart/sakatlık durumları taze görünsün)
  try {
    if (typeof renderRoster === 'function') {
      try { renderRoster('all'); } catch(e){}
    }
    if (typeof renderPitch === 'function') {
      try { renderPitch(); } catch(e){}
    }
    if (typeof renderBench === 'function') {
      try { renderBench(); } catch(e){}
    }
  } catch(e) { console.warn('roster refresh hatası:', e); }

  // NOT: _isFriendly ve _fixtureRef'i showMatchResult kullanıyor — temizlemiyoruz
  // Overlay kapatılınca closeMatchScreen çağrılırsa otomatik temizlenir
}

// 🆕 toggleSpeed / skipToEnd kaldırıldı — kullanıcı maçı hızlandıramaz/atlayamaz

// ═══════════ ENGINE TAB SWITCH ═══════════
function showEngTab(name,el){
  ['tactic','events','stats','lineup'].forEach(t=>{
    const tabEl = document.getElementById('eng-'+t);
    if (tabEl) tabEl.style.display = (t===name ? 'block' : 'none');
  });
  document.querySelectorAll('.eng-tab').forEach(t=>t.classList.remove('active'));
  if(el)el.classList.add('active');
  // 🆕 Taktik sekmesine geçince pitch + bench render et (PRE durumunda da drag çalışsın)
  if (name === 'tactic') {
    try {
      if (typeof MS !== 'undefined' && MS) {
        // initTacticControls hiç çağrılmadıysa default değerler
        if (typeof MS.subsLeft !== 'number') MS.subsLeft = 5;
        // 🆕 Varsayılan "açık" DEĞİL — yetkiye göre hesaplanır (izleyicide kapalı)
        MS._tacticControlsActive = (typeof _msCanControlTactics === 'function') ? _msCanControlTactics() : false;
        // 587 — maç taktiği modu (yalnız bu maç): eskiden hiç açılmıyordu (initTacticControls çağrılmıyor)
        try { if (MS._tacticControlsActive && typeof macTaktikModuAc === 'function') macTaktikModuAc(true); } catch(e) {}
        // Panelleri de duruma göre göster (izleyici paneli / kaptan paneli)
        try {
          const _cp = document.getElementById('tacCaptainPanel');
          const _vp = document.getElementById('tacViewerPanel');
          if (_cp && _vp) {
            _cp.style.display = 'block';
            _cp.classList.toggle('tac-readonly', !MS._tacticControlsActive);
            _vp.style.display = MS._tacticControlsActive ? 'none' : 'flex';
          }
        } catch(e) {}
      }
      if (typeof renderMatchSubPitch === 'function') renderMatchSubPitch();
      if (typeof renderMatchSubBench === 'function') renderMatchSubBench();
      if (typeof refreshQuickStratUI === 'function') refreshQuickStratUI();
      if (typeof updateMatchTacticSummary === 'function') updateMatchTacticSummary();
      if (typeof renderTacFormationMaps === 'function') renderTacFormationMaps();
    } catch(e) { console.warn('Taktik tab render hatası:', e); }
  }
}

// 🆕 Taktik alt-sekmeleri (Diziliş / Formasyon / Strateji)
function tacSubTab(name, el) {
  ['lineup','formation','strategy'].forEach(t => {
    const sub = document.getElementById('tacSub-' + t);
    if (sub) sub.style.display = (t === name ? 'block' : 'none');
  });
  document.querySelectorAll('.tac-subtab').forEach(t => t.classList.remove('active'));
  if (el) el.classList.add('active');
  try {
    if (name === 'lineup') {
      if (typeof renderMatchSubPitch === 'function') renderMatchSubPitch();
      if (typeof renderMatchSubBench === 'function') renderMatchSubBench();
    } else if (name === 'formation') {
      if (typeof renderTacFormationMaps === 'function') renderTacFormationMaps();
    } else if (name === 'strategy') {
      if (typeof refreshQuickStratUI === 'function') refreshQuickStratUI();
      if (typeof updateMatchTacticSummary === 'function') updateMatchTacticSummary();
    }
  } catch(e) { console.warn('tacSubTab render hatası:', e); }
}

// 🆕 Görsel formasyon haritaları — her formasyonu mini sahada nokta dizilişiyle göster
function renderTacFormationMaps() {
  // 574 — Gece Mavisi: formasyon çipleri → sahada önizleme → "Uygula"
  const grid = document.getElementById('tacFmapGrid');
  if (!grid || typeof FORMATIONS === 'undefined') return;
  const active = _gmAktifFormasyon();
  const sec = (typeof MS !== 'undefined' && MS && MS._gmFmSec && FORMATIONS[MS._gmFmSec]) ? MS._gmFmSec : active;
  grid.innerHTML = Object.keys(FORMATIONS).map(f => {
    const alt = (f === active) ? '<small>✓ Aktif</small>' : `<small data-noi18n>${fmTurAd((FM_BILGI[f] && FM_BILGI[f].tur) || '')}</small>`;   // 585 — kulüp/milli seçiciyle aynı tür ve mini saha
    return `<div class="gm-fm${f === active ? ' akt' : ''}${f === sec ? ' sec' : ''}" onclick="gmFmSec('${f}')">${fmMiniSaha(f, 'fm-mini')}<b data-noi18n>${f}</b>${alt}</div>`;
  }).join('');
  const ak = document.getElementById('gmFmAktif'); if (ak) ak.innerHTML = `<span>Aktif</span>: <span data-noi18n>${active}</span>`;
  _gmFmOnizle(sec);
  const not = document.getElementById('gmFmNot');
  if (not) not.innerHTML = `⚡ <span><b data-noi18n>${sec}</b> · <span>${(FM_BILGI[sec] && FM_BILGI[sec].guc) || ''}</span>. <span>Değişiklik maçın kalan dakikalarına etki eder.</span></span>`;
  const bt = document.getElementById('gmFmUygula');
  if (bt) bt.style.display = 'none';   // 587 — Uygula kaptan bandında (değişiklik hakkının yanında)
  try { if (typeof _gmModBant === 'function') _gmModBant(); } catch(e) {}
  // kaydırılabilir listede seçili çip görünür olsun
  try { const el = grid.querySelector('.gm-fm.sec'); if (el && el.scrollIntoView) el.scrollIntoView({ block: 'nearest', inline: 'center' }); } catch(e) {}
}

