function _cnAnahtarAl(n) { return n.nodeType === 1 ? (n.getAttribute('data-k') || n.getAttribute('data-mk')) : null; }
function _cnMorf(e, y) {
  if (e.nodeType === 3 || e.nodeType === 8) { if (e.nodeValue !== y.nodeValue) e.nodeValue = y.nodeValue; return; }
  if (e.tagName === 'CANVAS') {   // tuvalin çizimi kendisinde (röportaj sahnesi): başka sahneyse yeniden çizilir
    const rp = y.getAttribute('data-rp') || '';
    if (e.getAttribute('data-rp') !== rp) { e.setAttribute('data-rp', rp); e.removeAttribute('data-ok'); }
    return;
  }
  for (const a of Array.from(e.attributes)) if (!y.hasAttribute(a.name)) e.removeAttribute(a.name);
  for (const a of Array.from(y.attributes)) if (e.getAttribute(a.name) !== a.value) e.setAttribute(a.name, a.value);
  _cnMorfCocuk(e, y);
}
function _cnMorfCocuk(eski, yeni) {
  const ec = Array.from(eski.childNodes), yc = Array.from(yeni.childNodes), harita = new Map(), kul = new Set();
  ec.forEach(n => { const k = _cnAnahtarAl(n); if (k && !harita.has(k)) harita.set(k, n); });
  let i = 0;
  const son = yc.map(y => {
    const k = _cnAnahtarAl(y);
    let e = k ? harita.get(k) : null;
    if (!k) { while (i < ec.length && (kul.has(ec[i]) || _cnAnahtarAl(ec[i]))) i++; e = ec[i++]; }
    if (!e || kul.has(e) || e.nodeType !== y.nodeType || e.nodeName !== y.nodeName) return y;
    kul.add(e); _cnMorf(e, y); return e;
  });
  ec.forEach(n => { if (!kul.has(n)) n.remove(); });
  son.forEach((n, j) => { if (eski.childNodes[j] !== n) eski.insertBefore(n, eski.childNodes[j] || null); });
}
