      a: h.ilk && h.rov ? `<span>Rövanş</span> <b class="cn-sk-b">${_cnCmSaat(Number(h.rov))}</b>` : `<span>${_CN_KUPA_AD[h.k]}</span> · <span>${_CN_TUR_AD[h.f] || ''}</span>`,
