// 776 — Manşet röportajları: en yeni transferler. Manşete çıkan en az 3 saat kalır; daha yeni transfer gelince süresini
//   dolduran yerini ona bırakır; daha yeni röportaj varken 6 saati geçen manşette kalmaz.
//   Yalnız transfer saatlerinden hesaplanır: herkes aynı manşeti görür.
const _CN_ROP_SURE = 3 * 36e5;
function _cnRopSec(liste, simdi) {
  const L = liste.slice().sort((a, b) => a.z - b.z), yer = [], bek = [];
  const ilerle = t => {   // t anına kadar süresi dolan yerlere o ana kadar gelmiş en yeni bekleyen
    for (;;) {
      const s = bek.length ? yer.filter(x => x.bas + _CN_ROP_SURE <= t).sort((a, b) => a.bas - b.bas)[0] : null;
      if (!s) return;
      s.o = bek.pop(); s.bas += _CN_ROP_SURE; bek.length = 0;
    }
  };
  for (const r of L) {
    ilerle(r.z);
    const s = yer.length < 2 ? null : yer.filter(x => x.bas + _CN_ROP_SURE <= r.z).sort((a, b) => a.bas - b.bas)[0];
    if (yer.length < 2) yer.push({ o: r, bas: r.z });
    else if (s) { s.o = r; s.bas = r.z; }
    else bek.push(r);
  }
  ilerle(simdi);
  // Daha yeni röportaj manşetteyken 6 saati geçen eski röportaj ikinci sırada kalmaz
  return yer.map(x => x.o).sort((a, b) => b.z - a.z).filter((x, i) => i === 0 || simdi - x.z <= 6 * 36e5);
}
