// Generate groups HTML — full stats table
function trnBuildGroups(teams, containerId){
  const container = document.getElementById(containerId);
  if(!container) return;
  const letters = ['A','B','C','D','E','F','G','H'];
  container.innerHTML = teams.map((grp, gi) => {
    // Sort: puan > averaj > atılan gol
    const sorted = [...grp].sort((a,b)=>{
      if(b.p!==a.p) return b.p-a.p;
      const avgB=(b.gf-b.ga), avgA=(a.gf-a.ga);
      if(avgB!==avgA) return avgB-avgA;
      return b.gf-a.gf;
    });
    const colHdr = `<div class="group-col-hdr">
      <span>#</span><span>${window._ligKolon().t}</span><span>${window._ligKolon().o}</span><span>${window._ligKolon().g}</span><span>${window._ligKolon().b}</span><span>${window._ligKolon().m}</span><span>${window._ligKolon().ay}</span><span>${window._ligKolon().av}</span><span>${window._ligKolon().p}</span>
    </div>`;
    const rows = sorted.map((t,ti) => {
      const isUser = t.isUser;
      const isQ = ti < 2; // İlk 2 geçer
      const avg = t.gf - t.ga;
      const avgStr = avg > 0 ? '+'+avg : avg;
      const rowBg = isUser ? 'background:rgba(0,230,118,.06)' : '';
      const ptColor = isQ ? 'color:var(--accent)' : '';
      const nameColor = isUser ? 'color:var(--accent)' : isQ ? 'color:var(--text)' : 'color:var(--text2)';
      return `<div class="group-team-row" style="${rowBg}">
        <div style="font-size:10px;color:${isQ?'var(--accent)':'var(--text3)'};font-weight:700;text-align:center">${ti+1}</div>
        <div class="gtr-name" style="${nameColor};${isUser?'font-weight:800':''}">${t.n}</div>
        <div class="gtr-num">${t.w+t.d+t.l}</div>
        <div class="gtr-num" style="color:var(--accent)">${t.w}</div>
        <div class="gtr-num" style="color:var(--gold)">${t.d}</div>
        <div class="gtr-num" style="color:var(--red)">${t.l}</div>
        <div class="gtr-num">${t.gf}:${t.ga}</div>
        <div class="gtr-avg" style="${avg>0?'color:var(--accent)':avg<0?'color:var(--red)':''}">${avgStr}</div>
        <div class="gtr-pts" style="${ptColor}">${t.p}</div>
      </div>`;
    }).join('');
    return `<div class="group-card">
      <div class="group-header" style="background:rgba(255,214,0,.06);color:var(--gold)">
        <span>Grup ${letters[gi]}</span>
        <span style="font-size:10px;color:var(--text3);font-weight:400;margin-left:auto">İlk 2 geçer</span>
      </div>
      ${colHdr}${rows}
    </div>`;
  }).join('');
}

// Generate bracket HTML
function trnBuildBracket(containerId, rounds){
  const container = document.getElementById(containerId);
  if(!container) return;
  container.innerHTML = rounds.map(r => `
    <div class="bracket-round">
      <div class="br-round-title">${r.name}</div>
      ${r.matches.map(m => `
        <div class="br-match">
          <div class="br-team ${m.winner===0?'winner':''}">
            <div class="br-team-logo" style="background:${m.teams[0].c};color:${m.teams[0].t}">${m.teams[0].n.substring(0,3).toUpperCase()}</div>
            <div class="br-team-name">${m.teams[0].n}</div>
            <div class="br-score">${m.scores[0]}</div>
          </div>
          <div class="br-team ${m.winner===1?'winner':''}">
            <div class="br-team-logo" style="background:${m.teams[1].c};color:${m.teams[1].t}">${m.teams[1].n.substring(0,3).toUpperCase()}</div>
            <div class="br-team-name">${m.teams[1].n}</div>
            <div class="br-score">${m.scores[1]}</div>
          </div>
        </div>`).join('')}
    </div>`).join('');
}

// Schedule list
function trnBuildSchedule(){
  const list = document.getElementById('trnScheduleList');
  if(!list) return;
  // Bu eski tek-tab schedule artık kullanılmıyor — yeni trn2 sayfası dinamik üretiyor.
  // Sezon başlamadıysa veya turnuva başlamadıysa bekleme mesajı göster.
  const info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : { preSeason: true, daysToStart: 0 };
  if(info.preSeason) {
    list.innerHTML = `<div style="text-align:center;padding:32px 16px;color:var(--text2)">
      <div style="font-size:38px;margin-bottom:10px">⏳</div>
      <div style="font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;font-size:18px;font-weight:900;color:var(--text);margin-bottom:6px">Turnuvalar Henüz Başlamadı</div>
      <div style="font-size:11px;line-height:1.5">Sezon 1 başlangıcına <b>${info.daysToStart||0} gün</b>. Lig sonunda hak kazanan takımlar turnuvalara katılır.</div>
    </div>`;
  } else {
    list.innerHTML = `<div style="text-align:center;padding:24px 16px;color:var(--text2);font-size:12px">Turnuva fikstürü "Turnuvalar" menüsünde görüntülenebilir.</div>`;
  }
}

