// Tab switching
function trnTab(name, el){
  ['championship','elite','convergence','schedule'].forEach(t=>{
    const el2 = document.getElementById('trn-'+t);
    if(el2) el2.style.display = t===name?'block':'none';
  });
  document.querySelectorAll('.trn-tab').forEach(t=>t.classList.remove('active'));
  el.classList.add('active');

  if(name==='championship'){
    trnBuildGroups(TRN_DATA.championship.teams, 'trnGroups');
    trnBuildBracket('trnBracket', bracketRounds16);
  }
  if(name==='elite'){
    trnBuildGroups(TRN_DATA.championship.teams.slice(0,4), 'trnGroupsElite');
  }
  if(name==='convergence'){
    trnBuildGroups(TRN_DATA.championship.teams.slice(4,8),'trnGroupsConv');
  }
  if(name==='schedule') trnBuildSchedule();
}

