function togglePw(id, btn){
  const inp = document.getElementById(id);
  if(inp.type==='password'){ inp.type='text'; btn.textContent='🙈'; }
  else{ inp.type='password'; btn.textContent='👁'; }
}

function checkPwStrength(pw){
  const bar = document.getElementById('pwStrength');
  if(!pw){ bar.className='pw-strength'; return; }
  if(pw.length < 6){ bar.className='pw-strength pw-weak'; return; }
  const hasUpper=/[A-Z]/.test(pw), hasNum=/[0-9]/.test(pw), hasSpecial=/[^A-Za-z0-9]/.test(pw);
  if(pw.length>=8 && hasUpper && hasNum && hasSpecial) bar.className='pw-strength pw-strong';
  else if(pw.length>=8 && (hasNum||hasSpecial)) bar.className='pw-strength pw-medium';
  else bar.className='pw-strength pw-weak';
}

