function confirmAvatarChange() {
  if(!_avatarModalSelected || !authUser) return;
  if(_avatarModalSelected === authUser.avatarId) { closeAvatarChangeModal(); return; }
  { const _sa = AVATAR_OPTIONS.find(a => a.id === _avatarModalSelected);
    if (!_sa || (_avatarKendiCins() && _sa.gender !== _avatarKendiCins())) return; }

  // 🆕 Avatar değişim ücreti — CÜZDAN (user_wallet)
  const AVATAR_CHANGE_COST = 100;
  const _wlBal = (typeof wlGetData === 'function') ? (wlGetData().dia || 0) : 0;
  if (_wlBal < AVATAR_CHANGE_COST) {
    if (typeof cftConfirm === 'function') {
      cftConfirm({
        title: 'Yetersiz Diamond',
        message: `Avatar değişimi için ${AVATAR_CHANGE_COST} 💎 gerekli ama sende sadece ${_wlBal.toLocaleString('tr')} 💎 var.`,
        confirmText: 'Tamam',
        cancelText: '',
        danger: true,
        onConfirm: () => {}
      });
    }
    return;
  }
  const _wlOk = (typeof wlDeduct === 'function')
    ? wlDeduct('dia', AVATAR_CHANGE_COST, `Avatar Değişimi`)
    : false;
  if (!_wlOk) return;

  authUser.avatarId = _avatarModalSelected;

  // 🆕 Supabase'e KALICI yaz — players kanonik (avatar_id)
  (async () => {
    try {
      if (!window.sb || !authUser.id) return;
      await window.sb.from('players').update({ avatar_id: _avatarModalSelected }).eq('user_id', authUser.id);
    } catch(e) { console.warn('[avatarChange] Supabase update hata:', e); }
  })();

  // Player sayfasındaki avatarı yenile
  if(typeof renderPlayerPage === 'function') renderPlayerPage();

  // 🆕 CFC Media sayfası açıksa avatar görünümünü tazele
  try {
    const cfcPage = document.getElementById('page-cfc-media');
    if (cfcPage && cfcPage.classList.contains('active') && typeof cfcMdRender === 'function') {
      cfcMdRender();
    }
  } catch(e) {}

  closeAvatarChangeModal();

  // Toast
  const t = document.createElement('div');
  t.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:linear-gradient(135deg,#388e3c,#4caf50);color:#fff;padding:12px 22px;border-radius:24px;font-size:13px;font-weight:700;z-index:9999;font-family:Twemoji Country Flags,"Barlow Condensed",sans-serif;letter-spacing:.4px;box-shadow:0 8px 24px rgba(0,0,0,.4)';
  t.textContent = '🎭 Avatar güncellendi!';
  document.body.appendChild(t);
  setTimeout(() => { t.style.transition='opacity .4s'; t.style.opacity='0'; setTimeout(()=>t.remove(),400); }, 2000);
}

