    const _sil = () => { try { Object.keys(localStorage).forEach(k => { if (/^sb-.*-auth-token/.test(k)) localStorage.removeItem(k); }); } catch(e) {} };
    try { if (window.sb) window.sb.auth.signOut().then(r => { if (r && r.error) _sil(); }, _sil); } catch(e) { _sil(); }
