// Oyuncuyu kov — custom confirm modal aç
let _pendingKickNum = null;

// 🆕 Minimum kadro boyutu — 11'in altına düşmek yasak
const ROSTER_MIN_SIZE = 12;

function rosterKickPlayer(playerNum){
  // Ziyaretçi modunda çalışmaz
  if(typeof _viewingTeam !== 'undefined' && _viewingTeam) return;
  if(!_userTeam || _userTeam.role !== 'captain'){ rosterToast('🔒 Sadece kaptan oyuncu kovabilir.', 'err'); return; }
  const p = ROSTER_DATA.find(p => p.num === playerNum);
  if(!p){ rosterToast('Oyuncu bulunamadı.', 'err'); return; }
  if(p.role === 'user'){ rosterToast('Kendini kovamazsın.', 'err'); return; }
  if(p.role === 'captain'){ rosterToast('Kaptan kovulamaz.', 'err'); return; }

  // 🆕 Minimum kadro kontrolü — kov sonrası 11'in altına düşemez
  if(ROSTER_DATA.length <= ROSTER_MIN_SIZE){
    rosterToast(`⚠️ Kadroda en az ${ROSTER_MIN_SIZE} oyuncu olmalı. Önce yeni oyuncu transfer et.`, 'err');
    return;
  }

  // 🆕 525 — Satış listesindeki oyuncu kovulamaz. Eskiden kovulan oyuncunun
  //   ilanı transfer listesinde asılı kalıyordu.
  try {
    const _ilan = (typeof _kdTfIlan === 'function') ? _kdTfIlan(p, _userTeam.teamName) : null;
    if (_ilan) {
      if (typeof closePlayerModal === 'function') closePlayerModal();
      if (typeof showInfoModal === 'function') {
        showInfoModal({
          icon: '🏷️', iconColor: '#f59e0b',
          title: 'Oyuncu Satış Listesinde',
          subtitle: '<span data-noi18n>' + _escapeHtml(p.name) + '</span>',
          body: '<div class="info-modal-rows"><div class="info-modal-row"><div class="info-modal-row-ic">🚫</div>'
              + '<div class="info-modal-row-body"><div class="info-modal-row-val" style="font-size:14px">Satış listesindeki oyuncu kovulamaz.</div></div></div></div>'
              + '<div class="info-modal-note">Önce oyuncuyu satış listesinden çıkar, sonra takımdan kovabilirsin.</div>',
          btnText: 'Anladım'
        });
      } else {
        rosterToast('Satış listesindeki oyuncu kovulamaz. Önce satış listesinden çıkar.', 'err');
      }
      return;
    }
  } catch(e) {}

  // Custom confirm modal aç
  _pendingKickNum = playerNum;
  const msgEl = document.getElementById('kickConfirmMsg');
  if(msgEl){
    msgEl.innerHTML = `<b>${_escapeHtml(p.name)}</b> kişisini kovacaksınız.<br><span style="font-size:12px;color:var(--text2)">Emin misiniz?</span>`;
  }
  _kickHakedisGoster(p);
  const ov = document.getElementById('kickConfirmOverlay');
  if(ov) ov.classList.add('open');
  // Player modal'ı arka planda kapat
  if(typeof closePlayerModal === 'function') closePlayerModal();
}

// 679 — kovulan gerçek oyuncunun son maaş gününden bugüne hakedişi (+ maaş borcu) takım kasasından ödenir
async function _kickHakedisGoster(p){
  const el = document.getElementById('kickConfirmPay');
  if (!el) return;
  el.style.display = 'none'; el.innerHTML = '';
  if (!window.sb || !p || !p.id || p.isBot || !(p.userId || p.user_id)) return;
  const { data, error } = await window.sb.rpc('kovma_hakedis', { target_player_id: p.id });
  if (error || !data || data.error || _pendingKickNum !== p.num) return;
  const borc = Number(data.borc) > 0 ? ' · <span>Maaş borcu dahil</span>' : '';
  el.innerHTML = `<span>Kalan maaş ödemesi<small><span>${Number(data.gun) || 0} gün</span>${borc}</small></span><b data-noi18n>${(Number(data.tutar) || 0).toLocaleString('tr')} €</b>`;
  el.style.display = '';
}

// Kov onay modal'ını kapat (vazgeç)
function closeKickConfirm(){
  _pendingKickNum = null;
  const ov = document.getElementById('kickConfirmOverlay');
  if(ov) ov.classList.remove('open');
}

// Kov işlemini gerçekleştir (Onay Ver)
async function executeKick(){
  const num = _pendingKickNum;
  _pendingKickNum = null;
  // Modal'ı kapat
  const ov = document.getElementById('kickConfirmOverlay');
  if(ov) ov.classList.remove('open');

  if(num == null) return;
  if(typeof ROSTER_DATA === 'undefined') return;

  const p = ROSTER_DATA.find(x => x.num === num);
  if(!p){ rosterToast('Oyuncu bulunamadı.', 'err'); return; }
  if(p.role === 'user'){ rosterToast('Kendini kovamazsın.', 'err'); return; }
  if(p.role === 'captain'){ rosterToast('Kaptan kovulamaz.', 'err'); return; }

  // 🆕 Minimum kadro çift kontrolü (modal açıkken kadro değişmiş olabilir)
  if(ROSTER_DATA.length <= ROSTER_MIN_SIZE){
    rosterToast(`⚠️ Kadroda en az ${ROSTER_MIN_SIZE} oyuncu olmalı.`, 'err');
    return;
  }

  // 681 — önce sunucu: kovma (ve kalan maaş ödemesi) gerçekleşmeden kadro ve diziliş değiştirilmez,
  //   başarı gösterilmez (eskiden ekran önce güncelleniyor, sunucu reddederse diziliş bozuk kalıyordu)
  if (!window.sb || !p.id) { rosterToast('Oyuncu bulunamadı.', 'err'); return; }
  const { error: _kErr } = await window.sb.rpc('team_kick_member', { target_player_id: p.id });
  if (_kErr) {
    rosterToast(/kasa_yetersiz/.test(_kErr.message || '') ? 'Kasada kalan maaşı ödeyecek kadar para yok.' : 'Kov başarısız: ' + _kErr.message, 'err');
    return;
  }
  if (typeof _trsLoadFromServer === 'function') _trsLoadFromServer().then(() => { if (typeof trsRender === 'function') trsRender(); if (typeof trsSyncHeader === 'function') trsSyncHeader(); });
  kadroYayin('oyuncu', p.id);   // 768 — takımdakiler oyuncuyu hemen çıkarır

  // Lokal ROSTER_DATA'dan çıkar (UI hemen güncellensin)
  const idx = ROSTER_DATA.findIndex(x => x.num === num);
  if(idx < 0) return;
  ROSTER_DATA.splice(idx, 1);

  // 🆕 DİZİLİŞ + BENCH TEMİZLİĞİ
  // 1) Kovulan oyuncu ilk 11'de ise, slot boş kalmasın → bench'ten otomatik yedek geçir
  // 2) Bench'te ise, sadece bench'ten çıkar
  let lineupChanged = false;
  try {
    if (typeof activePitchPlayers !== 'undefined' && Array.isArray(activePitchPlayers)) {
      const pIdx = activePitchPlayers.findIndex(e => e && e.player && e.player.num === num);
      if (pIdx !== -1) {
        const removedSlot = activePitchPlayers[pIdx];
        activePitchPlayers.splice(pIdx, 1);
        lineupChanged = true;

        // Aynı pos grubundan bench'te oyuncu varsa otomatik geçir
        if (typeof benchPlayers !== 'undefined' && Array.isArray(benchPlayers) && removedSlot.slotIdx != null) {
          const POSGRP = (typeof POS_GROUP !== 'undefined') ? POS_GROUP : {};
          const slotPos = removedSlot.pos;
          const slotGrp = POSGRP[slotPos];
          // Önce tam pos uyumlu yedek ara, yoksa aynı pos grubundan al
          const _uy = b => b && !(typeof _kadroUygunsuzlukMetni === 'function' && _kadroUygunsuzlukMetni(b));
          let replIdx = benchPlayers.findIndex(b => _uy(b) && b.pos === slotPos);
          if (replIdx === -1 && slotGrp) {
            replIdx = benchPlayers.findIndex(b => _uy(b) && (POSGRP[b.pos] === slotGrp));
          }
          if (replIdx !== -1) {
            const repl = benchPlayers[replIdx];
            benchPlayers.splice(replIdx, 1);
            activePitchPlayers.push({
              rosterIdx: ROSTER_DATA.indexOf(repl),
              slotIdx: removedSlot.slotIdx,
              pos: removedSlot.pos,
              x: removedSlot.x,
              y: removedSlot.y,
              player: repl
            });
          }
        }
      }
    }
    // Bench'te ise sadece çıkar
    if (typeof benchPlayers !== 'undefined' && Array.isArray(benchPlayers)) {
      const bIdx = benchPlayers.findIndex(b => b && b.num === num);
      if (bIdx !== -1) {
        benchPlayers.splice(bIdx, 1);
        lineupChanged = true;
      }
    }
    // Saha veya bench değişti → kaydet
    if (lineupChanged) {
      if (typeof saveTeamStrategy === 'function') saveTeamStrategy();
      if (typeof renderPitch === 'function') renderPitch();
      if (typeof renderBench === 'function') renderBench();
    }
  } catch(e) { console.warn('[kick] diziliş temizlik hatası:', e); }

  if(typeof renderRoster === 'function') renderRoster(typeof rosterCurrentFilter !== 'undefined' ? (rosterCurrentFilter || 'all') : 'all');
  if(typeof applyUserTeamUI === 'function') applyUserTeamUI();

  // Bildirim
  const _maxR = (typeof getMaxRosterSize === 'function') ? getMaxRosterSize() : 15;
  rosterToast(`✅ ${p.name} kişisi takımdan çıkartıldı (kadro: ${ROSTER_DATA.length}/${_maxR}).`, 'ok');
}

