// Yedek bot oluştur (kov sonrası)
function rosterCreateReplacementBot(pos){
  if(!_userTeam) return null;
  const cc = _userTeam.countryCode;
  const namePool = (typeof NAMES_BY_COUNTRY !== 'undefined' && NAMES_BY_COUNTRY[cc])
    ? NAMES_BY_COUNTRY[cc] : (NAMES_BY_COUNTRY ? NAMES_BY_COUNTRY['EN'] : ['Yeni Bot']);
  // Mevcut isimlerle çakışmasın
  const existingNames = new Set(ROSTER_DATA.map(p => (p.name||'').toLowerCase()));
  const pool = namePool.filter(n => !existingNames.has(n.toLowerCase()));
  const name = pool[Math.floor(Math.random()*pool.length)] || ('Bot' + Date.now());

  const FLAG_BY_CC2 = {TR:'🇹🇷',ES:'🇪🇸',DE:'🇩🇪',FR:'🇫🇷',IT:'🇮🇹',PT:'🇵🇹',NL:'🇳🇱',BE:'🇧🇪',CH:'🇨🇭',SE:'🇸🇪',NO:'🇳🇴',DK:'🇩🇰',FI:'🇫🇮',IE:'🇮🇪',CZ:'🇨🇿',SK:'🇸🇰',AT:'🇦🇹',PL:'🇵🇱',HU:'🇭🇺',RO:'🇷🇴',BG:'🇧🇬',RU:'🇷🇺',UA:'🇺🇦',RS:'🇷🇸',HR:'🇭🇷',GR:'🇬🇷',IL:'🇮🇱',AZ:'🇦🇿',KZ:'🇰🇿',AL:'🇦🇱',EN:'🏴',SC:'🏴'};

  // Kullanılan numaralardan farklı bir numara
  const usedNums = new Set(ROSTER_DATA.map(p => p.num));
  let num = 30;
  while(usedNums.has(num)) num++;

  return {
    num,
    name,
    nation: FLAG_BY_CC2[cc] || '🏳️',
    nationality: cc,
    pos: pos || 'MID',
    level: 0, xp: 0, overall: 10,
    avatar: '🤖',
    role: 'member',
    isBot: true,
  };
}

function rosterToast(msg, kind){
  const t = document.createElement('div');
  const bg = kind === 'err' ? '#ef5350' : kind === 'ok' ? '#00c853' : '#0288d1';
  t.style.cssText = `position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:${bg};color:#fff;padding:10px 18px;border-radius:20px;font-size:13px;font-weight:700;z-index:9999;font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;letter-spacing:.4px;box-shadow:0 4px 14px rgba(0,0,0,.4)`;
  t.textContent = msg;
  document.body.appendChild(t);
  setTimeout(() => t.remove(), 2400);
}

