function showJoinToast(msg) {
  const t = document.createElement('div');
  t.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:linear-gradient(135deg,#388e3c,#4caf50);color:#fff;padding:12px 22px;border-radius:24px;font-size:13px;font-weight:700;z-index:9999;font-family:Twemoji Country Flags,"Barlow Condensed",sans-serif;letter-spacing:.4px;box-shadow:0 8px 24px rgba(0,0,0,.4)';
  t.textContent = msg;
  document.body.appendChild(t);
  setTimeout(() => { t.style.transition='opacity .4s'; t.style.opacity='0'; setTimeout(()=>t.remove(),400); }, 2500);
}

// ══ KATILMA İSTEKLERİ (Join Requests) ══
// Takımsız kullanıcının başka takımlara gönderdiği "katılmak istiyorum" istekleri.
// 🆕 Join requests: user_player.join_requests jsonb kolonunda tutulur
let _joinRequestsCache = null;
let _joinRequestsSaveTimer = null;

async function _joinRequestsLoadFromServer() {
  if (!window.sb || !authUser || !authUser.id) { _joinRequestsCache = []; return; }
  try {
    const { data } = await window.sb.from('user_player')
      .select('join_requests')
      .eq('user_id', authUser.id)
      .maybeSingle();
    _joinRequestsCache = Array.isArray(data?.join_requests) ? data.join_requests : [];
  } catch(e) { _joinRequestsCache = []; }
}

function getJoinRequests() {
  const l = Array.isArray(_joinRequestsCache) ? _joinRequestsCache : [];
  for (const r of l) if (r && r.status === 'pending' && _jrReddedildi(r)) r.status = 'rejected';
  return l;
}
// 679 — kaptan reddettiyse oyuncunun gelen kutusuna red mesajı gelir; istek artık bekliyor sayılmaz
function _jrReddedildi(r) {
  const msgs = (typeof getInboxMsgs === 'function' && getInboxMsgs()) || [];
  return msgs.some(m => {
    if (!m) return false;
    const y = m.joinReqResp;
    const ayni = y ? (y.countryCode === r.countryCode && y.teamName === r.teamName)
                   : m.subject === 'Katılma İsteğin Reddedildi — ' + r.teamName;
    const t = Number(m.ts) || Number(String(m.id || '').replace(/^jr_resp_no_/, '')) || 0;
    return ayni && t >= (Number(r.sentAt) || 0);
  });
}

function saveJoinRequests(list) {
  _joinRequestsCache = Array.isArray(list) ? list : [];
  if (window.sb && authUser && authUser.id) {
    clearTimeout(_joinRequestsSaveTimer);
    _joinRequestsSaveTimer = setTimeout(async () => {
      try {
        await window.sb.from('user_player').update({
          join_requests: _joinRequestsCache
        }).eq('user_id', authUser.id);
      } catch(e) { console.warn('[joinRequests] save hata:', e); }
    }, 500);
  }
}

// Bu takıma daha önce istek gönderdik mi?
function hasJoinRequestFor(countryCode, teamName) {
  return getJoinRequests().some(r =>
    r.countryCode === countryCode && r.teamName === teamName && r.status === 'pending'
  );
}

// 🆕 Başka takımın katılım politikasını çek (teams.join_policy) — cache'li
window._teamJoinPolicyCache = window._teamJoinPolicyCache || {};
async function _fetchTeamJoinPolicy(cc, tn){
  const key = cc+':'+tn;
  if(window._teamJoinPolicyCache[key]) return window._teamJoinPolicyCache[key];
  let pol = { contract:false, minSkill:0, minLevel:0 };
  try{
    if(window.sb){
      const { data } = await window.sb.from('teams').select('join_policy').eq('country_code',cc).eq('name',tn).maybeSingle();
      if(data && data.join_policy && typeof data.join_policy==='object'){
        pol = { contract: !!data.join_policy.contract, minSkill: Number(data.join_policy.minSkill)||0, minLevel: Number(data.join_policy.minLevel)||0 };
      }
    }
  }catch(e){ console.warn('[joinPolicy] cek hata:', e); }
  window._teamJoinPolicyCache[key] = pol;
  return pol;
}

// 🆕 Merkezî katılım kararı: bot→satın al; gerçek kaptan→şart karşılanırsa DİREKT (politikaya göre kontratlı/kontratsız), yoksa istek
async function _joinDecide(cc, tn, rating){
  if(typeof userHasTeam==='function' && userHasTeam()){ showNeedTeamToast('Zaten bir takımdasın. Önce takımdan ayrıl.'); return; }
  if(typeof _loadRealCaptainsFromServer === 'function'){ try{ if(typeof _invalidateRealCaptainsCache==='function') _invalidateRealCaptainsCache(); await _loadRealCaptainsFromServer(cc); }catch(e){} }
  const pol = getTeamCaptainType(cc, tn) === 'bot' ? { contract:false, minSkill:0, minLevel:0 } : await _fetchTeamJoinPolicy(cc, tn);
  const meets = (typeof userMeetsJoinRequirements==='function') ? userMeetsJoinRequirements({ minSkill: pol.minSkill, minLevel: pol.minLevel }) : true;
  _showJoinPolicyModal(cc, tn, pol, meets, rating);
}

// 🆕 Sözleşmesiz DİREKT katılım — canLeaveFreely:true kontrat (sistem maaşı alır, serbest çıkar)
function _doJoinFree(cc, tn){
  joinTeamDirect(cc, tn);   // 592 — sözleşmesiz üye: sözleşme kaydı yok, istediği an ayrılır
}

// 🆕 Katılım politikası modalı (eski "sadece satın al" uyarısı yerine)
function _showJoinPolicyModal(cc, tn, pol, meets, rating){
  const flag = (_cftGetCountry(cc)||{}).flag || '🏳️';
  const canDirect = (!pol.contract) && meets;
  let m = document.getElementById('joinPolicyModal'); if(m) m.remove();
  m = document.createElement('div'); m.id='joinPolicyModal';
  m.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.72);z-index:10000;display:flex;align-items:center;justify-content:center;padding:20px';
  m.onclick=(e)=>{ if(e.target===m) m.remove(); };
  let icon, desc, btnLabel, btnGrad;
  if(canDirect){
    icon='🤝'; btnLabel='🚀 Hemen Katıl'; btnGrad='linear-gradient(135deg,#00b357,#00e676)';
    desc='Bu takım <b>sözleşmesiz oyuncu kabul ediyor</b>. Hemen katılabilir, istediğin zaman ayrılabilirsin (sistem maaşını alırsın).';
  } else if(pol.contract){
    icon='📋'; btnLabel='📨 Katılım İsteği Gönder'; btnGrad='linear-gradient(135deg,#f57c00,#ff9800)';
    desc='Bu takım <b>sözleşmesiz oyuncu kabul etmiyor</b> (sözleşmeli takım). Katılmak için katılım isteği gönder; kaptan onaylarsa sözleşme imzalanır.';
  } else {
    icon='📨'; btnLabel='📨 Katılım İsteği Gönder'; btnGrad='linear-gradient(135deg,#f57c00,#ff9800)';
    desc='Bu takım sözleşmesiz katılıma açık ama <b>katılım şartlarını (min yetenek/seviye) karşılamıyorsun</b>. Kaptan onayı için katılım isteği gönder.';
  }
  m.innerHTML = `<div style="background:var(--card);border:1px solid var(--border);border-radius:16px;width:100%;max-width:340px;padding:22px 20px;text-align:center;font-family:Twemoji Country Flags,'Barlow',sans-serif;box-shadow:0 12px 40px rgba(0,0,0,.6)">
    <div style="font-size:40px;margin-bottom:8px">${icon}</div>
    <div style="font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;font-size:17px;font-weight:900;color:var(--text);line-height:1.25;margin-bottom:4px">${flag} ${tn}</div>
    <div style="font-size:12px;color:var(--text2);line-height:1.55;margin:10px 4px 18px">${desc}</div>
    <div style="display:flex;gap:8px">
      <button type="button" onclick="document.getElementById('joinPolicyModal').remove()" style="flex:1;padding:12px;background:rgba(255,255,255,.06);border:1px solid var(--border);border-radius:9px;color:var(--text2);font-weight:700;font-size:12px;cursor:pointer;font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;letter-spacing:.4px;text-transform:uppercase">Vazgeç</button>
      <button type="button" id="jpmGoBtn" style="flex:1.4;padding:12px;background:${btnGrad};border:none;border-radius:9px;color:#06120a;font-weight:900;font-size:12px;cursor:pointer;font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;letter-spacing:.4px;text-transform:uppercase">${btnLabel}</button>
    </div>
  </div>`;
  document.body.appendChild(m);
  const go = document.getElementById('jpmGoBtn');
  if(go) go.onclick = ()=>{
    m.remove();
    if(canDirect){ _doJoinFree(cc, tn); return; }
    if(typeof hasJoinRequestFor==='function' && hasJoinRequestFor(cc,tn)){ if(typeof showJoinToast==='function') showJoinToast(`📩 ${flag} ${tn} takımına zaten istek gönderdin (beklemede).`); return; }
    if(typeof openJoinRequestWithTermsModal==='function') openJoinRequestWithTermsModal(cc, tn, rating);
  };
}

// Guest banner'ından takıma katılım — duruma göre ya direkt katılır ya istek gönderir
function requestJoinFromGuest() {
  if(!_viewingTeam) return;
  // Disabled chip'e tıklamayı yoksay
  const chip = document.getElementById('thbJoinChip');
  if(chip && chip.dataset.disabled === '1') return;
  if(userHasTeam()) {
    showNeedTeamToast('Zaten bir takımdasın. Önce takımdan ayrıl.');
    return;
  }
  const cc = _viewingTeam.countryCode;
  const tn = _viewingTeam.teamRef.name;
  const rating = (_viewingTeam.rating != null) ? _viewingTeam.rating
               : (_viewingTeam.teamRef && _viewingTeam.teamRef.rating != null ? _viewingTeam.teamRef.rating : 0);
  // 🆕 Merkezî karar: bot→satın al; gerçek kaptan→şart karşılanırsa direkt (politika), yoksa istek
  _joinDecide(cc, tn, rating);
  return;
}

// (eski onay-isteği akışı openJoinRequestWithTermsModal'a taşındı)
function _requestJoinFromGuest_LEGACY() {
  if(!_viewingTeam) return;
  const cc = _viewingTeam.countryCode;
  const tn = _viewingTeam.teamRef.name;
  const flag = (_cftGetCountry(cc)||{}).flag || '🏳️';

  // Onay isteği akışı (mevcut)
  // Tekrar göndermeyi engelle
  if(hasJoinRequestFor(cc, tn)) {
    showJoinToast(`📩 ${flag} ${tn} takımına zaten istek gönderdin (beklemede).`);
    return;
  }

  // İsteği kaydet
  const list = getJoinRequests();
  list.unshift({
    id: 'jr_' + Date.now(),
    countryCode: cc,
    teamName: tn,
    flag,
    sentAt: Date.now(),
    sentDate: new Date().toLocaleDateString('tr'),
    status: 'pending',
  });
  saveJoinRequests(list);

  // Inbox'a giden mesaj olarak ekle (kullanıcı mesajlar sayfasında görsün)
  if(typeof getInboxMsgs === 'function' && typeof saveInboxMsgs === 'function') {
    const myName = (authUser||{}).name || 'Sen';
    const msgs = getInboxMsgs();
    msgs.unshift({
      id: 'jr_msg_' + Date.now(),
      from: myName,
      to: tn + ' Yönetimi',
      fromAvatar: '🤝',
      type: 'join_request',
      subject: `Katılma İsteği — ${tn}`,
      body: `${flag} ${tn} takımına katılma isteği gönderdin.\n\nTakım yönetimi (kaptan ve yardımcı kaptanlar) isteğini değerlendirip yanıt verecek. Yanıt geldiğinde mesajlarına bildirim düşecek.\n\nBu süreçte başka takımları görüntülemeye veya başka takımlara da istek göndermeye devam edebilirsin.`,
      time: new Date().toLocaleDateString('tr'),
      read: true,
      thread: [],
      sent: true,
      joinReqData: { countryCode: cc, teamName: tn },
    });
    saveInboxMsgs(msgs);
    if(typeof inboxUpdateBadge === 'function') inboxUpdateBadge();
  }

  showJoinToast(`🤝 ${flag} ${tn} takımına katılma isteği gönderildi!`);

  // Buton durumunu güncelle (artık "İstek Gönderildi" göster)
  const joinBtn = document.getElementById('thbJoinChip');
  if(joinBtn) {
    const txtEl = joinBtn.querySelector('.thb-join-text');
    const iconEl = joinBtn.querySelector('.thb-join-icon');
    if(iconEl) iconEl.textContent = '✓';
    if(txtEl) txtEl.textContent = 'İstek Gönderildi';
    joinBtn.style.background = 'rgba(102,187,106,.18)';
    joinBtn.style.borderColor = 'rgba(102,187,106,.4)';
    joinBtn.style.borderLeftColor = '#66bb6a';
    joinBtn.style.cursor = 'default';
    joinBtn.style.boxShadow = 'none';
    joinBtn.dataset.disabled = '1';
  }
}

// ── Kullanıcının takım durumuna göre UI'ı güncelle ──
// Takım sayfası, takım sekmeleri, banner, ROSTER_DATA hepsini koordine eder.
// 🆕 Hero bar: gerçek GLOBAL sıra (team_points) + taze puan — Supabase'ten (top-50 değil, tüm takımlar).
// 🆕 Takım puanı çarpan tablosu (frontend canlı hesap — edge TEAM_POINT_MULT ile birebir; tarayıcı/Deno modül paylaşamaz).
const _TP_MULT = { chm:[0.55,0.50,0.45], elit:[0.50,0.45,0.40], conv:[0.45,0.40,0.35], t1:[0.40,0.35,0.30], t2:[0.35,0.30,0.25], t3:[0.30,0.25,0.20], t4:[0.25,0.20,0.15], t5:[0.20,0.15,0.10], t6:[0.15,0.10,0.05] };
function _tpComp(tkey, tier){ if(tkey==='champ')return 'chm'; if(tkey==='elite')return 'elit'; if(tkey==='conv')return 'conv'; if(tkey==null && tier>=1 && tier<=6)return 't'+tier; return null; }
function _tpAcc(rows, asHome){
  if(!Array.isArray(rows)) return 0;
  let p=0;
  for(const m of rows){
    const tkey=(m.data&&m.data.tournament_key)?m.data.tournament_key:null;
    const ck=_tpComp(tkey, m.tier); if(!ck) continue;
    const mult=_TP_MULT[ck];
    const hs=Number(m.home_score), as=Number(m.away_score);
    if(!Number.isFinite(hs)||!Number.isFinite(as)) continue;
    const res=asHome?(hs>as?0:hs===as?1:2):(as>hs?0:as===hs?1:2);
    p+=mult[res];
  }
  return p;
}
// 🆕 TEK KAYNAK: takımın GÜNCEL puanı (match_results'tan CANLI) + GLOBAL sırası (tüm takımlar).
async function _teamPointsRank(cc, name) {
  if (!window.sb || !name) return { rank: null, points: 0 };
  let pts = 0;
  try {
    // Puanı YENİDEN HESAPLAMA — teams.team_points'i (kayıtlı değer) oku
    let q = window.sb.from('teams').select('team_points').eq('name', name);
    if (cc) q = q.eq('country_code', cc);
    const { data } = await q.maybeSingle();
    if (data && Number.isFinite(Number(data.team_points))) pts = Number(data.team_points);
  } catch(e) {}
  let rank = null;
  try {
    const { count } = await window.sb.from('teams').select('*', { count: 'exact', head: true }).gt('team_points', pts);
    if (typeof count === 'number') rank = count + 1;
  } catch(e) {}
  return { rank, points: pts };
}
async function _updateTeamHeroRankPoints(cc, name) {
  if (!name) return;
  const { rank, points } = await _teamPointsRank(cc, name);
  const rankEl = document.getElementById('teamHeroRank');
  if (rankEl) rankEl.textContent = (rank != null) ? (rank + '.') : '—';
  const ptsEl = document.getElementById('teamHeroPoints');
  if (ptsEl) ptsEl.textContent = points.toFixed(2) + ' P';
}

function applyUserTeamUI() {
  // Takım sayfası — no-team panel veya hasTeamWrap göster
  // GUEST MODE: bir takımı ziyaret ediyorsak (takımsız bile olsa) hasTeamWrap göster
  const inGuestMode = !!(typeof _viewingTeam !== 'undefined' && _viewingTeam);
  const showTeamUI = userHasTeam() || inGuestMode;

  const noTeam = document.getElementById('noTeamPanel');
  const hasTeam = document.getElementById('hasTeamWrap');
  if(noTeam) noTeam.style.display = showTeamUI ? 'none' : 'flex';
  if(hasTeam) hasTeam.style.display = showTeamUI ? 'block' : 'none';

  // Takımlıysa team-roster hero-bar bilgilerini güncelle (guest modda hero guestRenderHeader'a aittir)
  if(userHasTeam() && _userTeam && !inGuestMode) {
    const cc = _userTeam.countryCode;
    const country = (true) ? _cftGetCountry(cc) : null;
    const flag = country ? country.flag : '🏳️';
    const lgName = (country && country.leagues && country.leagues[0]) ? country.leagues[0].name : 'Lig';

    // Takım rating / sıra hesabı
    let teamRank = '—';
    let teamRating = 50;
    if(country) {
      try {
        const teams = country.leagues[0].teams;
        const sorted = teams.slice().sort((a,b) => b.rating - a.rating);
        const idx = sorted.findIndex(t => t.name === _userTeam.teamName);
        if(idx >= 0) teamRank = (idx + 1) + '.';
        const t = teams.find(t => t.name === _userTeam.teamName);
        if(t) teamRating = t.rating;
      } catch(e) {}
    }

    // Takım kısaltması (logo)
    const shortName = _userTeam.teamName.slice(0, 3).toUpperCase();

    const set = (id, val) => { const el = document.getElementById(id); if(el) el.textContent = val; };
    // 🆕 Logo varsa hero logo'ya img koy, yoksa short text
    if (typeof applyCrestToEl === 'function') {
      applyCrestToEl(document.getElementById('teamHeroLogo'), _userTeam.teamName, shortName);
    } else {
      set('teamHeroLogo', shortName);
    }
    set('teamHeroName', _userTeam.teamName);
    // 🆕 Lig satırı (sadece bayrak + lig adı)
    set('teamHeroMeta', `${flag} ${lgName}`);
    // 🆕 Kullanıcı adı (lig satırının altında)
    const _userName = (typeof authUser !== 'undefined' && authUser && authUser.name) ? authUser.name : '—';
    set('teamHeroUser', _userName);
    try { _bgnTakimHero(_userTeam.countryCode, _userTeam.teamName, false); } catch (e) {}   // 784
    set('teamHeroPlayers', String(ROSTER_DATA.length));
    // 🆕 Max kadro tesise göre (getMaxRosterSize: 14 + capacity_level)
    try {
      const maxR = (typeof getMaxRosterSize === 'function') ? getMaxRosterSize() : 15;
      set('teamHeroPlayersMax', String(maxR));
    } catch(e) {}

    // 🆕 Ort. Güç = takım OVR'si — sıralama ile AYNI kaynak (edge'in sakladığı team_ovr;
    //    oyuncuların seçtiği mevki-OVR ortalaması, level/xp karışmaz).
    set('teamHeroPower', _teamPowerFromPlayers(_userTeam.countryCode, _userTeam.teamName, 1));

    // 🆕 Genel Sıralama — TAKIM PUANI'na göre (getTop50Teams ile aynı kaynak)
    try {
      // 🆕 Gerçek global sıra + taze puan (top-50 sınırı kaldırıldı, Supabase'ten)
      if (typeof _updateTeamHeroRankPoints === 'function') {
        _updateTeamHeroRankPoints(_userTeam.countryCode, _userTeam.teamName);
      }
      const mvEl = document.getElementById('teamHeroMarket');
      if (mvEl && typeof calculateTeamValue === 'function') {
        const _mv = calculateTeamValue({ name: _userTeam.teamName, countryCode: _userTeam.countryCode }); // 🆕 kadrodaki oyuncuların gösterilen değerlerinin TOPLAMI (tek doğru)
        mvEl.textContent = (typeof _carFmtEUR === 'function') ? _carFmtEUR(_mv) : (_mv + ' €');
      }
    } catch(e) {}

    // 🆕 Hat güçleri (KL/DF/OS/FW) — hero bar barları
    try {
      if (typeof calcLineStrengths === 'function') {
        const ls = calcLineStrengths({ name: _userTeam.teamName, teamName: _userTeam.teamName });
        const setLine = (idVal, idBar, v) => {
          const valEl = document.getElementById(idVal);
          const barEl = document.getElementById(idBar);
          if (valEl) valEl.textContent = String(v);
          if (barEl) barEl.style.width = Math.max(0, Math.min(100, v)) + '%';
        };
        setLine('thbLineGK', 'thbLineGKBar', ls.GK);
        setLine('thbLineDF', 'thbLineDFBar', ls.DEF);
        setLine('thbLineMD', 'thbLineMDBar', ls.MID);
        setLine('thbLineFW', 'thbLineFWBar', ls.FWD);
      }
    } catch(e) {}

    // 🆕 Role strip render kaldırıldı (kullanıcı isteği — kaptan/yrd/gerçek/bot sayıları gösterilmeyecek)
  }

  // Body'ye role class'larını set et (CSS .captain-only için)
  try{
    document.body.classList.remove('team-captain', 'team-vice', 'team-member', 'team-none');
    if(userHasTeam() && _userTeam){
      if(_userTeam.role === 'captain') document.body.classList.add('team-captain');
      else if(_userTeam.role === 'vice') document.body.classList.add('team-vice');
      else document.body.classList.add('team-member');
    } else {
      document.body.classList.add('team-none');
    }
  }catch(e){}

  // Listing butonu güncelle (kaptansa "satıştaysa" durumunu yansıt)
  try{ if(typeof tmRefreshListButton === 'function') tmRefreshListButton(); }catch(e){}

  // Hero banner'ı tazele
  if(typeof updateHero === 'function') updateHero();
  // 🆕 Üst bar kulüp adı da yenilenir (takım değişiminde hemen yansır)
  if(typeof updateTopbarFromUser === 'function') updateTopbarFromUser();
  _tsaGuncelle();   // 699 — "Takımı Al" etiketi
}

