function privacyOpen(kind) {
  try {
    const ov = document.getElementById('privacyOverlay');
    const t  = document.getElementById('privacyTitle');
    const b  = document.getElementById('privacyBody');
    if (!ov || !b) return;
    const kosul = (kind === 'terms');
    if (t) t.textContent = kosul ? 'Kullanım Koşulları' : 'Gizlilik Politikası';
    b.innerHTML = kosul ? TERMS_TEXT : PRIVACY_TEXT;
    b.scrollTop = 0;
    ov.classList.add('open');
  } catch(e) { console.warn('[privacy] hata:', e); }
}
function privacyClose() {
  const ov = document.getElementById('privacyOverlay');
  if (ov) ov.classList.remove('open');
}
window.privacyOpen = privacyOpen;
window.privacyClose = privacyClose;

