function accDeleteOpen() {
  if (!window.authUser || !window.authUser.id) {
    if (typeof showToast === 'function') showToast('Önce giriş yapmalısın');
    return;
  }
  const ov = document.getElementById('accDelOverlay');
  const inp = document.getElementById('accDelInput');
  const err = document.getElementById('accDelErr');
  const btn = document.getElementById('accDelBtn');
  if (inp) inp.value = '';
  if (err) err.textContent = '';
  if (btn) { btn.disabled = true; btn.textContent = 'Hesabımı Sil'; }
  if (ov) ov.classList.add('open');
}
function accDeleteClose() {
  const ov = document.getElementById('accDelOverlay');
  if (ov) ov.classList.remove('open');
}
function accDeleteCheck() {
  const inp = document.getElementById('accDelInput');
  const btn = document.getElementById('accDelBtn');
  if (!inp || !btn) return;
  const v = (inp.value || '').trim();
  const kabul = ['SİL', 'SIL', T('SİL').toUpperCase()];
  btn.disabled = ![v.toLocaleUpperCase('tr'), v.toUpperCase()].some(a => kabul.includes(a));
}
async function accDeleteConfirm() {
  const btn = document.getElementById('accDelBtn');
  const err = document.getElementById('accDelErr');
  if (!window.authUser || !window.authUser.id) return;
  if (btn) { btn.disabled = true; btn.textContent = 'Siliniyor…'; }
  if (err) err.textContent = '';
  try {
    const _res = await edgeCall('delete_account', { confirm: 'SIL' });
    const r = { ok: _res.ok }; const d = _res.data;
    if (!r.ok || !d || d.error) {
      if (err) err.textContent = 'Silinemedi: ' + ((d && d.error) || 'sunucu hatası');
      if (btn) { btn.disabled = false; btn.textContent = 'Hesabımı Sil'; }
      return;
    }
    // Yerel izleri temizle + oturumu kapat
    try {
      const kalsin = [];
      const sil = [];
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (k && k.startsWith('cft_') && kalsin.indexOf(k) === -1) sil.push(k);
      }
      sil.forEach(k => { try { localStorage.removeItem(k); } catch(e) {} });
    } catch(e) {}
    try { if (window.sb) await window.sb.auth.signOut(); } catch(e) {}
    accDeleteClose();
    try { alert('Hesabın kalıcı olarak silindi. Oyun yeniden başlatılıyor.'); } catch(e) {}
    location.reload();
  } catch(e) {
    if (err) err.textContent = 'Sunucuya ulaşılamadı.';
    if (btn) { btn.disabled = false; btn.textContent = 'Hesabımı Sil'; }
  }
}
window.accDeleteOpen = accDeleteOpen;
window.accDeleteClose = accDeleteClose;
window.accDeleteCheck = accDeleteCheck;
window.accDeleteConfirm = accDeleteConfirm;

// 803 — Ayarlar › E-posta: e-postasız hesaba ekle ya da değiştir (şifre sıfırlama bu adrese gelir)
function epostaAyarAc() {
  const u = authUser || {}; if (!u.id) return;
  const gizli = !u.email || _GIZLI_EPOSTA.test(u.email);
  let ov = document.getElementById('epOv');
  if (!ov) { ov = document.createElement('div'); ov.id = 'epOv'; ov.className = 'ep-ov'; ov.onclick = (e) => { if (e.target === ov) epostaAyarKapat(); }; document.body.appendChild(ov); }
  ov.innerHTML = `<div class="ep-kutu"><div class="ep-bas"><b>${gizli ? 'E-posta ekle' : 'E-postanı değiştir'}</b><button type="button" onclick="epostaAyarKapat()" aria-label="Kapat">✕</button></div>`
    + `<p>Şifreni unutursan sıfırlama bağlantısı bu adrese gelir.</p>`
    + `<input class="auth-input" type="email" id="epGir" inputmode="email" autocomplete="email" autocapitalize="off" spellcheck="false" placeholder="ornek@mail.com" value="${gizli ? '' : _gkE(u.email)}">`
    + `<div class="ep-msg" id="epMsg"></div><button type="button" class="auth-submit" id="epKaydet" onclick="epostaAyarKaydet()">Kaydet</button></div>`;
  ov.classList.add('open');
  setTimeout(() => { try { document.getElementById('epGir').focus(); } catch (e) {} }, 60);
}
function epostaAyarKapat() { const ov = document.getElementById('epOv'); if (ov) ov.classList.remove('open'); }
async function epostaAyarKaydet() {
  const g = document.getElementById('epGir'), m = document.getElementById('epMsg'), b = document.getElementById('epKaydet');
  const v = String((g && g.value) || '').trim();
  const yaz = (t, ok) => { if (m) { m.textContent = t; m.className = 'ep-msg ' + (ok ? 'ok' : 'no'); } };
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v) || _GIZLI_EPOSTA.test(v)) { yaz('Geçerli bir e-posta adresi yaz.'); return; }
  if (!window.sb) return;
  b.disabled = true;
  try {
    const { data, error } = await window.sb.auth.updateUser({ email: v });
    if (error) { yaz(/already|registered|exists/i.test(error.message) ? 'Bu e-posta başka bir hesapta kullanılıyor.' : 'Kaydedilemedi: ' + error.message); return; }
    const yeni = (data && data.user && data.user.email) || '';
    if (yeni.toLowerCase() === v.toLowerCase()) { authUser.email = yeni; yaz('E-posta kaydedildi.', true); if (typeof renderSettings === 'function') renderSettings(); setTimeout(epostaAyarKapat, 900); }
    else yaz(v + ' adresine bir onay bağlantısı gönderildi. Bağlantıya basınca e-postan kaydedilir.', true);
  } catch (e) { yaz('Kaydedilemedi: ' + (e.message || e)); }
  finally { b.disabled = false; }
}
function renderSettings() {
  const u = authUser || {};
  const NAT_LABELS = CFT_NAT_LABELS;

  const set = (id, val) => { const el = document.getElementById(id); if(el) el.textContent = val; };

  set('setName', u.name || '—');
  set('setUsername', u.username ? '@' + u.username : '—');
  set('setEmail', (!u.email || _GIZLI_EPOSTA.test(u.email)) ? 'Ekle ›' : u.email + ' ›');   // 803
  set('setNationality', NAT_LABELS[u.nationality] || u.nationality || '—');
  set('setPosition', u.position ? SUBPOS_LABEL[subPosOf({ pos: u.position, sub_pos: u.subPos })] : '—');

  // (Takım bölümü ayarlardan kaldırıldı — takım yönetimi Takım sayfasından yapılır)

  // 🔔 538 — bildirim anahtarlarının durumunu yansıt
  try { if (typeof bldAyarlariYansit === 'function') bldAyarlariYansit(); } catch(e) {}
}


// ── Destek: Şikayet / İstek / Talep (placeholder) ──
// Admin paneli henüz yapılmadı — şimdilik kullanıcıya bilgi toast'ı gösterir.
// İleride: form modal'ı + admin paneline kaydet
// ═══════════════════════════════════════════════════════════════
// 🛡️ 643 — ŞİKAYET · ENGELLEME · KÜFÜR FİLTRESİ (Apple kural 1.2)
//   Şikayet → feedback tablosu ('sikayet'), yönetim panelinde görünür.
//   Engel → kullanici_engel (engelle / engel_kaldir / engel_listem RPC);
//   engellenenin özel mesajı sunucuda reddedilir, gönderi ve sohbetleri gizlenir.
//   Filtre: yasaklı kelimeler gönderilmeden önce ve ekranda ***** olur.
// ═══════════════════════════════════════════════════════════════
const _MOD_IK = {
  daha: '<svg viewBox="0 0 24 24" fill="currentColor"><circle cx="5" cy="12" r="2"/><circle cx="12" cy="12" r="2"/><circle cx="19" cy="12" r="2"/></svg>',
  bayrak: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 22V4"/><path d="M5 4h12l-2 4.5L17 13H5"/></svg>',
  engel: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="9"/><path d="M5.6 5.6l12.8 12.8"/></svg>',
};
const _MOD_KUFUR = new RegExp('(?<![\\p{L}\\p{N}_])(?:' + [
  // Türkçe
  'amk', 'amq', 'aq', 'mk', 'oç', 'am[ıi]n[ıia]', 'amc[ıi]k\\p{L}*', 's[ıi]kt[ıi]r\\p{L}*', 's[ıi]ker[ıi]m', 's[ıi]key[ıi]m',
  's[ıi]k[ıi]k\\p{L}*', 's[ıi]kt[ıi]m', 's[ıi]k[ıi][sş]\\p{L}*', 'yarra?k\\p{L}*', 'dalyarak\\p{L}*', 'orr?[ou]spu\\p{L}*',
  'piç\\p{L}*', 'pezevenk\\p{L}*', 'kahpe\\p{L}*', 'gavat\\p{L}*', 'ibne\\p{L}*', 'yav[sş]ak\\p{L}*', '[sş]erefsiz\\p{L}*',
  'g[öo]tveren\\p{L}*', 'g[öo]t[üu]n[üu]',
  // English
  'fuck\\p{L}*', 'motherfuck\\p{L}*', 'shit\\p{L}*', 'bullshit', 'bitch\\p{L}*', 'cunt\\p{L}*', 'asshole\\p{L}*',
  'bastard\\p{L}*', 'whore\\p{L}*', 'slut\\p{L}*', 'nigg(?:a|er)\\p{L}*', 'faggot\\p{L}*',
  // Deutsch
  'schei(?:ß|ss)e\\p{L}*', 'arschloch\\p{L}*', 'hurensohn\\p{L}*', 'fotze\\p{L}*', 'wichser\\p{L}*',
  // Español · Português
  'puta\\p{L}*', 'mierda\\p{L}*', 'cabr[oó]n\\p{L}*', 'gilipollas', 'coño', 'porra', 'caralho\\p{L}*', 'merda\\p{L}*', 'foda-?se',
  // Français · Italiano
  'putain\\p{L}*', 'merde\\p{L}*', 'connard\\p{L}*', 'salope\\p{L}*', 'encul[ée]\\p{L}*',
  'cazzo\\p{L}*', 'vaffanculo', 'stronz[oa]\\p{L}*', 'puttan[ae]\\p{L}*', 'minchia',
  // Русский
  'бля\\p{L}*', 'хуй\\p{L}*', 'хуё\\p{L}*', 'хуе[вс]\\p{L}*', 'пизд\\p{L}*', '[её]б(?:ан|ат|ал|ну)\\p{L}*', 'сук[аи]', 'мудак\\p{L}*',
].join('|') + ')(?![\\p{L}\\p{N}_])', 'giu');

function modFiltre(s) {
  const m = String(s == null ? '' : s);
  // Türkçe (İ→i, I→ı) ve genel küçük harf ayrı ayrı denenir: "SHIT" Türkçede "shıt" olurdu
  const gizle = new Uint8Array(m.length);
  let bulundu = false;
  for (const k of [m.toLocaleLowerCase('tr-TR'), m.toLowerCase(), m]) {
    if (k.length !== m.length) continue;
    for (const x of k.matchAll(_MOD_KUFUR)) { gizle.fill(1, x.index, x.index + x[0].length); bulundu = true; }
  }
  if (!bulundu) return m;
  let out = '';
  for (let i = 0; i < m.length; i++) out += gizle[i] ? '*' : m[i];
  return out;
}

// Engellenenler: hesap kimliği → bilgi; CSC Media kimliği ('user:<ad>') ayrıca tutulur
const _modEngel = new Map();
const _modEngelSosyal = new Set();
function modEngelliMi(id) {
  if (!id) return false;
  return _modEngel.has(id) || _modEngelSosyal.has(String(id).toLowerCase());
}
function _modEngelEkle(r) {
  _modEngel.set(r.uid, r);
  if (r.kullanici_adi) _modEngelSosyal.add('user:' + String(r.kullanici_adi).toLowerCase());
}
async function modEngelYukle() {
  const { data, error } = await window.sb.rpc('engel_listem');
  if (error) { console.warn('[engel] liste okunamadı:', error.message); return; }
  _modEngel.clear(); _modEngelSosyal.clear();
  (data || []).forEach(_modEngelEkle);
}

// Türkçe ad + belirtme (-i) / ilgi (-in) eki: Mert Demir'i, Kaya'nın
function _modEk(ad, ilgi) {
  const k = String(ad || '').toLocaleLowerCase('tr-TR');
  const sesli = (k.match(/[aeıioöuü]/g) || ['e']).pop();
  const v = { a: 'ı', ı: 'ı', e: 'i', i: 'i', o: 'u', u: 'u', ö: 'ü', ü: 'ü' }[sesli];
  const sonSesli = /[aeıioöuü]$/.test(k);
  return ad + "'" + (ilgi ? (sonSesli ? 'n' : '') + v + 'n' : (sonSesli ? 'y' : '') + v);
}

// Menüler satır içi onclick ile açılır; hedef bilgisi burada tutulur
const _modHedef = new Map();
let _modSira = 0;
function _modKayit(o) { const k = 'm' + (++_modSira); _modHedef.set(k, o); return k; }

function _modKapat() { const ov = document.getElementById('modOv'); if (ov) ov.remove(); }
let _modPopEl = null;   // 737 — menü bir düğmeden açıldıysa o köşede küçük pencere
function _modSheet(ic) {
  _modKapat();
  const ov = document.createElement('div');
  ov.id = 'modOv'; ov.className = 'mod-ov';
  ov.onclick = (e) => { if (e.target === ov) _modKapat(); };
  if (_modPopEl && _modPopEl.isConnected) {
    const r = _modPopEl.getBoundingClientRect();
    ov.className = 'mod-pop-ov';
    ov.innerHTML = `<div class="mod-pop" style="top:${Math.round(r.bottom + 4)}px;right:${Math.max(8, Math.round(window.innerWidth - r.right))}px">${ic}</div>`;
  } else ov.innerHTML = `<div class="mod-sheet"><div class="mod-tutamac"></div>${ic}</div>`;
  document.body.appendChild(ov);
}

const _MOD_SIKAYET_SATIR = { gonderi: 'Gönderiyi şikayet et', mesaj: 'Mesajı şikayet et', sohbet: 'Mesajı şikayet et', profil: 'Profili şikayet et' };
function modMenuAc(k, el) {
  const o = _modHedef.get(k);
  if (!o) return;
  _modPopEl = el || null;
  const engelli = modEngelliMi(o.hedef);
  _modSheet(`<button class="mod-satir" onclick="modSikayetAc('${k}')">${_MOD_IK.bayrak}${_MOD_SIKAYET_SATIR[o.tur]}</button>`
    + (engelli
      ? `<button class="mod-satir" onclick="modEngelKaldir('${k}')">${_MOD_IK.engel}Engeli kaldır</button>`
      : `<button class="mod-satir kirmizi" onclick="modEngelSor('${k}')">${_MOD_IK.engel}<span data-noi18n>${_cfcMdEscape(T(_modEk(o.ad, false) + ' engelle'))}</span></button>`)
    + `<button class="mod-vazgec" onclick="_modKapat()">Vazgeç</button>`);
}

const _MOD_SEBEP = ['Küfür veya hakaret', 'Taciz veya zorbalık', 'Spam veya reklam', 'Uygunsuz içerik', 'Diğer'];
function modSikayetAc(k) {
  _modSheet(`<div class="mod-baslik">Neden şikayet ediyorsun?</div>`
    + _MOD_SEBEP.map((s, i) => `<button class="mod-satir" onclick="modSikayetGonder('${k}',${i})">${s}</button>`).join('')
    + `<button class="mod-vazgec" onclick="_modKapat()">Vazgeç</button>`);
}
const _MOD_TUR_AD = { gonderi: 'CSC Media gönderisi', mesaj: 'Özel mesaj', sohbet: 'Takım sohbeti mesajı', profil: 'CSC Media profili' };
async function modSikayetGonder(k, i) {
  const o = _modHedef.get(k);
  _modKapat();
  const { error } = await window.sb.from('feedback').insert({
    user_id: authUser.id,
    username: authUser.name || authUser.username || null,
    type: 'sikayet',
    message: ('[İçerik şikayeti]\nSebep: ' + _MOD_SEBEP[i] + '\nTür: ' + _MOD_TUR_AD[o.tur]
      + '\nŞikayet edilen: ' + (o.ad || '—') + ' (' + o.hedef + ')'
      + (o.icerikId ? '\nKayıt: ' + o.icerikId : '') + (o.icerik ? '\nİçerik: ' + String(o.icerik) : '')).slice(0, 1000),
  });
  if (error) { console.warn('[şikayet] gönderilemedi:', error.message); rosterToast('Şikayet gönderilemedi.', 'warn'); return; }
  rosterToast('Şikayetin alındı.', 'ok');
}

function modEngelSor(k) {
  const o = _modHedef.get(k);
  _modKapat();
  const ov = document.createElement('div');
  ov.id = 'modOv'; ov.className = 'cfcmd-del-overlay open';
  if (_modPopEl) ov.style.zIndex = '7700';
  ov.onclick = (e) => { if (e.target === ov) _modKapat(); };
  ov.innerHTML = `<div class="cfcmd-del-modal" role="dialog" aria-modal="true">
      <div class="cfcmd-del-icon">${_MOD_IK.engel}</div>
      <div class="cfcmd-del-title">Engellensin mi?</div>
      <div class="cfcmd-del-sub" data-noi18n>${_cfcMdEscape(T(_modEk(o.ad, true) + ' gönderilerini ve mesajlarını artık görmezsin, sana mesaj gönderemez.'))}</div>
      <div class="cfcmd-del-btns"><button class="cfcmd-del-cancel" onclick="_modKapat()">İptal</button><button class="cfcmd-del-confirm" onclick="modEngelle('${k}')">Engelle</button></div>
    </div>`;
  document.body.appendChild(ov);
}

async function modEngelle(k) {
  const o = _modHedef.get(k);
  _modKapat();
  const { data, error } = await window.sb.rpc('engelle', { p_hedef: o.hedef });
  if (error || !data || !data.ok) { console.warn('[engel]', error ? error.message : data); rosterToast('Engellenemedi.', 'warn'); return; }
  _modEngelEkle(data);
  // Engellenenle özel konuşmalar gelen kutusundan kalkar
  const kutu = getInboxMsgs();
  const kalan = kutu.filter(m => !(m && m.type === 'chat' && (m.peerId === data.uid || m.fromUserId === data.uid)));
  if (kalan.length !== kutu.length) {
    kutu.length = 0; kutu.push(...kalan);
    saveInboxMsgs(kutu);
    if (_inboxCurrentMsg && _inboxCurrentMsg.type === 'chat' && (_inboxCurrentMsg.peerId === data.uid || _inboxCurrentMsg.fromUserId === data.uid)) inboxBackToList();
    inboxRenderList();
    inboxUpdateBadge();
  }
  _modEkranTazele();
  rosterToast('Engellendi.', 'ok');
}

async function modEngelKaldir(k) {
  const o = _modHedef.get(k);
  _modKapat();
  const uid = _modEngel.has(o.hedef) ? o.hedef
    : ([..._modEngel.values()].find(r => 'user:' + String(r.kullanici_adi || '').toLowerCase() === String(o.hedef).toLowerCase()) || {}).uid;
  if (!uid) return;
  await _modEngelKaldirUid(uid);
}
async function _modEngelKaldirUid(uid) {
  const { error } = await window.sb.rpc('engel_kaldir', { p_uid: uid });
  if (error) { rosterToast('Engel kaldırılamadı.', 'warn'); return; }
  const r = _modEngel.get(uid);
  _modEngel.delete(uid);
  if (r && r.kullanici_adi) _modEngelSosyal.delete('user:' + String(r.kullanici_adi).toLowerCase());
  _modEkranTazele();
  rosterToast('Engel kaldırıldı.', 'ok');
}

// Açık ekranlar engel listesine göre yeniden çizilir
function _modEkranTazele() {
  const cm = document.getElementById('page-cfc-media');
  if (cm && cm.classList.contains('active')) cfcMdRender();
  if (document.getElementById('teamChatArea')) _teamChatLoadAndRender();
  if (document.getElementById('ntChatArea')) _ntChatYukleVeCiz();
}

// Ayarlar → Engellenen Kullanıcılar
async function modEngelListeAc() {
  await modEngelYukle();
  const satir = [..._modEngel.values()].map(r => {
    const av = (r.avatar_id && typeof getAvatarEmoji === 'function') ? getAvatarEmoji(r.avatar_id, null) : '👤';
    return `<div class="mod-kisi"><div class="mod-kisi-av">${av}</div>`
      + `<div class="mod-kisi-ad" data-noi18n><b>${_cfcMdEscape(r.ad || r.kullanici_adi || '—')}</b><small>@${_cfcMdEscape(r.kullanici_adi || '')}</small></div>`
      + `<button class="mod-kaldir" onclick="_modEngelKaldirUid('${r.uid}').then(modEngelListeAc)">Engeli kaldır</button></div>`;
  }).join('');
  _modSheet(`<div class="mod-baslik">Engellenen Kullanıcılar</div>`
    + (satir || `<div class="mod-bos">Engellediğin kimse yok.</div>`)
    + `<button class="mod-vazgec" onclick="_modKapat()">Kapat</button>`);
}

// Sohbet mesajına basılı tutunca (masaüstünde sağ tık) menü
function _modBasiliTut(el, ac) {
  let t = null, x0 = 0, y0 = 0;
  const iptal = () => { if (t) { clearTimeout(t); t = null; } };
  el.addEventListener('pointerdown', (e) => {
    iptal(); x0 = e.clientX; y0 = e.clientY;
    t = setTimeout(() => { t = null; if (navigator.vibrate) navigator.vibrate(15); ac(); }, 550);
  });
  el.addEventListener('pointermove', (e) => { if (Math.abs(e.clientX - x0) > 8 || Math.abs(e.clientY - y0) > 8) iptal(); });
  el.addEventListener('pointerup', iptal);
  el.addEventListener('pointercancel', iptal);
  el.addEventListener('pointerleave', iptal);
  el.addEventListener('contextmenu', (e) => { e.preventDefault(); iptal(); ac(); });
}

// ═══════════════════════════════════════════════════════════════
// 🆕 DESTEK — şikayet / istek / talep
//   Oyuncu yazar → feedback tablosuna kaydedilir → yönetici panelden
//   okur ve cevaplar → cevap gelen kutusuna sistem mesajı olarak düşer.
// ═══════════════════════════════════════════════════════════════
const SUPPORT_TIPLER = {
  complaint: { ikon:'🚨', ad:'Şikayet', renk:'#ef5350', db:'sikayet',
               ipucu:'Yaşadığın sorunu, hatayı veya kural ihlalini yaz. Mümkünse takım/oyuncu adı ekle.' },
  request:   { ikon:'💡', ad:'İstek',   renk:'#ffd54f', db:'istek',
               ipucu:'Oyunda görmek istediğin özelliği veya iyileştirmeyi anlat.' },
  inquiry:   { ikon:'📋', ad:'Talep',   renk:'#00b0ff', db:'talep',
               ipucu:'Hesabın, takımın veya bir işlemle ilgili talebini yaz.' },
};

function supportOpen(type) {
  const cfg = SUPPORT_TIPLER[type] || SUPPORT_TIPLER.inquiry;
  supportClose();

  const ov = document.createElement('div');
  ov.id = 'supportOverlay';
  ov.className = 'sup-ov';
  ov.onclick = (e) => { if (e.target === ov) supportClose(); };
  ov.innerHTML = `
    <div class="sup-modal">
      <div class="sup-head">
        <div class="sup-ikon" style="color:${cfg.renk}">${cfg.ikon}</div>
        <div class="sup-baslik">${cfg.ad} Gönder</div>
        <button class="sup-kapat" onclick="supportClose()" aria-label="Kapat">✕</button>
      </div>
      <div class="sup-ipucu">${cfg.ipucu}</div>
      <textarea id="supText" class="sup-text" maxlength="1000"
        placeholder="Buraya yaz…"></textarea>
      <div class="sup-sayac"><span id="supSay">0</span> / 1000</div>
      <div id="supHata" class="sup-hata" style="display:none"></div>
      <button id="supGonder" class="sup-btn" style="background:${cfg.renk}">Gönder</button>
      <div class="sup-not">Cevap geldiğinde gelen kutuna bildirim düşer.</div>
    </div>`;
  document.body.appendChild(ov);
  requestAnimationFrame(() => ov.classList.add('acik'));

  const ta = document.getElementById('supText');
  const sy = document.getElementById('supSay');
  if (ta) { ta.focus(); ta.oninput = () => { if (sy) sy.textContent = ta.value.length; }; }
  const btn = document.getElementById('supGonder');
  if (btn) btn.onclick = () => supportGonder(cfg.db, cfg.ad);
}

function supportClose() {
  const ov = document.getElementById('supportOverlay');
  if (ov) ov.remove();
}
window.supportClose = supportClose;

async function supportGonder(tip, ad) {
  const ta = document.getElementById('supText');
  const btn = document.getElementById('supGonder');
  const hata = document.getElementById('supHata');
  const gost = (m) => { if (hata) { hata.textContent = m; hata.style.display = 'block'; } };
  if (!ta) return;
  const metin = String(ta.value || '').trim();
  if (metin.length < 10) { gost('En az 10 karakter yaz.'); return; }
  if (!window.sb || !window.authUser || !window.authUser.id) { gost('Oturum bulunamadı.'); return; }

  btn.disabled = true; btn.textContent = 'Gönderiliyor…';
  try {
    const { error } = await window.sb.from('feedback').insert({
      user_id: window.authUser.id,
      username: (window.authUser.name || window.authUser.username || null),
      type: tip,
      message: metin.slice(0, 1000),
    });
    if (error) throw error;
    supportClose();
    if (typeof rosterToast === 'function') rosterToast('✅ ' + ad + ' gönderildi', 'ok');
    else if (typeof showToast === 'function') showToast('✅ ' + ad + ' gönderildi');
  } catch(e) {
    console.warn('[destek] gönderilemedi:', e);
    btn.disabled = false; btn.textContent = 'Gönder';
    gost('Gönderilemedi: ' + (e.message || e));
  }
}

// ── Yönetici cevabı geldi mi? (gelen kutusuna işle) ──
// 685 — her talep gelen kutusunda TEK sohbet: oyuncunun mesajları ve yönetim cevapları aynı mesajda
//   sırayla görünür. Yeni yönetim cevabı gelince o sohbet okunmamış olur ve en üste çıkar.
//   Her yönetim cevabı bir cevap hakkı verir; yönetim "Çözüldü" deyince talep kapanır.
//   _destekOnb: talep → { yon, oyu, kapali }.
const _destekOnb = {};
let _destekTarandi = false;
function _destekKonusma(f) {
  const th = Array.isArray(f.thread) ? f.thread.filter(e => e && (e.k === 'oyuncu' || e.k === 'yonetim')) : [];
  return [{ k: 'oyuncu', m: String(f.message || ''), t: f.created_at || null },
          { k: 'yonetim', m: String(f.reply || ''), t: f.replied_at || null }]
    .concat(th.map(e => ({ k: e.k, m: String(e.m || ''), t: e.t || null })));
}
// Düz metin (liste araması ve eski sürümler için)
function _destekMetin(L) {
  return L.map(e => e.k === 'oyuncu'
    ? 'Gönderdiğin mesaj:\n"' + e.m.slice(0, 300) + '"'
    : '— Yönetim cevabı —\n' + e.m).join('\n\n');
}
async function supportCevapTara() {
  try {
    if (!window.sb || !window.authUser || !window.authUser.id) return;
    if (!Array.isArray(_inboxCache)) return;          // gelen kutusu henüz yüklenmedi (tekrar koruması çalışmaz)
    let data = null;
    try {
      const r = await window.sb.rpc('destek_benim');
      if (!r.error && Array.isArray(r.data)) data = r.data;
    } catch(e) {}
    if (!data) {
      // 🆕 reply/replied_at kolonları yoksa PostgREST 400 dönüyor ve konsol her
      //   açılışta kırmızı hata gösteriyordu. Hata varsa sessizce çık (özellik pasif).
      const { data: d, error } = await window.sb.from('feedback')
        .select('id,type,message,reply,replied_at')
        .eq('user_id', window.authUser.id)
        .not('reply', 'is', null)
        .order('replied_at', { ascending: false }).limit(20);
      if (error) return;
      data = d || [];
    }
    if (!Array.isArray(_inboxCache)) return;
    _destekTarandi = true;
    const msgs = getInboxMsgs();
    const sent = _sysSentSet();
    let degisti = false;
    data.forEach(f => {
      const fid = String(f.id), id = 'destek_' + fid;
      const L = _destekKonusma(f);
      const yon = L.filter(e => e.k === 'yonetim').length, oyu = L.filter(e => e.k === 'oyuncu').length - 1;
      const kapali = f.status === 'cozuldu';
      _destekOnb[fid] = { yon, oyu, kapali };
      const ad = { sikayet:'Şikayetine', istek:'İsteğine', talep:'Talebine' }[f.type] || 'Bildirimine';
      const konu = ad + (yon > 1 ? ' Yeni Cevap' : ' Cevap Geldi');
      // 683'te ayrı mesaj olarak gelen sonraki cevaplar (destek_<id>_2 …) bu sohbette birleşir
      for (let i = msgs.length - 1; i >= 0; i--) {
        const x = msgs[i] && msgs[i].id;
        if (typeof x === 'string' && x.indexOf(id + '_') === 0 && /^\d+$/.test(x.slice(id.length + 1))) { msgs.splice(i, 1); degisti = true; }
      }
      const gorulen = n => n <= 1 ? sent.has(id) : (sent.has(id + '#' + n) || sent.has(id + '_' + n));
      const yeniCevap = !gorulen(yon);
      const veri = { fid, tur: f.type || null, mesajlar: L, kapali };
      const govde = _destekMetin(L);
      const ix = msgs.findIndex(m => m && m.id === id);
      if (ix >= 0) {
        const m = msgs[ix];
        if (JSON.stringify(m.destek || null) !== JSON.stringify(veri) || m.body !== govde) { m.destek = veri; m.body = govde; degisti = true; }
        if (yeniCevap) {
          m.subject = konu; m.read = false; m.ts = Date.now(); m.time = new Date().toLocaleDateString('tr-TR');
          degisti = true;
        }
      } else if (yeniCevap) {
        msgs.unshift({ id, from: '🛟 Destek', fromAvatar: '🛟', type: 'system', sysKind: 'destek', subject: konu, body: govde, destek: veri,
          time: new Date().toLocaleDateString('tr-TR'), ts: Date.now(), read: false, thread: [] });
        degisti = true;
      }
      for (let n = 1; n <= yon; n++) if (!gorulen(n)) _sysSentAdd(n <= 1 ? id : id + '#' + n);
    });
    if (degisti) {
      saveInboxMsgs(msgs);
      if (typeof inboxUpdateBadge === 'function') inboxUpdateBadge();
      try {
        const ov = document.getElementById('inboxOverlay');
        if (ov && ov.classList.contains('open') && typeof _inboxView !== 'undefined' && _inboxView === 'list' && typeof inboxRenderList === 'function') inboxRenderList();
      } catch(e) {}
    }
    // Açık destek sohbeti güncel konuşma ve haklarla yeniden çizilir
    try {
      if (typeof _inboxCurrentMsg !== 'undefined' && _inboxCurrentMsg && _destekDurum(_inboxCurrentMsg)
          && typeof _inboxView !== 'undefined' && _inboxView === 'detail' && typeof inboxRenderDetail === 'function') {
        const guncel = getInboxMsgs().find(m => m && m.id === _inboxCurrentMsg.id);
        if (guncel) { _inboxCurrentMsg = guncel; inboxRenderDetail(guncel); }
      }
    } catch(e) {}
  } catch(e) {}
}
window.supportCevapTara = supportCevapTara;

// Destek sohbeti → talep ve durumu. Cevap hakkı: talep açıkken her yönetim cevabına bir cevap.
function _destekDurum(m) {
  if (!m || m.sysKind !== 'destek') return null;
  const k = /^destek_(.+)$/.exec(String(m.id || ''));
  if (!k || /_\d+$/.test(k[1]) && !_destekOnb[k[1]]) return null;
  const fid = k[1], d = _destekOnb[fid];
  if (!d) return { fid, hak: false, gitti: false, kapali: !!(m.destek && m.destek.kapali), yok: true };
  return { fid, hak: !d.kapali && d.oyu < d.yon, gitti: d.oyu >= d.yon, kapali: d.kapali };
}
function _destekEylem(m) {
  const d = _destekDurum(m);
  if (!d) return '';
  if (d.yok && !_destekTarandi) { try { supportCevapTara(); } catch(e) {} }
  if (d.kapali) return `<span class="gk-iletildi">${_gkIk('tamam')}Talep kapandı</span>`;
  if (d.hak) return `<button class="bir" onclick="destekCevapAc('${String(d.fid).replace(/'/g, "\\'")}')">${_gkIk('yanitla')}Cevapla</button>`;
  if (d.gitti) return `<span class="gk-iletildi">${_gkIk('tamam')}Cevabın iletildi</span>`;
  return '';
}
// Sohbet görünümü: oyuncunun mesajları sağda, destek cevapları solda (oyuncu sohbetiyle aynı balonlar)
function _destekCiz(m, bas, body) {
  if (!m || m.sysKind !== 'destek' || !m.destek || !Array.isArray(m.destek.mesajlar)) return false;
  let h = bas + '<div class="gk-destek">';
  m.destek.mesajlar.forEach(e => {
    const ben = e.k === 'oyuncu';
    const ms = e.t ? Date.parse(e.t) : NaN;
    const zaman = (!isNaN(ms) && typeof _inboxFmtDateTime === 'function') ? _inboxFmtDateTime(ms) : '';
    h += `<div class="inbox-thread-msg ${ben ? 'sent' : 'received'}">`
       + `<div class="inbox-thread-bubble" data-noi18n>${_gkE(e.m).replace(/\n/g, '<br>')}</div>`
       + `<div class="inbox-thread-meta"><span>${ben ? 'Sen' : 'Destek'}</span>${zaman ? `<span data-noi18n> · ${_gkE(zaman)}</span>` : ''}</div></div>`;
  });
  h += '</div>' + _gkEylemHtml(m);
  body.innerHTML = h;
  _gkYanitGizle(true);
  requestAnimationFrame(() => { body.scrollTop = body.scrollHeight; requestAnimationFrame(() => { body.scrollTop = body.scrollHeight; }); });
  return true;
}

function destekCevapAc(fid) {
  supportClose();
  const ov = document.createElement('div');
  ov.id = 'supportOverlay';
  ov.className = 'sup-ov';
  ov.onclick = (e) => { if (e.target === ov) supportClose(); };
  ov.innerHTML = `
    <div class="sup-modal">
      <div class="sup-head">
        <div class="sup-ikon sup-ikon-svg"><svg viewBox="0 0 24 24"><path d="M10 7.5L5 12l5 4.5"/><path d="M5.5 12H14a5 5 0 0 1 5 5v1.5"/></svg></div>
        <div class="sup-baslik">Cevapla</div>
        <button class="sup-kapat" onclick="supportClose()" aria-label="Kapat">✕</button>
      </div>
      <textarea id="supText" class="sup-text" maxlength="1000" placeholder="Buraya yaz…"></textarea>
      <div class="sup-sayac"><span id="supSay">0</span> / 1000</div>
      <div id="supHata" class="sup-hata" style="display:none"></div>
      <button id="supGonder" class="sup-btn" style="background:var(--accent);color:#06210f">Gönder</button>
    </div>`;
  document.body.appendChild(ov);
  requestAnimationFrame(() => ov.classList.add('acik'));
  const ta = document.getElementById('supText');
  const sy = document.getElementById('supSay');
  if (ta) { ta.focus(); ta.oninput = () => { if (sy) sy.textContent = ta.value.length; }; }
  const btn = document.getElementById('supGonder');
  if (btn) btn.onclick = () => destekCevapGonder(fid);
}
window.destekCevapAc = destekCevapAc;

async function destekCevapGonder(fid) {
  const ta = document.getElementById('supText');
  const btn = document.getElementById('supGonder');
  const hata = document.getElementById('supHata');
  const gost = (m) => { if (hata) { hata.textContent = m; hata.style.display = 'block'; } };
  if (!ta || !btn || btn.disabled) return;
  const metin = String(ta.value || '').trim();
  if (metin.length < 2) { gost('En az 2 karakter yaz.'); return; }
  if (!window.sb || !window.authUser || !window.authUser.id) { gost('Oturum bulunamadı.'); return; }
  btn.disabled = true; btn.textContent = 'Gönderiliyor…';
  const ciz = () => { try { if (_inboxCurrentMsg) inboxRenderDetail(_inboxCurrentMsg); } catch(e) {} };
  try {
    const { error } = await window.sb.rpc('destek_cevapla', { p_id: String(fid), p_metin: metin.slice(0, 1000) });
    if (error) {
      const k = String(error.message || '');
      const d = _destekOnb[String(fid)];
      if (/cevap_hakki_yok|talep_kapali/.test(k)) {
        if (d) { if (/talep_kapali/.test(k)) d.kapali = true; else d.oyu = d.yon; }
        gost(/talep_kapali/.test(k) ? 'Talep kapandı' : 'Bu cevaba zaten yanıt verdin.');
        btn.textContent = 'Gönder';
        ciz();
        return;
      }
      throw error;
    }
    const d = _destekOnb[String(fid)]; if (d) d.oyu++;
    // Cevap sohbete hemen eklenir (sunucu taraması da aynısını getirir)
    try {
      const msgs = getInboxMsgs();
      const m = msgs.find(x => x && x.id === 'destek_' + fid);
      if (m && m.destek && Array.isArray(m.destek.mesajlar)) {
        m.destek.mesajlar.push({ k: 'oyuncu', m: metin.slice(0, 1000), t: new Date().toISOString() });
        m.body = _destekMetin(m.destek.mesajlar);
        saveInboxMsgs(msgs);
        if (_inboxCurrentMsg && _inboxCurrentMsg.id === m.id) _inboxCurrentMsg = m;
      }
    } catch(e) {}
    supportClose();
    ciz();
    if (typeof rosterToast === 'function') rosterToast('✅ Cevabın gönderildi', 'ok');
    else if (typeof showToast === 'function') showToast('✅ Cevabın gönderildi');
  } catch(e) {
    console.warn('[destek] cevap gönderilemedi:', e);
    btn.disabled = false; btn.textContent = 'Gönder';
    gost('Gönderilemedi: ' + (e.message || e));
  }
}
window.destekCevapGonder = destekCevapGonder;

// ── Toplu duyurular (broadcasts) → gelen kutusu ──
async function duyuruTara() {
  try {
    if (!window.sb || typeof sysMsg !== 'function') return;
    const { data } = await window.sb.from('broadcasts')
      .select('id,hedef,hedef_deger,baslik,govde,gonderen,created_at,konu')
      .eq('aktif', true).order('created_at', { ascending: false }).limit(30);
    if (!data || !data.length) return;

    const uyruk = (typeof getUserNationalityCC === 'function') ? getUserNationalityCC() : null;
    const takim = (typeof _userTeam !== 'undefined' && _userTeam) ? _userTeam.teamName : null;
    const ulke  = (typeof _userTeam !== 'undefined' && _userTeam) ? _userTeam.countryCode : null;
    if (data.some(b => b.konu === 'kampanya')) await kmpYukle();   // 809

    data.forEach(b => {
      let bana = false;
      if (b.hedef === 'all') bana = true;
      else if (b.hedef === 'country') bana = !!b.hedef_deger && (b.hedef_deger === uyruk || b.hedef_deger === ulke);
      else if (b.hedef === 'team')    bana = !!b.hedef_deger && (b.hedef_deger === takim);
      else if (b.hedef === 'uyruk')   bana = !!b.hedef_deger && !!uyruk && String(b.hedef_deger).toUpperCase() === String(uyruk).toUpperCase();   // 800
      else if (b.hedef === 'takim')   bana = !!b.hedef_deger && !!takim && b.hedef_deger === (ulke + '|' + takim);
      if (!bana) return;
      if (b.konu === 'kampanya' && (!_kmpTs || !_kmp.some(k => k.mesaj === 'yayin_' + b.id))) return;   // 809 — biten kampanyanın mesajı düşmez
      sysMsg({
        id: 'yayin_' + b.id,
        from: b.konu ? 'CSC' : (b.gonderen || '📢 Yönetim'), avatar: '📢', kind: b.konu ? 'yonetim' : 'duyuru', konu: b.konu || undefined,
        subject: b.baslik || 'Duyuru',
        body: b.govde || '',
      });
    });
  } catch(e) {}
}
window.duyuruTara = duyuruTara;
// 800 — uygulamaya dönünce yeni toplu mesajlar (en çok 5 dakikada bir)
let _duyuruDonus = 0;
document.addEventListener('visibilitychange', () => {
  if (document.hidden || Date.now() - _duyuruDonus < 300000) return;
  _duyuruDonus = Date.now();
  duyuruTara();
});

// ── Takımdan ayrıl onayı ──
// ══════════════════════════════════════════════════════════════
// 🆕 KAPTAN AYRILAMAZ MODALI — tarayıcı alert()'i yerine tema uyumlu kutu.
