async function _userMatchLogLoadFromServer() {
  if (!window.sb) {
    _userMatchLogCache = []; _userXpLogCache = [];
    _userTrainLogCache = []; _userRaceClaimedCache = {};
    return;
  }
  // 🆕 authUser'a bağımlı kalma — user_id'yi Supabase session'dan doğrudan al
  // (boot sequence'ta authInit henüz tamamlanmamış olabilir, ama session restore edilmiş olur)
  let userId = null;
  try {
    if (authUser && authUser.id) {
      userId = authUser.id;
    } else {
      const { data: sess } = await window.sb.auth.getSession();
      userId = sess?.session?.user?.id || null;
    }
  } catch(e) {}
  if (!userId) {
    _userMatchLogCache = []; _userXpLogCache = [];
    _userTrainLogCache = []; _userRaceClaimedCache = {};
    return;
  }
  try {
    const { data } = await window.sb.from('user_player')
      .select('match_log, xp_log, train_log, race_claimed')
      .eq('user_id', userId)
      .maybeSingle();
    _userMatchLogCache = Array.isArray(data?.match_log) ? data.match_log : [];
    _userXpLogCache = Array.isArray(data?.xp_log) ? data.xp_log : [];
    _userTrainLogCache = Array.isArray(data?.train_log) ? data.train_log : [];
    _userRaceClaimedCache = (data?.race_claimed && typeof data.race_claimed === 'object') ? data.race_claimed : {};
  } catch(e) {
    _userMatchLogCache = []; _userXpLogCache = [];
    _userTrainLogCache = []; _userRaceClaimedCache = {};
  }
}

// getUserMatchLog: kullanıcının kendi oyuncu satırından match_ratings'ı oku
// Edge function maç sonu her satıra: rating, goals, assists, yellows, reds,
// tournament_key, home, away, hs, as, result (W/D/L), isHome, opp, ts yazıyor.
// Kariyer sayfası bu kayıtları "userIsHome → isHome" map'iyle kullanır.
function getUserMatchLog() {
  if (typeof ROSTER_DATA === 'undefined' || !Array.isArray(ROSTER_DATA)) return [];
  const me = ROSTER_DATA.find(p => p.role === 'user');
  if (!me || !Array.isArray(me.matchRatings)) return [];
  // Eski API'yi koru: log[i].userIsHome, log[i].goals/assists/yellowCards/redCards, log[i].date
  return me.matchRatings.map(mr => ({
    match_key: mr.match_key,
    date: mr.ts ? new Date(mr.ts).toISOString() : null,
    home: mr.home,
    away: mr.away,
    hs: mr.hs,
    as: mr.as,
    result: mr.result,
    userIsHome: !!mr.isHome,
    opp: mr.opp,
    goals: mr.goals || 0,
    assists: mr.assists || 0,
    yellowCards: mr.yellows || 0,
    redCards: mr.reds || 0,
    rating: mr.rating || 0,
    tournament_key: mr.tournament_key || null,
  }));
}
function saveUserMatchLog(list) { /* no-op — Edge function tek yazar */ }

// ─────────────────────────────────────────────────────────────
// statsByComp v2 reader — sezon kırılımlı yapıdan değer okuma
// Yapı: { lig: { s1: {g,a,m}, s2: {g,a,m} }, chm: { s1: {g,a,m} } }
// statsByCompGetSeason(sbc, bucket, season) → {g,a,m}    tek sezon
// statsByCompGetTotal(sbc, bucket)          → {g,a,m}    tüm sezonlar toplamı
// ─────────────────────────────────────────────────────────────
function statsByCompGetSeason(sbc, bucket, season) {
  if (!sbc || typeof sbc !== 'object') return { g: 0, a: 0, m: 0 };
  const b = sbc[bucket];
  if (!b || typeof b !== 'object') return { g: 0, a: 0, m: 0 };
  const s = b['s' + season];
  if (!s || typeof s !== 'object') return { g: 0, a: 0, m: 0 };
  return { g: s.g || 0, a: s.a || 0, m: s.m || 0 };
}
function statsByCompGetTotal(sbc, bucket) {
  if (!sbc || typeof sbc !== 'object') return { g: 0, a: 0, m: 0 };
  const b = sbc[bucket];
  if (!b || typeof b !== 'object') return { g: 0, a: 0, m: 0 };
  let g = 0, a = 0, m = 0;
  for (const k in b) {
    if (!k.startsWith('s')) continue;
    const s = b[k];
    if (s && typeof s === 'object') {
      g += s.g || 0; a += s.a || 0; m += s.m || 0;
    }
  }
  return { g, a, m };
}
// Hangi sezonlar var? (oyuncu hangi sezonlarda oynamış)
function statsByCompGetSeasons(sbc) {
  if (!sbc || typeof sbc !== 'object') return [];
  const seasonSet = new Set();
  for (const bucket in sbc) {
    const b = sbc[bucket];
    if (b && typeof b === 'object') {
      for (const k in b) {
        if (k.startsWith('s')) {
          const n = parseInt(k.substring(1), 10);
          if (Number.isFinite(n)) seasonSet.add(n);
        }
      }
    }
  }
  return [...seasonSet].sort((x, y) => x - y);
}

