// 🆕 PİYASA DEĞERİ DÜZENLEME — kaptan oyuncu MV'yi değiştirir
let _pendingMVEdit = null;

function editPlayerMV(num, ev) {
  if (ev) { try { ev.stopPropagation(); } catch(e) {} }
  // 🆕 PİYASA DEĞERİ ARTIK DEĞİŞTİRİLEMEZ — oyun tarafından belirlenir.
  //   (Kaptan override'ı kaldırıldı; hiçbir rol müdahale edemez.)
  if (typeof rosterToast === 'function') {
    rosterToast('💶 Piyasa değeri oyun tarafından belirlenir, değiştirilemez.', 'err');
  }
  return;
  /* eslint-disable no-unreachable */
  if (typeof ROSTER_DATA === 'undefined' || !Array.isArray(ROSTER_DATA)) return;
  const player = ROSTER_DATA.find(p => p && p.num === num);
  if (!player) {
    if (typeof rosterToast === 'function') rosterToast('Oyuncu bulunamadı.', 'err');
    return;
  }

  const currentMV = getPlayerMarketValue(player);
  const isCustom = (typeof player.captainMV === 'number' && player.captainMV > 0);

  _pendingMVEdit = { num, playerName: player.name, currentMV };

  const infoEl = document.getElementById('mvPlayerInfo');
  if (infoEl) infoEl.textContent = player.name;
  const curEl = document.getElementById('mvCurrentVal');
  if (curEl) curEl.textContent = formatMV(currentMV) + (isCustom ? ' (kaptan)' : ' (otomatik)');
  const inputEl = document.getElementById('mvInput');
  if (inputEl) {
    inputEl.value = String(currentMV);
    setTimeout(() => { inputEl.focus(); inputEl.select(); }, 200);
  }
  // Reset butonu sadece custom değer varsa görünür
  const resetBtn = document.getElementById('mvResetBtn');
  if (resetBtn) resetBtn.style.display = isCustom ? 'block' : 'none';

  onMVInputChange();
  const ov = document.getElementById('mvEditOverlay');
  if (ov) ov.classList.add('open');
  /* eslint-enable no-unreachable */
}

function onMVInputChange(){
  const input = document.getElementById('mvInput');
  const warn  = document.getElementById('mvWarn');
  const btn   = document.getElementById('mvSaveBtn');
  if(!input || !warn || !btn || !_pendingMVEdit) return;

  const valStr = (input.value || '').trim();
  const newVal = parseInt(valStr, 10);

  warn.classList.remove('has-conflict','ok');

  if (valStr === '' || isNaN(newVal)) {
    warn.textContent = 'Bir değer gir (1.000 - 500.000.000 €).';
    btn.disabled = true;
    return;
  }
  if (newVal < 1000 || newVal > 500000000) {
    warn.textContent = '⛔ Değer 1.000 € ile 500.000.000 € arasında olmalı.';
    warn.classList.add('has-conflict');
    btn.disabled = true;
    return;
  }
  if (newVal === _pendingMVEdit.currentMV) {
    warn.textContent = 'Mevcut değerle aynı.';
    btn.disabled = true;
    return;
  }
  warn.innerHTML = `Yeni değer: <b style="color:#ffd54f">${formatMV(newVal)}</b>`;
  warn.classList.add('ok');
  btn.disabled = false;
}

function mvQuickSet(amount){
  const input = document.getElementById('mvInput');
  if (input) {
    input.value = String(amount);
    onMVInputChange();
  }
}

function executeMVEdit(){
  if (!_pendingMVEdit) return;
  const input = document.getElementById('mvInput');
  if (!input) return;
  const newVal = parseInt(input.value, 10);
  if (isNaN(newVal) || newVal < 1000 || newVal > 500000000) return;

  const player = ROSTER_DATA.find(p => p && p.num === _pendingMVEdit.num);
  if (!player) { closeMVEdit(); return; }

  player.captainMV = newVal;
  // Kullanıcıysa kendi profiline de yaz (oyuncu profil ekranı bunu gösterecek)
  if (player.role === 'user' && typeof authUser !== 'undefined' && authUser) {
    authUser.captainMV = newVal;
    /* cft_auth localStorage kaldırıldı - sadece Supabase */
  }

  closeMVEdit();
  if (typeof rosterToast === 'function') {
    rosterToast(`💶 ${player.name} piyasa değeri güncellendi: ${formatMV(newVal)}`, 'ok');
  }
  // Listeyi yenile
  if (typeof renderRoster === 'function') renderRoster(rosterCurrentFilter || 'all');
  // 🆕 Eğer kullanıcının kendi MV'si değiştiyse, oyuncu sayfası da yenilensin (açıkken)
  if (player.role === 'user' && typeof renderPlayerPage === 'function') {
    try { renderPlayerPage(); } catch(e){}
  }
}

function mvResetToAuto(){
  if (!_pendingMVEdit) return;
  const player = ROSTER_DATA.find(p => p && p.num === _pendingMVEdit.num);
  if (!player) { closeMVEdit(); return; }
  delete player.captainMV;
  if (player.role === 'user' && typeof authUser !== 'undefined' && authUser) {
    delete authUser.captainMV;
    /* cft_auth localStorage kaldırıldı - sadece Supabase */
  }
  closeMVEdit();
  if (typeof rosterToast === 'function') {
    rosterToast(`↺ ${player.name} otomatik hesaba döndü: ${formatMV(_carEstimateMarketValue(player))}`, 'ok');
  }
  if (typeof renderRoster === 'function') renderRoster(rosterCurrentFilter || 'all');
  // 🆕 Kullanıcı kendiyse oyuncu sayfasını da yenile
  if (player.role === 'user' && typeof renderPlayerPage === 'function') {
    try { renderPlayerPage(); } catch(e){}
  }
}

function closeMVEdit(){
  const ov = document.getElementById('mvEditOverlay');
  if (ov) ov.classList.remove('open');
  _pendingMVEdit = null;
}

// 744 — Kadro satırı forması: takımın 1. forma rengi, kumaş gölgesi, soyad + numara.
//   Yazı rengi: şort rengi formada okunuyorsa o (kontrast ≥ 4.5), değilse beyaz/siyah.
const KF_SIRT = 'forma-sirt.webp';
