  const a1p = a1 * (1 + G), a2p = a2 * (1 + G), C1 = Math.hypot(a1p, b1), C2 = Math.hypot(a2p, b2);
  const ac = (y, x) => { if (!y && !x) return 0; const t = Math.atan2(y, x) / rad; return t < 0 ? t + 360 : t; };
