  if (t[1] < .15 && t[2] < .5) { const s2 = _kfHsl(kit.short); if (s2 && (s2[1] >= .15 || s2[2] >= .5)) t = s2; }
  const S = t[1] < .15 ? 0 : Math.max(t[1], .6), L = Math.max(t[2], .55);
