// Genel modal açma
// 🆕 Serbest/dış-kaynaklı oyuncuyu DB'den canlı çöz (takım cache'inde yoksa).
//   _buildRosterFromPlayers ile aynı kanonik objeyi üretir → is_bot/avatar/abilities/userId/level doğru.
async function _resolvePlayerFromServer(player, ctx){
  if(!window.sb || !player) return null;
  try {
    const cols='id, user_id, team_name, num, name, pos, pos_group, sub_pos, nationality, nation, level, xp, overall, rating, abilities, role, avatar, avatar_id, gender, is_bot, last_seen, user_team_data, goals_total, assists_total, matches_played, match_ratings, stats_by_comp, season_yellow, suspend_matches, suspend_reason, injury_until';
    let q=window.sb.from('players').select(cols);
    const uid=player.userId||player.user_id;
    if(uid) q=q.eq('user_id',uid);
    else if(typeof player.id==='number') q=q.eq('id',player.id);
    else if(player.name){
      q=q.eq('name',player.name);
      // 🆕 Aynı isimli birden çok oyuncu olabilir → takım + ülke ile daralt (varsa)
      const _tn=(ctx&&(ctx.teamLookupName||ctx.teamName))||player.team_name||null;
      const _cc=(ctx&&(ctx.countryCode||ctx.cc))||player.country_code||null;
      if(_tn) q=q.eq('team_name',_tn);
      if(_cc) q=q.eq('country_code',String(_cc).toUpperCase().slice(0,2));
    }
    else return null;
    const { data, error }=await q.limit(1);
    if(error||!Array.isArray(data)||!data.length) return null;
    const mapped=_buildRosterFromPlayers([data[0]], data[0].nationality);
    const out=(mapped&&mapped[0])||null;
    if(out) out.team_name = (data[0].team_name == null ? null : data[0].team_name);
    return out;
  } catch(e){ return null; }
}

// 🆕 Oyuncu milli takım kadrosunda mı? (uuid seti yüklüyse true/false, değilse null)
function _isNtSquadPlayerSync(player, cc) {
  // 572 — başkanın kadrosu + sunucunun güncel çağrı listesi (otomatik kadrodaki gerçek oyuncular)
  try {
    const uset = (typeof _ntSquadUuidByCc !== 'undefined') ? _ntSquadUuidByCc[cc] : null;
    const snap = (typeof _ntSnapUidByCc !== 'undefined') ? _ntSnapUidByCc[cc] : null;
    if (!uset && !snap) return null;
    if (player && player.id && uset && uset.has(player.id)) return true;
    const uid = player && (player.user_id || player.userId);
    return !!(uid && snap && snap.has(String(uid)));
  } catch(e) { return null; }
}
// 🆕 Profil modalında 'Milli Takım Oyuncusu' rozetini doldur (gerekiyorsa kadroyu async yükle)
async function _ntFillProfileNtBadge(player) {
  try {
    if (!player) return;
    const cc = player.nationality || player._cc || player.country_code;
    if (!cc) return;
    let member = _isNtSquadPlayerSync(player, cc);
    if (member === null && typeof _loadNtSquadFromServer === 'function') {
      await _loadNtSquadFromServer(cc);
      member = _isNtSquadPlayerSync(player, cc);
    }
    const el = document.getElementById('pmNtBadge');
    if (el && member) el.style.display = '';
  } catch(e) {}
}


// 635 — OYUNCU KARTI (Takım Renkleri) yardımcıları
