  '4-2-2-2':  [{pos:'GK',s:'GK',x:50,y:88},{pos:'SB',s:'LB',x:13,y:67},{pos:'STB',s:'CB',x:38,y:68},{pos:'STB',s:'CB',x:62,y:68},{pos:'SB',s:'RB',x:87,y:67},{pos:'DOS',s:'DM',x:35,y:52},{pos:'DOS',s:'DM',x:65,y:52},{pos:'CAM',s:'AM',x:32,y:33},{pos:'CAM',s:'AM',x:68,y:33},{pos:'FWD',s:'ST',x:38,y:17},{pos:'FWD',s:'ST',x:62,y:17}],
  '3-4-2-1':  [{pos:'GK',s:'GK',x:50,y:88},{pos:'STB',s:'CB',x:25,y:68},{pos:'STB',s:'CB',x:50,y:69},{pos:'STB',s:'CB',x:75,y:68},{pos:'SAK',s:'LM',x:11,y:47},{pos:'OS',s:'CM',x:38,y:48},{pos:'OS',s:'CM',x:62,y:48},{pos:'SAK',s:'RM',x:89,y:47},{pos:'CAM',s:'AM',x:34,y:31},{pos:'CAM',s:'AM',x:66,y:31},{pos:'FWD',s:'ST',x:50,y:17}],
