  '3-5-2':    [{pos:'GK',s:'GK',x:50,y:88},{pos:'STB',s:'CB',x:22,y:68},{pos:'STB',s:'CB',x:50,y:69},{pos:'STB',s:'CB',x:78,y:68},{pos:'SB',s:'LB',x:9,y:46},{pos:'OS',s:'CM',x:30,y:46},{pos:'DOS',s:'DM',x:50,y:49},{pos:'OS',s:'CM',x:70,y:46},{pos:'SB',s:'RB',x:91,y:46},{pos:'FWD',s:'ST',x:34,y:21},{pos:'FWD',s:'ST',x:66,y:21}],
