// ═══════════════════════════════════════════════════════════════
//   FEDERASYON SİSTEMİ — Federation Engine
// ═══════════════════════════════════════════════════════════════
//
// Bir ülkenin tüm liglerindeki tüm takım sahipleri (kaptanlar) o
// ülkenin federasyonunun otomatik üyesidir. Federasyon her sezon
// başkan seçer. Başkan 3 yardımcı atar. Başkan = milli takım T.D.
//
// Storage: cft_federation_<CC>  (per ülke)
// ─────────────────────────────────────────────────────────────

// Türkçe-merkezli kaptan isim havuzu (deterministic seed üretimi için)

// Hızlı ve deterministik seed-bazlı pseudo-random (xorshift varyantı)
function fedSeedRand(seed) {
  let h = (seed | 0) ^ 0x9e3779b9;
  h = Math.imul(h ^ (h >>> 16), 0x85ebca6b);
  h = Math.imul(h ^ (h >>> 13), 0xc2b2ae35);
  h ^= h >>> 16;
  return ((h >>> 0) % 100000) / 100000;
}

function fedKey(cc) { return 'cft_federation_' + (cc || 'TR'); }

// Bir ülkedeki TÜM kaptanları (= federasyon üyeleri) hesapla
// Her takımın 1 kaptanı vardır → toplam üye = ülkedeki takım sayısı
// 🆕 Kaptan ismi/avatar/overall artık takım roster'ından gerçek oyuncudan çekilir
// 🆕 Federasyon etiketleri: T1/T2 yerine gerçek lig adları
function _fedLeagueName(cc, tier) {
  try {
    const c = (typeof _cftGetCountry === 'function') ? _cftGetCountry(cc) : null;
    const lg = ((c && c.leagues) || []).find(l => Number(l.tier) === Number(tier));
    if (lg && lg.name) return lg.name;
  } catch(e) {}
  const t = Number(tier);
  if (!isFinite(t)) return 'Lig';
  return _ligTierEtiketi(t);
}
// Filtre butonları için kısaltılmış ad (uzun lig adları taşmasın)
function _fedLeagueShort(name, tier) {
  const n = String(name || '').trim();
  if (n) {
    if (n.length <= 12) return n;
    return n.replace(/ligi?$/i, 'Lig').slice(0, 12) + '…';
  }
  const t = Number(tier);
  return _ligTierEtiketi(t);
}

// 🆕 563 — Federasyon üyelerinin kaptan bilgisi: eskiden her takım için ayrı AĞIR kadro
//   sorgusu (yetenekler dahil, ülke başına ~57 istek / ~6 MB) atılıyordu; kullanılan tek
//   bilgi kaptanın adı/avatarı/gücü. Artık ülke başına tek hafif sorgu (10 dk önbellek).
//   Seçim kuralı kadroyla AYNI: numara sırasında ilk kaptan/kullanıcı, yoksa en küçük numara.
window._fedKaptanOnb = window._fedKaptanOnb || {};
function _fedKaptanlariYukle(cc) {
  if (!window.sb || !cc) return Promise.resolve(null);
  const o = window._fedKaptanOnb[cc];
  if (o && (o.yukleniyor || (Date.now() - o.t) < 10 * 60 * 1000)) return o.p || Promise.resolve(o);
  const kayit = { t: 0, yukleniyor: true, byTeam: (o && o.byTeam) || null, p: null };
  window._fedKaptanOnb[cc] = kayit;
  kayit.p = (async () => {
    const liste = {};
    for (let from = 0; from < 10000; from += 1000) {
      const { data, error } = await window.sb.from('players')
        .select('team_name,num,name,avatar,avatar_id,is_bot,overall,rating,level,pos,role,nationality,user_id')
        .eq('country_code', cc).order('team_name').order('num').range(from, from + 999);
      if (error || !Array.isArray(data) || !data.length) break;
      for (const r of data) { if (r && r.team_name) (liste[r.team_name] || (liste[r.team_name] = [])).push(r); }
      if (data.length < 1000) break;
    }
    const byTeam = {};
    const liderGercek = {};   // 572 — kulübü gerçek kullanıcı mı yönetiyor (kaptan, yoksa yardımcı kaptan)
    const _yerli = p => String((p && p.nationality) || cc).toUpperCase() === String(cc).toUpperCase();   // 667
    for (const tn in liste) {
      const L = liste[tn];
      const c = L.find(p => p && p.role === 'captain');   // 766 — kaptan yoksa başka oyuncu kaptan sayılmaz
      if (c) byTeam[tn] = c;
      // 667 — yabancı kaptanlı kulüp federasyon üyesi değil; temsil eden gerçek lider de ülkenin uyruğunda olmalı
      const kap = L.find(p => p && !p.is_bot && p.role === 'captain');
      liderGercek[tn] = (!c || _yerli(c)) && (kap ? _yerli(kap) : L.some(p => p && !p.is_bot && p.role === 'vice' && _yerli(p)));
    }
    // 825 — başka ülkedeki kulübün kaptanı da kendi uyruğunun federasyonuna üye (anahtar 'IT|Sondrio')
    const disari = [];
    try {
      const { data: dk } = await window.sb.from('players')
        .select('team_name,country_code,num,name,avatar,avatar_id,is_bot,overall,rating,level,pos,role,nationality,user_id')
        .eq('role', 'captain').ilike('nationality', cc).neq('country_code', cc).limit(300);
      (Array.isArray(dk) ? dk : []).forEach(r => {
        if (!r || !r.team_name || !r.country_code) return;
        const k = String(r.country_code).toUpperCase() + '|' + r.team_name;
        disari.push(r); byTeam[k] = r; liderGercek[k] = !r.is_bot && !!r.user_id;
      });
    } catch (e) {}
    kayit.disari = disari;
    kayit.byTeam = byTeam; kayit.liderGercek = liderGercek; kayit.t = Date.now(); kayit.yukleniyor = false;
    try { if (_fedStateCache[cc]) _fedStateCache[cc]._t = 0; } catch(e) {}   // 826 — üyeler değişti: başkan eşlemesi yeniden yapılsın
    try { if (typeof fedActiveCountry === 'function' && fedActiveCountry() === cc && typeof fedRender === 'function') fedRender(); } catch(e) {}
    try { _ntFedDegisti(cc); } catch(e) {}   // 826
    return kayit;
  })().catch(() => { kayit.yukleniyor = false; kayit.t = Date.now() - 9 * 60 * 1000; return kayit; });
  return kayit.p;
}

function computeFederationMembers(cc) {
  if(false || !_cftGetCountry(cc)) return [];
  const country = _cftGetCountry(cc);
  const members = [];
  let memberIdx = 0;
  country.leagues.forEach((league, lgIdx) => {
    league.teams.forEach((team, teamIdx) => {
      const seed = (cc.charCodeAt(0)*977 + (cc.charCodeAt(1)||0)*131) + (lgIdx * 1000) + teamIdx;
      const id = 'cap_' + cc + '_t' + (lgIdx+1) + '_r' + team.rank;

      // Kullanıcı kontrolü
      const isUserTeam = (typeof _userTeam !== 'undefined' && _userTeam &&
                         _userTeam.countryCode === cc &&
                         _userTeam.teamName === team.name &&
                         _userTeam.role === 'captain');

      // 🆕 Gerçek kaptanı takım roster'ından çek
      let captainName = null;
      let avatar = null;
      let avatar_id = null;
      let captainOverall = null;
      let captainLevel = null;
      let captainPos = null;
      let capIsBot = true;
      let capUyruk = null;   // 667
      let capUid = null;     // 767
      try {
        let captain = null;
        if (isUserTeam && typeof ROSTER_DATA !== 'undefined' && Array.isArray(ROSTER_DATA)) {
          // Kullanıcının takımı: ROSTER_DATA'dan role:'user' olanı
          captain = ROSTER_DATA.find(p => p && (p.role === 'user' || p.role === 'captain'));
        } else {
          // 🆕 563 — önce zaten yüklü kadro (birebir aynı), yoksa ülke başına hafif kaptan
          //   listesi; takım takım ağır kadro sorgusu ATILMAZ.
          const _kk = String(cc).toUpperCase().slice(0, 2) + ':' + team.name;
          const _yuklu = (typeof _teamRosterCache !== 'undefined' && _teamRosterCache && _teamRosterCache[_kk]) ? _teamRosterCache[_kk] : null;
          const _hf = window._fedKaptanOnb && window._fedKaptanOnb[cc];
          const _kap = Array.isArray(_yuklu) ? _yuklu.find(p => p && p.role === 'captain') : null;   // 766 — yalnız gerçek kaptan
          if (_kap) {
            captain = _kap;
          } else if (_hf && _hf.byTeam) {
            const r = _hf.byTeam[team.name];
            if (r) captain = {
              name: r.name, avatar: r.avatar || (r.is_bot ? '🤖' : '👤'), avatar_id: r.avatar_id || null,
              isBot: !!r.is_bot, overall: r.overall || 10, rating: r.rating || 10,
              level: r.level || 0, pos: r.pos, nationality: r.nationality || null, userId: r.user_id || null
            };
          } else {
            _fedKaptanlariYukle(cc);
          }
        }
        if (captain) {
          captainName = captain.name;
          avatar = captain.avatar || '🤖';
          // 🆕 547 — gerçek kaptanın avatar görseli (botlarda yok)
          if (!captain.isBot && captain.avatar_id) avatar_id = captain.avatar_id;
          capIsBot = !!captain.isBot;
          captainOverall = captain.overall || captain.rating || null;
          captainLevel = (typeof captain.level === 'number') ? captain.level : null;
          captainPos = captain.pos || null;
          capUyruk = captain.nationality || null;
          capUid = (!captain.isBot && captain.userId) || null;
        }
      } catch(e) {}

      // Kullanıcının kendi adını/avatarını authUser'dan tercih et (otantik görünüm)
      if (isUserTeam) {
        try {
          if (typeof authUser !== 'undefined' && authUser && authUser.name) captainName = authUser.name;
          if (typeof authUser !== 'undefined' && authUser && authUser.avatar) avatar = authUser.avatar;
          if (typeof authUser !== 'undefined' && authUser && authUser.avatarId) avatar_id = authUser.avatarId;
          if (typeof authUser !== 'undefined' && authUser && authUser.nationality) capUyruk = authUser.nationality;
          if (typeof authUser !== 'undefined' && authUser && authUser.id) capUid = authUser.id;
        } catch(e) {}
      }

      // 667 — FEDERASYON ÜYESİ = kaptanı bu ülkenin uyruğunda olan kulüp. Yabancı kaptanlı kulüp
      //   hiçbir federasyona üye değil (oy, adaylık, başkanlık yok); milli takımı yine uyruğuna göre.
      if (capUyruk && String(capUyruk).toUpperCase() !== String(cc).toUpperCase()) return;

      // Roster çıkmadıysa (nadir) güvenli fallback
      if (!captainName) captainName = team.name + ' Kaptanı';
      if (!avatar) avatar = '🤖';

      const power = Math.round(60 + (16 - Math.min(team.rank,16)) * 1.4 + fedSeedRand(seed+41)*8);
      members.push({
        id,
        fedKey: team.name,   // 825 — federasyon kaydındaki anahtar
        memberNo: ++memberIdx,
        teamRank: team.rank,
        teamName: team.name,
        teamCity: team.city,
        teamShort: team.short,
        teamBg: team.bg,
        teamTc: team.tc,
        countryCode: cc,
        countryName: country.name,
        countryFlag: country.flag,
        captainName,
        avatar,
        avatar_id,
        captainOverall, // 🆕 kaptan gücü roster'dan (gerçek)
        captainLevel,   // 🆕 kaptan seviyesi (level)
        captainPos,     // 🆕 kaptan pozisyonu
        leagueName: league.name,
        leagueColor: league.color,
        tier: league.tier,
        power,
        isUser: isUserTeam,
        captainUid: capUid,   // 767
        isBotCaptain: isUserTeam ? false : capIsBot,
        // Influence skoru: tier yüksekse + rank düşükse daha güçlü oy
        influence: Math.round((7 - league.tier) * 10 + (16 - Math.min(team.rank,16)))
      });
    });
  });
  // 825 — başka ülkedeki kulübün bu ülke uyruklu kaptanı da bu federasyonun üyesi
  const _dis = (window._fedKaptanOnb && window._fedKaptanOnb[cc] && window._fedKaptanOnb[cc].disari) || [];
  _dis.forEach(r => {
    const kcc = String(r.country_code || '').toUpperCase(), kulke = _cftGetCountry(kcc);
    if (!kulke || kcc === String(cc).toUpperCase()) return;
    let li = -1, team = null, league = null;
    (kulke.leagues || []).some((lg, i) => { const t = (lg.teams || []).find(x => x && x.name === r.team_name); if (t) { li = i; team = t; league = lg; } return !!t; });
    if (!team) return;
    const isUserTeam = (typeof _userTeam !== 'undefined' && _userTeam && String(_userTeam.countryCode || '').toUpperCase() === kcc
                        && _userTeam.teamName === team.name && _userTeam.role === 'captain');
    let captainName = r.name, avatar = r.avatar || (r.is_bot ? '🤖' : '👤'), avatar_id = (!r.is_bot && r.avatar_id) || null, capUid = (!r.is_bot && r.user_id) || null;
    if (isUserTeam) {
      try {
        if (typeof authUser !== 'undefined' && authUser && authUser.name) captainName = authUser.name;
        if (typeof authUser !== 'undefined' && authUser && authUser.avatar) avatar = authUser.avatar;
        if (typeof authUser !== 'undefined' && authUser && authUser.avatarId) avatar_id = authUser.avatarId;
        if (typeof authUser !== 'undefined' && authUser && authUser.id) capUid = authUser.id;
      } catch(e) {}
    }
    members.push({
      id: 'cap_' + cc + '_x' + kcc + '_t' + (li + 1) + '_r' + team.rank,
      fedKey: kcc + '|' + team.name, disKulup: true,
      memberNo: ++memberIdx, teamRank: team.rank, teamName: team.name, teamCity: team.city, teamShort: team.short, teamBg: team.bg, teamTc: team.tc,
      countryCode: kcc, countryName: kulke.name, countryFlag: kulke.flag,
      captainName, avatar, avatar_id, captainOverall: r.overall || r.rating || null,
      captainLevel: (typeof r.level === 'number') ? r.level : null, captainPos: r.pos || null,
      leagueName: league.name, leagueColor: league.color, tier: league.tier,
      power: Math.round(60 + (16 - Math.min(team.rank, 16)) * 1.4),
      isUser: isUserTeam, captainUid: capUid, isBotCaptain: isUserTeam ? false : !!r.is_bot,
      influence: Math.round((7 - league.tier) * 10 + (16 - Math.min(team.rank, 16)))
    });
  });
  return members;
}
// 825 — federasyon kulüp anahtarı: 'IT|Sondrio' → { ad: 'Sondrio', cc: 'IT' } · 'Adana' → { ad: 'Adana', cc: federasyonun ülkesi }
function _fedAnahtarCoz(k, cc) {
  const m = /^([A-Z]{2,3})\|(.+)$/.exec(String(k || ''));
  return m ? { ad: m[2], cc: m[1] } : { ad: String(k || ''), cc };
}
function _fedAnahtarAd(k) { return k ? _fedAnahtarCoz(k, '').ad : k; }

// 🆕 Federasyon state'i SUNUCUDAN (federation_state) — RAM cache + fed_tick tetikleme.
// Sunucu otoriter: başkan/seçim/oylar sunucuda; client team_name -> member.id köprüsüyle eşler.
const _fedStateCache = {};
// 🆕 547 — Sunucudan gelen HAM satır (takım adlarıyla). Üye kimliği lig sırası ve
//   sıralamaya bağlı ('cap_TR_t1_r3') ve sıralama/lig değişince kayıyor. Eşleme bir
//   kez yapılıp saklandığında adaylar ve oylar kayboluyordu (ziyaretçide aday listesi
//   boş, oylar yanlış kişide). Artık eşleme ham veriden her okumada tazeleniyor.
const _fedStateRaw = {};
const _fedStateLoaded = {};
const _fedStateLoading = {};
const _fedCandidacy = {};

function _fedServerCandidacy(cc, row, members) {
  const me = members.find(m => m.isUser);
  if (!me || !row) return false;
  const apps = Array.isArray(row.applicants) ? row.applicants : [];
  const cands = Array.isArray(row.candidates) ? row.candidates : [];
  const k = me.fedKey || me.teamName;   // 825
  return apps.includes(k) || cands.includes(k);
}

function _fedBaskanAnahtar(row) { return row ? (row.president_user ? 'u:' + row.president_user : (row.president_team ? 't:' + row.president_team : '')) : ''; }   // 767
function _fedMapState(cc, row, oy) {
  const members = (typeof computeFederationMembers === 'function') ? computeFederationMembers(cc) : [];
  const idByTeam = {}; members.forEach(m => { idByTeam[m.fedKey || m.teamName] = m.id; });   // 825
  const toId = t => idByTeam[t] || null;
  // 572 — Sunucuda kayıt yoksa UYDURMA başkan / yardımcı üretilmez (eskiden en etkili kulüp
  //   "başkan" gösteriliyor, o kulübün kaptanı kendini T.D. sanıyordu).
  const _oy = oy || {};
  const _sayilarTakim = (_oy.sayilar && typeof _oy.sayilar === 'object') ? _oy.sayilar : {};
  const _sayilar = {};
  Object.keys(_sayilarTakim).forEach(t => { const id = toId(t); if (id) _sayilar[id] = Number(_sayilarTakim[t]) || 0; });
  if (!row) {
    return { countryCode: cc, season: 1, presidentId: null, vicePresidentIds: [],
      serverPresidentId: null, serverPresidentTeam: null, serverViceIds: [], vekilUid: null,
      electionPhase: 'closed', electionSeason: null, lastElectedSeason: 0,
      candidates: [], votes: {}, oySayilari: {}, toplamOy: 0, benimOyum: null,
      history: [], fedYardimci: [], userCandidacy: !!_fedCandidacy[cc] };
  }
  const _srvPresId = toId(row.president_team);
  const _oySezonu = (_oy.sezon != null) ? _oy.sezon : null;
  const _gecerliOy = (_oySezonu == null) || (_oySezonu === row.election_season);
  return {
    countryCode: cc,
    season: row.season || 1,
    presidentId: _srvPresId || null,
    // YETKİ yalnızca SUNUCUDAN gelen başkana verilir.
    serverPresidentId: _srvPresId || null,
    serverPresidentTeam: row.president_team || null,
    // 630 — yönetimin devrettiği başkan (bir kulübün lideri değil; sonraki seçime kadar)
    vekilUid: row.president_user || null,
    // 572 — federasyon yardımcı kulübü yok; milli takım yardımcılarını başkan seçer (nt_vices)
    serverViceIds: [],
    vicePresidentIds: [],
    electionPhase: row.election_phase || 'closed',
    electionSeason: row.election_season || null,
    lastElectedSeason: (row.election_phase === 'completed') ? (row.election_season || 0) : 0,
    candidates: (row.candidates || []).map(toId).filter(Boolean),
    // 🆕 524 — başvurular (sonraki seçimin adayları). Sunucu adaylığı hangi alana
    //   yazarsa yazsın ikisi birlikte gösterilir.
    applicants: Array.from(new Set([...(row.applicants || []), ...(row.candidates || [])]))
      .map(t => typeof t === 'string' ? t : (t && (t.team || t.name))).map(toId).filter(Boolean),
    // 572 — oylar gizli: sunucu yalnız aday başına sayı + kendi kulübümün oyunu verir
    votes: {},
    oySayilari: _gecerliOy ? _sayilar : {},
    toplamOy: _gecerliOy ? (Number(_oy.toplam) || 0) : 0,
    benimOyum: (_gecerliOy && _oy.benim) ? toId(_oy.benim) : null,
    history: Array.isArray(row.history) ? row.history : [],
    // 767 — federasyon yardımcıları: atayan başkan değişince geçersiz
    fedYardimci: (row.yardimcilar && row.yardimcilar.baskan === _fedBaskanAnahtar(row) && Array.isArray(row.yardimcilar.uids)) ? row.yardimcilar.uids.filter(Boolean).slice(0, 3) : [],
    userCandidacy: _fedServerCandidacy(cc, row, members) || !!_fedCandidacy[cc]
  };
}

const _fedStateT = {};   // 572 — cc -> son okuma zamanı (seçim/başkan değişince 2 dk içinde yansısın)
async function _loadFedStateFromServer(cc) {
  if (!window.sb) return _fedStateCache[cc] || null;
  if (_fedStateLoaded[cc] && (Date.now() - (_fedStateT[cc] || 0)) < 120000) return _fedStateCache[cc] || null;
  if (_fedStateLoading[cc]) return _fedStateLoading[cc];
  _fedStateLoading[cc] = (async () => {
    try { _fedKaptanlariYukle(cc); } catch(e) {}   // 🆕 563 — paralel, hafif
    const si = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : null;
    if (si && !si.preSeason) {
      await window.sb.rpc('fed_tick', { p_cc: cc, p_season: si.season || 1, p_day: si.dayInSeason || 1, p_hour: new Date().getHours() }).then(()=>{}, ()=>{});
    }
    // 572 — oylar gizli: kim kime oy verdi okunmaz; sunucu yalnız sayıları verir
    const [stRes, oyRes] = await Promise.all([
      window.sb.from('federation_state').select('*').eq('country_code', cc).maybeSingle(),
      window.sb.rpc('fed_oy_durumu', { p_cc: cc }).then(r => r, () => ({ data: null }))
    ]);
    _fedStateLoading[cc] = null;
    _fedStateLoaded[cc] = true;
    _fedStateT[cc] = Date.now();
    const row = stRes && stRes.data;
    const oy = (oyRes && oyRes.data && typeof oyRes.data === 'object') ? oyRes.data : null;
    _fedStateRaw[cc] = { row, oy };
    try { if (typeof ntRolYukle === 'function') ntRolYukle(cc, true); } catch(e) {}
    _fedStateCache[cc] = _fedMapState(cc, row, oy);
    _fedStateCache[cc]._t = Date.now();
    try { _ntFedDegisti(cc); } catch(e) {}   // 826
    if (typeof fedActiveCountry === 'function' && fedActiveCountry() === cc && typeof fedRender === 'function') {
      fedRender();
      // 🆕 547 — seçim sekmesi açıksa o da yenilensin (oy sayısı hemen görünsün)
      const _sec = document.getElementById('fed-election');
      if (_sec && _sec.style.display !== 'none') fedRenderElection();
    }
    return _fedStateCache[cc];
  })();
  return _fedStateLoading[cc];
}

// Federasyon state'i (sunucu cache; yüklenene kadar boş iskelet döner)
function fedLoad(cc) {
  cc = cc || 'TR';
  const _raw = _fedStateRaw[cc];
  if (_raw && (!_fedStateCache[cc] || (Date.now() - (_fedStateCache[cc]._t || 0)) > 1500)) {
    _fedStateCache[cc] = _fedMapState(cc, _raw.row, _raw.oy);
    _fedStateCache[cc]._t = Date.now();
  }
  if (window.sb && (!_fedStateLoaded[cc] || (Date.now() - (_fedStateT[cc] || 0)) > 120000)) _loadFedStateFromServer(cc).catch(()=>{});
  if (_fedStateCache[cc]) return _fedStateCache[cc];
  return _fedMapState(cc, null, null);
}

// Sunucu otoriter — client state yazmaz (no-op)
function fedSave(state) {}

function fedBootstrap(cc) {
  const members = computeFederationMembers(cc);
  if(members.length === 0) return null;
  // İlk başkan: 1. tier en yüksek influence — en büyük kulüp kaptanı
  const sorted = members.slice().sort((a,b) => b.influence - a.influence);
  const presId = sorted[0] ? sorted[0].id : null;
  const vpIds = sorted.slice(1, 4).map(m => m.id); // 3 yardımcı
  const state = {
    countryCode: cc,
    season: 1,
    presidentId: presId,
    vicePresidentIds: vpIds,
    nationalSquad: [],            // Sabit 18 oyuncu (sonra dolduracağız)
    formation: '4-3-3',
    electionPhase: 'closed',      // 'closed' | 'open' | 'completed'
    electionEndDay: null,
    candidates: [],
    votes: {},
    history: []                   // {season, presidentId, presName} listesi
  };
  fedSave(state);
  return state;
}

// Bir üyeyi ID'ye göre bul
function fedFindMember(cc, memberId) {
  const members = computeFederationMembers(cc);
  return members.find(m => m.id === memberId) || null;
}

// Kullanıcı bu federasyonun üyesi mi?
function fedIsUserMember(cc) {
  const members = computeFederationMembers(cc);
  return members.some(m => m.isUser);
}
function fedGetUserMember(cc) {
  const members = computeFederationMembers(cc);
  return members.find(m => m.isUser) || null;
}

// Kullanıcının yetkileri
function fedUserRole(cc) {
  const state = fedLoad(cc);
  const me = fedGetUserMember(cc);
  if (state && state.vekilUid && typeof authUser !== 'undefined' && authUser && authUser.id === state.vekilUid) return 'president';
  if(!state || !me) return 'none';
  // 🆕 Yetki SADECE sunucudaki seçim sonucuna göre (tek dünya). Sunucuda başkan yazılı
  //   değilse kimse başkan sayılmaz — eskiden yerel "en yüksek etkili kulüp" varsayımı
  //   yüzünden her kullanıcı kendini başkan/teknik direktör görebiliyordu.
  if(state.serverPresidentId && state.serverPresidentId === me.id) return 'president';
  return 'member';
}

// Federasyon başkanı = milli takım T.D.
// Bu objeyi page-national hero'da kullanacağız
function fedGetPresident(cc) {
  const state = fedLoad(cc);
  if (state && state.vekilUid) return _fedVekil(cc, state.vekilUid);
  if(!state || !state.presidentId) return null;
  return fedFindMember(cc, state.presidentId);
}
// 630 — Devirle atanan başkanın kartı oyuncu kaydından kurulur (federasyon üyesi olmayabilir)
const _fedVekilOnb = {};   // uid -> { p }
function _fedVekil(cc, uid) {
  const o = _fedVekilOnb[uid];
  if (!o) {
    _fedVekilOnb[uid] = { p: null };
    if (window.sb) window.sb.from('players').select('name,team_name,country_code,level,avatar,avatar_id,pos').eq('user_id', uid).maybeSingle()
      .then(({ data }) => { _fedVekilOnb[uid] = { p: data || null }; if (fedActiveCountry() === cc) fedRender(); },
            () => { delete _fedVekilOnb[uid]; });
    return null;
  }
  const p = o.p;
  if (!p) return null;
  const kulupUlke = _cftGetCountry(p.country_code || cc) || _cftGetCountry(cc);
  return {
    id: 'vekil_' + uid, vekil: true,
    captainName: p.name, avatar: p.avatar || '👤', avatar_id: p.avatar_id || null,
    captainLevel: p.level, captainPos: p.pos,
    teamName: p.team_name || '', countryCode: p.country_code || cc, countryFlag: kulupUlke ? kulupUlke.flag : '',
    isUser: typeof authUser !== 'undefined' && !!authUser && authUser.id === uid, isBotCaptain: false
  };
}
function fedGetVicePresidents(cc) {
  const state = fedLoad(cc);
  if(!state) return [];
  // 572 — federasyonda yardımcı kulüp yok (milli takım yardımcılarını başkan seçer); sahte doldurma yapılmaz
  return (state.vicePresidentIds || []).map(id => fedFindMember(cc, id)).filter(Boolean);
}

// ═══════════════════════════════════════════════════════════════
//   SEÇİM ENGINE
//   • Sezon X gün 1 (00:00) → seçim açılır (electionPhase='open')
//   • Sezon X gün 3 saat 19:00 → sonuçlar (electionPhase='completed')
//   • Aday: top 5 influence + (varsa) kullanıcı
//   • Bot oyları deterministik (cc + season + memberId seed)
// ═══════════════════════════════════════════════════════════════

const FED_ELECTION_END_HOUR = 19; // 3. günün 19:00'ı

function _fedHash(s) {
  let h = 0;
  for(let i = 0; i < s.length; i++) h = ((h << 5) - h + s.charCodeAt(i)) | 0;
  return Math.abs(h);
}

// Adayları belirle — top 5 influence + kullanıcı opt-in
function fedComputeCandidates(cc) {
  const members = computeFederationMembers(cc);
  if(members.length === 0) return [];
  const sorted = members.slice().sort((a,b) => b.influence - a.influence);
  const top5 = sorted.slice(0, 5).map(m => m.id);
  // Kullanıcı opt-in ettiyse listeye ekle (top5 dışındaysa)
  const me = fedGetUserMember(cc);
  if(me && fedIsUserCandidate(cc) && !top5.includes(me.id)) {
    top5.push(me.id);
  }
  return top5;
}

// Kullanıcı sonraki seçime aday olmuş mu?
function fedIsUserCandidate(cc) {
  cc = cc || fedActiveCountry();
  const state = fedLoad(cc);
  if(!state) return false;
  return !!state.userCandidacy;
}

// Aday Ol — kullanıcı sonraki seçime başvurur (her zaman geçerli)
function fedApplyForCandidacy() {
  const cc = fedActiveCountry();
  const state = fedLoad(cc);
  if(!state) return false;
  // Seçim AÇIK iken adaylık kilitli — yeni başvuru kabul edilmez
  if(state.electionPhase === 'open') return false;
  const me = fedGetUserMember(cc);
  if(!me) return false;
  _fedCandidacy[cc] = true;
  if (_fedStateCache[cc]) _fedStateCache[cc].userCandidacy = true;
  if (window.sb) window.sb.rpc('fed_apply_candidacy', { p_cc: cc, p_apply: true })
    .then(({ error }) => { if (error) { console.warn('[fed] aday hata:', error.message); return; } _fedStateLoaded[cc] = false; _loadFedStateFromServer(cc).catch(()=>{}); });
  return true;
}

// Adaylıktan çekil — sadece seçim AÇILMADAN önce
function fedWithdrawCandidacy() {
  const cc = fedActiveCountry();
  const state = fedLoad(cc);
  if(!state) return false;
  // Seçim AÇIK iken çekilemez
  if(state.electionPhase === 'open') return false;
  const me = fedGetUserMember(cc);
  if(!me) return false;
  _fedCandidacy[cc] = false;
  if (_fedStateCache[cc]) _fedStateCache[cc].userCandidacy = false;
  if (window.sb) window.sb.rpc('fed_apply_candidacy', { p_cc: cc, p_apply: false })
    .then(({ error }) => { if (error) { console.warn('[fed] çekilme hata:', error.message); return; } _fedStateLoaded[cc] = false; _loadFedStateFromServer(cc).catch(()=>{}); });
  return true;
}

// Yeni seçim aç
function fedStartElection(cc, season) {
  const state = fedLoad(cc);
  if(!state) return;
  state.electionPhase = 'open';
  state.electionSeason = season;
  state.candidates = fedComputeCandidates(cc);
  state.votes = {};       // memberId → candidateId
  fedSave(state);
}

// Bot oylarını üret + sayım yap + yeni başkan/yardımcılar belirle
function fedFinalizeElection(cc) {
  const state = fedLoad(cc);
  if(!state || state.electionPhase !== 'open') return;
  const members = computeFederationMembers(cc);
  const candIds = state.candidates || [];
  if(candIds.length === 0) {
    state.electionPhase = 'completed';
    state.lastElectedSeason = state.electionSeason;
    fedSave(state);
    return;
  }
  const oldPresId = state.presidentId;

  // Bot oyları (deterministik)
  members.forEach(m => {
    if(m.isUser) return; // kullanıcının oyu zaten state.votes[me.id]'de
    if(state.votes[m.id]) return; // (zaten oy verdiyse atla)

    // Influence ağırlıklı + eski başkana sadakat bonusu
    const weights = candIds.map(id => {
      const cand = members.find(mm => mm.id === id);
      let w = cand ? Math.max(1, cand.influence) : 1;
      if(id === oldPresId) w *= 1.25; // mevcut başkan +25%
      return w;
    });
    const total = weights.reduce((s,w) => s + w, 0);

    // Deterministik random
    const seed = _fedHash(cc + ':' + state.electionSeason + ':' + m.id);
    const r = (seed % 10000) / 10000;

    let acc = 0, chosen = candIds[0];
    for(let i = 0; i < candIds.length; i++) {
      acc += weights[i] / total;
      if(r <= acc) { chosen = candIds[i]; break; }
    }
    state.votes[m.id] = chosen;
  });

  // Sayım
  const tally = {};
  candIds.forEach(id => { tally[id] = 0; });
  Object.values(state.votes).forEach(cId => {
    if(cId in tally) tally[cId] += 1;
  });

  // Sıralama: oy desc, eşitlikte influence desc
  const ranked = candIds.slice().sort((a,b) => {
    if((tally[b]||0) !== (tally[a]||0)) return (tally[b]||0) - (tally[a]||0);
    const ma = members.find(m => m.id === a);
    const mb = members.find(m => m.id === b);
    return (mb?.influence||0) - (ma?.influence||0);
  });

  const newPresId = ranked[0];
  const newVPIds  = ranked.slice(1, 4); // 2-3-4. sıra yardımcılar

  // Tarihçe
  if(!state.history) state.history = [];
  state.history.push({
    season: state.electionSeason,
    presidentId: newPresId,
    presName: members.find(m => m.id === newPresId)?.captainName || '—',
    tally: { ...tally },
    candidates: candIds.slice(),
    timestamp: Date.now()
  });

  state.presidentId = newPresId;
  state.vicePresidentIds = newVPIds;
  state.electionPhase = 'completed';
  state.lastElectedSeason = state.electionSeason;
  fedSave(state);

  // 🆕 Kullanıcı bu federasyonun üyesiyse: seçim sonucunu inbox'a düşür
  try {
    const userMember = fedGetUserMember(cc);
    if (userMember && typeof getInboxMsgs === 'function') {
      const country = (true && _cftGetCountry(cc)) ? _cftGetCountry(cc) : null;
      const countryName = country ? country.name : cc;
      const countryFlag = country ? country.flag : '🏳️';
      const newPres = members.find(m => m.id === newPresId);
      const newPresName = newPres ? newPres.captainName : '—';
      const userWon = (newPresId === userMember.id);
      const userVoteCount = tally[userMember.id] || 0;
      const userTotalVotes = Object.keys(state.votes).length;

      let subject, body, avatar;
      if (userWon) {
        subject = `🎉 ${countryName} Federasyon Başkanı Seçildin!`;
        body = `Tebrikler! ${countryFlag} ${countryName} Futbol Federasyonu ${state.electionSeason}. sezon başkanı olarak seçildin.\n\n` +
               `📊 Oy sonuçları:\n` +
               `• Aldığın oy: ${userVoteCount}/${userTotalVotes}\n\n` +
               `Yetkilerin:\n` +
               `• Milli takım kadrosu seçimi\n• Diziliş ve taktik\n• 3 yardımcı atama\n\n` +
               `Görev sürene başla! 🏛️`;
        avatar = '👑';
      } else if (state.candidates.includes(userMember.id)) {
        subject = `📊 ${countryName} Seçim Sonuçları`;
        body = `Maalesef ${state.electionSeason}. sezon başkan seçimini kazanamadın.\n\n` +
               `🏛️ Yeni başkan: ${newPresName}\n` +
               `📊 Senin oyun: ${userVoteCount}/${userTotalVotes}\n\n` +
               `Bir sonraki sezon tekrar aday olabilirsin.`;
        avatar = '🗳️';
      } else {
        subject = `🏛️ ${countryName} Yeni Federasyon Başkanı`;
        body = `${state.electionSeason}. sezon ${countryFlag} ${countryName} Futbol Federasyonu başkan seçimi tamamlandı.\n\n` +
               `Yeni başkan: ${newPresName}\n` +
               `Toplam oy: ${userTotalVotes}\n\n` +
               `Federasyon Yetkiler sekmesinden detayları görebilirsin.`;
        avatar = '🏛️';
      }

      const msgs = getInboxMsgs();
      if (msgs) {
        msgs.unshift({
          id: 'fed_election_' + cc + '_s' + state.electionSeason + '_' + Date.now(),
          from: `${countryFlag} ${countryName} Federasyonu`,
          fromAvatar: avatar,
          subject, body,
          time: new Date().toLocaleDateString('tr'),
          read: false,
          type: 'system',
          thread: [],
        });
        if (typeof saveInboxMsgs === 'function') saveInboxMsgs(msgs);
        if (typeof inboxUpdateBadge === 'function') inboxUpdateBadge();
      }
    }
  } catch(e) { console.warn('[Fed] inbox mesajı hatası:', e); }
}

// Sunucu (fed_tick, federasyon sayfası açılınca) yönetiyor — client günlük tick yok
function fedDailyTickAll() {}

// Periyodik kontrol — sunucu (fed_tick) yönetiyor; client yalnız sunucu state'ini yükler
function fedTickElection(cc) {
  if (typeof _loadFedStateFromServer === 'function') _loadFedStateFromServer(cc).catch(()=>{});
}

// Kullanıcı oyu — sunucuya fed_cast_vote RPC ile
function fedVote(candidateId) {
  const cc = fedActiveCountry();
  const state = fedLoad(cc);
  if(!state || state.electionPhase !== 'open') return false;
  const me = fedGetUserMember(cc);
  if(!me) return false;
  // 🆕 Sunucudaki aday listesi boş olabilir (kimse resmi başvurmadı) —
  //   bu durumda canlı hesaplanan aday listesi geçerli sayılır.
  // 🆕 524 — yalnızca başvuru yapmış adaylara oy verilir (bot yedek listesi yok)
  const _gecerli = Array.from(new Set([...(state.candidates || []), ...(state.applicants || [])]));
  if(!_gecerli.includes(candidateId)) return false;
  if(state.benimOyum) return false;
  const cand = computeFederationMembers(cc).find(m => m.id === candidateId);
  if(!cand || !window.sb) return false;
  // 🆕 547 — Sunucu onayı beklenir; onaylanınca oy ANINDA sayıma eklenir.
  //   Eskiden sekme RPC bitmeden çiziliyor, sonra da yenilenmiyordu → "0 oy",
  //   ancak oyundan çıkıp girince 1 görünüyordu.
  const _ck = cand.fedKey || cand.teamName;   // 825
  return window.sb.rpc('fed_cast_vote', { p_cc: cc, p_candidate_team: _ck })
    .then(({ error }) => {
      if (error) { console.warn('[fed] oy hata:', error.message); window._fedSonOyHatasi = error.message || ''; return false; }
      const _raw = _fedStateRaw[cc];
      if (_raw) {
        const o = Object.assign({ sayilar: {}, toplam: 0 }, _raw.oy || {});
        o.sayilar = Object.assign({}, o.sayilar); o.sayilar[_ck] = (Number(o.sayilar[_ck]) || 0) + 1;
        o.toplam = (Number(o.toplam) || 0) + 1; o.benim = _ck;
        if (_raw.row && o.sezon == null) o.sezon = _raw.row.election_season;
        _raw.oy = o;
        if (_fedStateCache[cc]) _fedStateCache[cc]._t = 0;
      }
      _fedStateLoaded[cc] = false;
      _loadFedStateFromServer(cc).catch(()=>{});
      return true;
    }, () => false);
}

// Mevcut tally (UI için anlık görüntü)
function fedGetTally(cc) {
  const state = fedLoad(cc);
  if(!state) return {};
  const tally = {};
  Array.from(new Set([...(state.candidates || []), ...(state.applicants || [])])).forEach(id => { tally[id] = 0; });
  const S = state.oySayilari || {};
  Object.keys(S).forEach(id => { tally[id] = S[id]; });
  return tally;
}

// Kullanıcının verdiği oy (varsa)
function fedGetUserVote(cc) {
  const state = fedLoad(cc);
  if(!state) return null;
  const me = fedGetUserMember(cc);
  if(!me) return null;
  return state.benimOyum || null;
}

// Seçim sonuna kalan süre — UI için
function _fedSecimZamanlari(info) {
  // 572 — Sunucu: oylama sezonun 1. günü (UTC) açılır, 3. gün 19:00 TSİ'de (16:00 UTC) sonuçlanır.
  //   Eskiden cihazın yerel saatiyle 19:00 hesaplanıyordu (yurtdışında yanlış geri sayım).
  if (!info || !info.seasonStart) return null;
  const bas = new Date(info.seasonStart.getTime());
  const bit = new Date(info.seasonStart.getTime() + 2 * 86400000 + 16 * 3600000);
  const saat = (d) => String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
  return { bas, bit, basSaat: saat(bas), bitSaat: saat(bit) };
}
function fedElectionTimeLeft() {
  const info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : null;
  if(!info) return null;
  const day = info.dayInSeason;
  if(day > 3 || day < 1) return { ended: true };
  const z = _fedSecimZamanlari(info);
  if(!z) return null;
  const target = z.bit;
  const ms = target.getTime() - Date.now();
  if(ms <= 0) return { ended: true };
  const totalMin = Math.floor(ms / 60000);
  const days = Math.floor(totalMin / (60*24));
  const hrs  = Math.floor((totalMin % (60*24)) / 60);
  const mins = totalMin % 60;
  return { ended:false, days, hrs, mins, target };
}


// ═══════════════════════════════════════════════════════════════
//   FEDERASYON UI — Render & Tab
// ═══════════════════════════════════════════════════════════════

function fedActiveCountry() {
  // 572 — FEDERASYON = kulübünün ülkesi. 667: yabancı kaptan bu federasyonda İzleyici (üye değil).
  //   Takımsızsa uyruğu. Milli takım sayfası kendi ülkesini ntActiveCountry() ile bilir.
  try {
    if(typeof _userTeam !== 'undefined' && _userTeam && _userTeam.countryCode) {
      // 825 — kaptan, kulübü hangi ülkede olursa olsun kendi uyruğunun federasyonuna üye
      const _uy = (typeof authUser !== 'undefined' && authUser && authUser.nationality) ? String(authUser.nationality).toUpperCase() : '';
      if (_userTeam.role === 'captain' && _uy && _uy !== String(_userTeam.countryCode).toUpperCase() && _cftGetCountry(_uy)) return _uy;
      return _userTeam.countryCode;
    }
    if(typeof authUser !== 'undefined' && authUser && authUser.nationality) return authUser.nationality;
  } catch(e) {}
  return 'TR';
}

// 572 — KENDİ MİLLİ TAKIMIN = UYRUĞUN (kulübün hangi ülkede olduğu fark etmez)
function ntOwnCountry() {
  try {
    if (typeof authUser !== 'undefined' && authUser && authUser.nationality) return authUser.nationality;
    if (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.countryCode) return _userTeam.countryCode;
  } catch(e) {}
  return 'TR';
}
// Milli takım sayfasında görüntülenen ülke
function ntActiveCountry() {
  try { if (window._ntViewingCC) return window._ntViewingCC; } catch(e) {}
  return ntOwnCountry();
}
window.ntActiveCountry = ntActiveCountry;
window.ntOwnCountry = ntOwnCountry;

// Görüntülenen ülke değişince eski ülkenin diziliş/yedek/strateji durumunu bırak
let _ntSonCC = null;
function _ntUlkeDegistiKontrol() {
  const cc = ntActiveCountry();
  if (_ntSonCC === cc) return false;
  _ntSonCC = cc;
  try { NT_ROSTER_DATA = []; _ntCachedCC = null; } catch(e) {}
  try { _ntActivePitchPlayers = []; } catch(e) {}
  try { _ntMatchSquadBench = []; _ntBenchUserManaged = false; } catch(e) {}
  try { _ntStrategyCache = null; _ntStrategyCC = null; _ntDizilisDurum = 'yok'; } catch(e) {}
  try { if (typeof _ntChatAboneKapat === 'function') _ntChatAboneKapat(); } catch(e) {}
  return true;
}

// 🆕 Başka bir ülkenin milli takımını aç — ziyaretçi, ya da o ülkede başkan/yardımcıysan yönetici
function ntViewAsGuest(cc) {
  if (!cc || typeof _cftGetCountry !== 'function' || !_cftGetCountry(cc)) return;
  window._ntViewingCC = (cc === ntOwnCountry()) ? null : cc;
  _ntUlkeDegistiKontrol();
  try { if (typeof ntRolYukle === 'function') ntRolYukle(cc); } catch(e) {}
  const pageEl = document.getElementById('page-national');
  if (pageEl) pageEl.classList.toggle('nt-guest-mode', !!window._ntViewingCC && !(typeof ntRol === 'function' && ntRol(cc)));
  if (typeof showPage === 'function') showPage('national');
  setTimeout(() => { try { _ntZiyaretciModuUygula(); } catch(e) {} }, 30);
}
// 572 — Federasyon başkanı / yardımcısı: yönettiği milli takımı aç (başka ülkenin milli takımı olabilir)
function ntYonet(cc) { ntViewAsGuest(cc || fedActiveCountry()); }
window.ntYonet = ntYonet;

// Kendi milli takımına dön
function ntExitGuest() {
  window._ntViewingCC = null;
  _ntUlkeDegistiKontrol();
  const pageEl = document.getElementById('page-national');
  if (pageEl) pageEl.classList.remove('nt-guest-mode');
  if (typeof ntRender === 'function') ntRender();
  try { _ntZiyaretciModuUygula(); } catch(e) {}
  const activeTab = document.querySelector('#page-national .team-tab.active');
  if (activeTab) {
    const tab = activeTab.dataset.ntTab;
    if (tab && typeof ntTab === 'function') ntTab(tab, activeTab);
  }
}

function fedTab(name, el) {
  const PANES = ['board','members','election','powers'];
  PANES.forEach(t => {
    const e = document.getElementById('fed-' + t);
    if(e) e.style.display = t === name ? 'block' : 'none';
  });
  document.querySelectorAll('#page-federation .team-tab').forEach(t => t.classList.remove('active'));
  if(el) el.classList.add('active');
  if(name === 'members') fedRenderMembers();
  if(name === 'board')   fedRenderBoard();
  if(name === 'powers')  fedRenderPowers();
  if(name === 'election'){ fedTickElection(fedActiveCountry()); fedRenderElection(); }
}

