// Kaydet (toast)
// 🆕 NT diziliş/strateji: bekleyen debounce kaydını HEMEN team_data'ya yaz (çıkışta/kaydet'te kaybolmasın)
async function flushNtStrategySave() {
  if (!_ntStrategySaveTimer) return;
  clearTimeout(_ntStrategySaveTimer); _ntStrategySaveTimer = null;
  if (!window.sb || !_ntStrategyCache) return;
  // 🆕 506: Yetkisiz kullanıcıda sunucuya hiç gitme (RLS 403'ü önler).
  if (!_ntStratYazabilir()) return;
  try {
    await _ntTaktikYaz(_ntStrategyCC || ntActiveCountry(), _ntStrategyCache);
  } catch(e) { console.warn('[nt_strategy] flush hata:', e); }
}

function ntSaveFormation() {
  if (typeof ntTaktikKilitUyari === 'function' && ntTaktikKilitUyari()) return;   // 584
  if(!ntCanEditFormation()) { _ntNoPermToast(); return; }
  const _cnt = Array.isArray(_ntActivePitchPlayers) ? _ntActivePitchPlayers.filter(e=>e&&e.player).length : 0;
  if (_cnt < 11) { if (typeof showToast === 'function') showToast('İlk 11 tamamlanmadan kaydedilemez (' + _cnt + '/11)'); return; }
  ntSaveStrategy(true);
  try { flushNtStrategySave(); } catch(_){}
  const toast = document.createElement('div');
  toast.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:var(--accent);color:var(--bg);padding:8px 18px;border-radius:20px;font-size:12px;font-weight:700;z-index:9999;font-family:Twemoji Country Flags,"Barlow Condensed",sans-serif;letter-spacing:.5px';
  toast.textContent = '✅ Diziliş kaydedildi!';
  document.body.appendChild(toast);
  setTimeout(()=>toast.remove(), 2000);
}

// Strateji paneli
function ntOpenStrategyPanel() {
  if(!ntCanEditFormation()) { _ntNoPermToast(); return; }
  tkAc('milli');   // 586 — oyun planı (hazır stil + 6 boyut)
  document.getElementById('nt-strategyPanel').classList.add('open');
}
function ntCloseStrategyPanel() {
  document.getElementById('nt-strategyPanel').classList.remove('open');
  tkOzetCiz();
}
function ntUpdateSliderLabel(sliderId, labelId) {
  const s = document.getElementById(sliderId);
  const l = document.getElementById(labelId);
  if(s && l) l.textContent = s.value;
}

// ────────── SOHBET render ──────────
// ═══════════════════════════════════════════════════════════════════════
// 🆕 MİLLİ TAKIM SOHBETİ — GERÇEK MESAJLAŞMA
//   Eskiden bu bölüm sabit-kodlu sahte mesajlar basıyordu; gönder butonunun
//   çağırdığı ntSendChat fonksiyonu HİÇ TANIMLI DEĞİLDİ (ReferenceError).
//   Artık kulüp sohbetiyle aynı `team_chat` tablosunu kullanır:
//     country_code = ülke kodu · team_name = milli takım adı (ör. "Türkiye")
//   Mesaj kartlarını kulüp sohbetinin _teamChatAppendMsg'i çizer (aynı görünüm).
// ═══════════════════════════════════════════════════════════════════════
function _ntChatTakimAdi() {
  return (typeof _ntCountryName === 'function') ? _ntCountryName()
       : (ntActiveCountry());
}
function _ntChatUlke() {
  return ntActiveCountry();
}

function ntRenderChat() {
  const el = document.getElementById('nt-chat');
  if(!el) return;
  // 🆕 526 — kadroda olmayan sohbeti göremez / yazamaz
  if (typeof _ntTamErisim === 'function' && !_ntTamErisim()) {
    el.innerHTML = '';
    try { _ntZiyaretciModuUygula(); } catch(e) {}
    return;
  }
  el.innerHTML = `
    <div class="vt-section nt-chat-section">
      <div class="chat-header-row">
        <div class="vt-title" style="margin:0">💬 Milli Takım Sohbeti</div>
      </div>
      <div class="chat-area" id="ntChatArea"></div>
      <div class="chat-input-row">
        <input class="chat-input" type="text" id="ntChatInput" maxlength="300" autocomplete="off" autocorrect="off" autocapitalize="sentences" enterkeyhint="send" name="csc-sohbet-mesaji" data-lpignore="true" data-1p-ignore data-form-type="other"
               placeholder="Milli takıma mesaj yaz..." onkeydown="if(event.key==='Enter')ntSendChat()"/>
        <button class="chat-send" onmousedown="event.preventDefault()" tabindex="-1" onclick="ntSendChat()">→</button>
      </div>
    </div>
  `;
  try { _ntChatYukleVeCiz(); } catch(e) { console.warn('[nt_chat] render hata:', e); }
  try { _msCiz(); if (_msAcikMi()) _msOkundu(); } catch(e) {}   // 834
}

async function _ntChatYukleVeCiz() {
  const area = document.getElementById('ntChatArea');
  if (!area || !window.sb) return;
  const cc = _ntChatUlke();
  const ntName = _ntChatTakimAdi();
  try {
    const { data, error } = await window.sb.from('team_chat')
      .select('user_id, username, display_name, avatar_id, message, created_at')
      .eq('country_code', cc)
      .eq('team_name', ntName)
      .order('created_at', { ascending: false })
      .limit(200);
    if (error) { console.warn('[nt_chat] okuma hata:', error.message || error); return; }
    const myId = (typeof authUser !== 'undefined' && authUser) ? authUser.id : null;
    area.innerHTML = '';
    area._adRenk = null;   // 770
    const msgs = (data || []).slice().reverse();
    if (!msgs.length) {
      area.innerHTML = '<div style="padding:18px 10px;text-align:center;color:var(--text3);font-size:11.5px">'
        + 'Henüz mesaj yok — ilk yazan sen ol.</div>';
    } else {
      for (const m of msgs) {
        if (typeof _teamChatAppendMsg === 'function') {
          _teamChatAppendMsg(area, m, m.user_id && m.user_id === myId);
        }
      }
    }
    area.scrollTop = area.scrollHeight;
    requestAnimationFrame(() => { area.scrollTop = area.scrollHeight; });
    _ntChatAbone();
  } catch(e) { console.warn('[nt_chat] okuma hata:', e); }
}

// Realtime — kulüp sohbetiyle aynı desen, ayrı kanal
let _ntChatChannel = null;
let _ntChatChannelKey = null;
function _ntChatAbone() {
  if (!window.sb) return;
  const cc = _ntChatUlke();
  const ntName = _ntChatTakimAdi();
  const key = cc + ':' + ntName;
  if (_ntChatChannelKey === key && _ntChatChannel) return;
  if (_ntChatChannel) { try { window.sb.removeChannel(_ntChatChannel); } catch(e) {} _ntChatChannel = null; }
  const benId = () => (typeof authUser !== 'undefined' && authUser && authUser.id) || null;   // 721
  _ntChatChannelKey = key;
  // 690 — kulüp sohbetiyle aynı: veritabanı yayını ('mesaj': kimlik) → içerik tablodan, sırayla
  let _ntSira = Promise.resolve();
  const _ntIsle = (payload) => {
      const m = payload.new;
      if (!m || m.country_code !== cc || m.team_name !== ntName) return;
      if (m.user_id && m.user_id === benId()) return;   // kendi mesajım zaten eklendi
      const area = document.getElementById('ntChatArea');
      if (!area) return;
      const bos = area.querySelector('div[style*="Henüz mesaj yok"]');
      if (bos) area.innerHTML = '';
      if (typeof _teamChatAppendMsg === 'function') _teamChatAppendMsg(area, m, false);
      area.scrollTop = area.scrollHeight;
      try { if (_msAcikMi()) _msOkunduErtele(); } catch(e) {}   // 834
  };
  _ntChatChannel = window.sb.channel('nt_chat:' + key)
    .on('broadcast', { event: 'mesaj' }, (msg) => {
      const p = msg && msg.payload;
      if (!p || p.mid == null || (p.u && p.u === benId())) return;
      _ntSira = _ntSira.then(async () => {
        const { data } = await window.sb.from('team_chat')
          .select('id, country_code, team_name, user_id, username, display_name, avatar_id, message, created_at')
          .eq('id', p.mid).maybeSingle();
        if (data) _ntIsle({ new: data });
      }).catch((e) => console.warn('[nt_chat] mesaj okunamadı:', e));
    })
    .subscribe();
}
function _ntChatAboneKapat() {
  if (_ntChatChannel) { try { window.sb.removeChannel(_ntChatChannel); } catch(e) {} }
  _ntChatChannel = null; _ntChatChannelKey = null;
}
window._ntChatAboneKapat = _ntChatAboneKapat;

async function ntSendChat() {
  const inp = document.getElementById('ntChatInput');
  if (!inp || !inp.value.trim()) return;
  // 🆕 526 — yalnızca kadrodakiler (ve T.D. / yardımcılar) yazabilir
  if (typeof _ntTamErisim === 'function' && !_ntTamErisim()) {
    if (typeof showToast === 'function') showToast('Milli takım sohbetine yalnızca kadrodaki oyuncular yazabilir.');
    return;
  }
  const area = document.getElementById('ntChatArea');
  if (!area) return;
  const text = modFiltre(inp.value.trim().slice(0, 300));
  inp.value = '';

  const me = (typeof authUser !== 'undefined' && authUser) ? authUser : {};
  // Anında kendi mesajını göster
  const bos = area.querySelector('div[style*="Henüz mesaj yok"]');
  if (bos) area.innerHTML = '';
  if (typeof _teamChatAppendMsg === 'function') {
    _teamChatAppendMsg(area, {
      user_id: me.id || null,
      display_name: me.name || me.username || 'Sen',
      avatar_id: me.avatarId || null,
      message: text,
      created_at: new Date().toISOString()
    }, true);
  }
  area.scrollTop = area.scrollHeight;
  requestAnimationFrame(() => { area.scrollTop = area.scrollHeight; });
  inp.focus();

  if (!window.sb) return;
  try {
    const { error } = await window.sb.from('team_chat').insert({
      country_code: _ntChatUlke(),
      team_name: _ntChatTakimAdi(),
      user_id: me.id || null,
      username: me.username || null,
      display_name: me.name || me.username || null,
      avatar_id: me.avatarId || null,
      message: text
    });
    if (error) {
      console.warn('[nt_chat] gönderilemedi:', error.message || error);
      if (typeof showToast === 'function') showToast(ntHataMetni(error, 'Mesaj gönderilemedi'));
    } else if (typeof achBump === 'function') { achBump('chat'); }
  } catch(e) {
    console.warn('[nt_chat] gönderilemedi:', e);
    if (typeof showToast === 'function') showToast('Mesaj gönderilemedi');
  }
}
window.ntSendChat = ntSendChat;

// ═══════════════════════════════════════════════════════════════════════
// FEDERASYON YETKİLİSİ — Milli Takıma Davet
// Yetki: kullanıcının kendi ülkesinin federasyon başkanı veya 3 yardımcısından biri
// Şart: davet edilen oyuncunun uyruğu (= takımının ülkesi) kullanıcının ülkesi olmalı
// Onay gerekmez — milli takım daveti zorunludur. Oyuncuya inbox mesajı gider.
// ═══════════════════════════════════════════════════════════════════════

// 572 — Kullanıcı bu milli takımda yetkili mi (başkan / başkanın seçtiği yardımcı)?
//   cc verilmezse görüntülenen milli takım.
function fedUserIsOfficial(cc) {
  return (typeof ntRol === 'function') && !!ntRol(cc || ntActiveCountry());
}

// Bir oyuncu milli takıma çağrılabilir mi? Ölçüt oyuncunun UYRUĞU (kulübünün ülkesi değil).
// Dönen obj: { allowed:bool, reason:string, alreadyInSquad:bool }
function fedCallupCheck(player, ctx) {
  if (!player) return { allowed: false, reason: 'Oyuncu yok' };
  const cc = (ctx && ctx.playerNationality) || player.nationality || null;
  if (!cc) return { allowed: false, reason: 'Oyuncu uyruğu belirsiz' };
  if (!fedUserIsOfficial(cc)) return { allowed: false, reason: 'Yetkin yok' };
  const pool = ntPlayerPool(cc);
  const pp = _ntHavuzdaBul(cc, player, ctx);
  if (!pp) return { allowed: false, reason: pool.length ? 'Oyuncu havuzda bulunamadı' : 'Havuz yükleniyor…' };
  const e = _ntEtkinKadroYer(cc, pool);
  const i = e.ids.indexOf(pp.ntId);
  if (i !== -1 && !e.oto[i]) return { allowed: false, reason: 'Zaten milli takımda', alreadyInSquad: true };
  return { allowed: true, reason: 'OK' };
}

// 🆕 Uyruk denetimi — Almanya'da oynayan Türk ✔ / Türkiye'de oynayan Alman ✘
function _ntEligible(cc, p) {
  if (!p) return false;
  const nat = p.nationality || null;
  if (!nat) return false;
  return String(nat).toUpperCase() === String(cc).toUpperCase();
}

// Havuzda oyuncuyu bul: ntId → uuid → ad + kulüp
function _ntHavuzdaBul(cc, player, ctx) {
  const pool = ntPlayerPool(cc);
  let pp = null;
  if (player.ntId) pp = pool.find(p => p && p.ntId === player.ntId);
  if (!pp && player.id) pp = pool.find(p => p && p.id === player.id);
  const takim = (ctx && ctx.teamName) || player._team || player.sourceClub || null;
  if (!pp) pp = pool.find(p => p && p.name === player.name && (!takim || p.sourceClub === takim));
  return pp || null;
}

// Yetkili: oyuncuyu milli takıma çağır (zorunlu, onay gerekmez).
//   Bildirimi SUNUCU gönderir ("Milli Takıma Seçildin") — istemci ayrıca mesaj yazmaz.
function fedCallupPlayer(payloadStr) {
  let payload;
  try { payload = JSON.parse(payloadStr); } catch(e) { return; }
  const { player, ctx } = payload || {};
  if (!player) return;
  const cc = (ctx && ctx.playerNationality) || player.nationality || ntActiveCountry();
  if (!_ntEligible(cc, player) && !(ctx && ctx.playerNationality)) {
    if (typeof showToast === 'function') showToast('Bu oyuncu bu ülkenin uyruğunda değil');
    return;
  }
  const check = fedCallupCheck(player, ctx);
  if (!check.allowed) { if (typeof showToast === 'function') showToast(check.reason); return; }
  const pp = _ntHavuzdaBul(cc, player, ctx);
  if (!pp) return;
  if (ntKadroCagir(pp.ntId, cc) && typeof closePlayerModal === 'function') closePlayerModal();
}

// Yetkili: oyuncuyu milli takım kadrosundan çıkar
function fedRemoveFromNT(payloadStr) {
  let payload;
  try { payload = JSON.parse(payloadStr); } catch(e) { return; }
  const { player, ctx } = payload || {};
  if (!player) return;
  const cc = (ctx && ctx.playerNationality) || player.nationality || ntActiveCountry();
  if (!fedUserIsOfficial(cc)) { if (typeof showToast === 'function') showToast('Yetkin yok'); return; }
  const pp = _ntHavuzdaBul(cc, player, ctx);
  if (!pp) { if (typeof showToast === 'function') showToast('Kadroda değil'); return; }
  if (ntKadroCikar(pp.ntId, cc) && typeof closePlayerModal === 'function') closePlayerModal();
}

