// Sayım statik (oyuncu giriş/çıkış bot olmadığı için sabit) — periyodik refresh gerekmez
// ama updateHero() her çağrıldığında çağrılıyor; o yeterli.

// Hero banner'ı dinamik güncelle
function updateHero() {
  const info = getSeasonInfo();
  const today = new Date();
  // 🆕 Bildirim/sezon kontrolleri sayfadan bağımsız HER ZAMAN çalışır (davranış korunur).
  if(typeof checkSeasonEndTrigger === 'function') checkSeasonEndTrigger();
  if(typeof checkContractExpiration === 'function') checkContractExpiration();
  if(typeof runAllNotificationChecks === 'function') runAllNotificationChecks();
  // 🆕 Ana sayfa görünür DEĞİLSE ağır home render'larını ATLA — home'a dönünce showPage updateHero'yu zaten çağırır.
  try { const _hp = document.getElementById('page-home'); if(!(_hp && _hp.classList.contains('active'))) return; } catch(e){}
  const dateEl = document.getElementById('heroDate');
  const titleEl = document.getElementById('heroTitle');
  const statusEl = document.getElementById('heroStatus');
  const subEl = document.getElementById('heroSubtitle');

  if(dateEl) dateEl.textContent = formatTrDate(today);

  // heroStatus artık statik (oyuncu sayacı + takvim ikonu) — innerHTML değiştirme
  const seasonLblEl = document.getElementById('heroSeasonLbl');
  // 751 — üst kutu: kalan gün + sezon çubuğu
  const kalanEl = document.getElementById('heroKalan'), barEl = document.getElementById('heroBar');
  if (kalanEl) kalanEl.textContent = `${info.preSeason ? info.daysToStart : info.SEASON_LEN - info.dayInSeason} gün kaldı`;
  if (barEl) barEl.style.width = info.preSeason ? '0%' : (info.dayInSeason / info.SEASON_LEN * 100).toFixed(1) + '%';
  if(info.preSeason) {
    if(titleEl) titleEl.innerHTML = `Sezon <span>Başlıyor</span>`;
    if(seasonLblEl) seasonLblEl.textContent = `Sezonun başlamasına ${info.daysToStart} gün kaldı`;
    if(subEl) subEl.textContent = `Sezon 1 başlangıcı: 1 Haziran 2026`;
  } else {
    if(titleEl) titleEl.innerHTML = `Sezon <span>${info.season}</span> · Gün ${info.dayInSeason}`;
    if(seasonLblEl) seasonLblEl.textContent = `Sezonun sona ermesine ${info.SEASON_LEN - info.dayInSeason} gün kaldı`;
    if(subEl) subEl.textContent = `Süper Lig · Sezon ${info.season} · Gün ${info.dayInSeason} / ${info.SEASON_LEN}`;
  }
  // Oyuncu sayacını güncelle (mevcut + online)
  if(typeof updateHomePlayersCounter === 'function') updateHomePlayersCounter();

  // Home sayfası iç içeriğini de güncelle
  renderHomeUserCard();
  renderHomeSmartAction();
  renderHomeQuickAccessBadges();
  renderHomeEventFeed();
  if(typeof renderHomeRankingSummary==='function') renderHomeRankingSummary();
  renderHomeNextMatch();
  // (bildirim kontrolleri yukarı taşındı — sayfadan bağımsız çalışır)

  // Sezon içeriği bloğu
  // - Pre-season + takımı var → gizle (etkinlik feed yeterli)
  // - Pre-season + takımsız → "Takıma Katıl" panelini hep göster (kullanıcı boş ana sayfa görmesin)
  // - Sezon + takımsız → "Takıma Katıl" paneli
  // - Sezon + takımı var → Lig Sahnesi + Avrupa Sahnesi
  const genSec = document.getElementById('hmGeneralSection');
  const hasTeam = (typeof userHasTeam === 'function') ? userHasTeam() : !!(typeof _userTeam !== 'undefined' && _userTeam);

  if(genSec) {
    // Pre-season + takımı var → tamamen gizle
    // Diğer tüm durumlarda göster (içerik branch'i aşağıda)
    if (info.preSeason && hasTeam) {
      genSec.style.display = 'none';
    } else {
      genSec.style.display = 'block';
      const withTeam = document.getElementById('hmGeneralWithTeam');
      const noTeam = document.getElementById('hmGeneralNoTeam');
      // 🆕 Lig + Avrupa sahnesi takımsız oyuncuya da gösterilir.
      //    Takımsızken ek olarak "Takıma Katıl" kartı da görünür.
      if (withTeam) withTeam.style.display = 'block';
      if (noTeam) noTeam.style.display = hasTeam ? 'none' : 'block';
    }
  }

  // 🆕 Takım şartı kaldırıldı: takımsız oyuncu da uyruğunun lig özetini
  //    ve Avrupa sahnesini görür. Lig paneli, oyuncunun ülkesinin ligi
  //    yoksa renderHomeLeagueScene içinde kendini gizler.
  if(!info.preSeason) {
    renderHomeLeagueScene();
    renderHomeEuro();
  }
}

// ══ HOME — 1) Kullanıcı Hero Kartı ══
function renderHomeUserCard() {
  const wrap = document.getElementById('hmUserCard');
  if(!wrap) return;
  const user = authUser || {};
  const me = (typeof ROSTER_DATA !== 'undefined') ? ROSTER_DATA.find(p => p.role === 'user' && !p.isBot) : null;

  // Avatar (authUser.avatarId)
  const avatarEmoji = (typeof getAvatarEmoji === 'function')
    ? getAvatarEmoji(user.avatarId, user.position)
    : '🧑';
  const set = (id, val) => { const el = document.getElementById(id); if(el) el.textContent = val; };
  // Avatar HTML olabilir (img tag), innerHTML kullan
  const avEl = document.getElementById('hmUcAvatar');
  if(avEl) avEl.innerHTML = avatarEmoji;
  set('hmUcName', user.name || 'Oyuncu');

  const lvl = (me && typeof me.level === 'number') ? me.level : 0;
  const xp = (me && typeof me.xp === 'number') ? me.xp : 0;
  set('hmUcLevel', lvl);

  // Takım + rol
  let teamLine = '🚫 Takımsız · Yeni başlangıç';
  if(typeof userHasTeam === 'function' && userHasTeam() && _userTeam) {
    const cc = _userTeam.countryCode;
    const flag = (true && _cftGetCountry(cc)) ? _cftGetCountry(cc).flag : '';
    const role = _userTeam.role === 'captain' ? '👑 Kaptan'
              : _userTeam.role === 'vice'    ? '⭐ Yrd. Kaptan'
              : '👥 Üye';
    teamLine = `${flag} ${_userTeam.teamName} · ${role}`;
  }
  set('hmUcTeam', teamLine);

  // XP Bar
  const needed = (typeof rosterXpForLevel === 'function') ? rosterXpForLevel(lvl) : 60;
  const pct = Math.min(100, Math.round((xp / needed) * 100));
  const fill = document.getElementById('hmUcXpFill');
  if(fill) fill.style.width = pct + '%';
  set('hmUcXpPct', `${xp}/${needed} XP`);
}

// ══ HOME — 2) Akıllı Aksiyon Kartı (bağlam-duyarlı) ══
// Önceliklere göre en önemli işlemi gösterir.
function renderHomeSmartAction() {
  const card = document.getElementById('hmActionCard');
  if(!card) return;

  const info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : { preSeason: true, daysToStart: 0 };
  const inboxMsgs = (typeof getInboxMsgs === 'function') ? getInboxMsgs() : [];
  const unreadInbox = inboxMsgs.filter(m => !m.read && !m.sent).length;

  // Aktif antrenman var mı?
  let activeTrainingCount = 0;
  try {
    const list = (typeof trGetActive === 'function') ? trGetActive() : [];
    activeTrainingCount = Array.isArray(list) ? list.length : 0;
  } catch(e) {}

  const setIcon  = (v) => { const el = document.getElementById('hmAcIcon');  if(el) el.textContent = v; };
  const setTitle = (v) => { const el = document.getElementById('hmAcTitle'); if(el) el.textContent = v; };
  const setSub   = (v) => { const el = document.getElementById('hmAcSub');   if(el) el.textContent = v; };
  const setOnclick = (fn) => { card.onclick = fn; };
  const setVariant = (cls) => {
    card.classList.remove('urgent', 'info');
    if(cls) card.classList.add(cls);
  };

  // ÖNCELİK SIRASI:
  // 1) URGENT: Okunmamış inbox mesajı 3+
  // 2) URGENT: Takımsız kullanıcı
  // 3) INFO: Pre-season + 0 antrenman
  // 4) INFO: Pre-season + takım var → tesis yükselt
  // 5) DEFAULT: In-season + maç hazırlığı
  // 6) DEFAULT: Genel "Antrenmana git"

  card.style.display = 'flex';

  if(unreadInbox >= 3) {
    setVariant('urgent');
    setIcon('📨');
    setTitle(`${unreadInbox} okunmamış mesaj`);
    setSub('Inbox\'ı kontrol et — bazı mesajlar yanıt bekliyor');
    setOnclick(() => inboxOpen());
    return;
  }

  if(typeof userHasTeam === 'function' && !userHasTeam()) {
    setVariant('info');
    setIcon('🏟️');
    setTitle('Takımın Yok');
    setSub('Takım Bul, Satın Al veya katılma isteği gönder');
    setOnclick(() => showPage('team', document.querySelectorAll('.nav-btn')[2]));
    return;
  }

  if(info.preSeason) {
    if(activeTrainingCount === 0) {
      setVariant('info');
      setIcon('🏋️');
      setTitle('Antrenmana Başla');
      setSub(`Sezon başlangıcına ${info.daysToStart} gün — şimdi antrenmanla seviyeni yükselt`);
      setOnclick(() => showPage('training', document.querySelectorAll('.nav-btn')[3]));
      return;
    }
    // Tesisleri yükselt önerisi (kaptansa)
    if(_userTeam && _userTeam.role === 'captain') {
      setVariant('info');
      setIcon('🏟️');
      setTitle('Tesisleri Yükselt');
      setSub('Sezon öncesi son hazırlık — stadyum ve antrenman merkezini geliştir');
      setOnclick(() => showPage('team', document.querySelectorAll('.nav-btn')[2]));
      return;
    }
    // Genel
    setVariant('info');
    setIcon('⏳');
    setTitle(`Sezona ${info.daysToStart} gün`);
    setSub('Antrenman, mağaza ve penaltı düellosu ile gelişimine devam et');
    setOnclick(() => showPage('training', document.querySelectorAll('.nav-btn')[3]));
    return;
  }

  // In-season
  setVariant('');
  setIcon('⚽');
  setTitle('Sıradaki Maç');
  setSub(`Sezon ${info.season} · Gün ${info.dayInSeason} — fikstürünü kontrol et`);
  setOnclick(() => showPage('team', document.querySelectorAll('.nav-btn')[2]));
}

