function renderHomeEventFeed(forceRefresh) {
  const wrap = document.getElementById('hmEventFeed');
  if(!wrap) return;

  // 🆕 Server-side leaderboard preload — train için tüm gerçek kullanıcıların verisi
  // İlk render'da boş gelir, RPC bitince re-render tetiklenir
  try {
    if (typeof _evRacePreloadServerLb === 'function') {
      const cycle = _evRaceCycleInfo();
      const cycleStartMs = cycle.start.getTime();
      const cached = _evRaceServerLbCache.train;
      // 🆕 DÖNGÜ KORUMASI — RPC başarısız olursa cache boş kalıyor ve her render
      //   yeniden preload tetikliyordu: sonsuz yeniden çizim = ekranda titreme.
      //   Aynı anda tek istek + hata sonrası 60 sn bekleme.
      const _simdi = Date.now();
      const _mesgul = !!window._evRaceLbLoading;
      const _bekle = (window._evRaceLbNextTry || 0) > _simdi;
      if ((!cached || cached.cycleStart !== cycleStartMs) && !_mesgul && !_bekle) {
        window._evRaceLbLoading = true;
        window._evRaceLbNextTry = _simdi + 60000;
        _evRacePreloadServerLb().catch(()=>{}).then(() => {
          window._evRaceLbLoading = false;
          // Cache yüklendi → tekrar render et (bu sefer dolu liste gelir)
          const _ok = !!(_evRaceServerLbCache.train || _evRaceServerLbCache.rating);
          if (_ok) window._evRaceLbNextTry = 0;
          if (typeof renderHomeEventFeed === 'function') renderHomeEventFeed();
          // Etkinlik sayfası açıksa onu da tazele
          const evPage = document.getElementById('page-events');
          if (evPage && evPage.classList.contains('active') && typeof evRaceRender === 'function') {
            evRaceRender();
          }
        });
      }
    }
  } catch(e) {}

  // Build leaderboards (haftalık yarış üreticisi)
  let ratingTop = [], trainTop = [], penaltiTop = [];
  try {
    if (typeof _evRaceBuildLeaderboard === 'function') {
      ratingTop = _evRaceBuildLeaderboard('rating').slice(0, 5);
      trainTop  = _evRaceBuildLeaderboard('train').slice(0, 5);
      penaltiTop = _evRaceBuildLeaderboard('penalti').slice(0, 5);
    }
  } catch(e) {}

  // Boş veri kontrolü
  if (!ratingTop.length && !trainTop.length && !penaltiTop.length) {
    wrap.innerHTML = `<div class="hm-race-empty">
      <div style="font-size:18px;margin-bottom:6px;opacity:.6">…</div>
      <div>Haftalık yarış henüz başlamadı</div>
    </div>`;
    return;
  }

  // Tek satır render — solda rating, sağda train
  function _renderRow(e, kind) {
    const isUser = !!e.isUser;
    const rankCls = (e.rank === 1 ? ' rank-1' : e.rank === 2 ? ' rank-2' : e.rank === 3 ? ' rank-3' : '');
    const userCls = isUser ? ' is-user' : '';
    // Skor formatı
    const scoreTxt = (kind === 'rating') ? Number(e.score).toFixed(2) : String(e.score);
    // Takım kısa logo (renkli daire)
    const short = (e.teamShort || '?').slice(0, 3);
    const bg = e.teamBg || '#333';
    const tc = e.teamTc || '#fff';
    // Player adı (yoksa takım adı)
    const display = e.playerName || e.teamName || '—';
    return `<div class="hm-race-row${rankCls}${userCls}" title="${e.teamName||''}${isUser?' · SEN':''}">
      <span class="hm-race-rank">${e.rank}</span>
      ${inlineBadge({cls:'hm-race-team-logo', name:e.teamName, bg, tc, short})}
      <span class="hm-race-name">${display}</span>
      <span class="hm-race-score">${scoreTxt}</span>
    </div>`;
  }

  const ratingHtml = ratingTop.length
    ? ratingTop.map(e => _renderRow(e, 'rating')).join('')
    : `<div class="hm-race-empty" style="padding:14px 6px">Veri yok</div>`;
  const trainHtml = trainTop.length
    ? trainTop.map(e => _renderRow(e, 'train')).join('')
    : `<div class="hm-race-empty" style="padding:14px 6px">Veri yok</div>`;
  const penaltiHtml = penaltiTop.length
    ? penaltiTop.map(e => _renderRow(e, 'penalti')).join('')
    : `<div class="hm-race-empty" style="padding:14px 6px">Veri yok</div>`;

  // 🆕 İMZA KONTROLÜ — içerik değişmediyse DOM'a hiç dokunma (titreme biter)
  try {
    const _sig = ratingHtml.length + '|' + trainHtml.length + '|' +
      ratingTop.map(e => (e && (e.name || e.id)) + ':' + (e && e.value)).join(',') + '|' +
      trainTop.map(e => (e && (e.name || e.id)) + ':' + (e && e.value)).join(',') + '|' +
      penaltiHtml;
    if (!forceRefresh && wrap.dataset.sig === _sig) return;
    wrap.dataset.sig = _sig;
  } catch(e) {}

  const _kayX = (wrap.querySelector('.hm-race-preview') || {}).scrollLeft || 0;
  wrap.innerHTML = `
    <div class="hm-race-preview kaydir">
      <div class="hm-race-col rating">
        ${_banBant('star', 'HAFTANIN YILDIZI', _BAN_ALT.star,
          `<button class="bnt-go" onclick="event.stopPropagation();goToRaceTab('rating')" title="Tam liste — Haftanın Yıldızı" aria-label="Haftanın Yıldızı tam listesi"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><line x1="7" y1="17" x2="17" y2="7"/><polyline points="7 7 17 7 17 17"/></svg></button>`)}
        <div class="hm-race-list">${ratingHtml}</div>
      </div>
      <div class="hm-race-col train">
        ${_banBant('train', 'ANTRENMAN YILDIZI', _BAN_ALT.train,
          `<button class="bnt-go" onclick="event.stopPropagation();goToRaceTab('train')" title="Tam liste — Antrenman Yıldızı" aria-label="Antrenman Yıldızı tam listesi"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><line x1="7" y1="17" x2="17" y2="7"/><polyline points="7 7 17 7 17 17"/></svg></button>`)}
        <div class="hm-race-list">${trainHtml}</div>
      </div>
      <div class="hm-race-col penalti">
        ${_banBant('penalti', 'PENALTI USTASI', _BAN_ALT.penalti,
          `<button class="bnt-go" onclick="event.stopPropagation();goToRaceTab('penalti')" title="Tam liste — Penaltı Ustası" aria-label="Penaltı Ustası tam listesi"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><line x1="7" y1="17" x2="17" y2="7"/><polyline points="7 7 17 7 17 17"/></svg></button>`)}
        <div class="hm-race-list">${penaltiHtml}</div>
      </div>
    </div>
  `;
  if (_kayX) wrap.querySelector('.hm-race-preview').scrollLeft = _kayX;
}

