// HOME — Avrupa Sahnesi (Lig Sahnesi modeli, aşama-bilinçli)
// Her turnuva kartı bugünün aşamasına göre içerik gösterir:
//  - Playoff aşaması: ilk 5 playoff eşleşmesi
//  - Grup aşaması: kullanıcının grubu (yoksa Grup A) standings
//  - Eleme turu (Son 16 / Çeyrek / Yarı / Final): o turun ilk 5 eşleşmesi
function renderHomeEuro() {
  const wrap = document.getElementById('homeEuroStrip');
  if(!wrap) return;
  const info = getSeasonInfo();
  // 🆕 529 — Kulüp turnuvaları (CHM/ELI/CON) 39. günden itibaren YENİ sezonu
  //   gösterir; EURO Nations Cup finali 40. günde oynandığı için o gerçek
  //   sezonda kalır.
  const _kupaSezon = (typeof _trnGosterSezon === 'function') ? _trnGosterSezon('champ')
    : ((typeof _etkinSezon === 'function') ? _etkinSezon() : info.season);

  if(info.preSeason) {
    _hmYaz(wrap, `
      <div class="home-empty-card">
        <div class="hec-icon">⏳</div>
        <div class="hec-title">Avrupa Sahnesi Bekleniyor</div>
        <div class="hec-sub">Sezon başlangıcına ${info.daysToStart||0} gün — turnuvalar 1. sezon sonunda hak kazananlarla başlar.</div>
      </div>
    `);
    return;
  }

  // Hak kazananlar var mı?
  let qual;
  try { qual = trn2GetQualifiers(_kupaSezon); } catch(e) { qual = null; }
  if (!qual || (!qual.champ.length && !qual.elite.length && !qual.conv.length)) {
    _hmYaz(wrap, `
      <div class="home-empty-card">
        <div class="hec-icon">🏆</div>
        <div class="hec-title">Avrupa Eşleşmeleri Hazır Değil</div>
        <div class="hec-sub">İlk sezon henüz tamamlanmadı — hak kazananlar belirleniyor.</div>
      </div>
    `);
    return;
  }

  const TRN_DEFS = [
    { key: 'champ', type: 'chm', label: 'Championship', tierColor: '#ffd54f', tier: 'CHM', logoKey: 'champ',  isEuro: false },
    { key: 'elite', type: 'eli', label: 'Elite',        tierColor: '#90caf9', tier: 'ELI', logoKey: 'elite',  isEuro: false },
    { key: 'conv',  type: 'con', label: 'Convergence',  tierColor: '#a5d6a7', tier: 'CON', logoKey: 'conv',   isEuro: false }
  ];
  // 🆕 EURO Nationals Cup — sadece Sezon 2+'dan itibaren
  if (info.season >= 2) {
    TRN_DEFS.push({ key: 'euro', type: 'enc', label: 'EURO Cup', tierColor: '#ce93d8', tier: 'EUR', logoKey: 'natcup', isEuro: true });
  }

  const userTeamName = (typeof _userTeam !== 'undefined' && _userTeam) ? _userTeam.teamName : null;
  // 🔑 ESKİ HATA: EURO Cup için KULÜBÜN ülkesi kullanılıyordu. Türk liginde
  //    oynayan bir Alman'a Türkiye'nin grubu gösteriliyordu. Milli takım
  //    turnuvasında ölçüt KULÜP değil UYRUKTUR.
  const userCountry  = (typeof getUserNationalityCC === 'function' && getUserNationalityCC())
                     || ((typeof authUser !== 'undefined' && authUser)
                          ? (authUser.nationality || authUser.countryCode) : null)
                     || ((typeof _userTeam !== 'undefined' && _userTeam) ? _userTeam.countryCode : null);

  const cards = TRN_DEFS.map(def => {
    const stage = _euGetCurrentStage(def.type, info.dayInSeason);
    let kartEk = '';
    let bodyHtml = '';
    let stageLabel = 'Grup Aşaması';
    let userInTrn = false;

    if (def.isEuro) {
      // ─── EURO Nationals Cup ───
      // Playoff yok, sadece group + knockout
      if (stage.type === 'group') {
        const r = _euRenderEuroGroupMini(info.season, userCountry);
        bodyHtml = r.html;
        userInTrn = r.userIn;
        stageLabel = String(stage.round || 'Grup Aşaması').replace(/\s*🎲/u, '');
        if (r.bekle) kartEk = ' enc-bekle';
      } else {
        // knockout: Son 16, Çeyrek, Yarı, Final
        const r = _euRenderEuroKnockoutMini(info.season, userCountry, stage.round);
        bodyHtml = r.html;
        userInTrn = r.userIn;
        stageLabel = stage.round || 'Eleme';
      }
    } else {
      // ─── Kulüp turnuvası (chm/eli/con) ───
      if (stage.type === 'playoff') {
        const r = _euRenderPlayoffMini(def.key, _kupaSezon, userTeamName);
        bodyHtml = r.html;
        userInTrn = r.userIn;
        stageLabel = 'Play-off';
      } else if (stage.type === 'po2') {
        const r = _euRenderPlayoff2Mini(def.key, _kupaSezon, userTeamName);
        bodyHtml = r.html;
        userInTrn = r.userIn;
        stageLabel = 'Play-off 2';
      } else if (stage.type === 'group') {
        const r = _euRenderGroupMini(def.key, _kupaSezon, userTeamName);
        bodyHtml = r.html;
        userInTrn = r.userIn;
        stageLabel = stage.round || 'Grup Aşaması';
      } else if (stage.type === 'knockout') {
        const r = _euRenderKnockoutMini(def.key, _kupaSezon, userTeamName, stage.round);
        bodyHtml = r.html;
        userInTrn = r.userIn;
        stageLabel = stage.round || 'Eleme';
      }
    }

    // 🆕 Turnuva logosu (kullanıcı yüklediği gerçek logolar)
    const logoHtml = (typeof _cupLogoIMG === 'function')
      ? _cupLogoIMG(def.logoKey, 24)
      : `<span style="font-family:Twemoji Country Flags,'Barlow Condensed';font-size:11px;font-weight:900;color:#0e0e16;background:${def.tierColor};padding:2px 4px;border-radius:4px">${def.tier}</span>`;

    return `
      <div class="lg-scene-card${kartEk}" data-kupa="${def.key}" data-user="${userInTrn ? '1' : '0'}">
        ${_banBant(def.logoKey, `${def.label} · ${stageLabel}`, _BAN_ALT[def.logoKey],
          `<button class="bnt-go" onclick="event.stopPropagation();_euSceneOpen('${def.key}')" title="Turnuva sayfasına git" aria-label="${def.label} turnuvasına git"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><line x1="7" y1="17" x2="17" y2="7"/><polyline points="7 7 17 7 17 17"/></svg></button>`)}
        <div class="lg-scene-list">${bodyHtml}</div>
      </div>
    `;
  }).join('');

  _hmYaz(wrap, cards);
}

// Bugünün turnuva aşamasını belirle.
// 🆕 ÖNCE tournament_state.phase (gerçek aşama — server tek kaynak), SONRA takvim fallback.
//   phase: playoff(PO1) | po2 | group | r32/r16/qf/sf | final
// 🆕 AŞAMA SIRASI — hem phase alanı hem fikstür için ortak ölçek
const _TRN_PHASE_ORDER = ['playoff','po2','group','r32','r16','qf','sf','final'];

// 🆕 Fikstürden gerçek aşama: kurulmuş EN İLERİ tur.
//   tournament_state.phase bazı turnuvalarda geride kalabiliyor (sunucu yalnızca
//   bazılarını ilerletiyor); fikstür ise turlar kurulunca doluyor. İkisinin
//   ilerisini alıyoruz — böylece Elite/Convergence de doğru aşamayı gösteriyor.
function _trnPhaseFromFixture(tkey, season) {
  try {
    if (typeof _tournamentStateGet !== 'function') return null;
    const st = _tournamentStateGet(tkey, season);
    const fx = (st && st.fixture) ? st.fixture : null;
    if (!fx) return null;
    const ko = (tkey === 'champ') ? ['r16','qf','sf','final'] : ['r32','r16','qf','sf','final'];
    let last = null;
    for (const ph of ko) {
      const pairs = fx[ph];
      if (Array.isArray(pairs) && pairs.length > 0) last = ph;
    }
    if (last) return last;
    if (fx.groups || fx.groupMatches) return 'group';
    if (fx.playoff2) return 'po2';
    if (fx.playoff) return 'playoff';
  } catch(e) {}
  return null;
}

// 🆕 Turnuvanın güncel aşaması — phase ile fikstürün İLERİ olanı
function _trnGuncelFaz(tkey, season) {
  let ph = null;
  try {
    const st = (typeof _tournamentStateGet === 'function') ? _tournamentStateGet(tkey, season) : null;
    if (st && st.phase) ph = st.phase;
  } catch(e) {}
  const fx = _trnPhaseFromFixture(tkey, season);
  const i1 = _TRN_PHASE_ORDER.indexOf(ph);
  const i2 = _TRN_PHASE_ORDER.indexOf(fx);
  if (i1 < 0 && i2 < 0) return null;
  return _TRN_PHASE_ORDER[Math.max(i1, i2)];
}
window._trnGuncelFaz = _trnGuncelFaz;

function _euGetCurrentStage(type, dayInSeason) {
  // 1) Gerçek aşama — tournament_state.phase VE fikstürün ilerisi (takvim değil)
  const _tkeyMap = { chm: 'champ', eli: 'elite', con: 'conv' };
  const _tkey = _tkeyMap[type];
  if (_tkey && typeof getSeasonInfo === 'function') {
    const _season = (typeof _trnGosterSezon === 'function') ? _trnGosterSezon(_tkey)
      : ((typeof _etkinSezon === 'function') ? _etkinSezon() : getSeasonInfo().season);
    const ph = _trnGuncelFaz(_tkey, _season);
    if (ph) {
      if (ph === 'playoff') return { type: 'playoff',  round: 'Play-off',   day: 0 };
      if (ph === 'po2')     return { type: 'po2',      round: 'Play-off 2', day: 0 };
      if (ph === 'group')   return { type: 'group',    round: 'Grup Aşaması', day: 0 };
      // r32/r16/qf/sf/final → knockout
      const _knLabel = { r32:'Son 32', r16:'Son 16', qf:'Çeyrek Final', sf:'Yarı Final', final:'Final' }[ph];
      if (_knLabel) return { type: 'knockout', round: _knLabel, day: 0 };
    }
  }

  // 2) Takvim fallback (phase yoksa — turnuva henüz kurulmamış)
  if (typeof SEASON_TEMPLATE === 'undefined') return { type: 'group', round: 'Grup Aşaması', day: 0 };

  let foundDay = null, foundRound = null;
  for (let d = dayInSeason; d >= 1; d--) {
    const evs = SEASON_TEMPLATE[d] || [];
    const ev = evs.find(e => e && e.type === type);
    if (ev) { foundDay = d; foundRound = ev.round || ''; break; }
  }
  if (!foundRound) {
    for (let d = dayInSeason + 1; d <= 40; d++) {
      const evs = SEASON_TEMPLATE[d] || [];
      const ev = evs.find(e => e && e.type === type);
      if (ev) { foundDay = d; foundRound = ev.round || ''; break; }
    }
  }
  if (!foundRound) return { type: 'group', round: 'Grup Aşaması', day: 0 };

  if (/Play-off 2/i.test(foundRound)) return { type: 'po2',     round: foundRound, day: foundDay };
  if (/Play-off/i.test(foundRound))   return { type: 'playoff', round: foundRound, day: foundDay };
  if (/Grup|Kura/i.test(foundRound))  return { type: 'group',   round: foundRound, day: foundDay };
  return { type: 'knockout', round: foundRound, day: foundDay };
}

// Maç satırı (playoff ve knockout için ortak format)
// ═══════════════════════════════════════════════════════════════
// 🆕 ŞAMPİYON BLOĞU (tasarım B · Podyum)
//   Final maçı oynanmışsa kartın altına eklenir. Kart genişliği ve
//   şekli değişmez; yalnızca alta bir bölüm gelir.
//   Kulüp turnuvalarında takım logosu, EURO Cup'ta ülke bayrağı.
// ═══════════════════════════════════════════════════════════════
// Turnuva parıltı renkleri — CHM mavi · ELI turuncu · CON yeşil · EURO altın
const _SB_ISIK = {
  champ: 'rgba(61,139,255,.80)',
  elite: 'rgba(255,122,26,.80)',
  conv:  'rgba(0,230,118,.75)',
  enc:   'rgba(255,214,0,.80)'
};
// (519) KULÜP TURNUVALARI · şampiyon bölümü "buğulu kupa" tasarımı:
//   arkada turnuvanın kupalı görseli bulanık/karartılmış, sağda kupa net, solda büyük
//   logo turnuva renginde parlıyor; altta ortalı "ŞAMPİYON · takım adı".
//   Görseller _CUP_BANNERS'tan (turnuvalar sayfasıyla aynı) — tek sefer CSS'e basılır.
// Kupa kırpıntıları (turnuva görsellerinden, yazısız) — net kupa katmanı için
const _SB_KUPA_IMG = {
  champ: 'data:image/jpeg;base64,',
  elite: 'data:image/jpeg;base64,',
  conv:  'data:image/jpeg;base64,',
  natcup: 'data:image/jpeg;base64,'
};
// Kupa kırpıntılarının en/boy oranı (kupa kesilmeden, tam boy sığsın diye)
const _SB_KUPA_ORAN = { champ: '182/240', elite: '182/240', conv: '182/240', natcup: '208/240' };
const _SB_KUPA_ANAHTAR = { champ: 'champ', elite: 'elite', conv: 'conv', enc: 'natcup' };
function _sbKupaCssKur() {
  if (document.getElementById('sbKupaCss') || typeof _CUP_BANNERS === 'undefined') return;
  try {
    const st = document.createElement('style');
    st.id = 'sbKupaCss';
    st.textContent = ['champ', 'elite', 'conv', 'natcup'].map(k => (_CUP_BANNERS[k] && _SB_KUPA_IMG[k])
      ? `.sbk-${k} .sbk-bg{background-image:url(${_CUP_BANNERS[k]})}.sbk-${k} .sbk-kupa{background-image:url(${_SB_KUPA_IMG[k]});aspect-ratio:${_SB_KUPA_ORAN[k]}}`
      : '').join('');
    document.head.appendChild(st);
  } catch (e) {}
}
// (521) Konfeti parçaları — yer/gecikme/süre sabit tohumla (her çizimde aynı, titreme yok)
function _sbKonfeti() {
  let t = 7, h = '';
  const r = () => { t = (t * 9301 + 49297) % 233280; return t / 233280; };
  for (let i = 0; i < 18; i++) {
    h += `<i style="left:${Math.round(2 + r() * 95)}%;animation-delay:${(r() * 3.8).toFixed(2)}s;animation-duration:${(3 + r() * 1.6).toFixed(2)}s"></i>`;
  }
  return h;
}
function _euSampiyonHtml(o) {
  if (!o || !o.ad) return '';
  const _kupaK = _SB_KUPA_ANAHTAR[o.trn];
  if (_kupaK && (o.bayrak ? o.trn === 'enc' : o.trn !== 'enc')) {
    _sbKupaCssKur();
    const ad = String(o.ad);
    const isik = _SB_ISIK[o.trn] || _SB_ISIK.enc;
    let lg;
    if (o.bayrak) {
      // Oyundaki ülke bayrağı (Twemoji Country Flags yazı tipiyle — önizleme paneliyle aynı)
      lg = `<span class="sbk-logo sbk-bayrak">${o.bayrak}</span>`;
    } else {
      lg = (typeof inlineBadge === 'function')
        ? inlineBadge({ cls: 'sbk-logo', name: ad, bg: o.bg || '#37474f', tc: o.tc || '#fff', short: o.kisa || ad.slice(0, 3).toUpperCase() })
        : `<div class="sbk-logo" style="background:${o.bg || '#37474f'};color:${o.tc || '#fff'}">${_escapeHtml(o.kisa || ad.slice(0, 3).toUpperCase())}</div>`;
    }
    return `
    <div class="eu-sampiyon sbk sbk-${_kupaK}" style="--sb-isik:${isik}">
      <div class="sbk-bg"></div><div class="sbk-kon">${_sbKonfeti()}</div><div class="sbk-kupa"></div>
      <div class="sbk-ust">${lg}</div>
      <div class="sbk-alt"><span class="sb-lbl">${o.sezon ? '<span data-noi18n>S' + Number(o.sezon) + '</span> Şampiyonu' : 'Şampiyon'}</span><span class="sb-ad" title="${_escapeHtml(ad)}">${_escapeHtml(ad)}</span></div>
    </div>`;
  }
  const ad = String(o.ad);
  const isik = _SB_ISIK[o.trn] || _SB_ISIK.enc;
  let ic;
  if (o.bayrak) {
    ic = `<div class="sb-logo sb-logo-flag">${o.bayrak}</div>`;
  } else if (typeof inlineBadge === 'function') {
    ic = inlineBadge({ cls: 'sb-logo', name: ad, bg: o.bg || '#37474f',
                       tc: o.tc || '#fff', short: o.kisa || ad.slice(0,3).toUpperCase() });
  } else {
    ic = `<div class="sb-logo" style="background:${o.bg||'#37474f'};color:${o.tc||'#fff'}">${
          _escapeHtml(o.kisa || ad.slice(0,3).toUpperCase())}</div>`;
  }
  return `
    <div class="eu-sampiyon" style="--sb-isik:${isik}">
      <div class="sb-halka">${ic}</div>
      <div class="sb-lbl">Şampiyon</div>
      <div class="sb-ad" title="${_escapeHtml(ad)}">${_escapeHtml(ad)}</div>
    </div>`;
}
window._euSampiyonHtml = _euSampiyonHtml;

function _euMatchRowHtml(m, userTeamName) {
  if (!m || !m.home || !m.away) return '';
  const isUserHome = m.home.name === userTeamName;
  const isUserAway = m.away.name === userTeamName;
  const isUserRow = isUserHome || isUserAway;
  const homeShort = (m.home.short || m.home.name.slice(0,3)).toUpperCase();
  const awayShort = (m.away.short || m.away.name.slice(0,3)).toUpperCase();
  const homeBg = m.home.bg || '#37474f';
  const awayBg = m.away.bg || '#37474f';
  const homeTc = m.home.tc || '#fff';
  const awayTc = m.away.tc || '#fff';
  // Skor: agg (twoLeg) → leg1+leg2, single-leg → hs/as, henüz oynanmadıysa "vs"
  let score = 'vs';
  if (m.leg1 && m.leg2) {
    const aggH = (m.leg1.hs||0) + (m.leg2.as||0);
    const aggA = (m.leg1.as||0) + (m.leg2.hs||0);
    score = `${aggH}-${aggA}`;
  } else if (typeof m.hs === 'number' && typeof m.as === 'number') {
    // (523) oynanmamış eşleşmede hs/as '' geliyor — eskiden "-" yazıyordu
    score = `${m.hs}-${m.as}`;
  }
  if (score !== 'vs' && m.pens && m.pens.homePens != null) {
    score += `<small class="eu-pen" data-noi18n>(${m.pens.homePens}-${m.pens.awayPens} P)</small>`;
  }
  return `
    <div class="lg-scene-row eu-match-row${isUserRow ? ' is-user' : ''}">
      <div class="eu-team-l">
        ${inlineBadge({cls:'eu-crest', name:m.home.name, bg:homeBg, tc:homeTc, short:homeShort})}
        <span class="eu-tname" title="${m.home.name||''}">${m.home.countryFlag||''} ${m.home.name||'—'}</span>
      </div>
      <div class="eu-score">${score}</div>
      <div class="eu-team-r">
        <span class="eu-tname" title="${m.away.name||''}">${m.away.name||'—'} ${m.away.countryFlag||''}</span>
        ${inlineBadge({cls:'eu-crest', name:m.away.name, bg:awayBg, tc:awayTc, short:awayShort})}
      </div>
    </div>
  `;
}

// Playoff aşaması — ilk 5 eşleşme
function _euRenderPlayoffMini(trnKey, season, userTeamName) {
  try {
    const qual = trn2GetQualifiers(season);
    if (!qual[trnKey] || !qual[trnKey].length) return { html: '<div class="lg-scene-empty">Veri yok</div>', userIn: false };
    const playoff = trn2BuildPlayoff(qual[trnKey], season, trnKey);
    if (!playoff || !playoff.length) return { html: '<div class="lg-scene-empty">Eşleşmeler hazırlanıyor</div>', userIn: false };
    let userIn = false;
    // Kullanıcının maçını öne al, en önemli 3 maç göster
    const sorted = playoff.slice();
    sorted.sort((a, b) => {
      const aU = (a.home && a.home.name === userTeamName) || (a.away && a.away.name === userTeamName);
      const bU = (b.home && b.home.name === userTeamName) || (b.away && b.away.name === userTeamName);
      return (bU?1:0) - (aU?1:0);
    });
    const top5 = sorted.slice(0, 5);
    const rows = top5.map(m => {
      const isUser = (m.home && m.home.name === userTeamName) || (m.away && m.away.name === userTeamName);
      if (isUser) userIn = true;
      return _euMatchRowHtml(m, userTeamName);
    }).join('');
    return { html: rows, userIn };
  } catch(e) { return { html: '<div class="lg-scene-empty">Veri okunamadı</div>', userIn: false }; }
}

// 🆕 Play-off 2 aşaması — ilk 5 eşleşme (ELI/CON)
function _euRenderPlayoff2Mini(trnKey, season, userTeamName) {
  try {
    if (typeof trn2BuildPlayoff2 !== 'function') return { html: '<div class="lg-scene-empty">Veri yok</div>', userIn: false };
    const po2 = trn2BuildPlayoff2(trnKey, season);
    if (!po2 || !po2.length) return { html: '<div class="lg-scene-empty">Eşleşmeler hazırlanıyor</div>', userIn: false };
    let userIn = false;
    const sorted = po2.slice();
    sorted.sort((a, b) => {
      const aU = (a.home && a.home.name === userTeamName) || (a.away && a.away.name === userTeamName);
      const bU = (b.home && b.home.name === userTeamName) || (b.away && b.away.name === userTeamName);
      return (bU?1:0) - (aU?1:0);
    });
    const top5 = sorted.slice(0, 5);
    const rows = top5.map(m => {
      const isUser = (m.home && m.home.name === userTeamName) || (m.away && m.away.name === userTeamName);
      if (isUser) userIn = true;
      return _euMatchRowHtml(m, userTeamName);
    }).join('');
    return { html: rows, userIn };
  } catch(e) { return { html: '<div class="lg-scene-empty">Veri okunamadı</div>', userIn: false }; }
}

// Grup aşaması — kullanıcının grubu (yoksa Grup A) standings
function _euRenderGroupMini(trnKey, season, userTeamName) {
  try {
    const qual = trn2GetQualifiers(season);
    if (!qual[trnKey] || !qual[trnKey].length) return { html: '<div class="lg-scene-empty">Veri yok</div>', userIn: false };
    const playoff = trn2BuildPlayoff(qual[trnKey], season, trnKey);
    const winners = playoff.map(m => m.winner).filter(Boolean);
    const groups = trn2BuildGroups(winners, season, trnKey);
    if (!groups || !groups.length) return { html: '<div class="lg-scene-empty">Gruplar hazırlanıyor</div>', userIn: false };

    // Kullanıcının grubu varsa onu, yoksa ilk grup (A)
    let selected = groups[0];
    let userInGroup = false;
    for (const g of groups) {
      if (g.teams && g.teams.some(t => t.name === userTeamName)) {
        selected = g; userInGroup = true; break;
      }
    }

    // Grup etiketi
    const letter = selected.letter || (selected.name || '?').replace('Grup ','').trim();
    const header = `<div class="eu-stage-label">${userInGroup ? '⭐ ' : ''}Grup ${letter}</div>`;

    // Puana göre sırala (eşitlikte averaj, sonra atılan gol) → ilk 4 sıra
    const sortedTeams = (selected.teams || []).slice().sort((a, b) => {
      const ap = a.pts||0, bp = b.pts||0;
      if (bp !== ap) return bp - ap;
      const agd = (a.gd!=null?a.gd:((a.gf||0)-(a.ga||0))), bgd = (b.gd!=null?b.gd:((b.gf||0)-(b.ga||0)));
      if (bgd !== agd) return bgd - agd;
      return (b.gf||0) - (a.gf||0);
    });
    const top4 = sortedTeams.slice(0, 4);

    const rows = top4.map((t, ti) => {
      const isUser = t.name === userTeamName;
      const bg = t.bg || '#37474f', tc = t.tc || '#fff';
      const short = t.short || (t.name||'').slice(0,3).toUpperCase();
      return `
        <div class="lg-scene-row${isUser ? ' is-user' : ''}">
          <div class="lg-scene-rank">${ti+1}</div>
          ${inlineBadge({tag:'div', cls:'lg-scene-crest', name:t.name, bg, tc, short})}
          <div class="lg-scene-tname" title="${t.name||''}">${t.countryFlag||''} ${t.name||'—'}</div>
          <div class="lg-scene-pts">${t.pts||0}</div>
        </div>
      `;
    }).join('');

    return { html: header + rows, userIn: userInGroup };
  } catch(e) { return { html: '<div class="lg-scene-empty">Veri okunamadı</div>', userIn: false }; }
}

// Eleme turu (Son 16 / Çeyrek / Yarı / Final) — o turdaki ilk 5 eşleşme
function _euRenderKnockoutMini(trnKey, season, userTeamName, roundLabel) {
  try {
    const qual = trn2GetQualifiers(season);
    if (!qual[trnKey] || !qual[trnKey].length) return { html: '<div class="lg-scene-empty">Veri yok</div>', userIn: false };
    const playoff = trn2BuildPlayoff(qual[trnKey], season, trnKey);
    const winners = playoff.map(m => m.winner).filter(Boolean);
    const groups = trn2BuildGroups(winners, season, trnKey);
    const bracket = trn2BuildBracket(groups, season, trnKey);
    if (!bracket || !bracket.length) return { html: '<div class="lg-scene-empty">Bracket hazırlanıyor</div>', userIn: false };

    // 🆕 Round label → bracket index — İSİM EŞLEŞMESİYLE.
    //   ESKİ HATA: indeks sabitti (Çeyrek=1, Yarı=2, Final=3). Bu yalnızca
    //   Championship için doğru; Elite/Convergence bracket'i "Son 32" ile
    //   başladığı için tüm turlar bir kayıyordu → başlık "Yarı Final" derken
    //   ekranda Çeyrek Final maçları listeleniyordu.
    const _sad = t => String(t || '').toLocaleLowerCase('tr')
      .replace(/[^a-zçğıöşü0-9]/g, '');
    const _hedef = _sad(roundLabel);
    let roundIdx = bracket.findIndex(r => {
      const n = _sad(r && r.name);
      return n && _hedef && (n.indexOf(_hedef) === 0 || _hedef.indexOf(n) === 0);
    });
    if (roundIdx < 0) {
      // Yedek: eski sıra mantığı, ama bracket uzunluğuna göre kaydırmalı
      const _ofs = (bracket.length >= 5) ? 1 : 0;   // Elite/Conv'de Son 32 var
      if (/Çeyrek/i.test(roundLabel))      roundIdx = 1 + _ofs;
      else if (/Yarı/i.test(roundLabel))   roundIdx = 2 + _ofs;
      else if (/Final/i.test(roundLabel))  roundIdx = 3 + _ofs;
      else if (/Son\s*16/i.test(roundLabel)) roundIdx = 0 + _ofs;
      else roundIdx = 0;
      if (roundIdx >= bracket.length) roundIdx = bracket.length - 1;
    }

    const round = bracket[roundIdx];
    if (!round || !round.matches || !round.matches.length) return { html: '<div class="lg-scene-empty">Tur bilgisi yok</div>', userIn: false };

    let userIn = false;
    // Kullanıcının maçını öne al, en önemli 3 maç göster
    const sorted = round.matches.slice();
    sorted.sort((a, b) => {
      const aU = (a.home && a.home.name === userTeamName) || (a.away && a.away.name === userTeamName);
      const bU = (b.home && b.home.name === userTeamName) || (b.away && b.away.name === userTeamName);
      return (bU?1:0) - (aU?1:0);
    });
    const top5 = sorted.slice(0, 5);
    const rows = top5.map(m => {
      const isUser = (m.home && m.home.name === userTeamName) || (m.away && m.away.name === userTeamName);
      if (isUser) userIn = true;
      return _euMatchRowHtml(m, userTeamName);
    }).join('');

    // 🆕 FİNAL turu ve maç oynandıysa → şampiyon bloğu
    let sampiyon = '';
    try {
      const _finalTur = /final/i.test(String(round.name || roundLabel || ''))
                     && !/yarı|çeyrek/i.test(String(round.name || roundLabel || ''));
      if (_finalTur && round.matches.length === 1) {
        const fm = round.matches[0];
        let kz = fm.winner || null;
        if (!kz && fm.hs != null && fm.as != null && fm.hs !== fm.as) {
          kz = (fm.hs > fm.as) ? fm.home : fm.away;
        }
        if (!kz && fm.leg1 && fm.leg2) {
          const aH = (fm.leg1.hs||0) + (fm.leg2.as||0);
          const aA = (fm.leg1.as||0) + (fm.leg2.hs||0);
          if (aH !== aA) kz = (aH > aA) ? fm.home : fm.away;
        }
        if (kz && kz.name) {
          sampiyon = _euSampiyonHtml({
            ad: kz.name, kisa: kz.short, bg: kz.bg, tc: kz.tc, bayrak: null, trn: trnKey
          });
        }
      }
    } catch(e) {}

    return { html: rows + sampiyon, userIn };
  } catch(e) { return { html: '<div class="lg-scene-empty">Veri okunamadı</div>', userIn: false }; }
}

// 🆕 SON EURO CUP ŞAMPİYONU
//   Yeni kura çekilene kadar Avrupa Sahnesi'ndeki EURO Cup kutusu boş
//   kalıyordu. Artık kulüp turnuvalarındaki (CHM/ELI/CON) şampiyon
//   rozetinin aynısı gösteriliyor — son şampiyon ülkenin bayrağıyla.
//   encEnsureState sunucuda kayıt yoksa null döner, hiçbir şey üretmez.
// 🆕 559 — Geçmiş sezonun finali: istemcideki maç sonuçları önbelleği yalnız içinde
//   bulunulan sezonu tutuyor. Yeni sezona geçince geçen sezonun final skoru bulunamıyor,
//   şampiyon kartı yerine "Gruplar hazırlanıyor" çıkıyordu. Final sonucu bir kez
//   sunucudan (match_results · enc · final) okunur, gelince kart yeniden çizilir.
const _encFinalSunucu = {};   // sezon → {ad,kod,bayrak,sezon} | false (yok) | null (yükleniyor)
function _encFinalSunucudanYukle(sz) {
  if (!window.sb || _encFinalSunucu[sz] !== undefined) return;
  _encFinalSunucu[sz] = null;
  try {
    window.sb.from('match_results')
      .select('home_team,away_team,home_score,away_score,pensWinner:data->>pensWinner,etWinner:data->>etWinner')
      .eq('season', sz).eq('tournament_key', 'enc').eq('tournament_phase', 'final').limit(1)
      .then(({ data, error }) => {
        const m = (!error && Array.isArray(data)) ? data[0] : null;
        let ad = null;
        if (m) {
          const hs = Number(m.home_score), as = Number(m.away_score);
          if (hs > as) ad = m.home_team;
          else if (as > hs) ad = m.away_team;
          else {
            const w = m.pensWinner || m.etWinner || null;
            if (w === m.home_team || w === m.away_team) ad = w;
          }
        }
        if (!ad) { _encFinalSunucu[sz] = false; return; }
        let kod = null;
        try { for (const cc of _cftGetCountryCodes()) { const c = _cftGetCountry(cc); if (c && c.name === ad) { kod = cc; break; } } } catch(e) {}
        const bayrak = (typeof _hmUlkeBayrak === 'function' && (_hmUlkeBayrak(kod) || _hmUlkeBayrak(ad))) || '🏳️';
        _encFinalSunucu[sz] = { ad, kod, bayrak, sezon: sz };
        try { if (typeof renderHomeEuro === 'function') renderHomeEuro(); } catch(e) {}
      }, () => { _encFinalSunucu[sz] = false; });
  } catch(e) { _encFinalSunucu[sz] = false; }
}
function _encSonSampiyon(season) {
  try {
    if (typeof encEnsureState !== 'function') return null;
    const bu = Number(season) || 0;
    for (let s = bu; s >= 2 && s >= bu - 5; s--) {
      if (_encFinalSunucu[s]) return _encFinalSunucu[s];   // 🆕 559: sunucudan gelen final
      const st = encEnsureState(s);
      const fm = st && st.knockout && st.knockout.final;
      if (!fm) continue;
      let kzKod = null, kzAd = null, kzBayrak = null;
      const _fs = _encSkor(fm);
      if (_fs && _fs.kazanan) {
        const ev = _fs.kazanan === 'home';
        kzKod = ev ? fm.home : fm.away;
        kzAd  = ev ? (fm.homeName || fm.home) : (fm.awayName || fm.away);
        kzBayrak = ev ? fm.homeFlag : fm.awayFlag;
      }
      if (!kzAd) continue;
      if (!kzBayrak && typeof _hmUlkeBayrak === 'function') {
        kzBayrak = _hmUlkeBayrak(kzKod) || _hmUlkeBayrak(kzAd) || '';
      }
      return { ad: kzAd, kod: kzKod, bayrak: kzBayrak || '🏳️', sezon: s };
    }
    // 🆕 559: önbellekte bulunamadı → son sezonların finalini sunucudan iste (bir kez)
    for (let s = bu; s >= 2 && s >= bu - 5; s--) _encFinalSunucudanYukle(s);
  } catch(e) {}
  return null;
}
window._encSonSampiyon = _encSonSampiyon;

// Kura hazır değilken gösterilecek gövde: mesaj + son şampiyon rozeti
// 🆕 544 — EURO Cup kura bekleme ekranı: son şampiyon kartı (final sonrasıyla aynı)
//   + üstte "Yeni turnuvaya N gün kaldı". Kura günü takvimden (SEASON_TEMPLATE).
function _encKuraBekleHtml(sonSezon) {
  const sm = _encSonSampiyon(sonSezon);
  if (!sm) return '';
  let kalan = null;
  try {
    const gun = getSeasonInfo().dayInSeason || 0;
    for (let g = 1; g <= 40; g++) {
      const ev = (SEASON_TEMPLATE[g] || []).find(e => e && e.type === 'enc' && /Kura/i.test(e.round || ''));
      if (ev) { kalan = g - gun; break; }
    }
  } catch(e) {}
  const not = (kalan != null && kalan > 0)
    ? '<span>Yeni turnuvaya</span> <b data-noi18n>' + kalan + '</b> <span>gün kaldı</span>'
    : '<span>Kura bugün çekiliyor</span>';
  return '<div class="enc-bk-not">' + not + '</div>'
       + _euSampiyonHtml({ ad: sm.ad, bayrak: sm.bayrak, trn: 'enc', sezon: sm.sezon });
}

function _encBeklemeHtml(season, mesaj) {
  // (519) Şampiyon bölümü yalnızca final oynandıktan sonra görünür — bekleme
  //   aşamalarında (Son 16 / Çeyrek / Yarı kurası) geçen sezonun şampiyonu gösterilmez.
  return '<div class="lg-scene-empty">' + mesaj + '</div>';
  const sm = _encSonSampiyon(season);
  if (!sm) return '<div class="lg-scene-empty">' + mesaj + '</div>';
  const rozet = (typeof _euSampiyonHtml === 'function')
    ? _euSampiyonHtml({ ad: sm.ad, bayrak: sm.bayrak, trn: 'enc' }) : '';
  return '<div class="lg-scene-empty" style="padding-bottom:4px">' + mesaj + '</div>'
       + rozet
       + '<div class="lg-scene-empty" style="padding-top:2px;font-size:10px;opacity:.75">'
       + 'Sezon ' + sm.sezon + ' şampiyonu</div>';
}

// ─── EURO NATIONALS CUP ───
// Maç formatı kulüp turnuvalarından farklı: { home: 'TR', homeName, homeFlag, hs, as, result, ... }
// Kullanıcı eşleşmesi ülke koduyla (countryCode) yapılır.

// 🆕 523 — ENC maç skoru tek yerden. encEnsureState skorları hg/ag, penaltıyı
//   {homePens, awayPens} olarak verir; kart ve şampiyon kontrolü ise hs/as ve
//   pens dizisi bekliyordu → skor hiç yazılmıyor, şampiyon hiç çıkmıyordu.
function _encSkor(m) {
  if (!m) return null;
  const h = (m.hg != null) ? m.hg : m.hs;
  const a = (m.ag != null) ? m.ag : m.as;
  if (typeof h !== 'number' || typeof a !== 'number') return null;
  let ph = null, pa = null;
  if (m.pens) {
    if (Array.isArray(m.pens)) { ph = m.pens[0]; pa = m.pens[1]; }
    else { ph = m.pens.homePens; pa = m.pens.awayPens; }
  }
  let kazanan = (m.result === 'home' || m.result === 'away') ? m.result : null;
  if (!kazanan) {
    if (h > a) kazanan = 'home';
    else if (a > h) kazanan = 'away';
    else if (ph != null && pa != null && ph !== pa) kazanan = ph > pa ? 'home' : 'away';
  }
  return { h, a, ph, pa, kazanan };
}
window._encSkor = _encSkor;

function _euEuroMatchRowHtml(m, userCountry) {
  if (!m) return '';
  const isUserHome = m.home === userCountry;
  const isUserAway = m.away === userCountry;
  const isUserRow = isUserHome || isUserAway;
  const homeShort = (m.home || '??').toUpperCase();
  const awayShort = (m.away || '??').toUpperCase();
  // EURO milli takımları için temalı arka plan (her ülkenin bayrağı belirgin)
  const homeBg = '#37474f', awayBg = '#37474f';
  const homeTc = '#fff', awayTc = '#fff';
  // Skor: hs/as → "vs" eğer yoksa
  let score = 'vs';
  const _sk = _encSkor(m);
  if (_sk) {
    score = `${_sk.h}-${_sk.a}`;
    if (_sk.ph != null && _sk.pa != null) score += `<small class="eu-pen" data-noi18n>(${_sk.ph}-${_sk.pa} P)</small>`;
  }
  return `
    <div class="lg-scene-row eu-match-row${isUserRow ? ' is-user' : ''}">
      <div class="eu-team-l">
        <div class="eu-crest" style="background:transparent!important;border:none!important;box-shadow:none!important;display:flex;align-items:center;justify-content:center;font-size:16px;line-height:1">${m.homeFlag||'🏳️'}</div>
        <span class="eu-tname" title="${m.homeName||''}">${m.homeName||'—'}</span>
      </div>
      <div class="eu-score">${score}</div>
      <div class="eu-team-r">
        <span class="eu-tname" title="${m.awayName||''}">${m.awayName||'—'}</span>
        <div class="eu-crest" style="background:transparent!important;border:none!important;box-shadow:none!important;display:flex;align-items:center;justify-content:center;font-size:16px;line-height:1">${m.awayFlag||'🏳️'}</div>
      </div>
    </div>
  `;
}

// EURO Cup — Grup aşaması (kullanıcı ülkesinin grubu veya Grup A)
function _euRenderEuroGroupMini(season, userCountry) {
  try {
    // Sezon 2'den önce hiç state yok
    if (season < 2) return { html: '<div class="lg-scene-empty">Sezon 2\'de başlar</div>', userIn: false };
    if (typeof encEnsureState !== 'function') return { html: '<div class="lg-scene-empty">Veri yok</div>', userIn: false };

    const state = encEnsureState(season);
    if (!state || !state.groups || !state.groups.length) {
      // 🆕 544 — Kura çekilene kadar son şampiyon kartı + yeni turnuvaya kalan gün
      const _bk = _encKuraBekleHtml(season - 1);
      if (_bk) return { html: _bk, userIn: false, bekle: true };
      return { html: _encBeklemeHtml(season - 1, 'Gruplar hazırlanıyor'), userIn: false };
    }

    // Kullanıcının ülkesinin grubu varsa onu, yoksa Grup A
    let selected = state.groups[0];
    let userInGroup = false;
    if (userCountry) {
      for (const g of state.groups) {
        if ((g.teams || []).some(t => t.code === userCountry)) {
          selected = g; userInGroup = true; break;
        }
      }
    }

    // Standings hesaplama (encCalcStandings)
    let standings = [];
    try {
      if (typeof encCalcStandings === 'function') {
        standings = encCalcStandings(selected);
      } else {
        standings = selected.teams || [];
      }
    } catch(e) { standings = selected.teams || []; }

    const letter = selected.id || (selected.name || '?').replace('Grup ','').trim();
    const header = `<div class="eu-stage-label">${userInGroup ? '⭐ ' : ''}Grup ${letter} · 4 Ülke</div>`;

    // 4 ülke puanlarıyla
    // 🔑 ESKİ HATA: encCalcStandings 'Pts' (büyük harf) döndürüyor, burada
    //    't.pts' okunuyordu → puan hep 0 görünüyordu.
    // 🔧 SADECE PUAN — averaj/oynanan sütunu kaldırıldı.
    //    O ek sütun 4'lü grid'i bozuyor ve satırları kaydırıyordu.
    const rows = standings.map((t, ti) => {
      const isUser = t.code === userCountry;
      const _pts = (typeof t.Pts === 'number') ? t.Pts
                 : ((typeof t.pts === 'number') ? t.pts
                 : ((typeof t.points === 'number') ? t.points : 0));
      return `
        <div class="lg-scene-row${isUser ? ' is-user' : ''}">
          <div class="lg-scene-rank">${ti+1}</div>
          <div class="lg-scene-crest" style="background:transparent!important;border:none!important;box-shadow:none!important;display:flex;align-items:center;justify-content:center;font-size:16px;line-height:1">${t.flag||'🏳️'}</div>
          <div class="lg-scene-tname" title="${t.name||''}">${t.name||'—'}</div>
          <div class="lg-scene-pts">${_pts}</div>
        </div>
      `;
    }).join('');

    // 🆕 Yeşil buton bu grubu açsın (A grubunu değil)
    try { window._euUserGroupLetter = letter; } catch(e) {}

    return { html: header + rows, userIn: userInGroup };
  } catch(e) { return { html: '<div class="lg-scene-empty">Veri okunamadı</div>', userIn: false }; }
}

