const _BAN_SH_KEY = ['S','1L','2L','3L','4L','5L'];
// Lig sırası (tierIdx) → klasman kalkanı <img>
function _banKalkanImg(tierIdx, boy, ekSinif) {
  const k = _BAN_SH_KEY[Math.max(0, Math.min(5, Number(tierIdx) || 0))];
  const src = _BAN_SH[k];
  if (!src) return '';
  const s = boy || 30;
  return '<img class="ban-sh' + (ekSinif ? ' ' + ekSinif : '') + '" src="' + src + '" alt="" style="width:' + Math.round(s * .88) + 'px;height:' + s + 'px">';
}
window._banKalkanImg = _banKalkanImg;
// 🆕 552 — Banner başlığı onaylanan önizlemedeki gibi: BÜYÜK HARF + iki renk
//   (son kelime ya da "·" sonrası banner rengiyle). Önce çevrilir, SONRA bölünür;
//   eskiden bölme çeviriden önce olduğu için İngilizcede kelimeler karışıyordu.
function _banBaslik(baslik) {
  const s = String(baslik == null ? '' : baslik);
  if (/[<>]/.test(s)) return s;                       // HTML gelirse dokunma
  const _T = (typeof T === 'function') ? T : (x => x);
  const dil = (typeof i18nLang === 'function') ? i18nLang() : 'tr';
  const loc = ({ tr:'tr-TR', de:'de-DE', es:'es-ES', pt:'pt-BR', it:'it-IT', fr:'fr-FR', ru:'ru-RU' })[dil] || 'en-US';
  const B = (x) => String(x).toLocaleUpperCase(loc);
  // Sözlükte yalnız BÜYÜK HARF anahtarı olan başlıklar için ikinci deneme
  const C = (x) => { const t = _T(x); if (t !== x) return t; const u = String(x).toLocaleUpperCase('tr-TR'); const tu = _T(u); return (tu !== u) ? tu : t; };
  let a = '', b = '';
  const i = s.indexOf(' · ');
  if (i > 0) { a = B(C(s.slice(0, i))) + ' ·'; b = B(C(s.slice(i + 3))); }
  else {
    const c = B(C(s)); const j = c.lastIndexOf(' ');
    if (j > 0) { a = c.slice(0, j); b = c.slice(j + 1); } else b = c;
  }
  return (a ? '<span class="bnt-t1">' + _escapeHtml(a) + '</span> ' : '')
       + '<span class="bnt-t2">' + _escapeHtml(b) + '</span>';
}
// Banner bandı — başlık + çizgi + alt yazı (+ isteğe bağlı kalkan ve buton)
function _banBant(key, baslikHtml, altYazi, sagHtml, kalkanIdx) {
  const acc = _BAN_ACC[key] || '#ffd54f';
  const bg = _BAN_BG[key] ? 'background-image:url(' + _BAN_BG[key] + ')' : '';
  const ic = (kalkanIdx == null) ? '' : _banKalkanImg(kalkanIdx, 30);
  return '<div class="bnt' + (ic ? ' ikonlu' : '') + '" style="--ban-acc:' + acc + ';' + bg + '">'
    + ic
    + '<span class="bnt-t" data-noi18n>' + _banBaslik(baslikHtml) + '</span>'
    + '<span class="bnt-rule"></span>'
    + (altYazi ? '<span class="bnt-alt">' + altYazi + '</span>' : '')
    + (sagHtml || '')
    + '</div>';
}
window._banBant = _banBant;

function _euRenderEuroKnockoutMini(season, userCountry, roundLabel) {
  try {
    if (season < 2) return { html: '<div class="lg-scene-empty">Sezon 2\'de başlar</div>', userIn: false };
    if (typeof encEnsureState !== 'function') return { html: '<div class="lg-scene-empty">Veri yok</div>', userIn: false };

    const state = encEnsureState(season);
    if (!state || !state.knockout) {
      return { html: _encBeklemeHtml(season - 1, 'Eşleşmeler hazırlanıyor'), userIn: false };
    }

    const ko = state.knockout;
    // Round label → bracket dizisi
    let matches = [];
    if (/Çeyrek/i.test(roundLabel))      matches = ko.qf || [];
    else if (/Yarı/i.test(roundLabel))   matches = ko.sf || [];
    else if (/Final/i.test(roundLabel))  matches = ko.final ? [ko.final] : [];
    else                                  matches = ko.r16 || [];   // Son 16 default

    if (!matches.length) return { html: _encBeklemeHtml(season - 1, 'Tur kurası bekleniyor'), userIn: false };

    let userIn = false;
    // Kullanıcının maçını öne al
    const sorted = matches.slice();
    sorted.sort((a, b) => {
      const aU = (a.home === userCountry) || (a.away === userCountry);
      const bU = (b.home === userCountry) || (b.away === userCountry);
      return (bU?1:0) - (aU?1:0);
    });
    const top5 = sorted.slice(0, 5);
    const rows = top5.map(m => {
      const isUser = (m.home === userCountry) || (m.away === userCountry);
      if (isUser) userIn = true;
      return _euEuroMatchRowHtml(m, userCountry);
    }).join('');

    // 🆕 FİNAL oynandıysa → şampiyon bloğu (ülke bayrağıyla)
    let sampiyon = '';
    try {
      if (/final/i.test(String(roundLabel || '')) && matches.length === 1) {
        const fm = matches[0];
        let kzKod = null, kzAd = null, kzBayrak = null;
        const _fs = _encSkor(fm);
        if (_fs && _fs.kazanan) {
          const ev = _fs.kazanan === 'home';
          kzKod    = ev ? fm.home : fm.away;
          kzAd     = ev ? (fm.homeName || fm.home) : (fm.awayName || fm.away);
          kzBayrak = ev ? fm.homeFlag : fm.awayFlag;
        }
        if (kzAd) {
          if (!kzBayrak && typeof _hmUlkeBayrak === 'function') {
            kzBayrak = _hmUlkeBayrak(kzKod) || _hmUlkeBayrak(kzAd) || '🏳️';
          }
          sampiyon = _euSampiyonHtml({ ad: kzAd, bayrak: kzBayrak || '🏳️', trn: 'enc' });
        }
      }
    } catch(e) {}

    return { html: rows + sampiyon, userIn };
  } catch(e) { return { html: '<div class="lg-scene-empty">Veri okunamadı</div>', userIn: false }; }
}

