// Yetenek değerleri: localStorage'dan oku
function getSkillLevels(pos, opts) {
  // Tüm 45 yetenek: 4 mevkinin verilerini birleştir
  // 593b — her oyuncunun 45 yeteneği var; kaydı olmayan 10 (veritabanındaki kopya da aynı kuralla)
  const levels = {};
  if (typeof SKILL_DEFS !== 'undefined' && SKILL_DEFS.ALL) SKILL_DEFS.ALL.forEach(c => c.skills.forEach(sk => { levels[sk.id] = 10; }));
  ['GK','DEF','MID','FWD'].forEach(p => {
    const trData = trGetData(p);
    Object.keys(trData).forEach(id => {
      levels[id] = (trData[id] && trData[id].level) || 10;
    });
  });
  // 🆕 Item bonusları uygula (default açık, raw=true ile ham değer alınır)
  const includeEq = !opts || opts.raw !== true;
  if (includeEq && typeof getEquippedBonuses === 'function') {
    const bonuses = getEquippedBonuses();
    Object.keys(bonuses).forEach(id => {
      if (levels[id] === undefined) return;
      const base = levels[id];
      const bonus = bonuses[id];
      // Formül: base * (1 + percent/100), 100 ile sınırlı
      levels[id] = Math.min(100, Math.round(base * (1 + bonus / 100)));
    });
  }
  return levels;
}

// 🆕 Yetenek adı → ID mapper (item stats'ı parse etmek için)
const SKILL_NAME_TO_ID = (function() {
  const map = {};
  if (typeof SKILL_DEFS !== 'undefined' && SKILL_DEFS.ALL) {
    SKILL_DEFS.ALL.forEach(cat => {
      cat.skills.forEach(s => {
        // Türkçe büyük/küçük + boşluk normalleştir
        map[s.name.toLowerCase().trim()] = s.id;
      });
    });
  }
  return map;
})();

// 🆕 Debug helper — konsola yazar: eqDebug() çağır
window.eqDebug = function() {
  const data = (typeof getEqData === 'function') ? getEqData() : null;
  console.group('🎒 Ekipman Debug');
  console.log('Wardrobe:', data?.wardrobe);
  console.log('Active Slots:', data?.activeSlots);
  console.log('Unlocked:', data?.unlockedSlots);
  data?.activeSlots?.forEach((id, i) => {
    if (!id) return;
    const item = data.wardrobe.find(w => w.id === id);
    console.log(`Slot ${i+1}:`, item?.name, '— stats:', item?.stats || '(no stats)');
  });
  const bonuses = getEquippedBonuses();
  console.log('Toplam Bonuslar (skillId → %):', bonuses);
  console.log('Skill Map (50 örnek):', Object.keys(SKILL_NAME_TO_ID).slice(0,5));
  console.groupEnd();
  return bonuses;
};

// 🆕 Item stats array → bonus dict ('Refleks +5%' → {refleks: 5})
function parseItemBonuses(stats) {
  const bonuses = {};
  if (!Array.isArray(stats)) return bonuses;
  stats.forEach(s => {
    const m = String(s).match(/^(.+?)\s*\+(\d+)%/);
    if (!m) return;
    const name = m[1].trim().toLowerCase();
    const id = SKILL_NAME_TO_ID[name];
    if (!id) return;
    bonuses[id] = (bonuses[id] || 0) + parseInt(m[2], 10);
  });
  return bonuses;
}

// 🆕 Aktif slot'lardaki itemlerin toplam bonuslarını hesapla
// 🆕 `veri` verilirse O ekipman setinin bonusları hesaplanır.
//    Boş bırakılırsa eskisi gibi giriş yapan kullanıcının kendi seti.
//    Başkasının profilinde onun ekipmanını uygulamak için gerekli.
// 593 — TEK DÜNYA: bonus eşya KATALOĞUNDAN (SHOP_ITEMS) okunur — veritabanı (players kopyası)
//   ve maç motoru da aynısını yapar. İlk 5 yuva, dolapta olan eşya, yetenek başına en fazla %40.
//   Dolaptaki kopyanın "stats" alanına güvenilmez (oyuncu kendi kaydını yazabiliyor).
const EQ_BONUS_TAVAN = 40;
function getEquippedBonuses(veri) {
  const totals = {};
  let data = veri || null;
  if (!data) {
    data = (typeof _eqData !== 'undefined' && _eqData) ? _eqData : null;
    if (!data || !Array.isArray(data.activeSlots)) {
      if (typeof getEqData === 'function') data = getEqData();
    }
  }
  if (!data || !Array.isArray(data.activeSlots) || !Array.isArray(data.wardrobe)) return totals;

  data.activeSlots.slice(0, 5).forEach(itemId => {
    if (!itemId || typeof itemId !== 'string') return;
    if (!data.wardrobe.some(w => w && w.id === itemId)) return;           // sahip olunmayan eşya sayılmaz
    const shopItem = (typeof SHOP_ITEMS !== 'undefined') ? SHOP_ITEMS.find(i => i.id === itemId) : null;
    if (!shopItem || !Array.isArray(shopItem.stats)) return;              // katalogda olmayan eşya etkisiz
    const itemBonuses = parseItemBonuses(shopItem.stats);
    Object.keys(itemBonuses).forEach(id => {
      totals[id] = (totals[id] || 0) + itemBonuses[id];
    });
  });
  Object.keys(totals).forEach(id => { if (!(totals[id] > 0)) delete totals[id]; else if (totals[id] > EQ_BONUS_TAVAN) totals[id] = EQ_BONUS_TAVAN; });
  return totals;
}

function saveSkillLevels(pos, levels) {
  // 🆕 skills kolonu DB trigger ile korunur → mevki değişimi SUNUCU RPC'si ile (şişirme doğrulamalı).
  if (!(window.sb && authUser && authUser.id)) return;
  try {
    // Yerel cache'i nested formata çevir (trGetData {level,points} bekler)
    const nested = {};
    Object.keys(levels||{}).forEach(id => { nested[id] = { level: Number(levels[id])||10, points: 0 }; });
    if (window._skillsCache) window._skillsCache[pos] = nested;
    window.sb.rpc('user_player_change_position_skills', { p_new_group: pos, p_new_levels: levels })
      .then(({data,error})=>{
        if(error){ console.warn('[skills] pos rpc hata:', error.message); return; }
        if(data && data.ok && data.skills){ window._skillsCache = data.skills; }
        else if(data && data.ok===false){ console.warn('[skills] pos reddedildi:', data.error); }
      }).catch(e=>console.warn('[skills] pos rpc hata:', e));
  } catch(e){ console.warn('[skills] pos save hata:', e); }
}

// Oyuncu genel gücü hesapla
function calcOverall(pos, levels) {
  // 🆕 Kullanıcının ana mevki grubunun yetenek ortalaması
  // pos 'OS'/'STB' gibi specific olabilir → POS_GROUP ile 'GK'/'DEF'/'MID'/'FWD'a çevir
  const posGroup = (typeof POS_GROUP !== 'undefined' && POS_GROUP[pos]) || pos || 'MID';
  const groupIdx = posGroup === 'GK'  ? 0
                 : posGroup === 'DEF' ? 1
                 : posGroup === 'FWD' ? 3
                 : 2; // MID default
  const cat = SKILL_DEFS.ALL[groupIdx];
  if (!cat || !cat.skills) return 10;
  let total = 0, count = 0;
  cat.skills.forEach(s => {
    total += levels[s.id] || 10;
    count++;
  });
  return count ? Math.round(total / count) : 10;
}

// 🆕 Belirli bir pos grubu için kullanıcının yetenek ortalaması
// (4 mevki için ayrı ayrı hesap; oyuncu hero barında 4'ünü göstermek için)
function calcOverallForGroup(posGroup, levels) {
  const groupIdx = posGroup === 'GK'  ? 0
                 : posGroup === 'DEF' ? 1
                 : posGroup === 'FWD' ? 3
                 : 2;
  const cat = SKILL_DEFS.ALL[groupIdx];
  if (!cat || !cat.skills) return 10;
  let total = 0, count = 0;
  cat.skills.forEach(s => {
    total += levels[s.id] || 10;
    count++;
  });
  return count ? Math.round(total / count) : 10;
}

// Kategori ortalaması
function calcCatAvg(catSkills, levels) {
  const sum = catSkills.reduce((a,s) => a + (levels[s.id]||10), 0);
  return Math.round(sum / catSkills.length);
}

// Değere göre renk
function skillColor(val) {
  if(val >= 80) return '#ffd600';
  if(val >= 60) return '#00e676';
  if(val >= 40) return '#00b0ff';
  if(val >= 20) return '#ff9800';
  return '#ef5350';
}

// Sayfa render
// 🆕 Ziyaretçi modu helper'ları
// Başka oyuncunun yetenek seviyelerini overall'a göre tahmin et (gerçek skill saklanmıyor başka oyuncularda)
// 🆕 Ziyaret edilen gerçek kullanıcıların skill cache'i (user_id → 45 skill levels)
const _visitorSkillsCache = {};

// 🆕 Gerçek kullanıcının skill'lerini Supabase'ten çek (async, cache'le, sonra render yenile)
async function _loadVisitorSkills(userId) {
  if (!userId || !window.sb) return null;
  if (_visitorSkillsCache[userId]) return _visitorSkillsCache[userId];
  try {
    const { data } = await window.sb.from('user_player')
      .select('skills')
      .eq('user_id', userId)
      .maybeSingle();
    const skills = (data && data.skills && typeof data.skills === 'object') ? data.skills : null;
    if (!skills) {
      // 🆕 Boş döndü (çoğunlukla RLS: başkasının satırı okunamaz).
      //    Önbelleğe BOŞ yaz ki aynı kişi için tekrar tekrar istek
      //    atılmasın. Eskiden bu yoktu ve çağıran kod her seferinde
      //    yeniden deniyordu — sonsuz döngülerin zemini buydu.
      _visitorSkillsCache[userId] = {};
      return null;
    }
    if (skills) {
      // skills formatı: {GK:{id:{level,points}}, DEF:{...}, MID:{...}, FWD:{...}}
      // Tüm 4 pos birleştir → flat {id:level} map
      const flat = {};
      ['GK','DEF','MID','FWD'].forEach(pos => {
        const posSkills = skills[pos] || {};
        Object.keys(posSkills).forEach(id => {
          const entry = posSkills[id];
          if (entry && typeof entry.level === 'number') flat[id] = entry.level;
        });
      });
      _visitorSkillsCache[userId] = flat;
      return flat;
    }
  } catch(e) { console.warn('[visitor skills] load hata:', e); }
  return null;
}

function _carBuildSkillsForVisitor(vp) {
  // 🆕 Üç durum:
  // 1) Gerçek kullanıcı (isBot=false ve user_id var) → Supabase'ten user_player.skills
  // 2) Bot oyuncu → vp.abilities mevcutsa ana mevki ortalaması, yoksa 10
  // 3) Veri yoksa → 10 (sabit fallback)
  const lvls = {};
  const cats = SKILL_DEFS.ALL;
  // İlk: tüm skill'leri 10 ile başlat (fallback)
  cats.forEach(cat => {
    cat.skills.forEach(s => { lvls[s.id] = 10; });
  });

  const vpUid = vp && (vp.userId || vp.user_id);
  const isExplicitBot = vp && vp.isBot === true;

  // 🔴 TEK DÜNYA · TEK KAYNAK — `players.abilities`
  //   Eskiden gerçek kullanıcıların yetenekleri yalnızca
  //   `user_player.skills` içindeydi ve o tablonun okuma politikası
  //   "sadece kendi satırın" diyor. Yani BAŞKASININ profilinde veri
  //   asla gelmiyor, kod sessizce 10'a düşüyordu. (Uzun süre fark
  //   edilmemesinin sebebi ayrı bir hataydı: bot olmayan herkes "sen"
  //   sayıldığı için başkasının profilinde SENİN verilerin
  //   gösteriliyordu.)
  //
  //   Artık sunucu, kullanıcının yeteneklerini herkesin okuyabildiği
  //   `players.abilities` sütununa da yazıyor (sync_player_abilities
  //   tetiği). Bot ya da gerçek kullanıcı — hepsi buradan okunur.
  const _ab = vp && vp.abilities;
  let _abBulundu = false;
  if (_ab && typeof _ab === 'object') {
    ['GK','DEF','MID','FWD'].forEach(g => {
      const sub = _ab[g];
      if (!sub || typeof sub !== 'object') return;
      Object.keys(sub).forEach(id => {
        const v = sub[id];
        if (typeof v === 'number' && lvls[id] !== undefined) {
          lvls[id] = v;
          _abBulundu = true;
        }
      });
    });
  }

  // 🆕 Ekipman bonusu — bakılan oyuncunun kendi seti uygulanır.
  //    Kendi profilinde bu iş `getSkillLevels()` içinde yapılıyor;
  //    ziyaretçi görünümünde hiç yapılmıyordu, o yüzden başkasının
  //    profilinde sadece ham yetenekler görünüyordu.
  const _ekipmanUygula = (seviyeler) => {
    try {
      if (typeof _eqIsVisitor !== 'function' || !_eqIsVisitor()) return seviyeler;
      if (typeof _getVisitorEqData !== 'function' || typeof getEquippedBonuses !== 'function') return seviyeler;
      const bonuslar = getEquippedBonuses(_getVisitorEqData());
      Object.keys(bonuslar).forEach(id => {
        if (seviyeler[id] === undefined) return;
        seviyeler[id] = Math.min(100, Math.round(seviyeler[id] * (1 + bonuslar[id] / 100)));
      });
    } catch(e) {}
    return seviyeler;
  };

  if (vp && !isExplicitBot && vpUid) {
    // Kendi satırın (ya da başka yoldan gelmiş taze veri) varsa onu yeğle
    const cached = _visitorSkillsCache[vpUid];
    if (cached && Object.keys(cached).length > 0) {
      Object.keys(cached).forEach(id => {
        if (lvls[id] !== undefined) lvls[id] = cached[id];
      });
      return _ekipmanUygula(lvls);
    }
    if (_abBulundu) return _ekipmanUygula(lvls);   // abilities yeterli, istek atma
    // Hiç veri yoksa son çare: kendi satırın için user_player'ı dene
    _loadVisitorSkills(vpUid).then(skills => {
      if (skills && typeof renderPlayerPage === 'function') {
        try { renderPlayerPage(); } catch(e) {}
      }
    });
    return _ekipmanUygula(lvls);
  }
  if (_abBulundu) return _ekipmanUygula(lvls);

  // Durum 2: Bot → abilities'ten ana mevki ortalaması
  if (vp && vp.abilities && typeof vp.abilities === 'object') {
    const ab = vp.abilities;
    if (ab.GK || ab.DEF || ab.MID || ab.FWD) {
      // Yeni format: posGroup objeleri
      const posGroup = (typeof POS_GROUP !== 'undefined' && POS_GROUP[vp.pos]) || vp.posGroup || 'MID';
      const sub = ab[posGroup] || ab.MID || {};
      const vals = Object.values(sub).filter(v => typeof v === 'number');
      if (vals.length) {
        const avg = Math.round(vals.reduce((a,b)=>a+b,0) / vals.length);
        cats.forEach(cat => {
          cat.skills.forEach(s => { lvls[s.id] = avg; });
        });
      }
    } else {
      // Eski flat format
      const vals = Object.values(ab).filter(v => typeof v === 'number');
      if (vals.length) {
        const avg = Math.round(vals.reduce((a,b)=>a+b,0) / vals.length);
        cats.forEach(cat => {
          cat.skills.forEach(s => { lvls[s.id] = avg; });
        });
      }
    }
  }

  return lvls;
}

// ══════════════════════════════════════════════════════════
// 🆕 OYUNCUM HERO — MEVKİ HARİTASI (1./2./3. bölge) + KARİYER BAŞLANGICI
// ══════════════════════════════════════════════════════════
const _PMAP_XY = {
  ST:[50,19], LF:[24,27], RF:[76,27],
  AM:[50,46], LM:[17,62], RM:[83,62], CM:[50,70],
  DM:[50,93], LB:[20,110], CB:[50,114], RB:[80,110],
  GK:[50,134]
};
// Birincil mevkiye göre 2. ve 3. bölge (komşu mevkiler)
const _PMAP_NEAR = {
  GK:[], 
  CB:['LB','RB'], LB:['CB','LM'], RB:['CB','RM'],
  DM:['CM','CB'], CM:['DM','AM'], AM:['CM','ST'],
  LM:['LB','LF'], RM:['RB','RF'],
  ST:['LF','RF'], LF:['ST','LM'], RF:['ST','RM']
};
function _plSubPosOf(p, posGroup) {
  const sp = (p && (p.subPos || p.sub_pos)) || null;
  if (sp && _PMAP_XY[sp]) return sp;
  const g = posGroup || (p && p.pos) || 'MID';
  return ({ GK:'GK', DEF:'CB', MID:'CM', FWD:'ST' })[g] || 'CM';
}
// Gerçek saha mevki haritası — oyuncu profili ve oyuncu kartı aynı çizimi kullanır (onek: svg kimlikleri)
function _sahaHaritaSvg(p, posGroup, onek) {
  const primary = _plSubPosOf(p, posGroup);
  const near = _PMAP_NEAR[primary] || [];
  const zone = {}; zone[primary] = 'p1';
  if (near[0]) zone[near[0]] = 'p2';
  if (near[1]) zone[near[1]] = 'p3';

  const RENK = { p1: '#00e676', p2: '#29b6ff', p3: '#ffd600' };
  const yazi = (x, y, boy, renk, kod) => `<text x="${x}" y="${(y + boy * .37).toFixed(1)}" text-anchor="middle" font-family="Barlow Condensed,sans-serif" font-weight="900" font-size="${boy}" fill="${renk}">${kod}</text>`;
  const toplar = Object.keys(_PMAP_XY).map(code => {
    const [x, y] = _PMAP_XY[code];
    const z = zone[code];
    if (!z) return `<circle cx="${x}" cy="${y}" r="5.3" fill="rgba(0,0,0,.22)" stroke="rgba(255,255,255,.55)" stroke-width=".7"/>` + yazi(x, y, 5.6, 'rgba(255,255,255,.9)', code);
    return (z === 'p1' ? `<circle class="nabiz" cx="${x}" cy="${y}" r="9" fill="none" stroke="${RENK[z]}" stroke-width="1.2"/>` : '')
      + `<circle cx="${x}" cy="${y}" r="${z === 'p1' ? 7.6 : 6.8}" fill="${RENK[z]}" stroke="#fff" stroke-width="1.4" filter="url(#${onek}Golge)"/>` + yazi(x, y, 6.4, '#06140c', code);
  }).join('');
  let cim = '';
  for (let i = 0; i < 12; i++) cim += `<rect x="0" y="${(i * 145 / 12).toFixed(2)}" width="100" height="12.3" fill="${i % 2 ? '#1c703d' : '#228049'}"/>`;
  const svg = `<svg viewBox="0 0 100 145"><defs>
      <radialGradient id="${onek}Isik" cx="50%" cy="46%" r="72%"><stop offset="0" stop-color="#fff" stop-opacity=".13"/><stop offset=".6" stop-color="#fff" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".32"/></radialGradient>
      <filter id="${onek}Golge" x="-50%" y="-50%" width="200%" height="200%"><feDropShadow dx="0" dy=".7" stdDeviation=".7" flood-color="#000" flood-opacity=".55"/></filter></defs>
      ${cim}<rect width="100" height="145" fill="url(#${onek}Isik)"/>
      <g fill="none" stroke="rgba(255,255,255,.88)" stroke-width=".85">
        <rect x="4" y="4" width="92" height="137" rx="1"/><line x1="4" y1="72.5" x2="96" y2="72.5"/><circle cx="50" cy="72.5" r="11"/>
        <rect x="24" y="4" width="52" height="21"/><rect x="37" y="4" width="26" height="8"/><path d="M43.5 25a9.5 9.5 0 0 0 13 0"/>
        <rect x="24" y="120" width="52" height="21"/><rect x="37" y="133" width="26" height="8"/><path d="M43.5 120a9.5 9.5 0 0 1 13 0"/>
        <path d="M4 7a3 3 0 0 0 3-3M93 4a3 3 0 0 0 3 3M96 138a3 3 0 0 0-3 3M7 141a3 3 0 0 0-3-3"/></g>
      <g fill="rgba(255,255,255,.9)"><circle cx="50" cy="72.5" r="1.1"/><circle cx="50" cy="17" r=".9"/><circle cx="50" cy="128" r=".9"/></g>
      <g fill="rgba(255,255,255,.18)" stroke="#fff" stroke-width=".5"><rect x="44" y="1.2" width="12" height="2.8"/><rect x="44" y="141" width="12" height="2.8"/></g>
      ${toplar}</svg>`;
  return { svg, near };
}
function _plRenderPosMap(p, posGroup) {
  const el = document.getElementById('plPosMap');
  const lg = document.getElementById('plPosMapLegend');
  if (!el) return;
  const { svg, near } = _sahaHaritaSvg(p, posGroup, 'plPm');
  el.innerHTML = svg;
  // Yanında yalnız 1 · 2 · 3 (mevki kısaltmaları zaten toplarda)
  if (lg) lg.innerHTML = '<div><i class="z1"></i>1</div>' + (near[0] ? '<div><i class="z2"></i>2</div>' : '') + (near[1] ? '<div><i class="z3"></i>3</div>' : '');
}

// Kariyer başlangıcı — oyuncunun oyuna kayıt tarihi + o günün sezonu: "12/12/2026 S1".
//   Tarih sunucudan (oyuncu_kayit_tarihi): gerçek kullanıcıda hesabın açıldığı an, botta satırın oluştuğu an.
const _plKayitOnb = {};
function _plKariyerBaslangicYaz(el, ts, sezon) {
  if (!ts) { el.style.display = 'none'; return; }
  const d = new Date(ts), iki = n => String(n).padStart(2, '0');
  el.innerHTML = `Kariyer başlangıcı: <b data-noi18n>${iki(d.getDate())}/${iki(d.getMonth() + 1)}/${d.getFullYear()}</b> <b class="sz" data-noi18n>S${sezon || _ptrSeasonOfTs(ts) || 1}</b>`;
  el.style.display = '';
}
function _plRenderCareerStart(p, isVisitor) {
  const el = document.getElementById('plCareerStart');
  if (!el) return;
  const oid = !isVisitor ? (window._benimOyuncuId || (p && p.id) || null) : (p && p.id != null && String(p.id) !== '' ? p.id : null);
  el.dataset.oid = oid != null ? String(oid) : '';
  const onb = oid != null ? _plKayitOnb[oid] : undefined;
  if (onb !== undefined) { _plKariyerBaslangicYaz(el, onb && onb.ts, onb && onb.sezon); return; }
  // Kendi profilinde hesap açılış tarihi zaten elde; sunucu yanıtına kadar onu göster
  const ilk = (!isVisitor && typeof authUser !== 'undefined' && authUser && authUser.created_at) ? new Date(authUser.created_at).getTime() : null;
  _plKariyerBaslangicYaz(el, ilk, null);
  if (oid == null || !window.sb) return;
  window.sb.rpc('oyuncu_kayit_tarihi', { p_id: oid }).then(({ data, error }) => {
    if (error) return;
    _plKayitOnb[oid] = (data && data.ts) ? { ts: Number(data.ts), sezon: data.sezon } : null;
    const k = _plKayitOnb[oid];
    if (el.dataset.oid === String(oid) && (k || isVisitor)) _plKariyerBaslangicYaz(el, k && k.ts, k && k.sezon);
  }, () => {});
}

function _plSakatlikSeridi(p, takimAdi) {
  const hero = document.getElementById('plHero');
  if (!hero) return;
  let el = document.getElementById('plInjStrip');
  if (!p || typeof isPlayerInjured !== 'function' || !isPlayerInjured(p)) { if (el) el.remove(); return; }
  if (!el) {
    el = document.createElement('div');
    el.id = 'plInjStrip'; el.className = 'pl-inj-strip';
    hero.parentNode.insertBefore(el, hero);
  }
  el.classList.remove('iyilesti');
  el.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="7" width="18" height="13" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M12 10.5v6M9 13.5h6"/></svg>`
    + `<span class="t"><b>Sakat</b> · <span data-noi18n>${_sakatlikTesisMetni(p, takimAdi).replace(/^🏥\s*/, '')}</span></span>${_sakatlikSayacHtml(p)}`;
}

function renderPlayerPage() {
  // 🆕 Ziyaretçi modu kontrolü
  const isVisitor = !!(typeof _visitedPlayerData !== 'undefined' && _visitedPlayerData && _visitedPlayerData.player);
  const vp = isVisitor ? _visitedPlayerData.player : null;
  const vctx = isVisitor ? (_visitedPlayerData.ctx || {}) : null;

  // page-player'a is-visitor class'ı (ayarlar gizleme için)
  const _pgPlayer = document.getElementById('page-player');
  if (_pgPlayer) _pgPlayer.classList.toggle('is-visitor', isVisitor);

  const user = authUser || {};
  const meRoster = (typeof ROSTER_DATA !== 'undefined') ? ROSTER_DATA.find(p => p.role === 'user') : null;
  // Ziyaretçide vp'nin pos/skills'i kullanılır
  const pos  = isVisitor ? (vp.pos || 'MID') : ((meRoster && meRoster.pos) || user.position || 'MID');
  const cfg  = POS_CONFIG[pos] || POS_CONFIG.MID;
  const lvls = isVisitor ? _carBuildSkillsForVisitor(vp) : getSkillLevels(pos);
  // 🆕 ITEM BONUSU GÖSTERİMİ — taban (itemsiz) değerler. Hesap DEĞİŞMEZ;
  //   yalnızca "efektif − taban" farkı ekranda ayrıca gösterilir. 637 — bu fark yalnız oyuncunun
  //   kendisine görünür; ziyaretçi ekipman dahil toplamı görür.
  const _lvlsRaw = isVisitor ? null : getSkillLevels(pos, { raw: true });
  // 🆕 Overall: ziyaretçide HER ZAMAN 45 skill ortalaması kullan (vp.overall'a güvenme)
  // Eskiden vp.overall'a fallback varsa eski/yüksek değer geliyordu.
  // Botlar artık SABİT 10 yetenekli → calcOverall(pos, lvls) → 10
  let overall;
  if (isVisitor) {
    // 🆕 Visitor OVR = lvls (UI barlarının kaynağı) ile aynı hesaplama.
    //   Bot: _carBuildSkillsForVisitor abilities'ten 45 skill üretti
    //   User: _visitorSkillsCache'ten 45 skill geldi
    //   Her iki durumda da 4 hat ortalamasının ortalamasını alıyoruz.
    //   Cache yüklenince UI yeniden render olur ve OVR de güncellenir.
    if (typeof SKILL_DEFS !== 'undefined' && SKILL_DEFS.ALL && lvls) {
      const _catAvgV = (catSkills) => {
        if (!catSkills || !catSkills.length) return null;
        const sum = catSkills.reduce((a, s) => a + (lvls[s.id] || 10), 0);
        return sum / catSkills.length;
      };
      const gk = _catAvgV(SKILL_DEFS.ALL[0] && SKILL_DEFS.ALL[0].skills);
      const df = _catAvgV(SKILL_DEFS.ALL[1] && SKILL_DEFS.ALL[1].skills);
      const md = _catAvgV(SKILL_DEFS.ALL[2] && SKILL_DEFS.ALL[2].skills);
      const fw = _catAvgV(SKILL_DEFS.ALL[3] && SKILL_DEFS.ALL[3].skills);
      if (gk != null && df != null && md != null && fw != null) {
        overall = Math.max(1, Math.min(99, Math.round((gk + df + md + fw) / 4)));
      } else {
        overall = Number(vp.overall || vp.rating || 10);
        overall = Math.max(1, Math.min(99, Math.round(overall)));
      }
    } else {
      overall = Number(vp.overall || vp.rating || 10);
      overall = Math.max(1, Math.min(99, Math.round(overall)));
    }
  } else if (meRoster && typeof getPlayerMainOverall === 'function') {
    overall = getPlayerMainOverall(meRoster);
  } else {
    overall = calcOverall(pos, lvls);
  }

  // Bayrak
  const flag = isVisitor ? (vp.nation || ccToFlag(vp.nationality)) : ((meRoster && meRoster.nation) || ccToFlag(user.nationality));

  const lvl = isVisitor ? (vp.level || 0) : ((meRoster && meRoster.level) || 0);

  // Hero — FIFA kart yapısı
  document.getElementById('plName').textContent    = isVisitor ? (vp.name || 'Oyuncu') : (user.name || 'Oyuncu');
  document.getElementById('plName').insertAdjacentHTML('beforeend', _cinsIk(isVisitor ? vp : Object.assign({ isUser: true }, meRoster || {})));   // 697
  try {   // 784 — beğeni: ziyaretçi kalbe dokunur, kendi profilinde salt sayı
    const _bEl = document.getElementById('plBgn');
    if (_bEl) {
      const _bUid = isVisitor ? (!vp.isBot && (vp.userId || vp.user_id)) : (user && user.id);
      const _benMi = !!(_bUid && user && user.id && String(_bUid) === String(user.id));
      _bEl.innerHTML = _bUid ? _bgnPill('oyuncu', String(_bUid), _bgnGiris()) : '';   // 785 — kendi profili de beğenilir
    }
  } catch (e) {}
  // 🆕 Milli Takım Oyuncusu rozeti (Oyuncum sayfası)
  try {
    const _ntB = document.getElementById('plNtBadge');
    if (_ntB) {
      _ntB.style.display = 'none';
      const _ntP = isVisitor ? vp : (meRoster || null);
      const _ntCc = (_ntP && _ntP.nationality) || (user && user.nationality);
      if (_ntP && _ntCc && typeof _isNtSquadPlayerSync === 'function') {
        let _ntM = _isNtSquadPlayerSync(_ntP, _ntCc);
        if (_ntM === null && typeof _loadNtSquadFromServer === 'function') {
          _loadNtSquadFromServer(_ntCc).then(() => { const _m2 = _isNtSquadPlayerSync(_ntP, _ntCc); const _e2 = document.getElementById('plNtBadge'); if (_e2 && _m2) _e2.style.display = ''; }).catch(()=>{});
        } else if (_ntM) { _ntB.style.display = ''; }
        // 🆕 🌍 yerine ülke bayrağı
        try {
          const _c = (typeof _cftGetCountry === 'function' && _ntCc) ? _cftGetCountry(_ntCc) : null;
          const _fl = (_c && _c.flag) || (_ntP && _ntP.nation) || '🌍';
          _ntB.textContent = _fl + ' Milli Takım Oyuncusu';
        } catch(e) {}
      }
    }
  } catch(e){}
  document.getElementById('plOverall').textContent = overall;
  const badge = document.getElementById('plPosBadge');
  badge.textContent  = cfg.label;
  badge.className    = 'pl-pos-pill ' + cfg.badge;
  // 🆕 Mevki haritası + kariyer başlangıcı
  try { _plRenderPosMap(isVisitor ? vp : (meRoster || {}), pos); } catch(e) { console.warn('[posMap]', e); }
  try { _plRenderCareerStart(isVisitor ? vp : (meRoster || {}), isVisitor); } catch(e) {}
  // 🆕 AÇIK SEKMEYİ TAZELE — ziyaretten dönünce ekipman/kariyer içeriği eski kalıyordu
  try {
    const _eqPane = document.getElementById('pl-equipment');
    if (_eqPane && _eqPane.style.display !== 'none' && typeof renderEquipment === 'function') renderEquipment();
    const _hiPane = document.getElementById('pl-history');
    if (_hiPane && _hiPane.style.display !== 'none' && typeof renderCareerTab === 'function') renderCareerTab();
  } catch(e) {}
  // Avatar: 
  //   - Ziyaretçi: vp.avatar_id varsa PNG (profiles tablosundan), yoksa vp.avatar emoji, yoksa pos fallback
  //   - Kendisi: authUser.avatarId
  if (isVisitor) {
    let visitorAvatarHTML = '';
    if (vp.avatar_id && typeof getAvatarEmoji === 'function') {
      visitorAvatarHTML = getAvatarEmoji(vp.avatar_id, pos);
    } else if (vp.avatar) {
      visitorAvatarHTML = vp.avatar;
    } else if (typeof getAvatarEmoji === 'function') {
      visitorAvatarHTML = getAvatarEmoji(null, pos);
    } else {
      visitorAvatarHTML = '👤';
    }
    document.getElementById('plAvatar').innerHTML = visitorAvatarHTML;
  } else {
    document.getElementById('plAvatar').innerHTML = getAvatarEmoji(user.avatarId, pos);
  }

  // 🆕 FIFA kart elementleri (Stadium tasarımı): pozisyon kısa kod, bayrak, takım
  const fcFlagEl = document.getElementById('plFcFlag');
  const fcTeamEl = document.getElementById('plFcTeam');
  const fcTeamNameEl = document.getElementById('plFcTeamName');
  if (fcFlagEl) fcFlagEl.textContent = flag;
  let ligIdx = null, ligAd = '', takimObj = null, takimCc = null, takimVar = false;
  // Takım kısa kodu — teams DB'den short field, yoksa isim ilk 3 harf
  if (fcTeamEl) {
    let teamShort = '—';
    let lookupCc = null, lookupName = null;
    if (isVisitor) {
      lookupCc = vctx.countryCode || null;
      lookupName = vctx.teamLookupName || vctx.teamName || vp.team || null;
    } else if (userHasTeam() && _userTeam) {
      lookupCc = _userTeam.countryCode;
      lookupName = _userTeam.teamName;
    }
    takimCc = lookupCc; takimVar = !!lookupName;
    if (lookupCc && lookupName) {
      if (true && _cftGetCountry(lookupCc)) {
        for (const [i, lg] of (_cftGetCountry(lookupCc).leagues || []).entries()) {
          const t = (lg.teams || []).find(x => x.name === lookupName);
          if (t) { teamShort = (t.short || lookupName.slice(0,3)).toUpperCase(); ligIdx = i; ligAd = lg.name || ''; takimObj = t; break; }
        }
      }
      if (teamShort === '—') teamShort = lookupName.slice(0,3).toUpperCase();
    }
    fcTeamEl.textContent = teamShort;
    // 🆕 Logo varsa <img> ile değiştir (crest-has-logo class çerçeveyi kaldırır, img dolar)
    if (lookupName && typeof applyCrestToEl === 'function') {
      applyCrestToEl(fcTeamEl, lookupName, teamShort);
    }
  }
  // Hero arka planı: takım rengi + sağ üstte soluk arma (Takımım hero'suyla aynı kaynak). Takımsız: lacivert.
  const _hero = document.getElementById('plHero');
  if (_hero) {
    _hero.style.setProperty('--tr', (takimObj && takimObj.bg) || (takimVar ? '#1f6f4a' : '#1e3a6b'));
    const _wm = document.getElementById('plHeroWm');
    const _logo = (takimObj && typeof teamLogoUrl === 'function') ? teamLogoUrl(Object.assign({}, takimObj, { countryCode: takimCc })) : null;
    if (_wm) _wm.style.backgroundImage = _logo ? `url("${_logo}")` : 'none';
  }
  // Lig klasman kalkanı (S / 1L / 2L / 3L …)
  const ligEl = document.getElementById('plFcLig');
  if (ligEl) {
    ligEl.innerHTML = (ligIdx != null && typeof _banKalkanImg === 'function') ? _banKalkanImg(ligIdx, 25) : '';
    ligEl.title = ligAd;
    ligEl.style.display = ligEl.innerHTML ? '' : 'none';
  }
  // Takım tam adı
  if (fcTeamNameEl) {
    if (isVisitor) {
      fcTeamNameEl.textContent = vctx.teamName || vp.team || 'Takımsız';
    } else {
      fcTeamNameEl.textContent = (userHasTeam() && _userTeam) ? _userTeam.teamName : 'Takımsız';
    }
  }

  // XP Progress Bar
  const currentXp = (isVisitor ? vp.xp : (meRoster && meRoster.xp)) || 0;
  const neededXp = (typeof rosterXpForLevel === 'function') ? rosterXpForLevel(lvl) : 100;
  const pct = Math.min(100, Math.round((currentXp / neededXp) * 100));
  const setXp = (id, val) => { const el = document.getElementById(id); if(el) el.textContent = val; };
  setXp('plXpLevel', lvl);
  setXp('plXpCurrent', currentXp.toLocaleString('tr'));
  setXp('plXpNeeded', neededXp.toLocaleString('tr'));
  setXp('plXpPct', pct + '%');
  setXp('plXpNextLevel', lvl + 1);
  const fillEl = document.getElementById('plXpFill');
  if(fillEl) fillEl.style.width = pct + '%';

  // İstatistik şeridi UI'dan kaldırıldı (kullanıcı isteği)
  const setStat = (id, val) => { const el=document.getElementById(id); if(el) el.textContent = val; };

  // 🆕 Piyasa değeri — TEK KAYNAK: getPlayerMarketValue(player)
  // Ziyaretçide vp (bot oyuncu), kendi profilinde ROSTER_DATA[user]
  const mvEl = document.getElementById('plMarketVal');
  const mvRow = document.getElementById('plMarketRow');
  if (mvEl) {
    // Hangi oyuncu? Ziyaretçi modunda bot, normal modda kendin
    let targetPlayer = null;
    if (isVisitor && vp) {
      targetPlayer = vp;
    } else if (typeof ROSTER_DATA !== 'undefined' && Array.isArray(ROSTER_DATA)) {
      targetPlayer = ROSTER_DATA.find(p => p && p.role === 'user') || null;
    }
    let mv = 0;
    let isCaptainSet = false;
    if (targetPlayer) {
      isCaptainSet = !!(typeof targetPlayer.captainMV === 'number' && targetPlayer.captainMV > 0);
      mv = (typeof getPlayerMarketValue === 'function') ? getPlayerMarketValue(targetPlayer) : 0;
    } else {
      mv = (typeof _carEstimateMarketValue === 'function')
            ? _carEstimateMarketValue({ overall: overall, level: 0 })
            : 0;
    }
    const fmtFull = (v) => (v || 0).toLocaleString('tr') + ' €';
    mvEl.innerHTML = fmtFull(mv);
    mvEl.style.color = 'var(--gold)';
    if (mvRow) mvRow.title = isCaptainSet ? 'Kaptan tarafından belirlendi' : 'Otomatik hesaplanan değer';
    // 🆕 Sezon maaşı (sistem) — piyasa değerinin yanında
    const salEl = document.getElementById('plSalaryVal');
    if (salEl) {
      const sal = (typeof getSystemPlayerSalary === 'function' && targetPlayer)
        ? getSystemPlayerSalary(targetPlayer)
        : (typeof getSystemPlayerSalary === 'function' ? getSystemPlayerSalary(overall) : 0);
      salEl.innerHTML = fmtFull(sal);
      salEl.style.color = 'var(--accent2)';
    }
  }

  // Güç satırı kaldırıldı — bilgiler artık FIFA kartında bar olarak gösteriliyor
  const defs = SKILL_DEFS.ALL;

  // 🆕 FIFA kart 4 stat — thb-line tarzı: değer + bar dolgusu (defs sırası: 0=Kaleci, 1=Defans, 2=Orta Saha, 3=Hücum)
  const fcStatIds  = ['plStGK','plStDEF','plStMID','plStATK'];
  const fcStatBars = ['plStGKBar','plStDEFBar','plStMIDBar','plStATKBar'];
  defs.forEach((cat, i) => {
    const avg = calcCatAvg(cat.skills, lvls);
    const valEl = document.getElementById(fcStatIds[i]);
    const barEl = document.getElementById(fcStatBars[i]);
    if (valEl) valEl.textContent = avg || '—';
    if (barEl) barEl.style.height = Math.max(0, Math.min(100, avg || 0)) + '%';
  });

  // Yetenekler — 4 bölüm × 3 sütun. Itemden gelen artı yalnız kendi profilinde görünür.
  const catsEl = document.getElementById('plSkillCategories');
  function skillRow(s) {
    const val = lvls[s.id] || 10;
    const _taban = (_lvlsRaw && _lvlsRaw[s.id] != null) ? _lvlsRaw[s.id] : val;
    const _bonus = Math.max(0, val - _taban);
    // 9 kademe: 0-19 gri · 20 açık sarı · 30 koyu sarı · 40 turuncu · 50 kırmızı · 60 yeşil · 70 mavi · 80 açık mor · 90+ premium mor
    let col, isPremium = false;
    if (val >= 90)      { col = '#b388ff'; isPremium = true; }
    else if (val >= 80) { col = '#ce93d8'; }
    else if (val >= 70) { col = '#2196f3'; }
    else if (val >= 60) { col = '#4caf50'; }
    else if (val >= 50) { col = '#f44336'; }
    else if (val >= 40) { col = '#ff9800'; }
    else if (val >= 30) { col = '#f9a825'; }
    else if (val >= 20) { col = '#fff176'; }
    else                { col = '#9aa3b2'; }
    return `<div class="ph-c${isPremium ? ' pr' : ''}"><span class="td" style="background:${col}"></span><span class="nm">${s.name}</span>`
      + `<b class="pl-grid-val${isPremium ? ' tier-premium' : ''}" style="color:${col}"${_bonus > 0 ? ` title="Taban ${_taban} · Itemden +${_bonus}"` : ''}>`
      + `${_bonus > 0 ? `<span class="pl-grid-bonus">+${_bonus}</span>` : ''}${val}</b></div>`;
  }
  catsEl.innerHTML = `<div class="ph-sk">${defs.map(cat => `<div class="ph-ch" style="--cc:${cat.color};--cc15:${cat.color}26"><span class="dt"></span><b>${cat.cat.replace(/^\S+\s+/, '')}</b><span class="av">${calcCatAvg(cat.skills, lvls)}</span></div>`
    + `<div class="ph-g">${cat.skills.map(skillRow).join('')}</div>`).join('')}</div>`;
  // 🆕 Piyasa değeri yukarıda (renderPlayerPage başında) zaten set edildi — eski override kaldırıldı
  // Kariyer tab açıksa yenile
  if(document.getElementById('pl-history')?.style.display !== 'none' && typeof renderCareerTab === 'function') renderCareerTab();
  // (512) Sakatlık şeridi — oyuncu profilinde kalan süre (canlı) + tesis bilgisi
  try { _plSakatlikSeridi(isVisitor ? vp : meRoster, isVisitor ? (vctx && (vctx.teamLookupName || vctx.teamName)) : (typeof _userTeam !== 'undefined' && _userTeam ? _userTeam.teamName : null)); } catch(e) {}
}

function toggleSkillCat(idx) {
  document.getElementById('skillCat'+idx).classList.toggle('collapsed');
}




// ══════════════════════════════════════════════════════════
// 🆕 TRANSFER GEÇMİŞİ (player_transfers) — bonservis + imza elması
// ══════════════════════════════════════════════════════════
async function _ptrRecord(item, offer) {
  if (!window.sb || !item || !offer) return;
  let season = null, day = null;
  try { const i = getSeasonInfo(); season = i.season; day = i.dayInSeason; } catch(e) {}
  const row = {
    player_user_id: item.playerUserId || item.userId || (item.sellerUserId ? null : null) || null,
    player_name:    item.playerId || item.playerName || '—',
    from_team:      item.sellerTeam || item.seller || null,
    from_cc:        item.countryCode || item.cc || null,
    to_team:        offer.fromTeam || null,
    to_cc:          offer.fromCC || null,
    fee_eur:        Number(offer.transferFee || offer.fee || 0) || 0,
    fee_dia:        Number(offer.signingDiamond || 0) || 0,
    season:         season,
    day_in_season:  day
  };
  try { await window.sb.from('player_transfers').insert(row); }
  catch(e) { console.warn('[player_transfers] insert hata:', e); }
}

var _ptrCache = {};
async function _ptrLoad(playerName, userId) {
  const key = (userId || '') + '|' + (playerName || '');
  if (_ptrCache[key]) return _ptrCache[key];
  if (!window.sb || (!playerName && !userId)) return [];
  try {
    let q = window.sb.from('player_transfers')
      .select('player_name,from_team,from_cc,to_team,to_cc,fee_eur,fee_dia,season,created_at')
      .order('created_at', { ascending: false }).limit(30);
    q = userId ? q.eq('player_user_id', userId) : q.eq('player_name', playerName);
    const { data } = await q;
    _ptrCache[key] = data || [];
    return _ptrCache[key];
  } catch(e) { return []; }
}

function _ptrHtml(rows) {
  if (!rows || !rows.length) return '';
  const money = r => {
    const parts = [];
    if (r.fee_eur > 0) parts.push(Number(r.fee_eur).toLocaleString('tr') + ' €');
    if (r.fee_dia > 0) parts.push(Number(r.fee_dia).toLocaleString('tr') + ' 💎');
    return parts.length ? parts.join(' + ') : 'Bonservissiz';
  };
  const dt = r => { const d = new Date(r.created_at); return isNaN(d.getTime()) ? '' : d.toLocaleDateString('tr', { day: '2-digit', month: 'short', year: 'numeric' }); };
  return '<div class="car-season-sec-t">🔁 Transferler</div>' + rows.map(r => `
    <div class="car-sr">
      <div class="car-sr-s">S${r.season || '?'}</div>
      <div class="car-sr-i">
        <div class="car-sr-t">${r.from_team || '—'} <span style="color:var(--text3)">→</span> ${r.to_team || '—'}</div>
        <div class="car-sr-m">${dt(r)}</div>
      </div>
      <div style="flex-shrink:0;font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;font-weight:900;font-size:12.5px;color:var(--accent,#00e676);text-align:right">${money(r)}</div>
    </div>`).join('');
}

// 🆕 Kayıtlı transfer yoksa: oyuna katılım tarihini baz alan "kariyer başlangıcı" satırı
function _ptrSeasonOfTs(ts) {
  if (!ts) return null;
  let curS = 1;
  try { curS = (getSeasonInfo().season) || 1; } catch(e) {}
  if (typeof _seasonRangeMs === 'function') {
    for (let k = 1; k <= curS; k++) {
      const r = _seasonRangeMs(k);
      if (ts >= r[0] && ts < r[1]) return k;
    }
    if (ts < _seasonRangeMs(1)[0]) return 1;   // sezon öncesi kayıt → S1
  }
  return curS;
}

function _ptrStartRow(p, isSelf) {
  let ts = null, team = null;
  // 1) Kendi profilinde: takım geçmişinin ilk kaydı (katılım tarihi + ilk takım)
  if (isSelf) {
    try {
      const ch = (typeof getCareerHistory === 'function') ? getCareerHistory() : [];
      if (ch && ch.length) {
        const first = ch[0];
        if (first && first.joinDate) ts = new Date(first.joinDate).getTime();
        team = (first && first.teamName) || null;
      }
    } catch(e) {}
    // Hesap oluşturma tarihi (takım geçmişi yoksa)
    if (!ts) {
      try { if (authUser && authUser.created_at) ts = new Date(authUser.created_at).getTime(); } catch(e) {}
    }
  }
  // 2) Herkes için: en eski maç kaydı (gerçek veri, ziyaretçide de çalışır)
  if (!ts || !team) {
    try {
      const mr = Array.isArray(p && (p.matchRatings || p.match_ratings)) ? (p.matchRatings || p.match_ratings) : [];
      const withTs = mr.filter(x => x && x.ts).sort((a, b) => a.ts - b.ts);
      if (withTs.length) {
        if (!ts) ts = withTs[0].ts;
        if (!team) team = withTs[0].isHome ? withTs[0].home : withTs[0].away;
      }
    } catch(e) {}
  }
  if (!team) team = (p && (p.teamName || p.team_name)) || null;
  if (!team) return '';
  const dStr = ts ? new Date(ts).toLocaleDateString('tr', { day: '2-digit', month: 'short', year: 'numeric' }) : '—';
  const sn = _ptrSeasonOfTs(ts);
  return '<div class="car-season-sec-t">🔁 Transferler</div>' + `
    <div class="car-sr">
      <div class="car-sr-s">S${sn || '?'}</div>
      <div class="car-sr-i">
        <div class="car-sr-t">🎬 Kariyer başlangıcı <span style="color:var(--text3)">→</span> ${team}</div>
        <div class="car-sr-m">${dStr}${isSelf ? ' · oyuna katılım' : ' · ilk maç kaydı'}</div>
      </div>
      <div style="flex-shrink:0;font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;font-weight:900;font-size:12px;color:var(--text3);text-align:right">Bedelsiz</div>
    </div>`;
}

// Takım geçmişi kutusuna transfer listesini asenkron ekle
function _ptrFillInto(elId, p, isSelf) {
  const el = document.getElementById(elId);
  if (!el) return;
  const nm = (p && (p.name)) || null;
  const uid = (p && (p.userId || p.user_id)) || null;
  _ptrLoad(nm, uid).then(rows => {
    const cur = document.getElementById(elId);
    if (!cur) return;
    if (rows && rows.length) {
      cur.insertAdjacentHTML('beforeend', _ptrHtml(rows));
    } else {
      // Kayıtlı transfer yok → kariyer başlangıcı (bedelsiz)
      const startHtml = _ptrStartRow(p, !!isSelf);
      if (startHtml) cur.insertAdjacentHTML('beforeend', startHtml);
    }
  }).catch(()=>{});
}

// 🆕 KARİYER SEKMESİ TEK GİRİŞ NOKTASI — ziyaretçi modunda başkasının,
//   kendi profilinde kendi verini render eder. (Eskiden yetenek render'ı
//   doğrudan renderCareerPage() çağırdığı için ziyarette kendi verin görünüyordu.)
// ══════════════════════════════════════════════════════════════════════
// 595 — KARİYER SEKMESİ (yeniden tasarım · yalnız gerçek veri)
//   Kaynaklar (hepsi sunucuda, herkes aynı veriyi görür):
//     players.kariyer        sezon → kulüp → turnuva [maç, gol, asist, reyting toplamı, reytingli maç]
//     players.stats_by_comp  sezon/turnuva toplamları (tam kayıt) — tablo toplamları buradan
//     players.match_ratings  son 50 maç (son 10 maç grafiği, reyting ortalaması)
//     players.pd_gecmis      piyasa değeri geçmişi (değer değiştiği gün sunucu yazar)
//     kariyer_hareket        kulüp değişiklikleri (katılım / ayrılma / transfer + bedel)
//   Bilinmeyen hiçbir değer uydurulmaz: kayıt yoksa "—" ya da açıklama gösterilir.
// ══════════════════════════════════════════════════════════════════════
var _krOnbellek = {};          // anahtar → { t, v }
var _krSon = null;             // son çizilen { anahtar, acik:{sezon:true} }
const _KR_KOVA = [
  { k: 'lig', ad: 'Lig',              renk: '#00e676', ik: 'lig' },
  { k: 'chm', ad: 'Şampiyonlar Ligi', renk: '#29b6ff', ik: 'yildiz' },
  { k: 'eli', ad: 'Elit Lig',         renk: '#b388ff', ik: 'kupa' },
  { k: 'con', ad: 'Konferans Ligi',   renk: '#ffb020', ik: 'kupa' },
  { k: 'enc', ad: 'EURO Nations Cup', renk: '#ff5c6c', ik: 'bayrak' },
];
const _KR_IKON = {
  simsek: '<path d="M13 2 4.5 13.5H11l-1 8.5L19.5 10H13l1-8Z"/>',
  grafik: '<path d="M3 20h18"/><path d="M4 16l5-5 4 3 7-8"/><path d="M15 6h5v5"/>',
  takvim: '<rect x="3.5" y="5" width="17" height="15" rx="2"/><path d="M3.5 10h17M8 3v4M16 3v4"/>',
  kalkan: '<path d="M12 3l7.5 2.7v5.5c0 4.7-3.1 8.3-7.5 9.8-4.4-1.5-7.5-5.1-7.5-9.8V5.7z"/>',
  transfer: '<path d="M4 8h14l-3-3M20 16H6l3 3"/>',
  lig: '<path d="M4 20V9l8-5 8 5v11"/><path d="M9 20v-6h6v6"/>',
  yildiz: '<path d="M12 3l2.7 5.6 6.1.9-4.4 4.3 1 6.1L12 17l-5.4 2.9 1-6.1-4.4-4.3 6.1-.9z"/>',
  kupa: '<path d="M8 4h8v5a4 4 0 0 1-8 0z"/><path d="M8 5.5H5a3 3 0 0 0 3 4M16 5.5h3a3 3 0 0 1-3 4M12 13v4M8.5 20h7M10 17h4v3h-4z"/>',
  bayrak: '<path d="M5 21V4M5 4h11l-2 4 2 4H5"/>',
  sevron: '<path d="M9 6l6 6-6 6"/>',
  basla: '<path d="M7 4v16l12-8z"/>',
  cikis: '<path d="M14 4h5v16h-5"/><path d="M10 12H3m3-3-3 3 3 3"/>',
  bilgi: '<circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 8h.01"/>',
};
function _krIk(ad, renk, cls) {
  return `<svg class="kr-ik${cls ? ' ' + cls : ''}" viewBox="0 0 24 24"${renk ? ` style="color:${renk}"` : ''}>${_KR_IKON[ad] || ''}</svg>`;
}
function _krEsc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }
function _krSayi(v) { return (Number(v) || 0).toLocaleString((typeof window._tarihYerel === 'function') ? window._tarihYerel() : 'tr-TR'); }
function _krEur(v) { return _krSayi(Math.round(Number(v) || 0)) + ' €'; }
function _krKisaEur(v) {
  v = Number(v) || 0;
  if (v >= 1e6) return (Math.round(v / 1e4) / 100).toLocaleString((typeof window._tarihYerel === 'function') ? window._tarihYerel() : 'tr-TR') + 'M €';
  if (v >= 1e3) return Math.round(v / 1e3) + 'K €';
  return Math.round(v) + ' €';
}
function _krTarih(ms) {
  const d = new Date(ms); if (isNaN(d.getTime())) return '';
  return d.toLocaleDateString((typeof window._tarihYerel === 'function') ? window._tarihYerel() : 'tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric' });
}
function _krRenk(r) { return r >= 8 ? '#29b6ff' : r >= 7 ? '#00e676' : r >= 6.5 ? '#c6e04a' : r >= 6 ? '#ffb020' : '#ff5c6c'; }
function _krKova(tk) { if (!tk || tk === 'league') return 'lig'; return ({ champ: 'chm', elite: 'eli', conv: 'con', enc: 'enc' })[tk] || null; }
function _krAktifSezon() {
  try { return ((typeof _etkinSezon === 'function') ? _etkinSezon() : getSeasonInfo().season) || 1; } catch (e) { return 1; }
}
function _krSezonGun(ms) {
  // İstemcideki getSeasonInfo ile aynı kural (UTC gün, 40 günlük sezon)
  try {
    const ep = Date.UTC(SEASON_EPOCH.getUTCFullYear(), SEASON_EPOCH.getUTCMonth(), SEASON_EPOCH.getUTCDate());
    const d = new Date(ms); const g = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate());
    const n = Math.floor((g - ep) / 86400000); if (n < 0) return { s: 1, g: 0 };
    return { s: Math.floor(n / SEASON_LEN) + 1, g: (n % SEASON_LEN) + 1 };
  } catch (e) { return { s: null, g: null }; }
}
// Kulüp anahtarı "TR|Artvin" · milli takım "NT|TR" · ayrılamayan "?"
function _krAnahtar(k) {
  const i = String(k).indexOf('|');
  if (i < 0) return { tur: 'bilinmez', ad: '', cc: '' };
  const a = k.slice(0, i), b = k.slice(i + 1);
  if (a === 'NT') {
    const c = (typeof _cftGetCountry === 'function') ? _cftGetCountry(b) : null;
    return { tur: 'milli', cc: b, ad: (c && c.name) || b };
  }
  return { tur: 'kulup', cc: a === '?' ? '' : a, ad: b };
}
function _krArma(k, boy) {
  const a = typeof k === 'string' ? _krAnahtar(k) : k;
  if (a.tur === 'milli') {
    const fl = (typeof ccToFlag === 'function') ? ccToFlag(a.cc) : '🏳️';
    return `<span class="kr-arma kr-bayrak" style="width:${boy}px;height:${boy}px;font-size:${Math.round(boy * .8)}px">${fl}</span>`;
  }
  if (!a.ad) return `<span class="kr-arma kr-bos" style="width:${boy}px;height:${boy}px">?</span>`;
  try {
    if (typeof inlineBadge === 'function') {
      return `<span class="kr-arma" style="width:${boy}px;height:${boy}px">${inlineBadge({ name: a.ad, cc: a.cc || undefined, tag: 'span', cls: 'kr-arma-ic' })}</span>`;
    }
  } catch (e) {}
  return `<span class="kr-arma kr-bos" style="width:${boy}px;height:${boy}px">${_krEsc(a.ad.slice(0, 3))}</span>`;
}

// ── Veri ────────────────────────────────────────────────────────────
const _KR_KOLON = 'id, name, user_id, team_name, country_code, nationality, level, overall, rating, abilities, '
  + 'matches_played, goals_total, assists_total, motm_total, match_ratings, stats_by_comp, kariyer, pd_gecmis';
function _krKimlik(p, benMi) {
  const uid = benMi ? (typeof authUser !== 'undefined' && authUser && authUser.id) : (p && (p.userId || p.user_id));
  const id = (p && p.id != null && String(p.id) !== '') ? p.id : null;   // players.id (uuid ya da sayı)
  const anahtar = id != null ? 'id:' + id : (uid ? 'u:' + uid : 'n:' + (p && p.name) + '|' + (p && (p.teamName || p.team_name || p.team)));
  return { uid, id, anahtar };
}
async function _krYukle(p, benMi) {
  if (!window.sb) throw new Error('baglanti_yok');
  const { uid, id, anahtar } = _krKimlik(p, benMi);
  const on = _krOnbellek[anahtar];
  if (on && Date.now() - on.t < 60000) return on.v;

  // Sıra: kimlik → hesap → ad+takım (ilk bulan). Ad+takım yalnız başka yol yoksa.
  const yollar = [];
  if (id != null) yollar.push(q => q.eq('id', id));
  if (uid) yollar.push(q => q.eq('user_id', uid).eq('is_bot', false));
  if (p && p.name && (p.teamName || p.team_name || p.team)) yollar.push(q => {
    q = q.eq('name', p.name).eq('team_name', p.teamName || p.team_name || p.team);
    const cc = p.countryCode || p.country_code; return cc ? q.eq('country_code', cc) : q;
  });
  let yol = 0;
  const semaHatasi = e => e && (e.code === '42703' || /kariyer|pd_gecmis/.test(String(e.message || '')));
  const sec = async (kolon) => {
    let sonHata = null;
    for (let i = yol; i < yollar.length; i++) {
      const r = await yollar[i](window.sb.from('players').select(kolon)).limit(1).maybeSingle();
      if (r.data || semaHatasi(r.error)) { yol = i; return r; }
      if (r.error) sonHata = r.error;              // ör. geçersiz kimlik biçimi → sıradaki yol
    }
    return { data: null, error: sonHata };
  };
  let { data: row, error } = await sec(_KR_KOLON);
  let eskiSema = false;
  if (semaHatasi(error)) {
    eskiSema = true;                                            // SQL henüz kurulmadı
    ({ data: row, error } = await sec(_KR_KOLON.replace(', kariyer, pd_gecmis', '')));
  }
  if (error) throw error;
  if (!row) throw new Error('oyuncu_yok');

  // Geçmişi henüz kurulmamış oyuncu (ör. ilk kez görüntülenen bot): sunucu kendi kayıtlarından kurar
  if (!eskiSema && (!row.kariyer || !row.kariyer._v)) {
    try {
      const { error: rErr } = await window.sb.rpc('kariyer_hazirla', { p_id: row.id });
      if (!rErr) { const t2 = await sec(_KR_KOLON); if (t2.data) row = t2.data; }
    } catch (e) {}
  }
  let hareket = [];
  if (!eskiSema) {
    try {
      const { data: h } = await window.sb.from('kariyer_hareket')
        .select('eski_takim,eski_cc,yeni_takim,yeni_cc,tur,bedel_eur,bedel_dia,sezon,gun,zaman,tarih_kesin,kaynak')
        .eq('oyuncu_id', row.id).order('zaman', { ascending: false }).limit(200);
      hareket = Array.isArray(h) ? h.slice().reverse() : [];
    } catch (e) {}
  }
  const v = { row, hareket, eskiSema, anahtar };
  _krOnbellek[anahtar] = { t: Date.now(), v };
  return v;
}

// Sezon satırları: toplamlar stats_by_comp'tan, kulüp dağılımı kariyer'den.
//   İkisi tutmazsa (ör. kayıt aksadıysa) fark "kulübe ayrılamadı" satırında gösterilir — asla uydurulmaz.
function _krSezonlar(row) {
  const sbc = (row.stats_by_comp && typeof row.stats_by_comp === 'object') ? row.stats_by_comp : {};
  const kr = (row.kariyer && typeof row.kariyer === 'object') ? row.kariyer : {};
  const sezonSet = new Set();
  Object.keys(sbc).forEach(b => { const o = sbc[b]; if (o && typeof o === 'object') Object.keys(o).forEach(k => { const n = /^s(\d+)$/.exec(k); if (n) sezonSet.add(+n[1]); }); });
  Object.keys(kr).forEach(k => { if (/^\d+$/.test(k)) sezonSet.add(+k); });
  const out = [];
  [...sezonSet].sort((a, b) => b - a).forEach(s => {
    const ks = (kr[String(s)] && typeof kr[String(s)] === 'object') ? kr[String(s)] : {};
    const satir = {};          // anahtar → { kova → [m,g,a,rs,rn] }
    Object.keys(ks).forEach(k => {
      if (k === '_a') return;
      const o = ks[k]; if (!o || typeof o !== 'object') return;
      Object.keys(o).forEach(b => { const t = o[b]; if (Array.isArray(t)) { (satir[k] = satir[k] || {})[b] = t.map(x => Number(x) || 0); } });
    });
    // stats_by_comp ile karşılaştır: eksik kalan kısım "?" satırına
    _KR_KOVA.forEach(({ k: b }) => {
      const t = sbc[b] && sbc[b]['s' + s]; if (!t) return;
      let m = 0, g = 0, a = 0;
      Object.keys(satir).forEach(k => { const x = satir[k][b]; if (x) { m += x[0]; g += x[1]; a += x[2]; } });
      const dm = (Number(t.m) || 0) - m, dg = (Number(t.g) || 0) - g, da = (Number(t.a) || 0) - a;
      if (dm > 0) {
        const q = (satir['?'] = satir['?'] || {});
        const x = q[b] || [0, 0, 0, 0, 0];
        q[b] = [x[0] + dm, x[1] + Math.max(0, dg), x[2] + Math.max(0, da), x[3], x[4]];
      }
    });
    const topla = (kovalar) => {
      let m = 0, g = 0, a = 0, rs = 0, rn = 0;
      Object.keys(kovalar).forEach(b => { const x = kovalar[b]; m += x[0]; g += x[1]; a += x[2]; rs += x[3]; rn += x[4]; });
      return { m, g, a, rs, rn, ort: (m > 0 && rn === m) ? rs / rn : null };
    };
    const satirlar = Object.keys(satir).map(k => ({ k, ...topla(satir[k]), kovalar: satir[k] }))
      .filter(x => x.m > 0);
    if (!satirlar.length) return;
    const tur = k => k === '?' ? 2 : (k.startsWith('NT|') ? 1 : 0);
    satirlar.sort((x, y) => tur(x.k) - tur(y.k) || y.m - x.m);
    // Turnuva kırılımı (sezon geneli)
    const kovaTop = {};
    satirlar.forEach(r => Object.keys(r.kovalar).forEach(b => {
      const x = r.kovalar[b], o = (kovaTop[b] = kovaTop[b] || [0, 0, 0, 0, 0]);
      for (let i = 0; i < 5; i++) o[i] += x[i];
    }));
    const tum = topla(kovaTop);
    out.push({ s, satirlar, kovaTop, ...tum, aday: Array.isArray(ks._a) ? ks._a : [] });
  });
  return out;
}

// Kulüp kariyeri: kariyer'deki kulüp satırlarının sezonlar boyu toplamı
function _krKulupler(row, sezonlar) {
  const map = {};
  sezonlar.forEach(S => S.satirlar.forEach(r => {
    if (r.k === '?') return;
    const o = (map[r.k] = map[r.k] || { k: r.k, m: 0, g: 0, a: 0, bas: S.s, son: S.s });
    o.m += r.m; o.g += r.g; o.a += r.a; o.bas = Math.min(o.bas, S.s); o.son = Math.max(o.son, S.s);
  }));
  // Şu anki kulüp (henüz maçı olmasa da)
  if (row.team_name) {
    const k = (row.country_code || '?') + '|' + row.team_name;
    if (!map[k]) map[k] = { k, m: 0, g: 0, a: 0, bas: _krAktifSezon(), son: _krAktifSezon() };
    map[k].simdi = true;
  }
  const ayrilamayan = [];
  sezonlar.forEach(S => S.satirlar.forEach(r => { if (r.k === '?') ayrilamayan.push({ s: S.s, m: r.m }); }));
  const liste = Object.values(map);
  const tur = k => k.startsWith('NT|') ? 1 : 0;
  liste.sort((x, y) => tur(x.k) - tur(y.k) || (y.simdi ? 1 : 0) - (x.simdi ? 1 : 0) || y.son - x.son || y.m - x.m);
  return { liste, ayrilamayan };
}

// ── Çizim ───────────────────────────────────────────────────────────
function _krBolum(ik, renk, baslik, meta, ic, ek) {
  return `<section class="kr-sec${ek ? ' ' + ek : ''}"><div class="kr-sec-t">${_krIk(ik, renk)}<span>${baslik}</span>${meta ? `<em>${meta}</em>` : ''}</div>${ic}</section>`;
}

function _krKpi(row) {
  const mr = Array.isArray(row.match_ratings) ? row.match_ratings.filter(x => x && typeof x.rating === 'number') : [];
  const ort = mr.length ? mr.reduce((t, x) => t + x.rating, 0) / mr.length : null;
  const h = [
    [_krSayi(row.matches_played), 'maç', '', ''],
    [_krSayi(row.goals_total), 'gol', 'var(--accent)', ''],
    [_krSayi(row.assists_total), 'asist', 'var(--gold)', ''],
    [ort != null ? ort.toFixed(1) : '—', 'Ort.', ort != null ? _krRenk(ort) : '', mr.length ? `son ${mr.length} maç` : ''],
    [_krSayi(row.motm_total), 'M. Adamı', 'var(--accent2)', ''],
  ];
  return `<div class="kr-kpi">${h.map(([v, l, c, alt]) => `<div><b${c ? ` style="color:${c}"` : ''}>${v}</b><span>${l}</span>${alt ? `<i>${alt}</i>` : ''}</div>`).join('')}</div>`;
}

function _krSon10(row) {
  const mr = Array.isArray(row.match_ratings) ? row.match_ratings.filter(x => x && typeof x.rating === 'number') : [];
  if (!mr.length) return _krBolum('simsek', '#00e676', 'Son 10 Maç', '', '<div class="kr-bos-y">Henüz maç oynanmadı</div>');
  const son = mr.slice(-10);
  const lk = (typeof window._ligKolon === 'function') ? window._ligKolon() : { g: 'G', b: 'B', m: 'M' };
  let motmVar = false, hazVar = false;
  const bars = son.map(m => {
    const rt = m.rating, h = Math.max(8, Math.min(1, (rt - 4) / 6) * 76);
    const opp = m.opp || (m.isHome ? m.away : m.home) || '';
    const kendi = m.isHome ? m.home : m.away;
    let rakip = { tur: 'kulup', ad: opp, cc: '' };
    if (m.tournament_key === 'enc') {
      let occ = '';
      try { occ = (_cftGetCountryCodes() || []).find(c => { const o = _cftGetCountry(c); return o && o.name === opp; }) || ''; } catch (e) {}
      rakip = occ ? { tur: 'milli', cc: occ, ad: opp } : { tur: 'kulup', ad: '', cc: '' };
    } else if ((!m.tournament_key || m.tournament_key === 'league') && kendi && kendi === row.team_name) {
      rakip.cc = row.country_code || '';
    }
    const s = m.result === 'W' ? 'g' : (m.result === 'D' ? 'b' : (m.result === 'L' ? 'm' : 'x'));
    const haz = !_krKova(m.tournament_key); if (haz) hazVar = true;
    if (m.motm === true) motmVar = true;
    const gs = (m.goals || 0) > 0 ? `<s class="kr-b-g">${m.goals}</s>` : '';
    const as = (m.assists || 0) > 0 ? `<s class="kr-b-a">${m.assists}</s>` : '';
    return `<div class="kr-b${haz ? ' haz' : ''}">${m.motm === true ? _krIk('yildiz', '', 'kr-st') : ''}<em style="color:${_krRenk(rt)}">${rt.toFixed(1)}</em>`
      + `<i style="height:${h.toFixed(0)}px;background:linear-gradient(180deg,${_krRenk(rt)},${_krRenk(rt)}40)"></i>`
      + `<span class="kr-b-rk">${_krArma(rakip, 16)}</span>`
      + `<u class="kr-s-${s}">${s === 'g' ? lk.g : (s === 'b' ? lk.b : (s === 'm' ? lk.m : '?'))}</u><span class="kr-b-ga">${gs}${as}</span></div>`;
  }).join('');
  const lej = `<div class="kr-lej"><span><i style="background:#29b6ff"></i>8+</span><span><i style="background:#00e676"></i>7–7,9</span>`
    + `<span><i style="background:#c6e04a"></i>6,5–6,9</span><span><i style="background:#ffb020"></i>6–6,4</span><span><i style="background:#ff5c6c"></i>6-</span>`
    + `<span><s class="kr-b-g">1</s>Gol</span><span><s class="kr-b-a">1</s>Asist</span>`
    + (motmVar ? `<span>${_krIk('yildiz', '#ffd600')}Maçın adamı</span>` : '')
    + (hazVar ? `<span><i class="haz"></i>Hazırlık maçı</span>` : '') + `</div>`;
  return _krBolum('simsek', '#00e676', 'Son 10 Maç', 'reyting', `<div class="kr-bars">${bars}</div>${lej}`);
}

function _krDeger(row, hareket, p) {
  // Güncel değer profil üstündekiyle aynı nesneden hesaplanır (aynı ekranda iki farklı rakam olmasın)
  let simdi = 0;
  const kaynak = (p && p.abilities && typeof p.abilities === 'object') ? p : row;
  try { simdi = (typeof getPlayerMarketValue === 'function') ? getPlayerMarketValue(kaynak) : 0; } catch (e) {}
  const pts = (Array.isArray(row.pd_gecmis) ? row.pd_gecmis : [])
    .filter(x => Array.isArray(x) && isFinite(x[0]) && isFinite(x[1])).map(x => ({ t: +x[0], v: +x[1] }));
  if (simdi > 0 && (!pts.length || pts[pts.length - 1].v !== simdi || Date.now() - pts[pts.length - 1].t > 3600000)) pts.push({ t: Date.now(), v: simdi, canli: true });
  const zirve = pts.reduce((z, p) => (!z || p.v > z.v) ? p : z, null);
  const bas = `<div class="kr-mv-h"><div><b>${_krEur(simdi)}</b><span>güncel piyasa değeri</span></div>`
    + (zirve && new Set(pts.map(q => q.v)).size > 1 ? `<div class="kr-mv-z"><span>En yüksek</span><b>${_krKisaEur(zirve.v)}</b><em>S${_krSezonGun(zirve.t).s}</em></div>` : '') + `</div>`;
  if (new Set(pts.map(q => q.v)).size < 2) {
    // Değer hiç değişmemiş: grafik yerine kaydın ne zamandan beri tutulduğu
    const ilk = pts.length ? pts[0].t : Date.now();
    const not = (Date.now() - ilk > 86400000)
      ? `Değer ${_krTarih(ilk)} tarihinden beri değişmedi.`
      : 'Değer geçmişi bu güncellemeyle kaydedilmeye başladı. Değer değiştikçe grafik oluşur.';
    return _krBolum('grafik', '#00e676', 'Piyasa Değeri', '', bas + `<div class="kr-not">${_krIk('bilgi')}<span>${not}</span></div>`);
  }
  const W = 320, H = 132, PL = 34, PR = 10, PT = 16, PB = 22;
  const t0 = pts[0].t, t1 = pts[pts.length - 1].t, dt = Math.max(1, t1 - t0);
  const vmax = Math.max(...pts.map(p => p.v)), vmin = Math.min(...pts.map(p => p.v));
  const ust = vmax * 1.08, alt = Math.max(0, vmin - (vmax - vmin) * 0.25 - vmax * 0.02);
  const x = t => PL + (t - t0) / dt * (W - PL - PR), y = v => PT + (1 - (v - alt) / Math.max(1, ust - alt)) * (H - PT - PB);
  // basamaklı çizgi: değer bir sonraki kayda kadar sabit kalır
  let d = `M${x(pts[0].t).toFixed(1)},${y(pts[0].v).toFixed(1)}`;
  for (let i = 1; i < pts.length; i++) d += `H${x(pts[i].t).toFixed(1)}V${y(pts[i].v).toFixed(1)}`;
  const alan = d + `V${H - PB}H${x(t0).toFixed(1)}Z`;
  const izg = [0, 1, 2].map(i => { const v = alt + (ust - alt) * i / 2; return `<line x1="${PL}" x2="${W - PR}" y1="${y(v).toFixed(1)}" y2="${y(v).toFixed(1)}" class="g"/><text x="${PL - 5}" y="${(y(v) + 3).toFixed(1)}" text-anchor="end" class="ax">${_krKisaEur(v).replace(' €', '')}</text>`; }).join('');
  // sezon sınırları
  let sez = '';
  const s0 = _krSezonGun(t0).s, s1 = _krSezonGun(t1).s;
  if (s0 && s1 && typeof _seasonRangeMs === 'function') {
    for (let s = s0; s <= s1; s++) {
      const r = _seasonRangeMs(s); const a = Math.max(r[0], t0), b = Math.min(r[1], t1);
      if (s > s0 && r[0] > t0 && r[0] < t1) sez += `<line x1="${x(r[0]).toFixed(1)}" x2="${x(r[0]).toFixed(1)}" y1="${PT - 6}" y2="${H - PB}" class="sz"/>`;
      if (b > a) sez += `<text x="${((x(a) + x(b)) / 2).toFixed(1)}" y="${H - 6}" text-anchor="middle" class="ax">S${s}</text>`;
    }
  }
  // kulüp değişiklikleri (grafik aralığındaysa)
  const isaret = (hareket || []).filter(h => h.yeni_takim && h.tarih_kesin !== false).map(h => ({ ...h, ms: new Date(h.zaman).getTime() }))
    .filter(h => h.ms >= t0 && h.ms <= t1).map(h => {
      const xx = x(h.ms); const vv = (pts.filter(p => p.t <= h.ms).pop() || pts[0]).v;
      return `<line x1="${xx.toFixed(1)}" x2="${xx.toFixed(1)}" y1="${(y(vv) - 4).toFixed(1)}" y2="${(y(vv) - 16).toFixed(1)}" class="tr"/>`
        + `<foreignObject x="${(xx - 9).toFixed(1)}" y="${(y(vv) - 36).toFixed(1)}" width="18" height="18">${_krArma((h.yeni_cc || '?') + '|' + h.yeni_takim, 18)}</foreignObject>`;
    }).join('');
  const nokta = pts.map((p, i) => i === pts.length - 1
    ? `<circle cx="${x(p.t).toFixed(1)}" cy="${y(p.v).toFixed(1)}" r="3.6" fill="#fff" stroke="#00e676" stroke-width="2"/>`
    : `<circle cx="${x(p.t).toFixed(1)}" cy="${y(p.v).toFixed(1)}" r="2" fill="#00e676"/>`).join('');
  const svg = `<svg viewBox="0 0 ${W} ${H}" class="kr-mv-svg"><defs><linearGradient id="krMvG" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#00e676" stop-opacity=".3"/><stop offset="1" stop-color="#00e676" stop-opacity="0"/></linearGradient></defs>`
    + izg + sez + `<path d="${alan}" fill="url(#krMvG)"/><path d="${d}" fill="none" stroke="#00e676" stroke-width="2.2" stroke-linejoin="round"/>` + isaret + nokta + `</svg>`;
  const kayit = `<div class="kr-mv-a"><span>${_krTarih(t0)}</span><span>${_krTarih(t1)}</span></div>`;
  return _krBolum('grafik', '#00e676', 'Piyasa Değeri', '', bas + svg + kayit);
}

function _krBasliklar() {
  let d = 'tr'; try { d = (typeof i18nLang === 'function') ? i18nLang() : 'tr'; } catch (e) {}
  return ({ en: ['MP', 'G', 'A', 'Avg'], de: ['Sp', 'T', 'V', 'Ø'], es: ['PJ', 'G', 'A', 'Med'], pt: ['J', 'G', 'A', 'Méd'],
            it: ['P', 'G', 'A', 'Med'], fr: ['M', 'B', 'PD', 'Moy'], ru: ['И', 'Г', 'П', 'Ср'] })[d] || ['M', 'G', 'A', 'Ort'];
}
function _krTablo(row, sezonlar, acik) {
  if (!sezonlar.length) return _krBolum('takvim', '#29b6ff', 'Sezon Sezon', '', '<div class="kr-bos-y">Henüz resmi maç yok</div>');
  const aktif = _krAktifSezon();
  const hucre = (m, g, a, ort) => `<div class="c-n">${m}</div><div class="c-n g">${g}</div><div class="c-n a">${a}</div>`
    + `<div class="c-r">${ort != null ? `<b style="background:${_krRenk(ort)}">${ort.toFixed(1)}</b>` : '<span class="yok">—</span>'}</div>`;
  let ortEksik = false;
  const govde = sezonlar.map(S => {
    const ac = !!acik[S.s];
    const kulupSat = S.satirlar.map((r, j) => {
      if (r.ort == null) ortEksik = true;
      const a = r.k === '?' ? null : _krAnahtar(r.k);
      const ad = r.k === '?'
        ? `<span class="kr-aday">${(S.aday || []).map(k => _krArma(k, 16)).join('')}</span><span class="kr-soluk">Kulübe ayrılamadı</span>`
        : `${_krArma(r.k, 18)}<span${a.tur === 'milli' ? '' : ' data-noi18n'}>${_krEsc(a.ad)}</span>`;   // milli takım: bayrak + ülke adı
      return `<div class="kr-r${j ? ' alt' : ''}"><div class="c-s">${j ? '' : `S${S.s}${S.s === aktif ? '<i>Aktif</i>' : ''}`}</div>`
        + `<div class="c-k">${ad}</div>${hucre(r.m, r.g, r.a, r.ort)}`
        + `<div class="c-v">${j ? '' : _krIk('sevron', '', ac ? 'dn' : '')}</div></div>`;
    }).join('');
    const det = ac ? `<div class="kr-det">${_KR_KOVA.filter(K => S.kovaTop[K.k] && S.kovaTop[K.k][0] > 0).map(K => {
      const x = S.kovaTop[K.k]; const o = (x[0] > 0 && x[4] === x[0]) ? x[3] / x[4] : null;
      return `<div class="kr-r kr-dr"><div class="c-s"></div><div class="c-k">${_krIk(K.ik, K.renk)}<span>${K.ad}</span></div>${hucre(x[0], x[1], x[2], o)}<div class="c-v"></div></div>`;
    }).join('')}</div>` : '';
    return `<div class="kr-grp${ac ? ' ac' : ''}" onclick="_krSezonAc(${S.s})">${kulupSat}${det}</div>`;
  }).join('');
  let tm = 0, tg = 0, ta = 0, trs = 0, trn = 0;
  const kulupSay = new Set();
  sezonlar.forEach(S => { tm += S.m; tg += S.g; ta += S.a; trs += S.rs; trn += S.rn; S.satirlar.forEach(r => { if (r.k !== '?' && !r.k.startsWith('NT|')) kulupSay.add(r.k); }); });
  const tort = (tm > 0 && trn === tm) ? trs / trn : null;
  const B = _krBasliklar();
  const bas = `<div class="kr-r h"><div class="c-s">Sezon</div><div class="c-k">Kulüp</div><div class="c-n" data-noi18n>${B[0]}</div><div class="c-n" data-noi18n>${B[1]}</div><div class="c-n" data-noi18n>${B[2]}</div><div class="c-r" data-noi18n>${B[3]}</div><div class="c-v"></div></div>`;
  const top = `<div class="kr-r top"><div class="c-s">Toplam</div><div class="c-k"><span class="kr-soluk">${sezonlar.length} sezon · ${kulupSay.size} kulüp</span></div>${hucre(tm, tg, ta, tort)}<div class="c-v"></div></div>`;
  const notlar = [];
  const fark = (Number(row.matches_played) || 0) - tm;
  if (fark > 0) notlar.push(`Tabloda resmi maçlar var. Kariyer toplamındaki diğer ${fark} maç (hazırlık maçları ve sezon kaydı tutulmadan önceki maçlar) tabloda yer almıyor.`);
  if (ortEksik || tort == null) notlar.push('Reyting ortalaması yalnız bütün maçlarının reytingi kayıtlı olan satırlarda gösterilir.');
  const not = notlar.map(n => `<div class="kr-not">${_krIk('bilgi')}<span>${n}</span></div>`).join('');
  return _krBolum('takvim', '#29b6ff', 'Sezon Sezon', 'satıra dokun → turnuvalar', `<div class="kr-tbl">${bas}${govde}${top}</div>${not}`);
}

function _krKulupKariyer(row, sezonlar, hareket) {
  const { liste, ayrilamayan } = _krKulupler(row, sezonlar);
  // Şu anki kulübe katılış sezonu: yalnız kayıtlı hareketten (kesin)
  let katilisS = null;
  (hareket || []).forEach(h => {
    if (h.yeni_takim === row.team_name && (h.yeni_cc || '') === (row.country_code || '') && h.tarih_kesin !== false
        && ['baslangic', 'katilim', 'transfer'].includes(h.tur)) katilisS = (h.sezon != null) ? h.sezon : _krSezonGun(new Date(h.zaman).getTime()).s;
  });
  if (!liste.length) return _krBolum('kalkan', '#b388ff', 'Kulüp Kariyeri', '', '<div class="kr-bos-y">Henüz kulüp kaydı yok</div>');
  const satir = liste.map(o => {
    const a = _krAnahtar(o.k);
    const donem = a.tur === 'milli'
      ? `<span class="kr-mt">Milli takım</span> <span>S${o.bas}${o.son !== o.bas ? ' → S' + o.son : ''}</span>`
      : (o.simdi
          ? (katilisS ? `<span>S${katilisS} →</span><span>bugün</span>` : `<span>S${o.bas}${o.son !== o.bas ? ' → S' + o.son : ''}</span><span class="kr-simdi">Şu an</span>`)
          : `<span>S${o.bas}${o.son !== o.bas ? ' → S' + o.son : ''}</span>`);
    return `<div class="kr-kr${a.tur === 'milli' ? ' milli' : ''}${o.simdi ? ' simdi' : ''}">${_krArma(o.k, 30)}<div class="n"><b${a.tur === 'milli' ? '' : ' data-noi18n'}>${_krEsc(a.ad)}</b><div class="d">${donem}</div></div>`
      + `<div class="s"><b>${o.m}</b><span>maç</span></div><div class="s"><b class="g">${o.g}</b><span>gol</span></div><div class="s"><b class="a">${o.a}</b><span>asist</span></div></div>`;
  }).join('');
  const topAyr = ayrilamayan.reduce((t, x) => t + x.m, 0);
  const not = topAyr > 0
    ? `<div class="kr-not">${_krIk('bilgi')}<span>Kulübü kayıtlı olmayan ${topAyr} maç kulüp toplamlarına eklenmedi (${ayrilamayan.map(x => 'S' + x.s).reverse().join(', ')}).</span></div>`
    : '';
  return _krBolum('kalkan', '#b388ff', 'Kulüp Kariyeri', '', satir + not);
}

function _krTransferler(row, hareket, sezonlar) {
  const h = (hareket || []).slice();
  if (!h.length) {
    return _krBolum('transfer', '#ffd600', 'Transfer Geçmişi', '', `<div class="kr-bos-y">Kayıtlı kulüp değişikliği yok</div>`);
  }
  const satirlar = h.slice().reverse().map((x) => {
    const i = h.indexOf(x), onceki = i > 0 ? h[i - 1] : null;
    const ms = new Date(x.zaman).getTime();
    const sg = (x.sezon != null) ? { s: x.sezon, g: x.gun } : _krSezonGun(ms);
    const kesin = x.tarih_kesin !== false;
    const tarih = kesin ? `<span>${sg.g}. gün</span> <span>${_krTarih(ms)}</span>` : `<span class="kr-soluk">tarih kaydı yok</span>`;
    const eski = x.eski_takim ? _krArma((x.eski_cc || '?') + '|' + x.eski_takim, 22)
      : `<span class="kr-arma kr-bos" style="width:22px;height:22px">${x.tur === 'baslangic' ? _krIk('basla') : '?'}</span>`;
    const yeni = x.yeni_takim ? _krArma((x.yeni_cc || '?') + '|' + x.yeni_takim, 22) : `<span class="kr-arma kr-bos" style="width:22px;height:22px">${_krIk('cikis')}</span>`;
    let baslik, alt, bedel;
    const imza = (Number(x.bedel_dia) || 0) > 0 ? `<i class="kr-imza">+${_krSayi(x.bedel_dia)} 💎</i>` : '';
    if (x.tur === 'transfer') {
      baslik = x.eski_takim
        ? `<span data-noi18n>${_krEsc(x.eski_takim)}</span> → <span data-noi18n>${_krEsc(x.yeni_takim || '')}</span>`
        : `<span data-noi18n>${_krEsc(x.yeni_takim || '')}</span>`;
      alt = x.eski_takim ? '<span>Transfer</span>' : '<span>Serbest oyuncu olarak katıldı</span>';
      bedel = ((Number(x.bedel_eur) || 0) > 0 ? `<div class="kr-tr-b">${_krEur(x.bedel_eur)}${imza}</div>` : `<div class="kr-tr-b bos">Bedelsiz${imza}</div>`);
    } else if (x.tur === 'baslangic') {
      baslik = `<span data-noi18n>${_krEsc(x.yeni_takim || '')}</span>`;
      alt = '<span>Kariyer başlangıcı</span>'; bedel = '';
    } else if (x.tur === 'ayrilma' || !x.yeni_takim) {
      baslik = `<span data-noi18n>${_krEsc(x.eski_takim || '')}</span> → <span>Serbest</span>`;
      alt = '<span>Takımdan ayrıldı</span>'; bedel = '';
    } else if (!x.eski_takim) {
      baslik = `<span data-noi18n>${_krEsc(x.yeni_takim)}</span>`;
      const serbestten = onceki && (onceki.tur === 'ayrilma' || !onceki.yeni_takim);
      if (serbestten) { alt = '<span>Serbest oyuncu olarak katıldı</span>'; bedel = `<div class="kr-tr-b bos">Bedelsiz</div>`; }
      else { alt = '<span>Katıldı</span>'; bedel = ''; }
    } else {
      // Kulüpten kulübe geçiş ama transfer kaydı yok: bedel bilinmiyor → yazılmaz
      baslik = `<span data-noi18n>${_krEsc(x.eski_takim)}</span> → <span data-noi18n>${_krEsc(x.yeni_takim)}</span>`;
      alt = '<span>Katıldı</span>'; bedel = '';
    }
    return `<div class="kr-tr"><div class="kr-tr-d"><b>${kesin ? 'S' + (sg.s || '?') : '—'}</b><div>${tarih}</div></div>`
      + `<div class="kr-tr-k">${eski}${_krIk('transfer', '', 'ok')}${yeni}<div><b>${baslik}</b><div class="alt">${alt}</div></div></div>${bedel}</div>`;
  }).join('');
  return _krBolum('transfer', '#ffd600', 'Transfer Geçmişi', '', satirlar);
}

function _krKupaBolum(liste) {
  const toplam = liste.reduce((t, x) => t + x.adet, 0);
  return _krBolum('kupa', '#ffd54f', 'Kupalar', toplam ? `${toplam} kupa` : '',
    toplam ? _kupaDolabiHtml(_kupaSirala(liste)) : '<div class="kr-bos-y">Henüz kupa kazanılmadı</div>', 'kr-kupa');
}

function _krCizVeri(kok, v, p) {
  const row = v.row;
  if (p === undefined && _krSon && _krSon.v === v) p = _krSon.p;
  const sezonlar = _krSezonlar(row);
  const acik = (_krSon && _krSon.id === row.id) ? _krSon.acik : {};
  _krSon = { id: row.id, acik, v, p };
  const kupa = _pmkKupaOnb[row.id];
  kok.innerHTML = `<div class="kr">`
    + _krKpi(row)
    + (kupa ? _krKupaBolum(kupa.v) : '<section class="kr-kupa" hidden></section>')
    + _krSon10(row)
    + _krDeger(row, v.hareket, p)
    + _krTablo(row, sezonlar, acik)
    + _krKulupKariyer(row, sezonlar, v.hareket)
    + _krTransferler(row, v.hareket, sezonlar)
    + `</div>`;
  if (!kupa || Date.now() - kupa.t >= 300000) _pmkKupalar(row.id).then(l => {
    const el = kok.querySelector('.kr-kupa');
    if (l && el && _krSon.id === row.id) el.outerHTML = _krKupaBolum(l);
  });
}

function _krSezonAc(s) {
  if (!_krSon) return;
  _krSon.acik[s] = !_krSon.acik[s];
  const kok = document.getElementById('krKok');
  if (kok && _krSon.v) _krCizVeri(kok, _krSon.v, _krSon.p);
}

var _krCizimNo = 0;
function _krCiz(p, benMi) {
  const kok = document.getElementById('krKok');
  if (!kok) return;
  const no = ++_krCizimNo;
  if (!p && !benMi) { kok.innerHTML = '<div class="kr-bos-y">Oyuncu bulunamadı</div>'; return; }
  const kim = _krKimlik(p || {}, benMi);
  const on = _krOnbellek[kim.anahtar];
  if (on) _krCizVeri(kok, on.v, p);                                        // anında göster, arkadan tazele
  else if (!(_krSon && _krSon.v && _krSon.v.anahtar === kim.anahtar && kok.querySelector('.kr')))
    kok.innerHTML = '<div class="kr-yuk"><span></span><em>Kariyer yükleniyor…</em></div>';
  if (on && Date.now() - on.t < 60000) return;
  _krYukle(p || {}, benMi).then(v => {
    if (no !== _krCizimNo) return;                 // bu arada başka oyuncu açıldı
    _krCizVeri(kok, v, p);
  }).catch(e => {
    if (no !== _krCizimNo) return;
    console.warn('[kariyer]', e);
    kok.innerHTML = '<div class="kr-bos-y">Kariyer verisi yüklenemedi</div>';
  });
}

function renderCareerTab() {
  // 595 — kendi profilin ve ziyaret ettiğin oyuncu AYNI çizimle, AYNI sunucu verisinden
  let vp = null;
  try { vp = (typeof _visitedPlayerData !== 'undefined' && _visitedPlayerData) ? _visitedPlayerData.player : null; } catch(e) {}
  if (vp) { _krCiz(vp, false); return; }
  let me = null;
  try { me = (typeof ROSTER_DATA !== 'undefined' && Array.isArray(ROSTER_DATA)) ? ROSTER_DATA.find(p => p.role === 'user') : null; } catch(e) {}
  _krCiz(me, true);
}

// ── Sezon kırılımı: her sezon için takım + gol/asist/maç/reyting (HER oyuncu için gerçek veri) ──
function _carSeasonRows(p) {
  const num = v => (typeof v === 'number' && isFinite(v)) ? v : 0;
  const sbc = (p && (p.statsByComp || p.stats_by_comp)) || {};
  const mr  = Array.isArray(p && (p.matchRatings || p.match_ratings)) ? (p.matchRatings || p.match_ratings) : [];
  // 🆕 535 — etkin sezon (39. günde yeni sezon) ki yeni sezon satırı da listelenebilsin
  let curS = 1; try { curS = ((typeof _etkinSezon==='function') ? _etkinSezon() : getSeasonInfo().season) || 1; } catch(e) {}

  const map = {};
  // stats_by_comp → sezon toplamları
  Object.keys(sbc).forEach(bucket => {
    const b = sbc[bucket];
    if (!b || typeof b !== 'object') return;
    Object.keys(b).forEach(sk => {
      const sn = parseInt(String(sk).replace(/^s/, ''), 10);
      if (!isFinite(sn)) return;
      if (!map[sn]) map[sn] = { season: sn, g: 0, a: 0, m: 0, rSum: 0, rCnt: 0, teams: {} };
      map[sn].g += num(b[sk].g); map[sn].a += num(b[sk].a); map[sn].m += num(b[sk].m);
    });
  });
  // match_ratings → reyting + o sezon oynadığı takım(lar)
  mr.forEach(x => {
    if (!x || typeof x.rating !== 'number') return;
    let sn = null;
    if (x.ts && typeof _seasonRangeMs === 'function') {
      for (let k = 1; k <= curS; k++) {
        const r = _seasonRangeMs(k);
        if (x.ts >= r[0] && x.ts < r[1]) { sn = k; break; }
      }
    }
    if (sn == null) sn = curS;
    if (!map[sn]) map[sn] = { season: sn, g: 0, a: 0, m: 0, rSum: 0, rCnt: 0, teams: {} };
    map[sn].rSum += x.rating; map[sn].rCnt++;
    const own = x.isHome ? x.home : x.away;
    if (own) map[sn].teams[own] = (map[sn].teams[own] || 0) + 1;
  });

  return Object.values(map).map(r => {
    const tl = Object.keys(r.teams).sort((a, b) => r.teams[b] - r.teams[a]);
    return {
      season: r.season, g: r.g, a: r.a, m: r.m,
      rating: r.rCnt > 0 ? Math.round((r.rSum / r.rCnt) * 10) / 10 : null,
      team: tl[0] || (p && (p.teamName || p.team_name)) || '—',
      teams: tl
    };
  }).sort((x, y) => y.season - x.season);   // en güncel sezon üstte
}

// Sezon listesi HTML — ilk 5 görünür, kalanı kaydırmayla
function _carSeasonListHtml(rows) {
  if (!rows.length) return '<div class="car-table-empty">Sezon verisi yok</div>';
  const row = r => `
    <div class="car-sr">
      <div class="car-sr-s">S${r.season}</div>
      <div class="car-sr-i">
        <div class="car-sr-t">${r.team}${r.teams && r.teams.length > 1 ? ' <span style="color:var(--text3);font-size:9.5px">+' + (r.teams.length - 1) + ' takım</span>' : ''}</div>
        <div class="car-sr-m">${r.m} maç</div>
      </div>
      <div class="car-sr-n"><b>${r.g}</b><span>gol</span></div>
      <div class="car-sr-n"><b>${r.a}</b><span>asist</span></div>
      <div class="car-sr-n rt"><b>${r.rating != null ? r.rating.toFixed(1) : '—'}</b><span>reyting</span></div>
    </div>`;
  const scroll = rows.length > 5 ? ' style="max-height:290px;overflow-y:auto;-webkit-overflow-scrolling:touch"' : '';
  return `<div class="car-season-list"${scroll}>${rows.map(row).join('')}</div>`
       + (rows.length > 5 ? '<div style="text-align:center;font-size:9.5px;color:var(--text3);padding:5px">↕ daha eski sezonlar için kaydır</div>' : '');
}

// 🆕 Piyasa değeri ÇİZGİ GRAFİĞİ (transfermarkt tarzı, SVG)
function _carMvChartHtml(points) {
  const pts = (points || []).filter(p => p && isFinite(p.value));
  if (pts.length < 2) return '<div class="car-mv-empty">Grafik için yeterli veri yok</div>';
  const W = 320, H = 120, PAD_L = 6, PAD_R = 6, PAD_T = 10, PAD_B = 18;
  const vals = pts.map(p => p.value);
  const maxV = Math.max(...vals), minV = Math.min(...vals);
  const span = (maxV - minV) || Math.max(1, maxV * 0.1);
  const x = i => PAD_L + (i / (pts.length - 1)) * (W - PAD_L - PAD_R);
  const y = v => PAD_T + (1 - (v - minV) / span) * (H - PAD_T - PAD_B);
  const line = pts.map((p, i) => `${i === 0 ? 'M' : 'L'}${x(i).toFixed(1)},${y(p.value).toFixed(1)}`).join(' ');
  const area = line + ` L${x(pts.length - 1).toFixed(1)},${(H - PAD_B).toFixed(1)} L${x(0).toFixed(1)},${(H - PAD_B).toFixed(1)} Z`;
  const first = pts[0].value, last = pts[pts.length - 1].value;
  const up = last >= first;
  const col = up ? 'var(--accent,#00e676)' : '#ff5c7a';
  const fmt = v => (typeof _carFmtEUR === 'function') ? _carFmtEUR(v) : (v.toLocaleString('tr') + ' €');
  const dLbl = d => { const dt = new Date(d); return isNaN(dt.getTime()) ? '' : `${dt.getDate()}/${dt.getMonth() + 1}`; };
  const dots = pts.map((p, i) => `<circle cx="${x(i).toFixed(1)}" cy="${y(p.value).toFixed(1)}" r="${i === pts.length - 1 ? 3.2 : 1.8}" fill="${col}"><title>${dLbl(p.day)} · ${fmt(p.value)}</title></circle>`).join('');
  const pct = first > 0 ? Math.round(((last - first) / first) * 100) : 0;
  return `
    <div class="car-mvc">
      <div class="car-mvc-head">
        <div><div class="car-mvc-val">${fmt(last)}</div><div class="car-mvc-sub">güncel piyasa değeri</div></div>
        <div class="car-mvc-chg" style="color:${col}">${up ? '▲' : '▼'} ${pct > 0 ? '+' : ''}${pct}%</div>
      </div>
      <svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" style="width:100%;height:120px;display:block">
        <defs><linearGradient id="mvg" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="${col}" stop-opacity=".28"/><stop offset="100%" stop-color="${col}" stop-opacity="0"/>
        </linearGradient></defs>
        <path d="${area}" fill="url(#mvg)"/>
        <path d="${line}" fill="none" stroke="${col}" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>
        ${dots}
      </svg>
      <div class="car-mvc-x"><span>${dLbl(pts[0].day)}</span><span>${dLbl(pts[pts.length - 1].day)}</span></div>
    </div>`;
}

// 🆕 ZİYARETÇİ KARİYER GÖRÜNÜMÜ — başka bir oyuncunun profilinde "Kariyer" sekmesi.
//   Eskiden renderCareerPage() çağrılıyordu ve o hep KENDİ verini gösteriyordu.
//   Burada ziyaret edilen oyuncunun DB alanları kullanılır (goals_total, match_ratings, stats_by_comp).
function renderCareerPageVisitor(p) {
  if (!p) return;
  const _num = (v) => (typeof v === 'number' && isFinite(v)) ? v : 0;
  const mr = Array.isArray(p.matchRatings) ? p.matchRatings
           : (Array.isArray(p.match_ratings) ? p.match_ratings : []);
  const sbc = (p.statsByComp && typeof p.statsByComp === 'object') ? p.statsByComp
            : ((p.stats_by_comp && typeof p.stats_by_comp === 'object') ? p.stats_by_comp : {});
  const totM = _num(p.matchesPlayed != null ? p.matchesPlayed : p.matches_played);
  const totG = _num(p.goalsTotal   != null ? p.goalsTotal   : p.goals_total);
  const totA = _num(p.assistsTotal != null ? p.assistsTotal : p.assists_total);
  const cnt = (arr, f) => arr.reduce((s,x)=> s + (f(x)||0), 0);
  const W = mr.filter(m=>m && m.result==='W').length;
  const D = mr.filter(m=>m && m.result==='D').length;
  const L = mr.filter(m=>m && m.result==='L').length;
  const YC = cnt(mr, m=>m.yellows); const RC = cnt(mr, m=>m.reds);
  const cell = (v,l,c) => `<div class="car-stat-card"><div class="car-stat-value${c?' '+c:''}">${v}</div><div class="car-stat-label">${l}</div></div>`;

  // Kariyer özeti
  const g1 = document.getElementById('carStatsGrid');
  if (g1) g1.innerHTML = cell(totM,'Maç') + cell(totG,'Gol','green') + cell(totA,'Asist','acc')
        + cell(W,'Galibiyet','green') + cell(D,'Beraberlik') + cell(L,'Mağlubiyet','red');

  // Bu sezon (stats_by_comp + sezon içi match_ratings)
  // 🆕 535 — sezon 39. günde döndüğü için "bu sezon" da etkin sezonu gösterir
  let sN = 1; try { sN = ((typeof _etkinSezon==='function') ? _etkinSezon() : getSeasonInfo().season) || 1; } catch(e) {}
  const rng = (typeof _seasonRangeMs==='function') ? _seasonRangeMs(sN) : [0, Infinity];
  const inSeason = mr.filter(m => m && m.ts && m.ts >= rng[0] && m.ts < rng[1]);
  let sg=0, sa=0, sm=0;
  Object.keys(sbc).forEach(function(b){
    const v = sbc[b] && sbc[b]['s'+sN];
    if (v) { sg += _num(v.g); sa += _num(v.a); sm += _num(v.m); }
  });
  const g2 = document.getElementById('carSeasonStatsGrid');
  if (g2) g2.innerHTML = cell(sm,'Maç') + cell(sg,'Gol','green') + cell(sa,'Asist','acc')
        + cell(inSeason.filter(m=>m.result==='W').length,'Galibiyet')
        + cell(cnt(inSeason,m=>m.yellows),'Sarı Kart')
        + cell(cnt(inSeason,m=>m.reds),'Kırmızı','red');

  // Yarışmalara göre (tüm zamanlar)
  const g3 = document.getElementById('carCompGrid');
  if (g3) {
    const COMPS = [
      { key:'lig', icon:'🏟️', name:'Lig' },
      { key:'chm', icon:'🏆', name:'Şampiyonlar Ligi' },
      { key:'eli', icon:'🥈', name:'Elit Lig' },
      { key:'con', icon:'🥉', name:'Konferans Ligi' },
      { key:'enc', icon:'🌍', name:'EURO Nations Cup' },
    ];
    let any = false;
    g3.innerHTML = COMPS.map(function(c){
      const t = (typeof statsByCompGetTotal==='function') ? statsByCompGetTotal(sbc, c.key) : {g:0,a:0,m:0};
      if ((t.m||0) > 0) any = true;
      return `<div class="car-comp-row${(t.m||0)>0?'':' is-empty'}" style="${(t.m||0)>0?'':'opacity:.45'}">
        <div class="car-comp-ic">${c.icon}</div>
        <div class="car-comp-name">${c.name}</div>
        <div class="car-comp-nums">
          <span class="car-comp-num"><b>${t.m||0}</b><span class="car-comp-num-lbl">Maç</span></span>
          <span class="car-comp-num"><b>${t.g||0}</b><span class="car-comp-num-lbl">Gol</span></span>
          <span class="car-comp-num"><b>${t.a||0}</b><span class="car-comp-num-lbl">Asist</span></span>
        </div></div>`;
    }).join('');
    if (!any) g3.innerHTML = '<div class="car-table-empty">Henüz yarışma verisi yok</div>';
  }

  // Form (son 5)
  const fe = document.getElementById('carForm');
  if (fe) {
    if (!mr.length) fe.innerHTML = '<div class="car-form-empty">Henüz maç oynanmadı</div>';
    else {
      const last5 = mr.slice(-5);
      const cells = last5.map(function(m){
        const cls = String(m.result||'').toLowerCase();
        const _fk2 = window._ligKolon(); const lbl = m.result==='W' ? _fk2.g : (m.result==='D' ? _fk2.b : _fk2.m);
        return `<div class="car-form-cell ${cls}">${lbl}</div>`;
      }).join('');
      fe.innerHTML = Array(Math.max(0,5-last5.length)).fill('<div class="car-form-cell q">?</div>').join('') + cells;
    }
  }

  // 🆕 SEZON KIRILIMI (takım geçmişi + başarılar) — gerçek veriden
  const _rows = _carSeasonRows(p);
  const th = document.getElementById('carTeamHistory');
  if (th) { th.innerHTML = _carSeasonListHtml(_rows); _ptrFillInto('carTeamHistory', p, false); }
  const tr = document.getElementById('carTrophies');
  if (tr) tr.innerHTML = _carSeasonListHtml(_rows);
  // Piyasa değeri: başka oyuncunun geçmişi saklanmıyor → güncel değeri göster
  const mv = document.getElementById('carMvChart');
  if (mv) {
    let mvNow = 0;
    try { mvNow = (typeof getPlayerMarketValue === 'function') ? getPlayerMarketValue(p) : 0; } catch(e) {}
    mv.innerHTML = mvNow
      ? `<div class="car-mvc"><div class="car-mvc-head"><div><div class="car-mvc-val">${(typeof formatMV==='function')?formatMV(mvNow):mvNow.toLocaleString('tr')+' €'}</div><div class="car-mvc-sub">güncel piyasa değeri · geçmiş grafiği yalnızca kendi profilinde</div></div></div></div>`
      : '<div class="car-mv-empty">Piyasa değeri verisi yok</div>';
  }

  // Son maçlar
  const me = document.getElementById('carMatches');
  if (me) {
    if (!mr.length) me.innerHTML = '<div class="car-table-empty">Henüz maç oynanmadı</div>';
    else {
      me.innerHTML = mr.slice().reverse().slice(0,10).map(function(m){
        const cls = String(m.result||'').toLowerCase();
        const _fk2 = window._ligKolon(); const lbl = m.result==='W' ? _fk2.g : (m.result==='D' ? _fk2.b : _fk2.m);
        const own = m.isHome ? m.home : m.away;
        const opp = m.opp || (m.isHome ? m.away : m.home) || '—';
        const score = m.isHome ? `${m.hs}-${m.as}` : `${m.as}-${m.hs}`;
        const st = [];
        if (m.goals)   st.push(`<span class="car-match-stat-g">⚽${m.goals}</span>`);
        if (m.assists) st.push(`<span class="car-match-stat-a">🅰️${m.assists}</span>`);
        if (m.yellows) st.push(`<span class="car-match-stat-y">🟨${m.yellows}</span>`);
        if (m.reds)    st.push(`<span class="car-match-stat-r">🟥${m.reds}</span>`);
        return `<div class="car-match-row">
            <div class="car-match-result ${cls}">${lbl}</div>
            <div class="car-match-teams">${own||'—'} <span style="color:var(--text3)">vs</span> ${opp}</div>
            <div class="car-match-score">${score}</div>
            <div class="car-match-stats">${st.join('')}</div>
          </div>`;
      }).join('');
    }
  }
}

function plTab(name, btn) {
  document.querySelectorAll('.pl-tab').forEach(t=>t.classList.remove('active'));
  if(btn) btn.classList.add('active');
  document.getElementById('pl-skills').style.display    = name==='skills'?'block':'none';
  document.getElementById('pl-equipment').style.display = name==='equipment'?'block':'none';
  document.getElementById('pl-history').style.display   = name==='history'?'block':'none';
  if(name==='equipment') renderEquipment();
  if(name==='history') {
    // 🆕 Ziyaretçi modunda ziyaret edilen oyuncunun kariyeri gösterilir (kendi verin değil)
    if (typeof renderCareerTab === 'function') renderCareerTab();
  }
}

function renderPlayerHistory() {
  const el = document.getElementById('plCareerContent');
  if(!el) return;

  // 🆕 GERÇEK VERİLER: maç logu + takım kariyeri + sezon
  let matchLog = [];
  let careerHist = [];
  let curSeason = 1;
  try { matchLog   = getUserMatchLog(); } catch(e) {}
  try { careerHist = getCareerHistory(); } catch(e) {}
  try { if (typeof getSeasonInfo === 'function') curSeason = getSeasonInfo().season || 1; } catch(e) {}

  // Toplamlar
  const totMac = matchLog.length;
  const totGol = matchLog.reduce((s,m) => s + (m.goals || 0), 0);
  const totAst = matchLog.reduce((s,m) => s + (m.assists || 0), 0);
  const ratings = matchLog.filter(m => typeof m.rating === 'number' && m.rating > 0).map(m => m.rating);
  const totOrt = ratings.length ? (ratings.reduce((s,r) => s+r, 0) / ratings.length) : 0;

  // Her takım dönemi için istatistik biriktir (career_history listesi)
  // Eğer career_history boşsa ve mevcut takım varsa onu sentez et
  let stints = [];
  if (careerHist.length > 0) {
    careerHist.forEach((h, idx) => {
      const startDate = h.joinDate ? new Date(h.joinDate) : null;
      const endDate = h.leaveDate ? new Date(h.leaveDate) : null;
      // Bu takımdaki maçlar: tarih ve takım ismi eşleşmesi
      const stintMatches = matchLog.filter(m => {
        if (!m.date) return false;
        const md = new Date(m.date);
        if (startDate && md < startDate) return false;
        if (endDate && md > endDate) return false;
        // Takım eşleşmesi: home veya away olarak h.teamName
        return (m.home === h.teamName || m.away === h.teamName);
      });
      const sg = stintMatches.reduce((s,m)=>s+(m.goals||0),0);
      const sa = stintMatches.reduce((s,m)=>s+(m.assists||0),0);
      const sm = stintMatches.length;
      const rArr = stintMatches.filter(m => typeof m.rating === 'number' && m.rating > 0).map(m => m.rating);
      const so = rArr.length ? (rArr.reduce((s,r)=>s+r,0) / rArr.length) : 0;

      // Takım kısaltması (ilk 3 harf)
      const short = (h.teamName || '?').slice(0,3).toUpperCase();
      const cc = h.countryCode || '';
      const country = (true && cc) ? _cftGetCountry(cc) : null;
      const flag = country ? country.flag : '';

      stints.push({
        teamName: h.teamName || '—',
        leagueName: h.leagueName || '',
        flag,
        short,
        mac: sm, gol: sg, ast: sa, ort: so,
        startDate: startDate,
        endDate: endDate,
        ongoing: !endDate,
        idx
      });
    });
  } else if (typeof _userTeam !== 'undefined' && _userTeam) {
    // career_history boş ama kullanıcı bir takımda — sentez
    const cc = _userTeam.countryCode || '';
    const country = (true && cc) ? _cftGetCountry(cc) : null;
    const flag = country ? country.flag : '';
    stints.push({
      teamName: _userTeam.teamName || '—',
      leagueName: '',
      flag,
      short: (_userTeam.teamName || '?').slice(0,3).toUpperCase(),
      mac: totMac, gol: totGol, ast: totAst, ort: totOrt,
      startDate: null, endDate: null, ongoing: true, idx: 0
    });
  }
  // En yeni dönem üstte
  stints.reverse();

  // ─── HTML ───
  let html = `<div style="padding:10px 12px 80px">

    <div class="cv-summary">
      <div class="cv-sum-stat"><div class="cv-sum-val">${totMac}</div><div class="cv-sum-lbl">Maç</div></div>
      <div class="cv-sum-sep"></div>
      <div class="cv-sum-stat"><div class="cv-sum-val" style="color:var(--accent)">${totGol}</div><div class="cv-sum-lbl">Gol</div></div>
      <div class="cv-sum-sep"></div>
      <div class="cv-sum-stat"><div class="cv-sum-val" style="color:var(--accent2)">${totAst}</div><div class="cv-sum-lbl">Asist</div></div>
      <div class="cv-sum-sep"></div>
      <div class="cv-sum-stat"><div class="cv-sum-val" style="color:var(--gold)">${curSeason}</div><div class="cv-sum-lbl">Sezon</div></div>
    </div>`;

  if (stints.length === 0) {
    html += `<div style="padding:30px 16px;text-align:center;color:var(--text3);font-size:12px;background:rgba(255,255,255,.02);border:1px dashed var(--border);border-radius:10px;margin-top:12px">
      <div style="font-size:32px;margin-bottom:8px">⚽</div>
      <div style="font-weight:700;color:var(--text2);margin-bottom:4px">Henüz kariyer geçmişi yok</div>
      <div>Bir takıma katılıp maç oynadığında buraya yansıyacak.</div>
    </div>`;
  } else {
    html += stints.map(s => {
      const ortCol = s.ort >= 7.5 ? 'var(--accent)' : s.ort >= 6.5 ? 'var(--gold)' : (s.ort > 0 ? '#ef5350' : 'var(--text3)');
      const ortText = s.ort > 0 ? s.ort.toFixed(1) : '—';
      const fmtDate = (d) => d ? d.toLocaleDateString('tr', {month:'short', year:'numeric'}) : '';
      const period = s.startDate ? (fmtDate(s.startDate) + (s.endDate ? ' - ' + fmtDate(s.endDate) : ' → şimdi')) : 'Aktif';
      const bg = s.ongoing ? 'rgba(0,230,118,.2)' : 'rgba(255,255,255,.05)';
      const tc = s.ongoing ? '#00e676' : 'var(--text2)';
      return `<div class="cv-row">
        <div class="cv-left">
          ${inlineBadge({tag:'div', cls:'cv-logo', name:s.teamName, bg, tc, short:s.short})}
        </div>
        <div class="cv-mid">
          <div class="cv-club">${s.flag} ${s.teamName}${s.ongoing?'<span class="cv-live"> ●</span>':''}</div>
          <div class="cv-meta">${period}${s.leagueName ? ' · ' + s.leagueName : ''}</div>
        </div>
        <div class="cv-right">
          <div class="cv-nums">
            <span class="cv-g" title="Gol">${s.gol}G</span>
            <span class="cv-a" title="Asist">${s.ast}A</span>
            <span class="cv-m" title="Maç">${s.mac}M</span>
          </div>
          <div class="cv-ort" style="color:${ortCol}">${ortText}</div>
        </div>
      </div>`;
    }).join('');
  }

  html += `</div>`;
  el.innerHTML = html;
}

// ══ MEVKİ DEĞİŞTİR ══
let _selectedNewPos = null;

const _MK_RENK = { GK:'#ffd166', DEF:'#66b3ff', MID:'#46d17a', FWD:'#ff8c66' };
const _MK_NOKTA = { GK:[12,29], RB:[19.4,23.6], CB:[12,24.4], LB:[4.6,23.6], DM:[12,20], CM:[12,16.5], RM:[19.4,14], LM:[4.6,14], AM:[12,11.5], RF:[18.6,6.6], LF:[5.4,6.6], ST:[12,4.6] };
let _posCurGrp = null;
// Mini saha: mevkinin sahadaki yeri (hücum yukarı)
function _mkSaha(c, r) {
  const n = _MK_NOKTA[c] || [12, 16.5];
  return `<svg class="kmd-ms" viewBox="0 0 24 33"><rect class="z" x="1" y="1" width="22" height="31" rx="3"/><line x1="1" y1="16.5" x2="23" y2="16.5"/><circle cx="12" cy="16.5" r="3.4"/><rect x="7" y="1" width="10" height="4.6"/><rect x="7" y="27.4" width="10" height="4.6"/><circle class="n" cx="${n[0]}" cy="${n[1]}" r="2.7" style="fill:${r}"/></svg>`;
}
function _posUcretYaz(bedava) {
  const el = document.getElementById('posModalUcret');
  el.classList.toggle('bedava', bedava);
  el.innerHTML = bedava ? 'Ücretsiz' : '<svg class="kmd-e"><use href="#ic-diamond"/></svg>150 Diamond';
}

function openChangePosModal() {
  const user   = authUser || {};
  const curGrp = user.position || 'MID';
  const curSub = user.subPos || (typeof subPosOf==='function' ? subPosOf({pos:curGrp, pos_group:curGrp, sub_pos:user.subPos}) : '');
  _selectedNewPos = null;

  const _curLbl = (typeof SUBPOS_LABEL!=='undefined' && SUBPOS_LABEL[curSub]) ? SUBPOS_LABEL[curSub]
                : ((POS_CONFIG[curGrp]||POS_CONFIG.MID).label);
  document.getElementById('posModalCurrent').textContent = _curLbl;
  const _kod = document.getElementById('posModalKod');
  _kod.textContent = curSub; _kod.style.setProperty('--r', _MK_RENK[curGrp] || '#46d17a');
  document.getElementById('posModalConfirm').disabled    = true;
  _posCurGrp = curGrp;
  _posUcretYaz(false);

  const grpNames = { GK:'Kaleci', DEF:'Defans', MID:'Orta Saha', FWD:'Forvet' };
  const grid = document.getElementById('posModalGrid');
  let html = '';
  ['GK','DEF','MID','FWD'].forEach(g => {
    const subs = (typeof SUB_POS!=='undefined' && SUB_POS[g]) ? SUB_POS[g] : [];
    if (!subs.length) return;
    const r = _MK_RENK[g];
    html += `<div class="kmd-grp" style="--r:${r}"><div class="kmd-grp-bas"><i></i><b>${grpNames[g]}</b>`
      + (g === curGrp ? '<em class="bedava">Ücretsiz</em>' : '<em class="ucretli"><svg class="kmd-e"><use href="#ic-diamond"/></svg>150</em>') + '</div><div class="kmd-mk-izg">';
    html += subs.map(sp => {
      const isCur = sp.c === curSub;
      return `<div class="kmd-mk${isCur ? ' mevcut' : ''}" onclick="selectNewPos('${sp.c}', this)">${_mkSaha(sp.c, r)}`
        + `<span class="kmd-mk-t"><b data-noi18n>${sp.c}</b><i>${sp.t}</i></span>${isCur ? '<span class="kmd-mv">Mevcut</span>' : ''}</div>`;
    }).join('') + '</div></div>';
  });
  grid.innerHTML = html;

  document.getElementById('posModal').classList.add('open');
}

function selectNewPos(sub, el) {
  _selectedNewPos = sub;
  document.querySelectorAll('#posModalGrid .kmd-mk').forEach(c => c.classList.remove('secili'));
  el.classList.add('secili');
  document.getElementById('posModalConfirm').disabled = false;
  _posUcretYaz(SUBPOS_GROUP[sub] === _posCurGrp);
}

function closePosModal() {
  document.getElementById('posModal').classList.remove('open');
  _selectedNewPos = null;
}

async function confirmPosChange() {
  if(!_selectedNewPos) return;
  const user  = authUser || {};
  const newSub   = _selectedNewPos;
  const newGroup = (typeof SUBPOS_GROUP!=='undefined' && SUBPOS_GROUP[newSub]) ? SUBPOS_GROUP[newSub] : newSub;

  // Eski grubu FRESH oku (stale cache → yanlış skill silme bug'ı önlenir)
  let oldGroup = user.position || 'MID';
  let oldSub   = user.subPos || '';
  try {
    if (window.sb && user.id) {
      const { data: _pr } = await window.sb.from('players').select('pos, pos_group, sub_pos').eq('user_id', user.id).maybeSingle();
      if (_pr) { oldGroup = _pr.pos_group || _pr.pos || oldGroup; user.position = oldGroup; }
    }
  } catch(e) { console.warn('[posChange] fresh oldGroup okunamadı:', e); }

  if (newSub === oldSub && newGroup === oldGroup) { closePosModal(); return; }

  const groupChanged = (newGroup !== oldGroup);

  // 🆕 2026-08-18 · MEVKİ DEĞİŞİMİ SUNUCUDA
  //   Eskiden 500 elmas gerçekten düşüyordu ama `pos`/`pos_group` kolonları
  //   players tetikleyicisinin beyaz listesinde olmadığı için yazılmıyordu:
  //   para gidiyor, mevki eski kalıyor, üstelik yetenekler yeni mevkiye göre
  //   kaydedildiği için mevki-yetenek uyumsuzluğu oluşuyordu.
  //   Artık ödeme + yazma tek yerde; yazılamazsa para iade ediliyor.
  try {
    const _res = await edgeCall('change_position', { sub: newSub });
    const d = _res && _res.data;
    if (!_res.ok || !d || d.error) {
      closePosModal();
      const msg = {
        yetersiz_bakiye: 'Yetersiz Diamond! Mevki değişimi 150 💎.',
        gecersiz_mevki: 'Geçersiz mevki.',
        oyuncu_bulunamadi: 'Oyuncu kaydı bulunamadı.',
        yazilamadi_para_iade: 'Kaydedilemedi, elmasların iade edildi.'
      }[d && d.error] || ((typeof _mevkiDoluMetin === 'function') && _mevkiDoluMetin(d && d.error, d && d.grup)) || 'Mevki değiştirilemedi.';
      showPosToast('❌ ' + msg, '#ef5350');
      return;
    }
    // Cüzdanı sunucudan tazele (yerel tahmin yok)
    try { if (typeof wlLoadFromServer === 'function') await wlLoadFromServer(); } catch(e) {}
  } catch(e) {
    closePosModal();
    showPosToast('❌ Sunucuya ulaşılamadı.', '#ef5350');
    return;
  }

  // 🆕 Yetenek seti taşımasını da SUNUCU yaptı (change_position içinde).
  //   İstemcinin `saveSkillLevels` ile yazması tetikleyici tarafından geri
  //   alınıyordu. Burada sadece sunucudaki güncel seti geri okuyoruz.
  if (groupChanged) {
    try {
      const { data: _up } = await window.sb.from('user_player')
        .select('skills').eq('user_id', authUser.id).maybeSingle();
      if (_up && _up.skills && typeof _up.skills === 'object') {
        let _dolu = 0;
        for (const p of ['GK','DEF','MID','FWD'])
          if (_up.skills[p] && Object.keys(_up.skills[p]).length > 0) _dolu++;
        if (_dolu === 4) { _skillsCache = _up.skills; window._skillsLoadedOk = true; }
      }
    } catch(e) { console.warn('[posChange] yetenek tazeleme hatası:', e); }
  }

  user.position = newGroup;
  user.subPos   = newSub;
  authUser      = user;

  // 🆕 Bellekteki kullanıcı oyuncusunu da güncelle → kadro/saha/profil ANINDA doğru
  //   pozisyon/alt-mevkiyi gösterir (sayfa yenilemeyi beklemeden). players tablosu zaten yazıldı.
  try {
    if (typeof ROSTER_DATA !== 'undefined' && Array.isArray(ROSTER_DATA)) {
      const _up = ROSTER_DATA.find(p => p && p.role === 'user');
      if (_up) { _up.pos = newGroup; _up.posGroup = newGroup; _up.subPos = newSub; }
    }
  } catch(e) {}

  try { kadroYayin('oyuncu', ((typeof ROSTER_DATA !== 'undefined' && ROSTER_DATA.find(p => p && p.role === 'user')) || {}).id); } catch(e) {}   // 768 — mevki herkese

  // 🆕 players yazımı KALDIRILDI — yukarıdaki change_position aksiyonu
  //   pos, pos_group ve sub_pos'u service_role ile zaten yazdı. Buradaki
  //   istemci yazımı tetikleyici tarafından sessizce geri alınıyordu.

  // 🆕 Mevki/yetenek değişti → takım gücünü ANINDA tazele (kullanıcı takımdaysa).
  try{
    if(typeof _userTeam!=='undefined' && _userTeam && _userTeam.teamName){
      _recomputeTeamOvrServer(_userTeam.countryCode, _userTeam.teamName);
    }
  }catch(e){}

  closePosModal();

  const subLbl = (typeof SUBPOS_LABEL!=='undefined' && SUBPOS_LABEL[newSub]) ? SUBPOS_LABEL[newSub] : newSub;
  if (groupChanged) {
    showPosToast(`✅ Mevki ${subLbl}'e değiştirildi!\nTüm yeteneklerin olduğu gibi korundu.`, 'var(--accent)');
  } else {
    showPosToast(`✅ Alt mevki ${subLbl} olarak güncellendi.`, 'var(--accent)');
  }

  setTimeout(renderPlayerPage, 300);
}

function showPosToast(msg, color) {
  const t = document.createElement('div');
  t.style.cssText = `position:fixed;bottom:90px;left:50%;transform:translateX(-50%);
    background:${color};color:${color==='var(--accent)'?'var(--bg)':'#fff'};
    padding:10px 18px;border-radius:12px;font-size:11px;font-weight:700;
    z-index:9999;font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;letter-spacing:.3px;
    text-align:center;line-height:1.5;max-width:280px;white-space:pre-line;
    box-shadow:0 4px 20px rgba(0,0,0,.5)`;
  t.textContent = msg;
  document.body.appendChild(t);
  setTimeout(() => t.remove(), 3500);
}


