// Nadir renkleri
// ═══ 🆕 554 — ITEM GÖRSELLERİ ═══
//   Görseller sitede item-img/<id>.webp olarak durur (index.html'in yanında).
//   Görseli olmayan ya da yüklenemeyen item için eski emoji gösterilir.
const ITEM_GORSEL_IDS = new Set('atk1 atk2 atk3 atk4 atk5 atk6 atk7 atk8 def1 def2 def3 def4 def5 def6 def7 def8 gk1 gk2 gk3 gk4 gk5 gk6 gk7 men1 men2 men3 men4 men5 men6 men7 men8 pm1 pm2 pm3 pm4 pm5 pm6 pm7 pm8'.split(' '));
const ITEM_GORSEL_SURUM = '554';
function itemGorselUrl(id) {
  id = String(id || '');
  return ITEM_GORSEL_IDS.has(id) ? ('item-img/' + id + '.webp?v=' + ITEM_GORSEL_SURUM) : '';
}
function itemGorselHtml(item) {
  const u = itemGorselUrl(item && item.id);
  const emo = String((item && item.icon) || '🎯').replace(/[<>"&']/g, '');
  if (!u) return emo;
  return '<img class="itm-gorsel" src="' + u + '" alt="" loading="lazy" decoding="async" draggable="false" data-emo="' + emo + '" onerror="_itemGorselHata(this)">';
}
function _itemGorselHata(img) {
  try {
    const kutu = img.parentNode;
    const s = document.createElement('span');
    s.textContent = img.getAttribute('data-emo') || '🎯';
    if (kutu && kutu.classList && kutu.classList.contains('shc-img')) s.className = 'shc-emo';
    img.replaceWith(s);
    if (kutu && kutu.classList) kutu.classList.remove('itm-gorselli', 'slot-img', 'ward-img');
  } catch (e) {}
}
window._itemGorselHata = _itemGorselHata;
// textContent yerine: kutuya görsel (yoksa emoji) yaz
function itemGorselYaz(el, item) {
  if (!el) return;
  if (itemGorselUrl(item && item.id)) { el.innerHTML = itemGorselHtml(item); el.classList.add('itm-gorselli'); }
  else { el.textContent = (item && item.icon) || '🎯'; el.classList.remove('itm-gorselli'); }
}

