// ── Item yerleştirme ──
// 🆕 Slot tıklama hint toast (drag-drop'a yönlendir)
let _eqSlotHintCooldown = 0;
function _eqSlotHint(kind) {
  if (_eqIsVisitor()) return;
  // Spam koruması: 2 saniyede bir
  const now = Date.now();
  if (now - _eqSlotHintCooldown < 2000) return;
  _eqSlotHintCooldown = now;
  const msg = (kind === 'filled')
    ? '💡 Item\'i çıkarmak için dolaba sürükle'
    : '💡 Dolaptan item sürükleyerek bu slota bırak';
  if (typeof showEqToast === 'function') {
    showEqToast(msg, 'rgba(95,184,255,.9)');
  }
}

// 🚫 Eski item seç modalı kaldırıldı (drag-drop sistemi var)
