async function _marketListingsLoadFromServer() {
  if (!window.sb) return [];
  try {
    const { data, error } = await window.sb.from('item_listings')
      .select('*')
      .order('created_at', { ascending: false })
      .limit(500);
    if (error) { console.warn('[market] load hata:', error); return []; }
    return (data || []).map(r => Object.assign({
      id: r.id,
      seller: r.seller_name,
      sellerUserId: r.seller_user_id,
      price: r.price,
      listed: r.listed !== false,
      createdAt: new Date(r.created_at).getTime()
    }, r.data || {}));
  } catch(e) { console.warn('[market] load exception:', e); return []; }
}

function initMarketListings() {
  if (_marketListingsYuklendi || _marketListingsLoading) return;
  // Supabase'ten yükle (async — sayfa açıldığında render edilir)
  _marketListingsLoading = _marketListingsLoadFromServer().then(arr => {
    _marketListings = arr;
    _marketListingsLoading = null;
    _marketListingsYuklendi = true;
    try {
      if (typeof renderMarket === 'function' && document.getElementById('shop-market') && document.getElementById('shop-market').style.display !== 'none') {
        renderMarket();
      }
    } catch(e) {}
  });
}

