  if (etArr) {
    const a0 = Number(etArr[0]) || 0, a1 = Number(etArr[1]) || 0;
    if (belEv === H) { etH = a0; etA = a1; } else { etH = a1; etA = a0; }
  }
  const skorH = sH == null ? '–' : (sH + (etH || 0));
  const skorA = sA == null ? '–' : (sA + (etA || 0));
