  if ((!pens || pens.homePens == null) && Array.isArray(st.pens) && st.pens.length === 2) {
    const p0 = Number(st.pens[0]) || 0, p1 = Number(st.pens[1]) || 0;   // belirleyici maçın ev/dep
    pens = (belEv === H) ? { homePens: p0, awayPens: p1 } : { homePens: p1, awayPens: p0 };
  }
