    const nasil = penVar ? 'Penaltılarla ' : (uzGol ? 'Uzatmada ' : '');
    const top = d.twoLeg ? `<span class="tmd-top">Toplam ${sH}-${sA}${(etArr && (etH + etA) > 0) ? ' (uzt. ' + (sH + etH) + '-' + (sA + etA) + ')' : ''}</span> · ` : '';
