      [].concat(lu.players || [], lu.bench || []).forEach(p => { if (p && p.name && typeof p.matchRating === 'number') m[p.name] = p.matchRating; });
      if (lu.ratings) for (const k in lu.ratings) if (typeof lu.ratings[k] === 'number') m[k] = lu.ratings[k];
