function _pdTakim(b) { if (!b || !b.takim) return null; try { return _cftFindTeam(b.cc, b.takim); } catch (e) { return null; } }
function _pdLogo(b) { const t = _pdTakim(b); if (!t) return b && b.takim ? null : _pdYol('csc-logo.webp'); try { return teamLogoUrl(t); } catch (e) { return null; } }
