// ══ TRANSFER SİSTEMİ — Oyuncu transfer pazarı ══
// 🆕 Supabase player_transfer_listings tablosu
let _tfListCache = null;
let _tfListLoading = null;

async function _tfListLoadFromServer() {
  if (!window.sb) return [];
  try {
    const { data, error } = await window.sb.from('player_transfer_listings')
      .select('*')
      .order('created_at', { ascending: false })
      .limit(500);
    if (error) { console.warn('[tf_list] load hata:', error); return []; }
    return (data || []).map(r => Object.assign({
      id: r.id,
      sellerUserId: r.seller_user_id,
      createdAt: new Date(r.created_at).getTime()
    }, r.data || {}));
  } catch(e) { return []; }
}

// Transfer listesi: Supabase
function getTfList() {
  if (_tfListCache === null) {
    if (!_tfListLoading) {
      _tfListLoading = _tfListLoadFromServer().then(arr => {
        _tfListCache = arr;
        _tfListLoading = null;
        try {
          if (typeof tfRender === 'function' && document.getElementById('page-transfers') && document.getElementById('page-transfers').classList.contains('active')) {
            tfRender();
          }
        } catch(e) {}
      });
    }
    return [];
  }
  return _tfListCache;
}

async function saveTfList(list) {
  _tfListCache = Array.isArray(list) ? list : [];
  // Supabase: full rewrite yerine tek tek upsert (büyük listede daha verimli)
  // Burada basit yaklaşım: tüm listeyi senkron tutmak yerine, üst seviyede tek tek
  // add/update/remove fonksiyonları kullanmak daha mantıklı.
  // Geçici çözüm: cache'i güncel tutuyoruz, gerçek persist için tfAddItem/tfRemoveItem fonksiyonları gerek.
  // Ancak mevcut kod direkt saveTfList kullanıyor, biz de batch upsert yapalım:
  if (window.sb && authUser && authUser.id) {
    try {
      const userListings = _tfListCache.filter(l => l && (l.sellerUserId === authUser.id || l.sellerId === authUser.id || !l.sellerUserId));
      for (const l of userListings) {
        const payload = {
          id: l.id,
          seller_user_id: authUser.id,
          data: Object.assign({}, l)
        };
        delete payload.data.id; delete payload.data.sellerUserId;
        await window.sb.from('player_transfer_listings').upsert(payload, { onConflict: 'id' });
      }
    } catch(e) { console.warn('[tf_list] batch save hata:', e); }
  }
}

