const TR_WHISTLE = 'data:image/png;base64,';

const TR_POS_ICO = {GK:'data:image/png;base64,',DEF:'data:image/png;base64,',MID:'data:image/png;base64,',FWD:'data:image/png;base64,'};

// Seviye → sonraki seviye için gereken puan: ÜSTEL formül
// Sv 10 → 11: 300 puan (başlangıç)
// Her sonraki seviye için kümülatif × 1,035 (her seviyede %3,5 artış)
// Sv 99 → 100: ~6.409 puan
// YETENEK SINIRI KALDIRILDI — sonsuza kadar artabilir.
function trPointsNeeded(level) {
  return Math.max(1, Math.round(300 * Math.pow(1.035, level - 10)));
}

// Antrenman maliyeti: seviye+4 base, ×1/2/3 süreye göre
function trCost(level, mins) {
  const base = level + 4;
  return { euro: base * (mins/3), energy: mins };
}

// ─────────────────────────────────────────────────────────────────────
// 🆕 SİSTEM MAAŞ HESABI — Oyuncu maaşı sistemce belirlenir, kullanıcı kafasına göre koymaz.
// Formül: 40 günlük max antrenman harcaması × 1,045 (%4,5 marj)
//
//   • Oyuncu "seviyesi" = ortalama yetenek seviyesi (getPlayerMainOverall ile aynı 4-hat ortalaması)
//   • Günlük antrenman harcaması = günde 500 enerji × 9-dk antrenman maliyeti
//                                = (500/9) × (level+4) × 3
//                                ≈ 166,67 × (level+4) €/gün
//   • 40 gün × 1,045 = ~6.974 × (level+4) €
//
// Örnek:
//   Sv 10  oyuncu → 6.974 × 14  ≈   97.600 € /sezon →  24.400 €/taksit (4 taksit)
//   Sv 50  oyuncu → 6.974 × 54  ≈  376.600 € /sezon →  94.150 €/taksit
//   Sv 99  oyuncu → 6.974 × 103 ≈  718.300 € /sezon → 179.575 €/taksit
//   Sv 150 oyuncu → 6.974 × 154 ≈ 1.074.000 €/sezon → 268.500 €/taksit
// ─────────────────────────────────────────────────────────────────────

// Bir seviye için 40 günlük max antrenman euro maliyeti (enerji limitiyle).
function _trEstimate40DayCost(level) {
  if (typeof level !== 'number' || level < 1) level = 10;
  // Günde 500 enerji, her 9-dk antrenmanda 9 enerji + (level+4)×3 € maliyet.
  // 500/9 antrenman × (level+4)×3 € = 166,67 × (level+4) €/gün
  const dailyCost = (500 / 9) * (level + 4) * 3;
  return dailyCost * 40;
}

// Sistem oyuncu maaşı (sezonluk, 4 taksit halinde ödenir).
// player obje veya seviye sayısı kabul eder.
// 681 — sunucu maaşı oyuncunun güncel OVR'si (eşya dahil, players.overall) ile öder; gösterim de aynısı
function _benimSezonMaasim() {
  return getSystemPlayerSalary(Number(window._userProgressCache && window._userProgressCache.overall) || 10);
}

function getSystemPlayerSalary(playerOrLevel) {
  let level;
  if (typeof playerOrLevel === 'number') {
    level = playerOrLevel;
  } else if (playerOrLevel && typeof getPlayerMainOverall === 'function') {
    level = getPlayerMainOverall(playerOrLevel);
  } else {
    level = 10;
  }
  const baseCost = _trEstimate40DayCost(level);
  return Math.round(baseCost * 1.05);
}

// Bir taksit (sezonun 10/20/30/40. gününde ödenir)
function getSystemSalaryInstallment(playerOrLevel) {
  return Math.round(getSystemPlayerSalary(playerOrLevel) / 4);
}

// Bonservis = oyuncunun şu anki piyasa değeri (mevcut sistemce hesaplanır).
function getSystemTransferFee(player) {
  if (!player) return 0;
  if (typeof getPlayerMarketValue === 'function') {
    return Math.round(getPlayerMarketValue(player) || 0);
  }
  return 0;
}

// Kazanılan puan: 3dk→100, 6dk→200, 9dk→300
function trGainPoints(mins) { return mins * 100 / 3; }
// Kazanılan tecrübe (oyuncu seviyesi için):
//   🆕 3dk → 15 XP · 6dk → 25 XP · 9dk → 35 XP
//   (uzun antrenman toplamda daha çok XP verir ama dakika başına verim düşer)
const TRAIN_XP = { 3: 15, 6: 25, 9: 35 };
function trGainXP(mins) {
  const m = Number(mins) || 0;
  if (TRAIN_XP[m] != null) return TRAIN_XP[m];
  // Tablo dışı süreler için orantılı yaklaşım (3dk=15 tabanlı)
  return Math.max(0, Math.round(m * 5 - Math.max(0, m - 3) * 1.67));
}

// Yetenek verileri localStorage
function trGetData(pos) {
  // 🆕 ÖNCE RAM cache (Supabase'ten gelen, login'de doldurulur)
  if (_skillsCache && _skillsCache[pos] && Object.keys(_skillsCache[pos]).length > 0) {
    return _skillsCache[pos];
  }
  // 🆕 Cache yok — boş başlangıç (Supabase'ten yüklenecek)
  // Başlangıç: her yetenek seviye 10, 0 puan
  const data = {};
  (TR_SKILLS[pos] || []).forEach(sk => {
    data[sk.id] = { level: 10, points: 0 };
  });
  return data;
}

// 🆕 Skill payload üret (tüm 4 mevkiyi RAM cache'ten birleştir)
//
// ⚠️ VERİ KAYBI KORUMASI — 2026-08-18
//   Eskiden bu fonksiyon cache boşsa `{}` döndürüyordu ve çağıranlar bunu
//   user_player.skills'in ÜSTÜNE yazıyordu. Yükleme başarısız olduğunda
//   (ağ hatası, veritabanı çökmesi) ilk kaydetme tetiklendiği anda
//   kullanıcının bütün yetenekleri siliniyordu; trGetData da boş cache'i
//   görüp her yeteneği 10 döndürüyordu. Artık:
//     • Sunucudan BAŞARIYLA yüklenmediyse hiç yazılmaz (null döner)
//     • Boş grup varsa yazılmaz — kısmi veriyle tam veri ezilmez
function _trSkillsYuklendiMi() {
  if (!window._skillsLoadedOk) return false;
  if (!_skillsCache) return false;
  for (const p of ['GK','DEF','MID','FWD']) {
    const g = _skillsCache[p];
    if (!g || typeof g !== 'object' || Object.keys(g).length === 0) return false;
  }
  return true;
}
function _trBuildSkillsPayload() {
  if (!_trSkillsYuklendiMi()) {
    console.warn('[Skills] KAYDETME İPTAL — yetenekler sunucudan yüklenmedi, ' +
                 'boş veri yazılıp mevcut yetenekler silinmesin diye atlandı.');
    return null;
  }
  const full = {};
  ['GK','DEF','MID','FWD'].forEach(p => { full[p] = _skillsCache[p]; });
  return full;
}

// 🆕 Pending tüm save'leri ANINDA tetikle (sayfa kapanırken / sekme gizlenirken kullanılır)
function trFlushPendingSaves() {
  if (!window.sb || typeof authUser === 'undefined' || !authUser || !authUser.id) return;
  // Skills timer varsa hemen tetikle
  if (_skillsSaveTimer) {
    clearTimeout(_skillsSaveTimer);
    _skillsSaveTimer = null;
    const full = _trBuildSkillsPayload();
    if (!full) return;                       // 🆕 boş veri yazma
    try {
      window.sb.from('user_player').update({ skills: full }).eq('user_id', authUser.id)
        .then(() => console.info('[Skills] flush save tamamlandı'))
        .catch(e => console.warn('[Skills] flush save hata:', e));
    } catch(e) { console.warn('[Skills] flush exception:', e); }
  }
  // Active trainings timer varsa hemen tetikle
  if (_activeSaveTimer) {
    clearTimeout(_activeSaveTimer);
    _activeSaveTimer = null;
    try {
      window.sb.from('user_player').update({ active_trainings: _activeCache || [] }).eq('user_id', authUser.id)
        .then(() => console.info('[ActiveTrainings] flush save tamamlandı'))
        .catch(e => console.warn('[ActiveTrainings] flush save hata:', e));
    } catch(e) { console.warn('[ActiveTrainings] flush exception:', e); }
  }
  // 🆕 Takım dizilişi/stratejisi: bekleyen debounce kaydını HEMEN yaz (maç başlamadan
  //   son diziliş ayarı garanti team_data'ya gitsin → motor onu kullanır; elle "Kaydet" gerekmez)
  try { if (typeof flushTeamStrategySave === 'function') flushTeamStrategySave(); } catch(e) {}
  try { if (typeof flushNtStrategySave === 'function') flushNtStrategySave(); } catch(e) {}
}

function trSaveData(pos, data) {
  // 🆕 RAM cache güncelle (localStorage yazma yok — Supabase tek doğru kaynak)
  if (!_skillsCache) _skillsCache = {};
  _skillsCache[pos] = data;
  // 🆕 Debounced Supabase write — 4 pozisyonu tek JSONB sütununda tutar
  if (window.sb && typeof authUser !== 'undefined' && authUser && authUser.id) {
    clearTimeout(_skillsSaveTimer);
    _skillsSaveTimer = setTimeout(async () => {
      _skillsSaveTimer = null;
      try {
        const full = _trBuildSkillsPayload();
        if (!full) return;                   // 🆕 boş veri yazma
        await window.sb.from('user_player').update({
          skills: full
        }).eq('user_id', authUser.id);
      } catch(e) { console.warn('[Skills] save hata:', e); }
    }, 200);
  }
}

// Aktif antrenmanlar: [{pos, skillId, skillName, mins, startTime, endTime}]
function trGetActive() {
  // 🆕 RAM cache — Supabase tek doğru kaynak
  return Array.isArray(_activeCache) ? _activeCache : [];
}
function trSaveActive(list) {
  // 🆕 RAM cache güncelle (localStorage yazma yok)
  _activeCache = list || [];
  // 🆕 Debounced Supabase write — 200ms
  if (window.sb && typeof authUser !== 'undefined' && authUser && authUser.id) {
    clearTimeout(_activeSaveTimer);
    _activeSaveTimer = setTimeout(async () => {
      _activeSaveTimer = null;
      try {
        await window.sb.from('user_player').update({
          active_trainings: _activeCache
        }).eq('user_id', authUser.id);
      } catch(e) { console.warn('[ActiveTrainings] save hata:', e); }
    }, 200);
  }
}

// ══════ ENERJİ SİSTEMİ ══════
// Günlük maksimum: 450 enerji
// Her gün saat 00:00'da (kullanıcının ülke saatine göre) 450'ye sıfırlanır
// Kullanılmayan enerji bir sonraki güne aktarılmaz (her gün 450'den başlar)
const ENERGY_MAX = 450;

// Kullanıcının "günlük gün" anahtarı (TZ-aware "YYYY-MM-DD")
// Kullanıcının takım ülkesine göre hesaplanır, takım yoksa tarayıcının saatine göre
function getUserDayKey() {
  // Kullanıcının ülke saatini hesapla
  // _userTeam varsa onun ülkesinin TZ'i, yoksa authUser.nationality, yoksa cihaz saati
  let tzOffset = null;
  try {
    if(typeof _userTeam !== 'undefined' && _userTeam && typeof TZ_OFFSETS !== 'undefined') {
      tzOffset = TZ_OFFSETS[_userTeam.countryCode];
    }
    if(tzOffset === null && typeof authUser !== 'undefined' && authUser && authUser.nationality && typeof TZ_OFFSETS !== 'undefined') {
      tzOffset = TZ_OFFSETS[authUser.nationality];
    }
  } catch(e) {}

  if(typeof tzOffset !== 'number') {
    // Cihaz yerel saati fallback
    const d = new Date();
    return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  }

  // UTC'ye göre offset uygula
  const now = new Date();
  const utcMs = now.getTime() + (now.getTimezoneOffset() * 60000);
  const localMs = utcMs + (tzOffset * 3600000);
  const local = new Date(localMs);
  return `${local.getFullYear()}-${String(local.getMonth()+1).padStart(2,'0')}-${String(local.getDate()).padStart(2,'0')}`;
}

// Bir sonraki sıfırlamaya ne kadar var? (saniye cinsinden, UI'da geri sayım için)
function getSecondsToNextReset() {
  let tzOffset = null;
  try {
    if(typeof _userTeam !== 'undefined' && _userTeam && typeof TZ_OFFSETS !== 'undefined') {
      tzOffset = TZ_OFFSETS[_userTeam.countryCode];
    }
    if(tzOffset === null && typeof authUser !== 'undefined' && authUser && authUser.nationality && typeof TZ_OFFSETS !== 'undefined') {
      tzOffset = TZ_OFFSETS[authUser.nationality];
    }
  } catch(e) {}

  if(typeof tzOffset !== 'number') {
    // Cihaz yerel saati fallback
    const now = new Date();
    const tomorrow = new Date(now);
    tomorrow.setDate(tomorrow.getDate() + 1);
    tomorrow.setHours(0, 0, 0, 0);
    return Math.floor((tomorrow - now) / 1000);
  }

  // Kullanıcı ülkesinin saatine göre bir sonraki gece yarısı
  const now = new Date();
  const utcMs = now.getTime() + (now.getTimezoneOffset() * 60000);
  const localMs = utcMs + (tzOffset * 3600000);
  const local = new Date(localMs);
  // Local günde gece yarısına kalan ms
  const msToMidnight =
    (24 - local.getHours()) * 3600000
    - local.getMinutes() * 60000
    - local.getSeconds() * 1000
    - local.getMilliseconds();
  return Math.floor(msToMidnight / 1000);
}

// 🆕 RAM CACHE (energy) — Supabase'ten gelir
let _energyCache = null;
let _energySaveTimer = null;
let _energyLoading = false;

// 🆕 RAM CACHE (skills + active_trainings) — Supabase'ten gelir, login pull doldurur
// _skillsCache: { GK:{skId:{level,points}}, DEF:{}, MID:{}, FWD:{} }
// _activeCache: [{pos, skillId, skillName, mins, startTime, endTime}, ...]
let _skillsCache = null;
let _activeCache = null;
let _skillsSaveTimer = null;
let _activeSaveTimer = null;

// 🆕 RAM CACHE (kupalar) — user_player.trophies kolonundan gelir
let _trophiesCache = null;
let _trophiesSaveTimer = null;

// Server'dan kupaları yükle (login pull tarafından çağrılır)
async function _trophiesLoadFromServer() {
  if (!window.sb || !authUser || !authUser.id) { _trophiesCache = []; return; }
  try {
    const { data, error } = await window.sb.from('user_player')
      .select('trophies')
      .eq('user_id', authUser.id).maybeSingle();
    if (error) { console.warn('[trophies] load hata:', error); _trophiesCache = []; return; }
    _trophiesCache = (data && Array.isArray(data.trophies)) ? data.trophies : [];
  } catch(e) { console.warn('[trophies] load hata:', e); _trophiesCache = []; }
}

// Sync getter — diğer kodların kullandığı tek arayüz
function getTrophies() {
  return Array.isArray(_trophiesCache) ? _trophiesCache : [];
}

// Sync setter — cache anlık, server'a debounced
function saveTrophies(arr) {
  if (!Array.isArray(arr)) arr = [];
  _trophiesCache = arr;
  if (window.sb && authUser && authUser.id) {
    clearTimeout(_trophiesSaveTimer);
    _trophiesSaveTimer = setTimeout(async () => {
      try {
        await window.sb.from('user_player').update({ trophies: arr }).eq('user_id', authUser.id);
      } catch(e) { console.warn('[trophies] save hata:', e); }
    }, 500);
  }
}

// ─────────────────────────────────────────────────────────────────────
// 🆕 TAKIM KUPALARI — team_data.trophies (lig şampiyonlukları + turnuva kupaları)
// ─────────────────────────────────────────────────────────────────────
// Kişisel kupalardan AYRI tutulur. Takıma ait kupa havuzu — tüm üyeler aynı vitrini görür.
// Mevcut kişisel akış (user_player.trophies) korunur — kariyer sayfasında kullanılır.
//
// Yapı: team_data.data_key='trophies', data: [{season, type, leagueName?, tierIdx?, wonAt}, ...]
//   type: 'league' | 'champ' | 'elite' | 'conv'  (ENC ulusal takıma ait, kulüpte yok)

let _teamTrophiesCache = null;
let _teamTrophiesSaveTimer = null;

async function _teamTrophiesLoadFromServer() {
  if (!window.sb || !_userTeam || !_userTeam.countryCode || !_userTeam.teamName) {
    _teamTrophiesCache = [];
    return;
  }
  try {
    const { data, error } = await window.sb.from('team_data')
      .select('data')
      .eq('country_code', _userTeam.countryCode)
      .eq('team_name', _userTeam.teamName)
      .eq('data_key', 'trophies')
      .maybeSingle();
    if (error) { console.warn('[team_trophies] load hata:', error); _teamTrophiesCache = []; return; }
    _teamTrophiesCache = (data && Array.isArray(data.data)) ? data.data : [];
  } catch(e) { console.warn('[team_trophies] load hata:', e); _teamTrophiesCache = []; }
}

function getTeamTrophies() {
  return Array.isArray(_teamTrophiesCache) ? _teamTrophiesCache : [];
}

function saveTeamTrophies(arr) {
  if (!Array.isArray(arr)) arr = [];
  _teamTrophiesCache = arr;
  if (window.sb && _userTeam && _userTeam.countryCode && _userTeam.teamName) {
    clearTimeout(_teamTrophiesSaveTimer);
    _teamTrophiesSaveTimer = setTimeout(async () => {
      try {
        await window.sb.from('team_data').upsert({
          country_code: _userTeam.countryCode,
          team_name: _userTeam.teamName,
          data_key: 'trophies',
          data: arr,
          updated_at: new Date().toISOString()
        }, { onConflict: 'country_code,team_name,data_key' });
      } catch(e) { console.warn('[team_trophies] save hata:', e); }
    }, 500);
  }
}

// Ziyaretçi modunda başka takımın kupalarını çek (read-only)
async function _loadVisitedTeamTrophies(countryCode, teamName) {
  if (!window.sb || !countryCode || !teamName) return [];
  try {
    const { data } = await window.sb.from('team_data')
      .select('data')
      .eq('country_code', countryCode)
      .eq('team_name', teamName)
      .eq('data_key', 'trophies')
      .maybeSingle();
    return (data && Array.isArray(data.data)) ? data.data : [];
  } catch(e) { return []; }
}

// 🆕 Sayfa görünmez olduğunda / kapanırken pending save'leri ANINDA tetikle
// Bu olmadan, debounce timer'ı içinde olan save'ler sayfa kapanınca kaybolur
// → diğer cihazda eski veri görünür
(function _trAttachFlushListeners() {
  // visibilitychange: kullanıcı sekme değiştirdi / minimize etti / arka plana attı
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'hidden') {
      try { if (typeof trFlushPendingSaves === 'function') trFlushPendingSaves(); } catch(e) {}
    }
  });
  // pagehide: mobile Safari + bazı tarayıcılarda beforeunload yerine bu fire eder
  window.addEventListener('pagehide', () => {
    try { if (typeof trFlushPendingSaves === 'function') trFlushPendingSaves(); } catch(e) {}
    try { _viewerLeaveBeacon(); } catch(e) {}
  });
  // beforeunload: yenileme / kapatma / link tıklama
  window.addEventListener('beforeunload', () => {
    try { if (typeof trFlushPendingSaves === 'function') trFlushPendingSaves(); } catch(e) {}
    try { _viewerLeaveBeacon(); } catch(e) {}
  });
  // 🆕 Match-screen açıkken sekme/pencere kapanırsa izleyici listesinden düş.
  //   navigator.sendBeacon ile tarayıcı kapanırken bile fire eder (fetch güvensiz).
  function _viewerLeaveBeacon() {
    const mk = window._viewerBeatMatchKey;
    if (!mk || !window.authUser || !window.authUser.id) return;
    if (typeof SUPABASE_URL === 'undefined' || typeof SUPABASE_KEY === 'undefined') return;
    const url = `${SUPABASE_URL}/functions/v1/tick-matches?action=viewer_leave&match_key=${encodeURIComponent(mk)}&user_id=${encodeURIComponent(window.authUser.id)}`;
    // 🔒 565 — sunucu kimliği oturumdan alıyor; sendBeacon başlık taşıyamadığı için keepalive
    //   fetch. Gönderilemezse sunucu eski izleyici kaydını 75 sn içinde zaten temizliyor.
    try {
      _oturumJwt().then(_jwt => {
        if (!_jwt) return;
        fetch(url, { method: 'GET', keepalive: true, headers: { 'Authorization': 'Bearer ' + _jwt, 'apikey': SUPABASE_KEY } }).catch(() => {});
      }).catch(() => {});
    } catch(e) {}
  }
})();

// Supabase'ten energy çek
async function _energyLoadFromServer() {
  if (!window.sb || !authUser || !authUser.id) return null;
  if (_energyLoading) return _energyCache;
  _energyLoading = true;
  try {
    const { data, error } = await window.sb
      .from('user_player')
      .select('energy')
      .eq('user_id', authUser.id)
      .maybeSingle();
    if (error || !data) {
      console.warn('[Energy] load hata:', error);
      return _energyCache;
    }
    // Cache yapısı: {current, max, dayKey}
    const cur = (typeof data.energy === 'number') ? data.energy : ENERGY_MAX;
    // 🆕 max'ı dinamik hesapla (statik ENERGY_MAX değil)
    // Aksi halde trCheckEnergyReset her reload'da "max yükseldi" sanıp +bonus ekler
    const dynMax = (typeof getUserEffectiveMaxEnergy === 'function') ? getUserEffectiveMaxEnergy() : ENERGY_MAX;
    _energyCache = {
      current: cur,
      max: dynMax,
      dayKey: (typeof getUserDayKey === 'function') ? getUserDayKey() : new Date().toDateString()
    };
    // Daily reset kontrolü
    if (typeof trCheckEnergyReset === 'function') {
      try { trCheckEnergyReset(); } catch(e) {}
    }
    // UI yenile
    const dispEl = document.getElementById('energy-display');
    if(dispEl) dispEl.textContent = Math.max(0, _energyCache.current);
    return _energyCache;
  } catch(e) {
    console.warn('[Energy] load exception:', e);
    return _energyCache;
  } finally {
    _energyLoading = false;
  }
}

function trGetEnergy() {
  if (_energyCache) return _energyCache;
  // Henüz yüklenmemiş — arka planda çek
  if (window.sb && authUser && authUser.id) {
    _energyLoadFromServer().catch(()=>{});
  }
  // 🆕 Default: dinamik max kullan (statik ENERGY_MAX değil)
  // Aksi halde her reload'da trCheckEnergyReset "max yükseldi" sanıp +bonus ekler
  const dynMax = (typeof getUserEffectiveMaxEnergy === 'function') ? getUserEffectiveMaxEnergy() : ENERGY_MAX;
  return {
    current: dynMax,
    max: dynMax,
    dayKey: (typeof getUserDayKey === 'function') ? getUserDayKey() : new Date().toDateString()
  };
}

function trSaveEnergy(e) {
  // 🆕 Yalnızca RAM cache + ekran. Enerjiyi sunucu düşer (antrenman_baslat RPC);
  //   energy kolonu DB trigger ile korunur → istemci doğrudan yazamaz (hile önleme).
  _energyCache = Object.assign({}, _energyCache || {}, e);
  const dispEl = document.getElementById('energy-display');
  if(dispEl) dispEl.textContent = Math.max(0, e.current);
}

// ══ DİNAMİK MAX ENERJİ — PERFORMANS MERKEZİ BONUSU ══
// Kural:
//   • Takımsız oyuncu: günlük 450 enerji
//   • Takımı olan oyuncu: 450 + (performans_merkezi_seviyesi * 5)
//     ↳ Sv 1 → +5, Sv 2 → +10, ..., Sv 10 → +50
//
// Dinamik davranış:
//   • Takıma katılma → max yükselir, fark kadar bonus current'a eklenir
//   • Tesis yükseltme → max +5 yükselir, +5 current'a eklenir
//   • Takımdan ayrılma → max düşer, current yeni max'a clamp edilir
//   • Günlük 00:00 reset → current = yeni max (bonus dahil)
function getUserEffectiveMaxEnergy() {
  let max = ENERGY_MAX; // 450 default
  try {
    if(typeof _userTeam !== 'undefined' && _userTeam &&
       typeof FAC_LEVELS !== 'undefined' && FAC_LEVELS) {
      const perfLvl = (typeof FAC_LEVELS.performance === 'number') ? FAC_LEVELS.performance : 1;
      max = ENERGY_MAX + perfLvl * 5;
    }
  } catch(e) {}
  return max;
}

// 🆕 ENERJİ sunucuda yenilenir (ülke saatiyle 00:00, tesis bonusu dahil) — istemci hiçbir şeyi
// sıfırlamaz veya yazmaz. Bu fonksiyon yalnızca cache'teki değeri okuyup max'ı
// gösterim için günceller (geriye uyumluluk: aynı imza, aynı dönüş şekli).
function trCheckEnergyReset() {
  const e = trGetEnergy();
  // max'ı dinamik göster (takım/tesis durumuna göre) — current'a DOKUNMA, server yönetir.
  e.max = getUserEffectiveMaxEnergy();
  // 🆕 ESKİ HATA: current > max ise max'a çekiliyordu. Günlük giriş hediyesi
  //    tavanın üstüne eklendiğinde (500 → 510) fazlası ekranda anında yok
  //    oluyordu. Artık kırpma yok — sunucudaki gerçek değer gösterilir.
  return e;
}

// Takım/tesis değişikliklerinde çağrılır → enerji bonusunu uygular ve UI'yı tazeler.
// Geri dönüş: { delta, before, after, max } — UI tarafından toast/animasyon için kullanılabilir.
function recomputeUserEnergyBonus() {
  const before = trGetEnergy();
  const beforeCur = before.current;
  const e = trCheckEnergyReset();        // dinamik max'ı uygular ve kaydeder
  const dispEl = document.getElementById('energy-display');
  if(dispEl) dispEl.textContent = Math.max(0, e.current);
  // Antrenman sayfası açıksa orayı da tazele
  try { if(typeof trRender === 'function' && document.getElementById('page-training')?.classList.contains('active')) trRender(); } catch(e2){}
  return { delta: e.current - beforeCur, before: beforeCur, after: e.current, max: e.max };
}

// Topbar enerji metnini güncelle (UI senkronu)
function syncEnergyDisplay() {
  const e = trCheckEnergyReset();
  const dispEl = document.getElementById('energy-display');
  if(dispEl) dispEl.textContent = Math.max(0, e.current);
}

// 🆕 Antrenman & enerji bilgi modalı — statik içerik, veri çekmez
function trOpenInfo() {
  const ov = document.getElementById('trInfoOverlay');
  if (ov) ov.classList.add('open');
}
function trCloseInfo() {
  const ov = document.getElementById('trInfoOverlay');
  if (ov) ov.classList.remove('open');
}

// State
let _trPos = 'MID'; // oyuncunun mevkisi varsayılan
let _trSelectedSkill = null;
let _trSelectedMins = 3;
let _trTimerInterval = null;

// ── Render ──
function trRender() {
  const user = authUser || {};
  // 🆕 _trPos ilk açılışta kullanıcının ana mevkisine atanır,
  // sonra kullanıcı sekme değiştirebilir (trSelectPos). Her render'da override etme.
  if (!_trPos) _trPos = user.position || 'MID';
  try { if (typeof enjTrSeritCiz === 'function') enjTrSeritCiz(); } catch(e) {}   // 760

  // Pos tab aktifliği
  const posMap = { GK: 0, DEF: 1, MID: 2, FWD: 3 };
  document.querySelectorAll('.tr-pos-tab').forEach((btn, i) => {
    btn.classList.toggle('active', i === (posMap[_trPos] ?? 2));
  });

  // Subtitle: tesis seviyesi
  const facLvl = FAC_LEVELS['training'] || 1;
  const active0 = trGetActive();
  const sub = document.getElementById('trSubtitle');
  if(sub) sub.textContent = `Antrenman Merkezi Sv.${facLvl} · Eş Zamanlı: ${active0.length}/${facLvl}`;

  // 763 — üst kutular: enerji · sıfırlanma · merkez
  trBaslikCiz();

  // Para
  const monEl = document.getElementById('trMoney');
  if(monEl) { const md = document.getElementById('money-display'); if(md) monEl.textContent = md.dataset.tam || md.textContent; }

  trRenderActive();
  trRenderSkills();
  trStartTimers();
}

// 763 — antrenman sayfası üst paneli (enerji halkası · sıfırlanma · merkez)
function trBaslikCiz() {
  try {
    const energy = trCheckEnergyReset();
    const cur = Math.max(0, Number(energy.current) || 0), max = Math.max(1, Number(energy.max) || 1);
    const eEl = document.getElementById('trEnergy'); if (eEl) eEl.textContent = cur;
    const mEl = document.getElementById('trEnergyMax'); if (mEl) mEl.textContent = '/ ' + max;
    const hal = document.getElementById('trEnergyHalka');
    if (hal) { const C = 2 * Math.PI * 34; hal.setAttribute('stroke-dasharray', `${(C * Math.min(1, cur / max)).toFixed(1)} ${C.toFixed(1)}`); }
    const b = (typeof _enjB === 'function') ? _enjB() : ['g', 'sa', 'dk', 'sn'];
    const resetEl = document.getElementById('trEnergyReset');
    if (resetEl) {
      const secs = (typeof getSecondsToNextReset === 'function') ? getSecondsToNextReset() : 0;
      const hh = Math.floor(secs / 3600), mm = Math.floor((secs % 3600) / 60);
      resetEl.textContent = `${hh}${b[1]} ${mm}${b[2]}`;
    }
    const ulEl = document.getElementById('trEnergyUlke');
    if (ulEl) {
      let f = '';
      try { const cc = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.countryCode) || (authUser && authUser.nationality); const u = cc && _uyrukUlke(cc); if (u && u.flag) f = u.flag; } catch (e) {}
      ulEl.textContent = f;
    }
    const facEl = document.getElementById('trFacLvl');
    if (facEl) {
      const fl = FAC_LEVELS['training'] || 1, al = trGetActive().length;
      facEl.textContent = `Sv.${fl}`;
      const sy = document.getElementById('trFacSay'); if (sy) sy.textContent = `${al}/${fl}`;
      const k = facEl.closest('.trh-a-mz'); if (k) k.classList.toggle('dolu', al >= fl);
      const y = document.getElementById('trFacYuva');
      if (y) { y.classList.toggle('cok', fl > 6); y.innerHTML = Array.from({ length: fl }, (_, i) => `<i class="${i < al ? 'd' : ''}"></i>`).join(''); }
    }
  } catch (e) {}
}

function trSelectPos(pos, btn) {
  _trPos = pos;
  document.querySelectorAll('.tr-pos-tab').forEach(b => b.classList.remove('active'));
  if(btn) btn.classList.add('active');
  trRenderSkills();
}

// ── Aktif antrenmanlar ──
function trRenderActive() {
  const active = trGetActive();
  const wrap = document.getElementById('trActiveWrap');
  const list = document.getElementById('trActiveList');
  if(!wrap || !list) return;

  // Bitmiş antrenmanları tespit et
  const now = Date.now();
  const done = active.filter(a => now >= a.endTime);
  const running = active.filter(a => now < a.endTime);

  // 🆕 Üst kart artık gizli — geri sayım & Topla yetenek kutusunun içinde gösteriliyor.
  wrap.style.display = 'none';

  list.innerHTML = active.map(a => {
    const remaining = Math.max(0, a.endTime - now);
    const isDone = remaining === 0;
    const mins = Math.floor(remaining / 60000);
    const secs = Math.floor((remaining % 60000) / 1000);
    const timerStr = isDone ? '✓' : `${mins}:${secs.toString().padStart(2,'0')}`;

    return `<div class="tr-active-card">
      <div class="tr-ac-icon">💪</div>
      <div class="tr-ac-info">
        <div class="tr-ac-name">${a.skillName}</div>
        <div class="tr-ac-sub">${a.mins} dakika · ${a.pos === 'GK'?'Kaleci':a.pos==='DEF'?'Defans':a.pos==='MID'?'Orta Saha':'Forvet'}</div>
      </div>
      <div style="display:flex;flex-direction:column;align-items:flex-end;gap:4px;flex-shrink:0">
        ${isDone
          ? `<button class="tr-ac-collect-btn" onclick="trCollect('${a.id}')"><img class="tr-ac-ico" src="${TR_WHISTLE}"> Topla</button>`
          : `<div class="tr-ac-timer" id="trTimer_${a.id}">${timerStr}</div>`
        }
        ${!isDone ? `<button class="tr-ac-instant-btn" onclick="trInstantFinish('${a.id}',${a.mins})">
          ⚡ ${a.mins}💎 Bitir
        </button>` : ''}
      </div>
    </div>`;
  }).join('');
}

// ── Yetenek listesi (3 sütun kompakt grid) ──
function trRenderSkills() {
  const el = document.getElementById('trSkillList');
  if(!el) return;

  const skills = TR_SKILLS[_trPos] || [];
  const data   = trGetData(_trPos);
  const active = trGetActive();

  const posColors = {GK:'#7e57c2', DEF:'#1565c0', MID:'#2e7d32', FWD:'#b71c1c'};
  const barColor  = posColors[_trPos] || 'var(--accent)';

  el.innerHTML = '<div class="tr-skill-grid">' + skills.map(sk => {
    const d = data[sk.id] || { level: 10, points: 0 };
    const needed   = trPointsNeeded(d.level);
    const pct      = Math.min(100, Math.round(d.points / needed * 100));
    const activeEntry = active.find(a => a.pos === _trPos && a.skillId === sk.id);
    const isActive = !!activeEntry;

    // Seviye renk eşiği: 80+ altın, 60+ accent, 40+ accent2, beyaz
    const lvColor = d.level >= 80 ? '#ffd600' : d.level >= 60 ? 'var(--accent)' : d.level >= 40 ? 'var(--accent2)' : '#fff';
    const _ph = TR_PHOTOS[sk.id];
    const _pcls = _ph ? ' has-photo' : '';
    const _head = _ph
      ? `<div class="sk-photo-wrap"><img class="sk-photo" src="${_ph}" alt="${sk.name}"><div class="sk-photo-grad"></div><div class="sk-photo-name">${sk.name}</div></div>`
      : `<div class="tr-sm-icon">${sk.icon}</div><div class="tr-sm-name">${sk.name}</div>`;

    // 🆕 Aktif antrenman: aynı kutu içinde geri sayım → bitince Topla (Varyant 2)
    if (isActive) {
      const now = Date.now();
      const remaining = Math.max(0, activeEntry.endTime - now);
      const isDone = remaining === 0;
      const total = Math.max(1, activeEntry.endTime - activeEntry.startTime);
      const elapsedPct = Math.min(100, Math.round((total - remaining) / total * 100));
      const mins = Math.floor(remaining / 60000);
      const secs = Math.floor((remaining % 60000) / 1000);
      const timerStr = isDone ? '✓' : `${mins}:${secs.toString().padStart(2,'0')}`;

      const _abody = `<div class="tr-sm-timer" id="trSkTimer_${activeEntry.id}">${timerStr}</div>
        <div class="tr-sm-running-label">${isDone ? 'tamamlandı' : 'kaldı'}</div>
        <div class="tr-sm-cd-bar-wrap"><div class="tr-sm-cd-bar" id="trSkBar_${activeEntry.id}" style="width:${isDone?100:elapsedPct}%"></div></div>
        ${isDone
          ? `<button class="tr-sm-collect-btn" onclick="trCollect('${activeEntry.id}')"><img class="tr-btn-ico" src="${TR_WHISTLE}"> Topla</button>`
          : `<button class="tr-sm-instant" onclick="trInstantFinish('${activeEntry.id}',${activeEntry.mins})">⚡ ${activeEntry.mins}💎 Bitir</button>`}`;
      return `<div class="tr-skill-mini tr-sm-active ${isDone?'tr-sm-done':''}${_pcls}" title="${sk.desc}">${_head}${_ph?`<div class="sk-body">${_abody}</div>`:_abody}</div>`;
    }

    const _body = `<div class="tr-sm-level" style="color:${lvColor}">${d.level}</div>
      <div class="tr-sm-bar-wrap"><div class="tr-sm-bar" style="width:${pct}%;background:${barColor}"></div></div>
      <div class="tr-sm-pct">${d.points} / ${needed}</div>
      <button class="tr-sm-btn" onclick="trOpenModal('${_trPos}','${sk.id}')"><img class="tr-btn-ico" src="${TR_POS_ICO[_trPos]}"> Çalış</button>`;
    return `<div class="tr-skill-mini${_pcls}" title="${sk.desc}">${_head}${_ph?`<div class="sk-body">${_body}</div>`:_body}</div>`;
  }).join('') + '</div>';
}

// ── Modal aç ──
function trOpenModal(pos, skillId) {
  const skill = (TR_SKILLS[pos] || []).find(s => s.id === skillId);
  if(!skill) return;

  _trSelectedSkill = { pos, skillId, skill };
  _trSelectedMins  = 3;

  const data  = trGetData(pos);
  const d     = data[skillId] || { level: 10, points: 0 };

  // Modal skill bilgisi
  const lvColor = d.level >= 80 ? '#ffd600' : d.level >= 60 ? 'var(--accent)' : 'var(--accent2)';
  document.getElementById('trModalSkill').innerHTML = `
    <div class="trx-skill-ic">${skill.icon}</div>
    <div style="min-width:0">
      <div class="trx-skill-name">${skill.name}</div>
      <div class="trx-skill-desc">${skill.desc}</div>
    </div>
    <div class="trx-skill-lv">
      <div class="trx-skill-lv-n" style="color:${lvColor}">${d.level}</div>
      <div class="trx-skill-lv-t">Seviye</div>
    </div>`;

  // Süre kartları
  [3, 6, 9].forEach(m => {
    const cost = trCost(d.level, m);
    const pts  = trGainPoints(m);
    const xp   = trGainXP(m);
    const el   = document.getElementById(`trDurInfo${m}`);
    if(el) el.innerHTML = `<span class="tr-dur-xp">+${xp} XP</span><div class="tr-dur-meta">⚡ ${cost.energy} · +${pts} puan${cost.euro?`<br>💵 ${cost.euro} €`:''}</div>`;
  });

  // Aktif kart sıfırla
  document.querySelectorAll('.tr-dur-card').forEach((c,i)=>c.classList.toggle('active',i===0));
  trUpdateSummary(d.level);

  // 🆕 Çakışma önle: başka antrenman overlay'i açıksa kapat (eski modal arkada kalmasın)
  try { document.getElementById('trDoneModal')?.classList.remove('open'); } catch(e){}
  try { document.getElementById('lvlupOverlay')?.remove(); } catch(e){}

  // 🆕 Modal HTML'de #page-training icinde duruyor. Herhangi bir ata
  //    elemana transform/filter/perspective gelirse position:fixed artik
  //    ekrana degil O ATAYA gore konumlanir ve modal sayfanin ortasinda
  //    kalir. <body>'ye tasiyarak bu riski tamamen kaldiriyoruz.
  const _trOv = document.getElementById('trModal');
  try { if (_trOv && _trOv.parentNode !== document.body) document.body.appendChild(_trOv); } catch(e){}
  _trOv.classList.add('open');
}

function trCloseModal() {
  document.getElementById('trModal').classList.remove('open');
  _trSelectedSkill = null;
}

function trSelectDur(mins, el) {
  _trSelectedMins = mins;
  document.querySelectorAll('.tr-dur-card').forEach(c=>c.classList.remove('active'));
  if(el) el.classList.add('active');
  if(_trSelectedSkill) {
    const data = trGetData(_trSelectedSkill.pos);
    const d    = data[_trSelectedSkill.skillId] || {level:10,points:0};
    trUpdateSummary(d.level);
  }
}

function trUpdateSummary(level) {
  const cost = trCost(level, _trSelectedMins);
  const pts  = trGainPoints(_trSelectedMins);
  const xp   = trGainXP(_trSelectedMins);
  const energy = trCheckEnergyReset();

  const canAfford = energy.current >= cost.energy;

  // Oyuncu seviyesi ilerleme önizlemesi
  const me = ROSTER_DATA.find(p => p.role === 'user' && !p.isBot);
  let levelPreview = '';
  if(me) {
    const curLevel = me.level || 0;
    const curXp = me.xp || 0;
    const needed = (typeof rosterXpForLevel === 'function') ? rosterXpForLevel(curLevel) : 100;
    const newXp = curXp + xp;
    const willLevelUp = newXp >= needed;
    if(willLevelUp) {
      levelPreview = `<div class="tr-sum-row" style="background:rgba(255,213,79,.08);padding:6px 10px;border-radius:8px;border:1px solid rgba(255,213,79,.3)"><span class="tr-sum-label">🌟 Seviye Atlıyorsun!</span><span class="tr-sum-val" style="color:#ffd54f">Sv.${curLevel} → Sv.${curLevel+1}</span></div>`;
    } else {
      const newPct = Math.round((newXp / needed) * 100);
      const curPct = Math.round((curXp / needed) * 100);
      levelPreview = `<div class="tr-sum-row"><span class="tr-sum-label">Oyuncu Sv.${curLevel}</span><span class="tr-sum-val">${curPct}% → ${newPct}% (${newXp}/${needed} XP)</span></div>`;
    }
  }

  document.getElementById('trModalSummary').innerHTML = `
    <div class="tr-sum-row"><span class="tr-sum-label" data-enj="sure">Süre</span><span class="tr-sum-val">${_trSelectedMins} dakika</span></div>
    <div class="tr-sum-row"><span class="tr-sum-label">Enerji</span><span class="tr-sum-val" style="color:${canAfford?'var(--accent)':'#ef5350'}">⚡ ${cost.energy} (${energy.current} mevcut)</span></div>
    <div class="tr-sum-row"><span class="tr-sum-label">Ücret</span><span class="tr-sum-val">💵 ${cost.euro} €</span></div>
    <div class="tr-sum-row"><span class="tr-sum-label" data-enj="puan">Yetenek Puanı</span><span class="tr-sum-val" style="color:var(--accent)">+${pts} puan</span></div>
    <div class="tr-sum-row"><span class="tr-sum-label" data-enj="xp">Tecrübe (XP)</span><span class="tr-sum-val" style="color:#ffd54f">+${xp} xp</span></div>
    ${levelPreview}`;
  try { if (typeof enjModalUygula === 'function') enjModalUygula(_trSelectedMins); } catch(e) {}   // 760

  const btn = document.querySelector('.tr-btn-start');
  if(btn) {
    btn.disabled = !canAfford;
    btn.textContent = canAfford ? 'Başlat' : '⚡ Yetersiz Enerji';
  }
}

// ── Antrenman başlat ──
let _trBasliyor = false;
async function trStartTraining() {
  if(!_trSelectedSkill || _trBasliyor) return;

  const { pos, skillId, skill } = _trSelectedSkill;
  const data   = trGetData(pos);
  const d      = data[skillId] || { level: 10, points: 0 };
  const cost   = trCost(d.level, _trSelectedMins);
  const energy = trCheckEnergyReset();

  // Enerji kontrolü
  if(energy.current < cost.energy) { trCloseModal(); if (energy.current < 3 && typeof rhIste === 'function') rhIste('enerji'); return; }

  // Zaten bu yetenek için aktif mi?
  const active = trGetActive();
  if(active.some(a => a.pos === pos && a.skillId === skillId)) {
    trCloseModal();
    trToast('Bu yetenek için zaten aktif antrenman var!', '#ff9800');
    return;
  }

  // Toplam eş zamanlı = antrenman tesisi seviyesi
  const facilityLvl = FAC_LEVELS['training'] || 1;
  if(active.filter(a => a && a.endTime > Date.now()).length >= facilityLvl) {
    trCloseModal();
    trToast(`Antrenman Merkezi Sv.${facilityLvl}: Eş zamanlı en fazla ${facilityLvl} antrenman. Tesisi yükselt!`, '#ff9800');
    return;
  }

  // 623 — enerji, ücret (kişisel cüzdandan) ve eşzamanlı sınır sunucuda tek işlemde
  const mins = _trSelectedMins;
  _trBasliyor = true;
  let r = null;
  try {
    const { data, error } = await window.sb.rpc('antrenman_baslat', { p_pos: pos, p_skill: skillId, p_mins: mins, p_ad: skill.name });
    r = error ? null : data;
  } catch(e) {}
  _trBasliyor = false;
  if(!r || !r.ok) {
    trCloseModal();
    const hata = r && r.error;
    if(hata === 'yetersiz_bakiye') {
      trToast(`Yeterli paran yok! Gerekli: ${Number(r.gerekli || cost.euro).toLocaleString('tr')} € · Mevcut: ${Number(r.eur || 0).toLocaleString('tr')} €`, '#ef5350');
    } else if(hata === 'es_zamanli_sinir') {
      trToast(`Antrenman Merkezi Sv.${r.sinir}: Eş zamanlı en fazla ${r.sinir} antrenman. Tesisi yükselt!`, '#ff9800');
      _trAktifTazele();   // 740 — sunucuda olup ekranda görünmeyen antrenman varsa gelsin
    } else if(hata === 'yetersiz_enerji') {
      trToast('⚡ Yetersiz Enerji', '#ef5350');
      if (typeof rhIste === 'function') rhIste('enerji');   // 663
    } else if(hata === 'zaten_aktif') {
      trToast('Bu yetenek için zaten aktif antrenman var!', '#ff9800');
      if (Array.isArray(r.active)) { _trSunucuEkle(r.active); trRender(); }
    } else {
      trToast(r ? 'Antrenman başlatılamadı.' : 'Sunucuya ulaşılamadı.', '#ef5350');
      if (!r) _trAktifTazele();   // 739 — cevap kaybolduysa antrenman sunucuda başlamış olabilir
    }
    if(r && typeof r.energy === 'number') { energy.current = r.energy; trSaveEnergy(energy); }
    return;
  }
  energy.current = r.energy;
  trSaveEnergy(energy);
  if (energy.current < 3 && typeof rhIste === 'function') rhIste('enerji');   // 663 — günün enerjisi bitti
  _wlApplyLocal(-r.euro, 0, 'out');
  _wlGunlukOnbellek = null;

  // 739 — antrenman kaydı sunucuda biletle aynı anda oluştu · 740 — yalnız bu kayıt eklenir
  if (r.entry && r.entry.id) {
    _trSunucuEkle([r.entry]);
    trCloseModal();
    trRender();
    _bldMacTara(true);   // 774
    return;
  }
  // Aktif listeye ekle
  const newEntry = {
    id: 'tr_' + Date.now(),
    pos, skillId,
    skillName: skill.name,
    playerName: (authUser||{}).name || 'Sen',
    mins,
    startTime: Date.now(),
    endTime: Date.now() + mins * 60 * 1000,
    gainPoints: trGainPoints(mins),
    gainXP: trGainXP(mins),
    level: d.level,
  };
  active.push(newEntry);
  trSaveActive(active);

  trCloseModal();
  // 🆕 'antrenman başladı' toast'ı kaldırıldı (modal yeterli)
  trRender();
}

// 739 — başlatma cevabı ulaşmadıysa aktif listeyi, enerjiyi ve cüzdanı sunucudan tazele
async function _trAktifTazele() {
  try {
    const { data } = await window.sb.from('user_player').select('active_trainings').eq('user_id', authUser.id).maybeSingle();
    if (data && Array.isArray(data.active_trainings)) { _trSunucuEkle(data.active_trainings); trRender(); }
  } catch (e) {}
  try { await _energyLoadFromServer(); syncEnergyDisplay(); } catch (e) {}
  try { await wlLoadFromServer(); } catch (e) {}
}
// 740 — sunucudaki kayıtlardan ekranda olmayanları ekle (toplanmakta olanlar hariç)
const _trToplaniyor = new Set();
function _trSunucuEkle(list) {
  const ac = trGetActive(), var_ = new Set(ac.map(a => a && a.id));
  const ek = (list || []).filter(a => a && a.id && !var_.has(a.id) && !_trToplaniyor.has(a.id));
  if (ek.length) _activeCache = ac.concat(ek);
}
// 739 — liste bütün olarak yazılmaz (eski ekran başka kaydı silebiliyordu): yalnız ilgili antrenman işaretlenir
function _trIsaret(ids, tur) {
  if (!ids.length || !window.sb) return;
  window.sb.rpc('antrenman_isaret', { p_ids: ids, p_tur: tur })
    .then(({ error }) => { if (error) console.warn('[antrenman_isaret]', error.message); });
}

// ── Antrenman topla ──
// 🆕 ANLIK TAKIM GÜCÜ — yetenek/mevki değişince sunucuda tek-takım team_ovr yeniden hesaplanır,
//   dönen değerle yerel TEK KAYNAK (_teamOvrMap + CFT_DB.teamOvr) tazelenir → hero, Sıralama>Takımlar
//   ve ana sayfa maç önizleme ANINDA güncel olur. Tüm dünya taranmaz, sadece bu takım.
async function _recomputeTeamOvrServer(cc, name){
  if(!cc || !name) return null;
  try{
    const url = `${SUPABASE_URL}/functions/v1/tick-matches?action=recompute_team&cc=${encodeURIComponent(cc)}&name=${encodeURIComponent(name)}`;
    const _jwt = await _oturumJwt();   // 🔒 565 — oturum zorunlu
    if (!_jwt) return null;
    const r = await fetch(url, { headers: { 'Authorization': 'Bearer ' + _jwt, 'apikey': SUPABASE_KEY } });
    const d = r.ok ? await r.json() : null;
    if(d && d.ok && typeof d.team_ovr === 'number'){
      const key = cc + ':' + name;
      const ov = Math.round(d.team_ovr);
      window._teamOvrMap = window._teamOvrMap || {};
      window._teamOvrMap[key] = ov;
      if(d.team_lines && typeof d.team_lines === 'object'){
        window._teamLinesMap = window._teamLinesMap || {};
        window._teamLinesMap[key] = d.team_lines;
      }
      try{
        const ctry = (typeof _cftGetCountry==='function') ? _cftGetCountry(cc) : null;
        if(ctry && ctry.leagues){
          for(const lg of ctry.leagues){
            const t=(lg.teams||[]).find(x=>x&&x.name===name);
            if(t){ t.teamOvr=ov; if(typeof d.market_value==='number') t.oz=d.market_value; break; }
          }
        }
      }catch(e){}
      // Hero "Ort. Güç" anında (kullanıcının kendi takımıysa)
      try{
        if(typeof _userTeam!=='undefined' && _userTeam && _userTeam.countryCode===cc && _userTeam.teamName===name){
          const _el=document.getElementById('teamHeroPower');
          if(_el && ov>0) _el.textContent=String(ov);
        }
      }catch(e){}
      // Sıralama > Takımlar açıksa tazele
      try{ if(typeof _rkListCache==='object' && _rkListCache){ delete _rkListCache['teams|overall']; delete _rkListCache['teams|coef']; delete _rkListCache['teams|market']; } }catch(e){}
      try{ if(typeof _rkActiveTab!=='undefined' && _rkActiveTab==='teams' && typeof rkRenderTeams==='function') rkRenderTeams(); }catch(e){}
    }
    return d;
  }catch(e){ console.warn('[recomputeTeamOvr]', e); return null; }
}

async function trCollect(id) {
  const active  = trGetActive();
  const entry   = active.find(a => a.id === id);
  if(!entry) return;

  const now = Date.now();
  if(now < entry.endTime) { trToast('Antrenman henüz bitmedi!', '#ff9800'); return; }
  if (_trToplaniyor.has(id)) return;
  _trToplaniyor.add(id);

  // 🆕 OPTIMISTIC: sonucu istemcide (sunucuyla AYNI formülle) hesaplayıp ANINDA göster.
  //   train_collect RPC arkada çalışıp kesin değerle sessizce eşitler (skills kolonu sunucu-korumalı).
  const pos = entry.pos, skillId = entry.skillId;
  const _gpE = (typeof entry.gainPoints === 'number' && entry.gainPoints > 0) ? entry.gainPoints : (entry.mins||0) * 100 / 3;   // 760 — pilav bonusu dahil
  const gainPoints = Math.round(_gpE);
  const gainXP = entry.gainXP || 0;

  if(!_skillsCache) _skillsCache = {};
  if(!_skillsCache[pos]) _skillsCache[pos] = {};
  const cur = _skillsCache[pos][skillId] || { level: 10, points: 0 };
  const oldLevel = cur.level || 10;
  let level = oldLevel, points = (cur.points||0) + _gpE;
  let _g = 0;
  while(points >= trPointsNeeded(level) && _g++ < 100000) { points -= trPointsNeeded(level); level++; }
  const newLevel = level;
  const leveledUp = newLevel > oldLevel;
  _skillsCache[pos][skillId] = { level: newLevel, points };

  // Aktiften çıkar (optimistic)
  _activeCache = (Array.isArray(_activeCache) ? _activeCache : active).filter(a => a.id !== id);

  // Oyuncu XP (players tablosu; skills'ten ayrı)
  const userPlayer = ROSTER_DATA.find(p => p.role === 'user');
  let playerLevelUp = null;
  if(userPlayer) {
    playerLevelUp = rosterAwardXp(userPlayer.num, gainXP);
  }

  // Tamamlandı modal — ANINDA göster
  const skillInfo = (TR_SKILLS[entry.pos]||[]).find(s=>s.id===entry.skillId);
  document.getElementById('trDoneBody').innerHTML = `
    <div class="tdn-rozet"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg></div>
    <div class="tdn-title">Antrenman Tamam!</div>
    <div class="tdn-sub"><svg class="tdn-ic"><use href="#ic-training"/></svg><span><b>${entry.skillName}</b> · ${entry.mins} dakika</span></div>
    <div class="tdn-stats">
      <div class="tdn-stat">
        <svg class="tdn-ic"><use href="#ic-bolt"/></svg>
        <div class="tdn-stat-val">+${gainPoints}</div>
        <div class="tdn-stat-lbl">Puan</div>
      </div>
      <div class="tdn-stat xp">
        <svg class="tdn-ic"><use href="#ic-fin-up"/></svg>
        <div class="tdn-stat-val">+${gainXP}</div>
        <div class="tdn-stat-lbl">XP</div>
      </div>
    </div>
    ${leveledUp ? `<div class="tdn-levelup"><span>Yetenek</span><b>${oldLevel}</b><svg viewBox="0 0 24 24"><path d="M5 12h14M13 6l6 6-6 6"/></svg><b>${newLevel}</b></div>` : ''}
    <button class="tdn-btn" onclick="trCloseDone()">Tamam</button>`;
  try { document.getElementById('trModal')?.classList.remove('open'); } catch(e){}  // 🆕 başlat modalı açıksa kapat (çakışma önle)
  document.getElementById('trDoneModal').classList.add('open');
  if (leveledUp && typeof rhIste === 'function') rhIste('milli');   // 663 — "Tamam" denince açılır

  if(typeof updateTopbarFromUser === 'function') updateTopbarFromUser();

  try{
    if(typeof achBump === 'function') achBump('train');
    if(typeof evRefreshBadge === 'function') evRefreshBadge();
  }catch(e){}

  try{
    const trainLog = getUserTrainLog();
    trainLog.push({ ts: Date.now(), energy: entry.mins });
    saveUserTrainLog(trainLog);
  }catch(e){}

  try { _evRaceServerLbCache.train = null; } catch(e) {}
  try {
    if (typeof _evRacePreloadServerLb === 'function') {
      _evRacePreloadServerLb(['train']).then(() => {   // 798 — yalnız antrenman sıralaması
        if (typeof renderHomeEventFeed === 'function') renderHomeEventFeed();
        const evPage = document.getElementById('page-events');
        if (evPage && evPage.classList.contains('active') && typeof evRaceRender === 'function') {
          evRaceRender();
        }
      });
    }
  } catch(e) {}

  trRender();

  // 🆕 Sunucu doğrulaması — AWAIT edilir: hızlı sekme geçişi/yenilemede istek iptal
  //   olup toplama SUNUCUYA yazılmadan kaybolmasın. Modal zaten yukarıda gösterildiği
  //   için his hâlâ ANINDA; burada sadece sunucu onayını bekleyip kesin değerle eşitliyoruz.
  // 🆕 560 — Sunucu yoğunken istek hata verirse eskiden yalnızca konsola yazılıyordu:
  //   ekranda toplanmış görünüp sunucuda toplanmamış kalıyordu. Artık 1 kez yeniden
  //   denenir; yine olmazsa iyimser değişiklik geri alınır ve kullanıcıya söylenir.
  let r = null;
  for (let _den = 0; _den < 2; _den++) {
    try {
      r = await window.sb.rpc('train_collect', { p_id: id });
      // 598 — "Hemen Bitir" ödemesi sunucuya yeni ulaştıysa bir kez daha dene
      if (r && !r.error && r.data && r.data.ok === false && r.data.error === 'not_done' && _den === 0) {
        await new Promise(res => setTimeout(res, 2500));
        continue;
      }
      if (r && !r.error) break;
      console.warn('[trCollect] rpc hata:', r && r.error);
    } catch(e) { r = null; console.warn('[trCollect] rpc hata:', e); }
    if (_den === 0) await new Promise(res => setTimeout(res, 2500));
  }
  _trToplaniyor.delete(id);
  if (r && !r.error && r.data && r.data.ok) {
    if (r.data.skills) _skillsCache = r.data.skills;
    _activeCache = trGetActive().filter(a => a.id !== id);
    if (typeof trRenderSkills === 'function') { try { trRenderSkills(); } catch(e){} }
    else if (typeof trRender === 'function') { try { trRender(); } catch(e){} }
  } else if (r && !r.error) {
    // 598 — sunucu reddetti: ekrandaki iyimser değişikliği geri al (süre/enerji sunucuda doğrulanıyor)
    console.warn('[trCollect] sunucu reddetti:', r && r.data);
    const _hk = (r.data && r.data.error) || '';
    try {
      if (_skillsCache && _skillsCache[pos]) _skillsCache[pos][skillId] = cur;
      if (_hk === 'bilet_yok' || _hk === 'not_found') {
        _activeCache = trGetActive().filter(a => a.id !== id);   // sunucuda bu antrenman yok / kaldırıldı
      } else {
        const _ac = Array.isArray(_activeCache) ? _activeCache : [];
        if (!_ac.some(a => a && a.id === id)) _activeCache = _ac.concat([entry]);
      }
      document.getElementById('trDoneModal')?.classList.remove('open');
      trRender();
    } catch(e) {}
    trToast(T(_hk === 'not_done' ? 'Antrenman henüz bitmedi!'
      : _hk === 'bilet_yok' ? 'Bu antrenmanın enerjisi sunucuya ulaşmamış; antrenman iptal edildi.'
      : 'Antrenman toplanamadı.'), '#e53935');
    return;
  } else {
    // Sunucuya yazılamadı → geri al: yetenek eski haline, antrenman tekrar "toplanabilir"
    try {
      if (_skillsCache && _skillsCache[pos]) _skillsCache[pos][skillId] = cur;
      const _ac = Array.isArray(_activeCache) ? _activeCache : [];
      if (!_ac.some(a => a && a.id === id)) _activeCache = _ac.concat([entry]);
      document.getElementById('trDoneModal')?.classList.remove('open');
      trRender();
    } catch(e) {}
    trToast(T('Sunucuya ulaşılamadı, antrenman toplanmadı. Biraz sonra tekrar dene.'), '#e53935');
    return;
  }

  // 🆕 Yetenek arttı → OVR'yi sunucuda tazele. Bloke etmez.
  //   Takımı varsa: recompute_team tüm kadronun players.overall'ını da yazar.
  //   Takımsızsa: recompute_team çağrılamıyor, kendi satırı için refresh_ovr.
  try{
    if(typeof _userTeam!=='undefined' && _userTeam && _userTeam.teamName){
      _recomputeTeamOvrServer(_userTeam.countryCode, _userTeam.teamName);
    } else if (typeof edgeCall === 'function') {
      edgeCall('refresh_ovr', {}).catch(()=>{});
    }
  }catch(e){}
}

function trCloseDone() {
  document.getElementById('trDoneModal').classList.remove('open');
  // 🆕 Modal kapanınca arayüzü yenile (aktif liste boş gözüksün, yetenek puanları güncel olsun)
  try { trRender(); } catch(e) {}
}

// ── Hemen Bitir ──
function trInstantFinish(id, mins) {
  // 🆕 Maliyet: dakika kadar elmas (3dk→3💎, 6dk→6💎, 9dk→9💎)
  const diamondCost = mins;
  if(typeof trsCanAfford !== 'function' || !trsCanAfford('dia', diamondCost)) {
    const bal = (typeof trsGetBalance==='function' ? trsGetBalance('dia') : 0).toLocaleString('tr');
    trToast(`❌ Yetersiz Diamond! Gerekli: ${diamondCost}💎 · Mevcut: ${bal}💎`, '#ef5350');
    return;
  }
  trsDeduct('dia', diamondCost, 'Antrenman Atlama');

  // Antrenmanı bitmiş say (endTime'ı geçmişe al)
  const active = trGetActive();
  const idx = active.findIndex(a => a.id === id);
  if(idx !== -1) {
    active[idx].endTime = Date.now() - 1;
    _trIsaret([id], 'bitir');
  }

  // 🆕 'anında tamamlandı' toast'ı kaldırıldı (Topla modali yeterli)
  trRenderActive();
  trRenderSkills();
}

// ── Timer tick ──
function trStartTimers() {
  if(_trTimerInterval) clearInterval(_trTimerInterval);
  _trTimerInterval = setInterval(() => {
    const active = trGetActive();
    if(!active.length) return;
    const now = Date.now();
    active.forEach(a => {
      const remaining = Math.max(0, a.endTime - now);
      if(remaining === 0) {
        trRenderActive(); // üst kart (gizli) güncelle
        trRenderSkills(); // 🆕 kutu içi: geri sayım → Topla
        return;
      }
      const mins = Math.floor(remaining / 60000);
      const secs = Math.floor((remaining % 60000) / 1000);
      const timerStr = `${mins}:${secs.toString().padStart(2,'0')}`;
      // Üst kart timer'ı (varsa)
      const el = document.getElementById('trTimer_' + a.id);
      if(el) el.textContent = timerStr;
      // 🆕 Kutu içi sayaç + dolan bar
      const skEl = document.getElementById('trSkTimer_' + a.id);
      if(skEl) skEl.textContent = timerStr;
      const skBar = document.getElementById('trSkBar_' + a.id);
      if(skBar) {
        const total = Math.max(1, a.endTime - a.startTime);
        const elapsedPct = Math.min(100, Math.round((total - remaining) / total * 100));
        skBar.style.width = elapsedPct + '%';
      }
    });
  }, 1000);
}

// 🆕 ── Arka plan antrenman bildirimi ──
// Kullanıcı diğer sayfalardayken biten antrenmanları izle, sağ üstten bildirim göster
function _trWatchCompleted() {
  if (typeof trGetActive !== 'function') return;
  const active = trGetActive();
  if (!active.length) return;
  const now = Date.now();
  // Antrenman sayfasında zaten "Topla ✓" butonu görünüyor — orada bildirim gereksiz
  const trPage = document.getElementById('page-training');
  const onTrPage = trPage && trPage.classList.contains('active');
  const yeni = [], biten = [];
  active.forEach(a => {
    if (a.notified) return;          // bu antrenman zaten bildirildi
    if (now < a.endTime) return;     // henüz bitmedi
    a.notified = true;
    yeni.push(a.id);
    if (!onTrPage) biten.push(a);
  });
  if (biten.length) _trEnqueueDoneNotif(biten);   // 823 — aynı anda bitenler tek bildirim
  _trIsaret(yeni, 'bildirildi');
}
// 823 — Tek bildirim: aynı anda bitenler birleşir; bildirim ekrandayken bitenler de ona eklenir (ses tekrar çalmaz)
function _trNotifYaz(notif) {
  const L = notif._trAdlar || [];
  const skillEl = notif.querySelector('.tr-done-notif-skill');
  if (skillEl) skillEl.textContent = L.length === 1 ? L[0] : L.length + ' antrenman';
}
function _trEnqueueDoneNotif(entry) {
  const L = (Array.isArray(entry) ? entry : [entry]).map(e => (e && e.skillName) || 'Antrenman');
  if (!L.length) return;
  if (!window._trNotifQueue) window._trNotifQueue = [];
  const notif = document.getElementById('trDoneNotif');
  if (notif && notif._showing && Array.isArray(notif._trAdlar)) {
    notif._trAdlar.push(...L); _trNotifYaz(notif);
    if (notif._hideTimer) clearTimeout(notif._hideTimer);   // okumaya vakit kalsın: 5 sn baştan
    notif._hideTimer = setTimeout(() => {
      notif.classList.remove('show'); notif._hideTimer = null; notif._showing = false;
      setTimeout(_trProcessNotifQueue, 450);
    }, 5000);
    return;
  }
  if (window._trNotifQueue.length) { window._trNotifQueue[window._trNotifQueue.length - 1].adlar.push(...L); return; }
  window._trNotifQueue.push({ adlar: L });
  _trProcessNotifQueue();
}

// 🆕 ════════════════════════════════════════════════════════
// MERKEZİ BİLDİRİM SESİ — CHIME (C5 + E5 iki nota)
// Tüm bildirimler (antrenman, item satıldı, kupon, maç, mesaj, haftalık) bu sesi çalar
// ════════════════════════════════════════════════════════
function _playNotifSound() {
  try {
    const c = window._notifAudioCtx;
    if (!c) return; // audio context henüz unlock edilmedi (kullanıcı etkileşimi bekleniyor)
    if (c.state !== 'running') {
      c.resume().catch(() => {});
    }
    // CHIME: C5 (523.25Hz) + E5 (659.25Hz), 80ms aralık, sine wave
    [523.25, 659.25].forEach((freq, i) => {
      setTimeout(() => {
        try {
          const o = c.createOscillator();
          const g = c.createGain();
          o.type = 'sine';
          o.frequency.value = freq;
          // Master gain: hafif ton (0.12 ≈ test sayfasında %40 volume × 0.3 base)
          g.gain.setValueAtTime(0.12, c.currentTime);
          g.gain.exponentialRampToValueAtTime(0.001, c.currentTime + 0.4);
          o.connect(g); g.connect(c.destination);
          o.start();
          o.stop(c.currentTime + 0.45);
        } catch(_) {}
      }, i * 80);
    });
  } catch(_) {}
}

// Sayfa açılışında ses kapalı (mobile autoplay policy gereği)
// İlk kullanıcı etkileşiminde audio context unlock olur
(function _unlockNotifAudio(){
  function unlock() {
    try {
      if (!window._notifAudioCtx) {
        window._notifAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
      }
      if (window._notifAudioCtx.state !== 'running') {
        window._notifAudioCtx.resume().catch(()=>{});
      }
    } catch(e) {}
  }
  document.addEventListener('click', unlock, true);
  document.addEventListener('touchstart', unlock, true);
  document.addEventListener('keydown', unlock, true);
})();
// ════════════════════════════════════════════════════════

function _trProcessNotifQueue() {
  const notif = document.getElementById('trDoneNotif');
  if (!notif) return;
  if (notif._showing) return; // zaten bir bildirim gösteriliyor, sırasını bekleyecek
  if (!window._trNotifQueue || !window._trNotifQueue.length) return;
  const next = window._trNotifQueue.shift();
  notif._showing = true;
  notif._trAdlar = Array.isArray(next.adlar) ? next.adlar.slice() : [next.skillName || 'Antrenman'];   // 823
  _trNotifYaz(notif);
  notif.classList.add('show');
  if (typeof _playNotifSound === 'function') _playNotifSound(); // 🆕 CHIME
  if (notif._hideTimer) clearTimeout(notif._hideTimer);
  notif._hideTimer = setTimeout(() => {
    notif.classList.remove('show');
    notif._hideTimer = null;
    notif._showing = false;
    // Slide-out animasyonu (~400ms) bitince sıradakine geç
    setTimeout(_trProcessNotifQueue, 450);
  }, 5000);
}
function trDoneNotifClick() {
  const notif = document.getElementById('trDoneNotif');
  if (notif) {
    if (notif._hideTimer) clearTimeout(notif._hideTimer);
    notif._hideTimer = null;
    notif.classList.remove('show');
    notif._showing = false;
  }
  // Antrenman sayfasına yönlendir
  if (typeof showPage === 'function') {
    const navBtn = (typeof findNavBtn === 'function') ? findNavBtn('training') : null;
    showPage('training', navBtn);
  }
  // Sıradaki bildirimleri iptal et (kullanıcı zaten antrenman sayfasına gidiyor)
  if (window._trNotifQueue) window._trNotifQueue.length = 0;
}
// 5sn'de bir kontrol et — yeterince sık (sıkıştırılmış antrenmanlar 3-9 dk)
if (!window._trNotifWatcherInterval) {
  window._trNotifWatcherInterval = setInterval(() => { if (document.hidden) return; _trWatchCompleted(); }, 5000);
  // Sayfa yüklendikten kısa süre sonra ilk kontrolü yap
  setTimeout(_trWatchCompleted, 1500);
}

// ══════════════════════════════════════════════════════════════
// 🆕 GENERIC APP BİLDİRİM SİSTEMİ
// 4 tip: coupon (toto), match (maç), inbox (mesaj), weekly (haftalık)
// Her bildirim sağ üstten slide-in, tıklayınca ilgili sayfaya yönlendirir
// ══════════════════════════════════════════════════════════════
window._appNotifQueue = window._appNotifQueue || [];
window._appNotifShowing = false;
window._appNotifCurrent = null;

function _showAppNotif(opts) {
  if (!opts || !opts.type) return;
  // 🆕 540 — uygulama arka plandaysa aynı olayı telefon bildirimi olarak da gönder
  try {
    if (document.hidden && typeof _bldAnlik === 'function') {
      const _T2 = (typeof T === 'function') ? T : (x => x);
      _bldAnlik(_T2(opts.title || 'Bildirim'), _T2(opts.message || ''));
    }
  } catch(e){}
  window._appNotifQueue.push(opts);
  _processAppNotifQueue();
}

function _processAppNotifQueue() {
  const notif = document.getElementById('appNotif');
  if (!notif) return;
  if (window._appNotifShowing) return;
  if (!window._appNotifQueue.length) return;

  const next = window._appNotifQueue.shift();
  window._appNotifShowing = true;
  window._appNotifCurrent = next;

  // Eski tüm type-* class'larını temizle, yenisini ekle
  notif.classList.remove('type-coupon', 'type-match', 'type-inbox', 'type-weekly');
  notif.classList.add('type-' + next.type);

  const iconEl  = document.getElementById('appNotifIcon');
  const titleEl = document.getElementById('appNotifTitle');
  const msgEl   = document.getElementById('appNotifMsg');
  if (iconEl)  iconEl.textContent  = next.icon  || '🔔';
  if (titleEl) titleEl.textContent = next.title || 'Bildirim';
  if (msgEl)   msgEl.textContent   = next.message || '—';

  notif.classList.add('show');
  if (typeof _playNotifSound === 'function') _playNotifSound(); // 🆕 CHIME

  // Otomatik kapanma (5 saniye)
  if (notif._hideTimer) clearTimeout(notif._hideTimer);
  notif._hideTimer = setTimeout(() => {
    notif.classList.remove('show');
    notif._hideTimer = null;
    window._appNotifShowing = false;
    window._appNotifCurrent = null;
    setTimeout(_processAppNotifQueue, 450);
  }, 5000);
}

function _appNotifClick() {
  const notif = document.getElementById('appNotif');
  const cur = window._appNotifCurrent;
  if (notif) {
    if (notif._hideTimer) clearTimeout(notif._hideTimer);
    notif._hideTimer = null;
    notif.classList.remove('show');
    window._appNotifShowing = false;
  }
  // Tıklanan bildirim tipine göre yönlendirme
  if (cur && typeof cur.onClick === 'function') {
    try { cur.onClick(); } catch(e) { console.warn('appNotif onClick:', e); }
  }
  window._appNotifCurrent = null;
  // Aynı tip kuyruğu temizle (kullanıcı zaten o sayfaya gidiyor)
  if (cur) {
    window._appNotifQueue = window._appNotifQueue.filter(q => q.type !== cur.type);
  }
}

