function trToast(msg, color) {
  const t = document.createElement('div');
  const tc = (color==='var(--accent)'||color==='var(--gold)') ? 'var(--bg)' : '#fff';
  t.style.cssText = `position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:${color};color:${tc};padding:10px 18px;border-radius:12px;font-size:11px;font-weight:700;z-index:9999;font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;text-align:center;max-width:300px;box-shadow:0 4px 20px rgba(0,0,0,.5)`;
  t.textContent = msg;
  document.body.appendChild(t);
  setTimeout(()=>t.remove(), 3000);
}






// ═══════════════════════════════════════
//   TAKIM PAZARI (TEAM MARKETPLACE)
// ═══════════════════════════════════════
// Kullanıcılar takımlarını listeleyebilir, başkaları satın alabilir.
// Ayrıca demo bot listing'leri sezon başında oluşturulur (oyun ekosistemi için).
const TM_KEY = 'cft_team_market';
const TM_MIN_DIA = 150;     // 623 — takımlar yalnız elmasla satılır; en düşük fiyat (sunucu da denetler)

// 🆕 Transfer Market RAM cache - Supabase tek doğru kaynak
let _tmCache = null;  // null = henüz yüklenmedi, [] = yüklendi+boş
let _tmLoadingPromise = null;

async function _tmLoadFromServer() {
  if (!window.sb) return [];
  try {
    const { data, error } = await window.sb.from('transfer_listings')
      .select('*')
      .order('created_at', { ascending: false })
      .limit(500);
    if (error) { console.warn('[transfers] load hata:', error); return []; }
    // DB row → frontend listing format
    return (data || []).map(r => ({
      id: r.id,
      owner: r.owner_tag,
      ownerUserId: r.owner_user_id,
      countryCode: r.country_code,
      teamName: r.team_name,
      tierIdx: r.tier_idx,
      currency: r.currency,
      price: r.price,
      createdAt: new Date(r.created_at).getTime(),
      // Esnek payload
      ...(r.data || {})
    }));
  } catch(e) { console.warn('[transfers] load exception:', e); return []; }
}

function tmGetListings(){
  // Cache yoksa boş dön + arka planda yükle
  if (_tmCache === null) {
    if (!_tmLoadingPromise) {
      _tmLoadingPromise = _tmLoadFromServer().then(arr => {
        _tmCache = arr;
        _tmLoadingPromise = null;
        // Eğer transfer sayfası açıksa render et
        try {
          if (typeof tfRender === 'function' && document.getElementById('page-transfers') && document.getElementById('page-transfers').classList.contains('active')) {
            tfRender();
          }
        } catch(e) {}
      });
    }
    return [];
  }
  return _tmCache;
}

function tmSaveListings(arr){
  // Yeni mimari: tek tek upsert/delete yapıyoruz, tüm array overwrite yok.
  // Bu fonksiyon backward-compat için kalır ama Supabase'e direkt yazmaz.
  _tmCache = arr;
}

async function tmAddListing(listing){
  // Cache'e ekle
  if (_tmCache === null) _tmCache = [];
  _tmCache.unshift(listing);
  // Supabase'e yaz
  if (window.sb) {
    try {
      const payload = {
        id: listing.id,
        owner_tag: listing.owner || null,
        owner_user_id: listing.ownerUserId || (typeof authUser !== 'undefined' && authUser ? authUser.id : null),
        country_code: listing.countryCode || null,
        team_name: listing.teamName || null,
        tier_idx: typeof listing.tierIdx === 'number' ? listing.tierIdx : null,
        currency: 'dia',
        price: listing.price || 0,
        data: Object.assign({}, listing),  // tüm orijinal field'lar jsonb'de
        created_at: new Date(listing.createdAt || Date.now()).toISOString()
      };
      // jsonb'den DB kolonlarını çıkar (duplicate olmasın)
      delete payload.data.id; delete payload.data.owner; delete payload.data.ownerUserId;
      delete payload.data.countryCode; delete payload.data.teamName; delete payload.data.tierIdx;
      delete payload.data.currency; delete payload.data.price; delete payload.data.createdAt;
      const { error } = await window.sb.from('transfer_listings').insert(payload);
      if (error) console.warn('[transfers] insert hata:', error);
    } catch(e) { console.warn('[transfers] add exception:', e); }
  }
}

async function tmRemoveListing(id){
  // Cache'ten çıkar
  if (Array.isArray(_tmCache)) {
    _tmCache = _tmCache.filter(l => l.id !== id);
  }
  // Supabase'ten sil
  if (window.sb) {
    try {
      const { error } = await window.sb.from('transfer_listings').delete().eq('id', id);
      if (error) console.warn('[transfers] delete hata:', error);
    } catch(e) {}
  }
}

async function tmUpdateListing(id, patch){
  if (Array.isArray(_tmCache)) {
    const idx = _tmCache.findIndex(l => l.id === id);
    if (idx >= 0) {
      _tmCache[idx] = Object.assign({}, _tmCache[idx], patch);
    }
  }
  if (window.sb) {
    try {
      // Patch içinde DB kolonu olanları ayır, kalanı data'ya
      const dbCols = {};
      if (typeof patch.price === 'number') dbCols.price = patch.price;
      if (patch.currency) dbCols.currency = patch.currency;
      // Diğer alanlar: önce mevcut data'yı çek, üzerine yaz
      const { data: cur } = await window.sb.from('transfer_listings')
        .select('data').eq('id', id).maybeSingle();
      const newData = Object.assign({}, (cur && cur.data) || {}, patch);
      // DB kolonlarını data'dan temizle
      delete newData.price; delete newData.currency; delete newData.id;
      delete newData.owner; delete newData.ownerUserId;
      delete newData.countryCode; delete newData.teamName; delete newData.tierIdx;
      delete newData.createdAt;
      dbCols.data = newData;
      const { error } = await window.sb.from('transfer_listings').update(dbCols).eq('id', id);
      if (error) console.warn('[transfers] update hata:', error);
    } catch(e) {}
  }
}

// Kullanıcının kendi listing'i (varsa) — owner='__user__' tag'i ile
function tmFindUserListing(){
  // 🆕 558: '__user__' etiketi tüm kullanıcı ilanlarında aynı — ilan sahibini kişiye göre bul
  return tmGetListings().find(l => _tmBenimMi(l)) || null;
}
// 🆕 558 — İlan bu oyuncunun mu? (ilan sahibinin kullanıcı kimliği; eski ilanlarda kaptanı olduğu takım)
function _tmBenimMi(l){
  if (!l) return false;
  const uid = (typeof authUser !== 'undefined' && authUser && authUser.id) || null;
  if (l.ownerUserId && uid) return String(l.ownerUserId) === String(uid);
  const ut = (typeof _userTeam !== 'undefined' && _userTeam) || null;
  return !!(ut && ut.role === 'captain' && ut.teamName === l.teamName && (!l.countryCode || ut.countryCode === l.countryCode));
}

// Önerilen fiyat: takım kalitesine göre (Takım Satın Al fiyatı baz alınır + %30)
function tmSuggestedPrice(team, tierIdx){
  return Math.max(TM_MIN_DIA, Math.round(calcTeamPrice(team.pop, team.rating, tierIdx) * 1.3 / 50) * 50);
}

// ── Listing Modal aç ──
function tmOpenListingModal(){
  // Ziyaretçi modunda kesinlikle çalışmaz
  if(typeof _viewingTeam !== 'undefined' && _viewingTeam){
    if(typeof showJoinToast === 'function') showJoinToast('⚠️ Bu başkasının takımı.');
    return;
  }
  if(!userHasTeam() || !_userTeam || _userTeam.role !== 'captain'){
    if(typeof showJoinToast === 'function') showJoinToast('Bu işlem sadece kaptana özeldir.');
    return;
  }
  const cc = _userTeam.countryCode;
  const country = (true) ? _cftGetCountry(cc) : null;
  if(!country) return;

  // Takım bilgilerini bul
  let team = null, tierIdx = 0, leagueName = 'Lig';
  for(let i = 0; i < country.leagues.length; i++){
    const lg = country.leagues[i];
    const t = lg.teams.find(x => x.name === _userTeam.teamName);
    if(t){ team = t; tierIdx = i; leagueName = lg.name; break; }
  }
  if(!team) return;

  // Modal içeriği
  const flag = country.flag;
  document.getElementById('tlmTeamFlag').textContent = flag;
  document.getElementById('tlmTeamName').textContent = _userTeam.teamName;
  document.getElementById('tlmTeamMeta').textContent = `${country.name} · ${leagueName} · ${(team.pop||0).toLocaleString('tr')} nüfus`;
  document.getElementById('tlmTeamRating').textContent = '★ ' + (team.rating || 50);

  // State'i taze ayarla
  const existing = tmFindUserListing();
  if(existing){
    // Zaten listede — düzenleme modu
    document.getElementById('tlmTitle').textContent = '💸 Listemi Düzenle';
    document.getElementById('tlmConfirmBtn').textContent = '✓ Fiyatı Güncelle';
    // Vazgeç + İlanı Kaldır + Güncelle: 3 buton
    document.getElementById('tlmActions').innerHTML = `
      <button class="tlm-btn tlm-btn-cancel" onclick="tmCloseListingModal()">Vazgeç</button>
      <button class="tlm-btn tlm-btn-cancel-listing" onclick="tmCancelMyListing()">İlanı Kaldır</button>
      <button class="tlm-btn tlm-btn-confirm" id="tlmConfirmBtn" onclick="tmSubmitListing()">✓ Güncelle</button>
    `;
    document.getElementById('tlmPriceInput').value = existing.price;
  } else {
    document.getElementById('tlmTitle').textContent = '💸 Takımı Satışa Çıkar';
    document.getElementById('tlmActions').innerHTML = `
      <button class="tlm-btn tlm-btn-cancel" onclick="tmCloseListingModal()">Vazgeç</button>
      <button class="tlm-btn tlm-btn-confirm" id="tlmConfirmBtn" onclick="tmSubmitListing()">✓ Satışa Çıkar</button>
    `;
    document.getElementById('tlmPriceInput').value = '';
  }

  tmRefreshSuggestion(team, tierIdx);
  tmHideError();
  document.getElementById('tlmOverlay').classList.add('open');
}

function tmCloseListingModal(){
  document.getElementById('tlmOverlay').classList.remove('open');
}

function tmRefreshSuggestion(team, tierIdx){
  if(!team) return;
  const sug = tmSuggestedPrice(team, tierIdx);
  const txt = document.getElementById('tlmSuggestedText');
  if(txt) txt.innerHTML = `Önerilen fiyat: <b>${sug.toLocaleString('tr')} 💎</b>`;
}

function tmGetCurrentTeamData(){
  if(!_userTeam) return null;
  const country = _cftGetCountry(_userTeam.countryCode);
  if(!country) return null;
  for(let i = 0; i < country.leagues.length; i++){
    const t = country.leagues[i].teams.find(x => x.name === _userTeam.teamName);
    if(t) return { team: t, tierIdx: i, country };
  }
  return null;
}

function tmSetQuickPrice(n){
  const inp = document.getElementById('tlmPriceInput');
  if(inp){ inp.value = n; tmValidateListingPrice(); }
}

function tmShowError(msg){
  const el = document.getElementById('tlmError');
  if(el){ el.textContent = msg; el.classList.add('show'); }
}
function tmHideError(){
  const el = document.getElementById('tlmError');
  if(el){ el.textContent = ''; el.classList.remove('show'); }
}

function tmValidateListingPrice(){
  const inp = document.getElementById('tlmPriceInput');
  if(!inp) return false;
  const val = parseInt(inp.value || '0') || 0;
  if(val < TM_MIN_DIA){
    tmShowError(`Minimum fiyat ${TM_MIN_DIA.toLocaleString('tr')} 💎 olmalı.`);
    return false;
  }
  tmHideError();
  return true;
}

// ── Listele/Güncelle ──
function tmSubmitListing(){
  if(!_userTeam || _userTeam.role !== 'captain') return;
  if(!tmValidateListingPrice()) return;

  const inp = document.getElementById('tlmPriceInput');
  const price = parseInt(inp.value || '0') || 0;

  const td = tmGetCurrentTeamData();
  if(!td){ tmShowError('Takım bilgileri bulunamadı.'); return; }

  const existing = tmFindUserListing();
  if(existing){
    // Güncelle
    tmUpdateListing(existing.id, { price, currency: 'dia', updatedAt: Date.now() });
    if(typeof showJoinToast === 'function') showJoinToast(`✅ İlanın güncellendi: ${price.toLocaleString('tr')} 💎`);
  } else {
    // Yeni ilan
    const userName = (window.authUser && authUser.name) ? authUser.name : 'Kaptan';
    const listing = {
      id: 'tml_' + Date.now() + '_' + Math.floor(Math.random()*9999),
      owner: '__user__',
      sellerName: userName,
      countryCode: _userTeam.countryCode,
      teamName: _userTeam.teamName,
      tierIdx: td.tierIdx,
      rating: td.team.rating || 50,
      pop: td.team.pop || 0,
      price,
      currency: 'dia',
      listedAt: Date.now(),
    };
    tmAddListing(listing);
    if(typeof showJoinToast === 'function') showJoinToast(`✅ Takımın satışa çıkarıldı: ${price.toLocaleString('tr')} 💎`);
  }
  tmCloseListingModal();
  tmRefreshListButton();
  // Mağaza açıksa listing'i göster
  if(typeof renderTeamMarket === 'function') renderTeamMarket();
}

// İlanı kaldır
function tmCancelMyListing(){
  const ex = tmFindUserListing();
  if(!ex) return;
  cftConfirm({
    title: 'İlanı Kaldır',
    message: 'İlanını kaldırmak istediğine emin misin? Takımın hala senin olacak.',
    confirmText: 'Kaldır',
    danger: true,
    onConfirm: () => {
      tmRemoveListing(ex.id);
      tmCloseListingModal();
      tmRefreshListButton();
      if(typeof renderTeamMarket === 'function') renderTeamMarket();
      if(typeof showJoinToast === 'function') showJoinToast('🗑️ İlan kaldırıldı.');
    }
  });
}

// "Takımı Satışa Çıkar" butonunun durumunu yansıt
function tmRefreshListButton(){
  const btn = document.getElementById('btnListTeam');
  const lbl = document.getElementById('btnListTeamLabel');
  if(!btn || !lbl) return;
  const existing = tmFindUserListing();
  if(existing){
    btn.classList.add('listed');
    lbl.textContent = `Satışta: ${existing.price.toLocaleString('tr')} 💎 · İlanı Düzenle`;
  } else {
    btn.classList.remove('listed');
    lbl.textContent = 'Takımı Satışa Çıkar';
  }
}

// ── Mağaza takım listesi: sadece gerçek kaptanların satışa çıkardığı takımlar ──
//   (Botların sahte ilan/isim üretmesi tamamen kaldırıldı — tek dünya, gerçek veri.)



// ═══════════════════════════════════════
//   TAKVİM (CALENDAR) — Sezonun 40 günlük şablonu
// ═══════════════════════════════════════
//
// SEASON_TEMPLATE'i baz alarak kullanıcıya sezonun her günü ne olacağını gösterir.
// Bilgi amaçlı (bot haberleri/fikstür gibi gerçek maçları göstermez, sadece olay tipi).

let _calFilter = 'all';

function calSetFilter(f) {
  _calFilter = f;
  ['all','lig','trn','break','special'].forEach(k => {
    const btn = document.getElementById('calFlt' + k.charAt(0).toUpperCase() + k.slice(1));
    if(btn) btn.classList.toggle('active', _calFilter === k);
  });
  calRenderDays();
}

// Olay tipini → metadata
function calEventMeta(ev) {
  if(ev.type === 'lig') {
    return { cls:'ev-lig', icon:'⚽', label:`${ev.week}. Hafta Lig Maçı`, sub:'LİG' };
  }
  if(ev.type === 'chm') {
    return { cls:'ev-chm', icon:_cupLogoInline('champ',16), label:`Championship · ${ev.round||''}`, sub:'CHM' };
  }
  if(ev.type === 'eli') {
    return { cls:'ev-eli', icon:_cupLogoInline('elite',16), label:`Elite Ligi · ${ev.round||''}`, sub:'ELI' };
  }
  if(ev.type === 'con') {
    return { cls:'ev-con', icon:_cupLogoInline('conv',16), label:`Convergence · ${ev.round||''}`, sub:'CON' };
  }
  if(ev.type === 'enc') {
    return { cls:'ev-enc', icon:_cupLogoInline('natcup',16), label:`EURO National Cup · ${ev.round||''}`, sub:'EURO' };
  }
  if(ev.type === 'fed') {
    return { cls:'ev-fed', icon:'🏛️', label:`Federasyon · ${ev.round||''}`, sub:'FED' };
  }
  // Helper: label'ın başında emoji varsa temizler (icon ayrı render edileceği için çift olmasın)
  function _stripEmoji(s) {
    if(!s) return s;
    // Baştaki emoji + boşlukları temizle (Unicode emoji ranges)
    return s.replace(/^[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{2700}-\u{27BF}\u{1F000}-\u{1F02F}\u{1F0A0}-\u{1F0FF}\u{1F100}-\u{1F1FF}\u{1F200}-\u{1F2FF}\u{1F300}-\u{1F5FF}\u{1F600}-\u{1F64F}\u{1F680}-\u{1F6FF}\u{1F900}-\u{1F9FF}]+\s*/u, '').trim();
  }
  if(ev.type === 'break') {
    return { cls:'ev-break', icon:'🔄', label: _stripEmoji(ev.label) || 'Transfer Dönemi', sub:'ARA' };
  }
  if(ev.type === 'special') {
    return { cls:'ev-special', icon:'⭐', label: _stripEmoji(ev.label) || 'Özel Olay', sub:'ÖZEL' };
  }
  return { cls:'', icon:'📌', label: ev.label || 'Olay', sub:'' };
}

// Bir günün dönem etiketi (1. günse "sezon başı", 38. günse "sezon sonu" vs.)
// Verilen sezon-gününe denk gelen gerçek tarihi 'D MMM' formatında döner
function calFormatDayDate(day) {
  try {
    const info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : null;
    let baseStart;
    if(info && info.seasonStart) {
      baseStart = new Date(info.seasonStart);
    } else if(typeof SEASON_EPOCH !== 'undefined') {
      baseStart = new Date(SEASON_EPOCH);
    } else {
      baseStart = new Date();
    }
    const dt = new Date(baseStart);
    dt.setDate(baseStart.getDate() + (day - 1));
    const months = ['Oca','Şub','Mar','Nis','May','Haz','Tem','Ağu','Eyl','Eki','Kas','Ara'];
    return dt.getDate() + ' ' + months[dt.getMonth()];
  } catch(e) {
    return '';
  }
}

function calDayLabel(day) {
  if(day === 1)  return 'Avrupa Play-off · Sezon Başı';
  if(day === 2)  return 'Federasyon Seçimi · CON MD1';
  if(day === 3)  return 'Seçim Sonuçları (19:00)';
  if(day === 15) return 'CON/ELI Grup Aşaması Sonu';
  if(day === 16 || day === 17 || day === 18) return 'Ara Dönem';
  if(day === 19) return 'CHM Grup Aşaması Sonu';
  if(day === 30) return 'Avrupa Yarı Final Sonrası';
  if(day === 31) return 'CON Finali 🏆';
  if(day === 32) return 'ELI Finali 🏆';
  if(day === 33) return 'CHM Finali 🏆 · Lig Sonu';
  if(day === 34) return 'EURO Grup 1';
  if(day === 35) return 'EURO Grup 2';
  if(day === 36) return 'EURO Grup 3';
  if(day === 37) return 'EURO Son 16';
  if(day === 38) return 'EURO Çeyrek Final';
  if(day === 39) return 'EURO Yarı Final';
  if(day === 40) return 'EURO Final & Sezon Sonu';
  return `Gün ${day}`;
}

// Olayların filtreye uyup uymadığını kontrol et
function calEventMatches(ev, filter) {
  if(filter === 'all') return true;
  if(filter === 'lig') return ev.type === 'lig';
  if(filter === 'trn') return ['chm','eli','con','enc'].includes(ev.type);
  if(filter === 'break') return ev.type === 'break';
  if(filter === 'special') return ev.type === 'special' || ev.type === 'fed';
  return false;
}

function calRenderHeader() {
  // Sezon progress
  let info;
  try { info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : null; } catch(e) { info = null; }
  const season = info ? info.season : 1;
  const seasonLen = (typeof SEASON_LEN !== 'undefined') ? SEASON_LEN : 38;
  const day = info ? Math.max(0, Math.min(seasonLen, info.dayInSeason || 0)) : 0;
  const preSeason = info ? info.preSeason : true;

  const seasonEl = document.getElementById('calSeasonText');
  const dayEl    = document.getElementById('calDayText');
  const fill     = document.getElementById('calProgressFill');
  const subEl    = document.getElementById('calHeroSub');

  if(seasonEl) seasonEl.textContent = `Sezon ${season}`;
  if(dayEl)    dayEl.textContent    = preSeason ? 'Sezon Henüz Başlamadı' : `Gün ${day} / ${seasonLen}`;
  if(fill)     fill.style.width     = preSeason ? '0%' : `${(day/seasonLen*100).toFixed(0)}%`;
  if(subEl) {
    if(preSeason) {
      const days = info ? info.daysToStart : 0;
      subEl.textContent = `Sezona ${days} gün kaldı — sezon başlayınca her gün canlanacak`;
    } else if(day >= seasonLen) {
      subEl.textContent = 'Sezon sona erdi — yeni fikstürler oluşturuldu';
    } else {
      subEl.textContent = `Sezonun ${day}. gününde · ${seasonLen-day} gün kaldı`;
    }
  }
}

function closeRewardInfoModal(){ const m=document.getElementById('rewardInfoModal'); if(m) m.style.display='none'; }
function openRewardInfoModal(){
  try{
    const fmt = n => (Number(n)||0).toLocaleString('tr');
    const fmtC = n => { n=Number(n)||0; if(!n) return '\u2014'; if(n>=1000000){ const v=n/1000000; return (Number.isInteger(v)?String(v):v.toFixed(1).replace('.',','))+'M'; } if(n>=1000) return Math.round(n/1000)+'K'; return String(n); };
    const ligs=[1,2,3,4,5,6].map(t=>[_ligTierEtiketi(t),EKONOMI.lig[t]]);
    const cups=[['Championship',EKONOMI.kupa.champ],['Elite',EKONOMI.kupa.elite],['Convergence',EKONOMI.kupa.conv]];
    const colors=['#00e676','#42a5f5','#ab47bc','#ffa726','#ef5350','#8d6e63'];
    const ligRows=ligs.map(p=>`<tr><td>${p[0]}</td><td class="rwm-win">${fmt(p[1].galibiyet)}</td><td class="rwm-draw">${fmt(p[1].beraberlik)}</td></tr>`).join('');
    const cupRows=cups.map(p=>`<tr><td>${p[0]}</td><td class="rwm-win">${fmt(p[1].galibiyet)}</td><td class="rwm-draw">${fmt(p[1].beraberlik)}</td></tr>`).join('');
    const cs=EKONOMI.kupa.champ.asama, es=EKONOMI.kupa.elite.asama, vs=EKONOMI.kupa.conv.asama;
    const sr=(l,a,b,c,ch)=>`<tr><td>${l}</td><td class="${ch?'rwm-champ':''}">${fmtC(a)}</td><td class="${ch?'rwm-champ':''}">${fmtC(b)}</td><td class="${ch?'rwm-champ':''}">${fmtC(c)}</td></tr>`;
    const trnRows=sr('Play-off 2',cs.po2,es.po2,vs.po2)+sr('Gruba \u00e7\u0131k\u0131\u015f',cs.group,es.group,vs.group)+sr('Son 32',cs.r32,es.r32,vs.r32)+sr('Son 16',cs.r16,es.r16,vs.r16)+sr('\u00c7eyrek',cs.qf,es.qf,vs.qf)+sr('Yar\u0131',cs.sf,es.sf,vs.sf)+sr('Finalist',cs.finalist,es.finalist,vs.finalist)+sr('\u015eampiyon',cs.champion,es.champion,vs.champion,true);
    const rankRows=ligs.map((p,i)=>`<tr><td><span class="rwm-pill" style="background:${colors[i]}"></span>${p[0]}</td><td class="rwm-champ">${fmt(p[1].sampiyon)}</td></tr>`).join('');
    const html=`
      <div class="rwm-sec"><div class="rwm-sec-h"><span class="d"></span>Lig Ma\u00e7 \u00d6d\u00fclleri</div><table class="rwm-tbl"><tr><th>Lig</th><th>Galibiyet</th><th>Beraberlik</th></tr>${ligRows}</table></div>
      <div class="rwm-sec"><div class="rwm-sec-h"><span class="d"></span>Kupa Ma\u00e7 \u00d6d\u00fclleri</div><table class="rwm-tbl"><tr><th>Kupa</th><th>Galibiyet</th><th>Beraberlik</th></tr>${cupRows}</table></div>
      <div class="rwm-sec"><div class="rwm-sec-h"><span class="d"></span>Turnuva Tur & \u015eampiyonluk Bonusu</div><table class="rwm-tbl"><tr><th>A\u015fama</th><th>Champ.</th><th>Elite</th><th>Conv.</th></tr>${trnRows}</table></div>
      <div class="rwm-sec"><div class="rwm-sec-h"><span class="d"></span>Lig Sezon-Sonu S\u0131ralama (\u015eampiyon)</div><table class="rwm-tbl"><tr><th>Lig</th><th>\u015eampiyon \u00f6d\u00fcl\u00fc</th></tr>${rankRows}</table><div class="rwm-note">\u0130lk 16 s\u0131raya \u00f6d\u00fcl verilir; a\u015fa\u011f\u0131 s\u0131ralar kademeli azal\u0131r. De\u011ferler 1.\u2019lik i\u00e7indir.</div></div>
      <div class="rwm-note">\uD83C\uDFC6 <b>EURO National Cup</b> finansal \u00f6d\u00fcl vermez \u2014 yaln\u0131zca milli tak\u0131m prestiji ve oyuncu istatistikleri.</div>`;
    const bd=document.getElementById('rewardInfoBody'); if(bd) bd.innerHTML=html;
    const m=document.getElementById('rewardInfoModal'); if(m) m.style.display='flex';
  }catch(e){ console.warn('[rewardInfo] hata:',e); }
}
function calRenderDays() {
  const list = document.getElementById('calDaysList');
  if(!list) return;
  if(typeof SEASON_TEMPLATE === 'undefined') {
    list.innerHTML = '<div style="text-align:center;padding:40px;color:var(--text3)">Sezon verisi bulunamadı</div>';
    return;
  }

  let info;
  try { info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : null; } catch(e) { info = null; }
  const currentDay = info && !info.preSeason ? info.dayInSeason : 0;

  let html = '';
  let visibleCount = 0;
  const totalDays = (typeof SEASON_LEN !== 'undefined') ? SEASON_LEN : 38;
  for(let d = 1; d <= totalDays; d++) {
    const events = SEASON_TEMPLATE[d] || [];
    // Filtre: gösterilecek olaylar
    const filteredEvents = events.filter(ev => calEventMatches(ev, _calFilter));

    // Filtre seçiliyse ve eşleşmiyorsa boş gün de filtrelenir
    if(_calFilter !== 'all' && filteredEvents.length === 0 && events.length > 0) continue;
    // Tümü filtresinde boş günler ('break' yoksa) zaten yok ama kontrol ekleyelim
    if(filteredEvents.length === 0 && events.length === 0) continue;

    visibleCount++;

    let cls = 'cal-day';
    let isToday = false;
    if(d < currentDay) cls += ' past';
    else if(d === currentDay) { cls += ' today'; isToday = true; }
    else cls += ' future';

    // Bu günün gerçek tarihi
    const dayDateStr = calFormatDayDate(d);

    const eventsHtml = filteredEvents.length > 0
      ? filteredEvents.map(ev => {
          const meta = calEventMeta(ev);
          return `<div class="cal-event ${meta.cls}">
            <div class="cal-event-icon">${meta.icon}</div>
            <div class="cal-event-label">${meta.label}</div>
            ${meta.sub ? `<div class="cal-event-sub">${meta.sub}</div>` : ''}
          </div>`;
        }).join('')
      : `<div class="cal-event ev-break"><div class="cal-event-icon">💤</div><div class="cal-event-label">Boş gün</div></div>`;

    const todayBadgeHtml = isToday ? '<div class="cal-day-today-pill">BUGÜN</div>' : '';

    html += `<div class="${cls}" id="calDay${d}">
      <div class="cal-day-num">
        <div class="cal-day-num-big">${d}</div>
        ${todayBadgeHtml}
        <div class="cal-day-num-date">${dayDateStr}</div>
        <div class="cal-day-num-lbl">${calDayLabel(d)}</div>
      </div>
      <div class="cal-day-events">${eventsHtml}</div>
    </div>`;
  }

  if(visibleCount === 0) {
    html = '<div style="text-align:center;padding:40px 20px;color:var(--text3);font-size:13px">Bu filtreye uygun olay bulunamadı.</div>';
  }

  list.innerHTML = html;

  // Bugün varsa scroll
  setTimeout(() => {
    if(currentDay > 0) {
      const todayEl = document.getElementById('calDay' + currentDay);
      if(todayEl) todayEl.scrollIntoView({ behavior:'smooth', block:'center' });
    }
  }, 100);
}

function calRender() {
  calRenderHeader();
  calRenderDays();
}

// ═══════════════════════════════════════
//   ETKİNLİK (EVENTS): Günlük Görevler + Başarılar
// ═══════════════════════════════════════
//
// Giriş serisi (7 günlük) → Supabase user_player (login_day/login_streak/streak_claimed), RPC ile.
// Başarılar (seri+pro) → Supabase (achievement_defs + players/user_player sayaçları), RPC ile.
// 592 — yaşam boyu sayaçlar hiç okunmuyordu, kaldırıldı. (Cüzdan hareket günlüğü cft_wallet_log
//   sunucu tablosu kurulana dek yerelde; tören gösterildi işareti gibi arayüz anahtarları kalır.)
//

// ── Günlük Giriş Ödülleri (7 gün ardışık seri) ──
// Server otoritesi: gerçek değerler RPC'deki _streak_reward'da. Bu tablo SADECE UI gösterimi.
const EV_STREAK_REWARDS = [
  { day:1, dia:3,  eur:300,  energy:1,  icon:'🎁' },
  { day:2, dia:6,  eur:600,  energy:4,  icon:'🎁' },
  { day:3, dia:9,  eur:900,  energy:7,  icon:'🎁' },
  { day:4, dia:12, eur:1200, energy:10, icon:'🎁' },
  { day:5, dia:15, eur:1500, energy:13, icon:'🎁' },
  { day:6, dia:18, eur:1800, energy:16, icon:'🎁' },
  { day:7, dia:21, eur:2100, energy:19, icon:'🎉', bonus:true },
];

// 🆕 Giriş serisi RAM cache — Supabase user_player'dan gelir (login pull doldurur).
//   { login_day:'YYYY-MM-DD', login_streak:int(0-7), streak_claimed:[int,...] }
let _userStreakCache = { login_day: null, login_streak: 0, streak_claimed: [] };

// 🆕 Giriş serisi state'i RAM cache'ten (Supabase user_player). localStorage YOK.
function evGetStreak() {
  const c = _userStreakCache || {};
  return {
    login_day: c.login_day || null,
    login_streak: (typeof c.login_streak === 'number') ? c.login_streak : 0,
    streak_claimed: Array.isArray(c.streak_claimed) ? c.streak_claimed : []
  };
}
// ── Giriş Serisi (Daily Login Streak) — SERVER OTORİTELİ (RPC) ──
// Giriş anında çağrılır: server UTC günüyle seriyi günceller, RAM cache'i tazeler.
async function evTouchLoginStreak() {
  if (!window.sb || !authUser || !authUser.id) return;
  try {
    const _prevDay = (_userStreakCache && _userStreakCache.login_day) || null;
    const { data, error } = await window.sb.rpc('touch_login_streak');
    if (error) { console.warn('[streak] touch hata:', error.message || error); return; }
    if (data && typeof data === 'object') {
      _userStreakCache = {
        login_day: data.login_day || null,
        login_streak: (typeof data.login_streak === 'number') ? data.login_streak : 0,
        streak_claimed: Array.isArray(data.streak_claimed) ? data.streak_claimed : []
      };
      // 🆕 Yeni gün → başarı "oyunda gün" sayacını artır (login_day değiştiyse)
      if (data.login_day && data.login_day !== _prevDay && typeof achBump === 'function') {
        achBump('login_days');
      }
      if (typeof evRender === 'function') evRender();
      if (typeof evRefreshBadge === 'function') evRefreshBadge();
    }
  } catch(e) { console.warn('[streak] touch exception:', e); }
}

// Belirli bir günün ödülünü topla (hak edilmiş + toplanmamış olmalı). Server ödülü yazar.
async function evClaimStreakDay(day) {
  if (!window.sb || !authUser || !authUser.id) return;
  const s = evGetStreak();
  if (day < 1 || day > 7) return;
  if (day > s.login_streak) return;                    // henüz hak edilmedi
  if (s.streak_claimed.includes(day)) return;          // zaten toplandı
  try {
    const { data, error } = await window.sb.rpc('claim_streak_reward', { p_day: day });
    if (error) { console.warn('[streak] claim hata:', error.message || error); return; }
    if (!data || data.ok !== true) {
      // not_earned / already_claimed / bad_day — sessizce render tazele
      if (data && data.streak_claimed) _userStreakCache.streak_claimed = data.streak_claimed;
      if (typeof evRender === 'function') evRender();
      return;
    }
    // Cache: toplandı işaretle
    if (Array.isArray(data.streak_claimed)) _userStreakCache.streak_claimed = data.streak_claimed;
    else if (!_userStreakCache.streak_claimed.includes(day)) _userStreakCache.streak_claimed.push(day);

    // 🆕 ÖDÜL ANİMASYONU: buton yeniden render'da silinecek → konumu şimdi al
    const _rect = (typeof wlSrcRect === 'function') ? wlSrcRect() : null;
    const _rEur = Number(data.eur) || 0, _rDia = Number(data.dia) || 0;
    if (_rect) { wlHoldHeader('eur', _rEur > 0); wlHoldHeader('dia', _rDia > 0); }

    // 🔔 540 — hediye alındı: bugünün hatırlatması iptal edilsin
    try { if (typeof _bldMacTara === 'function') _bldMacTara(true); } catch(e) {}

    // 🆕 Önce UI'ı anında güncelle — ödülü aldığı an rozet düşsün
    if (typeof evQuestBadgeSync === 'function') evQuestBadgeSync();
    if (typeof evRender === 'function') evRender();
    if (typeof evRefreshBadge === 'function') evRefreshBadge();
    if (typeof evQuestBadgeSync === 'function') setTimeout(evQuestBadgeSync, 0);
    if (typeof rosterToast === 'function') {
      const parts = [];
      if (data.dia) parts.push(`+${data.dia} 💎`);
      if (data.eur) parts.push(`+${data.eur} €`);
      if (data.energy) parts.push(`+${data.energy} ⚡`);
      rosterToast(`Gün ${day} hediyesi: ${parts.join('  ')}`, 'ok');
    }
    // Ödül server'da (claim_streak_reward RPC) cüzdana + enerjiye yazıldı — otoriter değerleri çekip tazele
    try {
      // 🆕 ENERJİ ÖDÜLÜ — AYRI ÇAĞRI YOK.
      //    claim_streak_reward fonksiyonu enerjiyi ZATEN mevcut değerin
      //    üzerine ekliyor:  energy = coalesce(energy,0) + v_energy
      //    Buradan ikinci kez energy_add çağırmak ÇİFT EKLEME yapıyordu.
      //    Sadece sunucudaki güncel değeri tazele.
      if (typeof wlLoadFromServer === 'function') await wlLoadFromServer();
      if (typeof _energyLoadFromServer === 'function') await _energyLoadFromServer();
    } catch(e2) {}
    // 🆕 Cüzdana uçuş animasyonu (elmas → euro)
    try {
      if (_rect && typeof wlFlyRewards === 'function') {
        wlFlyRewards(_rect, [{ cur:'dia', amount:_rDia }, { cur:'eur', amount:_rEur }]);
      } else { wlHoldHeader('eur', false); wlHoldHeader('dia', false); }
    } catch(e3) { wlHoldHeader('eur', false); wlHoldHeader('dia', false); }
  } catch(e) { console.warn('[streak] claim exception:', e); }
}

// Toplanmamış (hak edilmiş ama alınmamış) ödül var mı? — badge için
function evCanClaimStreak() {
  const s = evGetStreak();
  for (let d = 1; d <= s.login_streak; d++) {
    if (!s.streak_claimed.includes(d)) return true;
  }
  return false;
}

// ── Render ──
