// 🆕 Sunucu günü ile RAM cache aynı mı? Değilse seriyi tazele.
//   (Uygulama açıkken gece yarısı geçilirse veya oturum geri yüklendiyse.)
function evEnsureStreakToday() {
  try {
    if (!window.sb || !authUser || !authUser.id) return;
    const bugun = new Date().toISOString().slice(0, 10);   // UTC gün — server ile aynı ölçek
    const cache = (_userStreakCache && _userStreakCache.login_day) || null;
    if (cache === bugun) return;
    if (window._evStreakTouching) return;
    window._evStreakTouching = true;
    Promise.resolve(evTouchLoginStreak())
      .catch(() => {})
      .then(() => { window._evStreakTouching = false; });
  } catch(e) { window._evStreakTouching = false; }
}
window.evEnsureStreakToday = evEnsureStreakToday;

// 🆕 PERİYODİK SİSTEM MESAJI TARAYICISI
//   Oyun içinde oluşan ama sunucunun bilmediği durumlar için tek yerden kontrol.
//   Hepsi sysMsg() üzerinden gider → aynı mesaj ikinci kez düşmez.
function sysMsgTara() {
  try {
    if (!window.authUser || !window.authUser.id) return;
    if (!Array.isArray(_inboxCache)) return;   // 🆕 gelen kutusu yüklenmeden tarama yok

    // ── D21 · Seviye atladın ──
    try {
      const lv = (window._userProgressCache && window._userProgressCache.level) || 0;
      // 592 — "son bildirilen seviye" yerelde değil: sys_sent'te seviye_N kimlikleri.
      //   Hiç seviye kaydı yoksa (ilk takip) mevcut seviye sessizce işaretlenir.
      if (lv > 0 && !_sysSentSet().has('seviye_' + lv)) {
        const takipVar = Array.from(_sysSentSet()).some(id => /^seviye_\d+$/.test(id));
        if (takipVar) {
          sysMsg({
            id: 'seviye_' + lv, from: '📈 Gelişim', avatar: '📈', kind: 'seviye',
            subject: `Seviye ${lv} Oldun!`,
            body: `Tebrikler, ${lv}. seviyeye ulaştın.\n\n`
                + `• Yeteneklerin gelişti, piyasa değerin arttı.\n`
                + `• Antrenmana devam ederek daha da yükselebilirsin.`
          });
        }
        _sysSentAdd('seviye_' + lv);
      }
    } catch(e) {}

    // ── D22 · Piyasa değeri eşiği ──
    try {
      if (typeof getPlayerMarketValue === 'function' && typeof ROSTER_DATA !== 'undefined') {
        const me = (ROSTER_DATA || []).find(p => p && p.role === 'user');
        const mv = me ? getPlayerMarketValue(me) : 0;
        const esikler = [100000, 500000, 1000000, 5000000, 10000000];
        const gecilen = esikler.filter(e => mv >= e).pop();
        if (gecilen) {
          const f = (typeof formatMV === 'function') ? formatMV(gecilen) : (gecilen + ' €');
          sysMsg({
            id: 'mv_' + gecilen, from: '💶 Piyasa', avatar: '💶', kind: 'piyasa_degeri',
            subject: `Piyasa Değerin ${f} Sınırını Geçti`,
            body: `Performansın karşılığını buluyor.\n\n• Güncel piyasa değerin: ${f} üzeri\n\n`
                + `Piyasa değeri oyun tarafından yeteneklerine göre hesaplanır.`
          });
        }
      }
    } catch(e) {}

    // ── D19/D20 · Haftalık yarış derecesi (önceki tur kapandığında) ──
    try {
      if (typeof _evRaceCycleInfo === 'function' && typeof _evRaceBuildLeaderboard === 'function') {
        const c = _evRaceCycleInfo();
        const anahtar = 'cft_sys_race_' + (c && c.start ? c.start.getTime() : 0);
        if (!_sysSentSet().has('tara_' + anahtar)) {
          const bak = (tur, ad, ikon) => {
            const lb = _evRaceBuildLeaderboard(tur) || [];
            const idx = lb.findIndex(e => e && (e.isUser || e.isMe));
            if (idx >= 0 && idx < 3) {
              sysMsg({
                id: 'yaris_' + tur + '_' + anahtar,
                from: ikon + ' ' + ad, avatar: ikon, kind: 'yaris',
                subject: `${ad} — ${idx + 1}. Oldun!`,
                body: `Haftalık ${ad} yarışını ${idx + 1}. sırada tamamladın. ${ikon}\n\n`
                    + `• Ödülünü Etkinlik > Yarış ekranından almayı unutma.`
              });
            }
          };
          bak('rating', 'Haftanın Yıldızı', '⭐');
          bak('train', 'Antrenman Yıldızı', '🏋️');
          _sysSentAdd('tara_' + anahtar);
        }
      }
    } catch(e) {}

    // ── C16 · Sözleşmen bitiyor ──
    try {
      if (typeof _getContractRenewalState === 'function') {
        const st = _getContractRenewalState();
        if (st && !st.bitti && st.daysLeft != null && st.daysLeft <= 5 && st.daysLeft >= 0) {
          sysMsg({
            id: 'sozlesme_' + (_userTeam.teamName || '') + '_' + st.info.season,   // 592 — sezonda bir kez (st.season yoktu → hep aynı kimlik)
            from: '📄 Sözleşme', avatar: '📄', kind: 'sozlesme',
            subject: `Sözleşmen ${st.daysLeft} Gün Sonra Bitiyor`,
            body: `Kulübünle sözleşmen sezon sonunda sona eriyor.\n\n`
                + `• Yenileme talebini Sözleşmem ekranından gönderebilirsin.\n`
                + `• Yenilemezsen takımda kalırsın ama istediğin an ayrılabilirsin.`
          });
        }
      }
    } catch(e) {}

    // ── F36 · Kadro uyarısı (bitkin oyuncu / eksik 11) ──
    try {
      if (_userTeam && _userTeam.role === 'captain' && typeof ROSTER_DATA !== 'undefined') {
        const bitkin = (ROSTER_DATA || []).filter(p => p && (p.stamina != null) && p.stamina < 30).length;
        if (bitkin >= 3) {
          sysMsg({
            id: 'kadro_uyari',                          // 🆕 bir kez (eskiden her gün tekrar)
            from: '⚠️ Teknik Ekip', avatar: '⚠️', kind: 'kadro_uyari',
            subject: `${bitkin} Oyuncu Bitkin — Rotasyon Öner`,
            body: `Kadroda ${bitkin} oyuncunun kondisyonu kritik seviyede (%30 altı).\n\n`
                + `• Diziliş ekranından yedeklerle rotasyon yap.\n`
                + `• Bitkin oyuncular maçta düşük performans gösterir ve sakatlanma riski artar.`
          });
        }
      }
    } catch(e) {}

    // ── D18 · Toplanmamış günlük giriş hediyesi (gün başına ÖMÜR BOYU 1 kez) ──
    try {
      if (typeof evGetStreak === 'function') {
        const _s = evGetStreak();
        const _gun = _s.login_streak || 0;
        if (_gun >= 1 && !(_s.streak_claimed || []).includes(_gun)) {
          sysMsg({
            id: 'gunluk_seri_' + _gun,               // 🆕 tarih YOK → tekrar YOK
            from: '🎁 Günlük Giriş', avatar: '🎁', kind: 'gunluk',
            subject: `Gün ${_gun} Hediyen Hazır`,
            body: `Giriş serin ${_gun}. günde.\n\n• Hediyeni Etkinlik > Görevler ekranından al.\n`
                + `• Bu hatırlatma tekrar gönderilmez.`
          });
        }
      }
    } catch(e) {}

    // ── Başarım bildirimi (tek mesaj, yalnızca yeni açılanlar) ──
    try { if (typeof _achMesajKontrol === 'function') _achMesajKontrol(); } catch(e) {}

    // ── 🆕 Yönetim duyuruları + destek cevapları ──
    try { if (typeof duyuruTara === 'function') duyuruTara(); } catch(e) {}
    try { if (typeof supportCevapTara === 'function') supportCevapTara(); } catch(e) {}

    // ── G38 · Enerjin doldu ──
    try {
      if (_energyCache && _energyCache.max && _energyCache.current >= _energyCache.max) {
        sysMsg({
          id: 'enerji_dolu',                            // 🆕 bir kez (eskiden her gün tekrar)
          from: '⚡ Performans', avatar: '⚡', kind: 'enerji',
          subject: 'Enerjin Doldu — Antrenman Zamanı',
          body: `Enerjin tamamen doldu (${_energyCache.current}/${_energyCache.max}).\n\n`
              + `• Antrenman sayfasından yeteneklerini geliştirebilirsin.\n`
              + `• Kullanılmayan enerji birikmez, gün sonunda sıfırlanır.`
        });
      }
    } catch(e) {}

  } catch(e) { console.warn('[sysMsgTara] hata:', e); }
}
window.sysMsgTara = sysMsgTara;

// 🆕 ESKİ HATA: Etkinlik sekmesine her basıldığında sysMsgTara() çalışıyor ve
//    toplanmamış tüm ödüller için yeniden bildirim üretiliyordu. Tarama artık
//    yalnızca açılışta (12 sn) ve 3 dakikalık zamanlayıcıda çalışır.
function evRender() {
  try { evEnsureStreakToday(); } catch(e) {}
  evRenderStreak();
  evRenderAchievements();
}

function evRenderStreak() {
  const rows = document.getElementById('evStreakRows');
  const meta = document.getElementById('evStreakMeta');
  const info = document.getElementById('evStreakInfo');
  if(!rows) return;

  const s = evGetStreak();
  const streak = s.login_streak || 0;          // hak edilen en yüksek gün (0-7)
  const claimed = s.streak_claimed || [];       // toplanan gün no'ları

  if(meta) meta.textContent = streak > 0 ? `Seri: ${streak}/7 gün` : 'Seri başlamadı';

  const _lockSvg = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect x="5" y="11" width="14" height="9" rx="2"/><path d="M8 11V8a4 4 0 0 1 8 0v3"/></svg>';

  let html = '';
  for(let i = 1; i <= 7; i++) {
    const reward = EV_STREAK_REWARDS[i-1];
    const earned = i <= streak;
    const isClaimed = claimed.includes(i);
    const canClaim = earned && !isClaimed;

    let cls = '';
    if(reward.bonus) cls += ' bonus';
    let action = '';
    if(isClaimed) {
      cls += ' claimed';
      action = '<span class="ev-claimed-tag">✓ Alındı</span>';
    } else if(canClaim) {
      cls += ' claimable';
      action = `<button class="ev-claim-btn" onclick="evClaimStreakDay(${i})">Topla</button>`;
    } else {
      cls += ' locked';
      action = `<span class="ev-locked-tag">${_lockSvg}</span>`;
    }

    html += `<div class="ev-srow${cls}">
      <div class="ev-srow-day"><span class="d-lbl">Gün</span><span class="d-num">${i}</span></div>
      <div class="ev-srow-rewards">
        <span class="ev-rw dia"><span class="rw-ic">💎</span>${reward.dia}</span>
        <span class="ev-rw eur"><span class="rw-ic">💶</span>${reward.eur}</span>
        <span class="ev-rw energy"><span class="rw-ic">⚡</span>${reward.energy}</span>
      </div>
      <div class="ev-srow-action">${action}</div>
    </div>`;
  }
  rows.innerHTML = html;

  // Info — toplanabilir ödül var mı?
  if(info) {
    const pending = [];
    for(let d = 1; d <= streak; d++) if(!claimed.includes(d)) pending.push(d);
    if(streak === 0) {
      info.innerHTML = `🚪 Her gün giriş yap, serini büyüt! İlk gün hediyesi seni bekliyor.`;
      info.style.background = 'rgba(0,176,255,.06)';
      info.style.borderColor = 'rgba(0,176,255,.2)';
      info.style.color = 'var(--text2)';
    } else if(pending.length > 0) {
      info.innerHTML = `⏰ <b>${pending.length}</b> toplanmamış hediyen var! Toplamadan gün kaçırırsan yanar.`;
      info.style.background = 'rgba(255,213,79,.06)';
      info.style.borderColor = 'rgba(255,213,79,.3)';
      info.style.color = '#ffd54f';
    } else {
      info.innerHTML = `✅ Bu serideki tüm hediyelerini topladın. Yarın da gir, seri devam etsin!`;
      info.style.background = 'rgba(0,200,83,.06)';
      info.style.borderColor = 'rgba(0,200,83,.2)';
      info.style.color = '#81c784';
    }
  }
}

function evRenderAchievements() {
  // 🆕 Eski sistem yerine yeni 100 başarı sistemine yönlendir.
  // evAchList artık gizli legacy elemanı; yeni achList #ev-ach içinde render edilir.
  if (typeof achRenderAll === 'function') {
    try { achRenderAll(); } catch(e) { console.warn('achRenderAll fail:', e); }
    return;
  }
  // Fallback (achRenderAll yüklenmediyse boş gösterir)
  const list = document.getElementById('evAchList');
  if(list) list.innerHTML = '';
}

// ── Bildirim badge'i (ana ekrandaki Etkinlik kartında "!" göster) ──
function evCountClaimables() {
  let n = 0;
  // Giriş ödülü: toplanmamış hak edilmiş gün var mı
  if(evCanClaimStreak()) n++;
  // Achievement claim — 🆕 Seri + Pro görev sistemi
  if (typeof ACH_SERIES !== 'undefined' && typeof _achProgress === 'function') {
    for (const a of ACH_SERIES) if (!_achIsClaimed(a[0]) && _achProgress(a[2]) >= a[5]) n++;
    for (const a of ACH_PRO) if (!_achIsClaimed(a[0]) && _achProgress(a[1]) >= 1) n++;
  }
  return n;
}

function evRefreshBadge() {
  // 🆕 Ana sayfa Etkinlik rozeti kaldırıldı — yalnızca Etkinlik içi sekme rozetlerini güncelle
  evRefreshTabBadges();
}

let _evBadgeLastLoad = 0;
// 🆕 Toplanabilir günlük ödül sayısı — tek kaynak (rozet ve mesajlar bunu kullanır)
function evClaimableCount() {
  try {
    const s = (typeof evGetStreak === 'function') ? evGetStreak() : null;
    if (!s) return 0;
    const claimed = Array.isArray(s.streak_claimed) ? s.streak_claimed : [];
    let n = 0;
    for (let d = 1; d <= (s.login_streak || 0); d++) if (!claimed.includes(d)) n++;
    return n;
  } catch(e) { return 0; }
}
window.evClaimableCount = evClaimableCount;

// 🆕 GÖREVLER rozetini ANINDA güncelle (await beklemeden).
//   Ödülü alınca rozet hemen düşsün; 0 ise rozet gizlenir.
function evQuestBadgeSync() {
  _bnEvGuncelle({ gorev: evClaimableCount() });   // 728 — Görevler çanı
}
window.evQuestBadgeSync = evQuestBadgeSync;

async function evRefreshTabBadges() {
  // 🆕 Görevler rozeti önce senkron güncellenir — achLoadState beklenmez.
  try { evQuestBadgeSync(); } catch(e) {}
  // 🆕 BAYAT STATE FİX: badge'i GÜNCEL server claimed/stat'ından hesapla.
  //   (claimed liste yüklenmeden hesaplanınca TOPLANMIŞ ödül "toplanabilir" sayılıp
  //    bildirim fazla görünüyordu → render ile tutarsızlık.) Throttle: en çok 3sn'de bir.
  try {
    const _now = Date.now();
    if (typeof achLoadState === 'function' && (_now - _evBadgeLastLoad > 3000)) {
      _evBadgeLastLoad = _now;
      await achLoadState();
    }
  } catch(e){}

  // 728 — GÖREVLER = toplanabilir giriş ödülü günü · BAŞARILAR = toplanabilir seri + pro (render ile aynı koşul)
  _bnEvGuncelle({ gorev: evClaimableCount(), basari: _bnBasariIds() });
}

// ═══════════════════════════════════════
//   KİŞİSEL CÜZDAN (PERSONAL WALLET) — € + 💎
// ═══════════════════════════════════════
// Kullanıcının kişisel parası — takım kasasından (cft_treasury) AYRI tutulur.
// Hem euro (€) hem elmas (💎) tutar. Header'da gösterilen değerler buradan gelir.
// 🆕 ARTIK SUPABASE'DEN GELİR — localStorage YOK, sadece RAM cache.
const WL_KEY     = 'cft_wallet';     // Sadece backward-compat için, kullanılmıyor
const WL_DEFAULT = { eur: 50000, dia: 50, total_in: 50050, total_out: 0 };

// 🆕 RAM CACHE
let _wlCache = null;          // Supabase'ten yüklenen son veri
let _wlSaveTimer = null;      // Debounce timer
let _wlLoading = false;       // Concurrent load guard

// Supabase'ten cüzdanı çek + RAM cache'e koy + UI yenile
async function wlLoadFromServer() {
  if (!window.sb || !authUser || !authUser.id) return null;
  if (_wlLoading) return _wlCache;
  _wlLoading = true;
  try {
    const { data, error } = await window.sb
      .from('user_wallet')
      .select('eur, dia, total_in, total_out')
      .eq('user_id', authUser.id)
      .maybeSingle();
    if (error) { console.warn('[Wallet] load hata:', error); return _wlCache; }
    if (!data) {
      // Satır yok — oluştur
      const { data: ins } = await window.sb.from('user_wallet')
        .insert({ user_id: authUser.id })
        .select('eur, dia, total_in, total_out')
        .maybeSingle();
      _wlCache = ins ? {
        eur: Number(ins.eur) || 50000, dia: Number(ins.dia) || 50,
        total_in: Number(ins.total_in) || 0, total_out: Number(ins.total_out) || 0,
        totalIn: Number(ins.total_in) || 0, totalOut: Number(ins.total_out) || 0
      } : Object.assign({}, WL_DEFAULT);
    } else {
      _wlCache = {
        eur: Number(data.eur) || 0, dia: Number(data.dia) || 0,
        total_in: Number(data.total_in) || 0, total_out: Number(data.total_out) || 0,
        totalIn: Number(data.total_in) || 0, totalOut: Number(data.total_out) || 0
      };
    }
    try { wlSyncHeader(); } catch(e) {}
    return _wlCache;
  } catch(e) {
    console.warn('[Wallet] load exception:', e);
    return _wlCache;
  } finally {
    _wlLoading = false;
  }
}

// Senkron getter — RAM cache döner (yoksa default)
function wlGetData(){
  if (_wlCache) return _wlCache;
  // Henüz yüklenmemiş — Supabase'ten arka planda çek
  if (window.sb && authUser && authUser.id) {
    wlLoadFromServer().catch(()=>{});
  }
  // Boş cache döner — UI hemen render eder, fetch gelince güncellenir
  return Object.assign({}, WL_DEFAULT);
}

// Saver — RAM cache'i günceller + debounced Supabase write
function wlSaveData(d){
  _wlCache = Object.assign({}, _wlCache || {}, d);
  // backward compat alias
  if (typeof d.totalIn === 'number') _wlCache.total_in = d.totalIn;
  if (typeof d.totalOut === 'number') _wlCache.total_out = d.totalOut;
  if (typeof d.total_in === 'number') _wlCache.totalIn = d.total_in;
  if (typeof d.total_out === 'number') _wlCache.totalOut = d.total_out;

  wlSyncHeader();

  // 🔒 CÜZDAN İSTEMCİDEN YAZILMAZ.
  //   Eskiden bakiye burada doğrudan güncelleniyordu → konsoldan sınırsız para.
  //   Artık tüm para hareketleri sunucuda (Edge aksiyonları / RPC) yapılır;
  //   burada yalnızca EKRAN önbelleği güncellenir, DB'ye yazılmaz.
  if (false && window.sb && authUser && authUser.id) {
    clearTimeout(_wlSaveTimer);
    _wlSaveTimer = setTimeout(async () => {
      try {
        await window.sb.from('user_wallet').update({
          eur: _wlCache.eur || 0,
          dia: _wlCache.dia || 0,
          total_in: _wlCache.total_in || _wlCache.totalIn || 0,
          total_out: _wlCache.total_out || _wlCache.totalOut || 0
        }).eq('user_id', authUser.id);
      } catch(e) { console.warn('[Wallet] save hata:', e); }
    }, 500);
  }
}

// Header senkronu: hem € hem 💎 cüzdandan okunur
function wlSyncHeader(){
  try{
    const d = wlGetData();
    const diaEl = document.getElementById('diamond-display');
    // 🆕 Ödül uçuşu sürerken rakamı erken güncellemeyelim
    if(diaEl && !(window._WL_HOLD||{}).dia) diaEl.textContent = d.dia.toLocaleString('tr');
    const monEl = document.getElementById('money-display');
    if(monEl && !(window._WL_HOLD||{}).eur) monEl.textContent = d.eur.toLocaleString('tr') + ' €';
    const shopBal = document.getElementById('shopDiamondBal');
    if(shopBal) shopBal.textContent = d.dia.toLocaleString('tr');
  }catch(e){}
}


// ══════════════════════════════════════════════════════════════════
// 🆕 ÖDÜL UÇUŞ ANİMASYONU (varyant C — sayan)
//   wlFlyReward(srcEl, 'eur'|'dia', amount) → tutar butondan kalkar,
//   ilgili cüzdan rozetine uçar, varışta rakam sayarak yükselir + büyüyüp döner.
//   Uçuş boyunca başlık güncellemesi askıya alınır (rakam erken zıplamasın).
// ══════════════════════════════════════════════════════════════════
window._WL_HOLD = window._WL_HOLD || { eur: false, dia: false };
const _WL_HOLD = window._WL_HOLD;
function _wlHeaderEl(cur) {
  return document.getElementById(cur === 'dia' ? 'diamond-display' : 'money-display');
}
function _wlChipEl(cur) {
  const e = _wlHeaderEl(cur);
  if (!e) return null;
  // rozet kabı: en yakın üst öğe (yoksa kendisi)
  return e.closest('[class*="coin"],[class*="chip"],[class*="wallet"],[class*="bal"]') || e.parentElement || e;
}
// (514) ÜST BAR — sabit genişlikli kapsüller. Değer kapsüle sığmazsa kısaltılır
//   (12.565.915 € → 12,57M € → 12,6M €; 116.066 → 116,1K → 116K). Tam değer
//   data-tam'da ve kapsülün başlığında (title) durur; bakiye okuyan kod data-tam'ı kullanır.
function _hdrKisa(n, ondalik) {
  const a = Math.abs(n);
  const f = (v, s) => (Math.round(v * Math.pow(10, ondalik)) / Math.pow(10, ondalik)).toLocaleString('tr', { maximumFractionDigits: ondalik }) + s;
  if (a >= 1e9) return f(n / 1e9, 'B');
  return a >= 1e6 ? f(n / 1e6, 'M') : (a >= 1e3 ? f(n / 1e3, 'K') : String(n));
}
function _hdrSigdir(el) {
  if (!el) return;
  const txt = el.textContent || '';
  if (el._kisaYazi && txt === el._kisaYazi) return;          // kendi yazdığımız kısaltma
  el.dataset.tam = txt;
  el._kisaYazi = null;
  const pill = el.closest('.currency-pill');
  if (pill) pill.title = (pill.dataset.baslik || (pill.dataset.baslik = pill.title || '')) + (txt ? ' — ' + txt : '');
  if (el.scrollWidth <= el.clientWidth + 1) return;           // sığıyor → tam sayı
  const n = parseInt(txt.replace(/[^\d-]/g, ''), 10);
  if (!isFinite(n)) return;
  const euro = /€/.test(txt) ? ' €' : '';
  for (const od of [2, 1, 0]) {
    let k = (Math.abs(n) >= 1e9) ? ((Math.round(n / 1e9 * Math.pow(10, od)) / Math.pow(10, od)).toLocaleString('tr', { maximumFractionDigits: od }) + 'B')
          : _hdrKisa(n, od);
    k += euro;
    el._kisaYazi = k; el.textContent = k;
    if (el.scrollWidth <= el.clientWidth + 1) return;
  }
  if (euro) { const k = el.textContent.replace(' €', ''); el._kisaYazi = k; el.textContent = k; }
}
function _hdrPlan(el) {   // 798
  if (el._hdrBek) return;
  el._hdrBek = requestAnimationFrame(() => { el._hdrBek = 0; _hdrSigdir(el); });
}
function _hdrSigdirHepsi() {
  ['money-display', 'diamond-display', 'energy-display'].forEach(id => {
    const el = document.getElementById(id);
    if (!el) return;
    if (el.dataset.tam && el._kisaYazi) { el._kisaYazi = null; el.textContent = el.dataset.tam; }
    else _hdrSigdir(el);
  });
}
(function _hdrGozle() {
  const kur = () => {
    ['money-display', 'diamond-display', 'energy-display'].forEach(id => {
      const el = document.getElementById(id);
      if (!el || el._hdrGoz) return;
      el._hdrGoz = new MutationObserver(() => _hdrPlan(el));   // 798
      el._hdrGoz.observe(el, { childList: true, characterData: true, subtree: true });
      _hdrPlan(el);
    });
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', kur); else kur();
  let _t = null;
  window.addEventListener('resize', () => { clearTimeout(_t); _t = setTimeout(_hdrSigdirHepsi, 150); });
  try { if (document.fonts) requestAnimationFrame(() => { try { document.fonts.ready.then(_hdrSigdirHepsi); } catch (e) {} }); } catch(e) {}   // 816
})();

function _wlParseNum(txt) {
  const t = String(txt || '').replace(/[^\d]/g, '');
  return t ? parseInt(t, 10) : 0;
}
function _wlFmtHeader(cur, n) {
  return cur === 'dia' ? Number(n).toLocaleString('tr') : Number(n).toLocaleString('tr') + ' €';
}

// srcEl bir DOM öğesi VEYA {left,top,width,height} dikdörtgeni olabilir.
//   Dikdörtgen desteği önemli: bazı "Topla" butonları ödül alınır alınmaz
//   yeniden render edilip DOM'dan siliniyor → önce rect alıp sonra uçuruyoruz.
function wlFlyReward(srcEl, cur, amount, onDone) {
  amount = Math.round(Number(amount) || 0);
  const tgt = _wlHeaderEl(cur);
  const br = (srcEl && typeof srcEl.getBoundingClientRect === 'function')
    ? srcEl.getBoundingClientRect()
    : (srcEl && isFinite(srcEl.left) ? srcEl : null);
  if (!amount || amount <= 0 || !tgt || !br) {
    _WL_HOLD[cur] = false;
    try { wlSyncHeader(); } catch(e) {}
    if (onDone) onDone();
    return;
  }
  const chip = _wlChipEl(cur);
  const tr = tgt.getBoundingClientRect();
  if (!br.width || !tr.width) { try { wlSyncHeader(); } catch(e) {} if (onDone) onDone(); return; }

  // Uçuş süresince başlık dondurulur
  const fromVal = _wlParseNum(tgt.dataset.tam || tgt.textContent);
  _WL_HOLD[cur] = true;

  const f = document.createElement('div');
  f.className = 'wlfly' + (cur === 'dia' ? ' dia' : '');
  if (cur === 'dia') f.innerHTML = '+' + amount.toLocaleString('tr') + '<svg viewBox="0 0 64 56"><use href="#ic-elmas-tas"/></svg>';
  else f.textContent = '+' + amount.toLocaleString('tr') + ' €';
  document.body.appendChild(f);
  const fw = f.offsetWidth, fh = f.offsetHeight;
  const x0 = br.left + br.width / 2 - fw / 2, y0 = br.top + br.height / 2 - fh / 2;
  const x1 = tr.left + tr.width / 2 - fw / 2, y1 = tr.top + tr.height / 2 - fh / 2;
  f.style.left = x0 + 'px'; f.style.top = y0 + 'px';
  const dx = x1 - x0, dy = y1 - y0;

  const finish = () => {
    try { f.remove(); } catch(e) {}
    _WL_HOLD[cur] = false;
    _wlLandCount(cur, fromVal, amount);
    if (chip) { chip.classList.add('wl-glow'); setTimeout(() => chip.classList.remove('wl-glow'), 560); }
    if (onDone) { try { onDone(); } catch(e) {} }
  };

  if (!f.animate) { setTimeout(finish, 120); return; }
  const an = f.animate([
    { transform: 'translate(0,0) scale(1)', opacity: 1 },
    { transform: `translate(${dx * 0.18}px,${dy * 0.18}px) scale(1.12)`, opacity: 1, offset: 0.18 },
    { transform: `translate(${dx}px,${dy}px) scale(.34)`, opacity: 0 }
  ], { duration: 700, easing: 'cubic-bezier(.45,.05,.35,1)', fill: 'forwards' });
  an.onfinish = finish;
  setTimeout(() => { if (_WL_HOLD[cur]) finish(); }, 1400);   // emniyet
}

// Varışta: rakam 0,5 sn boyunca sayarak yükselir, aynı anda büyüyüp eski boyuna döner
function _wlLandCount(cur, fromVal, amount) {
  const el = _wlHeaderEl(cur);
  if (!el) { try { wlSyncHeader(); } catch(e) {} return; }
  let target = fromVal + amount;
  try {
    const d = wlGetData();
    const real = cur === 'dia' ? Number(d.dia) : Number(d.eur);
    if (isFinite(real) && real > 0) target = Math.round(real);
  } catch(e) {}
  el.classList.add('wl-bump');
  el.style.transform = 'scale(1.34)';
  setTimeout(() => { el.style.transform = 'scale(1)'; }, 195);
  const t0 = performance.now(), D = 500;
  const step = (t) => {
    const p = Math.min(1, (t - t0) / D);
    const e = 1 - Math.pow(1 - p, 3);
    el.textContent = _wlFmtHeader(cur, Math.round(fromVal + (target - fromVal) * e));
    if (p < 1) requestAnimationFrame(step);
    else { el.textContent = _wlFmtHeader(cur, target); try { wlSyncHeader(); } catch(e) {} }
  };
  requestAnimationFrame(step);
}

// 🆕 Birden fazla para birimi: sırayla uçur (önce elmas, sonra euro)
function wlFlyRewards(src, list, onDone) {
  const arr = (list || []).filter(x => x && x.amount > 0);
  if (!arr.length) { try { wlSyncHeader(); } catch(e) {} if (onDone) onDone(); return; }
  let i = 0;
  const next = () => {
    if (i >= arr.length) { if (onDone) onDone(); return; }
    const it = arr[i++];
    wlFlyReward(src, it.cur, it.amount, next);
  };
  next();
}
// 🆕 Tıklanan ödül butonunun konumunu (yeniden render'dan ÖNCE) sakla
function wlSrcRect() {
  try {
    const el = _wlSrcEl;
    if (el && document.body.contains(el)) {
      const r = el.getBoundingClientRect();
      if (r && r.width) return { left: r.left, top: r.top, width: r.width, height: r.height };
    }
  } catch(e) {}
  return null;
}
// 🆕 Uçuş başlayana kadar başlık rakamını dondur
function wlHoldHeader(cur, on) { try { _WL_HOLD[cur] = !!on; } catch(e) {} }

// ── Oyundaki TÜM "Ödülü Al / Topla" butonlarını otomatik yakala ──
//   Tıklanan öğe ödül butonuna benziyorsa referansı sakla; wlAddIncome
//   çağrıldığında animasyon oradan başlar.
let _wlSrcEl = null, _wlSrcAt = 0;
document.addEventListener('click', (ev) => {
  try {
    const el = ev.target && ev.target.closest
      ? ev.target.closest('button,[onclick],.claim,.ev-claim-btn,.ach-claim-btn,.ev-race-claim-btn,.ev-quest-btn') : null;
    if (!el) return;
    const sig = ((el.className || '') + ' ' + (el.textContent || '')).toLowerCase();
    if (/claim|collect|topla|ödül|odul|al\b/.test(sig)) { _wlSrcEl = el; _wlSrcAt = Date.now(); }
  } catch(e) {}
}, true);
function _wlTakeSrc() {
  const el = (_wlSrcEl && (Date.now() - _wlSrcAt) < 4000 && document.body.contains(_wlSrcEl)) ? _wlSrcEl : null;
  _wlSrcEl = null;
  return el;
}

// 596 — Cüzdan hareket günlüğü tarayıcıda DEĞİL, sunucuda (user_wallet_log).
//   Her bakiye değişikliğini veritabanı tetikleyicisi kaydeder; hangi cihazdan
//   bakılırsa bakılsın aynı liste görünür, sunucudan gelen gelirler de içindedir.

// ── Public API: currency = 'eur' | 'dia' ──
// 🆕 ATOMİK CÜZDAN — optimistic (anlık UI) + sunucu RPC (delta, satır kilidi).
//   Eski 'tüm satırı update' yöntemi sunucu yazımlarını (maaş/imza/ödül) eziyordu.
//   RPC auth.uid() kullanır → kullanıcı yalnızca KENDİ cüzdanını değiştirebilir (service_role hariç).
function _wlApplyLocal(d_eur, d_dia, kind){
  const c = Object.assign({}, WL_DEFAULT, _wlCache || {});
  c.eur = (Number(c.eur)||0) + (d_eur||0);
  c.dia = (Number(c.dia)||0) + (d_dia||0);
  const amt = Math.abs(d_eur||0) + Math.abs(d_dia||0);
  if(kind==='in'){ c.total_in=(Number(c.total_in)||0)+amt; c.totalIn=c.total_in; }
  else if(kind==='out'){ c.total_out=(Number(c.total_out)||0)+amt; c.totalOut=c.total_out; }
  _wlCache = c;
  if(typeof wlSyncHeader==='function') wlSyncHeader();
}
function _wlRpcApply(d_eur, d_dia, kind, kaynak){
  if(!window.sb || !authUser || !authUser.id) return;
  // 🔒 GÜVENLİK — tarayıcı yalnız HARCAYABİLİR.
  //   `user_wallet_apply` tarayıcıya kapalı (yalnız sunucu). Tarayıcının harcama
  //   fonksiyonu `cuzdan_harca`: pozitif değer verilirse 'kredi_yasak' döner,
  //   cüzdanı her zaman çağıranın KENDİ kimliğinden alır ve hareketi açıklamasıyla
  //   sunucudaki günlüğe (user_wallet_log) yazar.
  if ((Number(d_eur)||0) > 0 || (Number(d_dia)||0) > 0) {
    // Bu yol gelir eklemek için kullanılmaz; yanlışlıkla çağrılırsa gerçek bakiyeyi tazele.
    if(typeof wlLoadFromServer==='function') wlLoadFromServer().then(()=>{ if(typeof wlSyncHeader==='function') wlSyncHeader(); });
    return;
  }
  const sonuc = ({data,error})=>{
    if(error){ console.warn('[Wallet] rpc hata:', error); return; }
    _wlGunlukOnbellek = null;
    if(data && data.ok){
      _wlCache = { eur:Number(data.eur)||0, dia:Number(data.dia)||0,
        total_in:Number(data.total_in)||0, total_out:Number(data.total_out)||0,
        totalIn:Number(data.total_in)||0, totalOut:Number(data.total_out)||0 };
      if(typeof wlSyncHeader==='function') wlSyncHeader();
    } else if(data && data.ok===false){
      if(typeof wlLoadFromServer==='function') wlLoadFromServer().then(()=>{ if(typeof wlSyncHeader==='function') wlSyncHeader(); });
    }
  };
  window.sb.rpc('cuzdan_harca', { p_eur:d_eur||0, p_dia:d_dia||0, p_kaynak: kaynak ? String(kaynak).slice(0, 80) : null })
    .then(r=>{
      // Sunucu fonksiyonu henüz kurulmadıysa (SQL çalıştırılmadı) eski yol
      if(r && r.error && (r.error.code==='PGRST202' || r.error.code==='42883')){
        return window.sb.rpc('wallet_spend', { p_eur:d_eur||0, p_dia:d_dia||0, p_kind:kind||'out' }).then(sonuc);
      }
      sonuc(r);
    }).catch(e=>console.warn('[Wallet] rpc hata:', e));
}

function wlAddIncome(currency, amount, source, opts){
  if(!amount || amount<=0) return;
  const d_eur = currency==='eur'?amount:0, d_dia = currency==='dia'?amount:0;
  // 🆕 Ödül butonundan tetiklendiyse animasyonu başlat (başlık uçuş bitince güncellenir)
  let src = null;
  if (!(opts && opts.noFly)) { try { src = _wlTakeSrc(); } catch(e) {} }
  if (src) { try { _WL_HOLD[currency] = true; } catch(e) {} }
  // 🔒 A3 · İSTEMCİ CÜZDANA PARA YAZMAZ — SON KAPI.
  //   Tüm gelir yolları sunucuya taşındı (bet_claim, scratch_claim,
  //   race_claim, accept_transfer_offer, approve-join-request, market_buy).
  //   Bu fonksiyon artık yalnızca EKRAN önbelleğini güncelliyor ki
  //   ödül animasyonu akıcı kalsın; gerçek bakiye sunucudan gelir.
  //   `_wlRpcApply(..., 'in')` çağrısı KALDIRILDI: açık kalsaydı
  //   konsoldan `wlAddIncome('dia', 999999)` sınırsız elmas demekti.
  _wlApplyLocal(d_eur, d_dia, 'in');
  _wlGunlukOnbellek = null;   // hareket listesi sunucudan yeniden okunsun
  // Ekran gerçeği sunucudan tazelensin (yanlış bir yerden çağrıldıysa geri döner)
  try { if (typeof wlLoadFromServer === 'function') setTimeout(() => wlLoadFromServer().catch(()=>{}), 1200); } catch(e) {}
  if (src) { try { _WL_HOLD[currency] = false; wlFlyReward(src, currency, amount); } catch(e) { try { wlSyncHeader(); } catch(_) {} } }
}

function wlDeduct(currency, amount, reason){
  if(!amount || amount<=0) return false;
  const d = wlGetData();
  if(currency==='eur'){ if((Number(d.eur)||0) < amount) return false; }
  else if(currency==='dia'){ if((Number(d.dia)||0) < amount) return false; }
  else { return false; }
  const d_eur = currency==='eur'?-amount:0, d_dia = currency==='dia'?-amount:0;
  _wlApplyLocal(d_eur, d_dia, 'out');
  _wlRpcApply(d_eur, d_dia, 'out', reason || null);
  return true;
}

function wlCanAfford(currency, amount){
  const d = wlGetData();
  if(currency==='eur') return d.eur >= amount;
  if(currency==='dia') return d.dia >= amount;
  return false;
}

function wlGetBalance(currency){
  const d = wlGetData();
  if(currency==='eur') return d.eur;
  if(currency==='dia') return d.dia;
  return d.dia; // backward compat: parametresiz çağrılırsa elmas döner
}

// ── Geriye dönük uyumluluk: eski 'wlAddDia/wlDeductDia/wlCanAffordDia' isimleri ──
function wlAddDia(amount, source){ return wlAddIncome('dia', amount, source); }
function wlDeductDia(amount, reason){ return wlDeduct('dia', amount, reason); }
function wlCanAffordDia(amount){ return wlCanAfford('dia', amount); }

// 🆕 wlMigrateFromTreasury fonksiyonu silindi (Aşama 1)
// Cüzdan ve treasury artık tamamen Supabase'te. Eski lokal data migrate gerekmez.
function wlMigrateFromTreasury(){ /* no-op */ }

try{ wlMigrateFromTreasury(); }catch(e){}


// Cüzdan hareketleri penceresi — 596: liste SUNUCUDAN (user_wallet_log, son 50 hareket)
var _wlGunlukOnbellek = null;   // { t, rows }
function _wlKacis(x){ return String(x == null ? '' : x).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function _wlGunlukSatirlari(kayitlar){
  const yerel = (typeof window._tarihYerel === 'function') ? window._tarihYerel() : 'tr';
  const satirlar = [];
  (kayitlar || []).forEach(k => {
    const t = new Date(k.created_at);
    const tarih = isNaN(t.getTime()) ? '' : (t.toLocaleDateString(yerel, {day:'numeric',month:'short'}) + ' ' + t.toLocaleTimeString(yerel, {hour:'2-digit',minute:'2-digit'}));
    // Bir harekette hem € hem 💎 değişmişse iki satır
    [['eur', Number(k.eur) || 0, '€'], ['dia', Number(k.dia) || 0, '💎']].forEach(([cur, v, sym]) => {
      if (!v) return;
      const gelir = v > 0;
      const ad = (k.kaynak && String(k.kaynak).trim()) ? String(k.kaynak) : (gelir ? 'Gelir' : 'Gider');
      satirlar.push(`<div style="display:flex;justify-content:space-between;align-items:center;padding:9px 12px;border-bottom:1px solid var(--border);gap:10px">
      <div style="flex:1;min-width:0;text-align:left">
        <div style="font-size:13px;color:var(--text);font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${_wlKacis(ad)}</div>
        <div style="font-size:10px;color:var(--text3);margin-top:2px" data-noi18n>${tarih}</div>
      </div>
      <div style="font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;font-size:16px;font-weight:900;color:${gelir ? '#00e676' : '#ff5252'}" data-noi18n>${gelir ? '+' : '−'}${Math.abs(v).toLocaleString(yerel)} ${sym}</div>
    </div>`);
    });
  });
  return satirlar.length ? satirlar.join('') : '<div style="padding:24px;text-align:center;color:var(--text3);font-size:13px">Henüz işlem yok</div>';
}
async function _wlGunlukYukle(){
  if (_wlGunlukOnbellek && Date.now() - _wlGunlukOnbellek.t < 15000) return _wlGunlukOnbellek.rows;
  if (!window.sb || !authUser || !authUser.id) throw new Error('oturum_yok');
  const { data, error } = await window.sb.from('user_wallet_log')
    .select('eur,dia,kaynak,created_at')
    .eq('user_id', authUser.id)
    .order('created_at', { ascending: false })
    .limit(50);
  if (error) throw error;
  _wlGunlukOnbellek = { t: Date.now(), rows: Array.isArray(data) ? data : [] };
  return _wlGunlukOnbellek.rows;
}
// 596 — .fac-modal-overlay görünürlüğü .open sınıfına bağlı (opacity); eskiden yalnız
//   display ayarlandığı için pencere saydam kalıyor, tıklamalar içinden geçiyordu.
function _wlLogKapat(){
  const m = document.getElementById('walletLogModal');
  if (!m) return;
  m.classList.remove('open');
  setTimeout(() => { if (!m.classList.contains('open')) m.style.display = 'none'; }, 220);
}
function wlOpenLog(){
  const d = wlGetData();
  let modal = document.getElementById('walletLogModal');
  if(!modal){
    modal = document.createElement('div');
    modal.id = 'walletLogModal';
    modal.className = 'fac-modal-overlay';
    modal.onclick = function(e){ if(e.target===this) _wlLogKapat(); };
    document.body.appendChild(modal);
  }
  const rows = (_wlGunlukOnbellek ? _wlGunlukSatirlari(_wlGunlukOnbellek.rows)
    : '<div style="padding:24px;text-align:center;color:var(--text3);font-size:13px">Hareketler yükleniyor…</div>');

  modal.innerHTML = `
    <div class="fac-modal" style="max-width:440px;max-height:80vh;display:flex;flex-direction:column;padding:0;overflow:hidden">
      <div style="padding:18px 20px;border-bottom:1px solid var(--border);background:linear-gradient(135deg,rgba(0,176,255,.1),rgba(255,214,0,.06))">
        <div style="display:flex;align-items:center;gap:10px;margin-bottom:12px">
          <span style="font-size:24px">👛</span>
          <span style="font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;font-size:20px;font-weight:900;letter-spacing:.5px">KİŞİSEL CÜZDANIM</span>
        </div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:8px">
          <div style="padding:10px 12px;background:rgba(255,214,0,.08);border:1px solid rgba(255,214,0,.25);border-radius:8px;border-left:3px solid var(--gold)">
            <div style="font-size:10px;color:var(--text3);font-weight:700;letter-spacing:.5px">EURO</div>
            <div style="font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;font-size:20px;font-weight:900;color:var(--gold)">${(d.eur||0).toLocaleString('tr')} €</div>
          </div>
          <div style="padding:10px 12px;background:rgba(0,176,255,.08);border:1px solid rgba(0,176,255,.25);border-radius:8px;border-left:3px solid var(--accent2)">
            <div style="font-size:10px;color:var(--text3);font-weight:700;letter-spacing:.5px">ELMAS</div>
            <div style="font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;font-size:20px;font-weight:900;color:var(--accent2)">${(d.dia||0).toLocaleString('tr')} 💎</div>
          </div>
        </div>
        <div style="display:flex;justify-content:space-between;font-size:10px;color:var(--text2);margin-top:6px">
          <span>Toplam Gelir: <span style="color:#00e676;font-weight:700">+${(d.totalIn||0).toLocaleString('tr')}</span></span>
          <span>Toplam Gider: <span style="color:#ff5252;font-weight:700">−${(d.totalOut||0).toLocaleString('tr')}</span></span>
        </div>
      </div>
      <div style="flex:1;overflow-y:auto;max-height:50vh" id="walletLogRows">${rows}</div>
      <div style="padding:12px;border-top:1px solid var(--border);display:flex;gap:8px">
        <button class="fac-modal-cancel" style="flex:1" onclick="_wlLogKapat()">Kapat</button>
        <button class="fac-modal-confirm" style="flex:1" onclick="_wlLogKapat();showPage('shop',findNavBtn('shop'));shopTab('diamond')">💎 Elmas Al</button>
      </div>
    </div>`;
  modal.style.display = 'flex';
  requestAnimationFrame(() => modal.classList.add('open'));
  _wlGunlukYukle().then(k => {
    const el = document.getElementById('walletLogRows');
    if (el) el.innerHTML = _wlGunlukSatirlari(k);
  }).catch(e => {
    console.warn('[Wallet] hareketler okunamadı:', e);
    const el = document.getElementById('walletLogRows');
    if (el && !_wlGunlukOnbellek) el.innerHTML = '<div style="padding:24px;text-align:center;color:var(--text3);font-size:13px">Hareketler yüklenemedi</div>';
  });
}

// Header'daki kasa pill'inden çağrılır: takım sayfasındaki kasa sekmesini aç
function trsOpenPage(){
  // Takımı yoksa uyarı
  if(typeof _userTeam !== 'undefined' && !_userTeam){
    if(typeof toast === 'function') toast('Henüz bir takımın yok. Önce takım satın al ya da bir takıma katıl.', 'info');
    return;
  }
  // Takım sayfasına git
  if(typeof showPage === 'function'){
    showPage('team', document.querySelectorAll('.nav-btn')[2]);
    // Sonra treasury sekmesini aç
    setTimeout(function(){
      const trsTab = Array.from(document.querySelectorAll('.team-tab')).find(t => t.getAttribute('onclick')?.includes("'treasury'"));
      if(trsTab) trsTab.click();
    }, 100);
  }
}

// ═══════════════════════════════════════
//   TAKIM KASASI (TEAM TREASURY)
// ═══════════════════════════════════════
// Kasa verisi Supabase team_data tablosunda tutulur (data_key='treasury' ve 'treasury_log')
// localStorage anahtarları sadece temizlik için tanımlı (legacy cleanup)
const TRS_KEY     = 'cft_treasury';     // legacy - cleanup için tanımlı
const TRS_LOG_KEY = 'cft_treasury_log'; // legacy - cleanup için tanımlı

// Yeni kullanıcı başlangıcı: kasa boş (takım yokken kasa anlamsız).
// Takım satın alındığında kalkış sermayesi otomatik enjekte edilir.
// Hem euro hem elmas tutar — kullanıcı bağışıyla doldurulur, ödüllerle dolar.
const TRS_DEFAULT = { eur: 0, dia: 0, totalIn: 0, totalOut: 0, donCount: 0 };

let _trsDonateType = 'eur'; // 'eur' | 'dia' — kullanıcı seçer

// 🆕 RAM cache - bootstrap'ta server'dan doldurulur
let _trsCache = null;
let _trsLogCache = null;
let _trsSaveTimer = null;
let _trsLogSaveTimer = null;

// Server'dan kasa verisini yükle (bootstrap ve takım değişimi sonrası)
async function _trsLoadFromServer() {
  if (!window.sb || !_userTeam || !_userTeam.countryCode || !_userTeam.teamName) {
    _trsCache = null;
    _trsLogCache = null;
    return;
  }
  try {
    const { data, error } = await window.sb.from('team_data')
      .select('data_key, data')
      .eq('country_code', _userTeam.countryCode)
      .eq('team_name', _userTeam.teamName)
      .in('data_key', ['treasury', 'treasury_log']);
    if (error) { console.warn('[treasury] load hata:', error); return; }
    _trsCache = null;
    _trsLogCache = null;
    for (const row of (data || [])) {
      if (row.data_key === 'treasury') _trsCache = row.data;
      else if (row.data_key === 'treasury_log') _trsLogCache = row.data;
    }
  } catch(e) { console.warn('[treasury] load hata:', e); }
}

// 🆕 ATOMİK KASA — istemci optimistic (anlık UI) + sunucu RPC (delta, satır kilidi).
//   Eski 'tüm objeyi upsert' yöntemi sunucu yazımlarını (maç ödülü vb.) eziyordu.
//   Artık delta gönderiyoruz; dönüşte _trsCache sunucu otoriter değeriyle eşitlenir.
function _trsApplyLocal(d_eur, d_dia, kind, source){
  const c = Object.assign({}, TRS_DEFAULT, _trsCache || {});
  c.eur = (Number(c.eur)||0) + (d_eur||0);
  c.dia = (Number(c.dia)||0) + (d_dia||0);
  const amt = Math.abs(d_eur||0) + Math.abs(d_dia||0);
  if(kind==='in') c.totalIn = (Number(c.totalIn)||0) + amt;
  else if(kind==='out') c.totalOut = (Number(c.totalOut)||0) + amt;
  _trsCache = c;
  if(source){
    const entry = {ts:Date.now(), type:(kind==='out'?'out':'in'), cur:((d_dia&&!d_eur)?'dia':'eur'), amount:amt, source};
    if(Array.isArray(_trsLogCache)) _trsLogCache.unshift(entry); else _trsLogCache=[entry];
  }
  if(typeof trsSyncHeader==='function') trsSyncHeader();
}

function _trsRpcApply(d_eur, d_dia, kind, source, extra){
  if(!window.sb || !_userTeam || !_userTeam.countryCode || !_userTeam.teamName) return;
  // 🔒 597 — Takım kasası tarayıcıdan artık yalnız HARCANABİLİR (kasa_harca).
  //   team_treasury_apply sunucuya kapatıldı: eskiden herkes konsoldan HERHANGİ bir takımın
  //   kasasına para ekleyebiliyor ya da başka takımın kasasını boşaltabiliyordu.
  //   Takım ve yetki (kaptan/yardımcı) sunucuda bulunur; istemciden takım adı gitmez.
  //   Gelirler (maç, ödül, transfer, devralma sermayesi) zaten sunucuda yazılıyor.
  if ((Number(d_eur)||0) >= 0 && (Number(d_dia)||0) >= 0) {
    if (typeof _trsLoadFromServer === 'function') _trsLoadFromServer().then(()=>{ if(typeof trsRender==='function') trsRender(); if(typeof trsSyncHeader==='function') trsSyncHeader(); });
    return;
  }
  window.sb.rpc('kasa_harca', { p_eur:d_eur||0, p_dia:d_dia||0, p_kaynak: source ? String(source).slice(0, 80) : null })
    .then(({data,error})=>{
      if(error){ console.warn('[treasury] rpc hata:', error); }
      if(data && data.ok && data.treasury){
        _trsCache = data.treasury;
        if(typeof trsRender==='function') trsRender();
        if(typeof trsSyncHeader==='function') trsSyncHeader();
      } else if(typeof _trsLoadFromServer==='function'){
        _trsLoadFromServer().then(()=>{ if(typeof trsRender==='function') trsRender(); if(typeof trsSyncHeader==='function') trsSyncHeader(); });
      }
    }).catch(e=>console.warn('[treasury] rpc hata:', e));
}

function trsGetData(){
  if (_trsCache) return Object.assign({}, TRS_DEFAULT, _trsCache);
  return Object.assign({}, TRS_DEFAULT);
}

function trsSaveData(d){
  // RAM cache anında güncelle
  _trsCache = Object.assign({}, _trsCache || {}, d);
  // 🔒 TAKIM KASASI İSTEMCİDEN YAZILMAZ.
  //   Kasa hareketleri sunucudaki team_treasury_apply RPC'si ile yapılır.
  //   Burada yalnızca ekran önbelleği tutulur.
  if (false && window.sb && _userTeam && _userTeam.countryCode && _userTeam.teamName) {
    clearTimeout(_trsSaveTimer);
    _trsSaveTimer = setTimeout(async () => {
      try {
        await window.sb.from('team_data').upsert({
          country_code: _userTeam.countryCode,
          team_name: _userTeam.teamName,
          data_key: 'treasury',
          data: _trsCache,
          updated_at: new Date().toISOString()
        }, { onConflict: 'country_code,team_name,data_key' });
      } catch(e) { console.warn('[treasury] save hata:', e); }
    }, 500);
  }
  // Header senkronizasyonu — her kayıt sonrası DOM güncelle
  trsSyncHeader();
}

// ── Header senkronizasyonu ──
// money-display ve diamond-display her zaman cft_treasury'den okur.
function trsSyncHeader() {
  // Header'daki tüm para göstergeleri ARTIK CÜZDANDAN okunur (kasadan değil).
  // Bu fonksiyon backward-compat için kalır; gerçek iş wlSyncHeader'da yapılır.
  try {
    if(typeof wlSyncHeader === 'function') wlSyncHeader();
  } catch(e) {}
}


// 🆕 Kasa: içinde bulunulan sezonun zaman aralığı [başlangıç, bitiş) — ms
function _trsSeasonRange() {
  try {
    const info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : null;
    const sN = (info && info.season) || 1;
    if (typeof _seasonRangeMs === 'function') return _seasonRangeMs(sN);
    if (info && info.seasonStart) {
      const st = new Date(info.seasonStart).getTime();
      const len = (typeof SEASON_LEN !== 'undefined' ? SEASON_LEN : 40) * 86400000;
      return [st, st + len];
    }
  } catch(e) {}
  return [0, Infinity];
}

// 🆕 Hesap hareketleri modalı (bütçe/elmas kutusuna tıklayınca)
function trsOpenLogModal(cur) {
  window._trslCur = (cur === 'dia') ? 'dia' : 'eur';
  const ov = document.getElementById('trsLogOverlay');
  if (!ov) return;
  trsRenderLogModal();
  ov.classList.add('open');
  try { document.body.style.overflow = 'hidden'; } catch(e) {}
}
function trsCloseLogModal() {
  const ov = document.getElementById('trsLogOverlay');
  if (ov) ov.classList.remove('open');
  try { document.body.style.overflow = ''; } catch(e) {}
}
function trsRenderLogModal() {
  const cur = window._trslCur || 'eur';
  const isDia = cur === 'dia';
  const body = document.getElementById('trslBody');
  if (!body) return;
  let sN = 1;
  try { sN = (getSeasonInfo().season) || 1; } catch(e) {}
  const [sStart, sEnd] = _trsSeasonRange();

  const icEl = document.getElementById('trslIcon');
  if (icEl) icEl.textContent = isDia ? '💎' : '💶';
  const tEl = document.getElementById('trslTitle');
  if (tEl) tEl.textContent = isDia ? 'Elmas Hareketleri' : 'Bütçe Hareketleri';
  const sEl = document.getElementById('trslSub');
  if (sEl) sEl.textContent = 'Sezon ' + sN + ' · en yeni üstte';

  const all = (typeof trsGetLog === 'function' ? trsGetLog() : []).filter(e => e && e.cur === cur);
  const thisSeason = all.filter(e => typeof e.ts === 'number' && e.ts >= sStart && e.ts < sEnd);
  const older = all.filter(e => typeof e.ts === 'number' && e.ts < sStart);

  // Özet
  let sumIn = 0, sumOut = 0;
  thisSeason.forEach(e => {
    if (e.type === 'in' || e.type === 'don') sumIn += (e.amount || 0);
    else sumOut += (e.amount || 0);
  });
  const unit = isDia ? '' : ' €';
  const inEl = document.getElementById('trslIn');
  if (inEl) inEl.textContent = '+' + sumIn.toLocaleString('tr') + unit;
  const outEl = document.getElementById('trslOut');
  if (outEl) outEl.textContent = '−' + sumOut.toLocaleString('tr') + unit;

  // Devir: bu sezon başındaki bakiye = güncel bakiye − bu sezonun net hareketi
  let bal = 0;
  try {
    const d = (typeof trsGetData === 'function') ? trsGetData() : {};
    bal = isDia ? (Number(d.dia) || 0) : (Number(d.eur) || 0);
  } catch(e) {}
  const carry = bal - (sumIn - sumOut);

  const fmtDT = (ts) => {
    const dt = new Date(ts);
    return dt.toLocaleDateString('tr', { day: '2-digit', month: 'short', year: 'numeric' }) +
           ' · ' + dt.toLocaleTimeString('tr', { hour: '2-digit', minute: '2-digit' });
  };
  const rowHtml = (e) => {
    const isIn = (e.type === 'in' || e.type === 'don');
    const cls = e.type === 'don' ? 'don' : (isIn ? 'in' : 'out');
    const ico = e.type === 'don' ? '🤝' : (isIn ? '▲' : '▼');
    const amt = (isIn ? '+' : '−') + (e.amount || 0).toLocaleString('tr') + unit;
    const by = e.by ? ' · ' + e.by : '';
    return `<div class="trsl-row">
      <div class="trsl-ic ${cls}">${ico}</div>
      <div class="trsl-inf"><div class="t">${(e.source || 'İşlem')}${by}</div><div class="m">${fmtDT(e.ts)}</div></div>
      <div class="trsl-amt ${isIn ? 'in' : 'out'}">${amt}</div>
    </div>`;
  };

  let h = '';
  // En üstte bu sezon (en yeni önce)
  h += '<div class="trsl-sec">Sezon ' + sN + '</div>';
  if (thisSeason.length) {
    h += thisSeason.slice().sort((a, b) => (b.ts || 0) - (a.ts || 0)).map(rowHtml).join('');
  } else {
    h += '<div class="trsl-empty">Bu sezon henüz işlem yok.</div>';
  }

  // Devir satırı
  h += '<div class="trsl-sec">Sezon Başı</div>';
  h += `<div class="trsl-row">
      <div class="trsl-ic carry">↪</div>
      <div class="trsl-inf"><div class="t">Önceki sezondan devir</div><div class="m">${isFinite(sStart) && sStart > 0 ? fmtDT(sStart) : '—'}</div></div>
      <div class="trsl-amt carry">${carry.toLocaleString('tr')}${unit}</div>
    </div>`;

  // Önceki sezonların hareketleri
  if (older.length) {
    h += '<div class="trsl-sec">Önceki Sezonlar</div>';
    h += older.slice().sort((a, b) => (b.ts || 0) - (a.ts || 0)).slice(0, 60).map(rowHtml).join('');
  }

  body.innerHTML = h;
}
// ESC ile kapat
document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') {
    const o = document.getElementById('trsLogOverlay');
    if (o && o.classList.contains('open')) trsCloseLogModal();
  }
});

function trsGetLog(){
  return Array.isArray(_trsLogCache) ? _trsLogCache : [];
}

function trsSaveLog(log){
  // Sadece son 100 işlemi tut
  const trimmed = log.slice(0, 100);
  _trsLogCache = trimmed;
  // 597 — Kasa günlüğünü yalnız sunucu yazar (team_treasury_apply); burada ekran önbelleği.
  if (false && window.sb && _userTeam && _userTeam.countryCode && _userTeam.teamName) {
    clearTimeout(_trsLogSaveTimer);
    _trsLogSaveTimer = setTimeout(async () => {
      try {
        await window.sb.from('team_data').upsert({
          country_code: _userTeam.countryCode,
          team_name: _userTeam.teamName,
          data_key: 'treasury_log',
          data: trimmed,
          updated_at: new Date().toISOString()
        }, { onConflict: 'country_code,team_name,data_key' });
      } catch(e) { console.warn('[treasury_log] save hata:', e); }
    }, 500);
  }
}

function trsAddLog(entry){
  const log = trsGetLog();
  log.unshift(Object.assign({ts: Date.now()}, entry));
  trsSaveLog(log);
}

// ── Public API: diğer modüller tarafından çağrılır ──

// Gelir ekle (maç ödülü, lig/turnuva ödülü vs.)
// 'dia' → kişisel cüzdan, 'eur' → takım kasası
function trsAddIncome(currency, amount, source){
  if(!amount || amount<=0) return;
  if(currency==='dia'){
    // Elmas → cüzdana
    wlAddDia(amount, source);
    return;
  }
  // Euro → takım kasası: 597 — gelirleri sunucu yazar (maç geliri, ödüller);
  //   burada yalnız gerçek bakiye sunucudan tazelenir (eskiden aynı ödül bir de tarayıcıdan yazılıyordu).
  setTimeout(() => { try { _trsRpcApply(0, 0, 'in', source||'Gelir'); } catch(e) {} }, 1500);
}

// Gider düş (transfer, tesis, mağaza vs.). Yeterli bakiye yoksa false döner.
// 'dia' → kişisel cüzdandan, 'eur' → takım kasasından
function trsDeduct(currency, amount, reason){
  if(!amount || amount<=0) return false;
  if(currency==='dia'){
    // Elmas → cüzdandan düş
    return wlDeductDia(amount, reason);
  }
  // Euro → takım kasasından (ATOMİK RPC delta; yerelde ön kontrol, kesin kontrol sunucuda)
  const d = trsGetData();
  if((Number(d.eur)||0) < amount) return false;
  _trsApplyLocal(-amount, 0, 'out', reason||'Gider');
  _trsRpcApply(-amount, 0, 'out', reason||'Gider');
  trsRender();
  return true;
}

// Bakiye kontrolü (transfer öncesi)
// 'dia' → cüzdana bakar, 'eur' → kasaya bakar
function trsCanAfford(currency, amount){
  if(currency==='dia') return wlCanAffordDia(amount);
  const d = trsGetData();
  return d.eur >= amount;
}

function trsGetBalance(currency){
  if(currency==='dia') return wlGetBalance();
  const d = trsGetData();
  return d.eur;
}

// 🆕 KASA-Diamond helper'ları — `trs*('dia')` cüzdana yönleniyor (legacy).
// Bu fonksiyonlar GERÇEK takım kasasına erişir. Tesis yükseltme gibi
// "takım giderleri" buradan ödenir.
function trsTreasuryDiaBalance(){
  const d = trsGetData();
  return d.dia || 0;
}

function trsTreasuryDiaCanAfford(amount){
  const d = trsGetData();
  return (d.dia || 0) >= amount;
}

function trsTreasuryDiaDeduct(amount, reason){
  if(!amount || amount<=0) return false;
  const d = trsGetData();
  if((Number(d.dia) || 0) < amount) return false;
  // ATOMİK RPC delta (kasadan elmas düş)
  _trsApplyLocal(0, -amount, 'out', reason||'Gider');
  _trsRpcApply(0, -amount, 'out', reason||'Gider');
  if(typeof trsRender === 'function') trsRender();
  return true;
}

// ── UI ──
function trsSetDonateType(t){
  _trsDonateType = t;
  const eurBtn = document.getElementById('trsDtEur');
  const diaBtn = document.getElementById('trsDtDia');
  if(eurBtn) eurBtn.classList.toggle('active', t==='eur');
  if(diaBtn) diaBtn.classList.toggle('active', t==='dia');
  trsUpdateMyBalance();
  // Hızlı tutarları para birimine göre güncelle
  const qa = document.getElementById('trsQuickAmounts');
  if(qa){
    if(t==='eur'){
      qa.innerHTML = `
        <button class="trs-qa-btn" onclick="trsQuickAmount(10000)">10.000</button>
        <button class="trs-qa-btn" onclick="trsQuickAmount(50000)">50.000</button>
        <button class="trs-qa-btn" onclick="trsQuickAmount(100000)">100.000</button>
        <button class="trs-qa-btn" onclick="trsQuickAmount(500000)">500.000</button>`;
    } else {
      qa.innerHTML = `
        <button class="trs-qa-btn" onclick="trsQuickAmount(10)">10</button>
        <button class="trs-qa-btn" onclick="trsQuickAmount(50)">50</button>
        <button class="trs-qa-btn" onclick="trsQuickAmount(100)">100</button>
        <button class="trs-qa-btn" onclick="trsQuickAmount(500)">500</button>`;
    }
  }
  const inp = document.getElementById('trsDonateAmount');
  if(inp){ inp.value = ''; inp.placeholder = t==='dia' ? '💎 tutarı...' : '€ tutarı...'; }
}

function trsQuickAmount(n){
  const inp = document.getElementById('trsDonateAmount');
  if(inp) inp.value = n;
}

function trsGetUserBalance(currency){
  // (514) Başlıktaki değer kısaltılmış olabilir (12,5M) — cüzdandan oku
  if (typeof wlGetBalance === 'function') return Number(wlGetBalance(currency)) || 0;
  const id = currency==='dia' ? 'diamond-display' : 'money-display';
  const el = document.getElementById(id);
  if(!el) return 0;
  return parseInt((el.dataset.tam || el.textContent || '0').replace(/\D/g,''))||0;
}

function trsSetUserBalance(currency, val){
  const id = currency==='dia' ? 'diamond-display' : 'money-display';
  const el = document.getElementById(id);
  if(!el) return;
  if(currency==='dia') el.textContent = val.toLocaleString('tr');
  else el.textContent = val.toLocaleString('tr') + ' €';
}

function trsUpdateMyBalance(){
  // Cüzdandan seçilen para birimini göster (donate UI için)
  const bal = (typeof wlGetBalance === 'function') ? wlGetBalance(_trsDonateType) : 0;
  const el = document.getElementById('trsMyBalance');
  if(!el) return;
  el.textContent = _trsDonateType==='dia'
    ? bal.toLocaleString('tr') + ' 💎'
    : bal.toLocaleString('tr') + ' €';
}

// Bağış: cüzdandan kasaya transfer (€ veya 💎)
function trsDonate(){
  const amtEl = document.getElementById('trsDonateAmount');
  const amount = parseInt(amtEl?.value||'0')||0;
  const cur = _trsDonateType; // 'eur' | 'dia'

  if(amount<=0){ trsToast('Geçerli bir tutar gir.', 'var(--red)'); return; }

  // Takım kontrolü: bağış yapmak için kasanın olması lazım (= takım sahibi olmalı)
  if(typeof _userTeam !== 'undefined' && !_userTeam){
    trsToast('Önce bir takıma sahip olmalısın.', 'var(--red)');
    return;
  }

  // 🆕 Yetki kontrolü: sadece kaptan ve yardımcı kaptan bağış yapabilir
  if(typeof userCanMakeOffer === 'function' && !userCanMakeOffer()){
    trsToast('🔒 Sadece kaptan ve yardımcı kaptan bağış yapabilir.', 'var(--red)');
    return;
  }

  // Cüzdan bakiyesi yeterli mi?
  if(!wlCanAfford(cur, amount)){
    const lbl = cur==='dia' ? 'elmas' : 'euro';
    trsToast(`Cüzdanında yeterli ${lbl} yok.`, 'var(--red)');
    return;
  }

  // 597 — Bağış TEK sunucu işlemi: cüzdandan düşme + kasaya ekleme birlikte (biri olmazsa hiçbiri).
  //   Takım ve yetki sunucuda bulunur (kasa_bagis).
  if (!window.sb) { trsToast('Bağış yapılamadı.', 'var(--red)'); return; }
  const _eur = cur==='eur'?amount:0, _dia = cur==='dia'?amount:0;
  _wlApplyLocal(-_eur, -_dia, 'out');
  _trsApplyLocal(_eur, _dia, 'in', 'Bağış');
  window.sb.rpc('kasa_bagis', { p_eur:_eur, p_dia:_dia }).then(({data,error})=>{
    if (!error && data && data.ok) {
      const w = data.cuzdan || {};
      _wlCache = { eur:Number(w.eur)||0, dia:Number(w.dia)||0, total_in:Number(w.total_in)||0, total_out:Number(w.total_out)||0,
                   totalIn:Number(w.total_in)||0, totalOut:Number(w.total_out)||0 };
      if (data.treasury) _trsCache = data.treasury;
      try { _wlGunlukOnbellek = null; } catch(e) {}
      if(typeof wlSyncHeader==='function') wlSyncHeader();
      trsRender();
      if(cur==='eur'){
        trsToast(`🤝 ${amount.toLocaleString('tr')} € kasaya bağışlandı!`, 'var(--accent)');
      } else {
        trsToast(`🤝 ${amount.toLocaleString('tr')} 💎 kasaya bağışlandı!`, 'var(--accent2)');
      }
      return;
    }
    const kod = (data && data.error) || (error && error.message) || '';
    const mesaj = kod === 'yetki_yok' ? '🔒 Sadece kaptan ve yardımcı kaptan bağış yapabilir.'
                : kod === 'insufficient' ? (cur==='dia' ? 'Cüzdanında yeterli elmas yok.' : 'Cüzdanında yeterli euro yok.')
                : kod === 'takim_yok' ? 'Önce bir takıma sahip olmalısın.'
                : 'Bağış yapılamadı.';
    trsToast(mesaj, 'var(--red)');
    try { if (typeof wlLoadFromServer === 'function') wlLoadFromServer().then(()=>{ if(typeof wlSyncHeader==='function') wlSyncHeader(); }); } catch(e) {}
    try { if (typeof _trsLoadFromServer === 'function') _trsLoadFromServer().then(()=>{ trsRender(); if(typeof trsSyncHeader==='function') trsSyncHeader(); }); } catch(e) {}
  }).catch(e => { console.warn('[bağış]', e); trsToast('Bağış yapılamadı.', 'var(--red)'); });

  // Etkinlik: bağış sayacı
  try{
    if(typeof evRefreshBadge === 'function') evRefreshBadge();
  }catch(e){}

  amtEl.value = '';
  trsRender();
}

// 692 — Finans sekmeleri (Bağış · Maaşlar · İşlemler) ve bilgi penceresi
function fxSekme(s){
  const w = document.querySelector('#team-treasury .fx-govde');
  if(!w) return;
  w.dataset.sekme = s;
  document.querySelectorAll('#team-treasury .fx-sekme').forEach(b => b.classList.toggle('on', b.dataset.s === s));
}
function fxSekmeVarsayilan(){
  const w = document.querySelector('#team-treasury .fx-govde');
  if(!w) return;
  const yetkili = document.body.classList.contains('team-captain') || document.body.classList.contains('team-vice');
  if(!yetkili && w.dataset.sekme === 'bagis') fxSekme('maas');
}
function fxBilgi(ac){
  const s = document.getElementById('fxBilgi');
  if(s) s.classList.toggle('acik', !!ac);
}

function trsRender(){
  const d = trsGetData();
  // Kasa bakiyeleri: hem € hem 💎 KASADAN okunur
  const eurEl = document.getElementById('trsEurVal');
  const diaEl = document.getElementById('trsDiaVal');
  if(eurEl) eurEl.textContent = (d.eur||0).toLocaleString('tr') + ' €';
  if(diaEl) diaEl.textContent = (d.dia||0).toLocaleString('tr');
  const sznEl = document.getElementById('trsHeroSeason');
  if(sznEl){ try { sznEl.textContent = String((getSeasonInfo().season) || 1); } catch(e) {} }

  // Kadro/tesis sekmelerindeki ikili çubuk: SOL=KASA, SAĞ=CÜZDAN
  // data-trs="eur" → kasa euro
  // data-trs="dia" → kasa elmas
  // data-wl="eur"  → cüzdan euro
  // data-wl="dia"  → cüzdan elmas
  const eurStr = (d.eur||0).toLocaleString('tr') + ' €';
  const diaStr = (d.dia||0).toLocaleString('tr') + ' 💎';
  document.querySelectorAll('[data-trs="eur"]').forEach(el => el.textContent = eurStr);
  document.querySelectorAll('[data-trs="dia"]').forEach(el => el.textContent = diaStr);

  // 🆕 Hero bar hücreleri: emojisiz + kısa euro (5.4M / 540B)
  const _e = d.eur || 0;
  const eurShort = _e >= 1000000
    ? (_e/1000000).toFixed(_e % 1000000 === 0 ? 0 : 1) + 'M €'
    : _e >= 1000
      ? Math.round(_e/1000) + 'B €'
      : _e.toLocaleString('tr') + ' €';
  document.querySelectorAll('[data-trs-hero="eur"]').forEach(el => el.textContent = eurShort);
  document.querySelectorAll('[data-trs-hero="dia"]').forEach(el => el.textContent = (d.dia||0).toLocaleString('tr'));

  if(typeof wlGetBalance === 'function'){
    const wlEurStr = wlGetBalance('eur').toLocaleString('tr') + ' €';
    const wlDiaStr = wlGetBalance('dia').toLocaleString('tr') + ' 💎';
    document.querySelectorAll('[data-wl="eur"]').forEach(el => el.textContent = wlEurStr);
    document.querySelectorAll('[data-wl="dia"]').forEach(el => el.textContent = wlDiaStr);
  }

  const inEl  = document.getElementById('trsTotalIn');
  const outEl = document.getElementById('trsTotalOut');
  const dnEl  = document.getElementById('trsTotalDon');
  if(inEl)  inEl.textContent  = (d.totalIn||0).toLocaleString('tr') + ' €';
  if(outEl) outEl.textContent = (d.totalOut||0).toLocaleString('tr') + ' €';
  if(dnEl)  dnEl.textContent  = (d.donCount||0).toString();

  // 🆕 BU SEZON kasa gelirleri (sezon başlangıcından itibaren — her sezon sıfırlanır)
  const log = trsGetLog();
  const _sRange = _trsSeasonRange();
  let monEur = 0, monDia = 0;
  log.forEach(e=>{
    if(!e || typeof e.ts !== 'number') return;
    if(e.ts < _sRange[0] || e.ts >= _sRange[1]) return;
    if(e.type==='in' || e.type==='don'){
      if(e.cur==='eur') monEur += e.amount;
      else if(e.cur==='dia') monDia += e.amount;
    }
  });
  const mEEl = document.getElementById('trsEurMonth');
  if(mEEl) mEEl.textContent = `Bu sezon: +${monEur.toLocaleString('tr')} €`;
  const mDEl = document.getElementById('trsDiaMonth');
  if(mDEl) mDEl.textContent = `Bu sezon: +${monDia.toLocaleString('tr')}`;

  // Kullanıcı bakiyesi
  trsUpdateMyBalance();

  // Log render
  const logEl = document.getElementById('trsLog');
  if(!logEl) return;
  if(log.length===0){
    logEl.innerHTML = '<div class="trs-log-empty">Henüz işlem yok.</div>';
    return;
  }
  logEl.innerHTML = log.slice(0, 30).map(e=>{
    const isIn = e.type==='in' || e.type==='don';
    const iconCls = e.type==='don' ? 'don' : (isIn ? 'in' : 'out');
    const icon = e.type==='don'
      ? '<svg viewBox="0 0 24 24"><use href="#ic-thb-handshake"/></svg>'
      : (isIn ? '<svg viewBox="0 0 24 24"><use href="#ic-fin-up"/></svg>' : '<svg viewBox="0 0 24 24"><use href="#ic-fin-down"/></svg>');
    const sign = isIn ? '+' : '−';
    const curStr = e.cur==='dia' ? '💎' : '€';
    const amtStr = e.cur==='dia'
      ? `${sign}${e.amount.toLocaleString('tr')}`
      : `${sign}${e.amount.toLocaleString('tr')} €`;
    const date = new Date(e.ts);
    const dateStr = date.toLocaleDateString('tr',{day:'2-digit',month:'short'}) + ' · ' + date.toLocaleTimeString('tr',{hour:'2-digit',minute:'2-digit'});
    const byStr = e.by ? ` · ${e.by}` : '';
    return `<div class="trs-log-row">
      <div class="trs-log-icon ${iconCls}">${icon}</div>
      <div class="trs-log-info">
        <div class="trs-log-title">${e.source||'İşlem'}${byStr}</div>
        <div class="trs-log-meta">${dateStr}</div>
      </div>
      <div class="trs-log-amount ${isIn?'in':'out'}">${amtStr}</div>
    </div>`;
  }).join('');

  // 🆕 Maaş panelini de yenile
  if(typeof renderSalaryPanel === 'function') renderSalaryPanel();
}

function trsToast(msg, color){
  const t=document.createElement('div');
  const tc=(color==='var(--gold)'||color==='var(--accent)')?'var(--bg)':'#fff';
  t.style.cssText=`position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:${color};color:${tc};padding:10px 18px;border-radius:12px;font-size:11px;font-weight:700;z-index:9999;font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;text-align:center;max-width:300px;box-shadow:0 4px 20px rgba(0,0,0,.5)`;
  t.textContent=msg;
  document.body.appendChild(t);
  setTimeout(()=>t.remove(),2500);
}

// 🆕 Oyuncu sezonluk maaşı — sistemce hesaplanır (gerçek ve bot oyunculara seviye bazlı).
//   Sözleşmede kayıtlı seasonSalary varsa onu kullanır (kontrat aktiftir),
//   yoksa anlık hesap yapar (UI önizleme için).
function getPlayerSeasonWage(p){
  if(!p) return 0;
  // 625 — bot oyuncular da aynı formülle maaş alır (sunucu: takim_bot_maaslari, takım kasasından)
  if (!p.isBot && !p.userId && !p.user_id) return 0;
  // 🆕 TÜM kullanıcı oyuncuları: sistemce dinamik hesaplanır (Edge ödemesiyle birebir).
  //   Sabit sözleşme maaşı kaldırıldı — güncel yetenek seviyesine göre.
  if (typeof getSystemPlayerSalary === 'function') {
    return getSystemPlayerSalary(p);
  }
  return 0;
}

function getTeamSeasonWageBill(){
  if(typeof ROSTER_DATA === 'undefined' || !ROSTER_DATA.length) return 0;
  return ROSTER_DATA.reduce((s,p) => s + getPlayerSeasonWage(p), 0);
}

// 🆕 Sezon gününü gerçek tarihe çevir
//   seasonStart + (day-1) gün → Date objesi
function seasonDayToDate(day) {
  try {
    const info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : null;
    if (!info || !info.seasonStart) return null;
    const d = new Date(info.seasonStart);
    d.setUTCDate(d.getUTCDate() + (day - 1));
    return d;
  } catch(e) { return null; }
}

// Kısa tarih formatı: "5 Tem"
function _fmtShortDate(d) {
  if (!d) return '—';
  const months = ['Oca','Şub','Mar','Nis','May','Haz','Tem','Ağu','Eyl','Eki','Kas','Ara'];
  return `${d.getUTCDate()} ${months[d.getUTCMonth()]}`;
}

// Maaş ödeme günleri (sistem sabiti — Edge ile aynı)
const SALARY_PAY_DAYS = [10, 20, 30, 40];

// 🆕 Finans sayfası maaş paneli render — 4 taksit + gerçek tarih
function renderSalaryPanel(){
  const list = document.getElementById('salaryList');
  const totalEl = document.getElementById('salaryTotalSeason');
  const nextLblEl = document.getElementById('salaryNextLbl');
  const nextAmtEl = document.getElementById('salaryNextAmount');
  const nextDayEl = document.getElementById('salaryNextDay');
  if(!list) return;

  if(typeof ROSTER_DATA === 'undefined' || !ROSTER_DATA.length){
    list.innerHTML = '<div class="trs-log-empty">Kadroda oyuncu yok.</div>';
    if(totalEl) totalEl.textContent = '0 €';
    if(nextAmtEl) nextAmtEl.textContent = '—';
    return;
  }

  // Sezonluk toplam (gerçek + bot oyuncular)
  const totalSeason = getTeamSeasonWageBill();
  const taksit = Math.round(totalSeason / 4);
  if(totalEl) totalEl.textContent = totalSeason.toLocaleString('tr') + ' €';

  // Sonraki taksit (sezon gününe göre)
  let dayInSeason = 1;
  try {
    if(typeof getSeasonInfo === 'function'){
      const info = getSeasonInfo();
      dayInSeason = info.dayInSeason || 1;
    }
  } catch(e){}

  // Sıradaki ödeme günü
  const nextPayDay = SALARY_PAY_DAYS.find(d => d >= dayInSeason);
  if (nextPayDay) {
    const idx = SALARY_PAY_DAYS.indexOf(nextPayDay) + 1; // 1-4
    const realDate = seasonDayToDate(nextPayDay);
    const daysLeft = nextPayDay - dayInSeason;
    if(nextLblEl) nextLblEl.textContent = `${idx}/4 TAKSİT (GÜN ${nextPayDay})`;
    if(nextAmtEl) nextAmtEl.textContent = taksit.toLocaleString('tr') + ' €';
    if(nextDayEl) {
      const dateStr = realDate ? ` · ${_fmtShortDate(realDate)}` : '';
      nextDayEl.textContent = daysLeft === 0 ? `Bugün${dateStr}` : `${daysLeft} gün sonra${dateStr}`;
    }
  } else {
    if(nextLblEl) nextLblEl.textContent = 'SEZON BİTTİ';
    if(nextAmtEl) nextAmtEl.textContent = '—';
    if(nextDayEl) nextDayEl.textContent = 'Yeni sezon başlayacak';
  }

  // 🆕 Maaş ödeme takvimi — 4 taksit (sezon günü + gerçek tarih)
  const calEl = document.getElementById('salaryCalendar');
  if (calEl) {
    calEl.innerHTML = SALARY_PAY_DAYS.map((d, i) => {
      const realDate = seasonDayToDate(d);
      const dateStr = realDate ? _fmtShortDate(realDate) : '—';
      const isPast = d < dayInSeason;
      const isToday = d === dayInSeason;
      const isNext = d === nextPayDay && !isToday;
      const cls = isPast ? 'salary-cal-past' : (isToday ? 'salary-cal-today' : (isNext ? 'salary-cal-next' : ''));
      const stTxt = isPast ? 'Ödendi' : (isToday ? 'Bugün' : (isNext ? 'Sıradaki' : ''));
      return `<div class="salary-cal-cell ${cls}">
        <div class="salary-cal-no">${i+1}/4</div>
        <div class="salary-cal-day">Gün ${d}</div>
        <div class="salary-cal-date">${dateStr}</div>
        <div class="salary-cal-amount">${taksit.toLocaleString('tr')} €</div>
        <div class="salary-cal-st">${stTxt}</div>
      </div>`;
    }).join('');
  }

  // Pozisyon rengi (saha ile uyum)
  const _posColor = (pos) => {
    if(typeof POS_COLORS !== 'undefined' && POS_COLORS[pos]) return POS_COLORS[pos];
    return {bg:'#37474f', tc:'#b0bec5'};
  };

  // Oyuncu listesi — maaşı yüksek olan önce
  const sorted = [...ROSTER_DATA].sort((a,b) => {
    const wa = getPlayerSeasonWage(a);
    const wb = getPlayerSeasonWage(b);
    if (wa !== wb) return wb - wa;  // maaş yüksek olan önce
    return (b.overall||0) - (a.overall||0);
  });

  list.innerHTML = sorted.map(p => {
    const seasonWage = getPlayerSeasonWage(p);
    const installment = Math.round(seasonWage / 4);
    const isUser = p.role === 'user';
    const isBot = p.isBot;
    const pos = (typeof subPosOf === 'function') ? subPosOf(p) : (p.pos || '').toUpperCase();   // 692 — alt mevki
    const c = _posColor((typeof subPosGroupOf === 'function') ? subPosGroupOf(pos) : pos);
    const displayName = (p.name || '').replace(/^Bot_/, '').split('_').pop() || p.name || 'Oyuncu';
    const wageStr = seasonWage > 0
      ? `<div class="salary-row-season">${seasonWage.toLocaleString('tr')} €</div>
         <div class="salary-row-tax">4× ${installment.toLocaleString('tr')} €</div>`
      : `<div class="salary-row-season" style="color:var(--text3)">Ücretsiz</div>
         <div class="salary-row-tax" style="color:var(--text3)">(maaşsız)</div>`;
    // Yetenek = maaşın hesaplandığı seviye (bot: dört hattın ortalaması, sunucuyla aynı)
    const seviye = (typeof getPlayerMainOverall === 'function') ? getPlayerMainOverall(p) : (p.overall || 10);
    return `<div class="salary-row ${isUser?'is-user':''}">
      <div class="salary-row-num">#${p.num||'-'}</div>
      <div class="salary-row-info">
        <div class="salary-row-name">${displayName}${isUser?' <span class="salary-you">Sen</span>':''}${isBot?' <span class="salary-bot">Bot</span>':''}</div>
        <div class="salary-row-meta"><span class="salary-row-pos" style="background:${c.bg};color:${c.tc}">${pos}</span>Yetenek ${seviye}</div>
      </div>
      <div class="salary-row-amount">${wageStr}</div>
    </div>`;
  }).join('');
}


// ═══════════════════════════════════════
//   SIRALAMALAR (RANKINGS)
// ═══════════════════════════════════════

// ── Top 50 Oyuncu — teams DB'deki TÜM tier 1 takımlardan dinamik üretilir ──
// Her takıma ait isim havuzu + deterministik overall hesabı kullanılır.
// Sezon başında veya rkRenderPlayers çağrısında bir kere build edilir, sonra cache'de tutulur.
let _rkPlayerListCache = null;
let _rkPlayerListCacheKey = null;


// ═══════════════════════════════════════════════════════════════════════════
//  OYUNCU İSTATİSTİK AGGREGATION — Maç skorlarından gol/asist/rating dağıt
// ═══════════════════════════════════════════════════════════════════════════

// Pos bazlı gol/asist olasılık ağırlıkları
// _PS_POS_WEIGHTS ve _distributeMatchStats fonksiyonu SİLİNDİ
//   (lokal motor stat dağıtımı için kullanılıyordu, Supabase events ile artık gereksiz)

// In-memory cache (cache key = match results uzunluk + ilk 200 kar hash)
let _psCachedStats = null;
let _psCachedKey = null;

// 🆕 Sıfırdan yazıldı: lineup + events + calcPlayerRating.
//   Eski uydurma roster + _distributeMatchStats zinciri SİLİNDİ.
//   Kullanıcı/bot/kaptan ayrımı YOK — herkes aynı sistemden.
// 🆕 Sezon aralığı (ms) — match_ratings zaman filtresi için
function _seasonRangeMs(season){
  try{
    if(typeof SEASON_EPOCH!=='undefined' && typeof SEASON_LEN!=='undefined'){
      var st=new Date(SEASON_EPOCH); st.setUTCDate(st.getUTCDate()+(season-1)*SEASON_LEN);
      var en=new Date(SEASON_EPOCH); en.setUTCDate(en.getUTCDate()+season*SEASON_LEN);
      return [st.getTime(), en.getTime()];
    }
  }catch(e){}
  return [0, Infinity];
}
function _bucketOfTrn(tk){
  if(!tk || tk==='league') return 'lig';
  if(tk==='champ') return 'chm';
  if(tk==='elite') return 'eli';
  if(tk==='conv')  return 'con';
  if(tk==='enc')   return 'enc';
  return null;
}
function _calcPlayerStatsFromCache(teamFilter, opts) {
  // 🆕 GERÇEK SUPABASE VERİSİ: _teamRosterCache (players tablosu) direkt okuyor.
  //   Edge function maç sonu goals_total, assists_total, matches_played, match_ratings
  //   kolonlarını günceller. Frontend events'ten hesap YAPMAZ.
  if (typeof _teamRosterCache === 'undefined' || !_teamRosterCache) return {};

  let filterSet = null;
  if (teamFilter) {
    filterSet = new Set(Array.isArray(teamFilter) ? teamFilter : [teamFilter]);
  }

  // 🆕 SEZON FİLTRESİ: gol/asist/maç sezon bazlı (players.stats_by_comp), reyting
  //    match_ratings'in o sezona düşen kayıtlarından. Kariyer toplamı KULLANILMAZ —
  //    aksi halde istatistikler sezon değişince sıfırlanmıyordu.
  opts = opts || {};
  var _season = opts.season;
  // 🆕 535 — Sezon dönüşü 39. günde olduğu için gol/asist/reyting listeleri de
  //   yeni sezona geçer (yeni fikstürle birlikte sıfırlanır).
  if(_season == null){
    try{ _season = (typeof _etkinSezon === 'function') ? _etkinSezon() : getSeasonInfo().season; }
    catch(e){ _season = 1; }
  }
  var _buckets = Array.isArray(opts.buckets) && opts.buckets.length ? opts.buckets : null;  // null = tüm yarışmalar
  var _sKey = 's' + _season;
  var _rng = _seasonRangeMs(_season);

  const stats = {};
  Object.entries(_teamRosterCache).forEach(([cacheKey, roster]) => {
    // cacheKey format: "TR:TeamName"
    if (!Array.isArray(roster)) return;
    const colonIdx = cacheKey.indexOf(':');
    if (colonIdx < 0) return;
    const teamName = cacheKey.slice(colonIdx + 1);
    if (filterSet && !filterSet.has(teamName)) return;

    roster.forEach(p => {
      if (!p || !p.name) return;
      const sk = `${teamName}_${p.name}`;
      // 🆕 Rating: avgMatchRating/matchRatingsCount varsa kullan; yoksa match_ratings dizisinden hesapla
      //    (ham/eksik cache şekline tolerans — kendi takımın da gol/asist/reyting verir).
      // Reyting: sadece bu sezonun maçları (ts ile), istenirse yarışma filtresi
      const _arr = Array.isArray(p.matchRatings) ? p.matchRatings
                 : (Array.isArray(p.match_ratings) ? p.match_ratings : []);
      let _s = 0, _cnt = 0;
      for (const mr of _arr) {
        if (!mr || typeof mr.rating !== 'number') continue;
        const _ts = mr.ts || 0;
        if (_ts && (_ts < _rng[0] || _ts >= _rng[1])) continue;      // başka sezon
        if (_buckets) { const _b = _bucketOfTrn(mr.tournament_key); if (!_b || _buckets.indexOf(_b) < 0) continue; }
        _s += mr.rating; _cnt++;
      }

      // Gol/asist/maç: stats_by_comp[bucket]['s<season>']
      const _sbc = (p.statsByComp && typeof p.statsByComp === 'object') ? p.statsByComp
                 : ((p.stats_by_comp && typeof p.stats_by_comp === 'object') ? p.stats_by_comp : {});
      let _g = 0, _a = 0, _m = 0, _sawAny = false;
      Object.keys(_sbc).forEach(function(b){
        if (_buckets && _buckets.indexOf(b) < 0) return;
        const bo = _sbc[b];
        if (!bo || typeof bo !== 'object') return;
        _sawAny = true;
        const v = bo[_sKey];
        if (!v) return;
        _g += v.g || 0; _a += v.a || 0; _m += v.m || 0;
      });
      // Geriye dönük uyum: stats_by_comp hiç yoksa (eski kayıt) ve 1. sezona bakılıyorsa kariyer toplamı
      if (!_sawAny && _season === 1) {
        _g = (p.goalsTotal   != null ? p.goalsTotal   : p.goals_total)   || 0;
        _a = (p.assistsTotal != null ? p.assistsTotal : p.assists_total) || 0;
        _m = (p.matchesPlayed!= null ? p.matchesPlayed: p.matches_played)|| 0;
      }

      stats[sk] = {
        goals:   _g,
        assists: _a,
        matches: _m,
        ratingSum: _s,
        ratingCount: _cnt,
        pos: p.pos || 'MID',
        subPos: p.subPos || p.sub_pos || null,
        userId: (p.userId != null ? p.userId : p.user_id) || null,
      };
    });
  });

  return stats;
}

// Cache'i geçersiz kıl (yeni maç oynandığında)
function _invalidatePlayerStatsCache() {
  _psCachedStats = null;
  _psCachedKey = null;
}

function buildRkPlayerList() {
  // 🆕 Cache key: match_results sayısı + ilk/son key (büyük stringify yapma)
  const _matchCache = _matchResultsLoad() || {};
  const _matchKeys = Object.keys(_matchCache);
  const _matchKey = _matchKeys.length + '|' + (_matchKeys[0] || '') + '|' + (_matchKeys[_matchKeys.length-1] || '');
  if (_rkPlayerListCache && _rkPlayerListCacheKey === _matchKey) return _rkPlayerListCache;
  _rkPlayerListCacheKey = _matchKey;
  const all = [];
  const addedUserIds = new Set(); // gerçek kullanıcılar tek kez eklensin (tüm geçişlerde dedup)

  // Kendi takım oyuncuları (ROSTER_DATA)
  // 🆕 İki durum:
  //   1. Kullanıcı takımdaysa  → tüm kadro (15 oyuncu) sıralamaya katılır
  //   2. Takımsızsa            → sadece kullanıcının kendisi (role='user') katılır
  //                              ('Serbest oyuncu' takım adıyla, takım amblemsiz)
  try {
    const _hasTeam = (typeof userHasTeam === 'function') ? userHasTeam() : (!!_userTeam);

    if (typeof ROSTER_DATA !== 'undefined' && Array.isArray(ROSTER_DATA)) {
      // Kullanıcının takımının görsel verilerini (logo) bul (varsa)
      let myTeamData = null;
      try {
        if (_hasTeam && _userTeam && true) {
          const country = _cftGetCountry(_userTeam.countryCode);
          if (country && country.leagues) {
            for (const lg of country.leagues) {
              const t = (lg.teams || []).find(x => x.name === _userTeam.teamName);
              if (t) { myTeamData = t; break; }
            }
          }
        }
      } catch(e) {}

      const myTeamName = _hasTeam && _userTeam ? _userTeam.teamName : 'Serbest';
      const myCC = _hasTeam && _userTeam ? _userTeam.countryCode : 'TR';
      const myFlag = (myTeamData && _cftGetCountry(myCC)?.flag) || (_cftGetCountry(myCC)?.flag) || '🇹🇷';

      ROSTER_DATA.forEach(p => {
        // Takımsızsa sadece kullanıcının kendi profilini (role='user') ekle
        if (!_hasTeam && p.role !== 'user') return;

        const _isReal = (p.role === 'user') || (!p.isBot && p.userId);
        if (p.userId) addedUserIds.add(p.userId);
        all.push({
          n: p.name, f: myFlag,
          c: (myTeamData && myTeamData.name) || myTeamName,
          p: p.pos, o: p.overall, lv: p.level || 0, av: p.avatar || '🙂',
          cc: myCC,
          teamName: (myTeamData && myTeamData.name) || myTeamName, teamRank: 2,
          teamBg: (myTeamData && myTeamData.bg) || '#444',
          teamTc: (myTeamData && myTeamData.tc) || '#fff',
          teamShort: (myTeamData && myTeamData.short) || (_hasTeam ? 'XX' : 'FA'),
          _isMe: p.role === 'user',
          isUser: !!_isReal,
          userId: p.userId || null,
          _rosterPlayer: p,
        });
      });
    }
  } catch(e) {}

  // teams DB tier 1 liglerden tüm oyuncuları üret
  // Takım kadroları (getOrCreateTeamRoster) artık gerçek isim havuzlarından üretiliyor,
  // sıralamalar da o kadroları olduğu gibi kullanır.
  if(true) {
    for(const [cc, country] of _cftAllEntries()) {
      const tier1 = country.leagues && country.leagues[0];
      if(!tier1 || !tier1.teams) continue;

      tier1.teams.forEach(team => {
        const players = getOrCreateTeamRoster({ countryCode: cc, name: team.name, rank: team.rank || 1 });

        players.forEach((p, idx) => {
          if (!p.isBot && p.userId) {
            // 🆕 Gerçek kullanıcı: players'taki gerçek verisiyle yansıt (bota indirgeme yok)
            if (addedUserIds.has(p.userId)) return;
            addedUserIds.add(p.userId);
            all.push({
              n: p.name, f: country.flag, c: team.name,
              p: p.pos, o: p.overall || 10, lv: p.level || 0,
              av: p.avatar || '🧑', avatar_id: p.avatar_id || null,
              cc, teamName: team.name, teamRank: team.rank,
              teamBg: team.bg || '#444', teamTc: team.tc || '#fff', teamShort: team.short || 'XX',
              isUser: true, userId: p.userId,
            });
          } else {
            // KURAL: Botlar gelişmez. Yetenek (overall) sabit 10, Seviye (level) sabit 0.
            all.push({
              n: p.name, f: country.flag, c: team.name,
              p: p.pos, o: 10, lv: 0, av: '🤖',
              cc, teamName: team.name, teamRank: team.rank,
              teamBg: team.bg || '#444', teamTc: team.tc || '#fff', teamShort: team.short || 'XX',
            });
          }
        });
      });
    }

    // 🆕 Alt liglerdeki gerçek kullanıcılar da sıralamada/aramada görünsün:
    //   tier-1 dışında kalan tüm gerçek kullanıcıları players cache'inden topla.
    for (const cacheKey in _teamRosterCache) {
      const roster = _teamRosterCache[cacheKey];
      if (!Array.isArray(roster)) continue;
      const ci = cacheKey.indexOf(':');
      const ccK = ci > 0 ? cacheKey.slice(0, ci) : 'TR';
      const tnK = ci > 0 ? cacheKey.slice(ci + 1) : cacheKey;
      for (const p of roster) {
        if (!p || p.isBot || !p.userId || addedUserIds.has(p.userId)) continue;
        addedUserIds.add(p.userId);
        let tBg = '#444', tTc = '#fff', tShort = 'XX', tFlag = '🏳️';
        const ctry = _cftGetCountry(ccK);
        if (ctry) {
          tFlag = ctry.flag || '🏳️';
          for (const lg of (ctry.leagues || [])) {
            const t = (lg.teams || []).find(x => x.name === tnK);
            if (t) { tBg = t.bg || tBg; tTc = t.tc || tTc; tShort = t.short || tShort; break; }
          }
        }
        all.push({
          n: p.name, f: tFlag, c: tnK,
          p: p.pos, o: p.overall || 10, lv: p.level || 0,
          av: p.avatar || '🧑', avatar_id: p.avatar_id || null,
          cc: ccK, teamName: tnK, teamRank: 99,
          teamBg: tBg, teamTc: tTc, teamShort: tShort,
          isUser: true, userId: p.userId,
        });
      }
    }

    // 🆕 Takımsız (serbest) gerçek kullanıcılar — players cache'inde yoklar (team_name null).
    //   _loadFreeAgentUsers() ile RAM'e yüklenir; oturum kullanıcısı zaten ROSTER_DATA'da (dedup).
    for (const u of (_rkFreeUsersCache || [])) {
      if (!u || !u.user_id || addedUserIds.has(u.user_id)) continue;
      addedUserIds.add(u.user_id);
      const ctry = _cftGetCountry(u.country_code || 'TR');
      all.push({
        n: u.name, f: u.nation || (ctry && ctry.flag) || '🏳️', c: 'Serbest',
        p: u.pos || 'MID', o: u.overall || 10, lv: u.level || 0,
        av: u.avatar || '🧑', avatar_id: u.avatar_id || null,
        cc: u.country_code || 'TR', teamName: 'Serbest', teamRank: 99,
        teamBg: '#444', teamTc: '#fff', teamShort: 'FA',
        isUser: true, userId: u.user_id,
      });
    }
  }

  // 🆕 Oyuncu istatistiklerini topla (cached maçlardan deterministik dağıtım)
  let playerStats = {};
  try { playerStats = _calcPlayerStatsFromCache(); } catch(e) {}

  // Kullanıcı oyuncusunun gerçek loguna bak (cft_user_match_log)
  let userMatchLog = [];
  try { userMatchLog = getUserMatchLog(); } catch(e) {}
  // 🆕 SADECE BU SEZON — eskiden tüm kariyer toplanıyordu (gol sayısı sezon değişince sıfırlanmıyordu)
  try {
    // 🆕 535 — 39. günde sezon döndüğü için etkin sezona göre filtrele (liste sıfırlanır)
    const _sN = (typeof _etkinSezon==='function') ? _etkinSezon()
              : ((typeof getSeasonInfo==='function') ? getSeasonInfo().season : 1);
    const _r  = (typeof _seasonRangeMs==='function') ? _seasonRangeMs(_sN) : [0, Infinity];
    userMatchLog = (userMatchLog || []).filter(m => {
      if (!m) return false;
      if (m.season != null) return Number(m.season) === _sN;
      const _t = m.date ? new Date(m.date).getTime() : (m.ts || 0);
      if (!_t) return false;
      return _t >= _r[0] && _t < _r[1];
    });
  } catch(e) {}
  const userTotals = userMatchLog.reduce((acc, m) => {
    acc.goals    += m.goals    || 0;
    acc.assists  += m.assists  || 0;
    acc.ratingSum += (m.rating || 0);
    acc.matches  += m.played === false ? 0 : 1;
    return acc;
  }, { goals:0, assists:0, ratingSum:0, matches:0 });

  // Her oyuncuya stats ekle
  all.forEach(p => {
    if (p._isMe) {
      p.goals = userTotals.goals;
      p.assists = userTotals.assists;
      p.rating = userTotals.matches > 0 ? (userTotals.ratingSum / userTotals.matches) : 6.5;
      p.matches = userTotals.matches;
      p.isUser = true;
    } else {
      const sk = `${p.teamName}_${p.n}`;
      const s = playerStats[sk];
      const _rc = s ? ((s.ratingCount != null) ? s.ratingCount : s.matches) : 0;
      if (s && (s.matches > 0 || _rc > 0)) {
        p.goals = s.goals;
        p.assists = s.assists;
        p.rating = _rc > 0 ? (s.ratingSum / _rc) : 6.5;
        p.matches = s.matches;
      } else {
        p.goals = 0;
        p.assists = 0;
        p.rating = 6.5;
        p.matches = 0;
      }
    }
  });

  // Cache'e kaydet (sıralama mode'a göre rkRenderPlayers'da dinamik yapılır)
  _rkPlayerListCache = all;
  return all;
}

// Cache'i geçersiz kıl (oyuncu gelişimi, sezon geçişi gibi durumlarda)
function invalidateRkPlayerCache() { _rkPlayerListCache = null; }


// ── Top 50 Takım — teams DB'deki TÜM tier 1 takımlardan dinamik üretilir ──
// Sezon 1 başlangıcı: tüm takımların UEFA puanı (cf) = 0. Avrupa kupalarıyla birikecek.
// Avatar haritası — kıta/ülke kodlarına göre fallback emoji
const TEAM_AV_BY_COUNTRY = {
  EN:'🦁', SC:'🏴', IE:'☘️', PT:'🦅', ES:'🐂', FR:'🐓', DE:'🦅', NL:'🦁',
  IT:'🐺', BE:'🦁', CH:'🐂', AT:'🦅', SE:'👑', NO:'🦅', DK:'⚓', FI:'🦌',
  PL:'🦅', CZ:'🦁', SK:'🦅', HU:'👑', RO:'🦅', BG:'🦁', UA:'🦅', RU:'🐻',
  RS:'🦅', HR:'🛡️', AL:'🦅', GR:'🏛️', TR:'🌙', IL:'⭐', AZ:'🔥', KZ:'🦅',
};

// 🆕 Takımın gerçek gücünü OYUNCULARINDAN hesapla
// Kullanıcı takımı: ROSTER_DATA'dan (gelişen kullanıcı dahil)
// Bot takımları: getOrCreateTeamRoster ile (gerçek DB roster'ı)
function _teamPowerFromPlayers(countryCode, teamName, teamRank) {
  // 🆕 TEK KAYNAK — TÜM takımlar (kullanıcı dahil) Supabase teams.team_ovr'den okur
  //   (edge'in 4-hat ortalaması; _rkRefreshStats yükler). Hiçbir yerde yeniden hesap YOK;
  //   hero / maç önizleme / sıralama hepsi bu tek saklı değeri okur.

  // Supabase teams.team_ovr (tüm takımların haritası, _rkRefreshStats)
  try {
    const m = window._teamOvrMap;
    if (m) { const v = m[countryCode + ':' + teamName]; if (typeof v === 'number' && v > 0) return v; }
  } catch(e) {}

  // Diğer takımlar → edge'in sakladığı team_ovr (4-hat ortalaması; deploy sonrası doğru)
  try {
    const c = (typeof _cftGetCountry === 'function') ? _cftGetCountry(countryCode) : null;
    if (c && Array.isArray(c.leagues)) {
      for (const lg of c.leagues) {
        const t = (lg.teams || []).find(x => x && x.name === teamName);
        if (t) { const _tov = Number(t.teamOvr); if (Number.isFinite(_tov) && _tov > 0) return Math.round(_tov); break; }
      }
    }
  } catch(e) {}

  // Diğer takımlar fallback — sıralama cache'i (players.overall ort.). Not: bu kolon şişik;
  //   doğru değer edge team_ovr'si. Edge deploy edilince bu kullanılmaz.
  try {
    if (_teamPowerCache) {
      const key = countryCode + ':' + teamName;
      if (typeof _teamPowerCache[key] === 'number') return _teamPowerCache[key];
    }
  } catch(e) {}

  // Son çare: roster cache'inden tüm kadro ortalaması
  try {
    const players = getOrCreateTeamRoster({ countryCode: countryCode, name: teamName, rank: teamRank || 1 });
    if (!Array.isArray(players) || players.length === 0) return 10;
    const sum = players.reduce((s,p) => s + (p.overall||0), 0);
    return Math.round(sum / players.length);
  } catch(e) {}

  return 10; // fallback
}

// Eski API'yi koruyalım (başka yerlerden çağrılıyor olabilir)
function _teamEffectiveRating(team) {
  // 🆕 Takım gücü = oyuncu ortalaması. Players varsa direkt; yoksa oluştur.
  if (team.rating && team.rating > 15) return team.rating; // özel/override edilmiş
  if (typeof calcTeamPowerAverage === 'function' && Array.isArray(team.players) && team.players.length) {
    return calcTeamPowerAverage(team.players);
  }
  if (typeof getOrCreateTeamRoster === 'function' && typeof calcTeamPowerAverage === 'function'
      && team.name && (team.countryCode || team.cc)) {
    try {
      const players = getOrCreateTeamRoster(team);
      return calcTeamPowerAverage(players);
    } catch(e) {}
  }
  return 10;
}

// 🆕 Bir takım için Avrupa kupası katsayısı (son 5 sezon toplamı)

// 🆕 TEK DÜNYA TAKIM GÜCÜ — TEK SORGUDA sadece güç verisi (hafif).
//   Tüm oyuncuların yalnızca team_name + country_code + overall'ı çekilir
//   (15 kolonluk tam roster DEĞİL → oyunu kastırmaz). Takım bazında top-11
//   overall ortalaması _teamPowerCache'e yazılır. Sıralama buradan okur.
let _teamPowerCache = null;   // { "CC:TeamName": ortalamaGuc }
async function _loadAllTeamsForRanking() {
  // 🆕 ÖLÇEK: bu fonksiyon TÜM players tablosunu sayfalayarak tarıyordu (35 bin satır).
  //   Takım gücü artık sunucuda hesaplanıp teams.team_ovr'de duruyor ve _cftDb ile
  //   birlikte zaten yükleniyor; tarama gereksiz. Çağrısı da kalmamıştı.
  if (true) return;
  if (!window.sb) return;
  try {
    // Takım gücü (kadro overall ortalaması) — TÜM oyuncular (Supabase 1000 limitini sayfalı aş)
    const byTeam = {};
    const PAGE = 1000; let from = 0;
    while (true) {
      const { data, error } = await window.sb.from('players')
        .select('team_name, country_code, overall')
        .range(from, from + PAGE - 1);
      if (error || !Array.isArray(data) || data.length === 0) { if (error) console.warn('[teamPower] yük hata:', error); break; }
      for (const r of data) {
        if (!r || !r.team_name) continue;
        const cc = (r.country_code || 'TR');
        const key = cc + ':' + r.team_name;
        (byTeam[key] || (byTeam[key] = [])).push(Number(r.overall) || 10);
      }
      if (data.length < PAGE) break;
      from += PAGE; if (from > 200000) break;
    }
    // Her takım için TÜM KADRO ortalaması (top-11 değil)
    const cache = {};
    for (const key in byTeam) {
      const ovrs = byTeam[key];
      if (!ovrs.length) { cache[key] = 10; continue; }
      cache[key] = Math.round(ovrs.reduce((a,b) => a+b, 0) / ovrs.length);
    }
    _teamPowerCache = cache;
  } catch(e) { console.warn('[teamPower] exception:', e); }
}

function getTop50Teams() {
  const all = [];
  if(false) return [];

  // 🆕 Kullanıcı takımını tanımla (tie-break + alt-tier dahil etme için)
  const myCC   = (typeof _userTeam !== 'undefined' && _userTeam) ? _userTeam.countryCode : null;
  const myName = (typeof _userTeam !== 'undefined' && _userTeam) ? _userTeam.teamName    : null;

  for(const [code, country] of _cftAllEntries()) {
    if(!country.leagues) continue;
    // 🆕 TÜM tier'lar — her ligdeki her takım havuza girer (sadece tier-0 DEĞİL → 1824'ün hepsi)
    country.leagues.forEach(lg => {
      if(!lg || !lg.teams) return;
      lg.teams.forEach(team => {
        const isUserTeam = !!(myCC && myName && code === myCC && team.name === myName);
        all.push({
          n: team.name, f: country.flag, cn: country.name,
          countryCode: code, lg: lg.name,
          o: _teamPowerFromPlayers(code, team.name, team.rank),
          rawRating: team.rating || 10,
          oz: team.oz || 0,
          mv: team.oz || 0,
          cf: (team.teamPoints || 0),
          av: TEAM_AV_BY_COUNTRY[code] || '🛡️',
          bg: team.bg, tc: team.tc, short: team.short,
          rank: team.rank,
          _isMe: isUserTeam,
        });
      });
    });
  }

  // 🆕 Sıralama: o azalan → eşitlikte kullanıcı takımı önde → sonra oz → isim
  return all
    .sort((a,b) =>
      (b.o - a.o) ||
      ((b._isMe?1:0) - (a._isMe?1:0)) ||
      ((b.oz||0) - (a.oz||0)) ||
      (a.n > b.n ? 1 : -1)
    );
}

// Eski sabit liste yerine fonksiyondan al (geriye dönük uyumluluk için global ad)
let RK_TOP_TEAMS = []; // DOMContentLoaded'da getTop50Teams ile dolduruluyor

// ── Ülke Katsayıları (UEFA tarzı: son 5 sezon) ──
// SIFIRLANDI — Sezon 1 başlangıç (1 Haziran 2026): tüm ülkelerin Avrupa puanı 0.
// Avrupa kupalarındaki performansla zamanla birikir.
// 🆕 Ülke puanı EDGE'de hesaplanır (world_state.data.country_points = {cc:{s:[son 5 sezon], total}}).
//   Eski uydurma seed/baz sistemi kaldırıldı — edge tek kaynak, ülke = kulüplerinin puan toplamı.
function _countryPts(cc) {
  const cp = (typeof _worldStateCache !== 'undefined' && _worldStateCache && _worldStateCache.country_points)
    ? _worldStateCache.country_points : null;
  const d = (cp && cp[cc]) ? cp[cc] : null;
  const s = (d && Array.isArray(d.s)) ? d.s : [0,0,0,0,0];
  const total = (d && typeof d.total === 'number') ? d.total : s.reduce((a,b)=>a+b,0);
  return { s, total };
}

