// ════════════════════════════════════════════════════════════════
// CFC MEDIA — Sosyal Medya (Adapter Pattern, backend-ready)
// ════════════════════════════════════════════════════════════════
// MİMARİ:
//   • SocialAdapter: Local (şu an) ↔ Server (backend gelince swap)
//   • Post veri şeması: {id, authorId, authorName, authorHandle, authorAvatar,
//                        authorTeam, authorVerified, content, ts, likes:[],
//                        replies:[], reposts:[]}
//   • localStorage anahtarları:
//     - cft_cfcmd_posts        : tüm postlar (oturum + bot)
//     - cft_cfcmd_my_likes     : kullanıcının beğendiği post ID'leri
//     - cft_cfcmd_my_reposts   : kullanıcının paylaştığı post ID'leri
//     - cft_cfcmd_following    : kullanıcının takip ettiği authorId'ler
//
// BACKEND GEÇİŞİ:
//   InboxAdapter gibi — SocialServerAdapter doldurulup _socialAdapter swap edilir
//   Tüm fonksiyon imzaları async (server geldiğinde fetch döner)


// Aktif adapter (backend gelince SocialServerAdapter ile değişir)
// ════════════════════════════════════════════════════════════════
// 🆕 SUPABASE SERVER ADAPTER — gerçek kullanıcılar, sosyal alan
// ════════════════════════════════════════════════════════════════
const SocialServerAdapter = {
  async getGlobal(limit) {
    if (!window.sb) return [];
    // Son 50 paylaşım (zaman sınırı yok)
    const { data, error } = await window.sb.from('social_posts')
      .select('id, author_id, author_country, post_data, ts')
      .order('ts', { ascending: false })
      .limit(limit || 50);
    if (error) { console.warn('[social] getGlobal:', error); return []; }
    return (data || []).map(_postFromRow);
  },
  async getNational(countryCode, limit) {
    if (!window.sb) return [];
    const { data, error } = await window.sb.from('social_posts')
      .select('id, author_id, author_country, post_data, ts')
      .eq('author_country', countryCode)
      .order('ts', { ascending: false })
      .limit(limit || 50);
    if (error) { console.warn('[social] getNational:', error); return []; }
    return (data || []).map(_postFromRow);
  },
  async getPostsByAuthor(authorId, limit) {
    if (!window.sb) return [];
    const { data, error } = await window.sb.from('social_posts')
      .select('id, author_id, author_country, post_data, ts')
      .eq('author_id', authorId)
      .order('ts', { ascending: false })
      .limit(limit || 50);
    if (error) { console.warn('[social] getPostsByAuthor:', error); return []; }
    return (data || []).map(_postFromRow);
  },
  async getFollowingFeed(limit) {
    if (!window.sb) return [];
    const myId = cfcMdGetMyId();
    // Önce takip edilenleri çek
    const { data: follows } = await window.sb.from('social_follows')
      .select('following_id').eq('follower_id', myId);
    const ids = (follows || []).map(f => f.following_id);
    if (ids.length === 0) return [];
    const { data, error } = await window.sb.from('social_posts')
      .select('id, author_id, author_country, post_data, ts')
      .in('author_id', ids)
      .order('ts', { ascending: false })
      .limit(limit || 50);
    if (error) { console.warn('[social] getFollowingFeed:', error); return []; }
    return (data || []).map(_postFromRow);
  },
  async createPost(content, extra) {
    if (!window.sb) return null;
    const my = cfcMdGetMyProfile();
    const myAvId = (typeof authUser !== 'undefined' && authUser && authUser.avatarId) ? authUser.avatarId : null;
    const id = 'p_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7);
    const post = {
      id,
      authorId: my.id,
      authorName: my.name,
      authorHandle: my.handle,
      authorAvatarId: myAvId,
      authorAvatar: '⚽',
      authorTeam: my.team,
      authorCountry: my.country,
      authorVerified: false,
      content,
      ts: Date.now(),
      likeCount: 0,
      dislikeCount: 0,
      repostCount: 0,
      likes: [],
      dislikes: [],
      replies: [],
      reposts: [],
    };
    // 🆕 Hazır paylaşım şablonu (Takım/Futbolcu Arıyorum) — kart verisi posta gömülür
    if (extra && typeof extra === 'object') Object.assign(post, extra);
    const { error } = await window.sb.from('social_posts').insert({
      id,
      author_id: my.id,
      author_country: my.country,
      post_data: post,
      ts: new Date().toISOString()
    });
    if (error) {
      if (String(error.message || '').includes('tpl_gunluk')) return { hata: 'tpl_gunluk' };
      console.warn('[social] createPost:', error); return null;
    }
    return post;
  },
  async toggleLike(postId) {
    if (!window.sb) return null;
    const myId = cfcMdGetMyId();
    // Mevcut reaksiyon
    const { data: existing } = await window.sb.from('social_likes')
      .select('reaction').eq('user_id', myId).eq('post_id', postId).maybeSingle();
    if (existing && existing.reaction === 'like') {
      // Kaldır
      const { error } = await window.sb.from('social_likes')
        .delete().eq('user_id', myId).eq('post_id', postId);
      if (error) { console.warn('[social] toggleLike sil:', error); return { hata: true }; }
      const count = await _socialCountReaction(postId, 'like');
      return { liked: false, count };
    } else {
      // Like at (varsa dislike sil)
      const { error } = await window.sb.from('social_likes').upsert({
        user_id: myId, post_id: postId, reaction: 'like'
      }, { onConflict: 'user_id,post_id' });
      if (error) { console.warn('[social] toggleLike:', error); return { hata: true }; }
      const count = await _socialCountReaction(postId, 'like');
      return { liked: true, count };
    }
  },
  async toggleDislike(postId) {
    if (!window.sb) return null;
    const myId = cfcMdGetMyId();
    const { data: existing } = await window.sb.from('social_likes')
      .select('reaction').eq('user_id', myId).eq('post_id', postId).maybeSingle();
    if (existing && existing.reaction === 'dislike') {
      const { error } = await window.sb.from('social_likes')
        .delete().eq('user_id', myId).eq('post_id', postId);
      if (error) { console.warn('[social] toggleDislike sil:', error); return { hata: true }; }
      const count = await _socialCountReaction(postId, 'dislike');
      return { disliked: false, count };
    } else {
      const { error } = await window.sb.from('social_likes').upsert({
        user_id: myId, post_id: postId, reaction: 'dislike'
      }, { onConflict: 'user_id,post_id' });
      if (error) { console.warn('[social] toggleDislike:', error); return { hata: true }; }
      const count = await _socialCountReaction(postId, 'dislike');
      return { disliked: true, count };
    }
  },
  async toggleRepost(postId) {
    // Repost'lar şimdilik post_data içinde tutulur (basit)
    if (!window.sb) return null;
    const myId = cfcMdGetMyId();
    const { data: row } = await window.sb.from('social_posts')
      .select('post_data').eq('id', postId).maybeSingle();
    if (!row) return null;
    const p = row.post_data || {};
    if (!Array.isArray(p.reposts)) p.reposts = [];
    const idx = p.reposts.indexOf(myId);
    if (idx === -1) p.reposts.push(myId); else p.reposts.splice(idx, 1);
    p.repostCount = p.reposts.length;
    // ⚠️ Bu güncelleme yalnızca KENDİ gönderinde çalışır: satır sahibi
    //    olmadığın için başkasının gönderisinde 0 satır etkilenir.
    //    `.select()` ile gerçekten güncellendi mi kontrol ediyoruz.
    const { data: upd, error } = await window.sb.from('social_posts')
      .update({ post_data: p }).eq('id', postId).select('id');
    if (error || !upd || !upd.length) {
      console.warn('[social] toggleRepost yazılamadı:', error);
      return { hata: true, sebep: 'izin_yok' };
    }
    return { reposted: idx === -1, count: p.reposts.length };
  },
  async toggleFollow(authorId) {
    if (!window.sb) return null;
    const myId = cfcMdGetMyId();
    if (myId === authorId) return { following: false };  // kendini takip edemez
    const { data: existing } = await window.sb.from('social_follows')
      .select('follower_id').eq('follower_id', myId).eq('following_id', authorId).maybeSingle();
    if (existing) {
      const { error } = await window.sb.from('social_follows').delete()
        .eq('follower_id', myId).eq('following_id', authorId);
      if (error) { console.warn('[social] takipten çık:', error); return { hata: true }; }
      return { following: false };
    } else {
      const { error } = await window.sb.from('social_follows').insert({
        follower_id: myId, following_id: authorId
      });
      if (error) { console.warn('[social] takip et:', error); return { hata: true }; }
      return { following: true };
    }
  },
  async deletePost(postId) {
    if (!window.sb) return { deleted: false, reason: 'no_sb' };
    const myId = cfcMdGetMyId();
    const { data: row } = await window.sb.from('social_posts')
      .select('author_id').eq('id', postId).maybeSingle();
    if (!row) return { deleted: false, reason: 'not_found' };
    if (row.author_id !== myId) return { deleted: false, reason: 'forbidden' };
    // `.select()` silinen satırları geri döndürür — boşsa silme
    // GERÇEKLEŞMEMİŞTİR (ör. veritabanı izin vermedi). Eskiden bu
    // kontrol yoktu ve kullanıcıya "silindi" deniyordu.
    const { data: silinen, error } = await window.sb.from('social_posts')
      .delete().eq('id', postId).select('id');
    if (error) {
      console.warn('[social] deletePost:', error);
      return { deleted: false, reason: 'error' };
    }
    if (!silinen || !silinen.length) {
      return { deleted: false, reason: 'forbidden' };
    }
    // Bağlı reaksiyonları da temizle (başarısız olsa da gönderi gitti)
    await window.sb.from('social_likes').delete().eq('post_id', postId);
    return { deleted: true };
  },
};

// Post row → frontend post objesi (post_data + likeCount hesabı)
function _postFromRow(row) {
  const p = row.post_data || {};
  p.id = row.id;
  p.authorId = row.author_id || p.authorId;
  p.authorCountry = row.author_country || p.authorCountry;
  if (typeof row.ts === 'string') {
    const t = Date.parse(row.ts);
    if (!isNaN(t)) p.ts = t;
  }
  return p;
}

// Reaksiyon sayısını sayar
async function _socialCountReaction(postId, reaction) {
  if (!window.sb) return 0;
  const { count } = await window.sb.from('social_likes')
    .select('user_id', { count: 'exact', head: true })
    .eq('post_id', postId).eq('reaction', reaction);
  return count || 0;
}

// Aktif adapter — Supabase server adapter kullan
let _socialAdapter = SocialServerAdapter;

// 🆕 Takip listesi RAM cache (Supabase'ten yüklenir)
let _cfcMdFollowingCache = [];
let _cfcMdFollowersCache = [];

async function cfcMdLoadFollows() {
  if (!window.sb) { _cfcMdFollowingCache = []; _cfcMdFollowersCache = []; return; }
  const myId = cfcMdGetMyId();
  try {
    const [fingRes, fersRes] = await Promise.all([
      window.sb.from('social_follows').select('following_id').eq('follower_id', myId),
      window.sb.from('social_follows').select('follower_id').eq('following_id', myId),
    ]);
    _cfcMdFollowingCache = (fingRes.data || []).map(r => r.following_id);
    _cfcMdFollowersCache = (fersRes.data || []).map(r => r.follower_id);
  } catch(e) { console.warn('[social] follows hata:', e); }
}

function cfcMdGetFollowing() {
  return _cfcMdFollowingCache.slice();
}

function cfcMdGetFollowersList() {
  return _cfcMdFollowersCache.slice();
}

function cfcMdGetMyId() {
  try {
    if (typeof authUser !== 'undefined' && authUser && authUser.username) {
      // @ ile başlıyorsa temizle (benzersiz username sadece harfler)
      const u = String(authUser.username).replace(/^@+/, '').toLowerCase();
      if (u) return 'user:' + u;
    }
  } catch(e) {}
  return 'user:guest';
}

function cfcMdGetMyProfile() {
  const u = (typeof authUser !== 'undefined') ? authUser : {};
  const t = (typeof _userTeam !== 'undefined') ? _userTeam : null;
  const cc = (t && t.countryCode) || u.nationality || 'TR';
  // Username @ ile başlıyorsa temizle (kayıt sırasında @ ile yazılmış olabilir)
  const cleanUsername = String(u.username || 'guest').replace(/^@+/, '').toLowerCase();
  // 🆕 Oyuncunun seçtiği avatar (PNG img ya da emoji) — getAvatarEmoji HTML döner
  let avatarHTML = '⚽';
  try {
    if (u && u.avatarId && typeof getAvatarEmoji === 'function') {
      avatarHTML = getAvatarEmoji(u.avatarId, u.position || (t && t.userPos) || null);
    } else if (typeof getAvatarEmoji === 'function') {
      // avatarId yoksa pozisyona göre fallback emoji
      avatarHTML = getAvatarEmoji(null, u.position || (t && t.userPos) || null);
    }
  } catch(e) { avatarHTML = '⚽'; }
  return {
    id: cfcMdGetMyId(),
    name: u.name || 'Oyuncu',
    handle: '@' + cleanUsername,
    avatar: avatarHTML,
    team: t ? t.teamName : null,
    teamCc: t ? t.countryCode : null,
    country: cc,
  };
}

// 622 — Gece Akışı ikonları (emoji yerine)
const _CFCMD_IK = (() => {
  const s = (d) => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round">${d}</svg>`;
  return {
    dunya: s('<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c2.6 2.6 3.8 5.6 3.8 9s-1.2 6.4-3.8 9M12 3C9.4 5.6 8.2 8.6 8.2 12s1.2 6.4 3.8 9"/>'),
    kisiler: s('<circle cx="9" cy="8" r="3.5"/><path d="M2.5 20a6.5 6.5 0 0 1 13 0M16 4.6a3.5 3.5 0 0 1 0 6.8M18 14.2a6.4 6.4 0 0 1 3.5 5.8"/>'),
    sohbet: s('<path d="M21 12a8 8 0 0 1-11.6 7.1L4 20.5l1.4-4.9A8 8 0 1 1 21 12z"/>'),
    kalem: s('<path d="M4 20h4L19 9l-4-4L4 16z"/><path d="M14 6l4 4"/>'),
    ara: s('<circle cx="11" cy="11" r="7"/><path d="M20 20l-3.4-3.4"/>'),
    sag: s('<polyline points="9 6 15 12 9 18"/>'),
    kupa: s('<path d="M8 4h8v5a4 4 0 0 1-8 0z"/><path d="M8 5.5H5a3 3 0 0 0 3 4M16 5.5h3a3 3 0 0 1-3 4M12 13v4M8.5 20h7"/>'),
    carpi: s('<circle cx="12" cy="12" r="9"/><path d="M9 9l6 6M15 9l-6 6"/>'),
    saat: s('<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'),
    hedef: s('<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1.2" fill="currentColor"/>'),
  };
})();

// 622 — Rozetler (sunucu: sosyal_rozetler)
//   Mavi tik  : 1000 ve üstü takipçi
//   Altın tik : kariyerinde Avrupa kupası şampiyonluğu (Championship, Elite, Conference
//               ya da EURO Cup şampiyon kadrosunda yer almış). İkisi birden varsa altın.
const _cfcMdRozet = {};
async function _cfcMdRozetYukle(ids) {
  if (!window.sb) return;
  const simdi = Date.now();
  const adlar = [...new Set((ids || []).map(x => String(x || '').replace(/^user:/, '')).filter(a => a && a !== 'guest'))]
    .filter(a => !_cfcMdRozet[a] || simdi - _cfcMdRozet[a].t > 300000).slice(0, 100);
  if (!adlar.length) return;
  const { data, error } = await window.sb.rpc('sosyal_rozetler', { p_adlar: adlar });
  if (error) { console.warn('[social] rozet:', error.message || error); return; }
  for (const r of (data || [])) _cfcMdRozet[r.ad] = { t: simdi, takipci: r.takipci || 0, altin: !!r.altin };
}
function _cfcMdTik(id) {
  const r = _cfcMdRozet[String(id || '').replace(/^user:/, '')];
  const tur = !r ? '' : (r.altin ? 'altin' : (r.takipci >= 1000 ? 'mavi' : ''));
  if (!tur) return '';
  return `<svg class="cfcmd-tik ${tur}" viewBox="0 0 24 24"><path fill="currentColor" d="M12 1.8l2.6 1.9 3.2-.1 1 3 2.6 1.9-1 3.1 1 3.1-2.6 1.9-1 3-3.2-.1L12 22.2l-2.6-1.9-3.2.1-1-3-2.6-1.9 1-3.1-1-3.1L5.2 6.6l1-3 3.2.1z"/><path d="M8 12.3l2.7 2.7 5.5-5.6" fill="none" stroke="#fff" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
}

// 622 — Tek gönderi kartı (akış ve profil aynı kalıbı kullanır)
function _cfcMdPostHtml(p, o) {
  const { liked, disliked, likeC, dislikeC } = o;
  const taggedBody = _cfcMdEscape(modFiltre(p.content)).replace(/(#[\wçğıöşüÇĞİÖŞÜ]+|@[\w]+)/g, '<span class="cfcmd-tag">$1</span>');
  const cardHtml = (p.kind === 'tpl-player' || p.kind === 'tpl-team') ? _cfcMdTemplateCardHtml(p) : '';
  return `<div class="cfcmd-post${o.isMine ? ' is-mine' : ''}">
      ${o.isMine ? `<button class="cfcmd-post-del" onclick="cfcMdAskDelete('${p.id}')" aria-label="Gönderiyi sil" title="Gönderiyi sil">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
          <polyline points="3 6 5 6 21 6"/>
          <path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/>
          <path d="M10 11v6M14 11v6"/>
          <path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"/>
        </svg>
      </button>` : `<button class="cfcmd-post-more" onclick="modMenuAc('${_modKayit({ tur: 'gonderi', hedef: p.authorId, ad: p.authorName, icerikId: p.id, icerik: p.content })}')" aria-label="Diğer">${_MOD_IK.daha}</button>`}
      <div class="cfcmd-post-head" data-yazar="${_cfcMdEscape(p.authorId)}" onclick="cfcMdYazarAc(this)">
        <div class="cfcmd-post-avatar">${o.avatar}</div>
        <div class="cfcmd-post-author">
          <div class="cfcmd-post-name"><span class="cfcmd-post-ad">${_cfcMdEscape(p.authorName)}</span>${_cfcMdTik(p.authorId)}</div>
          <div class="cfcmd-post-sub"><span class="cfcmd-post-handle">${_cfcMdEscape(p.authorHandle)}</span><span class="cfcmd-post-time">${_cfcMdRelTime(p.ts)}</span></div>
        </div>
      </div>
      <div class="cfcmd-post-body">${taggedBody}</div>
      ${cardHtml}
      <div class="cfcmd-post-actions">
        <button class="cfcmd-post-action ${liked?'liked':''}" onclick="cfcMdToggleLike('${p.id}')" aria-label="Beğen">
          <svg class="cfcmd-icon cfcmd-icon-like" viewBox="0 0 24 24" fill="${liked?'currentColor':'none'}" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"><path d="M7 22V11M2 13v7a2 2 0 0 0 2 2h3V11H4a2 2 0 0 0-2 2zm18.79-3.39A2 2 0 0 0 19 9h-5.12l.92-4.39a1 1 0 0 0-.17-.84A1 1 0 0 0 13.83 3h-.5a1 1 0 0 0-.76.35L7 11v11h10.56a2 2 0 0 0 2-1.68l1.28-8.32a2 2 0 0 0-.05-.79z"/></svg>
          <span>${likeC}</span>
        </button>
        <button class="cfcmd-post-action ${disliked?'disliked':''}" onclick="cfcMdToggleDislike('${p.id}')" aria-label="Beğenme">
          <svg class="cfcmd-icon cfcmd-icon-dislike" viewBox="0 0 24 24" fill="${disliked?'currentColor':'none'}" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"><path d="M17 2v11M22 11V4a2 2 0 0 0-2-2h-3v11h3a2 2 0 0 0 2-2zM3.21 14.39A2 2 0 0 0 5 15h5.12l-.92 4.39a1 1 0 0 0 .17.84 1 1 0 0 0 .8.39h.5a1 1 0 0 0 .76-.35L17 13V2H6.44a2 2 0 0 0-2 1.68l-1.28 8.32a2 2 0 0 0 .05.79z"/></svg>
          <span>${dislikeC}</span>
        </button>
      </div>
    </div>`;
}

// ── UI Render ──
let _cfcMdCurrentTab = 'profile';
// 🆕 Ziyaretçi modu — başka kullanıcının profilini görüntüleme state'i
// null ise kendi profilim, "user:xxx" ise o kullanıcının profili
let _cfcMdViewingUserId = null;

function cfcMdTab(tab, el) {
  // 🆕 Profile tab'a her tıklamada kendi profile dön (ziyaretçi modu sıfırlanır)
  if (tab === 'profile') {
    _cfcMdViewingUserId = null;
  }
  _cfcMdCurrentTab = tab;
  document.querySelectorAll('.cfcmd-tab').forEach(t => t.classList.remove('active'));
  if (el) el.classList.add('active');

  // Pane toggle
  document.getElementById('cfcMdGlobal').style.display    = tab === 'global' ? 'block' : 'none';
  document.getElementById('cfcMdNational').style.display  = tab === 'national' ? 'block' : 'none';
  document.getElementById('cfcMdFollowing').style.display = tab === 'following' ? 'block' : 'none';
  document.getElementById('cfcMdProfile').style.display   = tab === 'profile' ? 'block' : 'none';

  if (tab === 'profile') _bnGordu('cfc_takipci');   // 728 — Profilim: takipçiler görüldü
  else if (tab === 'following') _bnGordu('cfc_takip');
  cfcMdRender();
}

async function cfcMdRender() {
  if (_cfcMdCurrentTab === 'global') {
    const posts = await _socialAdapter.getGlobal(50);
    const wrap = document.getElementById('cfcMdGlobal');
    if (!posts.length) {
      wrap.innerHTML = `<div class="cfcmd-empty"><div class="cfcmd-empty-icon">${_CFCMD_IK.dunya}</div>Henüz gönderi yok.<br><span style="font-size:11px;opacity:.7">Backend bağlandığında dünya üzerindeki kullanıcıların paylaşımları burada gözükecek.</span></div>`;
    } else {
      cfcMdRenderPosts(posts, wrap);
    }
  } else if (_cfcMdCurrentTab === 'national') {
    const my = cfcMdGetMyProfile();
    const posts = await _socialAdapter.getNational(my.country, 50);
    const wrap = document.getElementById('cfcMdNational');
    const countryName = _uyrukUlke(my.country).name || my.country;
    const countryFlag = _uyrukUlke(my.country).flag || '🏳️';
    if (!posts.length) {
      wrap.innerHTML = `<div class="cfcmd-empty"><div class="cfcmd-empty-icon">${countryFlag}</div>${countryName} ülkesinden henüz gönderi yok.<br><span style="font-size:11px;opacity:.7">Backend bağlandığında ülkendeki kullanıcıların paylaşımları burada gözükecek.</span></div>`;
    } else {
      cfcMdRenderPosts(posts, wrap);
    }
  } else if (_cfcMdCurrentTab === 'following') {
    const posts = await _socialAdapter.getFollowingFeed(50);
    const wrap = document.getElementById('cfcMdFollowing');
    if (!posts.length) {
      wrap.innerHTML = `<div class="cfcmd-empty"><div class="cfcmd-empty-icon">${_CFCMD_IK.kisiler}</div>Henüz kimseyi takip etmiyorsun.<br><span style="font-size:11px;opacity:.7">Backend bağlandığında takip ettiğin kullanıcıların paylaşımları burada gözükecek.</span></div>`;
    } else {
      cfcMdRenderPosts(posts, wrap);
    }
  } else if (_cfcMdCurrentTab === 'profile') {
    cfcMdRenderProfile();
  }
}

async function cfcMdRenderPosts(posts, container) {
  if (!container) return;
  posts = posts.filter(p => !modEngelliMi(p.authorId));
  if (!posts.length) {
    container.innerHTML = `<div class="cfcmd-empty"><div class="cfcmd-empty-icon">${_CFCMD_IK.sohbet}</div>Henüz gönderi yok.<br>İlk paylaşımı sen yap!</div>`;
    return;
  }
  const myId = cfcMdGetMyId();
  const myAvatarHTML = (typeof cfcMdGetMyProfile === 'function') ? (cfcMdGetMyProfile().avatar || '⚽') : '⚽';

  // 🆕 Tüm postların reaksiyonlarını server'dan toplu çek
  let myReactions = {};
  let postCounts = {};
  try {
    if (window.sb) {
      const postIds = posts.map(p => p.id);
      const [meRes, allRes] = await Promise.all([
        window.sb.from('social_likes').select('post_id, reaction').eq('user_id', myId).in('post_id', postIds),
        window.sb.from('social_likes').select('post_id, reaction').in('post_id', postIds),
      ]);
      (meRes.data || []).forEach(r => { myReactions[r.post_id] = r.reaction; });
      (allRes.data || []).forEach(r => {
        if (!postCounts[r.post_id]) postCounts[r.post_id] = { like: 0, dislike: 0 };
        postCounts[r.post_id][r.reaction] = (postCounts[r.post_id][r.reaction] || 0) + 1;
      });
    }
  } catch(e) { console.warn('[social] renderPosts reacts:', e); }

  await _cfcMdRozetYukle(posts.map(p => p.authorId));
  container.innerHTML = posts.map(p => {
    let avatarHTML;
    if (p.authorId === myId) {
      avatarHTML = myAvatarHTML;
    } else if (p.authorAvatarId && typeof getAvatarEmoji === 'function') {
      avatarHTML = getAvatarEmoji(p.authorAvatarId, null);
    } else {
      avatarHTML = p.authorAvatar || '⚽';
    }
    return _cfcMdPostHtml(p, {
      avatar: avatarHTML,
      isMine: p.authorId === myId,
      liked: myReactions[p.id] === 'like',
      disliked: myReactions[p.id] === 'dislike',
      likeC: (postCounts[p.id] && postCounts[p.id].like) || 0,
      dislikeC: (postCounts[p.id] && postCounts[p.id].dislike) || 0
    });
  }).join('');
}

async function cfcMdRenderProfile() {
  const my = cfcMdGetMyProfile();
  const myId = my.id;

  // 🆕 Ziyaretçi modu: _cfcMdViewingUserId set ise farklı kullanıcının profili
  const viewingOther = _cfcMdViewingUserId && _cfcMdViewingUserId !== myId;
  let viewedUser;
  if (viewingOther) {
    // Bilinen kullanıcılar listesinden bul (cache yoksa server'dan yükle)
    let known = cfcMdGetKnownUsers();
    if (!known.some(u => u.id === _cfcMdViewingUserId)) {
      try { await cfcMdLoadUsersByIds([_cfcMdViewingUserId]); } catch(e) {}
      known = cfcMdGetKnownUsers();
    }
    viewedUser = known.find(u => u.id === _cfcMdViewingUserId) || {
      id: _cfcMdViewingUserId,
      name: 'Bilinmeyen Kullanıcı',
      handle: '@' + _cfcMdViewingUserId.replace('user:', ''),
      avatar: '⚽',
      avatarId: null,
      team: null,
      country: null,
    };
  } else {
    viewedUser = my;
  }

  await _cfcMdRozetYukle([viewedUser.id]);

  // 🆕 Server'dan o kullanıcının postlarını çek
  let userPosts = [];
  try {
    userPosts = await _socialAdapter.getPostsByAuthor(viewedUser.id, 50);
  } catch(e) { console.warn('[social] profile posts:', e); }
  
  // Reaksiyonları çek (kendi cihazımdan kim like/dislike etmiş)
  let myReactions = {};
  try {
    if (window.sb && userPosts.length) {
      const postIds = userPosts.map(p => p.id);
      const { data: reacts } = await window.sb.from('social_likes')
        .select('post_id, reaction').eq('user_id', myId).in('post_id', postIds);
      (reacts || []).forEach(r => { myReactions[r.post_id] = r.reaction; });
    }
  } catch(e) {}
  
  // Reaksiyon sayılarını çek (her post için)
  let postCounts = {};
  try {
    if (window.sb && userPosts.length) {
      const postIds = userPosts.map(p => p.id);
      const { data: allReacts } = await window.sb.from('social_likes')
        .select('post_id, reaction').in('post_id', postIds);
      (allReacts || []).forEach(r => {
        if (!postCounts[r.post_id]) postCounts[r.post_id] = { like: 0, dislike: 0 };
        postCounts[r.post_id][r.reaction] = (postCounts[r.post_id][r.reaction] || 0) + 1;
      });
    }
  } catch(e) {}
  
  const totalLikes = userPosts.reduce((s, p) => s + ((postCounts[p.id] && postCounts[p.id].like) || 0), 0);
  const totalDislikes = userPosts.reduce((s, p) => s + ((postCounts[p.id] && postCounts[p.id].dislike) || 0), 0);
  const followerCount = cfcMdGetFollowerCount(viewedUser.id);
  const following = cfcMdGetFollowing();
  const isFollowing = following.includes(viewedUser.id);
  // 🆕 Ziyaretçi modunda: kullanıcının takip+takipçi sayılarını server'dan çek
  let followingDisplay;
  let viewedFollowerCount = followerCount;
  if (viewingOther) {
    try {
      const stats = await cfcMdLoadUserFollowStats(viewedUser.id);
      viewedFollowerCount = stats.followers;
      followingDisplay = stats.following;
    } catch(e) { followingDisplay = '—'; }
  } else {
    followingDisplay = following.length;
  }

  const postsHtml = userPosts.filter(p => !modEngelliMi(p.authorId)).map(p => _cfcMdPostHtml(p, {
    avatar: !viewingOther ? (my.avatar || p.authorAvatar || '⚽') : (viewedUser.avatar || p.authorAvatar || '⚽'),
    isMine: !viewingOther && p.authorId === myId,
    liked: myReactions[p.id] === 'like',
    disliked: myReactions[p.id] === 'dislike',
    likeC: (postCounts[p.id] && postCounts[p.id].like) || 0,
    dislikeC: (postCounts[p.id] && postCounts[p.id].dislike) || 0
  })).join('');

  // 🆕 Ziyaretçi modunda: üstte geri butonu + isim + takip et, compose yok
  const visitorBar = viewingOther ? `
    <div class="cfcmd-visitor-bar">
      <button class="cfcmd-visitor-back" onclick="cfcMdBackToMyProfile()" aria-label="Geri">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">
          <polyline points="15 18 9 12 15 6"/>
        </svg>
      </button>
      <div class="cfcmd-visitor-title">${_cfcMdEscape(viewedUser.name)}</div>
      <button class="cfcmd-follow-btn ${isFollowing?'following':''}" onclick="cfcMdToggleFollowUser('${viewedUser.id}')">
        ${isFollowing ? 'Takiptesin' : 'Takip Et'}
      </button>
      <button class="cfcmd-visitor-more" onclick="modMenuAc('${_modKayit({ tur: 'profil', hedef: viewedUser.id, ad: viewedUser.name })}')" aria-label="Diğer">${_MOD_IK.daha}</button>
    </div>
  ` : '';

  // 🆕 Ziyaretçi modunda compose yok
  const composeHtml = viewingOther ? '' : `
    <!-- Paylaşım kutusu (sadece kendi profilimde) -->
    <div class="cfcmd-compose">
      <div class="cfcmd-tpl-row">
        <button class="cfcmd-tpl-btn tpl-player" onclick="cfcMdShareTemplate('player', this)"><svg class="cfcmd-tpl-ic" viewBox="0 0 24 24"><use href="#ic-soccer"/></svg>Takım Arıyorum</button>
        <button class="cfcmd-tpl-btn tpl-team" onclick="cfcMdShareTemplate('team', this)"><svg class="cfcmd-tpl-ic" viewBox="0 0 24 24"><use href="#ic-team"/></svg>Futbolcu Arıyorum</button>
      </div>
      <div class="cfcmd-compose-row">
        <div class="cfcmd-avatar">${my.avatar}</div>
        <textarea class="cfcmd-textarea" id="cfcMdComposeText" placeholder="Aklından ne geçiyor? (en fazla 280 karakter)" maxlength="280" oninput="cfcMdUpdateCharCount()"></textarea>
      </div>
      <div class="cfcmd-compose-foot">
        <span class="cfcmd-char-count" id="cfcMdCharCount">0/280</span>
        <button class="cfcmd-post-btn" onclick="cfcMdSubmitPost()" aria-label="Paylaş">
          <svg viewBox="0 0 24 24" fill="currentColor" stroke="none">
            <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/>
          </svg>
        </button>
      </div>
    </div>
  `;

  // 622 — kapak takım renginde, silik arma; takımsız: lacivert
  const takimCc = viewedUser.teamCc || null;
  const takimObj = (viewedUser.team && takimCc) ? _cftFindTeam(takimCc, viewedUser.team) : null;
  const kapakArma = viewedUser.team ? inlineBadge({ name: viewedUser.team, cc: takimCc || undefined, tag: 'span', cls: 'cfcmd-kapak-arma' }) : '';
  const takimCip = viewedUser.team
    ? `<span class="cfcmd-profile-takim">${inlineBadge({ name: viewedUser.team, cc: takimCc || undefined, tag: 'span', cls: 'cfcmd-arma' })}${_cfcMdEscape(viewedUser.team)}</span>` : '';

  const sectionTitle = viewingOther ? 'Gönderileri' : 'Gönderilerin';
  const emptyMsg = viewingOther ? 'Henüz paylaşımı yok.' : 'Henüz paylaşım yapmadın.';

  document.getElementById('cfcMdProfile').innerHTML = `
    ${visitorBar}
    <div class="cfcmd-profile-card">
      <div class="cfcmd-kapak"${takimObj && takimObj.bg ? ` style="--kapak:${takimObj.bg}"` : ''}>${kapakArma}</div>
      <div class="cfcmd-profile-avatar">${viewedUser.avatar || '⚽'}</div>
      <div class="cfcmd-profile-name"><span>${_cfcMdEscape(viewedUser.name)}</span>${_cfcMdTik(viewedUser.id)}</div>
      <div class="cfcmd-profile-handle"><span>${_cfcMdEscape(viewedUser.handle)}</span>${takimCip}</div>
      <div class="cfcmd-profile-stats">
        <div class="cfcmd-profile-stat">
          <div class="cfcmd-profile-stat-val">${userPosts.length}</div>
          <div class="cfcmd-profile-stat-lbl">Gönderi</div>
        </div>
        <div class="cfcmd-profile-stat">
          <div class="cfcmd-profile-stat-val" style="color:#00e676">${totalLikes}</div>
          <div class="cfcmd-profile-stat-lbl">Like</div>
        </div>
        <div class="cfcmd-profile-stat">
          <div class="cfcmd-profile-stat-val" style="color:#ef5350">${totalDislikes}</div>
          <div class="cfcmd-profile-stat-lbl">Dislike</div>
        </div>
        <div class="cfcmd-profile-stat${!viewingOther ? ' clickable' : ''}"${!viewingOther ? " onclick=\"cfcMdOpenFollows('following')\"" : ''}>
          <div class="cfcmd-profile-stat-val">${followingDisplay}</div>
          <div class="cfcmd-profile-stat-lbl">Takip</div>
        </div>
        <div class="cfcmd-profile-stat${!viewingOther ? ' clickable' : ''}"${!viewingOther ? " onclick=\"cfcMdOpenFollows('followers')\"" : ''}>
          <div class="cfcmd-profile-stat-val">${viewedFollowerCount}</div>
          <div class="cfcmd-profile-stat-lbl">Takipçi</div>
        </div>
      </div>
    </div>

    ${composeHtml}

    <div class="cfcmd-section-title">${sectionTitle}</div>
    ${userPosts.length ? postsHtml : `<div class="cfcmd-empty"><div class="cfcmd-empty-icon">${_CFCMD_IK.kalem}</div>${emptyMsg}</div>`}
  `;
}

function cfcMdUpdateCharCount() {
  const ta = document.getElementById('cfcMdComposeText');
  const cnt = document.getElementById('cfcMdCharCount');
  if (!ta || !cnt) return;
  const len = ta.value.length;
  cnt.textContent = `${len}/280`;
  cnt.style.color = len > 260 ? '#ef5350' : 'var(--text3)';
}

async function cfcMdSubmitPost() {
  const ta = document.getElementById('cfcMdComposeText');
  if (!ta) {
    console.error('[CFC Media] textarea bulunamadı');
    return;
  }
  const text = (ta.value || '').trim();
  if (!text) return;
  if (text.length > 280) return;

  try {
    const newPost = await _socialAdapter.createPost(modFiltre(text));
    // ⚠️ createPost hata durumunda null döner. Eskiden bu kontrol
    //    yoktu: metin kutusu temizleniyor, profil sekmesine geçiliyor
    //    ve kullanıcı paylaştığını sanıyordu.
    if (!newPost) {
      if (typeof tfShowToast === 'function')
        tfShowToast('❌ Gönderi paylaşılamadı, tekrar dene', '#ef5350');
      return;
    }

    ta.value = '';
    cfcMdUpdateCharCount();

    // Profil sekmesinde isek, render et — değilse profil sekmesine geç
    if (_cfcMdCurrentTab !== 'profile') {
      const profileTabBtn = document.querySelector('.cfcmd-tab[data-cfcmd-tab="profile"]');
      cfcMdTab('profile', profileTabBtn);
    } else {
      cfcMdRender();
    }

    if (typeof tfShowToast === 'function') tfShowToast('📤 Paylaşıldı', 'var(--accent)');
  } catch(e) {
    console.error('[CFC Media] Post hatası:', e);
    if (typeof tfShowToast === 'function') tfShowToast('❌ Paylaşılamadı: ' + e.message, '#ef5350');
  }
}

// 🆕 Hazır paylaşım şablonları — gerçek oyuncu/takım verisinden kart üretir ve paylaşır
const _CFCMD_POS = {
  GK:  { short:'GK',  cls:'gk',  label:'Kaleci' },
  DEF: { short:'DEF', cls:'def', label:'Defans' },
  MID: { short:'MID', cls:'mid', label:'Orta Saha' },
  FWD: { short:'FWD', cls:'fw',  label:'Forvet' },
};
function _cfcMdMyPlayer() {
  try {
    if (typeof ROSTER_DATA !== 'undefined' && Array.isArray(ROSTER_DATA))
      return ROSTER_DATA.find(p => p && p.role === 'user') || null;
  } catch(e) {}
  return null;
}
function _cfcMdInitials(name) {
  const parts = String(name || '').trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return '⚽';
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}
// Yetkisiz kullanıcı "Futbolcu Arıyorum"a basınca buton üstünde küçük baloncuk uyarısı
function _cfcMdRoleBubble(btn) {
  const msg = 'Bu özelliği sadece kaptan ve yardımcı kaptan kullanabilir';
  const row = btn && btn.parentElement;
  if (!row) { if (typeof tfShowToast === 'function') tfShowToast(msg, '#ff9800'); return; }
  const old = row.querySelector('.cfcmd-role-bubble'); if (old) old.remove();
  const b = document.createElement('div');
  b.className = 'cfcmd-role-bubble';
  b.textContent = msg;
  b.style.left = (btn.offsetLeft + btn.offsetWidth / 2) + 'px';
  row.appendChild(b);
  requestAnimationFrame(() => b.classList.add('show'));
  setTimeout(() => { b.classList.remove('show'); setTimeout(() => b.remove(), 220); }, 2600);
}
async function cfcMdShareTemplate(kind, btn) {
  if (!window.sb) { if (typeof tfShowToast === 'function') tfShowToast('❌ Bağlantı yok', '#ef5350'); return; }
  const t = (typeof _userTeam !== 'undefined') ? _userTeam : null;
  try {
    let extra, content = '';
    if (kind === 'player') {
      const pl = _cfcMdMyPlayer();
      if (!pl) { if (typeof tfShowToast === 'function') tfShowToast('❌ Oyuncu verisi bulunamadı', '#ef5350'); return; }
      const altPos = subPosOf(pl);
      const posInfo = _CFCMD_POS[SUBPOS_GROUP[altPos]];
      const ovr = Math.round((typeof getPlayerMainOverall === 'function') ? getPlayerMainOverall(pl) : (pl.overall || pl.rating || 10));
      // KL/DF/OS/FW = 4 mevki grubu ortalaması. OVR ile BİREBİR aynı kaynak:
      // getSkillLevels + SKILL_DEFS.ALL (OVR de bu yoldan hesaplanıyor, bkz getPlayerMainOverall).
      let catVals = null;
      if (typeof getSkillLevels === 'function' && typeof SKILL_DEFS !== 'undefined' && SKILL_DEFS.ALL) {
        try {
          const lvls = getSkillLevels(pl.pos || 'MID');
          const _ca = (cat) => {
            const sk = cat && cat.skills;
            if (!sk || !sk.length) return null;
            return sk.reduce((a, s) => a + (lvls[s.id] || 10), 0) / sk.length;
          };
          catVals = [_ca(SKILL_DEFS.ALL[0]), _ca(SKILL_DEFS.ALL[1]), _ca(SKILL_DEFS.ALL[2]), _ca(SKILL_DEFS.ALL[3])];
        } catch(e) { catVals = null; }
      }
      const _cat = (g, i) => {
        if (catVals && catVals[i] != null) return Math.round(catVals[i]);
        return Math.round((typeof getPlayerPositionAvg === 'function') ? getPlayerPositionAvg(pl, g) : 10);
      };
      const cats = [
        { k: 'KL', v: _cat('GK', 0),  cls: 'cat-kl' },
        { k: 'DF', v: _cat('DEF', 1), cls: 'cat-df' },
        { k: 'OS', v: _cat('MID', 2), cls: 'cat-os' },
        { k: 'FW', v: _cat('FWD', 3), cls: 'cat-fw' },
      ];
      const cc = (t && t.countryCode) || (typeof authUser !== 'undefined' && authUser && authUser.nationality) || 'TR';
      const flag = _uyrukUlke(cc).flag || '🏳️';
      const mv = (typeof getPlayerMarketValue === 'function' && typeof formatMV === 'function') ? formatMV(getPlayerMarketValue(pl)) : null;
      const my = cfcMdGetMyProfile();
      extra = { kind: 'tpl-player', card: {
        ovr, lvl: pl.level || 0, posShort: altPos, posCls: posInfo.cls, posLabel: SUBPOS_LABEL[altPos],
        name: my.name, avatar: my.avatar || '⚽', flag, cats,
        matches: pl.matchesPlayed || pl.matches_played || 0, goals: pl.goalsTotal || pl.goals_total || 0, assists: pl.assistsTotal || pl.assists_total || 0,
        team: (t && t.teamName) || null, mv,
      }};
    } else {
      // Sadece kaptan/yardımcı kaptan paylaşabilir
      const role = (t && t.role) || '';
      if (role !== 'captain' && role !== 'vice') { _cfcMdRoleBubble(btn); return; }
      if (!t || !t.teamName) { if (typeof tfShowToast === 'function') tfShowToast('❌ Takım verisi bulunamadı', '#ef5350'); return; }
      const cc = t.countryCode, name = t.teamName;
      const flag = (typeof _cftGetCountry === 'function' && _cftGetCountry(cc)) ? (_cftGetCountry(cc).flag || '🏳️') : '🏳️';
      const ovr = (typeof _teamPowerFromPlayers === 'function') ? Math.round(_teamPowerFromPlayers(cc, name, t.rank)) : 10;
      const tierIdx = (typeof t.tierIdx === 'number') ? t.tierIdx : 0;
      const tierLabel = tierIdx === 0 ? 'Süper Lig' : (tierIdx + '. Lig');
      let rank = 0, points = 0;
      try { const rp = await _teamPointsRank(cc, name); if (rp) { rank = rp.rank || 0; points = rp.points || 0; } } catch(e) {}
      const squad = (typeof ROSTER_DATA !== 'undefined' && Array.isArray(ROSTER_DATA)) ? ROSTER_DATA.length : 0;
      // Takım logosu (varsa gerçek logo, yoksa renkli rozet) — çerçevesiz
      const teamObj = (typeof _cftFindTeam === 'function') ? _cftFindTeam(cc, name) : null;
      const logo = (teamObj && typeof teamLogoUrl === 'function') ? teamLogoUrl(teamObj) : null;
      extra = { kind: 'tpl-team', card: {
        ovr, name, flag, cc,
        logo: logo || null,
        bg: (teamObj && teamObj.bg) || '#222',
        tc: (teamObj && teamObj.tc) || '#fff',
        short: (teamObj && teamObj.short) || t.short || _cfcMdInitials(name),
        tierLabel, tierShort: tierIdx === 0 ? 'SL' : (tierIdx + 'L'),
        rank, points: Math.round(points * 100) / 100, squad,
      }};
    }
    const olusan = await _socialAdapter.createPost(content, extra);
    if (olusan && olusan.hata === 'tpl_gunluk') {
      if (typeof tfShowToast === 'function') tfShowToast('Bu paylaşımı 24 saatte 1 kez yapabilirsin.', '#ff9800');
      return;
    }
    if (!olusan) {
      if (typeof tfShowToast === 'function') tfShowToast('❌ Paylaşılamadı', '#ef5350');
      return;
    }
    if (_cfcMdCurrentTab !== 'profile') {
      cfcMdTab('profile', document.querySelector('.cfcmd-tab[data-cfcmd-tab="profile"]'));
    } else { cfcMdRender(); }
    if (typeof tfShowToast === 'function') tfShowToast('📤 Paylaşıldı', 'var(--accent)');
  } catch(e) {
    console.error('[CFC Media] Şablon paylaşım hatası:', e);
    if (typeof tfShowToast === 'function') tfShowToast('❌ Paylaşılamadı', '#ef5350');
  }
}
// Şablon kartı HTML'i (feed'de gösterilir) — Varyant B (kompakt karbon)
function _cfcMdTemplateCardHtml(p) {
  let c = p.card || {};
  // 734 — sağ üst tuş: oyuncu kartı / takım sayfası
  const _v = `data-k="${_cfcMdEscape(p.kind)}" data-a="${_cfcMdEscape(p.authorId)}" data-n="${_cfcMdEscape(p.authorName)}" data-cc="${_cfcMdEscape(c.cc)}" data-t="${_cfcMdEscape(c.name)}"`;
  if (p.kind === 'tpl-player') {
    const cats = (c.cats || []).map(a =>
      `<div class="tplc-ab ${a.cls}"><div class="tplc-ab-v">${a.v}</div><div class="tplc-ab-l">${a.k}</div></div>`).join('');
    const teamLine = c.team
      ? `Takım: <b>${_cfcMdEscape(c.team)}</b>${c.mv ? ' · ' + _cfcMdEscape(c.mv) : ''}`
      : (c.mv ? 'Serbest · ' + _cfcMdEscape(c.mv) : 'Serbest oyuncu');
    return `<div class="tplc tplc-player">
      <div class="tplc-pill tpl-fa"><svg class="tplc-pill-ic" viewBox="0 0 24 24"><use href="#ic-soccer"/></svg>TAKIM ARIYORUM<button type="button" class="tplc-git" ${_v} onclick="event.stopPropagation();cfcMdTplAc(this)"><span>Oyuncu Kartı</span><svg viewBox="0 0 24 24"><path d="M9 6l6 6-6 6"/></svg></button></div>
      <div class="tplc-body">
        <div class="tplc-lcol">
          <div class="tplc-ovr gold">${c.ovr}</div><div class="tplc-ovr-l">OVR</div>
          <div class="tplc-pos pos-${c.posCls}">${c.posShort}</div>
        </div>
        <div class="tplc-rcol">
          <div class="tplc-head">
            <div class="tplc-av">${c.avatar || '⚽'}<span class="tplc-flag">${c.flag}</span></div>
            <div class="tplc-nm">
              <div class="tplc-name">${_cfcMdEscape(c.name)}</div>
              <div class="tplc-meta">${_cfcMdEscape(c.posLabel)} · Seviye <b>${c.lvl}</b></div>
            </div>
          </div>
          <div class="tplc-abrow">${cats}</div>
          <div class="tplc-line"><b>${c.matches}</b> Maç · <b>${c.goals}</b> Gol · <b>${c.assists}</b> Asist</div>
          <div class="tplc-line">${teamLine}</div>
        </div>
      </div>
    </div>`;
  }
  if (p.kind === 'tpl-team') {
    const crest = c.logo
      ? `<div class="tplc-crest tplc-crest-logo"><img src="${c.logo}" alt="" loading="lazy"></div>`
      : `<div class="tplc-crest tplc-crest-badge" style="background:${c.bg};color:${c.tc}">${_cfcMdEscape(c.short)}</div>`;
    return `<div class="tplc tplc-team">
      <div class="tplc-pill tpl-tr"><svg class="tplc-pill-ic" viewBox="0 0 24 24"><use href="#ic-team"/></svg>FUTBOLCU ARIYORUM<button type="button" class="tplc-git" ${_v} onclick="event.stopPropagation();cfcMdTplAc(this)"><span>Takımı Gör</span><svg viewBox="0 0 24 24"><path d="M9 6l6 6-6 6"/></svg></button></div>
      <div class="tplc-body">
        <div class="tplc-lcol">
          <div class="tplc-ovr gold">${c.ovr}</div><div class="tplc-ovr-l">TAKIM OVR</div>
          <div class="tplc-pos pos-tier">${c.tierShort}</div>
        </div>
        <div class="tplc-rcol">
          <div class="tplc-head">
            ${crest}<span class="tplc-flag tplc-flag-team">${c.flag}</span>
            <div class="tplc-nm">
              <div class="tplc-name">${_cfcMdEscape(c.name)}</div>
              <div class="tplc-meta">${_cfcMdEscape(c.tierLabel)} · ${_cfcMdEscape(c.cc)}</div>
            </div>
          </div>
          <div class="tplc-abrow">
            <div class="tplc-ab"><div class="tplc-ab-v gold">${c.rank}.</div><div class="tplc-ab-l">Sıra</div></div>
            <div class="tplc-ab"><div class="tplc-ab-v">${c.points}</div><div class="tplc-ab-l">Takım Puanı</div></div>
            <div class="tplc-ab"><div class="tplc-ab-v">${c.squad}</div><div class="tplc-ab-l">Kadro</div></div>
          </div>
        </div>
      </div>
    </div>`;
  }
  return '';
}
// 734 — Takım Arıyorum → paylaşan oyuncunun kartı · Futbolcu Arıyorum → takım sayfası (ziyaretçi)
async function cfcMdTplAc(b) {
  const d = b.dataset;
  if (d.k === 'tpl-team') { if (d.cc && d.t && typeof viewTeam === 'function') viewTeam(d.cc, d.t); return; }
  const ad = String(d.a || '').replace(/^user:/, '').replace(/^@+/, '').toLowerCase().replace(/[,()%*'"\\]/g, '');
  if (!ad || !window.sb || b.disabled) return;
  b.disabled = true;
  const { data } = await window.sb.from('profiles').select('id').or('username.ilike.' + ad + ',username.ilike.@' + ad).limit(1);
  b.disabled = false;
  const uid = data && data[0] && data[0].id;
  if (!uid) { if (typeof tfShowToast === 'function') tfShowToast('Oyuncu bulunamadı', '#ef5350'); return; }
  openPlayerModal({ userId: uid, user_id: uid, name: d.n || '' }, {});
}
// Ortak uyarı — işlem sunucuda gerçekleşmediyse kullanıcı bilsin
function _cfcMdUyar(mesaj) {
  try { if (typeof tfShowToast === 'function') tfShowToast('❌ ' + mesaj, '#ef5350'); }
  catch(e) {}
}

async function cfcMdToggleLike(postId) {
  const r = await _socialAdapter.toggleLike(postId);
  if (r && r.hata) _cfcMdUyar('Beğeni kaydedilemedi');
  cfcMdRender();
}

async function cfcMdToggleDislike(postId) {
  const r = await _socialAdapter.toggleDislike(postId);
  if (r && r.hata) _cfcMdUyar('İşlem kaydedilemedi');
  cfcMdRender();
}

async function cfcMdToggleRepost(postId) {
  const r = await _socialAdapter.toggleRepost(postId);
  if (r && r.hata) _cfcMdUyar('Yeniden paylaşım şu an kullanılamıyor');
  cfcMdRender();
}

// 🆕 Sil onay akışı — basit modal, native confirm yerine
let _cfcMdPendingDeleteId = null;
function cfcMdAskDelete(postId) {
  _cfcMdPendingDeleteId = postId;
  const ov = document.getElementById('cfcMdDelOverlay');
  if (ov) ov.classList.add('open');
}
function cfcMdCloseDelModal() {
  _cfcMdPendingDeleteId = null;
  const ov = document.getElementById('cfcMdDelOverlay');
  if (ov) ov.classList.remove('open');
}
async function cfcMdConfirmDelete() {
  const id = _cfcMdPendingDeleteId;
  cfcMdCloseDelModal();
  if (!id) return;
  try {
    const res = await _socialAdapter.deletePost(id);
    if (res && res.deleted) {
      if (typeof tfShowToast === 'function') tfShowToast('🗑️ Gönderi silindi', '#ef5350');
      cfcMdRender();
    } else {
      const reason = res && res.reason === 'forbidden' ? 'Bu gönderiyi silemezsin' : 'Gönderi bulunamadı';
      if (typeof tfShowToast === 'function') tfShowToast('❌ ' + reason, '#ef5350');
    }
  } catch(e) {
    console.error('[CFC Media] Sil hatası:', e);
    if (typeof tfShowToast === 'function') tfShowToast('❌ Silinemedi', '#ef5350');
  }
}

// ── Yardımcılar ──
function _cfcMdLikeCount(p) {
  if (!p) return 0;
  if (typeof p.likeCount === 'number') return p.likeCount;
  if (Array.isArray(p.likes)) return p.likes.length;
  return 0;
}
function _cfcMdDislikeCount(p) {
  if (!p) return 0;
  if (typeof p.dislikeCount === 'number') return p.dislikeCount;
  if (Array.isArray(p.dislikes)) return p.dislikes.length;
  return 0;
}
function _cfcMdEscape(s) {
  return String(s || '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
function _cfcMdRelTime(ts) {
  const diff = (Date.now() - ts) / 1000;
  if (diff < 60) return Math.floor(diff) + 'sn';
  if (diff < 3600) return Math.floor(diff/60) + 'dk';
  if (diff < 86400) return Math.floor(diff/3600) + 'sa';
  if (diff < 604800) return Math.floor(diff/86400) + 'g';
  return new Date(ts).toLocaleDateString('tr');
}

// 🆕 Takipçi sayısı (yerel/single-user modunda dürüst hesaplama)
// - Kendi takipçim → 0 (yerel oyun, kimse beni takip edemez)
// - Başkasının takipçisi → ben onu takip ediyorsam 1, değilsem 0
// Backend gelince burası adapter'a taşınıp gerçek sayı döner.
// Takipçi sayısı — kendi profilim için cache, ziyaretçi profilinde async server sayımı
// (cfcMdRenderProfile içinde async olarak doldurulur)
function cfcMdGetFollowerCount(userId) {
  if (!userId) return 0;
  const my = cfcMdGetMyProfile();
  if (userId === my.id) {
    return _cfcMdFollowersCache.length;
  }
  // Başkasının takipçi sayısı için cache (async olarak doldurulur)
  return _cfcMdOtherFollowerCounts[userId] || 0;
}

// Ziyaret edilen kullanıcı için takipçi+takip eden sayılarını çek
let _cfcMdOtherFollowerCounts = {};
let _cfcMdOtherFollowingCounts = {};
async function cfcMdLoadUserFollowStats(userId) {
  if (!userId || !window.sb) return { followers: 0, following: 0 };
  try {
    const [ferRes, fingRes] = await Promise.all([
      window.sb.from('social_follows').select('follower_id', { count: 'exact', head: true }).eq('following_id', userId),
      window.sb.from('social_follows').select('following_id', { count: 'exact', head: true }).eq('follower_id', userId),
    ]);
    const followers = ferRes.count || 0;
    const following = fingRes.count || 0;
    _cfcMdOtherFollowerCounts[userId] = followers;
    _cfcMdOtherFollowingCounts[userId] = following;
    return { followers, following };
  } catch(e) { return { followers: 0, following: 0 }; }
}

// 🆕 Toplu sayım — bir kullanıcının postlarındaki toplam like + dislike (server'dan)
async function cfcMdGetUserStats(userId) {
  if (!userId || !window.sb) return { postCount: 0, totalLikes: 0, totalDislikes: 0 };
  try {
    const { data: posts } = await window.sb.from('social_posts')
      .select('id').eq('author_id', userId);
    const postCount = (posts || []).length;
    if (postCount === 0) return { postCount: 0, totalLikes: 0, totalDislikes: 0 };
    const postIds = posts.map(p => p.id);
    const { data: reacts } = await window.sb.from('social_likes')
      .select('reaction').in('post_id', postIds);
    let totalLikes = 0, totalDislikes = 0;
    (reacts || []).forEach(r => {
      if (r.reaction === 'like') totalLikes++;
      else if (r.reaction === 'dislike') totalDislikes++;
    });
    return { postCount, totalLikes, totalDislikes };
  } catch(e) {
    console.warn('[social] userStats:', e);
    return { postCount: 0, totalLikes: 0, totalDislikes: 0 };
  }
}

// ─────────────────────────────────────────────────────────────
// 🆕 ARAMA / ZİYARETÇİ PROFİL — Instagram tarzı kullanıcı arama
// ─────────────────────────────────────────────────────────────

// Kayıtlı kullanıcıları getir (Supabase profiles tablosundan)
// Async olduğu için arama açılışında awaitlenir, sonuçlar _cfcMdUsersCache'e atılır
let _cfcMdUsersCache = null;
let _cfcMdUsersCacheTs = 0;

// 🆕 ÖLÇEK: eskiden TÜM profiles + TÜM gerçek oyuncular çekiliyordu (20 bin
//   kullanıcıda arama her açıldığında 40 bin satır). Artık arama sunucuda yapılıyor:
//   en fazla 50 sonuç, oyuncu satırları da yalnızca o 50 kullanıcı için.
let _cfcMdUsersCacheQ = null;
function _cfcMdAramaTemizle(q) {
  return String(q || '').trim().slice(0, 40).replace(/[,()%*'"\\]/g, ' ').trim();
}

async function cfcMdLoadKnownUsers(query) {
  if (!window.sb) { _cfcMdUsersCache = []; return []; }
  const q = _cfcMdAramaTemizle(query);
  // 30 saniye cache (aynı arama tekrar tekrar istek atmasın)
  if (_cfcMdUsersCache && _cfcMdUsersCacheQ === q && (Date.now() - _cfcMdUsersCacheTs) < 30000) {
    return _cfcMdUsersCache;
  }
  try {
    let _pq = window.sb.from('profiles').select('id, username, name, nationality');
    if (q) _pq = _pq.or('username.ilike.%' + q + '%,name.ilike.%' + q + '%');
    const profRes = await _pq.order('username').limit(50);
    const _ids = (profRes.data || []).map(p => p.id).filter(Boolean);
    const playersRes = _ids.length
      ? await window.sb.from('players').select('user_id, user_team_data, avatar_id').in('user_id', _ids)
      : { data: [] };
    if (profRes.error) { console.warn('[social] users:', profRes.error); _cfcMdUsersCache = []; return []; }
    // user_id → user_team_data
    const teamByUid = {};
    const avByUid = {};
    for (const row of (playersRes.data || [])) {
      if (row.user_id && row.user_team_data) teamByUid[row.user_id] = row.user_team_data;
      if (row.user_id && row.avatar_id) avByUid[row.user_id] = row.avatar_id;
    }
    const myId = cfcMdGetMyId();
    const users = (profRes.data || []).map(p => {
      const handle = '@' + (p.username || '').replace(/^@+/, '').toLowerCase();
      const id = 'user:' + (p.username || '').replace(/^@+/, '').toLowerCase();
      const avId = avByUid[p.id] || null;
      let avHTML = '⚽';
      if (avId && typeof getAvatarEmoji === 'function') {
        avHTML = getAvatarEmoji(avId, null);
      }
      const t = teamByUid[p.id];
      return {
        id,
        name: p.name || p.username || 'Kullanıcı',
        handle,
        avatar: avHTML,
        avatarId: avId,
        team: t && t.teamName ? t.teamName : null,
        teamCc: t && t.countryCode ? t.countryCode : null,
        country: p.nationality || (t && t.countryCode) || null,
        isMe: id === myId,
      };
    });
    _cfcMdUsersCache = users;
    _cfcMdUsersCacheTs = Date.now();
    _cfcMdUsersCacheQ = q;
    return users;
  } catch(e) { console.warn('[social] users hata:', e); _cfcMdUsersCache = []; return []; }
}

// 🆕 Arama kutusu: 300 ms bekleyip sunucuda arar, sonra listeyi çizer.
let _cfcMdSearchTimer = null;
function cfcMdSearchInput(v) {
  const q = v;
  cfcMdRenderSearchResults(q);              // elde olan sonuçlarla anında süz
  if (_cfcMdSearchTimer) clearTimeout(_cfcMdSearchTimer);
  _cfcMdSearchTimer = setTimeout(async () => {
    try { await cfcMdLoadKnownUsers(q); } catch(e) {}
    await _cfcMdRozetYukle(cfcMdGetKnownUsers().map(u => u.id));
    cfcMdRenderSearchResults(q);
  }, 300);
}

// 🆕 Arama sonucu dışında, KİMLİĞİ bilinen kullanıcılar (takipçi listesi, ziyaret
//   edilen profil) ayrı bir cache'te tutulur; arama sonucu değişince kaybolmasınlar.
let _cfcMdUsersExtra = [];

function cfcMdGetKnownUsers() {
  // Sync API — arama cache'i + kimlikle çözülmüş kullanıcılar
  const a = _cfcMdUsersCache || [];
  if (!_cfcMdUsersExtra.length) return a;
  const gorulen = new Set(a.map(u => u.id));
  return a.concat(_cfcMdUsersExtra.filter(u => !gorulen.has(u.id)));
}

// 🆕 Belirli kullanıcıları (user:<kullanıcıadı>) sunucudan çöz — takipçi/takip listesi için.
async function cfcMdLoadUsersByIds(ids) {
  if (!window.sb) return;
  const adlar = [...new Set((ids || [])
    .map(x => String(x || '').replace(/^user:/, '').replace(/^@+/, '').toLowerCase())
    .filter(Boolean)
    .map(x => x.replace(/[,()%*'"\\]/g, '')))].slice(0, 200);
  const bilinen = new Set(cfcMdGetKnownUsers().map(u => u.id));
  const eksik = adlar.filter(a2 => !bilinen.has('user:' + a2));
  if (!eksik.length) return;
  try {
    const profRes = await window.sb.from('profiles')
      .select('id, username, name, nationality')
      .or(eksik.map(a2 => 'username.ilike.' + a2).join(','))
      .limit(200);
    const _ids = (profRes.data || []).map(p => p.id).filter(Boolean);
    const playersRes = _ids.length
      ? await window.sb.from('players').select('user_id, user_team_data, avatar_id').in('user_id', _ids)
      : { data: [] };
    const teamByUid = {}, avByUid = {};
    for (const row of (playersRes.data || [])) {
      if (row.user_id && row.user_team_data) teamByUid[row.user_id] = row.user_team_data;
      if (row.user_id && row.avatar_id) avByUid[row.user_id] = row.avatar_id;
    }
    const myId = cfcMdGetMyId();
    for (const p of (profRes.data || [])) {
      const uname = (p.username || '').replace(/^@+/, '').toLowerCase();
      const id = 'user:' + uname;
      if (_cfcMdUsersExtra.some(u => u.id === id)) continue;
      const avId = avByUid[p.id] || null;
      const t = teamByUid[p.id];
      _cfcMdUsersExtra.push({
        id,
        name: p.name || p.username || 'Kullanıcı',
        handle: '@' + uname,
        avatar: (avId && typeof getAvatarEmoji === 'function') ? getAvatarEmoji(avId, null) : '⚽',
        avatarId: avId,
        team: t && t.teamName ? t.teamName : null,
        teamCc: t && t.countryCode ? t.countryCode : null,
        country: p.nationality || (t && t.countryCode) || null,
        isMe: id === myId,
      });
    }
    if (_cfcMdUsersExtra.length > 400) _cfcMdUsersExtra = _cfcMdUsersExtra.slice(-400);
  } catch(e) { console.warn('[social] kullanıcı çözme hata:', e); }
}

async function cfcMdOpenSearch() {
  const ov = document.getElementById('cfcMdSearchOverlay');
  const inp = document.getElementById('cfcMdSearchInput');
  if (!ov) return;
  ov.classList.add('open');
  if (inp) { inp.value = ''; inp.blur(); }
  // 683 — klavye kendiliğinden açılmaz: arama çubuğu ve kişiler görünür, kutuya dokununca klavye açılır
  if (_cfcMdUsersCache && _cfcMdUsersCache.length) cfcMdRenderSearchResults('');
  // 🆕 Önce server'dan kayıtlı kullanıcıları yükle, sonra render
  try { await cfcMdLoadKnownUsers(''); } catch(e) {}
  await _cfcMdRozetYukle(cfcMdGetKnownUsers().map(u => u.id));
  if (!inp || !inp.value) cfcMdRenderSearchResults('');
}

function cfcMdCloseSearch() {
  const ov = document.getElementById('cfcMdSearchOverlay');
  if (!ov) return;
  ov.classList.remove('open');
  // Klavyeyi kapat (mobil)
  const inp = document.getElementById('cfcMdSearchInput');
  if (inp) inp.blur();
}

function cfcMdRenderSearchResults(query) {
  const container = document.getElementById('cfcMdSearchResults');
  if (!container) return;
  const users = cfcMdGetKnownUsers();
  const q = String(query || '').trim().toLowerCase();
  // Self önce, sonra alfabetik
  const filtered = users
    .filter(u => {
      if (!q) return true;
      const hay = (u.name + ' ' + u.handle).toLowerCase();
      return hay.indexOf(q) !== -1;
    })
    .sort((a, b) => {
      if (a.isMe && !b.isMe) return -1;
      if (!a.isMe && b.isMe) return 1;
      return a.name.localeCompare(b.name, 'tr');
    });

  if (!filtered.length) {
    container.innerHTML = `<div class="cfcmd-search-empty">
      <div class="cfcmd-search-empty-icon">${_CFCMD_IK.ara}</div>
      ${q ? 'Eşleşen kullanıcı bulunamadı.' : 'Henüz kayıtlı kullanıcı yok.'}
    </div>`;
    return;
  }

  const label = q ? 'SONUÇLAR' : 'KAYITLI KULLANICILAR';
  const items = filtered.map(u => {
    const flag = (u.country && _uyrukUlke(u.country).flag) || '';
    const countryName = (u.country && _uyrukUlke(u.country).name) || u.country || '';
    const parts = [];
    if (flag || countryName) parts.push(`${flag} ${_cfcMdEscape(countryName)}`.trim());
    if (u.team) parts.push(_cfcMdEscape(u.team));
    const subText = parts.join(' · ');
    return `
    <div class="cfcmd-search-item" onclick="cfcMdViewProfile('${u.id}')">
      <div class="cfcmd-search-avatar">${u.avatar || '⚽'}</div>
      <div class="cfcmd-search-meta">
        <div class="cfcmd-search-name">
          ${_cfcMdEscape(u.name)}${_cfcMdTik(u.id)}
          ${u.isMe ? '<span class="me-tag">Sen</span>' : ''}
        </div>
        ${subText ? `<div class="cfcmd-search-handle">${subText}</div>` : ''}
      </div>
      <span class="cfcmd-search-chev">${_CFCMD_IK.sag}</span>
    </div>`;
  }).join('');

  container.innerHTML = `
    <div class="cfcmd-search-section-lbl">${label} · ${filtered.length}</div>
    ${items}
  `;
}

// 635 — oyuncu kartındaki @kullanıcı adından gelince açılacak profil
let _cfcMdAcilisProfil = null;

// Profile aç — kendisi ise normal, başkası ise ziyaretçi modu
function cfcMdViewProfile(userId) {
  const my = cfcMdGetMyProfile();
  // 🆕 Açık olabilecek modalları kapat
  cfcMdCloseSearch();
  if (typeof cfcMdCloseFollows === 'function') cfcMdCloseFollows();
  // Kendisi mi?
  if (!userId || userId === my.id) {
    _cfcMdViewingUserId = null;
  } else {
    _cfcMdViewingUserId = userId;
  }
  // 🆕 Profile sekmesi UI'sını manuel aç (cfcMdTab _cfcMdViewingUserId'i sıfırlar!)
  _cfcMdCurrentTab = 'profile';
  document.querySelectorAll('.cfcmd-tab').forEach(t => {
    t.classList.toggle('active', t.getAttribute('data-cfcmd-tab') === 'profile');
  });
  const elGlobal = document.getElementById('cfcMdGlobal');
  const elNational = document.getElementById('cfcMdNational');
  const elFollowing = document.getElementById('cfcMdFollowing');
  const elProfile = document.getElementById('cfcMdProfile');
  if (elGlobal) elGlobal.style.display = 'none';
  if (elNational) elNational.style.display = 'none';
  if (elFollowing) elFollowing.style.display = 'none';
  if (elProfile) elProfile.style.display = 'block';
  cfcMdRender();
}

// 695 — gönderideki kişiye (avatar, ad, kullanıcı adı) dokununca onun CSC Media profili açılır
function cfcMdYazarAc(el) {
  cfcMdViewProfile(el.dataset.yazar);
  window.scrollTo(0, 0);
}

// Kendi profilime dön (geri butonu)
function cfcMdBackToMyProfile() {
  _cfcMdViewingUserId = null;
  cfcMdRenderProfile();
}

// Ziyaretçi profilindeki takip butonu
async function cfcMdToggleFollowUser(userId) {
  if (!userId) return;
  try {
    const r = await _socialAdapter.toggleFollow(userId);
    if (r && r.hata) {
      if (typeof tfShowToast === 'function')
        tfShowToast('❌ Takip işlemi kaydedilemedi', '#ef5350');
      return;
    }
    // 🆕 Cache'i yenile
    await cfcMdLoadFollows();
    // Profile'i yenile (takip butonu durumu güncellensin)
    cfcMdRenderProfile();
    // Follows modali açıksa onu da yenile
    const fov = document.getElementById('cfcMdFollowsOverlay');
    if (fov && fov.classList.contains('open')) {
      cfcMdRenderFollowsList(document.getElementById('cfcMdFollowsInput')?.value || '');
    }
  } catch(e) {
    console.error('[CFC Media] toggleFollow hatası:', e);
  }
}

// ─────────────────────────────────────────────────────────────
// 🆕 TAKİP / TAKİPÇİ MODALI — sekmeli + filtreli
// ─────────────────────────────────────────────────────────────

let _cfcMdFollowsActiveTab = 'following'; // 'following' | 'followers'

// ID'den user objesi resolve — known users'tan ara, bulamazsan fallback
function _cfcMdResolveUserById(id) {
  if (!id) return null;
  const known = cfcMdGetKnownUsers();
  const found = known.find(u => u.id === id);
  if (found) return found;
  // Fallback — id'den username türet
  const uname = String(id).replace(/^user:/, '');
  return {
    id,
    name: uname || 'Kullanıcı',
    handle: '@' + uname,
    avatar: '⚽',
    avatarId: null,
    team: null,
    country: null,
    isMe: false,
  };
}

async function cfcMdOpenFollows(initialTab) {
  // Sadece kendi profilim üzerinden açılır (ziyaretçi profilinde stat'lar clickable değil)
  _cfcMdFollowsActiveTab = (initialTab === 'followers') ? 'followers' : 'following';
  const inp = document.getElementById('cfcMdFollowsInput');
  if (inp) inp.value = '';
  // Sekme UI güncelle
  document.querySelectorAll('.cfcmd-follows-tab').forEach(t => {
    t.classList.toggle('active', t.getAttribute('data-follows-tab') === _cfcMdFollowsActiveTab);
  });
  // 🆕 Server'dan follows + users yükle
  try { await cfcMdLoadFollows(); } catch(e) {}
  try { await cfcMdLoadUsersByIds([].concat(cfcMdGetFollowing(), cfcMdGetFollowersList())); } catch(e) {}
  await _cfcMdRozetYukle([].concat(cfcMdGetFollowing(), cfcMdGetFollowersList()));
  // Sayaçları güncelle
  const followingIds = cfcMdGetFollowing();
  const followersIds = cfcMdGetFollowersList();
  const cf = document.getElementById('cfcMdFollowsCountFollowing');
  const cF = document.getElementById('cfcMdFollowsCountFollowers');
  if (cf) cf.textContent = followingIds.length;
  if (cF) cF.textContent = followersIds.length;
  // Liste render
  cfcMdRenderFollowsList('');
  // Modal aç
  const ov = document.getElementById('cfcMdFollowsOverlay');
  if (ov) ov.classList.add('open');
  // Input fokuslanmasın — kullanıcı isterse tıklayıp arar; otomatik klavye açma can sıkıcı olabilir
  // Eğer açılsın istenirse setTimeout ile inp.focus eklenir
}

function cfcMdCloseFollows() {
  const ov = document.getElementById('cfcMdFollowsOverlay');
  if (ov) ov.classList.remove('open');
  const inp = document.getElementById('cfcMdFollowsInput');
  if (inp) inp.blur();
}

function cfcMdFollowsTab(tab) {
  _cfcMdFollowsActiveTab = (tab === 'followers') ? 'followers' : 'following';
  document.querySelectorAll('.cfcmd-follows-tab').forEach(t => {
    t.classList.toggle('active', t.getAttribute('data-follows-tab') === _cfcMdFollowsActiveTab);
  });
  // Filtreyi temizle (sekme değiştiğinde temiz başla)
  const inp = document.getElementById('cfcMdFollowsInput');
  if (inp) inp.value = '';
  cfcMdRenderFollowsList('');
}

function cfcMdRenderFollowsList(query) {
  const container = document.getElementById('cfcMdFollowsList');
  if (!container) return;

  // ID listesi → user objelerine resolve
  let users;
  let emptyMsg;
  let emptyIcon;
  if (_cfcMdFollowsActiveTab === 'following') {
    const ids = cfcMdGetFollowing();
    users = ids.map(_cfcMdResolveUserById).filter(Boolean);
    emptyIcon = _CFCMD_IK.kisiler;
    emptyMsg = 'Henüz kimseyi takip etmiyorsun.';
  } else {
    const ids = cfcMdGetFollowersList();
    users = ids.map(_cfcMdResolveUserById).filter(Boolean);
    emptyIcon = _CFCMD_IK.kisiler;
    emptyMsg = 'Henüz takipçin yok.<br><span style="font-size:11px;opacity:.7">Backend bağlandığında burada gözükecek.</span>';
  }

  // Filtre uygula
  const q = String(query || '').trim().toLowerCase();
  const filtered = q
    ? users.filter(u => (u.name + ' ' + u.handle).toLowerCase().indexOf(q) !== -1)
    : users;

  // Alfabetik sırala
  filtered.sort((a, b) => a.name.localeCompare(b.name, 'tr'));

  // Boş durumlar
  if (!filtered.length) {
    if (!users.length) {
      container.innerHTML = `<div class="cfcmd-search-empty">
        <div class="cfcmd-search-empty-icon">${emptyIcon}</div>
        ${emptyMsg}
      </div>`;
    } else {
      container.innerHTML = `<div class="cfcmd-search-empty">
        <div class="cfcmd-search-empty-icon">${_CFCMD_IK.ara}</div>
        Eşleşen kullanıcı yok.
      </div>`;
    }
    return;
  }

  // Items — search-item ile aynı stiller
  const followingNow = cfcMdGetFollowing();
  const items = filtered.map(u => {
    const isFollowing = followingNow.includes(u.id);
    // "Following" sekmesinde küçük unfollow ipucu olarak takip durumu rozetli olabilir
    // Ama tıklamayla profile gitmek ana akış — sadece chevron göster
    const flag = (u.country && _uyrukUlke(u.country).flag) || '';
    const countryName = (u.country && _uyrukUlke(u.country).name) || u.country || '';
    const parts = [];
    if (flag || countryName) parts.push(`${flag} ${_cfcMdEscape(countryName)}`.trim());
    if (u.team) parts.push(_cfcMdEscape(u.team));
    const subText = parts.join(' · ');
    return `<div class="cfcmd-search-item" onclick="cfcMdViewProfile('${u.id}')">
      <div class="cfcmd-search-avatar">${u.avatar || '⚽'}</div>
      <div class="cfcmd-search-meta">
        <div class="cfcmd-search-name">${_cfcMdEscape(u.name)}${_cfcMdTik(u.id)}</div>
        ${subText ? `<div class="cfcmd-search-handle">${subText}</div>` : ''}
      </div>
      <span class="cfcmd-search-chev">${_CFCMD_IK.sag}</span>
    </div>`;
  }).join('');

  const label = _cfcMdFollowsActiveTab === 'following'
    ? `TAKİP ETTİKLERİM · ${filtered.length}`
    : `TAKİPÇİLERİM · ${filtered.length}`;
  container.innerHTML = `
    <div class="cfcmd-search-section-lbl">${label}</div>
    ${items}
  `;
}

// Sayfa açılınca render et
if (typeof showPage === 'function') {
  // showPage('cfc-media') çağrılınca otomatik render — showPage hook'lanmıyor,
  // bunun yerine page-cfc-media DOM görünür olduğunda render et
  const _cfcMdObserver = new MutationObserver(() => {
    const p = document.getElementById('page-cfc-media');
    if (!p) return;
    if (p.classList.contains('active')) {
      // 🆕 Her CFC Media'ya girişte "Profilim" sekmesinden başla
      _cfcMdViewingUserId = null; // ziyaretçi modu da sıfırlansın
      // 🆕 Server'dan follows + users cache'leri yükle
      cfcMdLoadFollows()
        .then(() => cfcMdLoadUsersByIds([].concat(cfcMdGetFollowing(), cfcMdGetFollowersList())))
        .catch(()=>{});
      if (_cfcMdAcilisProfil) { const h = _cfcMdAcilisProfil; _cfcMdAcilisProfil = null; cfcMdViewProfile(h); return; }
      const profileTab = document.querySelector('.cfcmd-tab[data-cfcmd-tab="profile"]');
      if (profileTab) {
        cfcMdTab('profile', profileTab);
      } else {
        _cfcMdCurrentTab = 'profile';
        cfcMdRender();
      }
    } else {
      // 🆕 Sayfa kapandığında: ziyaretçi modu sıfırla + açık modalları kapat
      _cfcMdViewingUserId = null;
      try {
        document.getElementById('cfcMdSearchOverlay')?.classList.remove('open');
        document.getElementById('cfcMdDelOverlay')?.classList.remove('open');
        document.getElementById('cfcMdFollowsOverlay')?.classList.remove('open');
      } catch(e) {}
    }
  });
  document.addEventListener('DOMContentLoaded', () => {
    const p = document.getElementById('page-cfc-media');
    if (p) _cfcMdObserver.observe(p, { attributes: true, attributeFilter: ['class'] });
  });
}

// ═══════════ BOOT ═══════════
document.addEventListener('DOMContentLoaded', () => {
  updateDevBadges();
  inboxUpdateBadge();
  // 🆕 Tüm federasyonları otomatik tick et (32 ülke için seçimler hep akar)
  try { if (typeof fedDailyTickAll === 'function') fedDailyTickAll(); } catch(e) {}
});
// 🆕 Her 60 saniyede bir tick — gün geçtiğinde seçim otomatik açılır/kapanır
setInterval(() => {
  try { if (typeof fedDailyTickAll === 'function') fedDailyTickAll(); } catch(e) {}
}, 60000);
setTimeout(async ()=>{
  // 🔧 ÖNCE auth ekranını hazırla (görünür yap), SONRA splash'ı fade'le
  // Aksi halde splash gizlendiğinde 500ms boyunca ana menü görünür
  try { await bootstrapWorld(); } catch(e) { console.warn('bootstrapWorld hata:', e); }
  // 🆕 Geri kalan 6 yükleme paralel — birbirinden bağımsız tablolar
  await Promise.all([
    // 🆕 SIRA ÖNEMLİ: sezon bilgisi (world_state) ve takım, maç verisinden ÖNCE gelmeli.
    //   Aksi halde _msLoadCore yanlış sezonu çekiyor → turnuva grupları/puanları sıfır görünüyordu.
    _worldStateLoadFromServer().catch(e => console.warn('worldState load hata:', e)),
    _tournamentStateLoadFromServer().catch(e => console.warn('tournamentState load hata:', e)),
    _frmLoadFromServer().catch(e => console.warn('friendly load hata:', e)),
    userTeamLoadFromServer().catch(e => console.warn('userTeamLoadFromServer hata:', e)),
  ]);
  // Sezon + takım hazır → maç verisi çekirdeği (doğru sezonla)
  await _loadAllMatchStateFromServer().catch(e => console.warn('match_state load hata:', e));

  // 🆕 Yenileme sonrası kadroyu yükle (login akışıyla aynı) — yoksa takım sayfası realtime event gelene kadar boş kalır
  if (typeof userHasTeam === 'function' && userHasTeam() && _userTeam && _userTeam.countryCode) {
    try { rosterBuildTeam(_userTeam.countryCode); } catch(e){}
  }
  
  // 🆕 PRESENCE — players.last_seen güncellemesi
  //   ÖLÇEK: eskiden 60 sn'de bir, sekme gizliyken bile yazıyordu. 20 bin oyuncuda
  //   bu saniyede ~330 yazma demek; ayrıca her yazma realtime yayınına düşüyor.
  //   Çevrimiçi eşiği 5 dakika olduğu için 3 dakikada bir yazmak aynı sonucu verir.
  //   Sekme arka plandayken hiç yazılmaz; öne gelince hemen bir kez yazılır.
  try {
    // 🆕 561 — tek presence yazıcısı: girişi açılıştan SONRA yapan kullanıcı için de
    //   çalışsın diye zamanlayıcı her durumda kurulur, kullanıcı çağrı anında kontrol edilir.
    if (window.sb) {
      const _updateLastSeen = async (zorla) => {
        if (!zorla && document.hidden) return;
        // Kullanıcı kimliği: sözcüksel authUser (giriş akışı) veya window.authUser
        const _uid = (typeof authUser !== 'undefined' && authUser && authUser.id) || (window.authUser && window.authUser.id);
        if (!_uid) return;
        try {
          // 681 — aynı yazımdan takım/rol de döner: kaptanlık devri, 21 gün kuralı, takımdan atılma, transfer gibi
          //   başkasının yaptığı değişiklik açık oyunda fark edilir ve kendi verimiz tazelenir (ek sorgu yok)
          const { data: _sr } = await window.sb.from('players')
            .update({ last_seen: new Date().toISOString() })
            .eq('user_id', _uid).select('team_name,country_code,role');
          const r = _sr && _sr[0];
          if (r && window._utYuklendi) {
            const sunucu = r.team_name ? r.country_code + '|' + r.team_name + '|' + (r.role || 'member') : '';
            const yerel = _userTeam ? _userTeam.countryCode + '|' + _userTeam.teamName + '|' + (_userTeam.role || 'member') : '';
            if (sunucu !== yerel) _yonetimIste();
          }
        } catch(e) {}
      };
      window._presenceYaz = _updateLastSeen;
      _updateLastSeen(true);
      if (!window._presenceTimer) {
        window._presenceTimer = setInterval(_updateLastSeen, 180 * 1000);
        document.addEventListener('visibilitychange', () => {
          if (!document.hidden) _updateLastSeen(true);
        });
      }
    }
  } catch(e) { console.warn('[presence] hata:', e); }
  
  // 🆕 SUPABASE REALTIME — anlık veri güncellemeleri
  // Sayfa yenileme gereği kalkıyor: maç biter, takım katılım, vs anlık güncellenir
  try {
    if (window.sb && !window._rtSubscribed) {
      window._rtSubscribed = true;
      
      // Debounce yardımcı (kısa sürede çok event geldiğinde tek tek değil tek seferde tepki ver)
      const _rtDebounce = (fn, ms) => {
        let t = null;
        return () => { if (t) clearTimeout(t); t = setTimeout(fn, ms); };
      };
      
      // match_results realtime subscription SİLİNDİ — match_state subscription
      //   (aşağıda 'rt-match-state') tüm güncellemeleri kapsıyor.


      // 🆕 Realtime olayı geldiğinde TÜM tabloyu yeniden çekmek yerine gelen satır
      //   doğrudan cache'e işlenir (sorgu YOK). Maliyet ve CPU açısından kritik fark.
      let _rtPending = [];
      const _refreshMatchState = _rtDebounce(async () => {
        try {
          if (_rtPending.length) {
            const batch = _rtPending; _rtPending = [];
            let applied = 0;
            for (const p of batch) { if (_msApplyRealtimeRow(p)) applied++; }
            if (applied) { try { _msRefreshActivePage(); } catch(e) {} }
          }
          // Ana sayfa maç önizleme paneli realtime'da YENİDEN ÇİZİLMEZ (flicker sebebi).
          //   Panel sayfa geçişinde (showPage → page-home) tazelenir; geri sayım kendi 1sn timer'ıyla akar.
          // Açık match-screen varsa güncelle
          const ms = document.getElementById('match-screen');
          if (ms && ms.classList.contains('open') && typeof _resLiveUpdate === 'function') {
            _resLiveUpdate();
          }
          // 🆕 İzleyici sayısı senkronu — başka kullanıcı bağlanınca anında güncel
          try {
            const mk = (typeof MS !== 'undefined' && MS && MS.match_key) ? MS.match_key
                     : (window._viewerBeatMatchKey || null);
            if (mk && typeof _liveMatchCache === 'object' && _liveMatchCache && _liveMatchCache[mk]) {
              const vc = _liveMatchCache[mk].viewer_count;
              if (typeof vc === 'number') {
                const el = document.getElementById('msViewerCount');
                if (el) el.textContent = vc;
              }
            }
          } catch(e) {}
        } catch(e) { console.warn('[realtime] match_state refresh hata:', e); }
      }, 500);
      
      // 🆕 ÖLÇEK: match_state tablosunun TAMAMINA abone olmak, dünyadaki her maç
      //   güncellemesini her istemciye gönderiyordu (20k oyuncuda saniyede on binlerce
      //   mesaj). Artık yalnızca AÇIK OLAN maç ekranının maçı dinleniyor; listelerin
      //   canlı skoru zaten _lmTick (7 sn) ve _resUpdateLiveCells ile geliyor.
      window._rtMatchChannel = null;
      window._rtMatchKey = null;
      window.rtWatchMatch = function (mk) {
        // 🆕 561 — ABONELİK KALDIRILDI: maç ekranı zaten 7 sn'lik okuma ile besleniyor,
        //   bu kanal her tikte yalnız arkadaki sayfayı yeniden çizdirip ek sorgu attırıyordu.
        //   (match_state Realtime yayınından da çıkarıldı → DB her tikte satırı çözmüyor.)
        try {
          if (window._rtMatchChannel) { try { window.sb.removeChannel(window._rtMatchChannel); } catch(e) {} }
          window._rtMatchChannel = null;
          window._rtMatchKey = null;
        } catch(e) {}
        return;
        try {
          if (window._rtMatchKey === mk) return;
          if (window._rtMatchChannel) { try { window.sb.removeChannel(window._rtMatchChannel); } catch(e) {} }
          window._rtMatchChannel = null;
          window._rtMatchKey = null;
          if (!mk || !window.sb) return;
          window._rtMatchKey = mk;
          window._rtMatchChannel = window.sb.channel('rt-ms-' + mk)
            .on('postgres_changes', {
              event: '*', schema: 'public', table: 'match_state',
              filter: 'match_key=eq.' + mk
            }, (payload) => {
              try { _rtPending.push(payload); } catch(e) {}
              _refreshMatchState();
            })
            .subscribe();
        } catch(e) { console.warn('[realtime] maç aboneliği hata:', e); }
      };
      
      // 3) players — takım kadrosu (yeni katılım, ayrılma, online durumu)
      const _refreshPlayers = _rtDebounce(async () => {
        try {
          // Kullanıcının takımı varsa kadroyu tazele
          if (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.countryCode && _userTeam.teamName) {
            if (typeof _rosterRefreshFromServer === 'function') {
              await _rosterRefreshFromServer(_userTeam.countryCode);
            }
          }
        } catch(e) { console.warn('[realtime] players refresh hata:', e); }
      }, 1000);
      
      // 🆕 561 — oyuncu satırı imzası (last_seen hariç, yalnız basit alanlar). İmza aynıysa
      //   değişen tek şey çevrimiçi damgasıdır → kadro yeniden çekilmez, yerelde işlenir.
      const _rtOyuncuImza = {};
      const _rtSadeceDamga = (payload) => {
        if (!payload || payload.eventType !== 'UPDATE' || !payload.new || payload.new.id == null) return false;
        const n = payload.new, parca = [];
        Object.keys(n).sort().forEach(k => {
          if (k === 'last_seen' || k === 'updated_at') return;
          const v = n[k];
          if (v !== null && typeof v === 'object') return;   // jsonb alanlar (TOAST'ta gelmeyebilir)
          parca.push(k + '=' + String(v));
        });
        const imza = parca.join('|'), onceki = _rtOyuncuImza[n.id];
        _rtOyuncuImza[n.id] = imza;
        if (onceki === undefined || onceki !== imza) return false;
        try {
          const r = (typeof ROSTER_DATA !== 'undefined' && Array.isArray(ROSTER_DATA)) ? ROSTER_DATA.find(x => x && x.id === n.id) : null;
          if (r && n.last_seen) {
            r.lastSeen = n.last_seen;
            const ms = new Date(n.last_seen).getTime();
            const esik = (typeof ONLINE_THRESHOLD_MS !== 'undefined') ? ONLINE_THRESHOLD_MS : 5 * 60 * 1000;
            r.isOnline = !!ms && (Date.now() - ms < esik);
          }
        } catch(e) {}
        return true;
      };

      // 🆕 ÖLÇEK: filtresiz abonelik, dünyadaki HER oyuncu satırı değişiminde
      //   (çevrimiçi damgası, maç istatistikleri) tüm istemcileri uyandırıyordu.
      //   Artık yalnızca kendi takımımın satırları dinleniyor.
      window._rtTeamChannels = { players: null, teamData: null, team: null };
      window.rtBindTeamChannels = function () {
        try {
          if (!window.sb) return;
          const tn = (typeof _userTeam !== 'undefined' && _userTeam) ? _userTeam.teamName : null;
          if (window._rtTeamChannels.team === tn) return;
          for (const k of ['players', 'teamData']) {
            if (window._rtTeamChannels[k]) { try { window.sb.removeChannel(window._rtTeamChannels[k]); } catch(e) {} }
            window._rtTeamChannels[k] = null;
          }
          window._rtTeamChannels.team = tn;
          // 690 — players / team_data Realtime yayınında değil, bu abonelikler hiç olay almıyordu.
          //   Kadro 12 sn'lik eşitleme ve sohbetteki [[SYS]] mesajıyla tazeleniyor.
          return;
          if (!tn) return;
          window._rtTeamChannels.players = window.sb.channel('rt-players-' + tn)
            .on('postgres_changes', {
              event: '*', schema: 'public', table: 'players',
              filter: 'team_name=eq.' + tn
            }, (payload) => {
              // 🆕 561 — satırda yalnız last_seen değiştiyse (çevrimiçi damgası) ağır kadro
              //   sorgusunu (~115 KB) atma; çevrimiçi bilgisini yerelde güncelle.
              try { if (_rtSadeceDamga(payload)) return; } catch(e) {}
              _refreshPlayers();
            })
            .subscribe();
          window._rtTeamChannels.teamData = window.sb.channel('rt-team-data-' + tn)
            .on('postgres_changes', {
              event: '*', schema: 'public', table: 'team_data',
              filter: 'team_name=eq.' + tn
            }, _refreshTeamData)
            .subscribe();
        } catch(e) { console.warn('[realtime] takım aboneliği hata:', e); }
      };
      
      // 4) team_data — manifesto, treasury, facility değişimleri
      const _refreshTeamData = _rtDebounce(async () => {
        try {
          if (typeof _mfsLoadFromServer === 'function') await _mfsLoadFromServer();
          if (typeof _trsLoadFromServer === 'function') await _trsLoadFromServer();
          if (typeof _facLevelsLoadFromServer === 'function') await _facLevelsLoadFromServer();
          if (typeof trsSyncHeader === 'function') trsSyncHeader();
        } catch(e) { console.warn('[realtime] team_data refresh hata:', e); }
      }, 1000);
      
      // team_data aboneliği rtBindTeamChannels içinde (takım filtreli) kuruluyor.
      window.rtBindTeamChannels();
      
      // 5) user_wallet — kendi cüzdanım değişti mi (server tarafından)
      //   660 — açılışta oturum kontrolü henüz bitmemiş olabilir: kimlik hazır olunca bir kez bağlanır
      const _kisiselBagla = () => {
        const myUserId = (typeof authUser !== 'undefined' && authUser && authUser.id) || (window.authUser && window.authUser.id);
        if (!myUserId) return false;
        // 690 — user_wallet Realtime yayınında değil, bu abonelik hiç olay almıyordu (kaldırıldı)
        if (false) window.sb.channel('rt-my-wallet')
          .on('postgres_changes', { 
            event: '*', 
            schema: 'public', 
            table: 'user_wallet',
            filter: `user_id=eq.${myUserId}`
          }, _rtDebounce(async () => {
            try {
              const { data } = await window.sb.from('user_wallet').select('*').eq('user_id', myUserId).maybeSingle();
              if (data) {
                _wlCache = {
                  eur: Number(data.eur) || 0,
                  dia: Number(data.dia) || 0,
                  total_in: Number(data.total_in) || 0,
                  total_out: Number(data.total_out) || 0,
                  totalIn: Number(data.total_in) || 0,
                  totalOut: Number(data.total_out) || 0
                };
                if (typeof wlSyncHeader === 'function') wlSyncHeader();
              }
            } catch(e) {}
          }, 300))
          .subscribe();

        // 🆕 7) user_inbox — bana mesaj geldi mi (anlık teslim)
        //   629 — kanal kullanıcıya özel: yönetim panelinden yapılan değişiklik de bu kanaldan
        //   "yonetim" yayını olarak gelir (ek abonelik açılmaz).
        window.sb.channel('rt-my-inbox-' + myUserId)
          .on('broadcast', { event: 'yonetim' }, () => _yonetimIste())
          .on('broadcast', { event: 'duello' }, (m) => { try { pdOlay(m && m.payload); } catch(e) { console.warn('[düello] olay', e); } })
          // 690 — kutu değişince veritabanı tetikleyicisi bu kanala 'kutu' yayını atar
          .on('broadcast', { event: 'kutu' }, _rtDebounce(async () => {
            if (typeof _inboxLoadFromServer !== 'function') return;
            await _inboxLoadFromServer();
            if (typeof inboxUpdateBadge === 'function') inboxUpdateBadge();
            // 🆕 Veri değişmediyse DOM'a dokunma
            if (!window._inboxChanged) return;
            const ov = document.getElementById('inboxOverlay');
            if (ov && ov.classList.contains('open')) {
              if (_inboxView === 'detail' && _inboxCurrentMsg) {
                const fresh = getInboxMsgs().find(m => m.id === _inboxCurrentMsg.id);
                if (fresh) { _inboxCurrentMsg = fresh; inboxRenderDetail(fresh); }
              } else if (_inboxView === 'list' && typeof inboxRenderList === 'function') { inboxRenderList(); }
            }
          }, 60))
          .subscribe((status) => {
            console.info('[inbox] realtime status:', status);
            if (status === 'SUBSCRIBED') { try { pdBaslat(); } catch(e) {} }
            if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT') {
              console.warn('[inbox] realtime BAĞLANAMADI — kanal: rt-my-inbox (kutu / yonetim / duello yayınları)');
            }
          });
        pdBaslat();
        return true;
      };
      if (!_kisiselBagla()) { const _kbT = setInterval(() => { if (_kisiselBagla()) clearInterval(_kbT); }, 1000); }
      
      console.info('[realtime] Subscribe edilen tablolar: match_results, match_state, players, team_data, user_wallet');
    }
  } catch(e) { console.warn('[realtime] subscribe hata:', e); }
  
  // 🆕 14 ardışık await → Promise.all paralel (kritik için bekle, kritik olmayan arka plan)
  // KRİTİK: authInit'in görmesi gereken kullanıcı verileri — bunları beklemeli
  await Promise.all([
    _facLevelsLoadFromServer().catch(e => console.warn('fac_levels load hata:', e)),
    _trsLoadFromServer().catch(e => console.warn('treasury load hata:', e)),
    _mfsLoadFromServer().catch(e => console.warn('manifesto load hata:', e)),
    _userMatchLogLoadFromServer().catch(e => console.warn('matchLog load hata:', e)),
    _teamStrategyLoadFromServer().catch(e => console.warn('team_strategy load hata:', e)),
    _ntStrategyLoadFromServer().catch(e => console.warn('nt_strategy load hata:', e)),
  ]);
  try { authInit(); } catch(e) { console.warn('authInit hata:', e); }

  // 🆕 1) OTURUM KARARI — window.authUser burada doluyor.
  //    Kadro yüklemesi authUser'a bağlı (_rosterRefreshFromServer, authUser
  //    yoksa ilk satırda sessizce çıkıyor), o yüzden veri çekmeden ÖNCE
  //    oturumun netleşmesini beklemek zorundayız.
  //    En fazla 7 sn bekler, sonra devam eder (takılı kalmasın).
  try {
    if (window._authKarar) {
      await Promise.race([
        window._authKarar,
        new Promise(function(r){ setTimeout(r, 7000); })
      ]);
    }
  } catch(e) {}

  // 🆕 2) ANA SAYFA VERİLERİ — splash kapanmadan ÖNCE hazır olsun.
  //    • kadro (ROSTER_DATA): rosterBuildTeam sunucu çağrısını beklemiyordu,
  //      ekran boş/eski kadroyla açılıyor, oyuncu kartında yanlış bilgi çıkıyordu
  //    • çevrimiçi sayacı: açılıştan 5 sn sonra çekiliyordu, o ana kadar 0
  //    ⚠️ SIRA ÖNEMLİ: önce pingLastSeen (kendini çevrimiçi işaretle),
  //       SONRA fetchOnlineStats (listeyi çek). Ters olursa kendini
  //       listede göremezsin ve sayaç 0 kalır.
  //    6 sn içinde gelmezse splash yine de açılır.
  try {
    const _anaSayfaVerisi = Promise.all([
      (async () => {
        const cc = (typeof _userTeam !== 'undefined' && _userTeam) ? _userTeam.countryCode : null;
        if (cc && typeof _rosterRefreshFromServer === 'function') {
          await _rosterRefreshFromServer(cc);
        }
      })().catch(e => console.warn('roster load hata:', e)),
      (async () => {
        if (typeof pingLastSeen === 'function') await pingLastSeen();
        if (typeof fetchOnlineStats === 'function') await fetchOnlineStats();
      })().catch(e => console.warn('online load hata:', e)),
    ]);
    await Promise.race([
      _anaSayfaVerisi,
      new Promise(function(r){ setTimeout(r, 6000); })
    ]);
  } catch(e) { console.warn('ana sayfa verisi hata:', e); }

  // 🆕 _userTeam server'dan geldikten sonra ana sayfa panelleri yenile — SPLASH KAPATMADAN ÖNCE
  //   Eski sıralama: splash.hide → updateHero → renderHomeNextMatch
  //   Sonuç: kullanıcı splash kapanınca BOŞ ana sayfa görür, sonra render olur (flash).
  //   Yeni sıralama: önce render et, sonra splash kapat → ekran dolu açılır.
  try { if (typeof updateHero === 'function') updateHero(); } catch(e) {}
  try { if (typeof renderHomeNextMatch === 'function') renderHomeNextMatch(); } catch(e) {}
  try { if (typeof renderFixture === 'function') renderFixture(); } catch(e) {}
  try { if (typeof renderResultsPage === 'function') renderResultsPage(); } catch(e) {}

  // Oturum kararı yukarıda beklendi (veri çekmeden önce authUser gerekiyordu).
  _acilisBitir();

  // 🆕 AÇILIŞ EMNİYETİ — hangi veri en son gelirse gelsin ana sayfa dolsun.
  //   Takım belliyse ülkenin sezon maçları garanti çekilir, sonra paneller tazelenir.
  (function _bootFillHome(){
    let tries = 0;
    const tick = async () => {
      tries++;
      try {
        // 🆕 524 — takımsız oyuncu için uyruğunun ülkesi
        const _cc = (typeof _hmSahneCC === 'function') ? _hmSahneCC() : null;
        if (_cc && typeof _msEnsureCountry === 'function') {
          await _msEnsureCountry(_cc);
        }
        if (typeof _msRefreshHomePanels === 'function') _msRefreshHomePanels(true);
        const ready = (typeof _msHomeReady === 'function') ? _msHomeReady() : true;
        if ((ready && _cc) || tries >= 12) return;
      } catch(e) {}
      setTimeout(tick, 1000);
    };
    setTimeout(tick, 300);
  })();

  // 🔔 538 — bildirim altyapısını başlat (izin + kanal + maç hatırlatmaları).
  //   Açılışı yavaşlatmamak için oyun yüklendikten birkaç saniye sonra.
  try { setTimeout(function(){ try { _bldBaslat(); } catch(e) {} }, 4500); } catch(e) {}
  
  // 🆕 KRİTİK OLMAYAN VERİLER — arka planda paralel yüklenir, UI bekletmez
  // Bunlar açılış anında gerekmez, sayfaya girince/etkileşimde kullanılır
  Promise.all([
    _loadRealCaptainsFromServer().catch(e => console.warn('realCaptains load hata:', e)),
    _marketValLoadFromServer().catch(e => console.warn('marketval load hata:', e)),
    _joinRequestsLoadFromServer().catch(e => console.warn('joinRequests load hata:', e)),
    _eqDataLoadFromServer().catch(e => console.warn('equipment load hata:', e)),
    _careerHistoryLoadFromServer().catch(e => console.warn('career_history load hata:', e)),
    _ntJerseyOverridesLoadFromServer().catch(e => console.warn('nt_jersey load hata:', e)),
    _shopStocksLoadFromServer().catch(e => console.warn('shop_stocks load hata:', e)),
    _tfListLoadFromServer().then(arr => { _tfListCache = arr; }).catch(e => console.warn('tf_list load hata:', e)),
    achLoadState().then(() => { try { achRefreshBadge(); } catch(e){} }).catch(e => console.warn('achievements load hata:', e)),
    _coachProfileLoadFromServer().catch(e => console.warn('coach_profile load hata:', e)),
  ]).catch(()=>{});
}, 800);

// 🆕 Hazırlık maçları otomatik simülasyonu — saati gelmiş olanları periyodik kontrol et
// Sayfa açılınca + her dakika + sayfa odağa gelince kontrol eder
// 🆕 BEKLEYEN DAVETLERİ ÇÖZ + EKSİK match_state SATIRINI ONAR
//   Sorun: botun cevabı davet gönderildikten 3-6 sn sonra setTimeout ile
//   veriliyordu. Sekme kapanırsa/yenilenirse o zamanlayıcı ölüyor ve davet
//   sonsuza dek 'pending' kalıyordu → maç saati gelse de match_state satırı
//   hiç oluşmadığı için maç BAŞLAMIYORDU.
//   Ayrıca kabul edilmiş ama satırı yazılamamış maçlar burada onarılır.
function _frmResolveStuck() {
  if (typeof FRM_AKTIF !== 'undefined' && !FRM_AKTIF) return;   // 🔴 kapalı
  try {
    const all = (typeof frmGetMatches === 'function') ? frmGetMatches() : null;
    if (!Array.isArray(all) || !all.length) return;
    const now = Date.now();
    const _benim = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName) || null;
    if (!_benim) return;   // takım bilinmeden hiçbir davete cevap üretme
    let n = 0;
    const kapatilan = [];
    for (const m of all) {
      if (!m || !m.id) continue;
      // ⛔ SADECE BENİM GÖNDERDİĞİM DAVET — başkasının davetine bot cevabı üretme
      if (m.fromTeam !== _benim) continue;
      // ⛔ SAATİ GEÇMİŞ DAVET — ne cevaplanır ne yeniden kurulur, kapatılır.
      const _ko = m.dateTime ? new Date(m.dateTime).getTime() : 0;
      if (_ko && (now - _ko) > 3 * 3600 * 1000) {
        if (!m.played) { m.played = true; m.playedAt = _ko; kapatilan.push(m); }
        continue;
      }
      // 1) Cevabı gecikmiş davet → botu şimdi cevaplat (turda en fazla 1 tane)
      if (m.status === 'pending') {
        const bekleme = now - (Number(m.createdAt) || 0);
        if (bekleme > 8000 && n === 0) { try { frmBotRespond(m.id); n++; } catch(e) {} }
        continue;
      }
      // 2) Kabul edilmiş ama match_state satırı yok → yeniden yaz
      if (m.status === 'accepted' && !m.played) {
        const key = 'friendly_' + m.id;
        const varMi = !!(_matchStateCache && _matchStateCache.byKey && _matchStateCache.byKey[key]);
        const kickoff = m.dateTime ? new Date(m.dateTime).getTime() : 0;
        // Maç saati çok geçmişse (24 saat+) onarma
        // 🆕 Turda EN FAZLA 1 onarım: bu artık bir sunucu çağrısı
        //   (friendly_schedule), her turda hepsini denemek gereksiz yük.
        if (!varMi && kickoff && (now - kickoff) < 24 * 3600 * 1000 && n === 0) {
          try { _frmUpsertMatchState(m); n++; } catch(e) {}
        }
      }
    }
    if (kapatilan.length) {
      try { frmSaveMatches(_frmMatchesCache.slice()); } catch(e) {}
      console.info('[hazırlık] süresi geçmiş maç kapatıldı:', kapatilan.length);
    }
    if (n) console.info('[hazırlık] onarılan kayıt:', n);
  } catch(e) {}
}

// 🆕 GELEN KUTUSU TEMİZLİĞİ — aynı hazırlık maçı için birikmiş tekrar mesajları sil.
//   (Önceki sürümde tüm dünyanın davetlerine cevap üretildiği için bildirim yağmuru oldu.)
function _frmPruneInbox() {
  try {
    if (typeof getInboxMsgs !== 'function') return;
    const msgs = getInboxMsgs();
    if (!Array.isArray(msgs) || msgs.length === 0) return;
    // Bana ait hazırlık maçlarının kimlikleri (liste sunucudan geldiyse)
    const benimIdler = new Set();
    const listeHazir = !!window._frmLoaded &&
      !!(typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName);
    if (listeHazir) {
      for (const fm of _frmMatchesCache) { if (fm && fm.id) benimIdler.add(fm.id); }
    }
    const gorulen = new Set();
    const temiz = [];
    let silinen = 0, yabanci = 0;
    for (const m of msgs) {
      const mid = m && m.friendlyData && m.friendlyData.matchId;
      if (m && m.type === 'friendly_response' && mid) {
        // 1) aynı maç için ikinci mesaj → sil
        if (gorulen.has(mid)) { silinen++; continue; }
        gorulen.add(mid);
        // 2) benim hazırlık maçlarımdan biri değilse → sil
        //    (önceki sürümde bu istemci başka oyuncuların davetlerine de
        //     cevap üretip kendi gelen kutuma bildirim yazıyordu)
        if (listeHazir && !benimIdler.has(mid)) { yabanci++; continue; }
      }
      temiz.push(m);
    }
    silinen += yabanci;
    if (silinen > 0) {
      saveInboxMsgs(temiz);
      if (typeof inboxUpdateBadge === 'function') inboxUpdateBadge();
      console.info('[hazırlık] tekrar eden bildirim silindi:', silinen);
    }
  } catch(e) {}
}
window._frmPruneInbox = _frmPruneInbox;

function _frmTickSimulate() {
  // 🔴 Hazırlık maçı kapalıyken hiçbir hazırlık işi dönmesin — yalnızca
  //    ana sayfa önizlemesi tazelensin.
  const _frmKapali = (typeof FRM_AKTIF !== 'undefined' && !FRM_AKTIF);
  if (!_frmKapali) {
    try { _frmPruneInbox(); } catch(e) {}            // 🆕 tekrar bildirimleri temizle
    try { _frmResolveStuck(); } catch(e) {}          // 🆕 önce takılanları çöz
    if (typeof frmEnsurePlayed === 'function') {
      try { frmEnsurePlayed(); } catch(e) {}
    }
  }
  // 🆕 Önizleme paneli güncelle — bitmiş maç bir sonrakiyle değişsin
  if (typeof renderHomeNextMatch === 'function') {
    try { renderHomeNextMatch(); } catch(e) {}
  }
}
// Sayfa açıldığında (auth sonrası) ilk kontrol
setTimeout(_frmTickSimulate, 5000);
// Her 60 saniyede bir
setInterval(() => { if (document.hidden) return; _frmTickSimulate(); }, 60 * 1000);
// 🆕 Sistem mesajı taraması — 3 dakikada bir (hepsi tekrar korumalı)
setInterval(() => { if (document.hidden) return; try { if (typeof sysMsgTara === 'function') sysMsgTara(); } catch(e) {} }, 3 * 60 * 1000);
setTimeout(() => { try { if (typeof sysMsgTara === 'function') sysMsgTara(); } catch(e) {} }, 12000);
// 🆕 Gün dönümü kontrolü — uygulama açıkken gece yarısı geçilirse günlük ödül açılsın
setInterval(() => { if (document.hidden) return; try { if (typeof evEnsureStreakToday === 'function') evEnsureStreakToday(); } catch(e) {} }, 5 * 60 * 1000);
document.addEventListener('visibilitychange', () => {
  if (!document.hidden) { try { if (typeof evEnsureStreakToday === 'function') evEnsureStreakToday(); } catch(e) {} }
});
// Sayfa görünür hale geldiğinde (kullanıcı sekmeye geri döndüğünde)
document.addEventListener('visibilitychange', () => {
  if (!document.hidden) _frmTickSimulate();
});

// 🆕 Inbox poll — kullanıcı oyunda gezerken yeni mesajları yakala (30sn)
// Özellikle "katılma isteği onaylandı" mesajlarını otomatik işler
