// 🆕 KADRO CANLI SENKRON — takım sayfası açıkken ~18sn'de bir SADECE değişiklik varsa tazele.
//   Katılma/ayrılma olunca herkesin ekranı sayfa yenilemeden güncellenir; değişiklik yoksa re-render YOK.
function _rosterCurrentSig(){
  try{
    if(typeof ROSTER_DATA==='undefined' || !Array.isArray(ROSTER_DATA)) return '';
    return ROSTER_DATA.length + '|' + ROSTER_DATA.filter(p=>p && !p.isBot && p.userId).map(p=>p.userId).sort().join(',');
  }catch(e){ return ''; }
}
// 789 — takım arkadaşının (ya da kendimin) adı, mevkisi, uyruğu, avatarı değişince kadro kaydı yerinde güncellenir; diziliş korunur
function _kadroKimlikEsitle(rows) {
  if (typeof ROSTER_DATA === 'undefined' || !Array.isArray(ROSTER_DATA) || !_userTeam) return false;
  const POSGRP = (typeof POS_GROUP !== 'undefined') ? POS_GROUP : {};
  const byId = new Map(ROSTER_DATA.filter(p => p && p.id).map(p => [p.id, p]));
  let degisti = false, ben = false;
  for (const r of rows) {
    const p = r && !r.is_bot ? byId.get(r.id) : null;
    if (!p) continue;
    const yeni = { name: r.name, pos: r.pos, posGroup: r.pos_group || POSGRP[r.pos] || 'MID', subPos: r.sub_pos || null,
                   nationality: r.nationality || _userTeam.countryCode, nation: r.nation || '🏳️', avatar_id: r.avatar_id || null };
    for (const k in yeni) if (p[k] !== yeni[k]) { p[k] = yeni[k]; degisti = true; if (p.isUser) ben = true; }
  }
  if (!degisti) return false;
  if (typeof recalcAllPlayerOveralls === 'function') recalcAllPlayerOveralls();
  _teamRosterCache[_userTeam.countryCode + ':' + _userTeam.teamName] = ROSTER_DATA.slice();
  if (ben && typeof oyKartTazele === 'function') oyKartTazele();
  return true;
}
async function _rosterLiveSyncTick(){
  try { if (typeof window.rtBindTeamChannels === 'function') window.rtBindTeamChannels(); } catch(e) {}
  // 🆕 ÖLÇEK: kadro senkronu 12 sn'de bir çalışıyordu. Kadronun göründüğü sayfalar
  //   dışında (Takım / Ana sayfa / Oyuncum) 4 turda bir yeter → ~48 sn.
  try {
    const _ap = document.querySelector('.page.active');
    const _id = _ap ? _ap.id : '';
    const _kadroEkrani = (_id === 'page-team' || _id === 'page-home' || _id === 'page-player');
    window._rosterSyncSayac = (window._rosterSyncSayac || 0) + 1;
    if (!_kadroEkrani && (window._rosterSyncSayac % 4) !== 0) return;
  } catch(e) {}
  if (document.hidden) return;
  const tp = document.getElementById('page-team');
  if (!tp || !tp.classList.contains('active')) return;            // sadece takım sayfası açıkken
  if (typeof _viewingTeam !== 'undefined' && _viewingTeam) return; // ziyaretçi modunda değil
  if (!(typeof userHasTeam==='function' && userHasTeam()) || !_userTeam || !_userTeam.countryCode || !_userTeam.teamName) return;
  if (!window.sb) return;
  try{
    const { data, error } = await window.sb.from('players')
      .select('id, user_id, is_bot, name, pos, pos_group, sub_pos, nationality, nation, avatar_id')   // 789 — kimlik alanları
      .eq('country_code', _userTeam.countryCode)
      .eq('team_name', _userTeam.teamName);
    if (error || !Array.isArray(data)) return;
    const sig = data.length + '|' + data.filter(p=>p && !p.is_bot && p.user_id).map(p=>p.user_id).sort().join(',');
    if (sig !== _rosterCurrentSig()){
      _kadroUyelikEsitle(true);   // 768 — değişti → yalnız yeni gelenler okunur, diziliş korunur
    } else if (_kadroKimlikEsitle(data)) {
      _kadroCiz();   // 789 — ad / mevki / uyruk / avatar değişti: yerinde güncellendi
    }
  }catch(e){}
}
// 🔴 KADRO TAZELEME SIKLIĞI
//   45 saniye, yeni katılan oyuncunun görünmesi için fazla uzundu:
//   kaptan onaylıyor, diğer üyeler yarım dakikadan fazla eski listeyi
//   görüyor ve "çıkıp girmek gerekiyor" hissi oluşuyordu.
//   Sorgu hafif (yalnız user_id + is_bot) ve sadece Takımım sayfası
//   açıkken çalışıyor, o yüzden 12 saniye pil açısından da güvenli.
setInterval(_rosterLiveSyncTick, 12 * 1000);
document.addEventListener('visibilitychange', () => { if (!document.hidden) _rosterLiveSyncTick(); });

// 🆕 Takımım sayfası açıldığı ANDA da kontrol et — bir sonraki turu bekleme.
//   `showPage('team')` zaten sunucudan çekiyor, ama sayfa zaten açıkken
//   sekmeler arasında gezinirken (Kadro'ya dönüşte) tetiklenmiyordu.
(function(){
  try {
    const tp = document.getElementById('page-team');
    if (!tp || typeof MutationObserver === 'undefined') return;
    new MutationObserver(() => {
      if (tp.classList.contains('active')) {
        try { _rosterLiveSyncTick(); } catch(e) {}
      }
    }).observe(tp, { attributes: true, attributeFilter: ['class'] });
  } catch(e) {}
})();

// Enerji günlük reset kontrolü — her dakika kontrol et (gece yarısı geçişini yakalamak için)
// Performans: fonksiyon hafif, sadece bugünün dayKey'i ile karşılaştırma yapar.
setInterval(() => {
  if(typeof syncEnergyDisplay === 'function') syncEnergyDisplay();
  // Antrenman sayfası açıksa geri sayımı tazele
  const trPage = document.getElementById('page-training');
  if(trPage && trPage.classList.contains('active') && typeof trRender === 'function') {
    // Sadece UI'ı güncelle, full state çağırma değil
    trBaslikCiz();   // 763
  }
}, 60000);

