function hbOpenDrawer(){
  const d=document.getElementById('hbDrawer');
  const o=document.getElementById('hbOverlay');
  if(!d||!o) return;
  d.classList.add('open');
  o.classList.add('open');
  document.body.classList.add('drawer-open');
}

function hbCloseDrawer(){
  const d=document.getElementById('hbDrawer');
  const o=document.getElementById('hbOverlay');
  if(d) d.classList.remove('open');
  if(o) o.classList.remove('open');
  document.body.classList.remove('drawer-open');
}


/* ══════════════════════════════════════════════════════════════
   🆕 ARŞİV — Geçmiş Sezonlar (şampiyonlar · kupalar · terfi/düşme)
   Veri: Supabase match_results / team_data.trophies (canlı okuma)
   ══════════════════════════════════════════════════════════════ */
var _arSeason = null, _arCC = null, _arTab = 'ozet';
var _arArcCC = null, _arArcTier = '';   // Arşiv sekmesi filtreleri ('__all' = tüm ülkeler, '' = tüm takımlar)
var _arCache = { league:{}, cups:{}, finals:null, trophies:null, euro:{}, total:null, cupChamps:null };
var _AR_CUPS = [
  {k:'champ', n:'CHAMPIONSHIP LEAGUE',   ic:'🏆', cls:'g', sub:'en üst kademe'},
  {k:'elite', n:'ELITE LEAGUE',          ic:'🥈', cls:'b', sub:'orta kademe'},
  {k:'conv',  n:'CONVERGENCE LEAGUE',    ic:'🥉', cls:'e', sub:'alt kademe'},
  {k:'enc',   n:'MİLLİ TAKIMLAR KUPASI', ic:'🌍', cls:'n', sub:'milli takımlar'}
];
// 🆕 671 — turnuva banner'larından kesilmiş kupa görselleri (arşiv vitrini + en çok kupa tablosu)
var _AR_KUPA_RES = {"champ": "data:image/webp;base64,", "elite": "data:image/webp;base64,", "conv": "data:image/webp;base64,", "enc": "data:image/webp;base64,"};
var _AR_PHASE_RANK = { group:0, r32:1, r16:2, qf:3, sf:4, final:5 };
// Ligler sayfasındaki bölge renkleri (getStandingsZone ile birebir)
var _AR_ZONE_COL = LG2_BOLGE_RENK;
var _AR_PHASE_NAME = { group:'Grup Aşaması', r32:'Son 32', r16:'Son 16', qf:'Çeyrek Final', sf:'Yarı Final', final:'Final' };

function _arEsc(x){ return String(x==null?'':x).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); }
function _arJs(x){ return String(x==null?'':x).replace(/\\/g,'\\\\').replace(/'/g,"\\'"); }
function _arMoney(n){ try { return Math.round(n).toLocaleString('tr')+' €'; } catch(e){ return n+' €'; } }
function _arLoading(){ return '<div class="ar-load"><div class="ar-spin"></div>Yükleniyor…</div>'; }
function _arCurSeason(){ try { var i=getSeasonInfo(); return i && i.season ? i.season : 1; } catch(e){ return 1; } }
function _arTierName(cc,tier){
  try { var c=_cftGetCountry(cc); var lg=((c&&c.leagues)||[]).find(function(l){return l.tier===tier;}); if(lg&&lg.name) return lg.name; } catch(e){}
  // ⚠️ `tier` 1 TABANLI gelir (match_state.tier / trophy.tierIdx). Eskiden
  //    0 tabanlıymış gibi işleniyordu: Süper Lig "1. Lig", 1. Lig "2. Lig"
  //    görünüyordu. Ortak kurala bağlandı.
  return _ligTierEtiketi(tier);
}
function _arTeamMeta(cc,name){
  try { var c=_cftGetCountry(cc);
    var lgs=(c&&c.leagues)||[];
    for(var i=0;i<lgs.length;i++){ var t=(lgs[i].teams||[]).find(function(x){return x.name===name;}); if(t) return t; }
  } catch(e){}
  return null;
}
function _arBadge(cc,name,cls){
  var t=_arTeamMeta(cc,name);
  var sh=(t&&t.short)||String(name||'?').slice(0,3).toUpperCase();
  if(typeof inlineBadge==='function'){
    return inlineBadge({tag:'div', cls:cls||'ar-crest', team:t, name:name, cc:cc,
      bg:(t&&t.bg)||'#37474f', tc:(t&&t.tc)||'#fff', short:sh});
  }
  return '<div class="'+(cls||'ar-crest')+'" style="background:#37474f;color:#fff">'+_arEsc(sh)+'</div>';
}
function _arFlag(cc){ try{ var c=_cftGetCountry(cc); return (c&&c.flag)||'🏳️'; }catch(e){ return '🏳️'; } }
function _arCName(cc){ try{ var c=_cftGetCountry(cc); return (c&&c.name)||cc; }catch(e){ return cc; } }

/* ── Veri: lig puan durumu (sezon+ülke) ── */
async function _arFetchLeague(season, cc){
  var key = season+'|'+cc;
  if(_arCache.league[key]) return _arCache.league[key];
  var rows=[], from=0;
  while(true){
    var r = await window.sb.from('match_state')
      .select('tier,home_team,away_team,home_score,away_score')
      .eq('season',season).eq('country_code',cc).not('tier','is',null).eq('status','finished')
      .range(from, from+999);
    if(r.error || !r.data || !r.data.length) break;
    rows = rows.concat(r.data);
    if(r.data.length<1000) break;
    from += 1000; if(from>30000) break;
  }
  var byTier={};
  for(var i=0;i<rows.length;i++){
    var m=rows[i], t=m.tier;
    if(!byTier[t]) byTier[t]={};
    var g=byTier[t];
    var h=g[m.home_team]||(g[m.home_team]={name:m.home_team,p:0,w:0,d:0,l:0,gf:0,ga:0,gp:0});
    var a=g[m.away_team]||(g[m.away_team]={name:m.away_team,p:0,w:0,d:0,l:0,gf:0,ga:0,gp:0});
    var hs=+m.home_score, as=+m.away_score;
    if(!isFinite(hs)||!isFinite(as)) continue;
    h.gf+=hs;h.ga+=as;h.gp++; a.gf+=as;a.ga+=hs;a.gp++;
    if(hs>as){h.p+=3;h.w++;a.l++;} else if(hs<as){a.p+=3;a.w++;h.l++;} else {h.p++;a.p++;h.d++;a.d++;}
  }
  var out={};
  Object.keys(byTier).map(Number).sort(function(x,y){return x-y;}).forEach(function(t){
    out[t]=Object.keys(byTier[t]).map(function(k){return byTier[t][k];}).sort(function(x,y){
      if(y.p!==x.p) return y.p-x.p;
      var xd=x.gf-x.ga, yd=y.gf-y.ga;
      if(yd!==xd) return yd-xd;
      return y.gf-x.gf;
    });
  });
  _arCache.league[key]=out;
  return out;
}

/* ── Veri: kupa finalleri (sezon) — match_state kaynaklı (kesin faz bilgisi) ── */
async function _arPens(season, home, away){
  try{
    // 🆕 563 — yalnız penaltı skoru (data'nın tamamı değil)
    var r = await window.sb.from('match_results').select('pens:data->pens')
      .eq('season',season).eq('home_team',home).eq('away_team',away).limit(1);
    var d = r.data && r.data[0];
    if(d && Array.isArray(d.pens) && d.pens.length===2) return d.pens;
  }catch(e){}
  return null;
}
async function _arCupChampsFromTrophies(){
  if(_arCache.cupChamps) return _arCache.cupChamps;
  var map={};
  try{
    var trs = await _arFetchTrophies();
    trs.forEach(function(r){
      (Array.isArray(r.data)?r.data:[]).forEach(function(t){
        if(!t || !t.type || t.type==='league' || t.season==null) return;
        if(!map[t.season]) map[t.season]={};
        map[t.season][t.type]={name:r.team_name, cc:r.country_code};
      });
    });
  }catch(e){}
  _arCache.cupChamps=map;
  return map;
}
async function _arFetchCups(season){
  if(_arCache.cups[season]) return _arCache.cups[season];
  var out={};
  try{
    var r = await window.sb.from('match_state')
      .select('tournament_key,home_team,away_team,home_score,away_score,status')
      .eq('season',season).eq('tournament_phase','final');
    var rows=(r.data||[]).filter(function(m){ return m && m.status==='finished' && m.tournament_key; });
    for(var i=0;i<rows.length;i++){
      var m=rows[i], hs=+m.home_score, as=+m.away_score, win=null, lose=null, extra='';
      if(hs>as){ win=m.home_team; lose=m.away_team; }
      else if(as>hs){ win=m.away_team; lose=m.home_team; }
      else {
        var p = await _arPens(season, m.home_team, m.away_team);
        if(p){ if(p[0]>p[1]){ win=m.home_team; lose=m.away_team; } else { win=m.away_team; lose=m.home_team; }
               extra='pen '+p[0]+'-'+p[1]; }
      }
      out[m.tournament_key]={win:win,lose:lose,hs:hs,as:as,extra:extra,home:m.home_team,away:m.away_team};
    }
    // 🆕 Beraberlik/penaltı → kazanan match_state'te yok; team_data.trophies'ten tamamla
    var champs = (await _arCupChampsFromTrophies())[season] || {};
    Object.keys(out).forEach(function(k){
      if(!out[k].win && champs[k] && champs[k].name){
        out[k].win = champs[k].name;
        out[k].lose = (champs[k].name===out[k].home) ? out[k].away : out[k].home;
        if(!out[k].extra) out[k].extra = 'penaltılarla';
      }
    });
  }catch(e){ console.warn('[arşiv] kupa hata:',e); }
  _arCache.cups[season]=out;
  return out;
}

/* ── Veri: tüm finaller (arşiv tablosu) ── */
async function _arFetchAllFinals(){
  if(_arCache.finals) return _arCache.finals;
  try{
    var r = await window.sb.from('match_state')
      .select('season,tournament_key,home_team,away_team,home_score,away_score,status')
      .eq('tournament_phase','final').order('season');
    var fr = (r.data||[]).filter(function(m){ return m && m.status==='finished' && m.tournament_key; });
    // beraberlikte kazananı penaltıdan çöz (özellikle EURO Cup / milli finaller)
    for(var fi=0; fi<fr.length; fi++){
      var fm=fr[fi];
      if(Number(fm.home_score)===Number(fm.away_score)){
        var pp = await _arPens(fm.season, fm.home_team, fm.away_team);
        if(pp) fm._pens = pp;
      }
    }
    _arCache.finals = fr;
  }catch(e){ _arCache.finals=[]; }
  return _arCache.finals;
}

/* ── Veri: kupa envanteri (team_data.trophies) ── */
async function _arFetchTrophies(){
  if(_arCache.trophies) return _arCache.trophies;
  var rows=[], from=0;
  try{
    while(true){
      var r = await window.sb.from('team_data').select('country_code,team_name,data')
        .eq('data_key','trophies').range(from, from+999);
      if(r.error||!r.data||!r.data.length) break;
      rows=rows.concat(r.data);
      if(r.data.length<1000) break;
      from+=1000; if(from>20000) break;
    }
  }catch(e){}
  _arCache.trophies=rows;
  return rows;
}

/* ── Veri: kullanıcının o sezonki Avrupa yolu ── */
async function _arFetchEuro(season, cc, name){
  var key=season+'|'+cc+'|'+name;
  if(_arCache.euro[key]) return _arCache.euro[key];
  var best=null;
  try{
    var nm=String(name).replace(/"/g,'');
    var r = await window.sb.from('match_results')
      .select('tournament_key,tournament_phase')
      .eq('season',season).not('tournament_key','is',null)
      .or('home_team.eq."'+nm+'",away_team.eq."'+nm+'"');
    (r.data||[]).forEach(function(m){
      if(!m.tournament_key || m.tournament_key==='enc') return;
      var rank=_AR_PHASE_RANK[m.tournament_phase];
      if(rank==null) return;
      if(!best || rank>best.rank) best={key:m.tournament_key, phase:m.tournament_phase, rank:rank};
    });
  }catch(e){}
  _arCache.euro[key]=best||{none:true};
  return _arCache.euro[key];
}

/* ── 630 · Görünüm yardımcıları ── */
var _arGen = 0;   // her çizimde artar: geç gelen eski sekme sonucu ekrana yazılmaz
function _arYaz(gen, h){ if(gen!==_arGen) return; var b=document.getElementById('arBody'); if(b) b.innerHTML=h; }
function _arIk(ad, cls){ return '<svg class="ar-ik'+(cls?' '+cls:'')+'" viewBox="0 0 24 24" aria-hidden="true"><use href="#ic-ar-'+ad+'"/></svg>'; }
function _arKalkan(tier, boy){ return (typeof _banKalkanImg==='function') ? _banKalkanImg((Number(tier)||1)-1, boy||18) : ''; }
function _arKart(ikon, baslik, alt, govde, cls){
  return '<div class="ar-card'+(cls?' '+cls:'')+'"><div class="ar-ch"><div class="ic">'+ikon+'</div>'
    + '<div class="ti"><b>'+baslik+'</b>'+(alt?'<span>'+alt+'</span>':'')+'</div></div>'+govde+'</div>';
}
function _arBos(ikon, metin){ return '<div class="ar-card"><div class="ar-empty"><div class="e">'+ikon+'</div>'+metin+'</div></div>'; }
function _arUlkeler(){
  var codes=[];
  try{ codes=(_cftGetCountryCodes()||[]).slice(); }catch(e){}
  return codes.sort(function(a,b){ return _arCName(a).localeCompare(_arCName(b),'tr'); });
}
function _arUlkeSecenek(cc){ return { v:cc, ad:_arCName(cc), ikon:'<span class="bay">'+_arFlag(cc)+'</span>' }; }

/* ── Sezon şeridi (en yeni başta) ── */
function arRenderSeasons(){
  var el=document.getElementById('arSeasons'); if(!el) return;
  var cur=_arCurSeason(), h='';
  for(var sN=cur; sN>=1; sN--){
    var live = (sN===cur);
    h += '<button type="button" class="ar-spill'+(sN===_arSeason?' on':'')+(live?' live':'')+'" onclick="arSelSeason('+sN+')">'
      + (live?'<i class="ar-nokta"></i>':'')+'<span>SEZON '+sN+'</span>'+(live?'<em>CANLI</em>':'')+'</button>';
  }
  el.innerHTML=h;
}
function arSelSeason(sN){ _arSeason=sN; arRenderSeasons(); arRender(); }
function arTab(t, btn){
  _arTab=t;
  try{
    document.querySelectorAll('#page-archive .ar-tab').forEach(function(b){ b.classList.remove('active'); });
    if(btn) btn.classList.add('active');
  }catch(e){}
  arRender();
}
function arSelCC(cc){ _arCC=cc; arRender(); }
function arArcCC(v){ _arArcCC=v; _arArcTier=''; arRender(); }
function arArcTier(v){ _arArcTier=v; arRender(); }
function arLigUlkeSec(){ mgSecimAc('Ülke', _arUlkeler().map(_arUlkeSecenek), _arCC, arSelCC); }
function _arTeamTier(cc,name){
  try{ var c=_cftGetCountry(cc); var lgs=(c&&c.leagues)||[];
    for(var i=0;i<lgs.length;i++){ if((lgs[i].teams||[]).some(function(t){return t.name===name;})) return lgs[i].tier; }
  }catch(e){}
  return null;
}
function arAcKapa(id, btn, kapaliYazi){
  var el=document.getElementById(id); if(!el) return;
  var on=el.classList.toggle('on');
  if(btn) btn.textContent = on ? 'GİZLE ▴' : kapaliYazi;
}
function arToggleFull(id, btn){
  var el=document.getElementById(id); if(!el) return;
  var on=el.classList.toggle('on');
  if(btn) btn.textContent = on ? 'GİZLE ▴' : 'TÜM PUAN DURUMU ▾';
}

/* ── Giriş ── */
function arInit(){
  var cur=_arCurSeason();
  _arSeason = cur;   // 🆕 sayfa her açıldığında CANLI sezon seçili gelir
  if(!_arCC){
    _arCC = (typeof _userTeam!=='undefined' && _userTeam && _userTeam.countryCode) ? _userTeam.countryCode : null;
    if(!_arCC){ try{ _arCC=(_cftGetCountryCodes()||[])[0]||'TR'; }catch(e){ _arCC='TR'; } }
  }
  if(_arArcCC==null) _arArcCC='__all';   // varsayılan: Tüm Ülkeler · Tüm takımlar
  arRenderSeasons();
  arRender();
}
function arRender(){
  var body=document.getElementById('arBody'); if(!body) return;
  var gen=++_arGen;
  body.innerHTML=_arLoading();
  if(_arTab==='ozet') _arRenderOzet(gen);
  else if(_arTab==='lig') _arRenderLig(gen);
  else if(_arTab==='kupa') _arRenderKupa(gen);
  else _arRenderArsiv(gen);
}

/* ── SEKME: ÖZETİM ── */
async function _arRenderOzet(gen){
  var ut=(typeof _userTeam!=='undefined')?_userTeam:null;
  if(!ut || !ut.teamName || !ut.countryCode){
    _arYaz(gen, _arBos(_arIk('ozet'), 'Bir takımda değilsin.<br>Takıma katıldığında sezon özetin burada görünecek.'));
    return;
  }
  var cc=ut.countryCode, nm=ut.teamName, sN=_arSeason;
  try{
    var lg = await _arFetchLeague(sN, cc);
    var tiers=Object.keys(lg).map(Number).sort(function(a,b){return a-b;});
    var myTier=null, myRow=null, myPos=0, myTotal=0;
    for(var i=0;i<tiers.length;i++){
      var arr=lg[tiers[i]];
      for(var j=0;j<arr.length;j++){ if(arr[j].name===nm){ myTier=tiers[i]; myRow=arr[j]; myPos=j+1; myTotal=arr.length; break; } }
      if(myRow) break;
    }
    if(!myRow){
      _arYaz(gen, _arBos(_arIk('bilgi'), _arEsc(nm)+' için Sezon '+sN+' lig kaydı bulunamadı.'));
      return;
    }
    var minT=tiers[0], maxT=tiers[tiers.length-1];
    var lgAd=_arTierName(cc,myTier);
    var hrk;
    if(myPos<=4 && myTier>minT) hrk={c:'up', m:_arTierName(cc,myTier-1)+'\'e yükseldi'};
    else if(myPos>myTotal-4 && myTier<maxT) hrk={c:'dn', m:_arTierName(cc,myTier+1)+'\'e düştü'};
    else hrk={c:'ok', m:lgAd+'\'de kaldı'};

    var euro = await _arFetchEuro(sN, cc, nm);
    var cupDef = (euro && !euro.none) ? _AR_CUPS.filter(function(c){return c.k===euro.key;})[0] : null;
    var gd=myRow.gf-myRow.ga;
    var prize = ekoSiraOdulu(myTier, myPos, sN);

    var trs = await _arFetchTrophies();
    var mine = trs.filter(function(r){ return r.country_code===cc && r.team_name===nm; });
    var myTrophies = [];
    mine.forEach(function(r){ (Array.isArray(r.data)?r.data:[]).forEach(function(t){ if(t && t.season===sN) myTrophies.push(t); }); });

    var h='<div class="ar-hero"><div class="ar-hero-r">'
      + _arBadge(cc,nm,'ar-crest-l')
      + '<div class="ar-hero-i"><div class="nm">'+_arEsc(nm)+'</div>'
      + '<div class="lg">'+_arKalkan(myTier,17)+'<span class="bay">'+_arFlag(cc)+'</span><span>'+_arEsc(lgAd)+' · Sezon '+sN+'</span></div></div>'
      + '<div class="ar-pos'+(myPos===1?' bir':'')+'"><div class="n">'+myPos+'<small>/'+myTotal+'</small></div><div class="l">Sıra</div></div></div>'
      + '<div class="ar-badges">'
      + (myPos===1 ? '<span class="ar-bdg tr">'+_arIk('kupa')+'<span>Şampiyon</span></span>'
                   : '<span class="ar-bdg tr">'+_arIk('lig')+'<span>Ligde '+myPos+'.</span></span>')
      + (cupDef ? '<span class="ar-bdg eu">'+_arCupLogo(euro.key,15)+'<b>'+_arEsc(cupDef.n.split(' ')[0])+'</b><span>'+_arEsc(_AR_PHASE_NAME[euro.phase]||euro.phase)+'</span></span>' : '')
      + '<span class="ar-bdg '+hrk.c+'">'+_arIk('ok')+'<span>'+_arEsc(hrk.m)+'</span></span>'
      + '</div></div>';

    var oran=function(x){ return myRow.gp ? (x*100/myRow.gp).toFixed(1) : 0; };
    var hucre=function(v,k,c){ return '<div class="ar-scell'+(c?' '+c:'')+'"><div class="v">'+v+'</div><div class="k">'+k+'</div></div>'; };
    h+=_arKart(_arIk('grafik'), 'Lig Performansı', myRow.gp+' maç · '+_arEsc(lgAd),
      '<div class="ar-cb">'
      + '<div class="ar-gbm"><i class="g" style="width:'+oran(myRow.w)+'%"></i><i class="b" style="width:'+oran(myRow.d)+'%"></i><i class="m" style="width:'+oran(myRow.l)+'%"></i></div>'
      + '<div class="ar-gbm-l"><span class="g"><b>'+myRow.w+'</b><span>Galibiyet</span></span><span class="b"><b>'+myRow.d+'</b><span>Beraber</span></span><span class="m"><b>'+myRow.l+'</b><span>Mağlup</span></span></div>'
      + '<div class="ar-sgrid">'+hucre(myRow.p,'Puan','y')+hucre(myRow.gf,'Attı','')+hucre(myRow.ga,'Yedi','')+hucre((gd>0?'+':'')+gd,'Averaj',gd>=0?'g':'r')+'</div>'
      + '</div>');

    var satir=function(ikon, bas, alt, cls){
      return '<div class="ar-kz'+(cls?' '+cls:'')+'"><span class="ic">'+ikon+'</span><span class="tx"><b>'+bas+'</b>'+(alt?'<small>'+alt+'</small>':'')+'</span></div>';
    };
    var kz='';
    myTrophies.forEach(function(t){
      if(t.type==='league') kz+=satir(_arKalkan(t.tierIdx,24), _arEsc(_arTierName(cc, t.tierIdx))+' Şampiyonu', 'Lig şampiyonluğu', 'altin');
      else kz+=satir(_arCupLogo(t.type,24), _arEsc(t.name||t.type||'Kupa'), 'Şampiyon', 'mavi');
    });
    if(cupDef && !myTrophies.some(function(t){ return t.type===euro.key; })){
      kz+=satir(_arCupLogo(euro.key,24), _arEsc(cupDef.n), _arEsc(_AR_PHASE_NAME[euro.phase]||euro.phase), 'mavi');
    }
    kz+=satir(_arKalkan(myTier,24), _arEsc(lgAd), myPos+'. sıra', '');
    h+=_arKart(_arIk('kupa'), 'Kazanımlar', 'Sezon '+sN, '<div class="ar-cb">'+kz+'</div>');

    h+=_arKart(_arIk('para'), 'Sezon Ödülü', 'lig sıralama ödülü',
      '<div class="ar-cb"><div class="ar-kz ar-odul"><span class="ic">'+_arKalkan(myTier,24)+'</span>'
      + '<span class="tx"><b>'+_arEsc(lgAd)+' · '+myPos+'. sıra</b><small>Kasaya yatan</small></span>'
      + '<span class="v">'+_arMoney(prize)+'</span></div></div>');

    _arYaz(gen, h);
  }catch(e){
    console.warn('[arşiv] özet hata:',e);
    _arYaz(gen, _arBos(_arIk('bilgi'), 'Veri yüklenemedi.'));
  }
}

/* ── SEKME: LİGLER ── */
async function _arRenderLig(gen){
  var head='<div class="ar-filtre"><button type="button" class="mg-cip" onclick="arLigUlkeSec()"><small>Ülke</small>'
    + '<span><span class="bay">'+_arFlag(_arCC)+'</span><b>'+_arEsc(_arCName(_arCC))+'</b></span></button></div>';
  try{
    var lg = await _arFetchLeague(_arSeason, _arCC);
    var tiers=Object.keys(lg).map(Number).sort(function(a,b){return a-b;});
    if(!tiers.length){
      _arYaz(gen, head+_arBos(_arIk('lig'), 'Sezon '+_arSeason+' için '+_arEsc(_arCName(_arCC))+' lig kaydı yok.'));
      return;
    }
    var myName=(typeof _userTeam!=='undefined'&&_userTeam)?_userTeam.teamName:null;
    var myCC=(typeof _userTeam!=='undefined'&&_userTeam)?_userTeam.countryCode:null;
    var minT=tiers[0], maxT=tiers[tiers.length-1];
    var isMine=function(n){ return myName && n===myName && myCC===_arCC; };
    var benimKume=null;
    tiers.forEach(function(t){ if(lg[t].some(function(x){ return isMine(x.name); })) benimKume=t; });
    if(benimKume==null) benimKume=minT;
    var tm=function(n, pos, renk){
      return '<button type="button" class="ar-tm'+(isMine(n)?' me':'')+'" style="--z:'+renk+'" onclick="viewTeam(\''+_arJs(_arCC)+'\',\''+_arJs(n)+'\')">'
        + '<span class="r">'+pos+'</span>'+_arBadge(_arCC,n,'ar-mini')+'<span class="ad">'+_arEsc(n)+'</span>'+(isMine(n)?'<span class="yz">★</span>':'')+'</button>';
    };
    var h=head;
    tiers.forEach(function(t){
      var arr=lg[t], champ=arr[0], total=arr.length;
      h+='<div class="ar-card ar-lig" style="--lk:'+(LG2_KALKAN_RENK[t-1]||'#78909c')+'">'
        + '<div class="ar-lig-h">'+_arKalkan(t,30)+'<div class="ti"><b>'+_arEsc(_arTierName(_arCC,t))+'</b><span>'+total+' takım · Sezon '+_arSeason+'</span></div></div>';
      if(champ){
        var cd=champ.gf-champ.ga;
        h+='<button type="button" class="ar-champ" onclick="viewTeam(\''+_arJs(_arCC)+'\',\''+_arJs(champ.name)+'\')">'
          + '<span class="kp">'+_arIk('kupa')+'</span>'+_arBadge(_arCC,champ.name,'ar-crest')
          + '<span class="tx"><small>ŞAMPİYON</small><b>'+_arEsc(champ.name)+'</b></span>'
          + '<span class="pt"><b>'+champ.p+'</b><small>PUAN</small><em>'+(cd>=0?'+':'')+cd+'</em></span></button>';
      }
      // En üst lig: Avrupa kupası katılım hakları (1-2 CHM · 3-4 ELI · 5-6 CON)
      if(t===minT && arr.length>=6){
        h+='<div class="ar-blok"><div class="ar-blok-b">'+_arIk('dunya')+'<span>Avrupa kupası katılım hakkı · Sezon '+(_arSeason+1)+'</span></div>';
        [{k:'champ',n:'Championship League',a:1,b:2,z:['chm-d','chm-p']},
         {k:'elite',n:'Elite League',a:3,b:4,z:['eli-d','eli-p']},
         {k:'conv', n:'Convergence League',a:5,b:6,z:['con-d','con-p']}].forEach(function(ed){
          var list=arr.slice(ed.a-1, ed.b);
          if(!list.length) return;
          h+='<div class="ar-avr"><span class="ka">'+_arCupLogo(ed.k,18)+'<b>'+ed.n+'</b></span><span class="ar-tl">';
          list.forEach(function(x,ix){ h+=tm(x.name, ed.a+ix, _AR_ZONE_COL[ed.z[ix]]); });
          h+='</span></div>';
        });
        h+='</div>';
      }
      var ups=[], dns=[];
      arr.forEach(function(x,idx){
        var pos=idx+1;
        if(pos<=4 && t>minT) ups.push({n:x.name,r:pos});
        else if(pos>total-4 && t<maxT) dns.push({n:x.name,r:pos});
      });
      if(ups.length){
        h+='<div class="ar-blok"><div class="ar-blok-b up">'+_arIk('ok')+'<span>'+_arEsc(_arTierName(_arCC,t-1))+'\'e yükselenler</span></div><div class="ar-tl">';
        ups.forEach(function(u){ h+=tm(u.n, u.r, _AR_ZONE_COL.promo); });
        h+='</div></div>';
      }
      if(dns.length){
        h+='<div class="ar-blok"><div class="ar-blok-b dn">'+_arIk('ok')+'<span>'+_arEsc(_arTierName(_arCC,t+1))+'\'e düşenler</span></div><div class="ar-tl">';
        dns.forEach(function(u){ h+=tm(u.n, u.r, _AR_ZONE_COL.rel); });
        h+='</div></div>';
      }
      var acik=(t===benimKume);
      var fid='arFull_'+_arCC+'_'+t;
      var takimlar=arr.map(function(x){
        return Object.assign({}, _arTeamMeta(_arCC,x.name)||{}, { name:x.name, played:x.gp, g:x.w, b:x.d, m:x.l, ag:x.gf, ay:x.ga, pts:x.p });
      });
      h+='<div class="ar-full'+(acik?' on':'')+'" id="'+fid+'">'+_lgPuanTablosu(takimlar, _arCC, t-1, maxT, (myCC===_arCC?myName:null))+'</div>';
      h+='<button type="button" class="ar-more" onclick="arToggleFull(\''+fid+'\',this)">'+(acik?'GİZLE ▴':'TÜM PUAN DURUMU ▾')+'</button></div>';
    });
    _arYaz(gen, h);
  }catch(e){
    console.warn('[arşiv] lig hata:',e);
    _arYaz(gen, head+_arBos(_arIk('bilgi'), 'Veri yüklenemedi.'));
  }
}

/* ── SEKME: KUPALAR ── */
async function _arRenderKupa(gen){
  try{
    var cups = await _arFetchCups(_arSeason);
    var h='<div class="ar-kupa-grid">';
    _AR_CUPS.forEach(function(c){
      var d=cups[c.k], isNat=(c.k==='enc');
      h+='<div class="ar-cup '+c.cls+'"><div class="ar-cuph"><div class="ar-cupic">'+_arCupLogo(c.k,34)+'</div>'
        + '<div class="ar-cupt"><b>'+_arEsc(c.n)+'</b><span>Sezon '+_arSeason+' · '+_arEsc(c.sub)+'</span></div></div>';
      var fin=function(){
        return '<div class="ar-final"><span class="fl">FİNAL</span><div class="ar-fm">'
          + '<span class="ev'+(d.win===d.home?' w':'')+'">'+_arSideHtml(isNat,d.home)+'</span>'
          + '<span class="sc">'+d.hs+' – '+d.as+'</span>'
          + '<span class="dep'+(d.win===d.away?' w':'')+'">'+_arSideHtml(isNat,d.away)+'</span></div>'
          + (d.extra?'<span class="lo">'+_arEsc(d.extra)+'</span>':'')+'</div>';
      };
      if(d && d.win){
        var wcc = isNat ? _arNatCC(d.win) : _arGuessCC(d.win);
        var sub = isNat ? 'Milli Takım' : (_arFlag(wcc)+' '+_arEsc(_arCName(wcc)));
        var click = isNat
          ? (wcc ? ' onclick="ntViewAsGuest(\''+_arJs(wcc)+'\')"' : '')
          : (wcc ? ' onclick="viewTeam(\''+_arJs(wcc)+'\',\''+_arJs(d.win)+'\')"' : '');
        h+='<div class="ar-win"'+click+'>'
          + (isNat ? '<div class="ar-natflag">'+_arFlag(wcc)+'</div>' : _arBadge(wcc, d.win,'ar-crest'))
          + '<div class="wi"><small>ŞAMPİYON</small><div class="n">'+_arEsc(d.win)+'</div><div class="s">'+sub+'</div></div>'
          + _arIk('kupa','b')+'</div>' + fin();
      } else if(d){
        // final oynandı ama kazanan tespit edilemedi (beraberlik + penaltı kaydı yok)
        h+=fin()+'<div class="ar-empty k">Final oynandı · kazanan penaltılarla belirlendi (kayıt yok)</div>';
      } else {
        h+='<div class="ar-empty k">'+_arIk('bilgi')+'<span>Final henüz oynanmadı.</span></div>';
      }
      h+='<button type="button" class="ar-more" onclick="arOpenTrnDetail(\''+c.k+'\')"><span>TÜM TURNUVA DETAYLARI</span> ›</button>';
      h+='</div>';
    });
    h+='</div>';
    _arYaz(gen, h);
  }catch(e){
    console.warn('[arşiv] kupa hata:',e);
    _arYaz(gen, _arBos(_arIk('bilgi'), 'Veri yüklenemedi.'));
  }
}
var _arNameIdx=null;
function _arBuildIdx(){
  if(_arNameIdx) return _arNameIdx;
  var idx={team:{}, country:{}};
  try{
    (_cftGetCountryCodes()||[]).forEach(function(cc){
      var c=_cftGetCountry(cc); if(!c) return;
      if(c.name) idx.country[String(c.name).toLowerCase()]=cc;
      idx.country[String(cc).toLowerCase()]=cc;
      (c.leagues||[]).forEach(function(lg){
        (lg.teams||[]).forEach(function(t){ if(t&&t.name&&!idx.team[t.name]) idx.team[t.name]=cc; });
      });
    });
  }catch(e){}
  _arNameIdx=idx; return idx;
}
function _arGuessCC(name){ var i=_arBuildIdx(); return i.team[name]||''; }
function _arSideHtml(isNat, name){
  var cc = isNat ? _arNatCC(name) : _arGuessCC(name);
  var mini = isNat ? '<span style="font-size:14px">'+_arFlag(cc)+'</span>' : _arBadge(cc,name,'ar-mini');
  var click = cc ? (isNat ? ' onclick="ntViewAsGuest(\''+_arJs(cc)+'\')"' : ' onclick="viewTeam(\''+_arJs(cc)+'\',\''+_arJs(name)+'\')"') : '';
  return '<span style="display:inline-flex;align-items:center;gap:5px;cursor:'+(cc?'pointer':'default')+'"'+click+'>'+mini+_arEsc(name)+'</span>';
}
function _arNatCC(name){ var i=_arBuildIdx(); return i.country[String(name||'').toLowerCase()]||''; }
// 🆕 671 — banner kupası (vitrin rafı); görsel yoksa eski logo
function _arKupaRes(k){
  var src=_AR_KUPA_RES[k];
  return src ? '<span class="ar-kres" style="background-image:url('+src+')"></span>' : _arCupLogo(k,20);
}
// 🆕 671 — Tüm zamanlar · En Çok Kupa: lig şampiyonlukları + CHM/ELI/CON (milli kupa hariç)
//   675 — yalnız CHM, ELI, CON ve Süper Lig. İlk 10 görünür, "Tam liste" ile kupası olan herkes.
//   Sıralama: toplam kupa; eşitlikte CHM › ELI › CON › Süper Lig
function _arEnCokKupa(trs, bySeason){
  var m={};
  function ekle(cc,nm,tip,sezon,tier){
    if(!nm) return;
    var key=(cc||'')+'|'+nm;
    if(!m[key]) m[key]={cc:cc||'', nm:nm, ch:0, el:0, cv:0, lg:[], g:{}};
    var x=m[key], g=tip+'|'+sezon+'|'+(tip==='league'?(tier==null?'':tier):'');
    if(x.g[g]) return; x.g[g]=1;
    if(tip==='champ') x.ch++; else if(tip==='elite') x.el++; else if(tip==='conv') x.cv++;
    else if(Number(tier)===1) x.lg.push(1);   // 675 — yalnız Süper Lig; alt lig şampiyonlukları sayılmaz
  }
  (trs||[]).forEach(function(r){
    (Array.isArray(r.data)?r.data:[]).forEach(function(t){
      if(!t || t.type==='enc' || t.season==null) return;
      ekle(r.country_code, r.team_name, t.type||'league', String(t.season), t.tierIdx);
    });
  });
  // finallerden gelen ama trophies'te olmayan kupalar
  Object.keys(bySeason||{}).forEach(function(sN){
    ['champ','elite','conv'].forEach(function(ck){
      var w=bySeason[sN][ck]; if(!w) return;
      var vardi=Object.keys(m).some(function(k){ return m[k].nm===w && m[k].g[ck+'|'+sN+'|']; });
      if(!vardi) ekle(_arGuessCC(w), w, ck, String(sN), null);
    });
  });
  var L=Object.keys(m).map(function(k){ var x=m[k]; x.lg.sort(function(a,b){return a-b;}); x.tot=x.ch+x.el+x.cv+x.lg.length; return x; });
  if(_arArcCC && _arArcCC!=='__all') L=L.filter(function(x){ return x.cc===_arArcCC; });
  L=L.filter(function(x){ return x.tot>0; }).sort(function(a,b){
    if(b.tot!==a.tot) return b.tot-a.tot;
    if(b.ch!==a.ch) return b.ch-a.ch;
    if(b.el!==a.el) return b.el-a.el;
    if(b.cv!==a.cv) return b.cv-a.cv;
    for(var i=0;i<Math.min(a.lg.length,b.lg.length);i++){ if(a.lg[i]!==b.lg[i]) return a.lg[i]-b.lg[i]; }
    return a.nm.localeCompare(b.nm,'tr');
  });
  var kp=function(k){ return '<span class="kp ar-t-'+k+'" style="background-image:url('+_AR_KUPA_RES[k]+')"></span>'; };
  var n=function(v){ return '<span class="n'+(v?'':' s')+'">'+(v||'·')+'</span>'; };
  var g='';
  if(!L.length){
    g='<div class="ar-empty">Henüz kupa kazanılmadı</div>';
  } else {
    g='<div class="ar-tb"><div class="r bas"><span></span><span class="tk">TAKIM</span><span>'+kp('champ')+'</span><span>'+kp('elite')+'</span><span>'+kp('conv')+'</span><span>'+_arKalkan(1,21)+'</span><span class="top">Toplam</span></div>';
    L.forEach(function(x,i){
      if(i===10) g+='<div class="ar-full" id="arKupaTam">';
      var click = x.cc ? ' onclick="viewTeam(\''+_arJs(x.cc)+'\',\''+_arJs(x.nm)+'\')"' : '';
      g+='<div class="r"'+click+'><span class="rk'+(i<3?' g'+(i+1):'')+'">'+(i+1)+'</span>'
        + '<span class="tk">'+_arBadge(x.cc,x.nm,'ar-crest')+'<b>'+_arEsc(x.nm)+'</b>'+(x.cc?'<span class="bay">'+_arFlag(x.cc)+'</span>':'')+'</span>'
        + n(x.ch)+n(x.el)+n(x.cv)+n(x.lg.length)+'<span class="n t">'+x.tot+'</span></div>';
    });
    if(L.length>10) g+='</div>';
    g+='</div>';
    if(L.length>10) g+='<button type="button" class="ar-more" onclick="arAcKapa(\'arKupaTam\',this,\'TAM LİSTE ▾\')">TAM LİSTE ▾</button>';
  }
  var kapsam=(_arArcCC && _arArcCC!=='__all') ? _arCName(_arArcCC) : 'Tüm ülkeler';
  return _arKart(_arIk('tac'), 'En Çok Kupa', _arEsc(kapsam)+' · tüm zamanlar · ilk 10', g, 'ar-tbk');
}
function _arCupLogo(k,size){
  var map={champ:'champ',elite:'elite',conv:'conv',enc:'natcup'};
  try{ if(typeof _cupLogoInline==='function'){ var h=_cupLogoInline(map[k]||k,size||30); if(h) return h; } }catch(e){}
  return {champ:'🏆',elite:'🥈',conv:'🥉',enc:'🌍'}[k]||'🏅';
}


// 🆕 ARŞİV — TURNUVA DETAY ÖZETİ (tüm aşamalar, grup → final)
function arCloseTrnDetail() {
  const o = document.getElementById('arTrnOverlay');
  if (o) o.classList.remove('open');
  try { document.body.style.overflow = ''; } catch(e) {}
}
async function arOpenTrnDetail(trnKey) {
  const ov = document.getElementById('arTrnOverlay');
  const body = document.getElementById('artdBody');
  if (!ov || !body) return;
  const def = _AR_CUPS.filter(c => c.k === trnKey)[0];
  const t = document.getElementById('artdTitle'); if (t) t.textContent = def ? def.n : trnKey;
  const sb = document.getElementById('artdSub'); if (sb) sb.textContent = 'Sezon ' + _arSeason + ' · tüm aşamalar';
  const ic = document.getElementById('artdIcon'); if (ic) ic.innerHTML = _arCupLogo(trnKey, 24);
  body.innerHTML = '<div class="artd-empty">⏳ Yükleniyor…</div>';
  ov.classList.add('open');
  try { document.body.style.overflow = 'hidden'; } catch(e) {}

  try {
    const rows = [];
    for (let from = 0; ; from += 1000) {
      const r = await window.sb.from('match_state')
        .select('tournament_phase,home_team,away_team,home_score,away_score,status,day_in_season,country_code')
        .eq('season', _arSeason).eq('tournament_key', trnKey)
        .order('day_in_season').range(from, from + 999);
      if (r.error || !r.data || !r.data.length) break;
      rows.push(...r.data);
      if (r.data.length < 1000) break;
    }
    if (!rows.length) { body.innerHTML = '<div class="artd-empty">Bu sezon için maç kaydı yok.</div>'; return; }

    const ORDER = ['playoff','po2','playoff2','group','r32','r16','qf','sf','final'];
    const NAME = { playoff:'Play-off', po2:'Play-off 2', playoff2:'Play-off 2', group:'Grup Aşaması',
                   r32:'Son 32', r16:'Son 16', qf:'Çeyrek Final', sf:'Yarı Final', final:'Final' };
    const byPh = {};
    rows.forEach(m => { const p = m.tournament_phase || 'group'; (byPh[p] = byPh[p] || []).push(m); });
    const isNat = (trnKey === 'enc');

    let h = '';
    ORDER.forEach(ph => {
      const list = byPh[ph];
      if (!list || !list.length) return;
      const done = list.filter(m => m.status === 'finished').length;
      h += `<div class="artd-ph"><b>${NAME[ph] || ph}</b><span>${done}/${list.length} oynandı</span></div>`;
      // Grup aşamasında maç listesi çok uzun → sadece özet + kullanıcının ülkesi
      const show = (ph === 'group') ? list.slice(0, 24) : list;
      show.forEach(m => {
        const fin = m.status === 'finished';
        const hs = Number(m.home_score), as = Number(m.away_score);
        const hw = fin && hs > as, aw = fin && as > hs;
        const nm = n => isNat ? (_arFlag(_arNatCC(n)) + ' ' + _arEsc(n)) : _arEsc(n);
        h += `<div class="artd-m">
            <div class="t ${hw ? 'w' : ''}">${nm(m.home_team)}</div>
            <div class="sc ${fin ? '' : 'pend'}">${fin ? (hs + ' - ' + as) : 'vs'}</div>
            <div class="t r ${aw ? 'w' : ''}">${nm(m.away_team)}</div>
          </div>`;
      });
      if (ph === 'group' && list.length > 24) {
        h += `<div style="text-align:center;font-size:10px;color:var(--text3);padding:6px">+${list.length - 24} maç daha</div>`;
      }
    });
    body.innerHTML = h || '<div class="artd-empty">Aşama verisi yok.</div>';
  } catch(e) {
    body.innerHTML = '<div class="artd-empty">Veri yüklenemedi.</div>';
  }
}
document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') {
    const o = document.getElementById('arTrnOverlay');
    if (o && o.classList.contains('open')) arCloseTrnDetail();
  }
});

/* ── SEKME: ARŞİV ── */
function arArcUlkeSec(){
  mgSecimAc('Ülke', [{ v:'__all', ad:'Tüm Ülkeler', ikon:_MG_IKON.dunya }].concat(_arUlkeler().map(_arUlkeSecenek)), _arArcCC, arArcCC);
}
function arArcLigSec(){
  if(!_arArcCC || _arArcCC==='__all') return;
  var c=_cftGetCountry(_arArcCC);
  var lgs=((c&&c.leagues)||[]).slice().sort(function(a,b){return a.tier-b.tier;});
  mgSecimAc('Lig', [{ v:'', ad:'Tüm takımlar', ikon:_MG_IKON.kalkan }].concat(lgs.map(function(lg){
    return { v:String(lg.tier), ad:lg.name||_arTierName(_arArcCC,lg.tier), ikon:_arKalkan(lg.tier,24) };
  })), String(_arArcTier), arArcTier);
}
function _arArcFilters(){
  var tum=(_arArcCC==='__all');
  var ulke = tum ? _MG_IKON.dunya+'<b>Tüm Ülkeler</b>' : '<span class="bay">'+_arFlag(_arArcCC)+'</span><b>'+_arEsc(_arCName(_arArcCC))+'</b>';
  var lig = (_arArcTier==='') ? '<b>Tüm takımlar</b>' : _arKalkan(Number(_arArcTier),16)+'<b>'+_arEsc(_arTierName(_arArcCC, Number(_arArcTier)))+'</b>';
  return '<div class="ar-filtre">'
    + '<button type="button" class="mg-cip" onclick="arArcUlkeSec()"><small>Ülke</small><span>'+ulke+'</span></button>'
    + '<button type="button" class="mg-cip'+(tum?' pasif':'')+'" onclick="arArcLigSec()"><small>Lig</small><span>'+lig+'</span></button></div>';
}

async function _arRenderArsiv(gen){
  var head=_arArcFilters();
  try{
    var finals = await _arFetchAllFinals();
    var cur=_arCurSeason();
    var bySeason={};
    finals.forEach(function(m){
      var hs=+m.home_score, as=+m.away_score, w=null;
      if(hs>as) w=m.home_team; else if(as>hs) w=m.away_team;
      else if(Array.isArray(m._pens) && m._pens.length===2) w=(m._pens[0]>m._pens[1])?m.home_team:m.away_team;
      if(!bySeason[m.season]) bySeason[m.season]={};
      if(w) bySeason[m.season][m.tournament_key]=w;
    });
    // trophies kaynaklı şampiyonlarla tamamla (beraberlik/penaltı finalleri)
    try{
      var champMap = await _arCupChampsFromTrophies();
      Object.keys(champMap).forEach(function(sk){
        if(!bySeason[sk]) bySeason[sk]={};
        Object.keys(champMap[sk]).forEach(function(tk){
          if(!bySeason[sk][tk]) bySeason[sk][tk]=champMap[sk][tk].name;
        });
      });
    }catch(e){}
    var h=head;

    // ── Turnuva şampiyonları (tüm sezonlar, en yeni başta) ──
    var KISA={champ:'CHM', elite:'ELI', conv:'CON', enc:'EURO CUP'};
    var sz='', ESKI=cur-3;   // 675 — son 3 sezon görünür; daha eskiler "Daha eski sezonlar" ile açılır
    for(var sN=cur; sN>=1; sN--){
      if(sN===ESKI) sz+='<div class="ar-full'+(_arSeason<=ESKI?' on':'')+'" id="arEskiSz">';
      var b=bySeason[sN]||{};
      var any=b.champ||b.elite||b.conv||b.enc;
      sz+='<div class="ar-sz'+(sN===_arSeason?' on':'')+'"><div class="ar-sz-b"><span>SEZON '+sN+'</span>'+(sN===cur?'<i class="ar-nokta"></i>':'')+'</div>';
      if(!any){
        sz+='<div class="ar-sz-bos'+(sN===cur?' canli':'')+'">'+(sN===cur?'Devam ediyor':'—')+'</div>';
      } else {
        sz+='<div class="ar-sz-g">';
        ['champ','elite','conv','enc'].forEach(function(k){
          var w=b[k], isNat=(k==='enc');
          var wcc = w ? (isNat?_arNatCC(w):_arGuessCC(w)) : '';
          var click = (w && wcc) ? (isNat ? ' onclick="ntViewAsGuest(\''+_arJs(wcc)+'\')"' : ' onclick="viewTeam(\''+_arJs(wcc)+'\',\''+_arJs(w)+'\')"') : '';
          sz+='<div class="ar-szh ar-t-'+k+(w?'':' bos')+'"'+click+'>'+_arKupaRes(k)+'<span class="tx"><small>'+KISA[k]+'</small>'
            + (w ? '<b>'+(isNat?'<span class="bay">'+_arFlag(wcc)+'</span>':_arBadge(wcc,w,'ar-mini'))+'<span>'+_arEsc(w)+'</span></b>' : '<b>—</b>')
            + '</span></div>';
        });
        sz+='</div>';
      }
      sz+='</div>';
    }
    if(ESKI>=1){
      var _ea=(_arSeason<=ESKI);
      sz+='</div><button type="button" class="ar-more" onclick="arAcKapa(\'arEskiSz\',this,\'DAHA ESKİ SEZONLAR ▾\')">'+(_ea?'GİZLE ▴':'DAHA ESKİ SEZONLAR ▾')+'</button>';
    }
    h+=_arKart(_arIk('arsiv'), 'Turnuva Şampiyonları', 'tüm sezonlar · tüm turnuvalar', sz, 'ar-szk ar-vitrin');

    // 🆕 671 — Tüm zamanlar · En Çok Kupa (kulüpler, ülke filtresine uyar)
    h+=_arEnCokKupa(await _arFetchTrophies(), bySeason);

    // ── Kupa kazananlar (SEÇİLİ SEZON + ülke + kazanıldığı lig) ──
    var trs = await _arFetchTrophies();
    var entries=[];   // {cc, nm, type, tierIdx}
    trs.forEach(function(r){
      (Array.isArray(r.data)?r.data:[]).forEach(function(t){
        if(!t || t.season !== _arSeason) return;
        if(t.type==='enc') return;   // milli takımlar bu listede yok (kulüpler listesi)
        entries.push({ cc:r.country_code, nm:r.team_name, type:t.type||'league', tierIdx:(t.tierIdx!=null?t.tierIdx:null) });
      });
    });
    // finallerden gelen kupa şampiyonlarını da ekle (trophies'te eksikse)
    var bs = bySeason[_arSeason] || {};
    ['champ','elite','conv'].forEach(function(ck){
      if(!bs[ck]) return;
      var exists = entries.some(function(e){ return e.type===ck && e.nm===bs[ck]; });
      if(exists) return;
      entries.push({ cc:_arGuessCC(bs[ck]), nm:bs[ck], type:ck, tierIdx:null });
    });

    var filt = entries.slice();
    if(_arArcCC && _arArcCC!=='__all') filt = filt.filter(function(e){ return e.cc===_arArcCC; });
    if(_arArcTier!=='') filt = filt.filter(function(e){ return e.type==='league' && String(e.tierIdx)===String(_arArcTier); });

    var gmap={};
    filt.forEach(function(e){
      var k=e.cc+'|'+e.nm;
      if(!gmap[k]) gmap[k]={cc:e.cc, nm:e.nm, list:[]};
      gmap[k].list.push(e);
    });
    // Kupa önem sırası: CHM(0) > ELI(1) > CON(2) > Milli(3) > Süper Lig(4) > 1.Lig(5) ...
    function _trophyRank(e){
      if(e.type==='champ') return 0;
      if(e.type==='elite') return 1;
      if(e.type==='conv')  return 2;
      if(e.type==='enc')   return 3;
      var ti = (e.tierIdx!=null) ? Number(e.tierIdx) : 99;
      return 3 + Math.max(1, ti);
    }
    var lead=Object.keys(gmap).map(function(k){
      var g=gmap[k];
      g.rank = Math.min.apply(null, g.list.map(_trophyRank));
      g.list.sort(function(a,b){ return _trophyRank(a)-_trophyRank(b); });
      return g;
    }).sort(function(a,b){
      if(a.rank!==b.rank) return a.rank-b.rank;
      return a.nm.localeCompare(b.nm,'tr');
    }).slice(0,20);

    var scope = (_arArcCC==='__all') ? 'Tüm ülkeler' : _arCName(_arArcCC);
    if(_arArcTier!=='') scope += ' · '+_arTierName(_arArcCC, Number(_arArcTier));
    var kk='';
    if(!lead.length) kk='<div class="ar-empty">Bu filtrede Sezon '+_arSeason+' kupası yok.</div>';
    lead.forEach(function(x,i){
      var chips='';
      x.list.forEach(function(e){
        if(e.type==='league') chips+='<span class="ar-chip">'+_arKalkan(e.tierIdx,14)+'<span>'+_arEsc(_arTierName(e.cc, e.tierIdx))+'</span></span>';
        else {
          var cd=_AR_CUPS.filter(function(c){return c.k===e.type;})[0];
          chips+='<span class="ar-chip blue">'+_arCupLogo(e.type,13)+'<span>'+_arEsc(cd?cd.n.split(' ')[0]:e.type)+'</span></span>';
        }
      });
      var click = x.cc ? ' onclick="viewTeam(\''+_arJs(x.cc)+'\',\''+_arJs(x.nm)+'\')"' : '';
      var _n = x.list.length;
      var _tag = (_n>=4) ? '<span class="ar-dbl t3">'+_n+'’LÜ KUPA</span>'
               : (_n===3) ? '<span class="ar-dbl t3">ÜÇLEME</span>'
               : (_n===2) ? '<span class="ar-dbl">ÇİFTE KUPA</span>'
               : '<span class="ct">'+_arIk('kupa')+'<b>1</b></span>';
      kk+='<div class="ar-lead'+(_n>=2?' multi':'')+'"'+click+'>'
        + '<span class="rk'+(i===0?' g1':(i===1?' g2':(i===2?' g3':'')))+'">'+(i+1)+'</span>'
        + _arBadge(x.cc,x.nm,'ar-crest')
        + '<span class="nm"><b><span>'+_arEsc(x.nm)+'</span>'+(x.cc?'<span class="bay">'+_arFlag(x.cc)+'</span>':'')+'</b>'
        +   '<span class="ar-cps">'+chips+'</span></span>'
        + _tag + '</div>';
    });
    h+=_arKart(_arIk('tac'), 'Kupa Kazananlar', _arEsc(scope)+' · Sezon '+_arSeason+' · '+filt.length+' kupa', '<div class="ar-cb">'+kk+'</div>');

    // ── Rekorlar (ülke + lig filtresine göre) ──
    var rk='';
    if(_arArcCC==='__all'){
      rk='<div class="ar-empty">'+_MG_IKON.dunya+'<span>Rekorlar için yukarıdan bir ülke seç.</span></div>';
    } else {
      var lg = await _arFetchLeague(_arSeason, _arArcCC);
      var allT=[];
      Object.keys(lg).forEach(function(t){
        if(_arArcTier!=='' && String(t)!==String(_arArcTier)) return;
        lg[t].forEach(function(x){ allT.push(x); });
      });
      if(allT.length){
        var top=allT.slice().sort(function(a,b){return b.p-a.p;})[0];
        var sc=allT.slice().sort(function(a,b){return b.gf-a.gf;})[0];
        var df=allT.slice().sort(function(a,b){return a.ga-b.ga;})[0];
        var gsum=allT.reduce(function(a,x){return a+x.gf;},0);
        var rec=function(ik, k, x, v){
          return '<div class="ar-rec"><span class="ic">'+_arIk(ik)+'</span><span class="k">'+k+'</span><span class="v">'
            + (x ? '<span class="tk" onclick="viewTeam(\''+_arJs(_arArcCC)+'\',\''+_arJs(x.name)+'\')">'+_arBadge(_arArcCC,x.name,'ar-mini')+'<span>'+_arEsc(x.name)+'</span></span>' : '')
            + '<b>'+v+'</b></span></div>';
        };
        rk=rec('tac','En yüksek puan',top,top.p)+rec('top','En çok gol atan',sc,sc.gf)+rec('kalkan','En iyi savunma',df,df.ga)
          + rec('top','Toplam gol',null,gsum)+rec('lig','Takım sayısı',null,allT.length);
      } else {
        rk='<div class="ar-empty">Bu sezon için veri yok.</div>';
      }
    }
    h+=_arKart(_arIk('simsek'), 'Rekorlar', _arEsc(scope)+' · Sezon '+_arSeason, '<div class="ar-cb">'+rk+'</div>');
    _arYaz(gen, h);
  }catch(e){
    console.warn('[arşiv] arşiv hata:',e);
    _arYaz(gen, head+_arBos(_arIk('bilgi'), 'Veri yüklenemedi.'));
  }
}

function hbNav(name){
  // Eski bottomnav'daki ilgili nav-btn'i bul (mevcut JS uyumu için)
  let btn = null;
  try {
    document.querySelectorAll('#bottomnav .nav-btn').forEach(b=>{
      const oc = b.getAttribute('onclick') || '';
      if (oc.includes("showPage('" + name + "'")) btn = b;
    });
  } catch(e) {}
  // showPage'i çağır (btn varsa onun aktif state'ini de senkronize eder)
  try { showPage(name, btn); } catch(e) { console.warn('hbNav showPage error:', e); }
  // Drawer'ı kapat
  hbCloseDrawer();
}

// showPage çağrıldığında drawer item'larının aktif state'ini senkronize et
(function(){
  if (typeof window.showPage !== 'function') return;
  const _origShowPage = window.showPage;
  window.showPage = function(name, btn){
    const result = _origShowPage.call(this, name, btn);
    // Drawer item active sync
    try {
      document.querySelectorAll('.hb-item[data-page]').forEach(i => i.classList.remove('active'));
      const it = document.querySelector('.hb-item[data-page="' + name + '"]');
      if (it) it.classList.add('active');
    } catch(e) {}
    return result;
  };
})();

// Sayfa yüklendiğinde mevcut aktif sayfayı drawer'da işaretle
setTimeout(function(){
  try {
    const activePage = document.querySelector('.page.active');
    const pageName = activePage ? activePage.id.replace('page-','') : 'home';
    document.querySelectorAll('.hb-item[data-page]').forEach(i => i.classList.remove('active'));
    const it = document.querySelector('.hb-item[data-page="' + pageName + '"]');
    if (it) it.classList.add('active');
  } catch(e) {}
}, 200);

// ESC tuşu ile drawer'ı kapat (klavye kullanımı için)
document.addEventListener('keydown', function(e){
  if (e.key === 'Escape' && document.body.classList.contains('drawer-open')) {
    hbCloseDrawer();
  }
});

